(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("plut-lives-1-e", [{"sp": "HDR", "t": "Βίοι Παράλληλοι"}, {"sp": "HDR", "t": "Θησεύς"}, {"sp": "N", "t": "ὥσπερ ἐν ταῖς γεωγραφίαις, ὦ Σόσσιε Σενεκίων, οἱ ἱστορικοὶ τὰ διαφεύγοντα τὴν γνῶσιν αὐτῶν τοῖς ἐσχάτοις μέρεσι τῶν πινάκων πιεζοῦντες, αἰτίας παραγράφουσιν ὅτι τὰ δ’ ἐπέκεινα θῖνες ἄνυδροι καὶ θηριώδεις ἢ πηλὸς ἀϊδνὴς ἢ σκυθικὸν κρύος ἢ πέλαγος πεπηγός, οὕτως ἐμοὶ περὶ τὴν τῶν βίων τῶν παραλλήλων γραφήν, τὸν ἐφικτὸν εἰκότι λόγῳ καὶ βάσιμον ἱστορίᾳ πραγμάτων ἐχομένῃ χρόνον διελθόντι, περὶ τῶν ἀνωτέρω καλῶς εἶχεν εἰπεῖν· τὰ δ’ ἐπέκεινα τερατώδη καὶ τραγικὰ ποιηταὶ καὶ μυθογράφοι νέμονται, καὶ οὐκέτ’ ἔχει πίστιν οὐδὲ σαφήνειαν. ἐπεὶ δὲ τὸν περὶ Λυκούργου τοῦ νομοθέτου καὶ Νομᾶ τοῦ βασιλέως λόγον ἐκδόντες, ἐδοκοῦμεν οὐκ ἂν ἀλόγως τῷ Ῥωμύλῳ προσαναβῆναι, πλησίον τῶν χρόνων αὐτοῦ τῇ ἱστορίᾳ γεγονότες, σκοποῦντι δέ μοι", "st": "Thes. 1.1"}, {"sp": "N", "t": "τοιῷδε φωτί (κατ’ Αἰσχύλον) τίς ξυμβήσεται;", "st": "Thes. 1.1b"}, {"sp": "N", "t": "τίν’ ἀντιτάξω τῷδε; τίς φερέγγυος;", "st": "Thes. 1.1c"}, {"sp": "N", "t": "ἐφαίνετο τὸν τῶν καλῶν καὶ ἀοιδίμων οἰκιστὴν Ἀθηνῶν ἀντιστῆσαι καὶ παραβαλεῖν τῷ πατρὶ τῆς ἀνικήτου καὶ μεγαλοδόξου Ῥώμης, εἴη μὲν οὖν ἡμῖν ἐκκαθαιρόμενον λόγῳ τὸ μυθῶδες ὑπακοῦσαι καὶ λαβεῖν ἱστορίας ὄψιν, ὅπου δ’ ἂν αὐθαδῶς τοῦ πιθανοῦ περιφρονῇ καὶ μὴ δέχηται τὴν πρὸς τὸ εἰκὸς μῖξιν, εὐγνωμόνων ἀκροατῶν δεησόμεθα καὶ πρᾴως τὴν ἀρχαιολογίαν προσδεχομένων.", "st": "Thes. 1.3"}, {"sp": "N", "t": "ἐδόκει δ’ οὖν ὁ Θησεὺς τῷ Ῥωμύλῳ κατὰ πολλὰς ἐναρμόττειν ὁμοιότητας· ἄμφω μὲν γὰρ ἀνεγγύω καὶ σκοτίω γενόμενοι δόξαν ἔσχον ἐκ θεῶν γεγονέναι,", "st": "Thes. 2.1"}, {"sp": "N", "t": "ἄμφω δ’ αἰχμητά, τό γε δὴ καὶ ἴδμεν ἅπαντες,", "st": "Thes. 2.1b"}, {"sp": "N", "t": "καὶ μετὰ τοῦ δυνατοῦ τὸ συνετὸν ἔχοντες. πόλεων δὲ τῶν ἐπιφανεστάτων ὁ μὲν ἔκτισε τὴν Ῥώμην, ὁ δὲ συνῴκισε τὰς Ἀθήνας· ἁρπαγὴ δὲ γυναικῶν ἑκατέρῳ πρόσεστιν. οὐδέτερος δὲ δυστυχίαν περὶ τὰ οἰκεῖα καὶ νέμεσιν ἐγγενῆ διέφυγεν, ἀλλὰ καὶ τελευτῶντες ἀμφότεροι λέγονται τοῖς ἑαυτῶν προσκροῦσαι πολίταις, εἴ τι τῶν ἥκιστα τραγικῶς εἰρῆσθαι δοκούντων ὄφελός ἐστι πρὸς ἀλήθειαν.", "st": "Thes. 2.2"}, {"sp": "N", "t": "Θησέως τὸ μὲν πατρῷον γένος εἰς Ἐρεχθέα καὶ τοὺς πρώτους αὐτόχθονας ἀνήκει, τῷ δὲ μητρῴῳ Πελοπίδης ἦν. Πέλοψ γὰρ οὐ χρημάτων πλήθει μᾶλλον ἢ παίδων μέγιστον ἴσχυσε τῶν ἐν Πελοποννήσῳ βασιλέων, πολλὰς μὲν ἐκδόμενος θυγατέρας τοῖς ἀρίστοις, πολλοὺς δὲ ταῖς πόλεσιν υἱοὺς ἐγκατασπείρας ἄρχοντας· ὧν εἷς γενόμενος Πιτθεύς, ὁ Θησέως πάππος, πόλιν μὲν οὐ μεγάλην τὴν Τροιζηνίων ᾤκισε, δόξαν δὲ μάλιστα πάντων ὡς ἀνὴρ λόγιος ἐν τοῖς τότε καὶ σοφώτατος ἔσχεν. ἦν δὲ τῆς σοφίας ἐκείνης τοιαύτη τις, ὡς ἔοικεν, ἰδέα καὶ δύναμις, οἵᾳ χρησάμενος Ἡσίοδος εὐδοκίμει μάλιστα περὶ τὰς ἐν τοῖς Ἔργοις γνωμολογίας. καὶ μίαν γε τούτων ἐκείνην λέγουσι Πιτθέως εἶναι,", "st": "Thes. 3.1"}, {"sp": "N", "t": "μισθὸς δ’ ἀνδρὶ φίλῳ εἰρημένος ἄρκιος ἔστω.", "st": "Thes. 3.1b"}, {"sp": "N", "t": "τοῦτο μὲν οὖν καὶ Ἀριστοτέλης ὁ φιλόσοφος εἴρηκεν, ὁ δ’ Εὐριπίδης, τὸν Ἱππόλυτον ἁγνοῦ Πιτθέως παίδευμα προσειπών, ἐμφαίνει τὴν περὶ τὸν Πιτθέα δόξαν.", "st": "Thes. 3.1c"}, {"sp": "N", "t": "Αἰγεῖ δὲ παίδων δεομένῳ τὴν Πυθίαν ἀνελεῖν λέγουσι τὸν θρυλούμενον χρησμόν, διακελευομένην μηδεμιᾷ γυναικὶ συγγενέσθαι πρὶν ἐλθεῖν εἰς Ἀθήνας, οὐ πάνυ δὲ τοῦτο φράζειν εὐδήλως δοκοῦσαν· ὅθεν εἰς Τροιζῆτα παρελθὼν ἀνεκοινοῦτο Πιτθεῖ τὴν τοῦ θεοῦ φωνὴν οὕτως ἔχουσαν·", "st": "Thes. 3.3"}, {"sp": "N", "t": "ἀσκοῦ τὸν προὔχοντα πόδα, μέγα φέρτατε λαῶν,<br>μὴ λύσῃς πρὶν δῆμον Ἀθηνέων εἰσαφικέσθαι·", "st": "Thes. 3.3b"}, {"sp": "N", "t": "ἃ δῆλον ὅτι νοήσας ὁ Πιτθεύς, ἔπεισεν αὐτὸν ἢ διηπάτησε τῇ Αἴθρᾳ συγγενέσθαι. συνελθὼν δὲ καὶ γνοὺς ἐκεῖνος ὅτι τῇ Πιτθέως θυγατρὶ συγγέγονε, καὶ κύειν αὐτὴν ὑπονοήσας, ἀπέλιπε ξίφος καὶ πέδιλα κρύψας ὑπὸ πέτραν μεγάλην, ἐντὸς ἔχουσαν κοιλότητα συμμέτρως ἐμπεριλαμβάνουσαν τὰ κείμενα. φράσας δὲ πρὸς μόνην ἐκείνην, καὶ διακελευσάμενος, ἂν υἱὸς ἐξ αὐτοῦ γένηται, καὶ λαβὼν ἀνδρὸς ἡλικίαν δυνατὸς ᾖ τὴν πέτραν ἀναστῆσαι καὶ ὑφελεῖν τὰ καταλειφθέντα, πέμπειν πρὸς αὐτὸν ἔχοντα ταῦτα μηδενὸς εἰδότος, ἀλλ’ ὡς ἔνεστι μάλιστα λανθάνοντα πάντας (ἰσχυρῶς γὰρ ἐδεδοίκει τοὺς Παλλαντίδας, ἐπιβουλεύοντας αὐτῷ καὶ διὰ τὴν ἀπαιδίαν καταφρονοῦντας· ἦσαν δὲ πεντήκοντα παῖδες ἐκ Πάλλαντος γεγονότες), ἀπῄει.", "st": "Thes. 3.4"}, {"sp": "N", "t": "τεκούσης δὲ τῆς Αἴθρας υἱόν, οἱ μὲν εὐθὺς ὀνομασθῆναι Θησέα λέγουσι διὰ τὴν τῶν γνωρισμάτων θέσιν, οἱ δὲ ὕστερον Ἀθήνησι παῖδα θεμένου τοῦ Αἰγέως αὐτόν. τρεφόμενον δὲ ὑπὸ τοῦ Πιτθέως ἐπιστάτην ἔχειν καὶ παιδαγωγὸν ὄνομα Κοννίδαν, ᾧ μέχρι νῦν Ἀθηναῖοι μιᾷ πρότερον ἡμέρᾳ τῶν Θησείων κριὸν ἐναγίζουσι, μεμνημένοι καὶ τιμῶντες πολὺ δικαιότερον ἢ Σιλανίωνα τιμῶσι καὶ Παρράσιον, εἰκόνων Θησέως γραφεῖς καὶ πλάστας γενομένους.", "st": "Thes. 4.1"}, {"sp": "N", "t": "ἔθους δὲ ὄντος ἔτι τότε τοὺς μεταβαίνοντας ἐκ παίδων ἐλθόντας εἰς Δελφοὺς ἀπάρχεσθαι τῷ θεῷ τῆς κόμης, ἦλθε μὲν εἰς Δελφοὺς ὁ Θησεύς, καὶ τόπον ἀπ’ αὐτοῦ τὴν Θησείαν ἔτι νῦν ὀνομάζεσθαι λέγουσιν, ἐκείρατο δὲ τῆς κεφαλῆς τὰ πρόσθεν μόνον, ὥσπερ Ὅμηρος ἔφη τοὺς Ἄβαντας· καὶ τοῦτο τῆς κουρᾶς τὸ γένος Θησηῒς ὠνομάσθη δι’ ἐκεῖνον.", "st": "Thes. 5.1"}, {"sp": "N", "t": "οἱ δὲ Ἄβαντες ἐκείραντο πρῶτοι τὸν τρόπον τοῦτον οὐχ ὑπ’ Ἀράβων διδαχθέντες, ὡς ἔνιοι νομίζουσιν, οὐδὲ Μυσοὺς ζηλώσαντες, ἀλλ’ ὄντες πολεμικοὶ καὶ ἀγχέμαχοι, καὶ μάλιστα δὴ πάντων εἰς χεῖρας ὠθεῖσθαι τοῖς ἐναντίοις μεμαθηκότες, ὡς μαρτυρεῖ καὶ Ἀρχίλοχος ἐν τούτοις·", "st": "Thes. 5.2"}, {"sp": "N", "t": "οὔ τοι πόλλ’ ἐπὶ τόξα τανύσσεται οὐδὲ θαμειαὶ<br>σφενδόναι, εὖτ’ ἂν δὴ μῶλον Ἄρης συνάγῃ<br>ἐν πεδίῳ, ξιφέων δὲ πολύστονον ἔσσεται ἔργον· ταύτης γὰρ κεῖνοι δαίμονές εἰσι μάχης<br>δεσπόται Εὐβοίας δουρικλυτοί.", "st": "Thes. 5.3"}, {"sp": "N", "t": "ὅπως οὖν μὴ παρέχοιεν ἐκ τῶν τριχῶν ἀντίληψιν τοῖς πολεμίοις ἀπεκείραντο. τοῦτο δὲ ἀμέλει καὶ Ἀλέξανδρον τὸν Μακεδόνα ἐννοήσαντά φασι προστάξαι τοῖς στρατηγοῖς ξυρεῖν τὰ γένεια τῶν Μακεδόνων, ὡς λαβὴν ταύτην ἐν ταῖς μάχαις οὖσαν προχειροτάτην.", "st": "Thes. 5.4"}, {"sp": "N", "t": "τὸν μὲν οὖν ἄλλον χρόνον ἔκρυπτεν Αἴθρα τὴν ἀληθινὴν τοῦ Θησέως γένεσιν· ἦν δὲ λόγος ὑπὸ τοῦ Πιτθέως διαδοθεὶς ὡς ἐκ Ποσειδῶνος τεκνωθείη. Ποσειδῶνα γὰρ Τροιζήνιοι σέβονται διαφερόντως, καὶ θεὸς οὗτός ἐστιν αὐτοῖς πολιοῦχος, ᾧ καὶ καρπῶν ἀπάρχονται καὶ τρίαιναν ἐπίσημον ἔχουσι τοῦ νομίσματος. ἐπεὶ δὲ μειράκιον ὤν, ἅμα τῇ τοῦ σώματος ῥώμῃ διέφαινεν ἀλκὴν καὶ φρόνημα μετὰ νοῦ καὶ συνέσεως βέβαιον, οὕτως αὐτὸν ἡ Αἴθρα πρὸς τὴν πέτραν προσαγαγοῦσα, καὶ φράσασα περὶ τῆς γενέσεως τἀληθές, ἐκέλευσεν ὑφελεῖν τὰ πατρῷα σύμβολα καὶ πλεῖν εἰς Ἀθήνας. ὁ δὲ τὴν μὲν πέτραν ὑπέδυ καὶ ῥᾳδίως ἀνέωσε, πλεῖν δὲ ἀπέγνω, καίπερ οὔσης ἀσφαλείας καὶ δεομένων τοῦ τε πάππου καὶ τῆς μητρός. χαλεπὸν γὰρ ἦν πεζῇ πορεύεσθαι τὴν εἰς Ἀθήνας ὁδόν, οὐδὲν μέρος καθαρὸν οὐδὲ ἀκίνδυνον ὑπὸ λῃστῶν καὶ κακούργων ἔχουσαν.", "st": "Thes. 6.1"}, {"sp": "N", "t": "ὁ γὰρ δὴ χρόνος ἐκεῖνος ἤνεγκεν ἀνθρώπους χειρῶν μὲν ἔργοις καὶ ποδῶν τάχεσι καὶ σωμάτων ῥώμαις, ὡς ἔοικεν, ὑπερφυεῖς καὶ ἀκαμάτους, πρὸς οὐδὲν δὲ τῇ φύσει χρωμένους ἐπιεικὲς οὐδὲ ὠφέλιμον, ἀλλ’ ὕβρει τε χαίροντας ὑπερηφάνῳ, καὶ ἀπολαύοντας τῆς δυνάμεως ὠμότητι καὶ πικρίᾳ, καὶ τῷ κρατεῖν τε καὶ βιάζεσθαι καὶ διαφθείρειν τὸ παραπῖπτον, αἰδῶ δὲ καὶ δικαιοσύνην καὶ τὸ ἴσον καὶ τὸ φιλάνθρωπον, ὡς ἀτολμίᾳ τοῦ ἀδικεῖν καὶ φόβῳ τοῦ ἀδικεῖσθαι τοὺς πολλοὺς ἐπαινοῦντας, οὐδὲν οἰομένους προσήκειν τοῖς πλέον ἔχειν δυναμένοις. τούτων Ἡρακλῆς τοὺς μὲν ἐξέκοπτε καὶ ἀνῄρει περιϊών, οἱ δὲ λανθάνοντες ἐκείνου παριόντος ἔπτησσον καὶ ἀνεδύοντο καὶ παρημελοῦντο ταπεινὰ πράττοντες. ἐπεὶ δὲ Ἡρακλῆς ἐχρήσατο συμφορᾷ, καὶ κτείνας Ἴφιτον εἰς Λυδίαν ἀπῆρε καὶ συχνὸν ἐκεῖ χρόνον ἐδούλευε παρ’ Ὀμφάλῃ, δίκην τοῦ φόνου ταύτην ἐπιθεὶς αὑτῷ, τότε τὰ μὲν Λυδῶν πράγματα πολλὴν ἔσχεν εἰρήνην καὶ ἄδειαν· ἐν δὲ τοῖς περὶ τὴν Ἑλλάδα τόποις αὖθις ἐξήνθησαν αἱ κακίαι καὶ ἀνερράγησαν, οὐδενὸς πιεζοῦντος οὐδὲ κατείργοντος.", "st": "Thes. 6.4"}, {"sp": "N", "t": "ἦν οὖν ὀλέθριος ἡ πορεία τοῖς Ἀθήναζε πεζῇ βαδίζουσιν ἐκ Πελοποννήσου· καὶ τῶν κακούργων ἕκαστον ἐξηγούμενος Πιτθεὺς ὁποῖος εἴη καὶ ὁποῖα δρῴη περὶ τοὺς ξένους, ἔπειθε τὸν Θησέα κομίζεσθαι διὰ θαλάττης. τὸν δὲ πάλαι μέν, ὡς ἔοικε, λεληθότως διέκαιεν ἡ δόξα τῆς Ἡρακλέους ἀρετῆς, καὶ πλεῖστον ἐκείνου λόγον εἶχε, καὶ προθυμότατος ἀκροατὴς ἐγίνετο τῶν διηγουμένων ἐκεῖνον οἷος εἴη, μάλιστα δὲ τῶν αὐτὸν ἑωρακότων καὶ πράττοντι καὶ λέγοντι προστετυχηκότων· τότε δὲ παντάπασιν ἦν φανερὸς πεπονθὼς ὅπερ ὕστερον χρόνοις πολλοῖς Θεμιστοκλῆς ἔπαθε, καὶ εἶπεν ὡς καθεύδειν αὐτὸν οὐκ ἐῴη τὸ Μιλτιάδου τρόπαιον· οὕτως ἐκείνῳ τοῦ Ἡρακλέους θαυμάζοντι τὴν ἀρετήν, καὶ νύκτωρ ὄνειρος ἦσαν αἱ πράξεις, καὶ μεθ’ ἡμέραν ἐξῆγεν αὐτὸν ὁ ζῆλος καὶ ἀνηρέθιζε ταὐτὰ πράττειν διανοούμενον.", "st": "Thes. 6.6"}, {"sp": "N", "t": "ἐτύγχανον δὲ καὶ γένους κοινωνοῦντες ἐξ ἀνεψιῶν ὄντες. Αἴθρα μὲν γὰρ ἦν Πιτθέως θυγάτηρ, Ἀλκμήνη δὲ Λυσιδίκης, Λυσιδίκη δὲ καὶ Πιτθεὺς ἀδελφοὶ γεγονότες ἐξ Ἱπποδαμείας καὶ Πέλοπος. δεινὸν οὖν ἐποιεῖτο καὶ οὐκ ἀνεκτὸν ἐκεῖνον μὲν ἐπὶ τοὺς πανταχοῦ πονηροὺς βαδίζοντα καθαίρειν γῆν καὶ θάλατταν, αὐτὸν δὲ τοὺς ἐμποδὼν ἄθλους ἀποδιδράσκειν, τὸν μὲν λόγῳ καὶ δόξῃ πατέρα καταισχύνων διὰ θαλάττης φυγῇ κομιζόμενος, τῷ δὲ ὄντι προσφέρων γνωρίσματα πέδιλα καὶ ξίφος ἀναίμακτον, οὐκ ἔργοις εὐθὺς ἀγαθοῖς καὶ πράξεσι παρέχων ἐμφανῆ χαρακτῆρα τῆς εὐγενείας. τοιούτῳ φρονήματι καὶ τοιούτοις λογισμοῖς ἐξώρμησεν, ὡς ἀδικήσων μὲν οὐδένα, τοὺς δὲ ὑπάρχοντας βίας ἀμυνούμενος.", "st": "Thes. 7.1"}, {"sp": "N", "t": "καὶ πρῶτον μὲν ἐν τῇ Ἐπιδαυρίᾳ Περιφήτην, ὅπλῳ χρώμενον κορύνῃ καὶ διὰ τοῦτο Κορυνήτην ἐπικαλούμενον, ἁπτόμενον αὐτοῦ καὶ κωλύοντα προάγειν συμβαλὼν ἀπέκτεινεν· ἡσθεὶς δὲ τῇ κορύνῃ λαβὼν ὅπλον ἐποιήσατο καὶ διετέλει χρώμενος, ὥσπερ ὁ Ἡρακλῆς τῷ δέρματι τοῦ λέοντος. ἐκείνῳ μὲν οὖν ἐπίδειξις ἦν φορούμενον ἡλίκου τὸ μέγεθος θηρίου κρατήσειεν, οὗτος δὲ τὴν κορύνην ἐπεδείκνυεν ἡττημένην μὲν ὑπ’ αὐτοῦ, μετ’ αὐτοῦ δὲ ἀήττητον οὖσαν.", "st": "Thes. 8.1"}, {"sp": "N", "t": "ἐν δ’ Ἰσθμῷ Σίνιν τὸν πιτυοκάμπτην ᾧ τρόπῳ πολλοὺς ἀνῄρει, τούτῳ διέφθειρεν αὐτός, οὐ μεμελετηκὼς οὐδ’ εἰθισμένος, ἐπιδείξας δὲ τὴν ἀρετὴν ὅτι καί τέχνης περίεστι καὶ μελέτης ἁπάσης. ἦν δὲ τῷ Σίνιδι καλλίστη καὶ μεγίστη θυγάτηρ, ὄνομα Περιγούνη. ταύτην τοῦ πατρὸς ἀνῃρημένου φυγοῦσαν ἐζήτει περιϊὼν ὁ Θησεύς· ἡ δ’ εἰς τόπον ἀπελθοῦσα λόχμην ἔχοντα πολλὴν στοιβήν τε πλείστην καὶ ἀσφάραγον, ἀκάκως πάνυ καὶ παιδικῶς ὥσπερ αἰσθανομένων δεομένη προσεύχετο μεθ’ ὅρκων, ἂν σώσωσιν αὐτὴν καὶ ἀποκρύψωσι, μηδέποτε λυμανεῖσθαι μηδὲ καύσειν. ἀνακαλουμένου δὲ τοῦ Θησέως καὶ πίστιν διδόντος ὡς ἐπιμελήσεται καλῶς αὐτῆς καὶ οὐδὲν ἀδικήσει, προῆλθε· καὶ τῷ μὲν Θησεῖ συγγενομένη Μελάνιππον ἔτεκε, Δηϊονεῖ δὲ τῷ Εὐρύτου τοῦ Οἰχαλιέως ὕστερον συνῴκησε, Θησέως δόντος. ἐκ δὲ Μελανίππου τοῦ Θησέως γενόμενος Ἴωξος Ὀρνύτῳ τῆς εἰς Καρίαν ἀποικίας μετέσχεν· ὅθεν Ἰωξίδαις καὶ Ἰωξίσι πάτριον κατέστη μήτε ἄκανθαν ἀσφαράγου μήτε στοιβὴν καίειν, ἀλλὰ σέβεσθαι καὶ τιμᾶν.", "st": "Thes. 8.2"}, {"sp": "N", "t": "ἡ δὲ Κρομμυωνία σῦς, ἣν Φαιὰν προσωνόμαζον, οὐ φαῦλον ἦν θηρίον, ἀλλὰ μάχιμον καὶ χαλεπὸν κρατηθῆναι. ταύτην ὁδοῦ πάρεργον, ὡς μὴ δοκοίη πάντα πρὸς ἀνάγκην πονεῖν, ὑποστὰς ἀνεῖλε, καὶ ἅμα τῶν μὲν ἀνθρώπων τοῖς πονηροῖς ἀμυνόμενον οἰόμενος δεῖν τὸν ἀγαθὸν προσφέρεσθαι, τῶν δὲ θηρίων καὶ προεπιχειροῦντα τοῖς γενναίοις μάχεσθαι καὶ διακινδυνεύειν. ἔνιοι δέ φασι τὴν Φαιὰν λῃστρίδα γενέσθαι γυναῖκα φονικὴν καὶ ἀκόλαστον, αὐτόθι κατοικοῦσαν ἐν Κρομμυῶνι, σῦν δὲ ἐπονομασθεῖσαν διὰ τὸ ἦθος καὶ τὸν βίον εἶτα ὑπὸ Θησέως ἀποθανεῖν.", "st": "Thes. 9.1"}, {"sp": "N", "t": "Σκείρωνα δὲ πρὸ τῆς Μεγαρικῆς ἀνεῖλε ῥίψας κατὰ τῶν πετρῶν, ὡς μὲν ὁ πολὺς λόγος λῃστεύοντα τοὺς παριόντας, ὡς δ’ ἔνιοι λέγουσιν ὕβρει καὶ τρυφῇ προτείνοντα τὼ πόδε τοῖς ξένοις καὶ κελεύοντα νίπτειν, εἶτα λακτίζοντα καὶ ἀπωθοῦντα νίπτοντας εἰς τὴν θάλατταν. οἱ δὲ Μεγαρόθεν συγγραφεῖς, ὁμόσε τῇ φήμῃ βαδίζοντες καὶ τῷ πολλῷ χρόνῳ, κατὰ Σιμωνίδην, πολεμοῦντες, οὔτε ὑβριστὴν οὔτε λῃστὴν γεγονέναι τὸν Σκείρωνά φασιν, ἀλλὰ λῃστῶν μὲν κολαστήν, ἀγαθῶν δὲ καὶ δικαίων οἰκεῖον ἀνδρῶν καὶ φίλον. Αἰακόν τε γὰρ Ἑλλήνων ὁσιώτατον νομίζεσθαι, καὶ Κυχρέα τιμὰς θεῶν ἔχειν Ἀθήνησι τὸν Σαλαμίνιον, τὴν δὲ Πηλέως καὶ Τελαμῶνος ἀρετὴν ὑπ’ οὐδενὸς ἀγνοεῖσθαι. Σκείρωνα τοίνυν Κυχρέως μὲν γενέσθαι γαμβρόν, Αἰακοῦ δὲ πενθερόν, Πηλέως δὲ καὶ Τελαμῶνος πάππον, ἐξ Ἐνδηίδος γεγονότων τῆς Σκείρωνος καὶ Χαρικλοῦς θυγατρός. οὔκουν εἰκὸς εἶναι τῷ κακίστῳ τοὺς ἀρίστους εἰς κοινωνίαν γένους ἐλθεῖν, τὰ μέγιστα καὶ τιμιώτατα λαμβάνοντας καὶ διδόντας. ἀλλὰ Θησέα φασὶν οὐχ ὅτε τὸ πρῶτον ἐβάδιζεν εἰς Ἀθήνας, ἀλλ’ ὕστερον Ἐλευσῖνά τε λαβεῖν Μεγαρέων ἐχόντων, παρακρουσάμενον Διοκλέα τὸν ἄρχοντα, καὶ Σκείρωνα ἀποκτεῖναι. ταῦτα μὲν οὖν ἔχει τοιαύτας ἀντιλογίας.", "st": "Thes. 10.1"}, {"sp": "N", "t": "ἐν δὲ Ἐλευσῖνι Κερκύονα τὸν ἐξ Ἀρκαδίας καταπαλαίσας ἀνεῖλε· καὶ μικρὸν προελθὼν Δαμάστην ἐν Ἐρινεῷ τὸν Προκρούστην, ἀναγκάσας αὑτὸν ἀπισοῦν τοῖς κλιντῆρσιν ὥσπερ τοὺς ξένους ἐκεῖνος. ἔπραττε δὲ ταῦτα μιμούμενος τὸν Ἡρακλέα. καὶ γὰρ ἐκεῖνος οἷς ἐπεβουλεύετο τρόποις ἀμυνόμενος τοὺς προεπιχειροῦντας, ἔθυσε τὸν Βούσιριν καὶ κατεπάλαισε τὸν Ἀνταῖον καὶ τὸν Κύκνον κατεμονομάχησε καὶ τὸν Τέρμερον συρρήξας τὴν κεφαλὴν ἀπέκτεινεν. ἀφ’ οὗ δὴ καὶ τὸ Τερμέρειον κακὸν ὀνομασθῆναι λέγουσι· παίων γάρ, ὡς ἔοικε, τῇ κεφαλῇ τοὺς ἐντυγχάνοντας ὁ Τέρμερος ἀπώλλυεν. οὕτω δὴ καὶ Θησεὺς κολάζων τοὺς πονηροὺς ἐπεξῆλθεν, οἷς μὲν ἐβιάζοντο τοὺς ἄλλους, ὑπ’ ἐκείνου καταβιαζομένους, ἐν δὲ τοῖς τρόποις τῆς ἑαυτῶν ἀδικίας τὰ δίκαια πάσχοντας.", "st": "Thes. 11.1"}, {"sp": "N", "t": "προϊόντι δὲ αὐτῷ καὶ γενομένῳ κατὰ τὸν Κηφισόν, ἄνδρες ἐκ τοῦ Φυταλιδῶν γένους ἀπαντήσαντες ἠσπάσαντο πρῶτοι, καὶ δεομένου καθαρθῆναι, τοῖς νενομισμένοις ἁγνίσαντες καὶ μειλίχια θύσαντες εἱστίασαν οἴκοι, μηδενὸς πρότερον αὐτῷ φιλανθρώπου καθ’ ὁδὸν ἐντυχόντος.", "st": "Thes. 12.1"}, {"sp": "N", "t": "ἡμέρᾳ μὲν οὖν ὀγδόῃ λέγεται Κρονίου μηνός, ὃν νῦν Ἑκατομβαιῶνα καλοῦσι, κατελθεῖν. κατελθὼν δὲ εἰς τὴν πόλιν εὗρε τά τε κοινὰ ταραχῆς μεστὰ καὶ διχοφροσύνης, καὶ τὰ περὶ τὸν Αἰγέα καὶ τὸν οἶκον ἰδίᾳ νοσοῦντα. Μήδεια γὰρ ἐκ Κορίνθου φυγοῦσα, φαρμάκοις ὑποσχομένη τῆς ἀτεκνίας ἀπαλλάξειν Αἰγέα, συνῆν αὐτῷ. προαισθομένη δὲ περὶ τοῦ Θησέως αὕτη, τοῦ δὲ Αἰγέως ἀγνοοῦντος, ὄντος δὲ πρεσβυτέρου καὶ φοβουμένου πάντα διὰ τὴν στάσιν, ἔπεισεν αὐτὸν ὡς ξένον ἑστιῶντα φαρμάκοις ἀνελεῖν. ἐλθὼν οὖν ὁ Θησεὺς ἐπὶ τὸ ἄριστον οὐκ ἐδοκίμαζε φράζειν αὑτόν, ὅστις εἴη, πρότερος, ἐκείνῳ δὲ βουλόμενος ἀρχὴν ἀνευρέσεως παρασχεῖν, κρεῶν παρακειμένων σπασάμενος τὴν μάχαιραν, ὡς ταύτῃ τέμνων, ἐδείκνυεν ἐκείνῳ. ταχὺ δὲ καταμαθὼν ὁ Αἰγεύς, τὴν μὲν κύλικα τοῦ φαρμάκου κατέβαλε, τὸν δὲ υἱὸν ἀνακρίνας ἠσπάζετο, καὶ συναγαγὼν τοὺς πολίτας ἐγνώριζεν, ἡδέως δεχομένους διὰ τὴν ἀνδραγαθίαν. λέγεται δὲ τῆς κύλικος πεσούσης ἐκχυθῆναι τὸ φάρμακον ὅπου νῦν ἐν Δελφινίῳ τὸ περίφρακτόν ἐστιν, ἐνταῦθα γὰρ ὁ Αἰγεὺς ᾤκει, καὶ τὸν Ἑρμῆν τὸν πρὸς ἕω τοῦ ἱεροῦ καλοῦσιν ἐπ’ Αἰγέως πύλαις.", "st": "Thes. 12.2"}, {"sp": "N", "t": "οἱ δὲ Παλλαντίδαι πρότερον μὲν ἤλπιζον αὐτοὶ τὴν βασιλείαν καθέξειν Αἰγέως ἀτέκνου τελευτήσαντος· ἐπεὶ δὲ Θησεὺς ἀπεδείχθη διάδοχος, χαλεπῶς φέροντες εἰ βασιλεύει μὲν Αἰγεὺς θετὸς γενόμενος Πανδίονι καὶ μηδὲν Ἐρεχθείδαις προσήκων, βασιλεύσει δ’ ὁ Θησεὺς πάλιν ἔπηλυς ὢν καὶ ξένος, εἰς πόλεμον καθίσταντο. καὶ διελόντες ἑαυτοὺς οἱ μὲν ἐμφανῶς Σφηττόθεν ἐχώρουν ἐπὶ τὸ ἄστυ μετὰ τοῦ πατρός, οἱ δὲ Γαργηττοῖ κρύψαντες ἑαυτοὺς ἐνήδρευον, ὡς διχόθεν ἐπιθησόμενοι τοῖς ὑπεναντίοις. ἦν δὲ κῆρυξ μετ’ αὐτῶν, ἀνὴρ Ἁγνούσιος, ὄνομα Λεώς. οὗτος ἐξήγγειλε τῷ Θησεῖ τὰ βεβουλευμένα τοῖς Παλλαντίδαις. ὁ δὲ ἐξαίφνης ἐπιπεσὼν τοῖς ἐνεδρεύουσι πάντας διέφθειρεν. οἱ δὲ μετὰ τοῦ Πάλλαντος πυθόμενοι διεσπάρησαν. ἐκ τούτου φασὶ τῷ Παλληνέων δήμῳ πρὸς τὸν Ἁγνουσίων ἐπιγαμίαν μὴ εἶναι, μηδὲ κηρύττεσθαι τοὐπιχώριον παρ’ αὐτοῖς ἀκούετε λεῷ· μισοῦσι γὰρ τοὔνομα διὰ τὴν προδοσίαν τοῦ ἀνδρός.", "st": "Thes. 13.1"}, {"sp": "N", "t": "ὁ δὲ Θησεὺς ἐνεργὸς εἶναι βουλόμενος, ἅμα δὲ καὶ δημαγωγῶν, ἐξῆλθεν ἐπὶ τὸν Μαραθώνιον ταῦρον, οὐκ ὀλίγα πράγματα τοῖς οἰκοῦσι τὴν Τετράπολιν παρέχοντα· καὶ χειρωσάμενος ἐπεδείξατο ζῶντα διὰ τοῦ ἄστεος ἐλάσας, εἶτα τῷ Ἀπόλλωνι τῷ Δελφινίῳ κατέθυσεν. ἡ δὲ Ἑκάλη καὶ τὸ περὶ αὐτὴν μυθολόγημα τοῦ ξενισμοῦ καὶ τῆς ὑποδοχῆς ἔοικε μὴ πάσης ἀμοιρεῖν ἀληθείας. ἔθυον γὰρ Ἑκαλήσια οἱ πέριξ δῆμοι συνιόντες Ἑκάλῳ Διΐ, καὶ τὴν Ἑκάλην ἐτίμων, Ἑκαλίνην ὑποκοριζόμενοι διὰ τὸ κἀκείνην νέον ὄντα κομιδῇ τὸν Θησέα ξενίζουσαν ἀσπάσασθαι πρεσβυτικῶς καὶ φιλοφρονεῖσθαι τοιούτοις ὑποκορισμοῖς. ἐπεὶ δὲ εὔξατο μὲν ὑπὲρ αὐτοῦ τῷ Διί, βαδίζοντος ἐπὶ τὴν μάχην, εἰ σῶς παραγένοιτο, θύσειν, ἀπέθανε δὲ πρὶν ἐκεῖνον ἐπανελθεῖν, ἔσχε τὰς εἰρημένας ἀμοιβὰς τῆς φιλοξενίας τοῦ Θησέως κελεύσαντος, ὡς Φιλόχορος ἱστόρηκεν.", "st": "Thes. 14.1"}, {"sp": "N", "t": "ὀλίγῳ δὲ ὕστερον ἧκον ἐκ Κρήτης τὸ τρίτον οἱ τὸν δασμὸν ἀπάξοντες. ὅτι μὲν οὖν Ἀνδρόγεω περὶ τὴν Ἀττικὴν ἀποθανεῖν δόλῳ δόξαντος, ὅ τε Μίνως πολλὰ κακὰ πολεμῶν εἰργάζετο τοὺς ἀνθρώπους καὶ τὸ δαιμόνιον ἔφθειρε τὴν χώραν (ἀφορία τε γὰρ καὶ νόσος ἐνέσκηψε πολλὴ καὶ ἀνέδυσαν οἱ ποταμοί), καὶ τοῦ θεοῦ προστάξαντος ἱλασαμένοις τὸν Μίνω καὶ διαλλαγεῖσι λωφήσειν τὸ μήνιμα καὶ τῶν κακῶν ἔσεσθαι παῦλαν, ἐπικηρυκευσάμενοι καὶ δεηθέντες ἐποιήσαντο συνθήκας ὥστε πέμπειν δι’ ἐννέα ἐτῶν δασμὸν ἠϊθέους ἑπτὰ καὶ παρθένους τοσαύτας, ὁμολογοῦσιν οἱ πλεῖστοι τῶν συγγραφέων· τοὺς δὲ παῖδας εἰς Κρήτην κομιζομένους ὁ μὲν τραγικώτατος μῦθος ἀποφαίνει τὸν Μινώταυρον ἐν τῷ Λαβυρίνθῳ διαφθείρειν, ἢ πλανωμένους αὐτοὺς καὶ τυχεῖν ἐξόδου μὴ δυναμένους ἐκεῖ καταθνήσκειν, τὸν δὲ Μινώταυρον, ὥσπερ Εὐριπίδης φησί,", "st": "Thes. 15.1"}, {"sp": "N", "t": "σύμμικτον εἶδος κἀποφώλιον βρέφος<br>γεγονέναι, καὶ<br>ταύρου μεμῖχθαι καὶ βροτοῦ διπλῇ φύσει.", "st": "Thes. 15.1b"}, {"sp": "N", "t": "φιλόχορος δέ φησιν οὐ ταῦτα συγχωρεῖν Κρῆτας, ἀλλὰ λέγειν ὅτι φρουρὰ μὲν ἦν ὁ Λαβύρινθος, οὐδὲν ἔχων κακὸν ἀλλ’ ἢ τὸ μὴ διαφυγεῖν τοὺς φυλαττομένους, ἀγῶνα δὲ ὁ Μίνως ἐπ’ Ἀνδρόγεῳ γυμνικὸν ἐποίει καὶ τοὺς παῖδας ἆθλα τοῖς νικῶσιν ἐδίδου τέως ἐν τῷ Λαβυρίνθῳ φυλαττομένους· ἐνίκα δὲ τοὺς προτέρους ἀγῶνας ὁ μέγιστον παρ’ αὐτῷ δυνάμενος τότε καὶ στρατηγῶν, ὄνομα Ταῦρος, ἀνὴρ οὐκ ἐπιεικὴς καὶ ἥμερος τὸν τρόπον, ἀλλὰ καὶ τοῖς παισὶ τῶν Ἀθηναίων ὑπερηφάνως καὶ χαλεπῶς προσφερόμενος. Ἀριστοτέλης δὲ καὶ αὐτὸς ἐν τῇ Βοττιαίων πολιτείᾳ δῆλός ἐστιν οὐ νομίζων ἀναιρεῖσθαι τοὺς παῖδας ὑπὸ τοῦ Μίνω, ἀλλὰ θητεύοντας ἐν τῇ Κρήτῃ καταγηράσκειν· καί ποτε Κρῆτας εὐχὴν παλαιὰν ἀποδιδόντας ἀνθρώπων ἀπαρχὴν εἰς Δελφοὺς ἀποστέλλειν, τοῖς δὲ πεμπομένοις ἀναμιχθέντας ἐκγόνους ἐκείνων συνεξελθεῖν· ὡς δὲ οὐκ ἦσαν ἱκανοὶ τρέφειν ἑαυτοὺς αὐτόθι, πρῶτον μὲν εἰς Ἰταλίαν διαπερᾶσαι κἀκεῖ κατοικεῖν περὶ τὴν Ἰαπυγίαν, ἐκεῖθεν δὲ αὖθις εἰς Θρᾴκην κομισθῆναι καὶ κληθῆναι Βοττιαίους· διὸ τὰς κόρας τῶν Βοττιαίων θυσίαν τινὰ τελούσας ἐπᾴδειν·", "st": "Thes. 16.1"}, {"sp": "N", "t": "ἴωμεν εἰς Ἀθήνας. ἔοικε γὰρ ὄντως χαλεπὸν εἶναι φωνὴν ἐχούσῃ πόλει καὶ μοῦσαν ἀπεχθάνεσθαι. καὶ γὰρ ὁ Μίνως ἀεὶ διετέλει κακῶς ἀκούων καὶ λοιδορούμενος ἐν τοῖς Ἀττικοῖς θεάτροις, καὶ οὔτε Ἡσίοδος αὐτὸν ὤνησε βασιλεύτατον οὔτε Ὅμηρος ὀαριστὴν Διὸς προσαγορεύσας, ἀλλ’ ἐπικρατήσαντες οἱ τραγικοὶ πολλὴν ἀπὸ τοῦ λογείου καὶ τῆς σκηνῆς ἀδοξίαν αὐτοῦ κατεσκέδασαν ὡς χαλεποῦ καὶ βιαίου γενομένου. καίτοι φασὶ τὸν μὲν Μίνω βασιλέα καὶ νομοθέτην, δικαστὴν δὲ τὸν Ῥαδάμανθυν εἶναι καὶ φύλακα τῶν ὡρισμένων ὑπ’ ἐκείνου δικαίων.", "st": "Thes. 16.3"}, {"sp": "N", "t": "ἐπεὶ δ’ οὖν καθῆκεν ὁ χρόνος τοῦ τρίτου δασμοῦ, καὶ παρέχειν ἔδει τοὺς πατέρας ἐπὶ τὸν κλῆρον οἷς ἦσαν ἠΐθεοι παῖδες, αὖθις ἀνεφύοντο τῷ Αἰγεῖ διαβολαὶ πρὸς τοὺς πολίτας, ὀδυρομένους καὶ ἀγανακτοῦντας ὅτι πάντων αἴτιος ὢν ἐκεῖνος, οὐδὲν μέρος ἔχει τῆς κολάσεως μόνος, ἀλλ’ ἐπὶ νόθῳ καὶ ξένῳ παιδὶ τὴν ἀρχὴν πεποιημένος αὐτοὺς περιορᾷ γνησίων ἐρήμους καὶ ἄπαιδας ἀπολειπομένους. ταῦτ’ ἠνία τὸν Θησέα, καὶ δικαιῶν μὴ ἀμελεῖν, ἀλλὰ κοινωνεῖν τῆς τύχης τοῖς πολίταις, ἐπέδωκεν ἑαυτὸν ἄνευ κλήρου προσελθών. καὶ τοῖς μὲν ἄλλοις τό τε φρόνημα θαυμαστὸν ἐφάνη καὶ τὸ δημοτικὸν ἠγάπησαν, ὁ δὲ Αἰγεύς, ἐπεὶ δεόμενος καὶ καθικετεύων ἀμετάπειστον ἑώρα καὶ ἀμετάτρεπτον, ἀπεκλήρωσε τοὺς ἄλλους παῖδας.", "st": "Thes. 17.1"}, {"sp": "N", "t": "Ἑλλάνικος δέ φησιν οὐ τοὺς λαχόντας ἀπὸ κλήρου καὶ τὰς λαχούσας ἐκπέμπειν τὴν πόλιν, αὐτὸν δὲ τὸν Μίνω παραγινόμενον ἐκλέγεσθαι καὶ τὸν Θησέα πάντων ἑλέσθαι πρῶτον ἐπὶ τοῖς ὁρισθεῖσιν· ὡρισμένον δ’ εἶναι τὴν μὲν ναῦν Ἀθηναίους παρέχειν, ἐμβάντας δὲ πλεῖν σὺν αὐτῷ τοὺς ἠϊθέους μηδὲν ὅπλον ἀρήϊον ἐπιφερομένους, ἀπολομένου δὲ τοῦ Μινωταύρου πέρας ἔχειν τὴν ποινήν.", "st": "Thes. 17.3"}, {"sp": "N", "t": "πρότερον μὲν οὖν οὐδεμία σωτηρίας ἐλπὶς ὑπέκειτο· διὸ καὶ μέλαν ἱστίον ἔχουσαν, ὡς ἐπὶ συμφορᾷ προδήλῳ, τὴν ναῦν ἔπεμπον· τότε δὲ τοῦ Θησέως τὸν πατέρα θαρρύνοντος καὶ μεγαληγοροῦντος ὡς χειρώσεται τὸν Μινώταυρον, ἔδωκεν ἕτερον ἱστίον λευκὸν τῷ κυβερνήτῃ, κελεύσας ὑποστρέφοντα σωζομένου τοῦ Θησέως ἐπάρασθαι τὸ λευκόν, εἰ δὲ μή, τῷ μέλανι πλεῖν καὶ ἀποσημαίνειν τὸ πάθος.", "st": "Thes. 17.4"}, {"sp": "N", "t": "ὁ δὲ Σιμωνίδης οὐ λευκόν φησιν εἶναι τὸ δοθὲν ὑπὸ τοῦ Αἰγέως, ἀλλὰ φοινίκεον ἱστίον ὑγρῷ πεφυρμένον πρίνου ἄνθει ἐριθάλλου· καὶ τοῦτο τῆς σωτηρίας αὐτῶν ποιήσασθαι σημεῖον· ἐκυβέρνα δὲ τὴν ναῦν Ἀμαρσυάδας Φέρεκλος, ὥς φησι Σιμωνίδης. φιλόχορος δὲ παρὰ Σκίρου φησὶν ἐκ Σαλαμῖνος τὸν Θησέα λαβεῖν κυβερνήτην μὲν Ναυσίθοον, πρωρέα δὲ Φαίακα, μηδέπω τότε τῶν Ἀθηναίων προσεχόντων τῇ θαλάττῃ· καὶ γὰρ εἶναι τῶν ἠϊθέων ἕνα Μενέσθην Σκίρου θυγατριδοῦν. μαρτυρεῖ δὲ τούτοις ἡρῷα Ναυσιθόου καὶ Φαίακος εἱσαμένου Θησέως Φαληροῖ πρὸς τῷ τοῦ Σκίρου ἱερῷ, καὶ τὴν ἑορτὴν τὰ Κυβερνήσιά φασιν ἐκείνοις τελεῖσθαι.", "st": "Thes. 17.5"}, {"sp": "N", "t": "γενομένου δὲ τοῦ κλήρου παραλαβὼν τοὺς λαχόντας ὁ Θησεὺς ἐκ τοῦ πρυτανείου, καὶ παρελθὼν εἰς Δελφίνιον, ἔθηκεν ὑπὲρ αὐτῶν τῷ Ἀπόλλωνι τὴν ἱκετηρίαν. ἦν δὲ κλάδος ἀπὸ τῆς ἱερᾶς ἐλαίας, ἐρίῳ λευκῷ κατεστεμμένος. εὐξάμενος δὲ κατέβαινεν ἕκτῃ μηνὸς ἐπὶ θάλασσαν ἱσταμένου Μουνυχιῶνος, ᾗ καὶ νῦν ἔτι τὰς κόρας πέμπουσιν ἱλασομένας εἰς Δελφίνιον. λέγεται δὲ αὐτῷ τὸν μὲν ἐν Δελφοῖς ἀνελεῖν θεὸν Ἀφροδίτην καθηγεμόνα ποιεῖσθαι καὶ παρακαλεῖν συνέμπορον, θύοντι δὲ πρὸς θαλάσσῃ τὴν αἶγα θήλειαν οὖσαν αὐτομάτως τράγον γενέσθαι· διὸ καὶ καλεῖσθαι τὴν θεὸν Ἐπιτραγίαν.", "st": "Thes. 18.1"}, {"sp": "N", "t": "ἐπεὶ δὲ κατέπλευσεν εἰς Κρήτην, ὡς μὲν οἱ πολλοὶ γράφουσι καὶ ᾄδουσι, παρὰ τῆς Ἀριάδνης ἐρασθείσης τὸ λίνον λαβών, καὶ διδαχθεὶς ὡς ἔστι τοῦ λαβυρίνθου τοὺς ἑλιγμοὺς διεξελθεῖν, ἀπέκτεινε τὸν Μινώταυρον καὶ ἀπέπλευσε τὴν Ἀριάδνην ἀναλαβὼν καὶ τοὺς ἠϊθέους. Φερεκύδης δὲ καὶ τὰ ἐδάφη τῶν Κρητικῶν νεῶν φησιν ἐκκόψαι τὸν Θησέα, τὴν δίωξιν ἀφαιρούμενον. δήμων δὲ καὶ τὸν Ταῦρον ἀναιρεθῆναί φησι τὸν τοῦ Μίνω στρατηγόν, ἐν τῷ λιμένι διαναυμαχοῦντα τοῦ Θησέως ἐκπλέοντος. ὡς δὲ Φιλόχορος ἱστόρηκε, τὸν ἀγῶνα τοῦ Μίνω συντελοῦντος, ἐπίδοξος ὢν ἅπαντας πάλιν νικήσειν, ὁ Ταῦρος ἐφθονεῖτο. καὶ γὰρ ἡ δύναμις αὐτοῦ διὰ τὸν τρόπον ἦν ἐπαχθής, καὶ διαβολὴν εἶχεν ὡς τῇ Πασιφάῃ πλησιάζων. διὸ καὶ τοῦ Θησέως ἀξιοῦντος ἀγωνίσασθαι συνεχώρησεν ὁ Μίνως. ἔθους δὲ ὄντος ἐν Κρήτῃ θεᾶσθαι καὶ τὰς γυναῖκας, Ἀριάδνη παροῦσα πρός τε τὴν ὄψιν ἐξεπλάγη τοῦ Θησέως καὶ τὴν ἄθλησιν ἐθαύμασε πάντων κρατήσαντος. ἡσθεὶς δὲ καὶ ὁ Μίνως μάλιστα τοῦ Ταύρου καταπαλαισθέντος καὶ προπηλακισθέντος, ἀπέδωκε τῷ Θησεῖ τοὺς παῖδας καὶ ἀνῆκε τῇ πόλει τὸν δασμόν.", "st": "Thes. 19.1"}, {"sp": "N", "t": "ἰδίως δέ πως καὶ περιττῶς ὁ Κλείδημος ἀπήγγειλε περὶ τούτων, ἄνωθέν ποθεν ἀρξάμενος, ὅτι δόγμα κοινὸν ἦν Ἑλλήνων μηδεμίαν ἐκπλεῖν τριήρη μηδαμόθεν ἀνδρῶν πέντε πλείονας δεχομένην· τὸν δὲ ἄρχοντα τῆς Ἀργοῦς Ἰάσονα μόνον περιπλεῖν ἐξείργοντα τῆς θαλάττης τὰ λῃστήρια. Δαιδάλου δὲ πλοίῳ φυγόντος εἰς Ἀθήνας, Μίνως παρὰ τὰ δόγματα μακραῖς ναυσὶ διώκων ὑπὸ χειμῶνος εἰς Σικελίαν ἀπηνέχθη κἀκεῖ κατέστρεψε τὸν βίον. ἐπεὶ δὲ Δευκαλίων ὁ υἱὸς αὐτοῦ πολεμικῶς ἔχων πρὸς τοὺς Ἀθηναίους ἔπεμψεν, ἐκδιδόναι Δαίδαλον αὑτῷ κελεύων ἢ τοὺς παῖδας ἀποκτενεῖν ἀπειλῶν οὓς ἔλαβεν ὁμήρους ὁ Μίνως, τούτῳ μὲν ἀπεκρίνατο πρᾴως ὁ Θησέυς, παραιτούμενος ἀνεψιὸν ὄντα Δαίδαλον κἀκείνῳ κατὰ γένος προσήκοντα, μητρὸς ὄντα Μερόπης τῆς Ἐρεχθέως, αὐτὸς δὲ ναυπηγίαν ἐπεβάλετο, τὴν μὲν ἐν Θυμαιταδῶν αὐτόθι μακρὰν τῆς ξενικῆς ὁδοῦ, τὴν δὲ διὰ Πιτθέως ἐν Τροιζῆνι, βουλόμενος λανθάνειν. γενομένων δὲ ἑτοίμων ἐξέπλευσε τόν τε Δαίδαλον ἔχων καὶ φυγάδας ἐκ Κρήτης καθηγεμόνας· οὐδενὸς δὲ προειδότος, ἀλλὰ ναῦς φιλίας οἰομένων τῶν Κρητῶν προσφέρεσθαι, τοῦ λιμένος κρατήσας καὶ ἀποβὰς ἔφθασεν εἰς τὴν Κνωσσὸν παρελθών· καὶ μάχην ἐν πύλαις τοῦ Λαβυρίνθου συνάψας ἀπέκτεινε τὸν Δευκαλίωνα καὶ τοὺς δορυφόρους. ἐν δὲ τοῖς πράγμασι τῆς Ἀριάδνης γενομένης, σπεισάμενος πρὸς αὐτὴν τούς τε ἠϊθέους ἀνέλαβε καὶ φιλίαν ἐποίησε τοῖς Ἀθηναίοις πρὸς τοὺς Κρῆτας, ὀμόσαντας μηδέποτε πολέμου κατάρξειν.", "st": "Thes. 19.4"}, {"sp": "N", "t": "πολλοὶ δὲ λόγοι καὶ περὶ τούτων ἔτι λέγονται καὶ περὶ τῆς Ἀριάδνης, οὐδὲν ὁμολογούμενον ἔχοντες. οἱ μὲν γὰρ ἀπάγξασθαί φασιν αὐτὴν ἀπολειφθεῖσαν ὑπὸ τοῦ Θησέως, οἱ δὲ εἰς Νάξον ὑπὸ ναυτῶν κομισθεῖσαν Οἰνάρῳ τῷ ἱερεῖ τοῦ Διονύσου συνοικεῖν, ἀπολειφθῆναι δὲ τοῦ Θησέως ἐρῶντος ἑτέρας·", "st": "Thes. 20.1"}, {"sp": "N", "t": "δεινὸς γάρ μὲν ἔτειρεν ἔρως Πανοπηΐδος Αἴγλης.", "st": "Thes. 20.1b"}, {"sp": "N", "t": "τοῦτο γὰρ τὸ ἔπος ἐκ τῶν Ἡσιόδου Πεισίστρατον ἐξελεῖν φησιν Ἡρέας ὁ Μεγαρεύς, ὥσπερ αὖ πάλιν ἐμβαλεῖν εἰς τὴν Ὁμήρου νέκυιαν τὸ", "st": "Thes. 20.2"}, {"sp": "N", "t": "Θησέα Πειρίθοόν τε θεῶν ἀριδείκετα τέκνα,", "st": "Thes. 20.2b"}, {"sp": "N", "t": "χαριζόμενον Ἀθηναίοις· ἔνιοι δὲ καὶ τεκεῖν ἐκ Θησέως Ἀριάδνην Οἰνοπίωνα καὶ Στάφυλον· ὧν καὶ ὁ Χῖος Ἴων ἐστὶ περὶ τῆς ἑαυτοῦ πατρίδος λέγων·", "st": "Thes. 20.2c"}, {"sp": "N", "t": "τήν ποτε Θησείδης ἔκτισεν Οἰνοπίων.", "st": "Thes. 20.2d"}, {"sp": "N", "t": "ἃ δ’ ἐστὶν εὐφημότατα τῶν μυθολογουμένων, πάντες ὡς ἔπος εἰπεῖν διὰ στόματος ἔχουσιν. ἴδιον δέ τινα περὶ τούτων λόγον ἐκδέδωκε Παίων ὁ Ἀμαθούσιος. τὸν γὰρ Θησέα φησὶν ὑπὸ χειμῶνος εἰς Κύπρον ἐξενεχθέντα καὶ τὴν Ἀριάδνην ἔγκυον ἔχοντα, φαύλως δὲ διακειμένην ὑπὸ τοῦ σάλου καὶ δυσφοροῦσαν, ἐκβιβάσαι μόνην, αὐτὸν δὲ τῷ πλοίῳ βοηθοῦντα πάλιν εἰς τὸ πέλαγος ἀπὸ τῆς γῆς φέρεσθαι. τὰς οὖν ἐγχωρίους γυναῖκας τὴν Ἀριάδνην ἀναλαβεῖν καὶ περιέπειν ἀθυμοῦσαν ἐπὶ τῇ μονώσει, καὶ γράμματα πλαστὰ προσφέρειν, ὡς τοῦ Θησέως γράφοντος αὐτῇ, καὶ περὶ τὴν ὠδῖνα συμπονεῖν καὶ βοηθεῖν· ἀποθανοῦσαν δὲ θάψαι μὴ τεκοῦσαν. ἐπελθόντα δὲ τὸν Θησέα καὶ περίλυπον γενόμενον τοῖς μὲν ἐγχωρίοις ἀπολιπεῖν χρήματα, συντάξαντα θύειν τῇ Ἀριάδνῃ, δύο δὲ μικροὺς ἀνδριαντίσκους ἱδρύσασθαι, τὸν μὲν ἀργυροῦν, τὸν δὲ χαλκοῦν. ἐν δὲ τῇ θυσίᾳ τοῦ Γορπιαίου μηνὸς ἱσταμένου δευτέρᾳ κατακλινόμενόν τινα τῶν νεανίσκων φθέγγεσθαι καὶ ποιεῖν ἅπερ ὠδίνουσαι γυναῖκες· καλεῖν δὲ τὸ ἄλσος Ἀμαθουσίους, ἐν ᾧ τὸν τάφον δεικνύουσιν, Ἀριάδνης Ἀφροδίτης.", "st": "Thes. 20.3"}, {"sp": "N", "t": "καὶ Ναξίων δέ τινες ἰδίως ἱστοροῦσι δύο Μίνωας γενέσθαι καὶ δύο Ἀριάδνας, ὧν τὴν μὲν Διονύσῳ γαμηθῆναί φασιν ἐν Νάξῳ καὶ τοὺς περὶ Στάφυλον τεκεῖν, τὴν δὲ νεωτέραν ἁρπασθεῖσαν ὑπὸ τοῦ Θησέως καὶ ἀπολειφθεῖσαν εἰς Νάξον ἐλθεῖν, καὶ τροφὸν μετ’ αὐτῆς ὄνομα Κορκύνην, ἧς δείκνυσθαι τάφον. ἀποθανεῖν δὲ καὶ τὴν Ἀριάδνην αὐτόθι καὶ τιμὰς ἔχειν οὐχ ὁμοίας τῇ προτέρᾳ. τῇ μὲν γὰρ ἡδομένους καὶ παίζοντας ἑορτάζειν, τὰς δὲ ταύτῃ δρωμένας θυσίας εἶναι πένθει τινὶ καὶ στυγνότητι μεμιγμένας.", "st": "Thes. 20.5"}, {"sp": "N", "t": "ἐκ δὲ τῆς Κρήτης ἀποπλέων εἰς Δῆλον κατέσχε· καὶ τῷ θεῷ θύσας καὶ ἀναθεὶς τὸ ἀφροδίσιον ὃ παρὰ τῆς Ἀριάδνης ἔλαβεν, ἐχόρευσε μετὰ τῶν ἠϊθέων χορείαν ἣν ἔτι νῦν ἐπιτελεῖν Δηλίους λέγουσι, μίμημα τῶν ἐν τῷ Λαβυρίνθῳ περιόδων καὶ διεξόδων, ἔν τινι ῥυθμῷ παραλλάξεις καὶ ἀνελίξεις ἔχοντι γιγνομένην. καλεῖται δὲ τὸ γένος τοῦτο τῆς χορείας ὑπὸ Δηλίων γέρανος, ὡς ἱστορεῖ Δικαίαρχος. ἐχόρευσε δὲ περὶ τὸν Κερατῶνα βωμόν, ἐκ κεράτων συνηρμοσμένον εὐωνύμων ἁπάντων. ποιῆσαι δὲ καὶ ἀγῶνά φασιν αὐτὸν ἐν Δήλῳ, καὶ τοῖς νικῶσι τότε πρῶτον ὑπ’ ἐκείνου φοίνικα δοθῆναι.", "st": "Thes. 21.1"}, {"sp": "N", "t": "τῇ δὲ Ἀττικῇ προσφερομένων ἐκλαθέσθαι μὲν αὐτόν, ἐκλαθέσθαι δὲ τὸν κυβερνήτην ὑπὸ χαρᾶς ἐπάρασθαι τὸ ἱστίον ᾧ τὴν σωτηρίαν αὐτῶν ἔδει γνώριμον τῷ Αἰγεῖ γενέσθαι· τὸν δὲ ἀπογνόντα ῥῖψαι κατὰ τῆς πέτρας ἑαυτὸν καὶ διαφθαρῆναι. καταπλεύσας δὲ ὁ Θησεὺς ἔθυε μὲν αὐτὸς ἃς ἐκπλέων θυσίας εὔξατο τοῖς θεοῖς Φαληροῖ, κήρυκα δὲ ἀπέστειλε τῆς σωτηρίας ἄγγελον εἰς ἄστυ. οὗτος ἐνέτυχεν ὀδυρομένοις τε πολλοῖς τὴν τοῦ βασιλέως τελευτὴν καὶ χαίρουσιν, ὡς εἰκός, ἑτέροις καὶ φιλοφρονεῖσθαι καὶ στεφανοῦν αὐτὸν ἐπὶ τῇ σωτηρίᾳ προθύμοις οὖσι. τοὺς μὲν οὖν στεφάνους δεχόμενος τὸ κηρύκειον ἀνέστεφεν, ἐπανελθὼν δὲ ἐπὶ θάλασσαν οὔπω πεποιημένου σπονδὰς τοῦ Θησέως ἔξω περιέμεινε, μὴ βουλόμενος τὴν θυσίαν ταράξαι. γενομένων δὲ τῶν σπονδῶν ἀπήγγειλε τὴν τοῦ Αἰγέως τελευτήν. οἱ δὲ σὺν κλαυθμῷ καὶ θορύβῳ σπεύδοντες ἀνέβαινον εἰς τὴν πόλιν. ὅθεν καὶ νῦν ἐν τοῖς ὠσχοφορίοις στεφανοῦσθαι μὲν οὐ τὸν κήρυκα λέγουσιν, ἀλλὰ τὸ κηρύκειον, ἐπιφωνεῖν δὲ ἐν ταῖς σπονδαῖς, Ἐλελεῦ, Ἰού, Ἰού, τοὺς παρόντας· ὧν τὸ μὲν σπεύδοντες ἀναφωνεῖν καὶ παιωνίζοντες εἰώθασι, τὸ δὲ ἐκπλήξεως καὶ ταραχῆς ἐστι.", "st": "Thes. 22.1"}, {"sp": "N", "t": "θάψας δὲ τὸν πατέρα, τῷ Ἀπόλλωνι τὴν εὐχὴν ἀπεδίδου τῇ ἑβδόμῃ τοῦ Πυανεψιῶνος μηνὸς ἱσταμένου· ταύτῃ γὰρ ἀνέβησαν εἰς ἄστυ σωθέντες. ἡ μὲν οὖν ἕψησις τῶν ὀσπρίων λέγεται γίνεσθαι διὰ τὸ σωθέντας αὐτοὺς εἰς ταὐτὸ συμμῖξαι τὰ περιόντα τῶν σιτίων καὶ μίαν χύτραν κοινὴν ἑψήσαντας συνεστιαθῆναι καὶ συγκαταφαγεῖν ἀλλήλοις. τὴν δὲ εἰρεσιώνην ἐκφέρουσι κλάδον ἐλαίας ἐρίῳ μὲν ἀνεστεμμένον, ὥσπερ τότε τὴν ἱκετηρίαν, παντοδαπῶν δὲ ἀνάπλεων καταργμάτων διὰ τὸ λῆξαι τὴν ἀφορίαν, ἐπᾴδοντες·", "st": "Thes. 22.4"}, {"sp": "N", "t": "εἰρεσιώνη σῦκα φέρει καὶ πίονας ἄρτους<br>καὶ μέλι ἐν κοτύλῃ καὶ ἔλαιον ἀποψήσασθαι<br>καὶ κύλικ’ εὔζωρον, ὡς ἂν μεθύουσα καθεύδῃ.", "st": "Thes. 22.4b"}, {"sp": "N", "t": "καίτοι ταῦτά τινες ἐπὶ τοῖς Ἡρακλείδαις γίνεσθαι λέγουσιν, οὕτως διατρεφομένοις ὑπὸ τῶν Ἀθηναίων· οἱ δὲ πλείονες ὡς προείρηται.", "st": "Thes. 22.4c"}, {"sp": "N", "t": "τὸ δὲ πλοῖον ἐν ᾧ μετὰ τῶν ἠϊθέων ἔπλευσε καὶ πάλιν ἐσώθη, τὴν τριακόντορον, ἄχρι τῶν Δημητρίου τοῦ Φαληρέως χρόνων διεφύλαττον οἱ Ἀθηναῖοι, τὰ μὲν παλαιὰ τῶν ξύλων ὑφαιροῦντες, ἄλλα δὲ ἐμβάλλοντες ἰσχυρὰ καὶ συμπηγνύντες οὕτως ὥστε καὶ τοῖς φιλοσόφοις εἰς τὸν αὐξόμενον λόγον ἀμφιδοξούμενον παράδειγμα τὸ πλοῖον εἶναι, τῶν μὲν ὡς τὸ αὐτό, τῶν δὲ ὡς οὐ τὸ αὐτὸ διαμένοι λεγόντων.", "st": "Thes. 23.1"}, {"sp": "N", "t": "ἄγουσι δὲ καὶ τὴν τῶν ὠσχοφορίων ἑορτὴν Θησέως καταστήσαντος. οὐ γὰρ ἁπάσας αὐτὸν ἐξαγαγεῖν τὰς λαχούσας τότε παρθένους, ἀλλὰ τῶν συνήθων νεανίσκων δύο θηλυφανεῖς μὲν ὀφθῆναι καὶ νεαρούς, ἀνδρώδεις δὲ τὰς ψυχὰς καὶ προθύμους, λουτροῖς τε θερμοῖς καὶ σκιατραφίαις καὶ ταῖς περὶ κόμην καὶ λειότητα καὶ χροιὰν ἀλοιφαῖς καὶ κοσμήσεσιν ὡς ἔστιν ἐξαλλάξαντα κομιδῇ, καὶ διδάξαντα φωνὴν καὶ σχῆμα καὶ βάδισιν ὡς ἔνι μάλιστα παρθένοις ὁμοιοῦσθαι καὶ μηδὲν φαίνεσθαι διαφέροντας, ἐμβαλεῖν εἰς τὸν τῶν παρθένων ἀριθμὸν καὶ διαλαθεῖν ἅπαντας· ἐπεὶ δὲ ἐπανῆλθεν, αὐτόν τε πομπεῦσαι καὶ τοὺς νεανίσκους οὕτως ἀμπεχομένους ὡς νῦν ἀμπέχονται τοὺς ὀσχοὺς φέροντες. φέρουσι δὲ Διονύσῳ καὶ Ἀριάδνῃ χαριζόμενοι διὰ τὸν μῦθον, ἢ μᾶλλον ὅτι συγκομιζομένης ὀπώρας ἐπανῆλθον· αἱ δὲ δειπνοφόροι παραλαμβάνονται καὶ κοινωνοῦσι τῆς θυσίας ἀπομιμούμεναι τὰς μητέρας ἐκείνων τῶν λαχόντων· ἐπεφοίτων γὰρ αὐτοῖς ὄψα καὶ σιτία κομίζουσαι· καὶ μῦθοι λέγονται διὰ τὸ κἀκείνας εὐθυμίας ἕνεκα καὶ παρηγορίας μύθους διεξιέναι τοῖς παισί. ταῦτα μὲν οὖν καὶ Δήμων ἱστόρηκεν. ἐξῃρέθη δὲ καί τέμενος αὐτῷ, καὶ τοὺς ἀπὸ τῶν παρασχόντων τὸν δασμὸν οἴκων ἔταξεν εἰς θυσίαν αὑτῷ τελεῖν ἀποφοράς· καὶ τῆς θυσίας ἐπεμελοῦντο Φυταλίδαι, Θησέως ἀποδόντος αὐτοῖς ἀμοιβὴν τῆς φιλοξενίας.", "st": "Thes. 23.2"}, {"sp": "N", "t": "μετὰ δὲ τὴν Αἰγέως τελευτὴν μέγα καὶ θαυμαστὸν ἔργον εἰς νοῦν βαλόμενος συνῴκισε τοὺς τὴν Ἀττικὴν κατοικοῦντας εἰς ἓν ἄστυ, καὶ μιᾶς πόλεως ἕνα δῆμον ἀπέφηνε, τέως σποράδας ὄντας καὶ δυσανακλήτους πρὸς τὸ κοινὸν πάντων συμφέρον, ἔστι δ’ ὅτε καὶ διαφερομένους ἀλλήλοις καὶ πολεμοῦντας. ἐπιὼν οὖν ἀνέπειθε κατὰ δήμους καὶ γένη, τῶν μὲν ἰδιωτῶν καὶ πενήτων ἐνδεχομένων ταχὺ τὴν παράκλησιν αὐτοῦ, τοῖς δὲ δυνατοῖς ἀβασίλευτον πολιτείαν προτείνων καὶ δημοκρατίαν αὐτῷ μόνον ἄρχοντι πολέμου καὶ νόμων φύλακι χρησομένην, τῶν δὲ ἄλλων παρέξουσαν ἅπασιν ἰσομοιρίαν. τοὺς μὲν ταῦτα ἔπειθεν, οἱ δὲ τὴν δύναμιν αὐτοῦ δεδιότες μεγάλην οὖσαν ἤδη καὶ τὴν τόλμαν, ἐβούλοντο πειθόμενοι μᾶλλον ἢ βιαζόμενοι ταῦτα συγχωρεῖν. καταλύσας οὖν τὰ παρ’ ἑκάστοις πρυτανεῖα καὶ βουλευτήρια καὶ ἀρχάς, ἓν δὲ ποιήσας ἅπασι κοινὸν ἐνταῦθα πρυτανεῖον καὶ βουλευτήριον ὅπου νῦν ἵδρυται τὸ ἄστυ, τήν τε πόλιν Ἀθήνας προσηγόρευσε καὶ Παναθήναια θυσίαν ἐποίησε κοινήν. ἔθυσε δὲ καὶ Μετοίκια τῇ ἕκτῃ ἐπὶ δέκα τοῦ Ἑκατομβαιῶνος, ἣν ἔτι νῦν θύουσι. καὶ τὴν βασιλείαν ἀφείς, ὥσπερ ὡμολόγησε, διεκόσμει τὴν πολιτείαν ἀπὸ θεῶν ἀρχόμενος· ἧκε γὰρ αὐτῷ χρησμὸς ἐκ Δελφῶν μαντευομένῳ περὶ τῆς πόλεως·", "st": "Thes. 24.1"}, {"sp": "N", "t": "Αἰγείδη Θησεῦ, Πιτθηΐδος ἔκγονε κούρης,<br>πολλαῖς τοι πολίεσσι πατὴρ ἐμὸς ἐγκατέθηκε<br>τέρματα καὶ κλωστῆρας ἐν ὑμετέρῳ πτολιέθρῳ.", "st": "Thes. 24.5"}, {"sp": "N", "t": "ἀλλὰ σὺ μή τι λίην πεπονημένος ἔνδοθι θυμὸν<br>βουλεύειν· ἀσκὸς γὰρ ἐν οἴδματι ποντοπορεύσει.", "st": "Thes. 24.5b"}, {"sp": "N", "t": "τοῦτο δὲ καὶ Σίβυλλαν ὕστερον ἀποστοματίσαι πρὸς τὴν πόλιν ἱστοροῦσιν, ἀναφθεγξαμένην·", "st": "Thes. 24.5c"}, {"sp": "N", "t": "ἀσκὸς βαπτίζῃ· δῦναι δέ τοι οὐ θέμις ἐστίν.", "st": "Thes. 24.5d"}, {"sp": "N", "t": "ἔτι δὲ μᾶλλον αὐξῆσαι τὴν πόλιν βουλόμενος ἐκάλει πάντας ἐπὶ τοῖς ἴσοις, καὶ τὸ δεῦρ’ ἴτε πάντες λεῴ κήρυγμα Θησέως γενέσθαι φασὶ πανδημίαν τινὰ καθιστάντος. οὐ μὴν ἄτακτον οὐδὲ μεμιγμένην περιεῖδεν ὑπὸ πλήθους ἐπιχυθέντος ἀκρίτου γενομένην τὴν δημοκρατίαν, ἀλλὰ πρῶτος ἀποκρίνας χωρὶς εὐπατρίδας καὶ γεωμόρους καὶ δημιουργούς, εὐπατρίδαις δὲ γινώσκειν τὰ θεῖα καὶ παρέχειν ἄρχοντας ἀποδοὺς καὶ νόμων διδασκάλους εἶναι καὶ ὁσίων καὶ ἱερῶν ἐξηγητάς, τοῖς ἄλλοις πολίταις ὥσπερ εἰς ἴσον κατέστησε, δόξῃ μὲν εὐπατριδῶν, χρείᾳ δὲ γεωμόρων, πλήθει δὲ δημιουργῶν ὑπερέχειν δοκούντων. ὅτι δὲ πρῶτος ἀπέκλινε πρὸς τὸν ὄχλον, ὡς Ἀριστοτέλης φησί, καὶ ἀφῆκε τὸ μοναρχεῖν, ἔοικε μαρτυρεῖν καὶ Ὅμηρος ἐν νεῶν καταλόγῳ μόνους Ἀθηναίους δῆμον προσαγορεύσας.", "st": "Thes. 25.1"}, {"sp": "N", "t": "ἔκοψε δὲ καὶ νόμισμα, βοῦν ἐγχαράξας, ἢ διὰ τὸν Μαραθώνιον ταῦρον, ἢ διὰ τὸν Μίνω στρατηγόν, ἢ πρὸς γεωργίαν τοὺς πολίτας παρακαλῶν. ἀπ’ ἐκείνου δέ φασι τὸ ἑκατόμβοιον καὶ τὸ δεκάβοιον ὀνομασθῆναι. προσκτησάμενος δὲ τῇ Ἀττικῇ τὴν Μεγαρικὴν βεβαίως, τὴν θρυλουμένην ἐν Ἰσθμῷ στήλην ἔστησεν, ἐπιγράψας τὸ διορίζον ἐπίγραμμα τὴν χώραν δυσὶ τριμέτροις, ὧν ἔφραζε τὸ μὲν πρὸς ἕω", "st": "Thes. 25.3"}, {"sp": "N", "t": "τάδ’ οὐχὶ Πελοπόννησος, ἀλλ’ Ἰωνία·<br>τὸ δὲ πρὸς ἑσπέραν<br>τάδ’ ἐστὶ Πελοπόννησος, οὐκ Ἰωνία.", "st": "Thes. 25.3b"}, {"sp": "N", "t": "καὶ τὸν ἀγῶνα πρῶτος ἔθηκε κατὰ ζῆλον Ἡρακλέους, ὡς δι’ ἐκεῖνον Ὀλύμπια τῷ Διΐ, καὶ δι’ αὐτὸν Ἴσθμια τῷ Ποσειδῶνι φιλοτιμηθεὶς ἄγειν τοὺς Ἕλληνας. ὁ γὰρ ἐπὶ Μελικέρτῃ τεθεὶς αὐτόθι νυκτὸς ἐδρᾶτο, τελετῆς ἔχων μᾶλλον ἢ θέας καὶ πανηγυρισμοῦ τάξιν. ἔνιοι δέ φασιν ἐπὶ Σκείρωνι τὰ Ἴσθμια τεθῆναι, τοῦ Θησέως ἀφοσιουμένου τὸν φόνον διὰ τὴν συγγένειαν· Σκείρωνα γὰρ υἱὸν εἶναι Κανήθου καὶ Ἡνιόχης τῆς Πιτθέως. οἱ δὲ Σίνιν, οὐ Σκείρωνα, καὶ τὸν ἀγῶνα τεθῆναι διὰ τοῦτον ὑπὸ Θησέως, οὐ δι’ ἐκεῖνον. ἔταξεν οὖν καὶ διωρίσατο πρὸς τοὺς Κορινθίους Ἀθηναίων τοῖς ἀφικνουμένοις ἐπὶ τὰ Ἴσθμια παρέχειν προεδρίαν ὅσον ἂν τόπον ἐπίσχῃ καταπετασθὲν τὸ τῆς θεωρίδος νεὼς ἱστίον, ὡς Ἑλλάνικος καὶ Ἄνδρων ὁ Ἁλικαρνασεὺς ἱστορήκασιν.", "st": "Thes. 25.4"}, {"sp": "N", "t": "εἰς δὲ τὸν πόντον ἔπλευσε τὸν Εὔξεινον, ὡς μὲν Φιλόχορος καί τινες ἄλλοι λέγουσι, μεθ’ Ἡρακλέους ἐπὶ τὰς Ἀμαζόνας συστρατεύσας, καὶ γέρας Ἀντιόπην ἔλαβεν· οἱ δὲ πλείους, ὧν ἐστὶ καὶ Φερεκύδης καὶ Ἑλλάνικος καὶ Ἡρόδωρος, ὕστερόν φασιν Ἡρακλέους ἰδιόστολον πλεῦσαι τὸν Θησέα καὶ τὴν Ἀμαζόνα λαβεῖν αἰχμάλωτον, πιθανώτερα λέγοντες. οὐδεὶς γὰρ ἄλλος ἱστόρηται τῶν μετ’ αὐτοῦ στρατευσάντων Ἀμαζόνα λαβεῖν αἰχμάλωτον. βίων δὲ καὶ ταύτην παρακρουσάμενον οἴχεσθαι λαβόντα· φύσει γὰρ οὔσας τὰς Ἀμαζόνας φιλάνδρους οὔτε φυγεῖν τὸν Θησέα προσβάλλοντα τῇ χώρᾳ, ἀλλὰ καὶ ξένια πέμπειν· τὸν δὲ τὴν κομίζουσαν ἐμβῆναι παρακαλεῖν εἰς τὸ πλοῖον·", "st": "Thes. 26.1"}, {"sp": "N", "t": "ἐμβάσης δὲ ἀναχθῆναι. Μενεκράτης δέ τις, ἱστορίαν περὶ Νικαίας τῆς ἐν Βιθυνίᾳ πόλεως ἐκδεδωκώς, Θησέα φησὶ τὴν Ἀντιόπην ἔχοντα διατρῖψαι περὶ τούτους τοὺς τόπους· τυγχάνειν δὲ συστρατεύοντας αὐτῷ τρεῖς νεανίσκους ἐξ Ἀθηνῶν ἀδελφοὺς ἀλλήλων, Εὔνεων καὶ Θόαντα καὶ Σολόεντα. τοῦτον οὖν ἐρῶντα τῆς Ἀντιόπης καὶ λανθάνοντα τοὺς ἄλλους ἐξειπεῖν πρὸς ἕνα τῶν συνήθων· ἐκείνου δὲ περὶ τούτων ἐντυχόντος τῇ Ἀντιόπῃ, τὴν μὲν πεῖραν ἰσχυρῶς ἀποτρίψασθαι, τὸ δὲ πρᾶγμα σωφρόνως ἅμα καὶ πρᾴως ἐνεγκεῖν καὶ πρὸς τὸν Θησέα μὴ κατηγορῆσαι. τοῦ δὲ Σολόεντος ὡς ἀπέγνω ῥίψαντος ἑαυτὸν εἰς ποταμόν τινα καὶ διαφθαρέντος, ᾐσθημένον τότε τὴν αἰτίαν καὶ τὸ πάθος τοῦ νεανίσκου τὸν Θησέα βαρέως ἐνεγκεῖν, καὶ δυσφοροῦντα λόγιόν τι πυθόχρηστον ἀνενεγκεῖν πρὸς ἑαυτόν· εἶναι γὰρ αὐτῷ προστεταγμένον ἐν Δελφοῖς ὑπὸ τῆς Πυθίας, ὅταν ἐπὶ ξένης ἀνιαθῇ μάλιστα καὶ περίλυπος γένηται, πόλιν ἐκεῖ κτίσαι καὶ τῶν ἀμφ’ αὐτόν τινας ἡγεμόνας καταλιπεῖν. ἐκ δὲ τούτου τὴν μὲν πόλιν, ἣν ἔκτισεν, ἀπὸ τοῦ θεοῦ Πυθόπολιν προσαγορεῦσαι, Σολόεντα δὲ τὸν πλησίον ποταμὸν ἐπὶ τιμῇ τοῦ νεανίσκου. καταλιπεῖν δὲ καὶ τοὺς ἀδελφοὺς αὐτοῦ, οἷν ἐπιστάτας καὶ νομοθέτας, καὶ σὺν αὐτοῖς Ἕρμον ἄνδρα τῶν Ἀθήνησιν εὐπατριδῶν· ἀφ’ οὗ καὶ τόπον Ἑρμοῦ καλεῖν οἰκίαν τοὺς Πυθοπολίτας, οὐκ ὀρθῶς τὴν δευτέραν συλλαβὴν περισπῶντας καὶ τὴν δόξαν ἐπὶ θεὸν ἀπὸ ἥρωος μετατιθέντας.", "st": "Thes. 26.3"}, {"sp": "N", "t": "πρόφασιν μὲν οὖν ταύτην ὁ τῶν Ἀμαζόνων πόλεμος ἔσχε· φαίνεται δὲ μὴ φαῦλον αὐτοῦ μηδὲ γυναικεῖον γενέσθαι τὸ ἔργον. οὐ γὰρ ἂν ἐν ἄστει κατεστρατοπέδευσαν οὐδὲ τὴν μάχην συνῆψαν ἐν χρῷ περὶ τὴν Πνύκα καὶ τὸ Μουσεῖον, εἰ μὴ κρατοῦσαι τῆς χώρας ἀδεῶς τῇ πόλει προσέμιξαν. εἰ μὲν οὖν, ὡς Ἑλλάνικος ἱστόρηκε, τῷ Κιμμερικῷ Βοσπόρῳ παγέντι διαβᾶσαι περιῆλθον, ἔργον ἐστὶ πιστεῦσαι· τὸ δὲ ἐν τῇ πόλει σχεδὸν αὐτὰς ἐνστρατοπεδεῦσαι μαρτυρεῖται καὶ τοῖς ὀνόμασι τῶν τόπων καὶ ταῖς θήκαις τῶν πεσόντων.", "st": "Thes. 27.1"}, {"sp": "N", "t": "πολὺν δὲ χρόνον ὄκνος ἦν καὶ μέλλησις ἀμφοτέροις τῆς ἐπιχειρήσεως· τέλος δὲ Θησεὺς κατά τι λόγιον τῷ Φόβῳ σφαγιασάμενος συνῆψεν αὐταῖς. ἡ μὲν οὖν μάχη Βοηδρομιῶνος ἐγένετο μηνὸς ἐφ’ ᾗ τὰ Βοηδρόμια μέχρι νῦν Ἀθηναῖοι θύουσιν. ἱστορεῖ δὲ Κλείδημος, ἐξακριβοῦν τὰ καθ’ ἕκαστα βουλόμενος, τὸ μὲν εὐώνυμον τῶν Ἀμαζόνων κέρας ἐπιστρέφειν πρὸς τὸ νῦν καλούμενον Ἀμαζόνειον, τῷ δὲ δεξιῷ πρὸς τὴν Πνύκα κατὰ τὴν Χρύσαν ἥκειν. μάχεσθαι δὲ πρὸς τοῦτο τοὺς Ἀθηναίους ἀπὸ τοῦ Μουσείου ταῖς Ἀμαζόσι συμπεσόντας, καὶ τάφους τῶν πεσόντων περὶ τὴν πλατεῖαν εἶναι τὴν φέρουσαν ἐπὶ τὰς πύλας παρὰ τὸ Χαλκώδοντος ἡρῷον, ἃς νῦν Πειραϊκὰς ὀνομάζουσι. καὶ ταύτῃ μὲν ἐκβιασθῆναι μέχρι τῶν Εὐμενίδων καὶ ὑποχωρῆσαι ταῖς γυναιξίν, ἀπὸ δὲ Παλλαδίου καὶ Ἀρδηττοῦ καὶ Λυκείου προσβαλόντας ὤσασθαι τὸ δεξιὸν αὐτῶν ἄχρι τοῦ στρατοπέδου καὶ πολλὰς καταβαλεῖν. τετάρτῳ δὲ μηνὶ συνθήκας γενέσθαι διὰ τῆς Ἱππολύτης· Ἱππολύτην γὰρ οὗτος ὀνομάζει τὴν τῷ Θησεῖ συνοικοῦσαν, οὐκ Ἀντιόπην.", "st": "Thes. 27.3"}, {"sp": "N", "t": "ἔνιοι δέ φασι μετὰ τοῦ Θησέως μαχομένην πεσεῖν τὴν ἄνθρωπον ὑπὸ Μολπαδίας ἀκοντισθεῖσαν, καὶ τὴν στήλην τὴν παρὰ τὸ τῆς Ὀλυμπίας ἱερὸν ἐπὶ ταύτῃ κεῖσθαι. καὶ θαυμαστὸν οὐκ ἔστιν ἐπὶ πράγμασιν οὕτω παλαιοῖς πλανᾶσθαι τὴν ἱστορίαν, ἐπεὶ καὶ τὰς τετρωμένας φασὶ τῶν Ἀμαζόνων ὑπ’ Ἀντιόπης εἰς Χαλκίδα λάθρα διαπεμφθείσας τυγχάνειν ἐπιμελείας, καὶ ταφῆναί τινας ἐκεῖ περὶ τὸ νῦν Ἀμαζόνειον καλούμενον. ἀλλὰ τοῦ γε τὸν πόλεμον εἰς σπονδὰς τελευτῆσαι μαρτύριόν ἐστιν ἥ τε τοῦ τόπου κλῆσις τοῦ παρὰ τὸ Θησεῖον, ὅνπερ Ὁρκωμόσιον καλοῦσιν, ἥ τε γινομένη πάλαι θυσία ταῖς Ἀμαζόσι πρὸ τῶν Θησείων. δεικνύουσι δὲ καὶ Μεγαρεῖς Ἀμαζόνων θήκην παρ’ αὑτοῖς, ἐπὶ τὸν καλούμενον Ῥοῦν βαδίζουσιν ἐξ ἀγορᾶς, ὅπου τὸ Ῥομβοειδές. λέγεται δὲ καὶ περὶ Χαιρώνειαν ἑτέρας ἀποθανεῖν, καὶ ταφῆναι παρὰ τὸ ῥευμάτιον ὃ πάλαι μέν, ὡς ἔοικε, Θερμώδων, Αἵμων δὲ νῦν καλεῖται· περὶ ὧν ἐν τῷ Δημοσθένους βίῳ γέγραπται. φαίνονται δὲ μηδὲ Θεσσαλίαν ἀπραγμόνως αἱ Ἀμαζόνες διελθοῦσαι· τάφοι γὰρ αὐτῶν ἔτι καὶ νῦν δείκνυνται περὶ τὴν Σκοτουσαίαν καὶ τὰς Κυνὸς κεφαλάς.", "st": "Thes. 27.5"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἄξια μνήμης περὶ τῶν Ἀμαζόνων. ἣν γὰρ ὁ τῆς Θησηΐδος ποιητὴς Ἀμαζόνων ἐπανάστασιν γέγραφε, Θησεῖ γαμοῦντι Φαίδραν τῆς Ἀντιόπης ἐπιτιθεμένης καὶ τῶν μετ’ αὐτῆς Ἀμαζόνων ἀμυνομένων καὶ κτείνοντος αὐτὰς Ἡρακλέους, περιφανῶς ἔοικε μύθῳ καὶ πλάσματι. τῆς δὲ Ἀντιόπης ἀποθανούσης ἔγημε Φαίδραν, ἔχων υἱὸν Ἱππόλυτον ἐξ Ἀντιόπης, ὡς δὲ Πίνδαρός φησι, Δημοφῶντα. τὰς δὲ περὶ ταύτην καὶ τὸν υἱὸν αὐτοῦ δυστυχίας, ἐπεὶ μηδὲν ἀντιπίπτει παρὰ τῶν ἱστορικῶν τοῖς τραγικοῖς, οὕτως ἔχειν θετέον ὡς ἐκεῖνοι πεποιήκασιν ἅπαντες.", "st": "Thes. 28.1"}, {"sp": "N", "t": "εἰσὶ μέντοι λόγοι περὶ γάμων Θησέως καὶ ἕτεροι, τὴν σκηνὴν διαπεφευγότες, οὔτε ἀρχὰς εὐγνώμονας οὔτε εὐτυχεῖς τελευτὰς ἔχοντες. καὶ γὰρ Ἀναξώ τινα Τροιζηνίαν ἁρπάσαι λέγεται, καὶ Σίνιν ἀποκτείνας καὶ Κερκύονα συγγενέσθαι βία ταῖς θυγατράσιν αὐτῶν· γῆμαι δὲ καὶ Περίβοιαν τὴν Αἴαντος μητέρα καὶ Φερέβοιαν αὖθις καὶ Ἰόπην τὴν Ἰφικλέους· καὶ διὰ τὸν Αἴγλης ἔρωτα τῆς Πανοπέως, ὥσπερ εἴρηται, τὴν Ἀριάδνης ἀπόλειψιν αἰτιῶνται μὴ καλὴν γενέσθαι μηδὲ πρέπουσαν· ἐπὶ πᾶσι δὲ τὴν Ἑλένης ἁρπαγὴν πολέμου μὲν ἐμπλῆσαι τὴν Ἀττικήν, αὐτῷ δὲ εἰς φυγὴν καὶ ὄλεθρον τελευτῆσαι· περὶ ὧν ὀλίγον ὕστερον εἰρήσεται.", "st": "Thes. 29.1"}, {"sp": "N", "t": "πολλῶν δὲ τότε τοῖς ἀρίστοις ἄθλων γενομένων Ἡρόδωρος μὲν οὐδενὸς οἴεται τὸν Θησέα μετασχεῖν, ἀλλὰ μόνοις Λαπίθαις τῆς κενταυρομαχίας· ἕτεροι δὲ καὶ μετὰ Ἰάσονος ἐν Κόλχοις γενέσθαι καὶ Μελεάγρῳ συνεξελεῖν τὸν κάπρον· καὶ διὰ τοῦτο παροιμίαν εἶναι τὴν οὐκ ἄνευ Θησέως· αὐτὸν μέντοι μηδενὸς συμμάχου δεηθέντα πολλοὺς καὶ καλοὺς ἄθλους κατεργάσασθαι, καὶ τὸν ἄλλος οὗτος Ἡρακλῆς λόγον ἐπ’ ἐκείνου κρατῆσαι. συνέπραξε δὲ καὶ Ἀδράστῳ τὴν ἀναίρεσιν τῶν ὑπὸ τῇ Καδμείᾳ πεσόντων, οὐχ ὡς Εὐριπίδης ἐποίησεν ἐν τραγῳδίᾳ, μάχῃ τῶν Θηβαίων κρατήσας, ἀλλὰ πείσας καὶ σπεισάμενος· οὕτω γὰρ οἱ πλεῖστοι λέγουσι· Φιλόχορος δὲ καὶ σπονδὰς περὶ νεκρῶν ἀναιρέσεως γενέσθαι πρώτας ἐκείνας. ὅτι δὲ Ἡρακλῆς πρῶτος ἀπέδωκε νεκροὺς τοῖς πολεμίοις, ἐν τοῖς περὶ Ἡρακλέους γέγραπται. ταφαὶ δὲ τῶν μὲν πολλῶν ἐν Ἐλευθεραῖς δείκνυνται, τῶν δὲ ἡγεμόνων περὶ Ἐλευσῖνα, καὶ τοῦτο Θησέως Ἀδράστῳ χαρισαμένου. καταμαρτυροῦσι δὲ τῶν Εὐριπίδου Ἱκετίδων οἱ Αἰσχύλου Ἐλευσίνιοι, ἐν οἷς καὶ ταῦτα λέγων ὁ Θησεὺς πεποίηται.", "st": "Thes. 29.3"}, {"sp": "N", "t": "τὴν δὲ πρὸς Πειρίθουν φιλίαν τοῦτον τὸν τρόπον αὐτῷ γενέσθαι λέγουσι. δόξαν εἶχεν ἐπὶ ῥώμῃ καὶ ἀνδρείᾳ μεγίστην· βουλόμενος οὖν ὁ Πειρίθους ἐξελέγξαι καὶ λαβεῖν διάπειραν, ἠλάσατο βοῦς ἐκ Μαραθῶνος αὐτοῦ, καὶ πυθόμενος διώκειν μετὰ τῶν ὅπλων ἐκεῖνον οὐκ ἔφυγεν, ἀλλ’ ἀναστρέψας ἀπήντησεν. ὡς δὲ εἶδεν ἅτερος τὸν ἕτερον καὶ τὸ κάλλος ἐθαύμασε καὶ τὴν τόλμαν ἠγάσθη, μάχης μὲν ἔσχοντο, Πειρίθους δὲ πρότερος τὴν δεξιὰν προτείνας ἐκέλευσεν αὐτὸν γενέσθαι δικαστὴν τὸν Θησέα τῆς βοηλασίας· ἑκὼν γὰρ ὑφέξειν ἣν ἂν ὁρίσῃ δίκην ἐκεῖνος· Θησεὺς δὲ καὶ τὴν δίκην ἀφῆκεν αὐτῷ καὶ προὐκαλεῖτο φίλον εἶναι καὶ σύμμαχον· ἐποιήσαντο δὲ τὴν φιλίαν ἔνορκον.", "st": "Thes. 30.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου γαμῶν ὁ Πειρίθους Δηϊδάμειαν, ἐδεήθη τοῦ Θησέως ἐλθεῖν καὶ τὴν χώραν ἱστορῆσαι καὶ συγγενέσθαι τοῖς Λαπίθαις. ἐτύγχανε δὲ καὶ τοὺς Κενταύρους κεκληκὼς ἐπὶ τὸ δεῖπνον. ὡς δὲ ἠσέλγαινον ὕβρει καὶ μεθύοντες οὐκ ἀπείχοντο τῶν γυναικῶν, ἐτράποντο πρὸς ἄμυναν οἱ Λαπίθαι· καὶ τοὺς μὲν ἔκτειναν αὐτῶν, τοὺς δὲ πολέμῳ κρατήσαντες ὕστερον ἐξέβαλον ἐκ τῆς χώρας, τοῦ Θησέως αὐτοῖς συμμαχομένου καὶ συμπολεμοῦντος. Ἡρόδωρος δὲ ταῦτα πραχθῆναί φησιν οὐχ οὕτως, ἀλλὰ τοῦ πολέμου συνεστῶτος ἤδη τὸν Θησέα βοηθοῦντα τοῖς Λαπίθαις παραγενέσθαι, καὶ τότε πρῶτον ὄψει γνωρίσαι τὸν Ἡρακλέα, ποιησάμενον ἔργον ἐντυχεῖν αὐτῷ περὶ Τραχῖνα πεπαυμένῳ πλάνης ἤδη καὶ ἄθλων· γενέσθαι δὲ μετὰ τιμῆς καὶ φιλοφροσύνης καὶ πολλῶν ἐπαίνων ἀμφοτέροις τὴν ἔντευξιν. οὐ μὴν ἀλλὰ μᾶλλον ἄν τις πρόσχοι τοῖς πολλάκις ἐντυχεῖν αὐτοὺς ἀλλήλοις ἱστοροῦσι· καὶ τὴν μύησιν Ἡρακλεῖ γενέσθαι Θησέως σπουδάσαντος καὶ τὸν πρὸ τῆς μυήσεως καθαρμὸν ὡς δεομένῳ διά τινας πράξεις ἀβουλήτους.", "st": "Thes. 30.3"}, {"sp": "N", "t": "ἤδη δὲ πεντήκοντα ἔτη γεγονώς, ὥς φησιν Ἑλλάνικος, ἔπραξε τὰ περὶ τὴν Ἑλένην, οὐ καθ’ ὥραν. ὅθεν ὡς δὴ μέγιστον ἐπανορθούμενοι τοῦτο τῶν ἐγκλημάτων, ἔνιοι λέγουσιν οὐκ αὐτὸν ἁρπάσαι τὴν Ἑλένην, ἀλλὰ Ἴδα καὶ Λυγκέως ἁρπασάντων παρακαταθήκην λαβόντα τηρεῖν καὶ μὴ προΐεσθαι τοῖς Διοσκούροις ἀπαιτοῦσιν· ἢ νὴ Δία Τυνδάρεω παραδόντος αὐτοῦ, φοβηθέντος Ἐναρσφόρον τὸν Ἱπποκόωντος ἔτι νηπίαν οὖσαν βιαζόμενον τὴν Ἑλένην λαβεῖν. τὰ δὲ εἰκότα καὶ πλείστους ἔχοντα μάρτυρας τοιαῦτά ἐστιν.", "st": "Thes. 31.1"}, {"sp": "N", "t": "ἦλθον μὲν εἰς Σπάρτην ἀμφότεροι καὶ τὴν κόρην ἐν ἱερῷ Ἀρτέμιδος Ὀρθίας χορεύουσαν ἁρπάσαντες ἔφυγον· τῶν δὲ πεμφθέντων ἐπὶ τὴν δίωξιν οὐ πορρωτέρω Τεγέας ἐπακολουθησάντων, ἐν ἀδείᾳ γενόμενοι καὶ διελθόντες τὴν Πελοπόννησον ἐποιήσαντο συνθήκας, τὸν μὲν λαχόντα κλήρῳ τὴν Ἑλένην ἔχειν γυναῖκα, συμπράττειν δὲ θατέρῳ γάμον ἄλλον. ἐπὶ ταύταις δὲ κληρουμένων ταῖς ὁμολογίαις ἔλαχε Θησεύς· καὶ παραλαβὼν τὴν παρθένον οὔπω γάμων ὥραν ἔχουσαν εἰς Ἀφίδνας ἐκόμισε· καὶ τὴν μητέρα καταστήσας μετ’ αὐτῆς Ἀφίδνῳ παρέδωκεν ὄντι φίλῳ, διακελευσάμενος φυλάττειν καὶ λανθάνειν τοὺς ἄλλους. αὐτὸς δὲ Πειρίθῳ τὴν ὑπουργίαν ἀποδιδούς, εἰς Ἤπειρον συναπεδήμησεν ἐπὶ τὴν Ἀϊδωνέως θυγατέρα τοῦ Μολοσσῶν βασιλέως, ὃς τῇ γυναικὶ Φερσεφόνην ὄνομα θέμενος, Κόρην δὲ τῇ θυγατρί, τῷ δὲ κυνὶ Κέρβερον, ἐκέλευε τούτῳ διαμάχεσθαι τοὺς μνωμένους τὴν παῖδα καὶ λαβεῖν τὸν κρατήσαντα. τοὺς μέντοι περὶ τὸν Πειρίθουν οὐ μνηστῆρας ἥκειν, ἀλλ’ ἁρπασομένους πυνθανόμενος συνέλαβε· καὶ τὸν μὲν Πειρίθουν εὐθὺς ἠφάνισε διὰ τοῦ κυνός, τὸν δὲ Θησέα καθείρξας ἐφύλαττεν.", "st": "Thes. 31.2"}, {"sp": "N", "t": "ἐν δὲ τῷ χρόνῳ τούτῳ Μενεσθεὺς ὁ Πετεὼ τοῦ Ὀρνέως τοῦ Ἐρεχθέως πρῶτος, ὥς φασιν, ἀνθρώπων ἐπιθέμενος τῷ δημαγωγεῖν καὶ πρὸς χάριν ὄχλῳ διαλέγεσθαι, τούς τε δυνατοὺς συνίστη καὶ παρώξυνε, πάλαι βαρυνομένους τὸν Θησέα καὶ νομίζοντας ἀρχὴν καὶ βασιλείαν ἀφῃρημένον ἑκάστου τῶν κατὰ δῆμον εὐπατριδῶν, εἰς ἓν ἄστυ συνείρξαντα πάντας ὑπηκόοις χρῆσθαι καὶ δούλοις, τούς τε πολλοὺς διετάραττε καὶ διέβαλλεν, ὡς ὄναρ ἐλευθερίας ὁρῶντας, ἔργῳ δὲ ἀπεστερημένους πατρίδων καὶ ἱερῶν, ὅπως ἀντὶ πολλῶν καὶ ἀγαθῶν καὶ γνησίων βασιλέων πρὸς ἕνα δεσπότην ἔπηλυν καὶ ξένον ἀποβλέπωσι. ταῦτα δὲ αὐτοῦ πραγματευομένου μεγάλην ῥοπὴν ὁ πόλεμος τῷ νεωτερισμῷ προσέθηκε, τῶν Τυνδαριδῶν ἐπελθόντων· οἱ δὲ καὶ ὅλως φασὶν ὑπὸ τούτου πεισθέντας ἐλθεῖν.", "st": "Thes. 32.1"}, {"sp": "N", "t": "τὸ μὲν οὖν πρῶτον οὐδὲν ἠδίκουν, ἀλλ’ ἀπῄτουν τὴν ἀδελφήν. ἀποκριναμένων δὲ τῶν ἐν ἄστει μήτε ἔχειν μήτε γινώσκειν ὅπου καταλέλειπται, πρὸς πόλεμον ἐτράποντο. φράζει δὲ αὐτοῖς Ἀκάδημος ᾐσθημένος ᾧ δή τινι τρόπῳ τὴν ἐν Ἀφίδναις κρύψιν αὐτῆς. ὅθεν ἐκείνῳ τε τιμαὶ ζῶντι παρὰ τῶν Τυνδαριδῶν ἐγένοντο, καὶ πολλάκις ὕστερον εἰς τὴν Ἀττικὴν ἐμβαλόντες Λακεδαιμόνιοι καὶ πᾶσαν ὁμοῦ τὴν χώραν τέμνοντες, τῆς Ἀκαδημείας ἀπείχοντο διὰ τὸν Ἀκάδημον. ὁ δὲ Δικαίαρχος Ἐχεδήμου φησὶ καὶ Μαράθου συστρατευσάντων τότε τοῖς Τυνδαρίδαις ἐξ Ἀρκαδίας, ἀφ’ οὗ μὲν Ἐχεδημίαν προσαγορευθῆναι τὴν νῦν Ἀκαδήμειαν, ἀφ’ οὗ δὲ Μαραθῶνα τὸν δῆμον, ἐπιδόντος ἑαυτὸν ἑκουσίως κατά τι λόγιον σφαγιάσασθαι πρὸ τῆς παρατάξεως.", "st": "Thes. 32.3"}, {"sp": "N", "t": "ἐλθόντες οὖν ἐπὶ τὰς Ἀφίδνας καὶ μάχῃ κρατήσαντες ἐξεῖλον τὸ χωρίον. ἐνταῦθά φασι καὶ Ἄλυκον πεσεῖν τὸν Σκείρωνος υἱόν, συστρατευόμενον τότε τοῖς Διοσκούροις, ἀφ’ οὗ καὶ τόπον τῆς Μεγαρικῆς Ἄλυκον καλεῖσθαι τοῦ σώματος ἐνταφέντος. Ἡρέας δ’ ὑπὸ Θησέως αὐτοῦ περὶ Ἀφίδνας ἀποθανεῖν τὸν Ἄλυκον ἱστόρηκε, καὶ μαρτύρια ταυτὶ τὰ ἔπη παρέχεται περὶ τοῦ Ἀλύκου·", "st": "Thes. 32.5"}, {"sp": "N", "t": "τὸν ἐν εὐρυχόρῳ ποτ’ Ἀφίδνῃ<br>μαρνάμενον Θησεὺς Ἑλένης ἕνεκ’ ἠϋκόμοιο κτεῖνεν.", "st": "Thes. 32.5b"}, {"sp": "N", "t": "Οὐ μὴν εἰκὸς αὐτοῦ Θησέως παρόντος ἁλῶναι τήν τε μητέρα καὶ τὰς Ἀφίδνας.", "st": "Thes. 32.5c"}, {"sp": "N", "t": "ἐχομένων δ’ οὖν τῶν Ἀφιδνῶν καὶ τῶν ἐν ἄστει δεδιότων, ἔπεισε τὸν δῆμον ὁ Μενεσθεὺς δέχεσθαι τῇ πόλει καὶ φιλοφρονεῖσθαι τοὺς Τυνδαρίδας, ὡς μόνῳ Θησεῖ βίας ὑπάρξαντι πολεμοῦντας, τῶν δὲ ἄλλων εὐεργέτας ὄντας ἀνθρώπων καὶ σωτῆρας. ἐμαρτύρει δὲ αὐτῷ καὶ τὰ παρ’ ἐκείνων· οὐδὲν γὰρ ἠξίωσαν ἁπάντων κρατοῦντες ἀλλ’ ἢ μυηθῆναι, μηδὲν ἧττον Ἡρακλέους τῇ πόλει προσήκοντες. καὶ τοῦτο οὖν ὑπῆρξεν αὐτοῖς, Ἀφίδνου ποιησαμένου παῖδας, ὡς Πύλιος Ἡρακλέα· καὶ τιμὰς ἰσοθέους ἔσχον, Ἄνακες προσαγορευθέντες, ἢ διὰ τὰς γενομένας ἀνοχὰς ἢ διὰ τὴν ἐπιμέλειαν καὶ κηδεμονίαν τοῦ μηδένα κακῶς παθεῖν στρατιᾶς τοσαύτης ἔνδον οὔσης· ἀνακῶς γὰρ ἔχειν τοὺς ἐπιμελομένους ἢ φυλάττοντας ὁτιοῦν· καὶ τοὺς βασιλεῖς ἴσως ἄνακτας διὰ τοῦτο καλοῦσιν. εἰσὶ δὲ οἱ λέγοντες διὰ τὴν τῶν ἀστέρων ἐπιφάνειαν Ἄνακας ὀνομάζεσθαι· τὸ γὰρ ἄνω τοὺς Ἀττικοὺς ἀνεκὰς ὀνομάζειν, καὶ ἀνέκαθεν τὸ ἄνωθεν.", "st": "Thes. 33.1"}, {"sp": "N", "t": "Αἴθραν δὲ τὴν Θησέως μητέρα γενομένην αἰχμάλωτον ἀπαχθῆναι λέγουσιν εἰς Λακεδαίμονα, κἀκεῖθεν εἰς Τροίαν μετὰ Ἑλένης· καὶ μαρτυρεῖν Ὅμηρον, ἕπεσθαι τῇ Ἑλένῃ φάμενον·", "st": "Thes. 34.1"}, {"sp": "N", "t": "Αἴθρην Πιτθῆος θύγατρα Κλυμένην τε βοῶπιν.", "st": "Thes. 34.1b"}, {"sp": "N", "t": "οἱ δὲ καὶ τοῦτο τὸ ἔπος διαβάλλουσι καὶ τὴν περὶ Μουνύχου μυθολογίαν, ὃν ἐκ Δημοφῶντος Λαοδίκης κρύφα τεκούσης ἐν Ἰλίῳ συνεκθρέψαι τὴν Αἴθραν λέγουσιν. ἴδιον δέ τινα καὶ παρηλλαγμένον ὅλως λόγον ὁ Ἴστρος ἐν τῇ τρισκαιδεκάτῃ τῶν Ἀττικῶν ἀναφέρει περὶ Αἴθρας, ὡς ἐνίων λεγόντων Ἀλέξανδρον μὲν τὸν Πάριν ἐν Θεσσαλίᾳ ὑπ’ Ἀχιλλέως καὶ Πατρόκλου μάχῃ κρατηθῆναι παρὰ τὸν Σπερχειόν, Ἕκτορα δὲ τὴν Τροιζηνίων πόλιν λαβόντα διαρπάσαι καὶ τὴν Αἴθραν ἀπάγειν ἐκεῖ καταλειφθεῖσαν. ἀλλὰ τοῦτο μὲν ἔχει πολλὴν ἀλογίαν.", "st": "Thes. 34.2"}, {"sp": "N", "t": "Ἀϊδωνέως δὲ τοῦ Μολοσσοῦ ξενίζοντος Ἡρακλέα καὶ τῶν περὶ τὸν Θησέα καὶ Πειρίθουν κατὰ τύχην μνησθέντος, ἅ τε πράξοντες ἦλθον καὶ ἃ φωραθέντες ἔπαθον, βαρέας ἤνεγκεν ὁ Ἡρακλῆς, τοῦ μὲν ἀπολωλότος ἀδόξως, τοῦ δὲ ἀπολλυμένου. καὶ περὶ Πειρίθου μὲν οὐδὲν ᾤετο ποιήσειν πλέον ἐγκαλῶν, τὸν δὲ Θησέα παρῃτεῖτο καὶ χάριν ἠξίου ταύτην αὐτῷ δοθῆναι. συγχωρήσαντος δὲ τοῦ Ἀϊδωνέως, λυθεὶς ὁ Θησεὺς ἐπανῆλθε μὲν εἰς τὰς Ἀθήνας, οὐδέπω παντάπασι τῶν φίλων αὐτοῦ κεκρατημένων, καὶ ὅσα ὑπῆρχε τεμένη πρότερον αὐτῷ τῆς πόλεως ἐξελούσης ἅπαντα καθιέρωσε τῷ Ἡρακλεῖ καὶ προσηγόρευσεν ἀντὶ Θησείων Ἡράκλεια, πλὴν τεσσάρων, ὡς Φιλόχορος ἱστόρηκεν. αὖθις δὲ βουλόμενος ὡς πρότερον ἄρχειν καὶ καθηγεῖσθαι τοῦ πολιτεύματος εἰς στάσεις ἐνέπεσε καὶ ταραχάς, οὓς μὲν ἀπέλιπε μισοῦντας αὐτὸν εὑρίσκων τὸ μὴ φοβεῖσθαι τῷ μισεῖν προσειληφότας, ἐν δὲ τῷ δήμῳ πολὺ τὸ διεφθαρμένον ὁρῶν καὶ θεραπεύεσθαι βουλόμενον ἀντὶ τοῦ ποιεῖν σιωπῇ τὸ προσταττόμενον. ἐπιχειρῶν οὖν βιάζεσθαι κατεδημαγωγεῖτο καὶ κατεστασιάζετο. καὶ τέλος ἀπογνοὺς τὰ πράγματα τοὺς μὲν παῖδας εἰς Εὔβοιαν ὑπεξέπεμψε πρὸς Ἐλεφήνορα τὸν Χαλκώδοντος, αὐτὸς δὲ Γαργηττοῖ κατὰ τῶν Ἀθηναίων ἀρὰς θέμενος, οὗ νῦν ἔστι τὸ καλούμενον Ἀρατήριον, εἰς Σκῦρον ἐξέπλευσεν, οὔσης αὐτῷ πρὸς τοὺς ἐκεῖ φιλίας, ὡς ᾤετο, καὶ χωρίων ἐν τῇ νήσῳ πατρῴων. ἐβασίλευε δὲ Λυκομήδης τότε τῶν Σκυρίων. πρὸς τοῦτον οὖν ἀφικόμενος ἐζήτει τοὺς ἀγροὺς ἀπολαβεῖν, ὡς αὐτόθι κατοικήσων· ἔνιοι δέ φασι παρακαλεῖν αὐτὸν βοηθεῖν ἐπὶ τοὺς Ἀθηναίους. ὁ δὲ Λυκομήδης, εἴτε δείσας τὴν δόξαν τοῦ ἀνδρός, εἴτε τῷ Μενεσθεῖ χαριζόμενος, ἐπὶ τὰ ἄκρα τῆς χώρας ἀναγαγὼν αὐτόν, ὡς ἐκεῖθεν ἐπιδείξων τοὺς ἀγρούς, ὦσε κατὰ τῶν πετρῶν καὶ διέφθειρεν. ἔνιοι δ’ ἀφ’ ἑαυτοῦ πεσεῖν φασι σφαλέντα, μετὰ δεῖπνον, ὥσπερ εἰώθει, περιπατοῦντα. καὶ παραυτίκα μὲν οὐδεὶς ἔσχεν αὐτοῦ λόγον οὐδένα τεθνηκότος, ἀλλὰ τῶν μὲν Ἀθηναίων ἐβασίλευσε Μενεσθεύς, οἱ δὲ παῖδες ἰδιωτεύοντες Ἐλεφήνορι συνεστράτευσαν εἰς Ἴλιον. ἐκεῖ δὲ Μενεσθέως ἀποθανόντος ἐπανελθόντες αὐτοὶ τὴν βασιλείαν ἀνεκομίσαντο. χρόνοις δ’ ὕστερον Ἀθηναίους ἄλλα τε παρέστησεν ὡς ἥρωα τιμᾶν Θησέα, καὶ τῶν ἐν Μαραθῶνι πρὸς Μήδους μαχομένων ἔδοξαν οὐκ ὀλίγοι φάσμα Θησέως ἐν ὅπλοις καθορᾶν πρὸ αὐτῶν ἐπὶ τοὺς βαρβάρους φερόμενον.", "st": "Thes. 35.1"}, {"sp": "N", "t": "μετὰ δὲ τὰ Μηδικὰ Φαίδωνος ἄρχοντος μαντευομένοις τοῖς Ἀθηναίοις ἀνεῖλεν ἡ Πυθία τὰ Θησέως ἀναλαβεῖν ὀστᾶ καὶ θεμένους ἐντίμως παρ’ αὑτοῖς φυλάττειν. ἦν δὲ καὶ λαβεῖν ἀπορία καὶ γνῶναι τὸν τάφον ἀμιξίᾳ καὶ χαλεπότητι τῶν ἐνοικούντων Δολόπων. οὐ μὴν ἀλλὰ Κίμων ἑλὼν τὴν νῆσον, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται, καὶ φιλοτιμούμενος ἐξανευρεῖν, ἀετοῦ τινα τόπον βουνοειδῆ κόπτοντος, ὥς φασι, τῷ στόματι καὶ διαστέλλοντος τοῖς ὄνυξι θείᾳ τινὶ τύχῃ συμφρονήσας ἀνέσκαψεν. εὑρέθη δὲ θήκη τε μεγάλου σώματος αἰχμή τε παρακειμένη χαλκῆ καὶ ξίφος. κομισθέντων δὲ τούτων ὑπὸ Κίμωνος ἐπὶ τῆς τριήρους, ἡσθέντες οἱ Ἀθηναῖοι πομπαῖς τε λαμπραῖς ἐδέξαντο καὶ θυσίαις ὥσπερ αὐτὸν ἐπανερχόμενον εἰς τὸ ἄστυ. καὶ κεῖται μὲν ἐν μέσῃ τῇ πόλει παρὰ τὸ νῦν γυμνάσιον, ἔστι δὲ φύξιμον οἰκέταις καὶ πᾶσι τοῖς ταπεινοτέροις καὶ δεδιόσι κρείττονας, ὡς καὶ τοῦ Θησέως προστατικοῦ τινος καὶ βοηθητικοῦ γενομένου καὶ προσδεχομένου φιλανθρώπως τὰς τῶν ταπεινοτέρων δεήσεις. θυσίαν δὲ ποιοῦσιν αὐτῷ τὴν μεγίστην ὀγδόῃ Πυανεψιῶνος, ἐν ᾗ μετὰ τῶν ἠϊθέων ἐκ Κρήτης ἐπανῆλθεν. οὐ μὴν ἀλλὰ καὶ ταῖς ἄλλαις ὀγδόαις τιμῶσιν αὐτόν, ἢ διὰ τὸ πρῶτον ἐκ Τροιζῆνος ἀφικέσθαι τῇ ὀγδόῃ τοῦ Ἑκατομβαιῶνος, ὡς ἱστόρηκε Διόδωρος ὁ περιηγητής, ἢ νομίζοντες ἑτέρου μᾶλλον ἐκείνῳ προσήκειν τὸν ἀριθμὸν τοῦτον ἐκ Ποσειδῶνος γεγονέναι λεγομένῳ. καὶ γὰρ Ποσειδῶνα ταῖς ὀγδόαις τιμῶσιν. ἡ γὰρ ὀγδοὰς κύβος ἀπ’ ἀρτίου πρῶτος οὖσα καὶ τοῦ πρώτου τετραγώνου διπλασία, τὸ μόνιμον καὶ δυσκίνητον οἰκεῖον ἔχει τῆς τοῦ θεοῦ δυνάμεως, ὃν ἀσφάλειον καὶ γαιήοχον προσονομάζομεν.", "st": "Thes. 36.1"}, {"sp": "HDR", "t": "Ῥωμύλος"}, {"sp": "N", "t": "τὸ μέγα τῆς Ῥώμης ὄνομα καὶ δόξῃ διὰ πάντων ἀνθρώπων κεχωρηκὸς ἀφ’ ὅτου καὶ δι’ ἣν αἰτίαν τῇ πόλει γέγονεν, οὐχ ὡμολόγηται παρὰ τοῖς συγγραφεῦσιν, ἀλλ’ οἱ μὲν Πελασγούς, ἐπὶ πλεῖστα τῆς οἰκουμένης πλανηθέντας ἀνθρώπων τε πλείστων κρατήσαντας, αὐτόθι κατοικῆσαι, καὶ διὰ τὴν ἐν τοῖς ὅπλοις ῥώμην οὕτως ὀνομάσαι τὴν πόλιν, οἱ δὲ Τροίας ἁλισκομένης διαφυγόντας ἐνίους καὶ πλοίων ἐπιτυχόντας ὑπὸ πνευμάτων τῇ Τυρρηνίᾳ προσπεσεῖν φερομένους, καὶ περὶ τὸν Θύμβριν ποταμὸν ὁρμίσασθαι· ταῖς δὲ γυναιξὶν αὐτῶν, ἀπορουμέναις ἤδη καὶ δυσανασχετούσαις πρὸς τὴν θάλασσαν, ὑποθέσθαι μίαν, ἣ καὶ γένει προὔχειν καὶ φρονεῖν ἐδόκει μάλιστα, Ῥώμην ὄνομα, καταπρῆσαι τὰ πλοῖα. πραχθέντος δὲ τούτου, πρῶτον μὲν ἀγανακτεῖν τοὺς ἄνδρας, ἔπειτα δι’ ἀνάγκην ἱδρυνθέντας περὶ τὸ Παλλάντιον, ὡς ὀλίγῳ χρόνῳ κρεῖττον ἐλπίδος ἔπραττον, ἀγαθῆς τε πειρώμενοι χώρας καὶ δεχομένων αὐτοὺς τῶν προσοίκων, ἄλλην τε τιμὴν ἀπονέμειν τῇ Ῥώμῃ καὶ τὴν πόλιν ἀπ’ αὐτῆς ὡς αἰτίας προσαγορεύειν. ἐξ ἐκείνου τε παραμένειν λέγουσι τὸ τοὺς συγγενεῖς τὰς γυναῖκας καὶ οἰκείους ἄνδρας ἀσπάζεσθαι τοῖς στόμασι· καὶ γὰρ ἐκείνας, ὅτε τὰ πλοῖα κατέπρησαν, οὕτως ἀσπάζεσθαι καὶ φιλοφρονεῖσθαι τοὺς ἄνδρας, δεομένας αὐτῶν καὶ παραιτουμένας τὴν ὀργήν.", "st": "Rom. 1.1"}, {"sp": "N", "t": "ἄλλοι δὲ Ῥώμην, Ἰταλοῦ θυγατέρα καὶ Λευκαρίας, (οἱ δὲ Τηλέφου τοῦ Ἡρακλέους), Αἰνείᾳ γαμηθεῖσαν, οἱ δ’ Ἀσκανίῳ τῷ Αἰνείου, λέγουσι τοὔνομα θέσθαι τῇ πόλει· οἱ δὲ Ῥωμανόν, Ὀδυσσέως παῖδα καὶ Κίρκης, οἰκίσαι τὴν πόλιν· οἱ δὲ Ῥῶμον ἐκ Τροίας ὑπὸ Διομήδους ἀποσταλέντα τὸν Ἠμαθίωνος, οἱ δὲ Ῥῶμιν Λατίνων τύραννον, ἐκβαλόντα Τυρρηνοὺς τοὺς εἰς Λυδίαν μὲν ἐκ Θετταλίας, ἐκ δὲ Λυδίας εἰς Ἰταλίαν παραγενομένους. οὐ μὴν οὐδ’ οἱ Ῥωμύλον τῷ δικαιοτάτῳ τῶν λόγων ἀποφαίνοντες ἐπώνυμον τῆς πόλεως ὁμολογοῦσι περὶ τοῦ γένους [αὐτοῦ]. οἱ μὲν γὰρ Αἰνείου καὶ Δεξιθέας τῆς Φόρβαντος υἱὸν ὄντα νήπιον εἰς Ἰταλίαν κομισθῆναι καὶ τὸν ἀδελφὸν αὐτοῦ Ῥῶμον· ἐν δὲ τῷ ποταμῷ πλημμύραντι τῶν ἄλλων σκαφῶν διαφθαρέντων, ἐν ᾧ δ’ ἦσαν οἱ παῖδες εἰς μαλακὴν ἀποκλινθέντος ὄχθην ἀτρέμα, σωθέντας ἀπροσδοκήτως ὄνομα θεῖναι Ῥώμην. οἱ δὲ Ῥώμην, θυγατέρα τῆς Τρωάδος ἐκείνης, Λατίνῳ τῷ Τηλεμάχου γαμηθεῖσαν τεκεῖν τὸν Ῥωμύλον· οἱ δ’ Αἰμυλίαν τὴν Αἰνείου καὶ Λαβινίας, Ἄρει συγγενομένην. οἱ δὲ μυθώδη παντάπασι περὶ τῆς γενέσεως διεξίασι.", "st": "Rom. 2.1"}, {"sp": "N", "t": "Ταρχετίῳ γάρ, Ἀλβανῶν βασιλεῖ παρανομωτάτῳ καὶ ὠμοτάτῳ, φάσμα δαιμόνιον οἴκοι γενέσθαι· φαλλὸν γὰρ ἐκ τῆς ἑστίας ἀνασχεῖν καὶ διαμένειν ἐπὶ πολλὰς ἡμέρας. εἶναι δὲ Τηθύος ἐν Τυρρηνίᾳ χρηστήριον, ἀφ’ οὗ κομισθῆναι τῷ Ταρχετίῳ χρησμόν, ὥστε συμμεῖξαι τῷ φάσματι παρθένον· ἔσεσθαι γὰρ ἐξ αὐτῆς παῖδα κλεινότατον, ἀρετῇ καὶ τύχη καὶ ῥώμῃ διαφέροντα. φράσαντος οὖν τὸ μάντευμα τοῦ Ταρχετίου μιᾷ τῶν θυγατέρων καὶ συγγενέσθαι τῷ φαλλῷ προστάξαντος, αὐτὴν μὲν ἀπαξιῶσαι, θεράπαιναν δ’ εἰσπέμψαι. τὸν δὲ Ταρχέτιον ὡς ἔγνω χαλεπῶς φέροντα συλλαβεῖν μὲν ἀμφοτέρας ἐπὶ θανάτῳ, τὴν δ’ Ἑστίαν ἰδόντα κατὰ τοὺς ὕπνους ἀπαγορεύουσαν αὐτῷ τὸν φόνον, ἱστόν τινα παρεγγυῆσαι ταῖς κόραις ὑφαίνειν δεδεμέναις, ὡς ὅταν ἐξυφήνωσι, τότε δοθησομένας πρὸς γάμον.", "st": "Rom. 2.4"}, {"sp": "N", "t": "ἐκείνας μὲν οὖν δι’ ἡμέρας ὑφαίνειν, ἑτέρας δὲ νύκτωρ τοῦ Ταρχετίου κελεύοντος ἀναλύειν τὸν ἱστόν. ἐκ δὲ τοῦ φαλλοῦ τῆς θεραπαινίδος τεκούσης δίδυμα, δοῦναί τινι Τερατίῳ τὸν Ταρχέτιον, ἀνελεῖν κελεύσαντα. τὸν δὲ θεῖναι φέροντα τοῦ ποταμοῦ πλησίον, εἶτα λύκαιναν μὲν ἐπιφοιτᾶν μαστὸν ἐνδιδοῦσαν, ὄρνιθας δὲ παντοδαποὺς ψωμίσματα κομίζοντας ἐντιθέναι τοῖς βρέφεσιν, ἄχρι οὗ βουκόλον ἰδόντα καὶ θαυμάσαντα τολμῆσαι προσελθεῖν καὶ ἀνελέσθαι τὰ παιδία. τοιαύτης δὲ τῆς σωτηρίας αὐτοῖς γενομένης, ἐκτραφέντας ἐπιθέσθαι τῷ Ταρχετίῳ καὶ κρατῆσαι. ταῦτα μὲν οὖν Προμαθίων τις, ἱστορίαν Ἰταλικὴν συντεταγμένος, εἴρηκε.", "st": "Rom. 2.6"}, {"sp": "N", "t": "τοῦ δὲ πίστιν ἔχοντος λόγου μάλιστα καὶ πλείστους μάρτυρας τὰ μὲν κυριώτατα πρῶτος εἰς τοὺς Ἕλληνας ἐξέδωκε Διοκλῆς Πεπαρήθιος, ᾧ καὶ Φάβιος ὁ Πίκτωρ ἐν τοῖς πλείστοις ἐπηκολούθηκε. γεγόνασι δὲ καὶ περὶ τούτων ἕτεραι διαφοραί· τύπῳ δ’ εἰπεῖν τοιοῦτός ἐστι. τῶν ἀπ’ Αἰνείου γεγονότων ἐν Ἄλβῃ βασιλέων εἰς ἀδελφοὺς δύο, Νομήτορα καὶ Ἀμούλιον, ἡ διαδοχὴ καθῆκεν. Ἀμουλίου δὲ νείμαντος τὰ πάντα δίχα, τῇ δὲ βασιλείᾳ τὰ χρήματα καὶ τὸν ἐκ Τροίας κομισθέντα χρυσὸν ἀντιθέντος, εἵλετο τὴν βασιλείαν ὁ Νομήτωρ. ἔχων οὖν ὁ Ἀμούλιος τὰ χρήματα καὶ πλέον ἀπ’ αὐτῶν δυνάμενος τοῦ Νομήτορος, τήν τε βασιλείαν ἀφείλετο ῥᾳδίως, καὶ φοβούμενος ἐκ τῆς θυγατρὸς αὐτοῦ γενέσθαι παῖδας, ἱέρειαν τῆς Ἑστίας ἀπέδειξεν, ἄγαμον καὶ παρθένον ἀεὶ βιωσομένην. ταύτην οἱ μὲν Ἰλίαν, οἱ δὲ Ῥέαν, οἱ δὲ Σιλουίαν ὀνομάζουσι. φωρᾶται δὲ μετ’ οὐ πολὺν χρόνον κυοῦσα παρὰ τὸν καθεστῶτα ταῖς Ἑστιάσι νόμον, καὶ τὸ μὲν ἀνήκεστα μὴ παθεῖν αὐτὴν ἡ τοῦ βασιλέως θυγάτηρ Ἀνθὼ παρῃτήσατο, δεηθεῖσα τοῦ πατρός, εἵρχθη δὲ καὶ δίαιταν εἶχεν ἀνεπίμεικτον, ὅπως μὴ λάθοι τεκοῦσα τὸν Ἀμούλιον. ἔτεκε δὲ δύο παῖδας ὑπερφυεῖς μεγέθει καὶ κάλλει. δι’ ὃ καὶ μᾶλλον ὁ Ἀμούλιος φοβηθείς, ἐκέλευσεν αὐτοὺς ὑπηρέτην λαβόντα ῥῖψαι. τοῦτον ἔνιοι Φαιστύλον ὀνομάζεσθαι λέγουσιν, οἱ δ’ οὐ τοῦτον, ἀλλὰ τὸν ἀνελόμενον. ἐνθέμενος οὖν εἰς σκάφην τὰ βρέφη, κατέβη μὲν ἐπὶ τὸν ποταμὸν ὡς ῥίψων, ἰδὼν δὲ κατιόντα πολλῷ ῥεύματι καὶ τραχυνόμενον, ἔδεισε προσελθεῖν, ἐγγὺς δὲ τῆς ὄχθης καταθεὶς ἀπηλλάσσετο. τοῦ δὲ ποταμοῦ κατακλύζοντος ἡ πλημμύρα τὴν σκάφην ὑπολαβοῦσα καὶ μετεωρίσασα πρᾴως κατήνεγκεν εἰς χωρίον ἐπιεικῶς μαλθακόν, ὃ νῦν Κερμαλὸν καλοῦσι, πάλαι δὲ Γερμανόν, ὡς ἔοικεν ὅτι καὶ τοὺς ἀδελφοὺς γερμανοὺς ὀνομάζουσιν.", "st": "Rom. 3.1"}, {"sp": "N", "t": "ἦν δὲ πλησίον ἐρινεός, ὃν Ῥωμινάλιον ἐκάλουν, ἢ διὰ τὸν Ῥωμύλον ὡς οἱ πολλοὶ νομίζουσιν, ἢ διὰ τὸ τὰ μηρυκώμενα τῶν θρεμμάτων ἐκεῖ διὰ τὴν σκιὰν ἐνδιάζειν, ἢ μάλιστα διὰ τὸν τῶν βρεφῶν θηλασμόν, ὅτι τήν τε θηλὴν ῥοῦμαν ὠνόμαζον οἱ παλαιοί, καὶ θεόν τινα τῆς ἐκτροφῆς τῶν νηπίων ἐπιμελεῖσθαι δοκοῦσαν ὀνομάζουσι Ῥουμῖναν, καὶ θύουσιν αὐτῇ νηφάλια, καὶ γάλα τοῖς ἱεροῖς ἐπισπένδουσιν. ἐνταῦθα δὴ τοῖς βρέφεσι κειμένοις τήν τε λύκαιναν ἱστοροῦσι θηλαζομένην καὶ δρυοκολάπτην τινὰ παρεῖναι συνεκτρέφοντα καὶ φυλάττοντα. νομίζεται δ’ Ἄρεως ἱερὰ τὰ ζῷα, τὸν δὲ δρυοκολάπτην καὶ διαφερόντως Λατῖνοι σέβονται καὶ τιμῶσιν· ὅθεν οὐχ ἥκιστα πίστιν ἔσχεν ἡ τεκοῦσα τὰ βρέφη τεκεῖν ἐξ Ἄρεως φάσκουσα. καίτοι τοῦτο παθεῖν αὐτὴν ἐξαπατηθεῖσαν λέγουσιν, ὑπὸ τοῦ Ἀμουλίου διαπαρθενευθεῖσαν, ἐν ὅπλοις ἐπιφανέντος αὐτῇ καὶ συναρπάσαντος.", "st": "Rom. 4.1"}, {"sp": "N", "t": "οἱ δὲ τοὔνομα τῆς τροφοῦ δι’ ἀμφιβολίαν ἐπὶ τὸ μυθῶδες ἐκτροπὴν τῇ φήμῃ παρασχεῖν· λούπας γὰρ ἐκάλουν οἱ Λατῖνοι τῶν τε θηρίων τὰς λυκαίνας καὶ τῶν γυναικῶν τὰς ἑταιρούσας· εἶναι δὲ τοιαύτην τὴν Φαιστύλου γυναῖκα τοῦ τὰ βρέφη θρέψαντος, Ἄκκαν Λαρεντίαν ὄνομα. ταύτῃ δὲ καὶ θύουσι Ῥωμαῖοι, καὶ χοὰς ἐπιφέρει τοῦ Ἀπριλίου μηνὸς αὐτῇ ὁ τοῦ Ἄρεως ἱερεύς, καὶ Λαρενταλίαν καλοῦσι τὴν ἑορτήν.", "st": "Rom. 4.3"}, {"sp": "N", "t": "ἑτέραν δὲ τιμῶσι Λαρεντίαν ἐξ αἰτίας τοιαύτης. ὁ νεωκόρος τοῦ Ἡρακλέους ἀλύων ὡς ἔοικεν ὑπὸ σχολῆς, προὔθετο πρὸς τὸν θεὸν διακυβεύειν, ὑπειπὼν ὅτι νικήσας μὲν αὐτὸς ἕξει τι παρὰ τοῦ θεοῦ χρηστόν, ἡττηθεὶς δὲ τῷ θεῷ τράπεζαν ἄφθονον παρέξει καὶ γυναῖκα καλὴν συναναπαυσομένην. ἐπὶ τούτοις τὰς μὲν ὑπὲρ τοῦ θεοῦ θείς, τὰς δ’ ὑπὲρ αὑτοῦ ψήφους, ἀνεφάνη νικώμενος. εὐσυνθετεῖν δὲ βουλόμενος καὶ δικαιῶν ἐμμένειν τοῖς ὁρισθεῖσι, δεῖπνόν τε τῷ θεῷ παρεσκεύασε, καὶ τὴν Λαρεντίαν οὖσαν ὡραίαν, οὔπω δ’ ἐπιφανῆ μισθωσάμενος, εἱστίασεν ἐν τῷ ἱερῷ κλίνην ὑποστορέσας, καὶ μετὰ τὸ δεῖπνον συνεῖρξεν, ὡς δὴ τοῦ θεοῦ ἕξοντος αὐτήν. καὶ μέντοι καὶ τὸν θεὸν ἐντυχεῖν λέγεται τῇ γυναικί, καὶ κελεῦσαι βαδίζειν ἕωθεν ἐπὶ τὴν ἀγορὰν καὶ τὸν ἀπαντήσαντα πρῶτον ἀσπασαμένην ποιεῖσθαι φίλον. ἀπήντησεν οὖν αὐτῇ τῶν πολιτῶν ἀνὴρ ἡλικίᾳ τε προήκων καὶ συνειλοχὼς οὐσίαν ἱκανήν, ἄπαις δὲ καὶ βεβιωκὼς ἄνευ γυναικός, ὄνομα Ταρρούτιος. οὗτος ἔγνω τὴν Λαρεντίαν καὶ ἠγάπησε, καὶ τελευτῶν ἀπέλιπε κληρονόμον ἐπὶ πολλοῖς καὶ καλοῖς κτήμασιν, ὧν ἐκείνη τὰ πλεῖστα τῷ δήμῳ κατὰ διαθήκας ἔδωκε. λέγεται δ’ αὐτὴν ἔνδοξον οὖσαν ἤδη καὶ θεοφιλῆ νομιζομένην ἀφανῆ γενέσθαι περὶ τοῦτον τὸν τόπον, ἐν ᾧ καὶ τὴν προτέραν ἐκείνην Λαρεντίαν κεῖσθαι. καλεῖται δὲ νῦν ὁ τόπος Βήλαβρον, ὅτι τοῦ ποταμοῦ πολλάκις ὑπερχεομένου διεπεραιοῦντο πορθμείοις κατὰ τοῦτο τὸ χωρίον εἰς ἀγοράν· τὴν δὲ πορθμείαν βηλατούραν καλοῦσιν. ἔνιοι δὲ λέγουσι τὴν εἰς τὸν ἱππόδρομον φέρουσαν ἐξ ἀγορᾶς πάροδον ἱστίοις καταπεταννύναι τοὺς τὴν θέαν παρέχοντας, ἐντεῦθεν ἀρχομένους· ῥωμαϊστὶ δὲ τὸ ἱστίον βῆλον ὀνομάζουσι. διὰ ταῦτα μὲν ἔχει τιμὰς ἡ δευτέρα Λαρεντία παρὰ Ῥωμαίοις.", "st": "Rom. 5.1"}, {"sp": "N", "t": "τὰ δὲ βρέφη Φαιστύλος Ἀμουλίου συφορβὸς ἀνείλετο λαθὼν ἅπαντας, ὡς δ’ ἔνιοί φασι τῶν εἰκότων ἐχόμενοι μᾶλλον, εἰδότος τοῦ Νομήτορος καὶ συγχορηγοῦντος τροφὰς κρύφα τοῖς τρέφουσι. καὶ γράμματα λέγονται καὶ τἆλλα μανθάνειν οἱ παῖδες εἰς Γαβίους κομισθέντες, ὅσα χρὴ τοὺς εὖ γεγονότας. κληθῆναι δὲ καὶ τούτους ἀπὸ τῆς θηλῆς ἱστοροῦσι Ῥωμύλον καὶ Ῥέμον, ὅτι θηλάζοντες ὤφθησαν τὸ θηρίον. ἡ μὲν οὖν ἐν τοῖς σώμασιν εὐγένεια καὶ νηπίων ὄντων εὐθὺς ἐξέφαινε μεγέθει καὶ ἰδέᾳ τὴν φύσιν, αὐξόμενοι δὲ θυμοειδεῖς ἦσαν ἀμφότεροι καὶ ἀνδρώδεις καὶ φρόνημα πρὸς τὰ φαινόμενα δεινὰ καὶ τόλμαν ὅλως ἀνέκπληκτον ἔχοντες· ὁ δὲ Ῥωμύλος γνώμῃ τε χρῆσθαι μᾶλλον ἐδόκει καὶ πολιτικὴν ἔχειν σύνεσιν, ἐν ταῖς περὶ νομὰς καὶ κυνηγίας πρὸς τοὺς γειτνιῶντας ἐπιμειξίαις πολλὴν ἑαυτοῦ παρέχων κατανόησιν ἡγεμονικοῦ μᾶλλον ἢ πειθαρχικοῦ φύσει γεγονότος. διὸ τοῖς μὲν ὁμοδούλοις ἢ ταπεινοτέροις προσφιλεῖς ἦσαν, ἐπιστάτας δὲ καὶ διόπους βασιλικοὺς καὶ ἀγελάρχας ὡς μηδὲν αὐτῶν ἀρετῇ διαφέροντας ὑπερφρονοῦντες, οὔτ’ ἀπειλῆς ἐφρόντιζον οὔτ’ ὀργῆς. ἐχρῶντο δὲ διαίταις καὶ διατριβαῖς ἐλευθερίοις, οὐ τὴν σχολὴν ἐλευθέριον ἡγούμενοι καὶ τὴν ἀπονίαν, ἀλλὰ γυμνάσια καὶ θήρας καὶ δρόμους καὶ τὸ λῃστὰς ἀλέξασθαι καὶ κλῶπας ἑλεῖν καὶ βίας ἐξελέσθαι τοὺς ἀδικουμένους. ἦσαν δὴ διὰ ταῦτα περιβόητοι.", "st": "Rom. 6.1"}, {"sp": "N", "t": "γενομένης δέ τινος πρὸς τοὺς Νομήτορος βουκόλους τοῖς Ἀμουλίου διαφορᾶς καὶ βοσκημάτων ἐλάσεως, οὐκ ἀνασχόμενοι συγκόπτουσι μὲν αὐτοὺς καὶ τρέπονται, ἀποτέμνονται δὲ τῆς ἀγέλης συχνήν. ἀγανακτοῦντος δὲ τοῦ Νομήτορος ὠλιγώρουν, συνῆγον δὲ καὶ προσεδέχοντο πολλοὺς μὲν ἀπόρους, πολλοὺς δὲ δούλους, θράσους ἀποστατικοῦ καὶ φρονήματος ἀρχὰς ἐνδιδόντες. τοῦ δὲ Ῥωμύλου πρός τινα θυσίαν ἀποτραπομένου (καὶ γὰρ ἦν φιλοθύτης καὶ μαντικός), οἱ τοῦ Νομήτορος βοτῆρες τῷ Ῥέμῳ μετ’ ὀλίγων βαδίζοντι προστυχόντες ἐμάχοντο, καὶ γενομένων πληγῶν καὶ τραυμάτων ἐν ἀμφοτέροις, ἐκράτησαν οἱ τοῦ Νομήτορος καὶ συνέλαβον ζῶντα τὸν Ῥέμον. ἀναχθέντος οὖν αὐτοῦ πρὸς τὸν Νομήτορα καὶ κατηγορηθέντος, αὐτὸς μὲν οὐκ ἐκόλασε, χαλεπὸν ὄντα δεδιὼς τὸν ἀδελφόν, ἐλθὼν δὲ πρὸς ἐκεῖνον ἐδεῖτο τυχεῖν δίκης, ἀδελφὸς ὢν καὶ καθυβρισμένος ὑπ’ οἰκετῶν ἐκείνου βασιλέως ὄντος. συναγανακτούντων δὲ τῶν ἐν Ἄλβῃ καὶ δεινὰ πάσχειν οἰομένων τὸν ἄνδρα παρ’ ἀξίαν, κινηθεὶς ὁ Ἀμούλιος αὐτῷ παραδίδωσι τῷ Νομήτορι τὸν Ῥέμον, ὅ τι βούλοιτο χρήσασθαι.", "st": "Rom. 7.1"}, {"sp": "N", "t": "παραλαβὼν δ’ ἐκεῖνος, ὡς ἧκεν οἴκαδε, θαυμάζων μὲν ἀπὸ τοῦ σώματος τὸν νεανίσκον, ὑπερφέροντα μεγέθει καὶ ῥώμῃ πάντας, ἐνορῶν δὲ τῷ προσώπῳ τὸ θαρραλέον καὶ ἰταμὸν τῆς ψυχῆς ἀδούλωτον καὶ ἀπαθὲς ὑπὸ τῶν παρόντων, ἔργα δ’ αὐτοῦ καὶ πράξεις ὅμοια τοῖς βλεπομένοις ἀκούων, τὸ δὲ μέγιστον ὡς ἔοικε θεοῦ συμπαρόντος καὶ συνεπευθύνοντος ἀρχὰς μεγάλων πραγμάτων, ἁπτόμενος ὑπονοίᾳ καὶ τύχῃ τῆς ἀληθείας, ἀνέκρινεν ὅστις εἴη καὶ ὅπως γένοιτο, φωνῇ τε πρᾳείᾳ καὶ φιλανθρώπῳ βλέμματι πίστιν αὐτῷ μετ’ ἐλπίδος ἐνδιδούς. ὁ δὲ θαρρῶν ἔλεγεν· ἀλλ’ οὐδὲν ἀποκρύψομαί σε· καὶ γὰρ εἶναι δοκεῖς Ἀμουλίου βασιλικώτερος. ἀκούεις γὰρ καὶ ἀνακρίνεις πρὶν ἢ κολάζειν· ὁ δ’ ἀκρίτους ἐκδίδωσι. πρότερον μὲν ἑαυτοὺς οἰκετῶν βασιλέως Φαιστύλου καὶ Λαρεντίας ἠπιστάμεθα παῖδας (ἐσμὲν δὲ δίδυμοι), γενόμενοι δ’ ἐν αἰτίᾳ πρὸς σὲ καὶ διαβολαῖς καὶ τοῖς περὶ ψυχῆς ἀγῶσιν, ἀκούομεν μεγάλα περὶ ἑαυτῶν· εἰ δὲ πιστά, κρινεῖν ἔοικε νῦν ὁ κίνδυνος. γοναὶ μὲν γὰρ ἡμῶν ἀπόρρητοι λέγονται, τροφαὶ δὲ καὶ τιθηνήσεις ἀτοπώτεραι νεογνῶν, οἷς ἐρρίφημεν οἰωνοῖς καὶ θηρίοις, ὑπὸ τούτων τρεφόμενοι, μαστῷ λυκαίνης καὶ δρυοκολάπτου ψωμίσμασιν, ἐν σκάφῃ τινὶ κείμενοι παρὰ τὸν μέγαν ποταμόν. ἔστι δ’ ἡ σκάφη καὶ σῴζεται, χαλκοῖς ὑποζώσμασι γραμμάτων ἀμυδρῶν ἐγκεχαραγμένων, ἃ γένοιτ’ ἂν ὕστερον ἴσως ἀνωφελῆ γνωρίσματα τοῖς τοκεῦσιν ἡμῶν ἀπολομένων.", "st": "Rom. 7.4"}, {"sp": "N", "t": "ὁ μὲν οὖν Νομήτωρ ἔκ τε τῶν λόγων τούτων καὶ πρὸς τὴν ὄψιν εἰκάζων τὸν χρόνον, οὐκ ἔφευγε τὴν ἐλπίδα σαίνουσαν, ἀλλ’ ἐφρόντιζεν ὅπως τῇ θυγατρὶ περὶ τούτων κρύφα συγγενόμενος φράσειεν· ἐφρουρεῖτο γὰρ ἔτι καρτερῶς.", "st": "Rom. 7.7"}, {"sp": "N", "t": "ὁ δὲ Φαιστύλος ἀκούσας τήν τε σύλληψιν τοῦ Ῥέμου καὶ τὴν παράδοσιν, τὸν μὲν Ῥωμύλον ἠξίου βοηθεῖν, τότε σαφῶς διδάξας περὶ τῆς γενέσεως· πρότερον δ’ ὑπῃνίττετο καὶ παρεδήλου τοσοῦτον ὅσον προσέχοντας μὴ μικρὸν φρονεῖν· αὐτὸς δὲ τὴν σκάφην κομίζων ἐχώρει πρὸς τὸν Νομήτορα, σπουδῆς καὶ δέους μεστὸς ὢν διὰ τὸν καιρόν. ὑποψίαν οὖν τοῖς περὶ τὰς πύλας φρουροῖς τοῦ βασιλέως παρέχων, καὶ ὑφορώμενος ὑπ’ αὐτῶν καὶ ταραττόμενος πρὸς τὰς ἀνακρίσεις, οὐκ ἔλαθε τὴν σκάφην τῷ χλαμυδίῳ περικαλύπτων. ἦν δέ τις ἐν αὐτοῖς ἀπὸ τύχης τῶν τὰ παιδάρια ῥῖψαι λαβόντων καὶ γεγονότων περὶ τὴν ἔκθεσιν. οὗτος ἰδὼν τὴν σκάφην τότε καὶ γνωρίσας τῇ κατασκευῇ καὶ τοῖς γράμμασιν, ἔτυχεν ὑπονοίᾳ τοῦ ὄντος καὶ οὐ παρημέλησεν, ἀλλὰ φράσας τὸ πρᾶγμα τῷ βασιλεῖ κατέστησεν εἰς ἔλεγχον. ἐν δὲ πολλαῖς καὶ μεγάλαις ἀνάγκαις ὁ Φαιστύλος οὔτ’ ἀήττητον ἑαυτὸν διεφύλαξεν, οὔτε παντάπασιν ἐκβιασθείς, σῴζεσθαι μὲν ὡμολόγησε τοὺς παῖδας, εἶναι δ’ ἄπωθεν τῆς Ἄλβης ἔφη νέμοντας· αὐτὸς δὲ τοῦτο πρὸς τὴν Ἰλίαν φέρων βαδίζειν, πολλάκις ἰδεῖν καὶ θιγεῖν ἐπ’ ἐλπίδι βεβαιοτέρᾳ τῶν τέκνων ποθήσασαν.", "st": "Rom. 8.1"}, {"sp": "N", "t": "ὅπερ οὖν οἱ ταραττόμενοι καὶ μετὰ δέους ἢ πρὸς ὀργὴν πράττοντες ὁτιοῦν ἐπιεικῶς πάσχουσι, συνέπεσε παθεῖν τὸν Ἀμούλιον. ἄνδρα γὰρ ἄλλῃ τε χρηστὸν καὶ τοῦ Νομήτορος φίλον ὑπὸ σπουδῆς ἔπεμψε, διαπυθέσθαι τοῦ Νομήτορος κελεύσας, εἴ τις ἥκοι λόγος εἰς αὐτὸν ὑπὲρ τῶν παίδων ὡς περιγενομένων. ἀφικόμενος οὖν ὁ ἄνθρωπος καὶ θεασάμενος ὅσον οὔπω τὸν Ῥέμον ἐν περιβολαῖς καὶ φιλοφροσύναις τοῦ Νομήτορος, τήν τε πίστιν ἰσχυρὰν ἐποίησε τῆς ἐλπίδος, καὶ παρεκελεύσατο τῶν πραγμάτων ὀξέως ἀντιλαμβάνεσθαι, καὶ συνῆν αὐτοῖς ἤδη καὶ συνέπραττεν. ὁ δὲ καιρὸς οὐδὲ βουλομένοις ὀκνεῖν παρεῖχεν. ὁ γὰρ Ῥωμύλος ἐγγὺς ἦν ἤδη, καὶ πρὸς αὐτὸν ἐξέθεον οὐκ ὀλίγοι τῶν πολιτῶν μίσει καὶ φόβῳ τοῦ Ἀμουλίου. πολλὴν δὲ καὶ σὺν αὑτῷ δύναμιν ἦγε συλλελοχισμένην εἰς ἑκατοστύας· ἑκάστης δ’ ἀνὴρ ἀφηγεῖτο χόρτου καὶ ὕλης ἀγκαλίδα κοντῷ περικειμένην ἀνέχων· μανίπλα ταύτας Λατῖνοι καλοῦσιν· ἀπ’ ἐκείνου δὲ καὶ νῦν ἐν τοῖς στρατεύμασι τούτους μανιπλαρίους ὀνομάζουσιν. ἅμα δὲ τοῦ μὲν Ῥέμου τοὺς ἐντὸς ἀφιστάντος, τοῦ δὲ Ῥωμύλου προσάγοντος ἔξωθεν, οὔτε πράξας οὐδὲν ὁ τύραννος οὔτε βουλεύσας σωτήριον ἑαυτῷ διὰ τὸ ἀπορεῖν καὶ ταράττεσθαι, καταληφθεὶς ἀπέθανεν.", "st": "Rom. 8.4"}, {"sp": "N", "t": "ὧν τὰ πλεῖστα καὶ Φαβίου λέγοντος καὶ τοῦ Πεπαρηθίου Διοκλέους, ὃς δοκεῖ πρῶτος ἐκδοῦναι Ῥώμης κτίσιν, ὕποπτον μὲν ἐνίοις ἐστὶ τὸ δραματικὸν καὶ πλασματῶδες, οὐ δεῖ δ’ ἀπιστεῖν τὴν τύχην ὁρῶντας οἵων ποιημάτων δημιουργός ἐστι, καὶ τὰ Ῥωμαίων πράγματα λογιζομένους, ὡς οὐκ ἂν ἐνταῦθα προὔβη δυνάμεως, μὴ θείαν τιν’ ἀρχὴν λαβόντα καὶ μηδὲν μέγα μηδὲ παράδοξον ἔχουσαν.", "st": "Rom. 8.7"}, {"sp": "N", "t": "Ἀμουλίου δ’ ἀποθανόντος καὶ τῶν πραγμάτων καταστάντων, Ἄλβην μὲν οὔτ’ οἰκεῖν μὴ ἄρχοντες οὔτ’ ἄρχειν ἐβούλοντο τοῦ μητροπάτορος ζῶντος, ἀποδόντες δὲ τὴν ἡγεμονίαν ἐκείνῳ καὶ τῇ μητρὶ τιμὰς πρεπούσας, ἔγνωσαν οἰκεῖν καθ’ ἑαυτούς, πόλιν ἐν οἷς χωρίοις ἐξ ἀρχῆς ἐνετράφησαν κτίσαντες· αὕτη γὰρ εὐπρεπεστάτη τῶν αἰτιῶν ἐστιν. ἦν δ’ ἴσως ἀναγκαῖον, οἰκετῶν καὶ ἀποστατῶν πολλῶν ἠθροισμένων πρὸς αὐτούς, ἢ καταλυθῆναι παντάπασι τούτων διασπαρέντων, ἢ συνοικεῖν ἰδίᾳ μετ’ αὐτῶν. ὅτι γὰρ οὐκ ἠξίουν οἱ τὴν Ἄλβην οἰκοῦντες ἀναμειγνύναι τοὺς ἀποστάτας ἑαυτοῖς οὐδὲ προσδέχεσθαι πολίτας, ἐδήλωσε πρῶτον μὲν τὸ περὶ τὰς γυναῖκας ἔργον, οὐχ ὕβρει τολμηθὲν ἀλλὰ δι’ ἀνάγκην, ἑκουσίων ἀπορίᾳ γάμων· ἐτίμησαν γὰρ αὐτὰς ἁρπάσαντες περιττῶς. ἔπειτα τῆς πόλεως τὴν πρώτην ἵδρυσιν λαμβανούσης, ἱερόν τι φύξιμον τοῖς ἀφισταμένοις κατασκευάσαντες, ὃ Θεοῦ Ἀσυλαίου προσηγόρευον, ἐδέχοντο πάντας, οὔτε δεσπόταις δοῦλον οὔτε θῆτα χρήσταις οὔτ’ ἄρχουσιν ἀνδροφόνον ἐκδιδόντες, ἀλλὰ μαντεύματι πυθοχρήστῳ πᾶσι βεβαιοῦν τὴν ἀσυλίαν φάσκοντες, ὥστε πληθῦσαι ταχὺ τὴν πόλιν, ἐπεὶ τάς γε πρώτας ἑστίας λέγουσι τῶν χιλίων μὴ πλείονας γενέσθαι. ταῦτα μὲν οὖν ὕστερον.", "st": "Rom. 9.1"}, {"sp": "N", "t": "Ὁρμήσασι δὲ πρὸς τὸν συνοικισμὸν αὐτοῖς εὐθὺς ἦν διαφορὰ περὶ τοῦ τόπου. Ῥωμύλος μὲν οὖν τὴν καλουμένην Ῥώμην κουαδράταν, ὅπερ ἐστὶ τετράγωνον, ἔκτισε, καὶ ἐκεῖνον ἐβούλετο πολίζειν τὸν τόπον, Ῥέμος δὲ χωρίον τι τοῦ Ἀβεντίνου καρτερόν, ὃ δι’ ἐκεῖνον μὲν ὠνομάσθη Ῥεμωρία, νῦν δὲ Ῥιγνάριον καλεῖται. συνθεμένων δὲ τὴν ἔριν ὄρνισιν αἰσίοις βραβεῦσαι, καὶ καθεζομένων χωρίς, ἕξ φασι τῷ Ῥέμῳ, διπλασίους δὲ τῷ Ῥωμύλῳ προφανῆναι γῦπας· οἱ δὲ τὸν μὲν Ῥέμον ἀληθῶς ἰδεῖν, ψεύσασθαι δὲ τὸν Ῥωμύλον, ἐλθόντος δὲ τοῦ Ῥέμου, τότε τοὺς δώδεκα τῷ Ῥωμύλῳ φανῆναι· διὸ καὶ νῦν μάλιστα χρῆσθαι γυψὶ Ῥωμαίους οἰωνιζομένους.", "st": "Rom. 9.4"}, {"sp": "N", "t": "Ἡρόδωρος δ’ ὁ Ποντικὸς ἱστορεῖ καὶ τὸν Ἡρακλέα χαίρειν γυπὸς ἐπὶ πράξει φανέντος. ἔστι μὲν γὰρ ἀβλαβέστατον ζῴων ἁπάντων, μηδὲν ὧν σπείρουσιν ἢ φυτεύουσιν ἢ νέμουσιν ἄνθρωποι σινόμενον, τρέφεται δ’ ἀπὸ νεκρῶν σωμάτων, ἀποκτίννυσι δ’ οὐδὲν οὐδὲ λυμαίνεται ψυχὴν ἔχον, πτηνοῖς δὲ διὰ συγγένειαν οὐδὲ νεκροῖς πρόσεισιν. ἀετοὶ δὲ καὶ γλαῦκες καὶ ἱέρακες ζῶντα κόπτουσι τὰ ὁμόφυλα καὶ φονεύουσι· καίτοι κατ’ Αἰσχύλον", "st": "Rom. 9.6"}, {"sp": "N", "t": "ὄρνιθος ὄρνις πῶς ἂν ἁγνεύοι φαγών;", "st": "Rom. 9.6b"}, {"sp": "N", "t": "ἔτι τἆλλα μὲν ἐν ὀφθαλμοῖς ὡς ἔπος εἰπεῖν ἀναστρέφεται καὶ παρέχει διὰ παντὸς αἴσθησιν ἑαυτῶν, ὁ δὲ γὺψ σπάνιόν ἐστι θέαμα, καὶ νεοσσοῖς γυπὸς οὐ ῥᾳδίως ἴσμεν ἐντετυχηκότες, ἀλλὰ καὶ παρέσχεν ἐνίοις ἄτοπον ὑπόνοιαν, ἔξωθεν αὐτοὺς ἀφ’ ἑτέρας τινὸς γῆς καταίρειν ἐνταῦθα, τὸ σπάνιον καὶ μὴ συνεχές, οἷον οἱ μάντεις ἀξιοῦσιν εἶναι τὸ μὴ κατὰ φύσιν μηδ’ ἀφ’ αὑτοῦ, πομπῇ δὲ θείᾳ φαινόμενον.", "st": "Rom. 9.7"}, {"sp": "N", "t": "ἐπεὶ δ’ ἔγνω τὴν ἀπάτην ὁ Ῥέμος, ἐχαλέπαινε, καὶ τοῦ Ῥωμύλου τάφρον ὀρύττοντος ᾗ τὸ τεῖχος ἔμελλε κυκλοῦσθαι, τὰ μὲν ἐχλεύαζε τῶν ἔργων, τοῖς δ’ ἐμποδὼν ἐγένετο. τέλος δὲ διαλλόμενον αὐτὸν οἱ μὲν αὐτοῦ Ῥωμύλου πατάξαντος, οἱ δὲ τῶν ἑταίρων τινὸς Κέλερος, ἐνταῦθα πεσεῖν λέγουσιν. ἔπεσε δὲ καὶ Φαιστύλος ἐν τῇ μάχῃ καὶ Πλειστῖνος, ὃν ἀδελφὸν ὄντα Φαιστύλου συνεκθρέψαι τοὺς περὶ τὸν Ῥωμύλον ἱστοροῦσιν. ὁ μὲν οὖν Κέλερ εἰς Τυρρηνίαν μετέστη, καὶ ἀπ’ ἐκείνου τοὺς ταχεῖς οἱ Ῥωμαῖοι καὶ ὀξεῖς κέλερας ὀνομάζουσι· καὶ Κόιντον Μέτελλον, ὅτι τοῦ πατρὸς ἀποθανόντος ἀγῶνα μονομάχων ἡμέραις ὀλίγαις ἐποίησε, θαυμάσαντες τὸ τάχος τῆς παρασκευῆς Κέλερα προσηγόρευσαν.", "st": "Rom. 10.1"}, {"sp": "N", "t": "ὁ δὲ Ῥωμύλος ἐν τῇ Ῥεμωρίᾳ θάψας τὸν Ῥέμον ὁμοῦ καὶ τοὺς τροφεῖς, ᾤκιζε τὴν πόλιν, ἐκ Τυρρηνίας μεταπεμψάμενος ἄνδρας ἱεροῖς τισι θεσμοῖς καὶ γράμμασιν ὑφηγουμένους ἕκαστα καὶ διδάσκοντας ὥσπερ ἐν τελετῇ. βόθρος γὰρ ὠρύγη περὶ τὸ νῦν Κομίτιον κυκλοτερής, ἀπαρχαί τε πάντων, ὅσοις νόμῳ μὲν ὡς καλοῖς ἐχρῶντο, φύσει δ’ ὡς ἀναγκαίοις, ἀπετέθησαν ἐνταῦθα. καὶ τέλος ἐξ ἧς ἀφῖκτο γῆς ἕκαστος ὀλίγην κομίζων μοῖραν ἔβαλλον εἰς ταὐτὸ καὶ συνεμείγνυον. καλοῦσι δὲ τὸν βόθρον τοῦτον ᾧ καὶ τὸν ὄλυμπον ὀνόματι μοῦνδον. εἶθ’ ὥσπερ κύκλον κέντρῳ περιέγραψαν τὴν πόλιν. ὁ δ’ οἰκιστὴς ἐμβαλὼν ἀρότρῳ χαλκῆν ὕνιν, ὑποζεύξας δὲ βοῦν ἄρρενα καὶ θήλειαν, αὐτὸς μὲν ἐπάγει περιελαύνων αὔλακα βαθεῖαν τοῖς τέρμασι, τῶν δ’ ἑπομένων ἔργον ἐστίν, ἃς ἀνίστησι βώλους τὸ ἄροτρον, καταστρέφειν εἴσω καὶ μηδεμίαν ἔξω περιορᾶν ἐκτρεπομένην. τῇ μὲν οὖν γραμμῇ τὸ τεῖχος ἀφορίζουσι, καὶ καλεῖται κατὰ συγκοπὴν πωμήριον, οἷον ὄπισθεν τείχους ἢ μετὰ τεῖχος· ὅπου δὲ πύλην ἐμβαλεῖν διανοοῦνται, τὴν ὕνιν ἐξελόντες καὶ τὸ ἄροτρον ὑπερθέντες διάλειμμα ποιοῦσιν. ὅθεν ἅπαν τὸ τεῖχος ἱερὸν πλὴν τῶν πυλῶν νομίζουσι· τὰς δὲ πύλας ἱερὰς νομίζοντας οὐκ ἦν ἄνευ δεισιδαιμονίας τὰ μὲν δέχεσθαι, τὰ δ’ ἀποπέμπειν τῶν ἀναγκαίων καὶ μὴ καθαρῶν.", "st": "Rom. 11.1"}, {"sp": "N", "t": "ὅτι μὲν οὖν ἡ κτίσις ἡμέρᾳ γένοιτο τῇ πρὸ ἕνδεκα καλανδῶν Μαΐων, ὁμολογεῖται, καὶ τὴν ἡμέραν ταύτην ἑορτάζουσι Ῥωμαῖοι, γενέθλιον τῆς πατρίδος ὀνομάζοντες. ἐν ἀρχῇ δ’ ὥς φασιν οὐδὲν ἔμψυχον ἔθυον, ἀλλὰ καθαρὰν καὶ ἀναίμακτον ᾤοντο δεῖν τῇ πατρίδι τὴν ἐπώνυμον τῆς γενέσεως ἑορτὴν φυλάττειν. οὐ μὴν ἀλλὰ καὶ πρὸ τῆς κτίσεως βοτηρική τις ἦν αὐτοῖς ἑορτὴ κατὰ ταύτην τὴν ἡμέραν, καὶ Παρίλια προσηγόρευον αὐτήν.", "st": "Rom. 12.1"}, {"sp": "N", "t": "νῦν μὲν οὖν οὐδὲν αἱ Ῥωμαϊκαὶ νουμηνίαι πρὸς τὰς Ἑλληνικὰς ὁμολογούμενον ἔχουσιν· ἐκείνην δὲ τὴν ἡμέραν, ᾗ τὴν πόλιν ὁ Ῥωμύλος ἔκτιζεν, ἀτρεκῆ τριακάδα τυχεῖν λέγουσι, καὶ σύνοδον ἐκλειπτικὴν ἐν αὐτῇ γενέσθαι σελήνης πρὸς ἥλιον, ἣν εἰδέναι καὶ Ἀντίμαχον οἴονται τὸν Τήιον ἐποποιόν, ἔτει τρίτῳ τῆς ἕκτης ὀλυμπιάδος συμπεσοῦσαν. ἐν δὲ τοῖς κατὰ Βάρρωνα τὸν φιλόσοφον χρόνοις, ἄνδρα Ῥωμαίων ἐν ἱστορίᾳ βυβλιακώτατον, ἦν Ταρούτιος ἑταῖρος αὐτοῦ, φιλόσοφος μὲν ἄλλως καὶ μαθηματικός, ἁπτόμενος δὲ τῆς περὶ τὸν πίνακα μεθόδου θεωρίας ἕνεκα καὶ δοκῶν ἐν αὐτῇ περιττὸς εἶναι. τούτῳ προὔβαλεν ὁ Βάρρων ἀναγαγεῖν τὴν Ῥωμύλου γένεσιν εἰς ἡμέραν καὶ ὥραν, ἐκ τῶν λεγομένων ἀποτελεσμάτων περὶ τὸν ἄνδρα ποιησάμενον τὸν συλλογισμόν, ὥσπερ αἱ τῶν γεωμετρικῶν ὑφηγοῦνται προβλημάτων ἀναλύσεις· τῆς γὰρ αὐτῆς θεωρίας εἶναι, χρόνον τε λαβόντας ἀνθρώπου γενέσεως βίον προειπεῖν, καὶ βίῳ δοθέντι θηρεῦσαι χρόνον. ἐποίησεν οὖν τὸ προσταχθὲν ὁ Ταρούτιος, καὶ τά τε πάθη καὶ τὰ ἔργα τοῦ ἀνδρὸς ἐπιδών, καὶ χρόνον ζωῆς καὶ τρόπον τελευτῆς καὶ πάντα τὰ τοιαῦτα συνθείς, εὖ μάλα τεθαρρηκότως καὶ ἀνδρείως ἀπεφήνατο, τὴν μὲν ἐν τῇ μητρὶ τοῦ Ῥωμύλου γεγονέναι σύλληψιν ἔτει πρώτῳ τῆς δευτέρας ὀλυμπιάδος ἐν μηνὶ κατ’ Αἰγυπτίους Χοιὰκ τρίτῃ καὶ εἰκάδι τρίτης ὥρας, καθ’ ἣν ὁ ἥλιος ἐξέλιπε παντελῶς, τὴν δ’ ἐμφανῆ γέννησιν ἐν μηνὶ Θωὺθ ἡμέρᾳ πρώτῃ μετ’ εἰκάδα περὶ ἡλίου ἀνατολάς· κτισθῆναι δὲ τὴν Ῥώμην ὑπ’ αὐτοῦ τῇ ἐνάτῃ Φαρμουθὶ μηνὸς ἱσταμένου μεταξὺ δευτέρας ὥρας καὶ τρίτης. ἐπεὶ καὶ πόλεως τύχην ὥσπερ ἀνθρώπου κύριον ἔχειν οἴονται χρόνον, ἐκ τῆς πρώτης γενέσεως πρὸς τὰς τῶν ἀστέρων ἐποχὰς θεωρούμενον. ἀλλὰ ταῦτα μὲν ἴσως καὶ τὰ τοιαῦτα τῷ ξένῳ καὶ περιττῷ προσάξεται μᾶλλον ἢ διὰ τὸ μυθῶδες ἐνοχλήσει τοὺς ἐντυγχάνοντας αὐτοῖς.", "st": "Rom. 12.2"}, {"sp": "N", "t": "κτισθείσης δὲ τῆς πόλεως, πρῶτον μὲν ὅσον ἦν ἐν ἡλικίᾳ πλῆθος εἰς συντάγματα στρατιωτικὰ διεῖλεν. ἕκαστον δὲ σύνταγμα πεζῶν τρισχιλίων ἦν καὶ τριακοσίων ἱππέων. ἐκλήθη δὲ λεγεὼν τῷ λογάδας εἶναι τοὺς μαχίμους ἐκ πάντων. ἔπειτα τοῖς μὲν ἄλλοις ἐχρῆτο δήμῳ, καὶ ποπούλους ὠνομάσθη τὸ πλῆθος· ἑκατὸν δὲ τοὺς ἀρίστους ἀπέδειξε βουλευτάς, καὶ αὐτοὺς μὲν πατρικίους, τὸ δὲ σύστημα σενᾶτον προσηγόρευσεν. ὁ μὲν οὖν σενᾶτος ἀτρεκῶς γερουσίαν σημαίνει· πατρικίους δὲ τοὺς βουλευτὰς κληθῆναι λέγουσιν οἱ μὲν ὅτι παίδων γνησίων πατέρες ἦσαν, οἱ δὲ μᾶλλον ὡς αὐτοὺς ἔχοντας ἑαυτῶν ἀποδεῖξαι πατέρας, ὅπερ οὐ πολλοῖς ὑπῆρξε τῶν πρώτων εἰς τὴν πόλιν συρρεόντων· οἱ δ’ ἀπὸ τῆς πατρωνείας· οὕτω γὰρ ἐκάλουν τὴν προστασίαν καὶ καλοῦσιν ἄχρι νῦν, οἰόμενοι Πάτρωνά τινα τῶν σὺν Εὐάνδρῳ παραγενομένων, κηδεμονικὸν τῶν ὑποδεεστέρων ὄντα καὶ βοηθητικόν, ἀφ’ αὑτοῦ τῷ πράγματι ταύτην τὴν προσηγορίαν ἀπολιπεῖν. μάλιστα δ’ ἄν τις τυγχάνοι τοῦ εἰκότος, εἰ νομίζοι τὸν Ῥωμύλον ἀξιοῦντα τοὺς πρώτους καὶ δυνατωτάτους πατρικῇ κηδεμονίᾳ καὶ φροντίδι προσήκειν ἐπιμελεῖσθαι τῶν ταπεινοτέρων, ἅμα δὲ τοὺς ἄλλους διδάσκοντα μὴ δεδιέναι μηδ’ ἄχθεσθαι ταῖς τῶν κρειττόνων τιμαῖς, ἀλλὰ χρῆσθαι μετ’ εὐνοίας καὶ νομίζοντας καὶ προσαγορεύοντας πατέρας, οὕτως ὀνομάσαι. καὶ γὰρ ἄχρι νῦν τοὺς ἐν συγκλήτῳ τελοῦντας οἱ μὲν ἔξωθεν ἄνδρας ἡγεμόνας καλοῦσιν, αὐτοὶ δὲ Ῥωμαῖοι πατέρας συγγεγραμμένους, τῷ μέγιστον μὲν ἀξίωμα καὶ τιμήν, ἥκιστα δὲ φθόνον ἔχοντι χρώμενοι τῶν ὀνομάτων.", "st": "Rom. 13.1"}, {"sp": "N", "t": "ἐν ἀρχῇ μὲν οὖν πατέρας αὐτοὺς μόνον, ὕστερον δὲ πλειόνων προσαναλαμβανομένων πατέρας συγγεγραμμένους προσηγόρευσαν. καὶ τοῦτο μὲν ἦν ὄνομα σεμνότερον αὐτῷ τῆς πρὸς τὸ δημοτικὸν τοῦ βουλευτικοῦ διαφορᾶς· ἑτέροις δὲ τοὺς δυνατοὺς ἀπὸ τῶν πολλῶν διῄρει, πάτρωνας ὀνομάζων, ὅπερ ἐστὶ προστάτας, ἐκείνους δὲ κλίεντας, ὅπερ ἐστὶ πελάτας· ἅμα δὲ πρὸς ἀλλήλους θαυμαστὴν εὔνοιαν αὐτοῖς καὶ μεγάλων δικαίων ὑπάρξουσαν ἐνεποίησεν. οὗτοι μὲν γὰρ ἐξηγητάς τε τῶν νομίμων καὶ προστάτας δικαζομένοις συμβούλους τε πάντων καὶ κηδεμόνας ἑαυτοὺς παρεῖχον, ἐκεῖνοι δὲ τούτους ἐθεράπευον, οὐ μόνον τιμῶντες, ἀλλὰ καὶ πενομένοις θυγατέρας συνεκδιδόντες καὶ χρέα συνεκτίνοντες, καταμαρτυρεῖν τε πελάτου προστάτην ἢ προστάτου πελάτην οὔτε νόμος οὐδεὶς οὔτ’ ἄρχων ἠνάγκαζεν.", "st": "Rom. 13.5"}, {"sp": "N", "t": "ὕστερον δὲ τῶν ἄλλων δικαίων μενόντων, τὸ λαμβάνειν χρήματα τοὺς δυνατοὺς παρὰ τῶν ταπεινοτέρων αἰσχρὸν ἐνομίσθη καὶ ἀγεννές. ταῦτα μὲν οὖν περὶ τούτων.", "st": "Rom. 13.5b"}, {"sp": "N", "t": "τετάρτῳ δὲ μηνὶ μετὰ τὴν κτίσιν, ὡς Φάβιος ἱστορεῖ, τὸ περὶ τὴν ἁρπαγὴν ἐτολμήθη τῶν γυναικῶν. καὶ λέγουσι μὲν ἔνιοι τὸν Ῥωμύλον αὐτὸν τῇ φύσει φιλοπόλεμον ὄντα, καὶ πεπεισμένον ἔκ τινων ἄρα λογίων ὅτι τὴν Ῥώμην πέπρωται πολέμοις τρεφομένην καὶ αὐξομένην γενέσθαι μεγίστην, βίας ὑπάρξαι πρὸς τοὺς Σαβίνους· οὐδὲ γὰρ πολλάς, ἀλλὰ τριάκοντα μόνας παρθένους λαβεῖν αὐτόν, ἅτε δὴ πολέμου μᾶλλον ἢ γάμων δεόμενον. τοῦτο δὲ οὐκ εἰκός· ἀλλὰ τὴν μὲν πόλιν ὁρῶν ἐποίκων εὐθὺς ἐμπιπλαμένην, ὧν ὀλίγοι γυναῖκας εἶχον, οἱ δὲ πολλοὶ μιγάδες ἐξ ἀπόρων καὶ ἀφανῶν ὄντες ὑπερεωρῶντο καὶ προσεδοκῶντο μὴ συμμενεῖν βεβαίως, ἐλπίζων δὲ πρὸς τοὺς Σαβίνους τρόπον τινὰ συγκράσεως καὶ κοινωνίας ἀρχὴν αὐτοῖς τὸ ἀδίκημα ποιήσειν ὁμηρευσαμένοις τὰς γυναῖκας, ἐπεχείρησε τῷ ἔργῳ τόνδε τὸν τρόπον.", "st": "Rom. 14.1"}, {"sp": "N", "t": "διεδόθη λόγος ὑπ’ αὐτοῦ πρῶτον, ὡς θεοῦ τινος ἀνευρήκοι βωμὸν ὑπὸ γῆς κεκρυμμένον. ὠνόμαζον δὲ τὸν θεὸν Κῶνσον, εἴτε βουλαῖον ὄντα (κωνσίλιον γὰρ ἔτι νῦν τὸ συμβούλιον καλοῦσι καὶ τοὺς ὑπάτους κώνσουλας οἷον προβούλους), εἴτε ἵππιον Ποσειδῶ. καὶ γὰρ ὁ βωμὸς ἐν τῷ μείζονι τῶν ἱπποδρόμων ἐστίν, ἀφανὴς τὸν ἄλλον χρόνον, ἐν δὲ τοῖς ἱππικοῖς ἀγῶσιν ἀνακαλυπτόμενος. οἱ δὲ καὶ ὅλως φασί, τοῦ βουλεύματος ἀπορρήτου καὶ ἀφανοῦς ὄντος, ὑπόγειον οὐκ ἀλόγως τῷ θεῷ βωμὸν γενέσθαι καὶ κεκρυμμένον. ὡς δ’ ἀνεφάνη, θυσίαν τε λαμπρὰν ἐπ’ αὐτῷ καὶ ἀγῶνα καὶ θέαν ἐκ καταγγελίας ἐπετέλει πανηγυρικήν. καὶ πολλοὶ μὲν ἄνθρωποι συνῆλθον, αὐτὸς δὲ προὐκάθητο μετὰ τῶν ἀρίστων, ἁλουργίδι κεκοσμημένος. ἦν δὲ τοῦ καιροῦ τῆς ἐπιχειρήσεως σύμβολον, ἐξαναστάντα τὴν ἁλουργίδα πτύξαι καὶ περιβαλέσθαι πάλιν. ἔχοντες οὖν ξίφη πολλοὶ προσεῖχον αὐτῷ, καὶ τοῦ σημείου γενομένου, σπασάμενοι τὰ ξίφη καὶ μετὰ βοῆς ὁρμήσαντες, ἥρπαζον τὰς θυγατέρας τῶν Σαβίνων, αὐτοὺς δὲ φεύγοντας εἴων καὶ παρίεσαν. ἁρπασθῆναι δέ φασιν οἱ μὲν τριάκοντα μόνας, ἀφ’ ὧν καὶ τὰς φρατρίας ὀνομασθῆναι· Οὐαλέριος δ’ Ἀντίας ἑπτὰ καὶ εἴκοσι καὶ πεντακοσίας, Ἰόβας δὲ τρεῖς καὶ ὀγδοήκοντα καὶ ἑξακοσίας, παρθένους. ὃ μέγιστον ἦν ἀπολόγημα τῷ Ῥωμύλῳ· γυναῖκα γὰρ οὐ λαβεῖν ἀλλ’ ἢ μίαν Ἑρσιλίαν, διαλαθοῦσαν αὐτούς, ἅτε δὴ μὴ μεθ’ ὕβρεως μηδ’ ἀδικίας ἐλθόντας ἐπὶ τὴν ἁρπαγήν, ἀλλὰ συμμεῖξαι καὶ συναγαγεῖν εἰς ταὐτὸ τὰ γένη ταῖς μεγίσταις ἀνάγκαις διανοηθέντας. τὴν δ’ Ἑρσιλίαν οἱ μὲν Ὁστίλιον γῆμαι λέγουσιν, ἄνδρα Ῥωμαίων ἐπιφανέστατον, οἱ δ’ αὐτὸν Ῥωμύλον, καὶ γενέσθαι καὶ παῖδας αὐτῷ, μίαν μὲν θυγατέρα Πρίμαν, τῇ τάξει τῆς γενέσεως οὕτω προσαγορευθεῖσαν, ἕνα δ’ υἱὸν μόνον, ὃν Ἀόλλιον μὲν ἐκεῖνος ἀπὸ τῆς γενομένης ἀθροίσεως ὑπ’ αὐτοῦ τῶν πολιτῶν ὠνόμασεν, οἱ δ’ ὕστερον Ἀβίλλιον. ἀλλὰ ταῦτα μὲν ἱστορῶν Ζηνόδοτος ὁ Τροιζήνιος πολλοὺς ἔχει τοὺς ἀντιλέγοντας.", "st": "Rom. 14.3"}, {"sp": "N", "t": "ἐν δὲ τοῖς ἁρπάζουσι τὰς παρθένους τότε τυχεῖν λέγουσι τῶν οὐκ ἐπιφανῶν τινας ἄγοντας κόρην τῷ τε κάλλει πολὺ καὶ τῷ μεγέθει διαφέρουσαν. ἐπεὶ δ’ ἀπαντῶντες ἔνιοι τῶν κρειττόνων ἐπεχείρουν ἀφαιρεῖσθαι, βοᾶν τοὺς ἄγοντας, ὡς Ταλασίῳ κομίζοιεν αὐτήν, ἀνδρὶ νέῳ μέν, εὐδοκίμῳ δὲ καὶ χρηστῷ· τοῦτ’ οὖν ἀκούσαντας εὐφημεῖν καὶ κροτεῖν ἐπαινοῦντας, ἐνίους δὲ καὶ παρακολουθεῖν ἀναστρέψαντας εὐνοίᾳ καὶ χάριτι τοῦ Ταλασίου, μετὰ βοῆς τοὔνομα φθεγγομένους. ἀφ’ οὗ δὴ τὸν Ταλάσιον ἄχρι νῦν, ὡς Ἕλληνες τὸν Ὑμέναιον, ἐπᾴδουσι Ῥωμαῖοι τοῖς γάμοις· καὶ γὰρ εὐτυχίᾳ φασὶ χρήσασθαι περὶ τὴν γυναῖκα τὸν Ταλάσιον.", "st": "Rom. 15.1"}, {"sp": "N", "t": "Σέξτιος δὲ Σύλλας ὁ Καρχηδόνιος, οὔτε μουσῶν οὔτε χαρίτων ἐπιδεὴς ἀνήρ, ἔλεγεν ἡμῖν ὅτι τῆς ἁρπαγῆς σύνθημα τὴν φωνὴν ἔδωκε ταύτην ὁ Ῥωμύλος· ἅπαντες οὖν ἐβόων τὸν Ταλάσιον οἱ τὰς παρθένους κομίζοντες, καὶ διὰ τοῦτο τοῖς γάμοις παραμένει τὸ ἔθος. οἱ δὲ πλεῖστοι νομίζουσιν, ὧν καὶ ὁ Ἰόβας ἐστί, παράκλησιν εἶναι καὶ παρακέλευσιν εἰς φιλεργίαν καὶ ταλασίαν, οὔπω τότε τοῖς Ἑλληνικοῖς ὀνόμασι τῶν Ἰταλικῶν ἐπικεχυμένων. εἰ δὲ τοῦτο μὴ λέγεται κακῶς, ἀλλ’ ἐχρῶντο Ῥωμαῖοι τότε τῷ ὀνόματι τῆς ταλασίας καθάπερ ἡμεῖς, ἑτέραν ἄν τις αἰτίαν εἰκάσειε πιθανωτέραν. ἐπεὶ γὰρ οἱ Σαβῖνοι πρὸς τοὺς Ῥωμαίους πολεμήσαντες διηλλάγησαν, ἐγένοντο συνθῆκαι περὶ τῶν γυναικῶν, ὅπως μηδὲν ἄλλο ἔργον τοῖς ἀνδράσιν ἢ τὰ περὶ τὴν ταλασίαν ὑπουργῶσι. παρέμεινεν οὖν καὶ τοῖς αὖθις γαμοῦσι τοὺς διδόντας ἢ παραπέμποντας ἢ ὅλως παρόντας ἀναφωνεῖν τὸν Ταλάσιον μετὰ παιδιᾶς, μαρτυρομένους ὡς ἐπ’ οὐδὲν ἄλλο ὑπούργημα τῆς γυναικὸς ἢ ταλασίαν εἰσαγομένης. διαμένει δὲ μέχρι νῦν τὸ τὴν νύμφην αὐτὴν ἀφ’ αὑτῆς μὴ ὑπερβαίνειν τὸν οὐδὸν εἰς τὸ δωμάτιον, ἀλλ’ αἰρομένην εἰσφέρεσθαι, διὰ τὸ καὶ τότε κομισθῆναι βιασθείσας, μὴ εἰσελθεῖν. ἔνιοι δὲ λέγουσι καὶ τὸ τὴν κόμην τῆς γαμουμένης αἰχμῇ διακρίνεσθαι δορατίου σύμβολον εἶναι τοῦ μετὰ μάχης καὶ πολεμικῶς τὸν πρῶτον γάμον γενέσθαι· περὶ ὧν ἐπὶ πλέον ἐν τοῖς Αἰτίοις εἰρήκαμεν.", "st": "Rom. 15.3"}, {"sp": "N", "t": "ἐτολμήθη μὲν οὖν ἡ ἁρπαγὴ περὶ τὴν ὀκτωκαιδεκάτην ἡμέραν τοῦ τότε Σεξτιλίου μηνός, Αὐγούστου δὲ νῦν, ἐν ᾗ τὴν τῶν Κωνσαλίων ἑορτὴν ἄγουσιν.", "st": "Rom. 15.3b"}, {"sp": "N", "t": "οἱ δὲ Σαβῖνοι πολλοὶ μὲν ἦσαν καὶ πολεμικοί, κώμας δ’ ᾤκουν ἀτειχίστους, ὡς προσῆκον αὐτοῖς μέγα φρονεῖν καὶ μὴ φοβεῖσθαι, Λακεδαιμονίων ἀποίκοις οὖσιν. οὐ μὴν ἀλλ’ ὁρῶντες αὑτοὺς ἐνδεδεμένους μεγάλοις ὁμηρεύμασι, καὶ δεδιότες περὶ τῶν θυγατέρων, πρέσβεις ἀπέστειλαν ἐπιεικῆ καὶ μέτρια προκαλούμενοι, τὸν Ῥωμύλον ἀποδόντα τὰς κόρας αὐτοῖς καὶ λύσαντα τὸ τῆς βίας ἔργον, εἶτα πειθοῖ καὶ νόμῳ πράττειν τοῖς γένεσι φιλίαν καὶ οἰκειότητα. τοῦ δὲ Ῥωμύλου τὰς μὲν κόρας μὴ προιεμένου, παρακαλοῦντος δὲ τὴν κοινωνίαν δέχεσθαι τοὺς Σαβίνους, οἱ μὲν ἄλλοι βουλευόμενοι καὶ παρασκευαζόμενοι διέτριβον, Ἄκρων δὲ βασιλεὺς Καινινητῶν, ἀνὴρ θυμοειδὴς καὶ δεινὸς ἐν τοῖς πολεμικοῖς, τά τε πρῶτα τολμήματα τοῦ Ῥωμύλου δι’ ὑποψίας εἶχε, καὶ τῷ πραχθέντι περὶ τὰς γυναῖκας ἤδη φοβερὸν ἡγούμενος πᾶσιν εἶναι καὶ οὐκ ἀνεκτὸν εἰ μὴ κολασθείη, προεξανέστη τῷ πολέμῳ καὶ μετὰ πολλῆς ἐχώρει δυνάμεως ἐπ’ αὐτόν, καὶ ὁ Ῥωμύλος ἐπ’ ἐκεῖνον. γενόμενοι δ’ ἐν ὄψει καὶ κατιδόντες ἀλλήλους προὐκαλοῦντο μάχεσθαι, τῶν στρατευμάτων ἐν τοῖς ὅπλοις ἀτρεμούντων. εὐξάμενος οὖν ὁ Ῥωμύλος, εἰ κρατήσειε καὶ καταβάλοι, τῷ Διὶ φέρων ἀναθήσειν αὐτὸς τὰ ὅπλα τοῦ ἀνδρός, αὐτόν τε καταβάλλει κρατήσας, καὶ τρέπεται τὸ στράτευμα μάχης γενομένης, αἱρεῖ δὲ καὶ τὴν πόλιν. οὐ μὴν ἠδίκησε τοὺς ἐγκαταληφθέντας, ἀλλ’ ἢ τὰς οἰκίας ἐκέλευσε καθελόντας ἀκολουθεῖν εἰς Ῥώμην, ὡς πολίτας ἐπὶ τοῖς ἴσοις ἐσομένους.", "st": "Rom. 16.1"}, {"sp": "N", "t": "τούτου μὲν οὖν οὐκ ἔστιν ὅ τι μᾶλλον ηὔξησε τὴν Ῥώμην, ἀεὶ προσποιοῦσαν ἑαυτῇ καὶ συννέμουσαν ὧν κρατήσειεν. ὁ δὲ Ῥωμύλος, ὡς ἂν μάλιστα τὴν εὐχὴν τῷ τε Διὶ κεχαρισμένην καὶ τοῖς πολίταις ἰδεῖν ἐπιτερπῆ παράσχοι σκεψάμενος, ἐπὶ στρατοπέδου δρῦν ἔτεμεν ὑπερμεγέθη καὶ διεμόρφωσεν ὥσπερ τρόπαιον, καὶ τῶν ὅπλων τοῦ Ἄκρωνος ἕκαστον ἐν τάξει περιήρμοσε καὶ κατήρτησεν, αὐτὸς δὲ τὴν μὲν ἐσθῆτα περιεζώσατο, δάφνῃ δ’ ἐστέψατο τὴν κεφαλὴν κομῶσαν. ὑπολαβὼν δὲ τῷ δεξιῷ τὸ τρόπαιον ὤμῳ προσερειδόμενον ὀρθόν, ἐβάδιζεν ἐξάρχων ἐπινικίου παιᾶνος ἐν ὅπλοις ἑπομένῃ τῇ στρατιᾷ, δεχομένων τῶν πολιτῶν μετὰ χαρᾶς καὶ θαύματος. ἡ μὲν οὖν πομπὴ τῶν αὖθις θριάμβων ἀρχὴν καὶ ζῆλον παρέσχε, τὸ δὲ τρόπαιον ἀνάθημα Φερετρίου Διὸς ἐπωνομάσθη— τὸ γὰρ πλῆξαι φερῖρε Ῥωμαῖοι καλοῦσιν, εὔξατο δὲ πλῆξαι τὸν ἄνδρα καὶ καταβαλεῖν· ὀπίμια δὲ τὰ σκῦλα, φησὶ Βάρρων, καθότι καὶ τὴν περιουσίαν ὄπεμ λέγουσι. πιθανώτερον δ’ ἄν τις εἴποι διὰ τὴν πρᾶξιν· ὄπους γὰρ ὀνομάζεται τὸ ἔργον, αὐτουργῷ δ’ ἀριστείας στρατηγῷ, στρατηγὸν ἀνελόντι, δέδοται καθιέρωσις ὀπιμίων.", "st": "Rom. 16.5"}, {"sp": "N", "t": "καὶ τρισὶ μόνοις τούτου τυχεῖν ὑπῆρξε Ῥωμαίοις ἡγεμόσι, πρώτῳ Ῥωμύλῳ κτείναντι τὸν Καινινήτην Ἄκρωνα, δευτέρῳ Κορνηλίῳ Κόσσῳ Τυρρηνὸν ἀνελόντι Τολούμνιον, ἐπὶ πᾶσι δὲ Κλαυδίῳ Μαρκέλλῳ Βριτομάρτου κρατήσαντι Γαλατῶν βασιλέως. Κόσσος μὲν οὖν καὶ Μάρκελλος ἤδη τεθρίπποις εἰσήλαυνον, αὐτοὶ τὰ τρόπαια φέροντες· Ῥωμύλον δ’ οὐκ ὀρθῶς φησιν ἅρματι χρήσασθαι Διονύσιος. Ταρκύνιον γὰρ ἱστοροῦσι τὸν Δημαράτου τῶν βασιλέων πρῶτον εἰς τοῦτο τὸ σχῆμα καὶ τὸν ὄγκον ἐξᾶραι τοὺς θριάμβους· ἕτεροι δὲ πρῶτον ἐφ’ ἅρματος θριαμβεῦσαι Ποπλικόλαν. τοῦ δὲ Ῥωμύλου τὰς εἰκόνας ὁρᾶν ἔστιν ἐν Ῥώμῃ τὰς τροπαιοφόρους πεζὰς ἁπάσας.", "st": "Rom. 16.8"}, {"sp": "N", "t": "μετὰ δὲ τὴν Καινινητῶν ἅλωσιν ἔτι τῶν ἄλλων Σαβίνων ἐν παρασκευαῖς ὄντων, συνέστησαν οἱ Φιδήνην καὶ Κρουστουμέριον καὶ Ἀντέμναν οἰκοῦντες ἐπὶ τοὺς Ῥωμαίους, καὶ μάχης γενομένης ἡττηθέντες ὁμοίως, τάς τε πόλεις Ῥωμύλῳ παρῆκαν ἑλεῖν καὶ τὴν χώραν δάσασθαι καὶ μετοικίσαι σφᾶς αὐτοὺς εἰς Ῥώμην. ὁ δὲ Ῥωμύλος τὴν μὲν ἄλλην κατένειμε χώραν τοῖς πολίταις, ὅσην δ’ εἶχον οἱ τῶν ἡρπασμένων παρθένων πατέρες, αὐτοὺς ἔχειν ἐκείνους εἴασεν.", "st": "Rom. 17.1"}, {"sp": "N", "t": "ἐπὶ τούτοις βαρέως φέροντες οἱ λοιποὶ Σαβῖνοι Τάτιον ἀποδείξαντες στρατηγὸν ἐπὶ τὴν Ῥώμην ἐστράτευσαν. ἦν δὲ δυσπρόσοδος ἡ πόλις, ἔχουσα πρόβλημα τὸ νῦν Καπιτώλιον, ἐν ᾧ φρουρὰ καθειστήκει καὶ Ταρπήιος ἡγεμὼν αὐτῆς, οὐχὶ Ταρπηία παρθένος, ὡς ἔνιοι λέγουσιν, εὐήθη τὸν Ῥωμύλον ἀποδεικνύοντες· ἀλλὰ θυγάτηρ ἡ Ταρπηία τοῦ ἄρχοντος οὖσα προὔδωκε τοῖς Σαβίνοις, ἐπιθυμήσασα τῶν χρυσῶν βραχιονιστήρων οὓς εἶδε περικειμένους, καὶ ᾔτησε μισθὸν τῆς προδοσίας ἃ φοροῖεν ἐν ταῖς ἀριστεραῖς χερσί. συνθεμένου δὲ τοῦ Τατίου, νύκτωρ ἀνοίξασα πύλην μίαν, ἐδέξατο τοὺς Σαβίνους. οὐ μόνος οὖν ὡς ἔοικεν Ἀντίγονος ἔφη προδιδόντας μὲν φιλεῖν, προδεδωκότας δὲ μισεῖν, οὐδὲ Καῖσαρ, εἰπὼν ἐπὶ τοῦ Θρᾳκὸς Ῥοιμητάλκου, φιλεῖν μὲν προδοσίαν, προδότην δὲ μισεῖν, ἀλλὰ κοινόν τι τοῦτο πάθος ἐστὶ πρὸς τοὺς πονηροὺς τοῖς δεομένοις αὐτῶν, ὥσπερ ἰοῦ καὶ χολῆς ἐνίων θηρίων δέονται· τὴν γὰρ χρείαν ὅτε λαμβάνουσιν ἀγαπῶντες, ἐχθαίρουσι τὴν κακίαν ὅταν τύχωσι. τοῦτο καὶ πρὸς τὴν Ταρπηίαν τότε παθὼν ὁ Τάτιος, ἐκέλευσε μεμνημένους τῶν ὁμολογιῶν τοὺς Σαβίνους μηδενὸς αὐτῇ φθονεῖν ὧν ἐν ταῖς ἀριστεραῖς ἔχουσι, καὶ πρῶτος ἅμα τὸν βραχιονιστῆρα τῆς χειρὸς περιελὼν καὶ τὸν θυρεὸν ἐπέρριψε. πάντων δὲ τὸ αὐτὸ ποιούντων, βαλλομένη τε τῷ χρυσῷ καὶ καταχωσθεῖσα τοῖς θυρεοῖς, ὑπὸ πλήθους καὶ βάρους ἀπέθανεν. ἑάλω δὲ καὶ Ταρπήιος προδοσίας ὑπὸ Ῥωμύλου διωχθείς, ὡς Ἰόβας φησὶ Γάλβαν Σουλπίκιον ἱστορεῖν. τῶν δ’ ἄλλα περὶ Ταρπηίας λεγόντων ἀπίθανοι μέν εἰσιν οἱ Τατίου θυγατέρα τοῦ ἡγεμόνος τῶν Σαβίνων οὖσαν αὐτήν, Ῥωμύλῳ δὲ βίᾳ συνοικοῦσαν, ἱστοροῦντες ταῦτα ποιῆσαι καὶ παθεῖν ὑπὸ τοῦ πατρός· ὧν καὶ Ἀντίγονός ἐστι. Σιμύλος δ’ ὁ ποιητὴς καὶ παντάπασι ληρεῖ, μὴ Σαβίνοις οἰόμενος, ἀλλὰ Κελτοῖς τὴν Ταρπηίαν προδοῦναι τὸ Καπιτώλιον, ἐρασθεῖσαν αὐτῶν τοῦ βασιλέως. λέγει δὲ ταῦτα·", "st": "Rom. 17.2"}, {"sp": "N", "t": "ἡ δ’ ἀγχοῦ Τάρπεια παραὶ Καπιτώλιον αἶπος ναίουσα Ῥώμης ἔπλετο τειχολέτις, Κελτῶν ἣ στέρξασα γαμήλια λέκτρα γενέσθαι σκηπτούχῳ, πατέρων οὐκ ἐφύλαξε δόμους.", "st": "Rom. 17.2b"}, {"sp": "N", "t": "καὶ μετ’ ὀλίγα περὶ τῆς τελευτῆς· τὴν δ’ οὔτ’ ἄρ’ Βόιοί τε καὶ ἔθνεα μυρία Κελτῶν χηράμενοι ῥείθρων ἐντὸς ἔθεντο Πάδου, ὅπλα δ’ ἐπιπροβαλόντες ἀρειμανέων ἀπὸ χειρῶν κούρῃ ἐπὶ στυγερῇ κόσμον ἔθεντο φόνον.", "st": "Rom. 17.2c"}, {"sp": "N", "t": "τῆς μέντοι Ταρπηίας ἐκεῖ ταφείσης, ὁ λόφος ὠνομάζετο Ταρπήιος, ἄχρι οὗ Ταρκυνίου βασιλέως Διὶ τὸν τόπον καθιεροῦντος ἅμα τά τε λείψανα μετηνέχθη, καὶ τοὔνομα τῆς Ταρπηίας ἐξέλιπε· πλὴν πέτραν ἔτι νῦν ἐν τῷ Καπιτωλίῳ Ταρπηίαν καλοῦσιν, ἀφ’ ἧς ἐρρίπτουν τοὺς κακούργους.", "st": "Rom. 18.1"}, {"sp": "N", "t": "ἐχομένης δὲ τῆς ἄκρας ὑπὸ τῶν Σαβίνων, ὅ τε Ῥωμύλος ὑπ’ ὀργῆς εἰς μάχην αὐτοὺς προὐκαλεῖτο, καὶ ὁ Τάτιος ἐθάρρει, καρτερὰν εἰ βιασθεῖεν ἀναχώρησιν ὁρῶν αὐτοῖς ὑπάρχουσαν. ὁ γὰρ μεταξὺ τόπος, ἐν ᾧ συμπίπτειν ἔμελλον, ὑπὸ πολλῶν λόφων περιεχόμενος, ἀγῶνα μὲν ὀξὺν ἐδόκει καὶ χαλεπὸν ὑπὸ δυσχωρίας ἀμφοτέροις παρέξειν, φυγὰς δὲ καὶ διώξεις ἐν στενῷ βραχείας. ἔτυχε δὲ τοῦ ποταμοῦ λιμνάσαντος οὐ πολλαῖς πρότερον ἡμέραις ἐγκαταλελεῖφθαι τέλμα βαθὺ καὶ τυφλὸν ἐν τόποις ἐπιπέδοις κατὰ τὴν νῦν οὖσαν ἀγοράν, ὅθεν οὐκ ἦν ὄψει πρόδηλον οὐδ’ εὐφύλακτον, ἄλλως δὲ χαλεπὸν καὶ ὕπουλον. ἐπὶ τοῦτο τοῖς Σαβίνοις ἀπειρίᾳ φερομένοις εὐτύχημα γίγνεται. Κούρτιος γάρ, ἀνὴρ ἐπιφανὴς δόξῃ καὶ φρονήματι γαῦρος, ἵππον ἔχων πολὺ πρὸ τῶν ἄλλων ἐχώρει·", "st": "Rom. 18.2"}, {"sp": "N", "t": "δεξαμένου δὲ τοῦ βαράθρου τὸν ἵππον, ἄχρι μέν τινος ἐπειρᾶτο πληγῇ καὶ παρακελεύσει χρώμενος ἐξελαύνειν, ὡς δ’ ἦν ἀμήχανον, ἐάσας τὸν ἵππον ἑαυτὸν ἔσῳζεν. ὁ μὲν οὖν τόπος δι’ ἐκεῖνον ἔτι νῦν Κούρτειος λάκκος ὀνομάζεται· φυλαξάμενοι δὲ τὸν κίνδυνον οἱ Σαβῖνοι μάχην καρτερὰν ἐμαχέσαντο, κρίσιν οὐ λαβοῦσαν, καίτοι πολλῶν πεσόντων, ἐν οἷς ἦν καὶ Ὁστίλιος. τοῦτον Ἑρσιλίας ἄνδρα καὶ πάππον Ὁστιλίου τοῦ μετὰ Νομᾶν βασιλεύσαντος γενέσθαι λέγουσιν. αὖθις δὲ πολλῶν ἀγώνων ἐν βραχεῖ συνισταμένων ὡς εἰκός, ἑνὸς μάλιστα τοῦ τελευταίου μνημονεύουσιν, ἐν ᾧ Ῥωμύλου τὴν κεφαλὴν πληγέντος λίθῳ καὶ πεσεῖν ὀλίγον δεήσαντος τοῦ τ’ ἀντέχειν ὑφεμένου, τοῖς Σαβίνοις ἐνέδωκαν οἱ Ῥωμαῖοι καὶ φυγῇ πρὸς τὸ Παλάτιον ἐχώρουν, ἐξωθούμενοι τῶν ἐπιπέδων. ἤδη δὲ ὁ Ῥωμύλος ἐκ τῆς πληγῆς ἀναφέρων, ἐβούλετο μὲν εἰς τὰ ὅπλα χωρεῖν τοῖς φεύγουσιν ἐναντίως, καὶ μέγα βοῶν ἵστασθαι καὶ μάχεσθαι παρεκάλει.", "st": "Rom. 18.5"}, {"sp": "N", "t": "πολλῆς δὲ τῆς φυγῆς αὐτῷ περιχεομένης, καὶ μηδενὸς ἀναστρέφειν τολμῶντος, ἀνατείνας εἰς οὐρανὸν τὰς χεῖρας ηὔξατο τῷ Διὶ στῆσαι τὸ στράτευμα καὶ τὰ Ῥωμαίων πράγματα πεσόντα μὴ περιιδεῖν, ἀλλ’ ὀρθῶσαι. γενομένης δὲ τῆς εὐχῆς, αἰδώς τε τοῦ βασιλέως ἔσχε πολλούς, καὶ θάρσος ἐκ μεταβολῆς παρέστη τοῖς φεύγουσιν. ἔστησαν οὖν πρῶτον οὗ νῦν ὁ τοῦ Διὸς τοῦ Στάτορος ἵδρυται νεώς, ὃν Ἐπιστάσιον ἄν τις ἑρμηνεύσειεν, εἶτα συνασπίσαντες πάλιν ἔωσαν ὀπίσω τοὺς Σαβίνους ἐπὶ τὴν νῦν Ῥήγιαν προσαγορευομένην καὶ τὸ τῆς Ἑστίας ἱερόν. ἐνταῦθα δ’ αὐτοὺς ὥσπερ ἐξ ὑπαρχῆς μάχεσθαι παρασκευαζομένους ἐπέσχε δεινὸν ἰδεῖν θέαμα καὶ λόγου κρείττων ὄψις. αἱ γὰρ ἡρπασμέναι θυγατέρες τῶν Σαβίνων ὤφθησαν ἀλλαχόθεν ἄλλαι μετὰ βοῆς καὶ ἀλαλαγμοῦ διὰ τῶν ὅπλων φερόμεναι καὶ τῶν νεκρῶν ὥσπερ ἐκ θεοῦ κάτοχοι, πρός τε τοὺς ἄνδρας αὑτῶν καὶ τοὺς πατέρας, αἱ μὲν παιδία κομίζουσαι νήπια πρὸς ταῖς ἀγκάλαις, αἱ δὲ τὴν κόμην προϊσχόμεναι λελυμένην, πᾶσαι δ’ ἀνακαλούμεναι τοῖς φιλτάτοις ὀνόμασι ποτὲ μὲν τοὺς Σαβίνους, ποτὲ δὲ τοὺς Ῥωμαίους. ἐπεκλάσθησαν οὖν ἀμφότεροι, καὶ διέσχον αὐταῖς ἐν μέσῳ καταστῆναι τῆς παρατάξεως, καὶ κλαυθμὸς ἅμα διὰ πάντων ἐχώρει, καὶ πολὺς οἶκτος ἦν πρός τε τὴν ὄψιν καὶ τοὺς λόγους ἔτι μᾶλλον, εἰς ἱκεσίαν καὶ δέησιν ἐκ δικαιολογίας καὶ παρρησίας τελευτῶντας.", "st": "Rom. 18.7"}, {"sp": "N", "t": "τί γάρ (ἔφασαν) ὑμᾶς δεινὸν ἢ λυπηρὸν ἐργασάμεναι, τὰ μὲν ἤδη πεπόνθαμεν, τὰ δὲ πάσχομεν τῶν σχετλίων κακῶν; ἡρπάσθημεν ὑπὸ τῶν νῦν ἐχόντων βίᾳ καὶ παρανόμως, ἁρπασθεῖσαι δ’ ἠμελήθημεν ὑπ’ ἀδελφῶν καὶ πατέρων καὶ οἰκείων χρόνον τοσοῦτον, ὅσος ἡμᾶς πρὸς τὰ ἔχθιστα κεράσας ταῖς μεγίσταις ἀνάγκαις πεποίηκε νῦν ὑπὲρ τῶν βιασαμένων καὶ παρανομησάντων δεδιέναι μαχομένων καὶ κλαίειν θνῃσκόντων. οὐ γὰρ ἤλθετε τιμωρήσοντες ἡμῖν παρθένοις οὔσαις ἐπὶ τοὺς ἀδικοῦντας, ἀλλὰ νῦν ἀνδρῶν ἀποσπᾶτε γαμετὰς καὶ τέκνων μητέρας, οἰκτροτέραν βοήθειαν ἐκείνης τῆς ἀμελείας καὶ προδοσίας βοηθοῦντες ἡμῖν ταῖς ἀθλίαις. τοιαῦτα μὲν ἠγαπήθημεν ὑπὸ τούτων, τοιαῦτα δ’ ὑφ’ ὑμῶν ἐλεούμεθα.", "st": "Rom. 19.3"}, {"sp": "N", "t": "καὶ γὰρ εἰ δι’ ἄλλην αἰτίαν ἐμάχεσθε, παύσασθαι δι’ ἡμᾶς πενθεροὺς γεγονότας καὶ πάππους καὶ οἰκείους ὄντας ἐχρῆν. εἰ δ’ ὑπὲρ ἡμῶν ὁ πόλεμός ἐστι, κομίσασθε ἡμᾶς μετὰ γαμβρῶν καὶ τέκνων, καὶ ἀπόδοτε ἡμῖν πατέρας καὶ οἰκείους, μηδ’ ἀφέλησθε παῖδας καὶ ἄνδρας. ἱκετεύομεν ὑμᾶς μὴ πάλιν αἰχμάλωτοι γενέσθαι.", "st": "Rom. 19.5"}, {"sp": "N", "t": "τοιαῦτα πολλὰ τῆς Ἑρσιλίας προαγορευούσης καὶ τῶν ἄλλων δεομένων, ἐσπείσθησαν ἀνοχαί, καὶ συνῆλθον εἰς λόγους οἱ ἡγεμόνες. αἱ δὲ γυναῖκες ἐν τούτῳ τοῖς πατράσι καὶ τοῖς ἀδελφοῖς τοὺς ἄνδρας προσῆγον καὶ τά τέκνα, προσέφερόν τε τροφὴν καὶ ποτὸν τοῖς δεομένοις, καὶ τοὺς τετρωμένους ἐθεράπευον οἴκαδε κομίζουσαι, καὶ παρεῖχον ὁρᾶν ἀρχούσας μὲν αὑτὰς τοῦ οἴκου, προσέχοντας δὲ τοὺς ἄνδρας αὐταῖς καὶ μετ’ εὐνοίας τιμὴν ἅπασαν νέμοντας. ἐκ τούτου συντίθενται, τῶν μὲν γυναικῶν τὰς βουλομένας συνοικεῖν τοῖς ἔχουσιν, ὥσπερ εἴρηται παντὸς ἔργου καὶ πάσης λατρείας πλὴν ταλασίας ἀφειμένας, οἰκεῖν δὲ κοινῇ τὴν πόλιν Ῥωμαίους καὶ Σαβίνους, καὶ καλεῖσθαι μὲν Ῥώμην ἐπὶ Ῥωμύλῳ τὴν πόλιν, Κυρίτας δὲ Ῥωμαίους ἅπαντας ἐπὶ τῇ Τατίου πατρίδι, βασιλεύειν δὲ κοινῇ καὶ στρατηγεῖν ἀμφοτέρους. ὅπου δὲ ταῦτα συνέθεντο, μέχρι νῦν Κομίτιον καλεῖται· κομῖρε γὰρ Ῥωμαῖοι τὸ συνελθεῖν καλοῦσι.", "st": "Rom. 19.6"}, {"sp": "N", "t": "Διπλασιασθείσης δὲ τῆς πόλεως, ἑκατὸν μὲν ἐκ Σαβίνων πατρίκιοι προσκατελέχθησαν, αἱ δὲ λεγεῶνες ἐγένοντο πεζῶν μὲν ἑξακισχιλίων, ἱππέων δ’ ἑξακοσίων. φυλὰς δὲ τρεῖς καταστήσαντες, ὠνόμασαν τοὺς μὲν ἀπὸ Ῥωμύλου Ῥαμνήνσης, τοὺς δ’ ἀπὸ Τατίου Τατιήνσης, τρίτους δὲ Λουκερήνσης διὰ τὸ ἄλσος εἰς ὃ πολλοὶ καταφυγόντες ἀσυλίας δεδομένης τοῦ πολιτεύματος μετέσχον· τὰ δ’ ἄλση λούκους ὀνομάζουσιν. ὅτι δ’ ἦσαν αἱ φυλαὶ τοσαῦται, τοὔνομα μαρτυρεῖ· τρίβους γὰρ ἔτι νῦν τὰς φυλὰς καλοῦσι καὶ τριβούνους τοὺς φυλάρχους. ἑκάστη δὲ φυλὴ δέκα φρατρίας εἶχεν, ἃς ἔνιοι λέγουσιν ἐπωνύμους ἐκείνων εἶναι τῶν γυναικῶν. τοῦτο δὲ δοκεῖ ψεῦδος εἶναι· πολλαὶ γὰρ ἔχουσιν ἀπὸ χωρίων τὰς προσηγορίας. ἄλλα μέντοι πολλὰ ταῖς γυναιξὶν εἰς τιμὴν ἀπέδωκαν, ὧν καὶ ταῦτ’ ἐστιν· ἐξίστασθαι μὲν ὁδοῦ βαδιζούσαις, αἰσχρὸν δὲ μηδένα μηδὲν εἰπεῖν παρούσης γυναικός, μηδ’ ὀφθῆναι γυμνόν, ἢ δίκην φεύγειν παρὰ τοῖς ἐπὶ τῶν φονικῶν καθεστῶσι, φορεῖν δὲ καὶ τοὺς παῖδας αὐτῶν τὴν καλουμένην βοῦλλαν ἀπὸ τοῦ σχήματος, ὅμοιον πομφόλυγι περιδέραιόν τι, καὶ περιπόρφυρον.", "st": "Rom. 20.1"}, {"sp": "N", "t": "ἐβουλεύοντο δ’ οἱ βασιλεῖς οὐκ εὐθὺς ἐν κοινῷ μετ’ ἀλλήλων, ἀλλ’ ἑκάτερος πρότερον ἰδίᾳ μετὰ τῶν ἑκατόν, εἶθ’ οὕτως εἰς ταὐτὸν ἅπαντας συνῆγον. ᾤκει δὲ Τάτιος μὲν ὅπου νῦν ὁ τῆς Μονήτης ναός ἐστι, Ῥωμύλος δὲ παρὰ τοὺς λεγομένους βαθμοὺς καλῆς ἀκτῆς. οὗτοι δ’ εἰσὶ περὶ τὴν εἰς τὸν ἱππόδρομον τὸν μέγαν ἐκ Παλατίου κατάβασιν. ἐνταῦθα δὲ καὶ τὴν κράνειαν ἔφασαν τὴν ἱερὰν γεγονέναι, μυθολογοῦντες ὅτι πειρώμενος ὁ Ῥωμύλος αὑτοῦ λόγχην ἀκοντίσειεν ἀπὸ τοῦ Ἀουεντίνου, τὸ ξυστὸν ἔχουσαν κρανείας· καταδύσης δὲ τῆς αἰχμῆς εἰς βάθος, ἀνασπάσαι μὲν οὐδεὶς πειρωμένων πολλῶν ἴσχυσε, τὸ δὲ ξύλον ἔστεξεν ἡ γῆ ζώφυτος οὖσα, καὶ βλαστοὺς ἀνῆκε καὶ στέλεχος εὐμέγεθες κρανείας ἔθρεψε. τοῦτο δ’ οἱ μετὰ Ῥωμύλον ὡς ἕν τι τῶν ἁγιωτάτων ἱερῶν φυλάττοντες καὶ σεβόμενοι περιετείχισαν. ὅτῳ δὲ προσιόντι δόξειε μὴ θαλερὸν εἶναι μηδὲ χλωρόν, ἀλλ’ οἷον ἀτροφεῖν καὶ φθίνειν, ὁ μὲν εὐθὺς ἔφραζε κραυγῇ τοῖς προστυγχάνουσιν, οἱ δ’ ὥσπερ ἐμπρησμῷ βοηθοῦντες ἐβόων ὕδωρ, ὕδωρ, καὶ συνέτρεχον πανταχόθεν ἀγγεῖα πλήρη κομίζοντες ἐπὶ τὸν τόπον. Γαΐου δὲ Καίσαρος ὥς φασι τὰς ἀναβάσεις ἐπισκευάζοντος, καὶ τῶν τεχνιτῶν περιορυττόντων τὰ πλησίον, ἔλαθον αἱ ῥίζαι κακωθεῖσαι παντάπασι, καὶ τὸ φυτὸν ἐμαράνθη.", "st": "Rom. 20.4"}, {"sp": "N", "t": "μῆνας μὲν οὖν οἱ Σαβῖνοι τοὺς Ῥωμαίων ἐδέξαντο, καὶ περὶ αὐτῶν ὅσα καλῶς εἶχεν, ἐν τῷ Νομᾶ βίῳ γέγραπται· θυρεοῖς δὲ τοῖς ἐκείνων ὁ Ῥωμύλος ἐχρήσατο, καὶ μετέβαλε τὸν ὁπλισμὸν ἑαυτοῦ τε καὶ τῶν Ῥωμαίων, Ἀργολικὰς πρότερον ἀσπίδας φορούντων. ἑορτῶν δὲ καὶ θυσιῶν ἀλλήλοις μετεῖχον, ἃς μὲν ἦγε τὰ γένη πρότερον οὐκ ἀνελόντες, ἑτέρας δὲ θέμενοι καινάς, ὧν ἥ τε τῶν Ματρωναλίων ἐστί, δοθεῖσα ταῖς γυναιξὶν ἐπὶ τῇ τοῦ πολέμου καταλύσει, καὶ ἡ τῶν Καρμενταλίων. τὴν δὲ Καρμένταν οἴονταί τινες Μοῖραν εἶναι κυρίαν ἀνθρώπων γενέσεως· διὸ καὶ τιμῶσιν αὐτὴν αἱ μητέρες· οἱ δὲ τὴν [τοῦ] Εὐάνδρου τοῦ Ἀρκάδος γυναῖκα, μαντικήν τινα καὶ φοιβαστικὴν ἐμμέτρων χρησμῶν γενομένην, Καρμένταν ἐπονομασθῆναι (τὰ γὰρ ἔπη κάρμενα καλοῦσι)· Νικοστράτη δ’ ἦν ὄνομα κύριον αὐτῇ. καὶ τοῦτο μὲν ὁμολογεῖται· τὴν δὲ Καρμένταν ἔνιοι πιθανώτερον ἀφερμηνεύουσιν οἷον ἐστερημένην νοῦ διὰ τὰς ἐν τοῖς ἐνθουσιασμοῖς παραφροσύνας. τὸ μὲν γὰρ στέρεσθαι καρῆρε, μέντεμ δὲ τὸν νοῦν ὀνομάζουσι. περὶ δὲ τῶν Παριλίων προείρηται. τὰ δὲ Λουπερκάλια τῷ μὲν χρόνῳ δόξειεν ἂν εἶναι καθάρσια· δρᾶται γὰρ ἐν ἡμέραις ἀποφράσι τοῦ Φεβρουαρίου μηνός, ὃν καθάρσιον ἄν τις ἑρμηνεύσειε, καὶ τὴν ἡμέραν ἐκείνην τὸ παλαιὸν ἐκάλουν Φεβράτην. τοὔνομα δὲ τῆς ἑορτῆς ἑλληνιστὶ σημαίνει Λύκαια, καὶ δοκεῖ διὰ τοῦτο παμπάλαιος ἀπ’ Ἀρκάδων εἶναι τῶν περὶ Εὔανδρον. ἀλλὰ τοῦτο μὲν κοινόν ἐστι· δύναται γὰρ ἀπὸ τῆς λυκαίνης γεγονέναι τοὔνομα. καὶ γὰρ ἀρχομένους τῆς περιδρομῆς τοὺς Λουπέρκους ὁρῶμεν ἐντεῦθεν, ὅπου τὸν Ῥωμύλον ἐκτεθῆναι λέγουσι. τὰ δὲ δρώμενα τὴν αἰτίαν ποιεῖ δυστόπαστον· σφάττουσι γὰρ αἶγας, εἶτα μειρακίων δυοῖν ἀπὸ γένους προσαχθέντων αὐτοῖς, οἱ μὲν ᾑμαγμένῃ μαχαίρᾳ τοῦ μετώπου θιγγάνουσιν, ἕτεροι δ’ ἀπομάττουσιν εὐθύς, ἔριον βεβρεγμένον γάλακτι προσφέροντες· γελᾶν δὲ δεῖ τὰ μειράκια μετὰ τὴν ἀπόμαξιν. ἐκ δὲ τούτου τὰ δέρματα τῶν αἰγῶν κατατεμόντες, διαθέουσιν ἐν περιζώσμασι γυμνοί, τοῖς σκύτεσι τὸν ἐμποδὼν παίοντες. αἱ δ’ ἐν ἡλικίᾳ γυναῖκες οὐ φεύγουσι τὸ παίεσθαι, νομίζουσαι πρὸς εὐτοκίαν καὶ κύησιν συνεργεῖν. ἴδιον δὲ τῆς ἑορτῆς τὸ καὶ κύνα θύειν τοὺς Λουπέρκους.", "st": "Rom. 21.1"}, {"sp": "N", "t": "βούτας δέ τις, αἰτίας μυθώδεις ἐν ἐλεγείοις περὶ τῶν Ῥωμαϊκῶν ἀναγράφων, φησὶ τοῦ Ἀμουλίου τοὺς περὶ τὸν Ῥωμύλον κρατήσαντας ἐλθεῖν δρόμῳ μετὰ χαρᾶς ἐπὶ τὸν τόπον, ἐν ᾧ νηπίοις οὖσιν αὐτοῖς ἡ λύκαινα θηλὴν ὑπέσχε, καὶ μίμημα τοῦ τότε δρόμου τὴν ἑορτὴν ἄγεσθαι, καὶ τρέχειν τοὺς ἀπὸ γένους τοὺς", "st": "Rom. 21.6"}, {"sp": "N", "t": "ἐμποδίους τύπτοντας, ὅπως τότε φάσγαν’ ἔχοντες ἐξ Ἄλβης ἔθεον Ῥωμύλος ἠδὲ Ῥέμος.", "st": "Rom. 21.6b"}, {"sp": "N", "t": "καὶ τὸ μὲν ξίφος ᾑμαγμένον προσφέρεσθαι τῷ μετώπῳ τοῦ τότε φόνου καὶ κινδύνου σύμβολον, τὴν δὲ διὰ τοῦ γάλακτος ἀποκάθαρσιν ὑπόμνημα τῆς τροφῆς αὐτῶν εἶναι. Γάιος δὲ Ἀκίλιος ἱστορεῖ πρὸ τῆς κτίσεως τὰ θρέμματα τῶν περὶ τὸν Ῥωμύλον ἀφανῆ γενέσθαι· τοὺς δὲ τῷ Φαύνῳ προσευξαμένους ἐκδραμεῖν γυμνοὺς ἐπὶ τὴν ζήτησιν, ὅπως ὑπὸ τοῦ ἱδρῶτος μὴ ἐνοχλοῖντο· καὶ διὰ τοῦτο γυμνοὺς περιτρέχειν τοὺς Λουπέρκους. τὸν δὲ κύνα φαίη τις ἄν, εἰ μὲν ἡ θυσία καθαρμός ἐστι, θύεσθαι καθαρσίῳ χρωμένων αὐτῷ· καὶ γὰρ Ἕλληνες ἔν τε τοῖς καθαρσίοις σκύλακας ἐκφέρουσι καὶ πολλαχοῦ χρῶνται τοῖς λεγομένοις περισκυλακισμοῖς· εἰ δὲ τῇ λυκαίνῃ χαριστήρια ταῦτα καὶ τροφεῖα καὶ σωτήρια Ῥωμύλου τελοῦσιν, οὐκ ἀτόπως ὁ κύων σφάττεται· λύκοις γάρ ἐστι πολέμιος· εἰ μὴ νὴ Δία κολάζεται τὸ ζῷον ὡς παρενοχλοῦν τοὺς Λουπέρκους ὅταν περιθέωσι.", "st": "Rom. 21.7"}, {"sp": "N", "t": "λέγεται δὲ καὶ τὴν περὶ τὸ πῦρ ἁγιστείαν Ῥωμύλον καταστῆσαι πρῶτον, ἀποδείξαντα παρθένους ἱερὰς Ἑστιάδας προσαγορευομένας. οἱ δὲ τοῦτο μὲν εἰς Νομᾶν ἀναφέρουσι, τὰ δ’ ἄλλα τὸν Ῥωμύλον θεοσεβῆ διαφερόντως, ἔτι δὲ μαντικὸν ἱστοροῦσι γενέσθαι, καὶ φορεῖν ἐπὶ μαντικῇ τὸ καλούμενον λίτυον· ἔστι δὲ καμπύλη ῥάβδος, ᾗ τὰ πλινθία καθεζομένους ἐπ’ οἰωνῶν διαγράφειν. τοῦτο δ’ ἐν Παλατίῳ φυλαττόμενον ἀφανισθῆναι, περὶ τὰ Κελτικὰ τῆς πόλεως ἁλούσης· εἶτα μέντοι τῶν βαρβάρων ἐκπεσόντων εὑρεθῆναι κατὰ τέφρας βαθείας, ἀπαθὲς ὑπὸ τοῦ πυρὸς ἐν πᾶσι τοῖς ἄλλοις ἀπολωλόσι καὶ διεφθαρμένοις.", "st": "Rom. 22.1"}, {"sp": "N", "t": "ἔθηκε δὲ καὶ νόμους τινάς, ὧν σφοδρὸς μέν ἐστιν ὁ γυναικὶ μὴ διδοὺς ἀπολείπειν ἄνδρα, γυναῖκα δὲ διδοὺς ἐκβάλλειν ἐπὶ φαρμακείᾳ τέκνων ἢ κλειδῶν ὑποβολῇ καὶ μοιχευθεῖσαν· εἰ δ’ ἄλλως τις ἀποπέμψαιτο, τῆς οὐσίας αὐτοῦ τὸ μὲν τῆς γυναικὸς εἶναι, τὸ δὲ τῆς Δήμητρος ἱερὸν κελεύων· τὸν δ’ ἀποδόμενον γυναῖκα θύεσθαι χθονίοις θεοῖς. ἴδιον δὲ τὸ μηδεμίαν δίκην κατὰ πατροκτόνων ὁρίσαντα, πᾶσαν ἀνδροφονίαν πατροκτονίαν προσειπεῖν, ὡς τούτου μὲν ὄντος ἐναγοῦς, ἐκείνου δ’ ἀδυνάτου. καὶ μέχρι χρόνων πολλῶν ἔδοξεν ὀρθῶς ἀπογνῶναι τὴν τοιαύτην ἀδικίαν· οὐδεὶς γὰρ ἔδρασε τοιοῦτον οὐδὲν ἐν Ῥώμῃ σχεδὸν ἐτῶν ἑξακοσίων διαγενομένων, ἀλλὰ πρῶτος μετὰ τὸν Ἀννιβιακὸν πόλεμον ἱστορεῖται Λεύκιος Ὅστιος πατροκτόνος γενέσθαι. ταῦτα μὲν οὖν ἱκανὰ περὶ τούτων.", "st": "Rom. 22.3"}, {"sp": "N", "t": "ἔτει δὲ πέμπτῳ τῆς Τατίου βασιλείας οἰκεῖοί τινες αὐτοῦ καὶ συγγενεῖς πρέσβεσιν ἀπὸ Λαυρέντου βαδίζουσιν εἰς Ῥώμην ἐντυχόντες καθ’ ὁδόν, ἐπεχείρουν ἀφαιρεῖσθαι τὰ χρήματα βίᾳ, καὶ μὴ προϊεμένους ἀλλ’ ἀμυνομένους ἀνεῖλον. ἔργου δὲ δεινοῦ τολμηθέντος, ὁ μὲν Ῥωμύλος εὐθὺς δεῖν ᾤετο κολάζεσθαι τοὺς ἀδικήσαντας, ὁ δὲ Τάτιος ἐξέκρουε καὶ παρῆγε. καὶ τοῦτο μόνον αὐτοῖς ὑπῆρξεν αἴτιον ἐμφανοῦς διαφορᾶς· τὰ δ’ ἄλλα κατακοσμοῦντες ἑαυτούς, ὡς ἔνι μάλιστα κοινῶς ἐχρῶντο καὶ μεθ’ ὁμονοίας τοῖς πράγμασιν. οἱ δὲ τῶν ἀνῃρημένων οἰκεῖοι πάσης ἐξειργόμενοι δίκης νομίμου διὰ τὸν Τάτιον, ἀποκτιννύουσιν αὐτὸν ἐν Λαβινίῳ θύοντα μετὰ Ῥωμύλου προσπεσόντες, τὸν δὲ Ῥωμύλον ὡς δίκαιον ἄνδρα προὔπεμψαν εὐφημοῦντες. ὁ δὲ τὸ μὲν σῶμα τοῦ Τατίου κομίσας ἐντίμως ἔθαψε, καὶ κεῖται περὶ τὸ καλούμενον Ἀρμιλούστριον ἐν Ἀουεντίνῳ, τῆς δὲ δίκης τοῦ φόνου παντάπασιν ἠμέλησεν. ἔνιοι δὲ τῶν συγγραφέων ἱστοροῦσι, τὴν μὲν πόλιν τῶν Λαυρεντίων φοβηθεῖσαν ἐκδιδόναι τοὺς αὐτόχειρας Τατίου, τὸν δὲ Ῥωμύλον ἀφεῖναι, φήσαντα φόνον φόνῳ λελύσθαι. τοῦτο δὲ λόγον μέν τινα παρέσχε καὶ ὑποψίαν, ὡς ἀσμένῳ γέγονεν αὐτῷ τὸ τοῦ συνάρχοντος ἀπαλλαγῆναι, τῶν δὲ πραγμάτων οὐδὲν διετάραξεν, οὐδὲ διεστασίασε τοὺς Σαβίνους, ἀλλ’ οἱ μὲν εὐνοίᾳ τῇ πρὸς αὐτόν, οἱ δὲ φόβῳ τῆς δυνάμεως, οἱ δ’ ὡς θεῶν χρώμενον εἰς πᾶν εὐνοίᾳν, θαυμάζοντες διετέλουν.", "st": "Rom. 23.1"}, {"sp": "N", "t": "ἐθαύμαζον δὲ πολλοὶ καὶ τῶν ἐκτὸς ἀνθρώπων τὸν Ῥωμύλον, οἱ δὲ προγενέστεροι Λατῖνοι πέμψαντες αὐτῷ φιλίαν ἐποιήσαντο καὶ συμμαχίαν. Φιδήνας δ’ εἷλεν, ἀστυγείτονα τῆς Ῥώμης πόλιν, ὡς μὲν ἔνιοί φασιν, ἐξαίφνης τοὺς ἱππέας πέμψας καὶ κελεύσας ὑποτεμεῖν τῶν πυλῶν τοὺς στρόφιγγας, εἶτ’ ἐπιφανεὶς αὐτὸς ἀπροσδοκήτως· ἕτεροι δὲ λέγουσι προτέρους ἐκείνους ἐμβαλόντας ἐλάσασθαί τε λείαν καὶ καθυβρίσαι πολλὰ τὴν χώραν καὶ τὸ προάστειον, ἐνέδρας δὲ τὸν Ῥωμύλον θέμενον αὐτοῖς καὶ διαφθείραντα πολλοὺς λαβεῖν τὴν πόλιν. οὐ μὴν ἀνεῖλεν οὐδὲ κατέσκαψεν, ἀλλὰ Ῥωμαίων ἐποίησεν ἀποικίαν, δισχιλίους καὶ πεντακοσίους ἀποστείλας οἰκήτορας εἰδοῖς Ἀπριλίαις.", "st": "Rom. 23.5"}, {"sp": "N", "t": "ἐκ τούτου λοιμὸς ἐμπίπτει, θανάτους μὲν αἰφνιδίους ἀνθρώποις ἄνευ νόσων ἐπιφέρων, ἁπτόμενος δὲ καὶ καρπῶν ἀφορίαις καὶ θρεμμάτων ἀγονίαις. ὕσθη δὲ καὶ σταγόσιν αἵματος ἡ πόλις, ὥστε πολλὴν προσγενέσθαι τοῖς ἀναγκαίοις πάθεσι δεισιδαιμονίαν. ἐπεὶ δὲ καὶ τοῖς τὸ Λαύρεντον οἰκοῦσιν ὅμοια συνέβαινεν, ἤδη παντάπασιν ἐδόκει τῶν ἐπὶ Τατίῳ συγκεχυμένων δικαίων ἐπί τε τοῖς πρέσβεσι φονευθεῖσι μήνιμα δαιμόνιον ἀμφοτέρας ἐλαύνειν τὰς πόλεις. ἐκδοθέντων δὲ τῶν φονέων καὶ κολασθέντων παρ’ ἀμφοτέροις, ἐλώφησεν ἐπιδήλως τὰ δεινά, καὶ καθαρμοῖς ὁ Ῥωμύλος ἥγνισε τὰς πόλεις, οὓς ἔτι νῦν ἱστοροῦσιν ἐπὶ τῆς Φερεντίνης πύλης συντελεῖσθαι.", "st": "Rom. 24.1"}, {"sp": "N", "t": "πρὶν δὲ λῆξαι τὸν λοιμόν, ἐπέθεντο Καμέριοι Ῥωμαίοις καὶ κατέδραμον τὴν χώραν, ὡς ἀδυνάτων ἀμύνεσθαι διὰ τὸ πάθος. εὐθὺς οὖν ὁ Ῥωμύλος ἐστράτευσεν ἐπ’ αὐτούς, καὶ μάχῃ κρατήσας ἑξακισχιλίους ἀπέκτεινε, καὶ τὴν πόλιν ἑλών, τοὺς μὲν ἡμίσεις τῶν περιγενομένων εἰς Ῥώμην ἐξῴκισε, τῶν δ’ ὑπομενόντων διπλασίους ἐκ Ῥώμης μετῴκισεν εἰς τὴν Καμερίαν Σεξτιλίαις καλάνδαις. τοσοῦτον αὐτῷ περιῆν πολιτῶν ἑκκαίδεκα ἔτη σχεδὸν οἰκοῦντι τὴν Ῥώμην. ἐν δὲ τοῖς ἄλλοις λαφύροις καὶ χαλκοῦν ἐκόμισε τέθριππον ἐκ Καμερίας· τοῦτο δὲ ἀνέστησεν ἐν τῷ ἱερῷ τοῦ Ἡφαίστου, ποιησάμενος ἑαυτὸν ὑπὸ Νίκης στεφανούμενον.", "st": "Rom. 24.3"}, {"sp": "N", "t": "οὕτω δὲ ῥωννυμένοις τοῖς πράγμασιν οἱ μὲν ἀσθενέστεροι τῶν προσοίκων ὑπεδύοντο καὶ τυγχάνοντες ἀδείας ἠγάπων, οἱ δὲ δυνατοὶ δεδιότες καὶ φθονοῦντες, οὐκ ᾤοντο δεῖν περιορᾶν, ἀλλ’ ἐνίστασθαι τῇ αὐξήσει καὶ κολούειν τὸν Ῥωμύλον. πρῶτοι δὲ Τυρρηνῶν Οὐήϊοι, χώραν κεκτημένοι πολλὴν καὶ πόλιν μεγάλην οἰκοῦντες, ἀρχὴν ἐποιήσαντο πολέμου Φιδήνην ἀπαιτεῖν ὡς προσήκουσαν αὐτοῖς. τὸ δ’ οὐκ ἄδικον ἦν μόνον, ἀλλὰ καὶ γελοῖον, ὅτι κινδυνεύουσι τότε καὶ πολεμουμένοις οὐ προσαμύναντες, ἀλλ’ ἐάσαντες ἀπολέσθαι τοὺς ἄνδρας, οἰκίας καὶ γῆν ἀπαιτοῖεν ἄλλων ἐχόντων. καθυβρισθέντες οὖν ὑπὸ τοῦ Ῥωμύλου [ἐν] ταῖς ἀποκρίσεσι, δίχα διεῖλον ἑαυτούς, καὶ τῷ μὲν ἐπέκειντο τῷ Φιδηνατῶν στρατεύματι, τῷ δὲ πρὸς Ῥωμύλον ἀπήντων. πρὸς μὲν οὖν Φιδήναις δισχιλίους Ῥωμαίων κρατήσαντες ἀπέκτειναν, ὑπὸ Ῥωμύλου δὲ νικηθέντες ὑπὲρ ὀκτακισχιλίους ἀπέβαλον. αὖθις δὲ περὶ Φιδήνην ἐμαχέσαντο, καὶ τὸ μὲν πλεῖστον ἔργον αὐτοῦ Ῥωμύλου γενέσθαι, τέχνην τε μετὰ τόλμης πᾶσαν ἐπιδειξαμένου, ῥώμῃ τε καὶ ποδωκείᾳ πολὺ δόξαντος ἀνθρωπίνης κρείττονι κεχρῆσθαι, πάντες ὁμολογοῦσι, τὸ δ’ ὑπ’ ἐνίων λεγόμενον κομιδῇ μυθῶδές ἐστι, μᾶλλον δ’ ὅλως ἄπιστον, ὅτι μυρίων καὶ τετρακισχιλίων πεσόντων ὑπερημίσεις ἦσαν οὓς αὐτὸς ἰδίᾳ χειρὶ Ῥωμύλος ἔκτεινεν, ὅπου καὶ Μεσσήνιοι κόμπῳ χρήσασθαι δοκοῦσι περὶ Ἀριστομένους λέγοντες, ὡς τρὶς ἑκατομφόνια θύσειεν ἀπὸ Λακεδαιμονίων.", "st": "Rom. 25.1"}, {"sp": "N", "t": "γενομένης δὲ τῆς τροπῆς, ἀφεὶς φεύγειν τοὺς περιόντας ὁ Ῥωμύλος ἐπ’ αὐτὴν ἐχώρει τὴν πόλιν· οἱ δ’ οὐκ ἠνέσχοντο μεγάλης συμφορᾶς γενομένης, ἀλλὰ δεηθέντες ὁμολογίαν ἐποιήσαντο καὶ φιλίαν εἰς ἔτη ἑκατόν, χώραν τε πολλὴν προέμενοι τῆς ἑαυτῶν, ἣν Σεπτεμπάγιον καλοῦσιν, ὅπερ ἐστὶν ἑπταμόριον, καὶ τῶν παρὰ τὸν ποταμὸν ἐκστάντες ἁλοπηγίων, καὶ πεντήκοντα τῶν ἀρίστων ὁμήρους ἐγχειρίσαντες. ἐθριάμβευσε δὲ καὶ ἀπὸ τούτων εἰδοῖς Ὀκτωβρίαις, ἄλλους τε πολλοὺς αἰχμαλώτους ἔχων καὶ τὸν ἡγεμόνα τῶν Βηίων, ἄνδρα πρεσβύτην, ἀφρόνως δόξαντα καὶ παρ’ ἡλικίαν ἀπείρως τοῖς πράγμασι κεχρῆσθαι. διὸ καὶ νῦν ἔτι θύοντες ἐπινίκια, γέροντα μὲν ἄγουσι δι’ ἀγορᾶς εἰς Καπιτώλιον ἐν περιπορφύρῳ, βοῦλλαν αὐτῷ παιδικὴν άψαντες, κηρύττει δ’ ὁ κῆρυξ Σαρδιανοὺς ὠνίους. Τυρρηνοὶ γὰρ ἄποικοι Σαρδιανῶν λέγονται, Τυρρηνικὴ δὲ πόλις οἱ Οὐήϊοι.", "st": "Rom. 25.4"}, {"sp": "N", "t": "τοῦτον ἔσχατον πόλεμον ὁ Ῥωμύλος ἐπολέμησεν. εἶθ’ ὃ πολλοί, μᾶλλον δὲ πλὴν ὀλίγων πάσχουσι πάντες οἱ μεγάλαις καὶ παραλόγοις ἀρθέντες εὐτυχίαις εἰς δύναμιν καὶ ὄγκον, οὐδ’ αὐτὸς διέφυγε παθεῖν, ἀλλ’ ἐκτεθαρρηκὼς τοῖς πράγμασι καὶ βαρυτέρῳ φρονήματι χρώμενος, ἐξίστατο τοῦ δημοτικοῦ, καὶ παρήλλαττεν εἰς μοναρχίαν ἐπαχθῆ καὶ λυποῦσαν ἀπὸ τοῦ σχήματος πρῶτον ᾧ κατεσχημάτιζεν ἑαυτόν. ἁλουργῆ μὲν γὰρ ἐνεδύετο χιτῶνα καὶ τήβεννον ἐφόρει περιπόρφυρον, ἐν θρόνῳ δ’ ἀνακλίτῳ καθήμενος ἐχρημάτιζεν. ἦσαν δὲ περὶ αὐτὸν ἀεὶ τῶν νέων οἱ καλούμενοι Κέλερες ἀπὸ τῆς περὶ τὰς ὑπουργίας ὀξύτητος. ἐβάδιζον δὲ πρόσθεν ἕτεροι βακτηρίαις ἀνείργοντες τὸν ὄχλον, ὑπεζωσμένοι δ’ ἱμάντας ὥστε συνδεῖν εὐθὺς οὓς προστάξειε.", "st": "Rom. 26.1"}, {"sp": "N", "t": "τὸ δὲ δῆσαι Λατῖνοι πάλαι μὲν λιγᾶρε, νῦν δ’ ἀλλιγᾶρε καλοῦσιν· ὅθεν οἵ τε ῥαβδοῦχοι λικτώρεις αἵ τε ῥάβδοι βάκιλα καλοῦνται διὰ τὸ χρῆσθαι τότε βακτηρίαις. εἰκὸς δὲ λικτώρεις ἐντιθεμένου τοῦ κάππα νῦν ὀνομάζεσθαι, πρότερον [γὰρ] λιτώρεις, ἑλληνιστὶ δὲ λειτουργοὺς ὄντας· λήιτον γὰρ τὸ δημόσιον ἔτι νῦν Ἕλληνες καὶ λαὸν τὸ πλῆθος ὀνομάζουσιν.", "st": "Rom. 26.3"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῦ πάππου Νομήτορος ἐν Ἄλβῃ τελευτήσαντος, αὐτῷ βασιλεύειν προσῆκον, εἰς μέσον ἔθηκε τὴν πολιτείαν δημαγωγῶν, καὶ κατ’ ἐνιαυτὸν ἀπεδείκνυεν ἄρχοντα τοῖς Ἀλβανοῖς, ἐδίδαξε δὲ καὶ τοὺς ἐν Ῥώμῃ δυνατοὺς ἀβασίλευτον ζητεῖν καὶ αὐτόνομον πολιτείαν, ἀρχομένους ἐν μέρει καὶ ἄρχοντας. οὐδὲ γὰρ οἱ καλούμενοι πατρίκιοι πραγμάτων μετεῖχον, ἀλλ’ ὄνομα καὶ σχῆμα περιῆν ἔντιμον αὐτοῖς, ἔθους ἕνεκα μᾶλλον ἢ γνώμης ἀθροιζομένοις εἰς τὸ βουλευτήριον· εἶτα σιγῇ προστάττοντος ἠκροῶντο, καὶ τῷ πρότεροι τὸ δεδογμένον ἐκείνῳ πυθέσθαι τῶν πολλῶν πλέον ἔχοντες ἀπηλλάττοντο. καὶ τἆλλα μὲν ἦν ἐλάττονα· τῆς δὲ γῆς τὴν δορίκτητον αὐτὸς ἐφ’ ἑαυτοῦ δασάμενος τοῖς στρατιώταις, καὶ τοὺς ὁμήρους τοῖς Βηίοις ἀποδούς, οὔτε πεισθέντων οὔτε βουλομένων ἐκείνων, ἔδοξε κομιδῇ τὴν γερουσίαν προπηλακίζειν. ὅθεν εἰς ὑποψίαν καὶ διαβολὴν ἐνέπεσε παραλόγως ἀφανισθέντος αὐτοῦ μετ’ ὀλίγον χρόνον. ἠφανίσθη δὲ νώναις Ἰουλίαις ὡς νῦν ὀνομάζουσιν, ὡς δὲ τότε, Κυντιλίαις, οὐδὲν εἰπεῖν βέβαιον οὐδ’ ὁμολογούμενον πυθέσθαι περὶ τῆς τελευτῆς ἀπολιπών, ἀλλ’ ἢ τὸν χρόνον, ὡς προείρηται. δρᾶται γὰρ ἔτι νῦν ὅμοια τῷ τότε πάθει πολλὰ κατὰ τὴν ἡμέραν ἐκείνην.", "st": "Rom. 27.1"}, {"sp": "N", "t": "οὐ δεῖ δὲ θαυμάζειν τὴν ἀσάφειαν, ὅπου Σκηπίωνος Ἀφρικανοῦ μετὰ δεῖπνον οἴκοι τελευτήσαντος οὐκ ἔσχε πίστιν οὐδ’ ἔλεγχον ὁ τρόπος τῆς τελευτῆς, ἀλλ’ οἱ μὲν αὐτομάτως ὄντα φύσει νοσώδη καμεῖν λέγουσιν, οἱ δ’ αὐτὸν ὑφ’ ἑαυτοῦ φαρμάκοις ἀποθανεῖν, οἱ δὲ τοὺς ἐχθροὺς τὴν ἀναπνοὴν ἀπολαβεῖν αὐτοῦ νύκτωρ παρεισπεσόντας. καίτοι Σκηπίων ἔκειτο νεκρὸς ἐμφανὴς ἰδεῖν πᾶσι, καὶ τὸ σῶμα παρεῖχε πᾶσιν ὁρώμενον ὑποψίαν τινὰ τοῦ πάθους καὶ κατανόησιν· Ῥωμύλου δ’ ἄφνω μεταλλάξαντος οὔτε μέρος ὤφθη σώματος οὔτε λείψανον ἐσθῆτος. ἀλλ’ οἱ μὲν εἴκαζον ἐν τῷ ἱερῷ τοῦ Ἡφαίστου τοὺς βουλευτὰς ἐπαναστάντας αὐτῷ καὶ διαφθείραντας, νείμαντας τὸ σῶμα καὶ μέρος ἕκαστον ἐνθέμενον εἰς τὸν κόλπον ἐξενεγκεῖν· ἕτεροι δ’ οἴονται μήτ’ ἐν τῷ ἱερῷ τοῦ Ἡφαίστου μήτε μόνων τῶν βουλευτῶν παρόντων γενέσθαι τὸν ἀφανισμόν, ἀλλὰ τυχεῖν μὲν ἔξω περὶ τὸ καλούμενον αἰγὸς [ἢ ζορκὸς] ἕλος ἐκκλησίαν ἄγοντα τὸν Ῥωμύλον, ἄφνω δὲ θαυμαστὰ καὶ κρείττονα λόγου περὶ τὸν ἀέρα πάθη γενέσθαι καὶ μεταβολὰς ἀπίστους· τοῦ μὲν γὰρ ἡλίου τὸ φῶς ἐκλιπεῖν, νύκτα δὲ κατασχεῖν οὐ πρᾳεῖαν οὐδ’ ἥσυχον, ἀλλὰ βροντάς τε δεινὰς καὶ πνοὰς ἀνέμων ζάλην ἐλαυνόντων πανταχόθεν ἔχουσαν· ἐν δὲ τούτῳ τὸν μὲν πολὺν ὄχλον σκεδασθέντα φυγεῖν, τοὺς δὲ δυνατοὺς συστραφῆναι μετ’ ἀλλήλων· ἐπεὶ δ’ ἔληξεν ἡ ταραχὴ καὶ τὸ φῶς ἐξέλαμψε, καὶ τῶν πολλῶν εἰς ταὐτὸ πάλιν συνερχομένων ζήτησις ἦν τοῦ βασιλέως καὶ πόθος, οὐκ ἐᾶν τοὺς δυνατοὺς ἐξετάζειν οὐδὲ πολυπραγμονεῖν, ἀλλὰ τιμᾶν παρακελεύεσθαι πᾶσι καὶ σέβεσθαι Ῥωμύλον, ὡς ἀνηρπασμένον εἰς θεοὺς καὶ θεὸν εὐμενῆ γενησόμενον αὐτοῖς ἐκ χρηστοῦ βασιλέως. τοὺς μὲν οὖν πολλοὺς ταῦτα πειθομένους καὶ χαίροντας ἀπαλλάττεσθαι, μετ’ ἐλπίδων ἀγαθῶν προσκυνοῦντας· εἶναι δέ τινας οἳ τὸ πρᾶγμα πικρῶς καὶ δυσμενῶς ἐξελέγχοντες ἐτάραττον τοὺς πατρικίους καὶ διέβαλλον, ὡς ἀβέλτερα τὸν δῆμον ἀναπείθοντας, αὐτοὺς δὲ τοῦ βασιλέως αὐτόχειρας ὄντας.", "st": "Rom. 27.4"}, {"sp": "N", "t": "οὕτως οὖν ἄνδρα τῶν πατρικίων γένει πρῶτον ἤθει τε δοκιμώτατον αὐτῷ τε Ῥωμύλῳ πιστὸν καὶ συνήθη, τῶν ἀπ’ Ἄλβης ἐποίκων, Ἰούλιον Πρόκλον, εἰς ἀγορὰν παρελθόντα καὶ τῶν ἁγιωτάτων ἔνορκον ἱερῶν ἁψάμενον εἰπεῖν ἐν πᾶσιν, ὡς ὁδὸν αὐτῷ βαδίζοντι Ῥωμύλος ἐξ ἐναντίας προσιὼν φανείη, καλὸς μὲν ὀφθῆναι καὶ μέγας ὡς οὔποτε πρόσθεν, ὅπλοις δὲ λαμπροῖς καὶ φλέγουσι κεκοσμημένος. αὐτὸς μὲν οὖν ἐκπλαγεὶς πρὸς τὴν ὄψιν ὦ βασιλεῦ, φάναι, τί δὴ παθὼν ἢ διανοηθείς, ἡμᾶς μὲν ἐν αἰτίαις πεποίηκας ἀδίκοις καὶ πονηραῖς, πᾶσαν δὲ τὴν πόλιν ὀρφανὴν ἐν μυρίῳ πένθει προλέλοιπας; ἐκεῖνον δ’ ἀποκρίνασθαι· θεοῖς ἔδοξεν ὦ Πρόκλε τοσοῦτον ἡμᾶς γενέσθαι μετ’ ἀνθρώπων χρόνον, ἐκεῖθεν ὄντας, καὶ πόλιν ἐπ’ ἀρχῇ καὶ δόξῃ μεγίστῃ κτίσαντας, αὖθις οἰκεῖν οὐρανόν. ἀλλὰ χαῖρε καὶ φράζε Ῥωμαίοις, ὅτι σωφροσύνην μετ’ ἀνδρείας ἀσκοῦντες ἐπὶ πλεῖστον ἀνθρωπίνης ἀφίξονται δυνάμεως. ἐγὼ δ’ ὑμῖν εὐμενὴς ἔσομαι δαίμων Κυρῖνος. ταῦτα πιστὰ μὲν εἶναι τοῖς Ῥωμαίοις ἐδόκει διὰ τὸν τρόπον τοῦ λέγοντος καὶ διὰ τὸν ὅρκον· οὐ μὴν ἀλλὰ καὶ δαιμόνιόν τι συνεφάψασθαι πάθος ὅμοιον ἐνθουσιασμῷ· μηδένα γὰρ ἀντειπεῖν, ἀλλὰ πᾶσαν ὑπόνοιαν καὶ διαβολὴν ἀφέντας εὔχεσθαι Κυρίνῳ καὶ θεοκλυτεῖν ἐκεῖνον.", "st": "Rom. 28.1"}, {"sp": "N", "t": "ἔοικε μὲν οὖν ταῦτα τοῖς ὑφ’ Ἑλλήνων περί τ’ Ἀριστέου τοῦ Προικοννησίου καὶ Κλεομήδους τοῦ Ἀστυπαλαιέως μυθολογουμένοις. Ἀριστέαν μὲν γὰρ ἔν τινι κναφείῳ τελευτῆσαί φασι, καὶ τὸ σῶμα μετιόντων αὐτοῦ τῶν φίλων ἀφανὲς οἴχεσθαι· λέγειν δέ τινας εὐθὺς ἐξ ἀποδημίας ἥκοντας ἐντυχεῖν Ἀριστέᾳ τὴν ἐπὶ Κρότωνος πορευομένῳ. Κλεομήδη δὲ ῥώμῃ καὶ μεγέθει σώματος ὑπερφυᾶ γενόμενον, ἔμπληκτόν τε τῷ τρόπῳ καὶ μανικὸν ὄντα, πολλὰ δρᾶν βίαια, καὶ τέλος ἔν τινι διδασκαλείῳ παίδων τὸν ὑπερείδοντα τὴν ὀροφὴν κίονα πατάξαντα τῇ χειρὶ κλάσαι μέσον καὶ τὴν στέγην καταβαλεῖν. ἀπολομένων δὲ τῶν παίδων διωκόμενον, εἰς κιβωτὸν καταφυγεῖν μεγάλην καὶ τὸ πῶμα κατακλείσαντα συνέχειν ἐντός, ὥστ’ ἀποσπάσαι μὴ δύνασθαι πολλοὺς ὁμοῦ βιαζομένους· κατασχίσαντας δὲ τὴν κιβωτόν, οὔτε ζῶντα τὸν ἄνθρωπον εὑρεῖν οὔτε νεκρόν. ἐκπλαγέντας οὖν ἀποστεῖλαι θεοπρόπους εἰς Δελφούς, οἷς τὴν Πυθίαν εἰπεῖν", "st": "Rom. 28.4"}, {"sp": "N", "t": "ἔσχατος ἡρώων Κλεομήδης Ἀστυπαλαιεύς.", "st": "Rom. 28.4b"}, {"sp": "N", "t": "λέγεται δὲ καὶ τὸν Ἀλκμήνης ἐκκομιζομένης νεκρὸν ἄδηλον γενέσθαι, λίθον δὲ φανῆναι κείμενον ἐπὶ τῆς κλίνης, καὶ ὅλως πολλὰ τοιαῦτα μυθολογοῦσι, παρὰ τὸ εἰκὸς ἐκθειάζοντες τὰ θνητὰ τῆς φύσεως ἅμα τοῖς θείοις.", "st": "Rom. 28.6"}, {"sp": "N", "t": "ἀπογνῶναι μὲν οὖν παντάπασι τὴν θειότητα τῆς ἀρετῆς ἀνόσιον καὶ ἀγεννές, οὐρανῷ δὲ μειγνύειν γῆν ἀβέλτερον. φατέον οὖν, ἐχομένοις τῆς ἀσφαλείας, κατὰ Πίνδαρον, ὡς", "st": "Rom. 28.6b"}, {"sp": "N", "t": "σῶμα μὲν πάντων ἕπεται θανάτῳ περισθενεῖ, ζῳὸν δ’ ἔτι λείπεται αἰῶνος εἴδωλον· τὸ γάρ ἐστι μόνον ἐκ θεῶν.", "st": "Rom. 28.6c"}, {"sp": "N", "t": "ἥκει γὰρ ἐκεῖθεν, ἐκεῖ δ’ ἄνεισιν, οὐ μετὰ σώματος, ἀλλ’ ἐὰν ὅτι μάλιστα σώματος ἀπαλλαγῇ καὶ διακριθῇ καὶ γένηται καθαρὸν παντάπασι καὶ ἄσαρκον καὶ ἁγνόν. αὕη γὰρ ψυχὴ ἀρίστη, καθ’ Ἡράκλειτον, ὥσπερ ἀστραπὴ νέφους διαπταμένη τοῦ σώματος. ἡ δὲ σώματι πεφυρμένη καὶ περίπλεως σώματος, οἷον ἀναθυμίασις ἐμβριθὴς καὶ ὁμιχλώδης, δυσέξαπτός ἐστι καὶ δυσανακόμιστος. οὐδὲν οὖν δεῖ τὰ σώματα τῶν ἀγαθῶν συναναπέμπειν παρὰ φύσιν εἰς οὐρανόν, ἀλλὰ τὰς ἀρετὰς καὶ τὰς ψυχὰς παντάπασιν οἴεσθαι κατὰ φύσιν καὶ δίκην θείαν ἐκ μὲν ἀνθρώπων εἰς ἥρωας, ἐκ δ’ ἡρώων εἰς δαίμονας, ἐκ δὲ δαιμόνων, ἂν τέλεον ὥσπερ ἐν τελετῇ καθαρθῶσι καὶ ὁσιωθῶσιν, ἅπαν ἀποφυγοῦσαι τὸ θνητὸν καὶ παθητικόν, οὐ νόμῳ πόλεως, ἀλλ’ ἀληθείᾳ καὶ κατὰ τὸν εἰκότα λόγον εἰς θεοὺς ἀναφέρεσθαι, τὸ κάλλιστον καὶ μακαριώτατον τέλος ἀπολαβούσας.", "st": "Rom. 28.7"}, {"sp": "N", "t": "τὴν δὲ γενομένην ἐπωνυμίαν τῷ Ῥωμύλῳ τὸν Κυρῖνον οἱ μὲν Ἐνυάλιον προσαγορεύουσιν, οἱ δὲ πολίτην, ὅτι καὶ τοὺς πολίτας Κυρίτας ὠνόμαζον, οἱ δὲ τὴν αἰχμὴν ἢ τὸ δόρυ τοὺς παλαιοὺς κύριν ὀνομάζειν, καὶ Κυρίτιδος Ἥρας ἄγαλμα καλεῖν ἐπ’ αἰχμῆς ἱδρυμένον, ἐν δὲ τῇ Ῥηγίᾳ δόρυ καθιδρυμένον Ἄρεα προσαγορεύειν καὶ δόρατι τοὺς ἐν πολέμοις ἀριστεύοντας γεραίρειν· ὡς οὖν ἀρήιόν τινα τὸν Ῥωμύλον ἢ αἰχμητὴν θεὸν ὀνομασθῆναι Κυρῖνον. ἱερὸν μὲν οὖν αὐτοῦ κατεσκευασμένον ἐστὶν ἐν τῷ λόφῳ τῷ Κυρίνᾳ προσαγορευομένῳ δι’ ἐκεῖνον· ᾗ δ’ ἡμέρᾳ μετήλλαξεν, ὄχλου φυγὴ καλεῖται καὶ νῶναι Καπρατῖναι διὰ τὸ θύειν εἰς τὸ τῆς αἰγὸς ἕλος ἐκ πόλεως κατιόντας· τὴν γὰρ αἶγα κάπραν ὀνομάζουσιν. ἐξιόντες δὲ πρὸς τὴν θυσίαν πολλὰ τῶν ἐπιχωρίων ὀνομάτων φθέγγονται μετὰ βοῆς, οἷον Μάρκου, Λουκίου, Γαΐου, μιμούμενοι τὴν τότε τροπὴν καὶ ἀνάκλησιν ἀλλήλων μετὰ δέους καὶ ταραχῆς.", "st": "Rom. 29.1"}, {"sp": "N", "t": "ἔνιοι μέντοι τὸ μίμημα τοῦτό φασι μὴ φυγῆς, ἀλλ’ ἐπείξεως εἶναι καὶ σπουδῆς, εἰς αἰτίαν τοιαύτην ἀναφέροντες τὸν λόγον. ἐπεὶ Κελτοὶ τὴν Ῥώμην καταλαβόντες ἐξεκρούσθησαν ὑπὸ Καμίλλου, καὶ δι’ ἀσθένειαν ἡ πόλις οὐκέτι ῥᾳδίως ἑαυτὴν ἀνελάμβανεν, ἐστράτευσαν ἐπ’ αὐτὴν πολλοὶ τῶν Λατίνων, ἄρχοντα Λίβιον Ποστούμιον ἔχοντες. οὗτος δὲ καθίσας τὸν στρατὸν οὐ πρόσω τῆς Ῥώμης ἔπεμπε κήρυκα, βούλεσθαι λέγων τοὺς Λατίνους ἐκλιποῦσαν ἤδη τὴν παλαιὰν οἰκειότητα καὶ συγγένειαν ἐκζωπυρῆσαι, καιναῖς αὖθις ἀνακραθέντων ἐπιγαμίαις τῶν γενῶν. ἂν οὖν πέμψωσι παρθένους τε συχνὰς καὶ γυναικῶν τὰς ἀνάνδρους, εἰρήνην ἔσεσθαι καὶ φιλίαν αὐτοῖς, ὡς ὑπῆρξε πρὸς Σαβίνους πρότερον ἐκ τῶν ὁμοίων. ταῦτ’ ἀκούσαντες οἱ Ῥωμαῖοι τόν τε πόλεμον ἐφοβοῦντο, καὶ τὴν παράδοσιν τῶν γυναικῶν οὐδὲν αἰχμαλωσίας ἐπιεικέστερον ἔχειν ἐνόμιζον. ἀποροῦσι δ’ αὐτοῖς θεράπαινα Φιλωτίς, ὡς δ’ ἔνιοι λέγουσι Τουτόλα καλουμένη, συνεβούλευσε μηδέτερα ποιεῖν, ἀλλὰ χρησαμένους δόλῳ διαφυγεῖν ἅμα τὸν πόλεμον καὶ τὴν ἐξομήρευσιν. ἦν δ’ ὁ δόλος, αὐτήν τε τὴν Φιλωτίδα καὶ σὺν αὐτῇ θεραπαινίδας εὐπρεπεῖς κοσμήσαντας ὡς ἐλευθέρας ἀποστεῖλαι πρὸς τοὺς πολεμίους· εἶτα νύκτωρ τὴν Φιλωτίδα πυρσὸν ἆραι, τοὺς δὲ Ῥωμαίους ἐπελθεῖν μετὰ τῶν ὅπλων καὶ χρήσασθαι κοιμωμένοις τοῖς πολεμίοις. ταῦτα δ’ ἐδρᾶτο πεισθέντων τῶν Λατίνων, καὶ τὸν πυρσὸν ἀνέσχεν ἡ Φιλωτὶς ἔκ τινος ἐρινεοῦ, περισχοῦσα προκαλύμμασι καὶ παραπετάσμασιν ὄπισθεν, ὥστε τοῖς πολεμίοις ἀόρατον εἶναι τὸ φῶς, τοῖς δὲ Ῥωμαίοις κατάδηλον. ὡς οὖν ἐπεῖδον, εὐθὺς ἐξῄεσαν ἐπειγόμενοι καὶ διὰ τὴν ἔπειξιν ἀλλήλους περὶ τὰς πύλας ἀνακαλοῦντες πολλάκις. ἐμπεσόντες δὲ τοῖς πολεμίοις ἀπροσδοκήτως καὶ κρατήσαντες, ἐπινίκιον ἄγουσι τὴν ἑορτήν. καὶ Καπρατῖναι μὲν αἱ νῶναι καλοῦνται διὰ τὸν ἐρινεόν, καπρίφικον ὑπὸ Ῥωμαίων ὀνομαζόμενον. ἑστιῶσι δὲ τὰς γυναῖκας ἔξω συκῆς κλάδοις σκιαζομένας· αἱ δὲ θεραπαινίδες ἀγείρουσι περιιοῦσαι καὶ παίζουσιν, εἶτα πληγαῖς καὶ βολαῖς λίθων χρῶνται πρὸς ἀλλήλας, ὡς καὶ τότε τοῖς Ῥωμαίοις παραγενόμεναι καὶ συναγωνισάμεναι μαχομένοις.", "st": "Rom. 29.3"}, {"sp": "N", "t": "ταῦτ’ οὖν πολλοὶ προσίενται τῶν συγγραφέων, ἀλλὰ καὶ τὸ μεθ’ ἡμέραν χρῆσθαι τῇ ἀνακλήσει τῶν ὀνομάτων καὶ τὸ πρὸς τὸ ἕλος τὸ τῆς αἰγὸς ὡς ἐπὶ θυσίαν βαδίζοντας ἔοικε τῷ προτέρῳ λόγῳ προστίθεσθαι μᾶλλον, εἰ μὴ νὴ Δία τῆς αὐτῆς ἡμέρας ἐν χρόνοις ἑτέροις ἀμφότερα τὰ πάθη συνέτυχε γενέσθαι. λέγεται δὲ Ῥωμύλος τέσσαρα μὲν ἔτη καὶ πεντήκοντα γεγονώς, ὄγδοον δὲ βασιλεύων ἐκεῖνο καὶ τριακοστόν, ἐξ ἀνθρώπων ἀφανισθῆναι.", "st": "Rom. 29.7"}, {"sp": "HDR", "t": "Θησέως καὶ Ῥωμύλου σύγκρισις"}, {"sp": "N", "t": "ἃ μὲν οὖν ἄξια μνήμης πυθέσθαι περὶ Ῥωμύλου καὶ Θησέως συμβέβηκεν ἡμῖν, ταῦτ’ ἐστί. φαίνεται δὲ πρῶτον ὁ μὲν ἐκ προαιρέσεως, οὐδενὸς ἀναγκάζοντος, ἀλλ’ ἐξὸν ἀδεῶς ἐν Τροιζῆνι βασιλεύειν διαδεξάμενον ἀρχὴν οὐκ ἄδοξον, αὐτὸς ἀφ’ ἑαυτοῦ μεγάλων ὀρεχθείς· ὁ δὲ δουλείας φυγῇ παρούσης καὶ τιμωρίας ἐπιφερομένης, ἐκεῖνο τὸ τοῦ Πλάτωνος, ἀτεχνῶς ὑπὸ δέους ἀνδρεῖος γενόμενος, καὶ φόβῳ τοῦ τὰ ἔσχατα παθεῖν ἐπὶ τὸ δρᾶν μεγάλα δι’ ἀνάγκην παραγενόμενος. ἔπειτα τούτου μὲν ἔργον ἐστὶ τὸ μέγιστον ἀνελεῖν ἕνα τὸν Ἄλβης τύραννον, ἐκείνου δὲ πάρεργα καὶ προάγωνες ἦσαν ὁ Σκείρων, ὁ Σίνις, ὁ Προκρούστης, ὁ Κορυνήτης, οὓς ἀναιρῶν καὶ κολάζων ἀπήλαττε τὴν Ἑλλάδα δεινῶν τυράννων πρὶν ὅστις ἐστὶ γινώσκειν τοὺς ὑπ’ αὐτοῦ σῳζομένους, καὶ τῷ μὲν παρῆν ἀπραγμόνως κομίζεσθαι διὰ θαλάττης ἀδικουμένῳ μηδὲν ὑπὸ τῶν λῃστῶν, Ῥωμύλῳ δ’ οὐ παρῆν μὴ πράγματα ἔχειν Ἀμουλίου ζῶντος. μέγα δὲ τούτου τεκμήριον ὁ μὲν γὰρ οὐδὲν αὐτὸς ἀδικούμενος ὥρμησεν ὑπὲρ ἄλλων ἐπὶ τοὺς πονηρούς, οἱ δ’ ὅσον αὐτοὶ κακῶς οὐκ ἔπασχον ὑπὸ τοῦ τυράννου, περιεώρων ἀδικοῦντα πάντας. καὶ μὴν εἰ μέγα τὸ τρωθῆναι μαχόμενον Σαβίνοις καὶ ἀνελεῖν Ἄκρωνα καὶ πολλῶν μάχῃ κρατῆσαι πολεμίων, τούτοις μὲν ἔστι τοῖς ἔργοις κενταυρομαχίαν καὶ τὰ πρὸς Ἀμαζόνας παραβαλεῖν· ὃ δ’ ἐτόλμησε Θησεὺς περὶ τὸν Κρητικὸν δασμόν, εἴτε τινὶ θηρίῳ βοράν, εἴτε πρόσφαγμα τοῖς Ἀνδρόγεω τάφοις, εἴθ’, ὃ κουφότατόν ἐστὶ τῶν λεγομένων, λατρεύειν παρ’ ἀνδράσιν ὑβρισταῖς καὶ δυσμενέσιν ἀκλεῆ λατρείαν καὶ ἄτιμον ἐπιδοὺς ἑαυτόν, ἑκουσίως μετὰ παρθένων πλεύσας καὶ παίδων νέων, οὐκ ἂν εἴποι τις ἡλίκης ἐστὶ τόλμης ἢ μεγαλοφροσύνης ἢ δικαιοσύνης περὶ τὸ κοινὸν ἢ πόθου δόξης καὶ ἀρετῆς. ὥστ’ ἔμοιγε φαίνεται μὴ κακῶς ὁρίζεσθαι τοὺς φιλοσόφους τὸν ἔρωτα θεῶν ὑπηρεσίαν πρὸς ἐπιμέλειαν καὶ σωτηρίαν νέων. ὁ γὰρ Ἀριάδνης ἔρως παντὸς μᾶλλον ἔοικεν ἔργον θεοῦ καὶ μηχανὴ γενέσθαι σωτηρίας ἕνεκα τοῦ ἀνδρός, καὶ οὐκ ἄξιον αἰτιᾶσθαι τὴν ἐρασθεῖσαν, ἀλλὰ θαυμάζειν εἰ μὴ πάντες οὕτω καὶ πᾶσαι διετέθησαν· εἰ δ’ ἐκείνη μόνη τοῦτ’ ἔπαθεν, εἰκότως ἔγωγε φαίην ἂν αὐτὴν ἀξιέραστον θεῷ γεγονέναι, φιλόκαλον καὶ φιλάγαθον καὶ τῶν ἀρίστων ἐρωτικὴν οὖσαν.", "st": "Comp. Thes.–Rom. 1.1"}, {"sp": "N", "t": "ἀμφοτέρων τοίνυν τῇ φύσει πολιτικῶν γεγονότων, οὐδέτερος διεφύλαξε τὸν βασιλικὸν τρόπον ἐξέστη δὲ καὶ μετέβαλε μεταβολὴν ὁ μὲν δημοτικήν, ὁ δὲ τυραννικήν, ταὐτὸν ἀπ’ ἐναντίων παθῶν ἁμαρτόντες. δεῖ γὰρ τὸν ἄρχοντα σῴζειν πρῶτον αὐτὴν τὴν ἀρχήν σῴζεται δ’ οὐχ ἧττον ἀπεχομένη τοῦ μὴ προσήκοντος ἢ περιεχομένη τοῦ προσήκοντος. ὁ δ’ ἐνδιδοὺς ἢ ἐπιτείνων οὐ μένει βασιλεὺς οὐδὲ ἄρχων, ἀλλ’ ἢ δημαγωγὸς ἢ δεσπότης γιγνόμενος, ἐμποιεῖ τὸ μισεῖν ἢ καταφρονεῖν τοῖς ἀρχομένοις. οὐ μὴν ἀλλ’ ἐκεῖνο μὲν ἐπιεικείας δοκεῖ καὶ φιλανθρωπίας εἶναι, τοῦτο δὲ φιλαυτίας ἁμάρτημα καὶ χαλεπότητος.", "st": "Comp. Thes.–Rom. 2.1"}, {"sp": "N", "t": "εἰ δὲ δεῖ καὶ τὰ δυστυχηθέντα μὴ παντάπασι ποιεῖσθαι δαίμονος, ἀλλ’ ἠθικὰς καὶ παθητικὰς ζητεῖν ἐν αὐτοῖς διαφοράς, θυμοῦ μὲν ἀλογίστου καὶ τάχος ἐχούσης ἄβουλον ὀργῆς μήτε τις ἐκεῖνον ἐν τοῖς πρὸς τὸν ἀδελφὸν ἀπολυέτω μήτε τοῦτον ἐν τοῖς πρὸς τὸν υἱόν ἡ δὲ κινήσασα τὸν θυμὸν ἀρχὴ μᾶλλον παραιτεῖται τὸν ὑπὸ μείζονος αἰτίας ὥσπερ ὑπὸ πληγῆς χαλεπωτέρας ἀνατραπέντα. Ῥωμύλῳ μὲν γὰρ ἐκ βουλῆς καὶ σκέψεως περὶ κοινῶν συμφερόντων διαφορᾶς γενομένης οὐκ ἄν ἠξίωσέ τις ἄφνω τὴν διάνοιαν ἐν τηλικούτῳ πάθει γενέσθαι· Θησέα δὲ πρὸς τὸν υἱόν, ἃ πάμπαν ὀλίγοι τῶν ὄντων διαπεφεύγασιν, ἔρως καὶ ζηλοτυπία καὶ διαβολαὶ γυναικὸς ἔσφηλαν. ὃ δὲ μεῖζόν ἐστιν, ὁ μὲν Ῥωμύλου θυμὸς εἰς ἔργον ἐξέπεσε καὶ πρᾶξιν οὐκ εὐτυχὲς ἔχουσαν τέλος, ἡ δὲ Θησέως ὀργὴ μέχρι λόγου καὶ βλασφημίας καὶ κατάρας πρεσβυτικῆς προῆλθε, τὰ δ’ ἄλλα φαίνεται τῇ τύχῃ χρήσασθαι τὸ μειράκιον. ὥστε ταύτας μὲν ἄν τις ἀποδοίη τῷ Θησεῖ τὰς ψήφους·", "st": "Comp. Thes.–Rom. 3.1"}, {"sp": "N", "t": "ἐκείνῳ δὲ πρῶτον μὲν ὑπάρχει μέγα τὸ μικροτάτας λαβεῖν ἀρχὰς ἐπὶ τὰ πράγματα. δοῦλοι γὰρ δὴ καὶ συφορβῶν παῖδες ὀνομαζόμενοι, πρὶν ἐλεύθεροι γενέσθαι, πάντας ὀλίγου δεῖν ἠλευθέρωσαν Λατίνους, ἑνὶ χρόνῳ τῶν καλλίστων ὀνομάτων ἅμα τυχόντες, φονεῖς ἐχθρῶν καὶ σωτῆρες οἰκείων καὶ βασιλεῖς ἐθνῶν καὶ οἰκισταὶ πόλεων, οὐ μετοικισταὶ, καθάπερ ἦν ὁ Θησεύς, ἐκ πολλῶν συντιθεὶς καὶ συνοικοδομῶν ἓν οἰκητήριον, ἀναιρῶν δὲ πολλὰς πόλεις ἐπωνύμους βασιλέων καὶ ἡρώων παλαιῶν. Ῥωμύλος δὲ ταῦτα μὲν ὕστερον ἔδρα, τοὺς πολεμίους ἀναγκάζων τὰ οἰκεῖα καταβάλλοντας καὶ ἀφανίζοντας τοῖς νενικηκόσι προσνέμεσθαι· τὸ δὲ πρῶτον οὐ μετατιθεὶς οὐδ’ αὔξων τὴν ὑπάρχουσαν, ἀλλὰ ποιῶν ἐξ οὐχ ὑπαρχόντων καὶ κτώμενος ἑαυτῷ χώραν ὁμοῦ, πατρίδα, βασιλείαν, γένη, γάμους, οἰκειότητας, ἀνῄρει μὲν οὐδένα οὐδὲ ἀπώλλυεν, εὐεργέτει δὲ τοὺς ἐξ ἀοίκων καὶ ἀνεστίων δῆμον ἐθέλοντας εἶναι καὶ πολίτας, λῃστὰς δὲ καὶ κακούργους οὐκ ἀπέκτεινεν, ἀλλ’ ἔθνη προσηγάγετο πολέμῳ καὶ πόλεις κατεστρέψατο καὶ βασιλεῖς ἐθριάμβευσε καὶ ἡγεμόνας.", "st": "Comp. Thes.–Rom. 4.1"}, {"sp": "N", "t": "καὶ τὸ μὲν Ῥώμου πάθος ἀμφισβητούμενον ἔχει τὸν αὐτόχειρα, καὶ τὸ πλεῖστον εἰς ἑτέρους τῆς αἰτίας τρέπουσι· τὴν δὲ μητέρα διολλυμένην ἔσωσε περιφανῶς, καὶ τὸν πάππον ἀκλεῶς δουλεύοντα καὶ ἀτίμως εἰς τὸν Αἰνείου θρόνον ἐκάθισε, καὶ πολλὰ μὲν ἑκὼν εὐεργέτησεν, ἔβλαψε δὲ αὐτὸν οὐδὲ ἄκων. τὴν δὲ Θησέως λήθην καὶ ἀμέλειαν τῆς περὶ τὸ ἱστίον ἐντολῆς μόλις ἂν οἶμαι μακρᾷ τινι παραιτήσει καὶ ἐν ῥᾳθύμοις δικασταῖς αἰτίαν ἀποφυγεῖν πατροκτονίας· ὃ δὴ καὶ συνιδών τις Ἀττικὸς ἀνὴρ ὡς παγχάλεπόν ἐστι βουλομένοις ἀπολογεῖσθαι, πλάττει τὸν Αἰγέα τῆς νεὼς προσφερομένης ὑπὸ σπουδῆς ἀνατρέχοντα πρὸς τὴν ἀκρόπολιν θέας ἕνεκα καὶ σφαλλόμενον καταπεσεῖν, ὥσπερ ὀπαδῶν ἔρημον, ἢ τὴν ἐπὶ θάλατταν ὁδὸν σπεύδοντι μὴ παρούσης τινὸς θεραπείας.", "st": "Comp. Thes.–Rom. 5.1"}, {"sp": "N", "t": "καὶ μὴν τὰ περὶ τὰς ἁρπαγὰς τῶν γυναικῶν ἡμαρτημένα Θησεῖ μὲν εὐσχήμονος ἐνδεᾶ προφάσεως γέγονε. πρῶτον μὲν ὅτι πολλάκις· ἥρπασε γὰρ Ἀριάδνην καὶ Ἀντιόπην καὶ Ἀναξὼ τὴν Τροιζηνίαν, ἐπὶ πάσαις δὲ τὴν Ἑλένην, παρηκμακὼς οὐκ ἀκμάζουσαν, ἀλλὰ νηπίαν καὶ ἄωρον αὐτὸς ὥραν ἔχων ἤδη γάμων πεπαῦσθαι καὶ νομίμων ἔπειτα διὰ τὴν αἰτίαν οὐ γὰρ ἀξιώτεραί γε παιδοποιοὶ τῶν Ἀθήνησιν Ἐρεχθηίδων καὶ Κεκροπίδων αἱ Τροιζηνίων καὶ Λακώνων καὶ Ἀμαζόνων ἀνέγγυοι θυγατέρες ἦσαν. ἀλλὰ ταῦτα μὲν ὑποψίαν ἔχει πρὸς ὕβριν καὶ καθ’ ἡδονὴν πεπρᾶχθαι. Ῥωμύλος δὲ πρῶτον μὲν ὀκτακοσίων ὀλίγον ἀριθμῷ δεούσας ἁρπάσας, οὐ πάσας, ἀλλὰ μίαν, ὥς φασιν, Ἑρσιλίαν ἔλαβε, τὰς δ’ ἄλλας διένειμε τοῖς ἀγαθοῖς τῶν πολιτῶν ἔπειτα τῇ μετὰ ταῦτα τιμῇ καὶ ἀγαπήσει καὶ δικαιοσύνῃ τῇ περὶ τὰς γυναῖκας ἀπέδειξε τὴν βίαν ἐκείνην καὶ τὴν ἀδικίαν κάλλιστον ἔργον καὶ πολιτικώτατον εἰς κοινωνίαν γενομένην. οὕτω συνέμιξεν ἀλλήλοις καὶ συνέπηξε τὰ γένη, καὶ παρέσχε πηγὴν τῆς εἰς αὖθις εὐνοίας καὶ δυνάμεως τοῖς πράγμασιν. αἰδοῦς δὲ καὶ φιλίας καὶ βεβαιότητος, ἣν εἰργάσατο περὶ τοὺς γάμους, ὁ χρόνος ἐστὶ μάρτυς, ἐν γὰρ ἔτεσι τριάκοντα καὶ διακοσίοις οὔτε ἀνὴρ ἐτόλμησε γυναικὸς οὔτε γυνὴ κοινωνίαν ἀνδρὸς ἐγκαταλιπεῖν, ἀλλ’ ὥσπερ ἐν Ἕλλησιν οἱ σφόδρα περιττοὶ τὸν πρῶτον ἔχουσιν εἰπεῖν πατροκτόνον ἢ μητροφόνον, οὕτω Ῥωμαῖοι πάντες ἴσασιν ὅτι Καρβίλιος Σπόριος ἀπεπέμψατο γυναῖκα πρῶτος, ἀπαιδίαν αἰτιασάμενος. τῷ δὲ τοσούτῳ χρόνῳ συμμαρτυρεῖ καὶ τὰ ἔργα. καὶ γὰρ ἀρχῆς ἐκοινώνησαν οἱ βασιλεῖς, καὶ πολιτείας τὰ γένη διὰ τὴν ἐπιγαμίαν ἐκείνην ἀπὸ δὲ τῶν Θησέως γάμων Ἀθηναίοις φιλικὸν μὲν οὐδὲν οὐδὲ κοινωνικὸν ὑπῆρξε πρὸς οὐδένα συμβόλαιον, ἔχθραι δὲ καὶ πόλεμοι καὶ φόνοι πολιτῶν καὶ τέλος Ἀφίδνας ἀπολέσαι καὶ μόλις ὑπ’ οἴκτου τῶν πολεμίων, προσκυνήσαντας καὶ θεοὺς ἀνειπόντας, μὴ παθεῖν ἃ Τρῶες ἔπαθον δι’ Ἀλέξανδρον. ἡ μέντοι μήτηρ ἡ Θησέως οὐκ ἐκινδύνευσεν, ἀλλ’ ἔπαθε τὰ τῆς Ἑκάβης, ἐγκαταλιπόντος καὶ προεμένου τοῦ παιδός, εἴγε μὴ πέπλασται τὰ τῆς αἰχμαλωσίας, ὡς ἔδει γε καὶ τοῦτο ψεῦδος εἶναι καὶ τὰ πλεῖστα τῶν ἄλλων, ἐπεὶ καὶ τὰ περὶ τοῦ θείου μυθολογούμενα πολλὴν ποιεῖ διαφοράν. Ῥωμύλῳ μὲν γὰρ ἡ σωτηρία μετὰ πολλῆς ὑπῆρξε θεῶν εὐμενείας, ὁ δ’ Αἰγεῖ δοθεὶς χρησμός, ἀπέχεσθαι γυναικὸς ἐπὶ ξένης, ἔοικεν ἀποφαίνειν παρὰ γνώμην θεῶν γεγονέναι τὴν Θησέως τέκνωσιν.", "st": "Comp. Thes.–Rom. 6.1"}, {"sp": "HDR", "t": "Λυκοῦργος"}, {"sp": "N", "t": "περὶ Λυκούργου τοῦ νομοθέτου καθόλου μὲν οὐδὲν ἔστιν εἰπεῖν ἀναμφισβήτητον, οὗ γε καὶ γένος καὶ ἀποδημία καὶ τελευτὴ καὶ πρὸς ἅπασιν ἡ περὶ τοὺς νόμους αὐτοῦ καὶ τὴν πολιτείαν πραγματεία διαφόρους ἔσχηκεν ἱστορίας, ἥκιστα δὲ οἱ χρόνοι καθ’ οὓς γέγονεν ὁ ἀνὴρ ὁμολογοῦνται, οἱ μὲν γάρ Ἰφίτῳ συνακμάσαι καὶ συνδιαθεῖναι τὴν Ὀλυμπιακὴν ἐκεχειρίαν λέγουσιν αὐτόν, ὧν ἐστι καὶ Ἀριστοτέλης ὁ φιλόσοφος, τεκμήριον προσφέρων τὸν Ὀλυμπίασι δίσκον ἐν ᾧ τοὔνομα τοῦ Λυκούργου διασώζεται καταγεγραμμένον· οἱ δὲ ταῖς διαδοχαῖς τῶν ἐν Σπάρτῃ βεβασιλευκότων ἀναλεγόμενοι τὸν χρόνον, ὥσπερ Ἐρατοσθένης καὶ Ἀπολλόδωρος, οὐκ ὀλίγοις ἔτεσι πρεσβύτερον ἀποφαίνουσι τῆς πρώτης Ὀλυμπιάδος. Τίμαιος δὲ ὑπονοεῖ, δυεῖν ἐν Σπάρτῃ γεγονότων Λυκούργων οὐ κατὰ τὸν αὐτὸν χρόνον, τῷ ἑτέρῳ τὰς ἀμφοῖν πράξεις διὰ τὴν δόξαν ἀνακεῖσθαι καὶ τόν γε πρεσβύτερον οὐ πόρρω τῶν Ὁμήρου γεγονέναι χρόνων, ἔνιοι δὲ καὶ κατ’ ὄψιν ἐντυχεῖν Ὁμήρῳ. δίδωσι δὲ καὶ Ξενοφῶν ὑπόνοιαν ἀρχαιότητος ἐν οἷς τὸν ἄνδρα λέγει γεγονέναι κατὰ τοὺς Ἡρακλείδας. γένει μὲν γὰρ Ἡρακλεῖδαι δήπουθεν ἦσαν καὶ οἱ νεώτατοι τῶν ἐν Σπάρτῃ βασιλέων, ὁ δὲ ἔοικε βουλομένῳ τοὺς πρώτους ἐκείνους καὶ σύνεγγυς Ἡρακλέους ὀνομάζειν Ἡρακλείδας.", "st": "Lyc. 1.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καίπερ οὕτως πεπλανημένης τῆς ἱστορίας, πειρασόμεθα τοῖς βραχυτάτας ἔχουσιν ἀντιλογίας ἢ γνωριμωτάτους μάρτυρας ἑπόμενοι τῶν γεγραμμένων περὶ τοῦ ἀνδρὸς ἀποδοῦναι τὴν διήγησιν. ἐπεὶ καὶ Σιμωνίδης ὁ ποιητὴς οὐκ Εὐνόμου λέγει τὸν Λυκοῦργον πατρός, ἀλλὰ Πρυτάνιδος καὶ τὸν Λυκοῦργον καὶ τὸν Εὔνομον, οἱ δὲ πλεῖστοι σχεδὸν οὐχ οὕτω γενεαλογοῦσιν, ἀλλὰ Προκλέους μὲν τοῦ Ἀριστοδήμου γενέσθαι Σόον, Σόου δὲ Εὐρυπῶντα, τούτου δὲ Πρύτανιν, ἐκ τούτου δὲ Εὔνομον, Εὐνόμου δὲ Πολυδέκτην ἐκ προτέρας γυναικός, Λυκοῦργον δὲ νεώτερον ἐκ Διωνάσσης, ὡς Διευτυχίδας ἱστόρηκεν, ἕκτον μὲν ἀπὸ Προκλέους, ἑνδέκατον δὲ ἀφ’ Ἡρακλέους.", "st": "Lyc. 1.4"}, {"sp": "N", "t": "τῶν δὲ προγόνων αὐτοῦ μάλιστα μὲν ἐθαυμάσθη Σόος, ἐφ’ οὗ καὶ τοὺς εἵλωτας ἐποιήσαντο δούλους οἱ Σπαρτιᾶται καὶ χώραν προσεκτήσαντο πολλὴν Ἀρκάδων ἀποτεμόμενοι. λέγεται δὲ τὸν Σόον ἐν χωρίῳ χαλεπῷ καὶ ἀνύδρῳ πολιορκούμενον ὑπὸ Κλειτορίων, ὁμολογῆσαι τὴν δορίκτητον γῆν αὐτοῖς ἀφήσειν, εἰ πίοι καὶ αὐτὸς καὶ οἱ μετ’ αὐτοῦ πάντες ἀπὸ τῆς πλησίον πηγῆς, γενομένων δὲ τῶν ὁρκίων συναγαγόντα τοὺς μεθ’ ἑαυτοῦ διδόναι τῷ μὴ πιόντι τὴν βασιλείαν· οὐδενὸς δὲ καρτερήσαντος, ἀλλὰ πάντων πιόντων, αὐτὸν ἐπὶ πᾶσι καταβάντα καὶ περιρρανάμενον ἔτι τῶν πολεμίων παρόντων ἀπελθεῖν καὶ τὴν χώραν κατασχεῖν, ὡς μὴ πάντων πιόντων.", "st": "Lyc. 2.1"}, {"sp": "N", "t": "ἀλλὰ καίπερ ἐπὶ τούτοις θαυμάζοντες αὐτὸν οὐκ ἀπὸ τούτου τὴν οἰκίαν, ἀλλὰ τοῦ παιδὸς αὐτοῦ προσηγόρευσαν Εὐρυπωντίδας, ὅτι δοκεῖ πρῶτος Εὐρυπῶν τὸ ἄγαν μοναρχικὸν ἀνεῖναι τῆς βασιλείας, δημαγωγῶν καὶ χαριζόμενος τοῖς πολλοῖς. ἐκ δὲ τῆς τοιαύτης ἀνέσεως τοῦ μὲν δήμου θρασυνομένου, τῶν δ’ ὕστερον βασιλέων τὰ μὲν ἀπεχθανομένων τῷ βιάζεσθαι τοὺς πολλούς, τὰ δὲ πρὸς χάριν ἢ δι’ ἀσθένειαν ὑποφερομένων, ἀνομία καὶ ἀταξία κατέσχε τὴν Σπάρτην ἐπὶ πολὺν χρόνον ὑφ’ ἧς καὶ τὸν πατέρα τοῦ Λυκούργου βασιλεύοντα συνέβη τελευτῆσαι. διερύκων γάρ ἁψιμαχίαν τινά, μαγειρικῇ κοπίδι πληγεὶς ἀπέθανε, τῷ πρεσβυτέρῳ παιδὶ Πολυδέκτῃ καταλιπὼν τὴν βασιλείαν.", "st": "Lyc. 2.3"}, {"sp": "N", "t": "ἀποθανόντος δὲ καὶ τούτου μετ’ ὀλίγον χρόνον ἔδει βασιλεύειν, ὡς πάντες ᾤοντο, τὸν Λυκοῦργον· καὶ πρίν γε τὴν γυναῖκα τοῦ ἀδελφοῦ φανερὰν γενέσθαι κύουσαν ἐβασίλευεν. ἐπεὶ δὲ τοῦτο τάχιστα ᾔσθετο, τὴν μὲν βασιλείαν ἀπέφηνε τοῦ παιδὸς οὖσαν, ἄνπερ ἄρρην γένηται, τὴν δὲ ἀρχὴν αὐτὸς ὡς ἐπίτροπος διεῖπε. τοὺς δὲ τῶν ὀρφανῶν βασιλέων ἐπιτρόπους Λακεδαιμόνιοι προδίκους ὠνόμαζον. ὡς δὲ ἡ γυνὴ προσέπεμπε κρύφα καὶ λόγους ἐποιεῖτο, βουλομένη διαφθεῖραι τὸ βρέφος ἐπὶ τῷ συνοικεῖν ἐκείνῳ βασιλεύοντι τῆς Σπάρτης, τὸ μὲν ἦθος αὐτῆς ἐμίσησε, πρὸς δὲ τὸν λόγον αὐτὸν οὐκ ἀντεῖπεν, ἀλλ’ ἐπαινεῖν καὶ δέχεσθαι προσποιούμενος, οὐκ ἔφη δεῖν ἀμβλίσκουσαν αὐτὴν καὶ φαρμακευομένην διαλυμαίνεσθαι τὸ σῶμα καὶ κινδυνεύειν αὐτῷ γὰρ μελήσειν ὅπως εὐθὺς ἐκποδὼν ἔσται τὸ γεννηθέν. οὕτω δὲ παραγαγὼν ἄχρι τοῦ τόκου τὴν ἄνθρωπον, ὡς ᾔσθετο τίκτουσαν, εἰσέπεμψε παρέδρους ταῖς ὠδῖσιν αὐτῆς καὶ φύλακας, οἷς ἦν προστεταγμένον, ἐὰν μὲν θῆλυ τεχθῇ, παραδοῦναι ταῖς γυναιξίν, ἐὰν δὲ ἄρρεν, κομίσαι πρὸς ἑαυτὸν ὅ τι ἂν τύχῃ πράττων. ἔτυχε δὲ δειπνοῦντος αὐτοῦ μετὰ τῶν ἀρχόντων ἀποκυηθὲν ἄρρεν καὶ παρῆσαν οἱ ὑπηρέται τὸ παιδάριον αὐτῷ κομίζοντες. ὁ δὲ δεξάμενος, ὡς λέγεται, καὶ πρὸς τοὺς παρόντας εἰπών, βασιλεὺς ὑμῖν γέγονεν, ὦ Σπαρτιᾶται, κατέκλινεν ἐν τῇ βασιλικῇ χώρᾳ καὶ Χαρίλαον ὠνόμασε διὰ τὸ τοὺς πάντας εἶναι περιχαρεῖς, ἀγαμένους αὐτοῦ τὸ φρόνημα καὶ τὴν δικαιοσύνην. ἐβασίλευσε δὲ μῆνας ὀκτὼ τὸ σύμπαν, ἦν δὲ καὶ τἆλλα περίβλεπτος ὑπὸ τῶν πολιτῶν, καὶ πλείονες ἐγένοντο τῶν ὡς ἐπιτρόπῳ βασιλέως καὶ βασιλικὴν ἐξουσίαν ἔχοντι πειθομένων οἱ δι’ ἀρετὴν προσέχοντες αὐτῷ καὶ ποιεῖν ἐθέλοντες ἑτοίμως τὸ προσταττόμενον.", "st": "Lyc. 3.1"}, {"sp": "N", "t": "ἦν δέ τι καὶ τὸ φθονοῦν καὶ πρὸς τὴν αὔξησιν ὄντι νέῳ πειρώμενον ἐνίστασθαι, μάλιστα μὲν οἱ συγγενεῖς καὶ οἰκεῖοι τῆς τοῦ βασιλέως μητρὸς ὑβρίσθαι δοκούσης, ὁ δὲ ἀδελφὸς αὐτῆς Λεωνίδας καὶ θρασύτερόν ποτε τῷ Λυκούργῳ λοιδορηθείς, ὑπεῖπεν ὡς εἰδείη σαφῶς μέλλοντα βασιλεύειν αὐτόν, ὑπόνοιαν διδοὺς καὶ προκαταλαμβάνων διαβολῇ τὸν Λυκοῦργον, εἴ τι συμβαίη τῷ βασιλεῖ παθεῖν, ὡς ἐπιβεβουλευκότα. τοιοῦτοι δὲ τινες λόγοι καὶ παρὰ τῆς γυναικὸς ἐξεφοίτων ἐφ’ οἷς βαρέως φέρων καὶ δεδοικὼς τὸ ἄδηλον, ἔγνω φυγεῖν ἀποδημίᾳ τὴν ὑπόνοιαν, καὶ πλανηθῆναι μέχρις ἂν ὁ ἀδελφιδοῦς ἐν ἡλικίᾳ γενόμενος τεκνώσῃ διάδοχον τῆς βασιλείας.", "st": "Lyc. 3.5"}, {"sp": "N", "t": "οὕτως ἀπάρας πρῶτον μὲν εἰς Κρήτην ἀφίκετο· καὶ τὰς αὐτόθι πολιτείας κατανοήσας καὶ συγγενόμενος τοῖς πρωτεύουσι κατὰ δόξαν ἀνδράσι, τὰ μὲν ἐζήλωσε καὶ παρέλαβε τῶν νόμων, ὡς οἴκαδε μετοίσων καὶ χρησόμενος, ἔστι δ’ ὧν κατεφρόνησεν. ἕνα δὲ τῶν νομιζομένων ἐκεῖ σοφῶν καὶ πολιτικῶν χάριτι καὶ φιλίᾳ πείσας ἀπέστειλεν εἰς τὴν Σπάρτην, Θάλητα, ποιητὴν μὲν δοκοῦντα λυρικῶν μελῶν καὶ πρόσχημα τὴν τέχνην ταύτην πεποιημένον, ἔργῳ δὲ ἅπερ οἱ κράτιστοι τῶν νομοθετῶν διαπραττόμενον. λόγοι γὰρ ἦσαν αἱ ᾠδαὶ πρὸς εὐπείθειαν καὶ ὁμόνοιαν ἀνακλητικοί, διὰ μελῶν ἅμα καὶ ῥυθμῶν πολὺ τὸ κόσμιον ἐχόντων καὶ καταστατικόν, ὧν ἀκροώμενοι κατεπραΰνοντο λεληθότως τὰ ἤθη καὶ συνῳκειοῦντο τῷ ζήλῳ τῶν καλῶν ἐκ τῆς ἐπιχωριαζούσης τότε πρὸς ἀλλήλους κακοθυμίας, ὥστε τρόπον τινὰ τῷ Λυκούργῳ προοδοποιεῖν τὴν παίδευσιν αὐτῶν ἐκεῖνον.", "st": "Lyc. 4.1"}, {"sp": "N", "t": "ἀπὸ δὲ τῆς Κρήτης ὁ Λυκοῦργος ἐπὶ Ἀσίαν ἔπλευσε, βουλόμενος, ὡς λέγεται, ταῖς Κρητικαῖς διαίταις, εὐτελέσιν οὔσαις καὶ αὐστηραῖς, τὰς Ἰωνικὰς πολυτελείας καὶ τρυφάς, ὥσπερ ἰατρὸς σώμασιν ὑγιεινοῖς ὕπουλα καὶ νοσώδη, παραβαλὼν ἀποθεωρῆσαι τὴν διαφορὰν τῶν βίων καὶ τῶν πολιτειῶν. ἐκεῖ δὲ καὶ τοῖς Ὁμήρου ποιήμασιν ἐντυχὼν πρῶτον, ὡς ἔοικε, παρὰ τοῖς ἐκγόνοις τοῖς Κρεοφύλου διατηρουμένοις, καὶ κατιδὼν ἐν αὐτοῖς τῆς πρὸς ἡδονὴν καὶ ἀκρασίαν διατριβῆς τὸ πολιτικὸν καὶ παιδευτικὸν οὐκ ἐλάττονος ἄξιον σπουδῆς ἀναμεμιγμένον, ἐγράψατο προθύμως καὶ συνήγαγεν ὡς δεῦρο κομιῶν. ἦν γάρ τις ἤδη δόξα τῶν ἐπῶν ἀμαυρὰ παρὰ τοῖς Ἕλλησιν, ἐκέκτηντο δὲ οὐ πολλοὶ μέρη τινά, σποράδην τῆς ποιήσεως, ὡς ἔτυχε, διαφερομένης γνωρίμην δὲ αὐτὴν καὶ μάλιστα πρῶτος ἐποίησε Λυκοῦργος.", "st": "Lyc. 4.3"}, {"sp": "N", "t": "Αἰγύπτιοι δὲ καὶ πρὸς αὑτοὺς ἀφικέσθαι τὸν Λυκοῦργον οἴονται, καὶ τὴν ἀπὸ τῶν ἄλλων γενῶν τοῦ μαχίμου διάκρισιν μάλιστα θαυμάσαντα μετενεγκεῖν εἰς τὴν Σπάρτην, καὶ χωρίσαντα τοὺς βαναύσους καὶ χειροτέχνας ἀστεῖον ὡς ἀληθῶς τὸ πολίτευμα καὶ καθαρὸν ἀποδεῖξαι. ταῦτα μὲν οὖν Αἰγυπτίοις ἔνιοι καὶ τῶν Ἑλληνικῶν συγγραφέων μαρτυροῦσιν· ὅτι δὲ καὶ Λιβύην καὶ Ἰβηρίαν ἐπῆλθεν ὁ Λυκοῦργος καὶ περὶ τὴν Ἰνδικὴν πλανηθεὶς τοῖς Γυμνοσοφισταῖς ὡμίλησεν, οὐδένα πλὴν Ἀριστοκράτη τὸν Ἱππάρχου Σπαρτιάτην εἰρηκότα γινώσκομεν.", "st": "Lyc. 4.5"}, {"sp": "N", "t": "οἱ δὲ Λακεδαιμόνιοι τὸν Λυκοῦργον ἐπόθουν ἀπόντα καὶ μετεπέμποντο πολλάκις, ὡς τοὺς μὲν βασιλεῖς ὄνομα καὶ τιμήν, ἄλλο δὲ μηδὲν διαφέρον τῶν πολλῶν ἔχοντας, ἐν ἐκείνῳ δὲ φύσιν ἡγεμονικὴν καὶ δύναμιν ἀνθρώπων ἀγωγὸν οὖσαν. οὐ μὴν οὐδὲ τοῖς βασιλεῦσιν ἦν ἀβούλητος ἡ παρουσία τοῦ ἀνδρός, ἀλλ’ ἤλπιζον ἐκείνου συμπαρόντος ἧττον ὑβρίζουσι χρῆσθαι τοῖς πολλοῖς. ἐπανελθὼν οὖν πρὸς οὕτω διακειμένους εὐθὺς ἐπεχείρει τὰ παρόντα κινεῖν καὶ μεθιστάναι τὴν πολιτείαν, ὡς τῶν κατὰ μέρος νόμων οὐδὲν ἔργον οὐδὲ ὄφελος, εἰ μή τις ὥσπερ σώματι πονηρῷ καὶ γέμοντι παντοδαπῶν νοσημάτων τὴν ὑπάρχουσαν ἐκτήξας καὶ μεταβαλὼν κρᾶσιν ὑπὸ φαρμάκων καὶ καθαρμῶν ἑτέρας ἄρξεται καινῆς διαίτης. διανοηθεὶς δὲ ταῦτα πρῶτον μὲν ἀπεδήμησεν εἰς Δελφούς· καὶ τῷ θεῷ θύσας καὶ χρησάμενος ἐπανῆλθε τὸν διαβόητον ἐκεῖνον χρησμὸν κομίζων, ᾧ θεοφιλῆ μὲν αὐτὸν ἡ Πυθία προσεῖπε καὶ θεὸν μᾶλλον ἢ ἄνθρωπον, εὐνομίας δὲ χρῄζοντι διδόναι καὶ καταινεῖν ἔφη τὸν θεὸν ἣ πολὺ κρατίστη τῶν ἄλλων ἔσται πολιτειῶν.", "st": "Lyc. 5.1"}, {"sp": "N", "t": "ἐπαρθεὶς δὲ τούτοις προσήγετο τοὺς ἀρίστους καὶ συνεφάπτεσθαι παρεκάλει, κρύφα διαλεγόμενος τοῖς φίλοις πρῶτον, εἶτα οὕτως κατὰ μικρὸν ἁπτόμενος πλειόνων καὶ συνιστὰς ἐπὶ τὴν πρᾶξιν. ὡς δ’ ὁ καιρὸς ἧκε, τριάκοντα τοὺς πρώτους ἐκέλευσε μετὰ τῶν ὅπλων ἕωθεν εἰς ἀγορὰν προελθεῖν ἐκπλήξεως ἕνεκα καὶ φόβου πρὸς τοὺς ἀντιπράττοντας. ὧν εἴκοσι τοὺς ἐπιφανεστάτους Ἕρμιππος ἀνέγραψε· τὸν δὲ μάλιστα τῶν Λυκούργου ἔργων κοινωνήσαντα πάντων καὶ συμπραγματευσάμενον τὰ περὶ τοὺς νόμους Ἀρθμιάδαν ὀνομάζουσιν. ἀρχομένης δὲ τῆς ταραχῆς ὁ βασιλεὺς Χαρίλαος φοβηθεὶς ὡς ἐπ’ αὐτὸν ὅλης τῆς πράξεως συνισταμένης, κατέφυγε πρὸς τὴν Χαλκίοικον εἶτα πεισθεὶς καὶ λαβὼν ὅρκους ἀνέστη καὶ μετεῖχε τῶν πραττομένων, φύσει πρᾷος ὢν· ὥς που καὶ λέγεται συμβασιλεύοντα τὸν Ἀρχέλαον αὐτῷ πρὸς τοὺς ἐγκωμιάζοντας τὸν νεανίσκον εἰπεῖν πῶς δ’ ἂν εἴη Χαρίλαος ἀνήρ ἀγαθός, ὃς οὐδὲ τοῖς πονηροῖς χαλεπός ἐστι;", "st": "Lyc. 5.4"}, {"sp": "N", "t": "πλειόνων δὲ καινοτομουμένων ὑπὸ τοῦ Λυκούργου πρῶτον ἦν καὶ μέγιστον ἡ κατάστασις τῶν γερόντων, ἥν φησιν ὁ Πλάτων τῇ τῶν βασιλέων ἀρχῇ φλεγμαινούσῃ μιχθεῖσαν καὶ γενομένην ἰσόψηφον εἰς τὰ μέγιστα σωτηρίαν ἅμα καὶ σωφροσύνην παρασχεῖν. αἰωρουμένη γὰρ ἡ πολιτεία καὶ ἀποκλίνουσα νῦν μὲν ὡς τοὺς βασιλεῖς ἐπὶ τυραννίδα, νῦν δὲ ὡς τὸ πλῆθος ἐπὶ δημοκρατίαν, οἷον ἕρμα τὴν τῶν γερόντων ἀρχὴν ἐν μέσῳ θεμένη καὶ ἰσορροπήσασα τὴν ἀσφαλεστάτην τάξιν ἔσχε καὶ κατάστασιν, ἀεὶ τῶν ὀκτὼ καὶ εἴκοσι γερόντων τοῖς μὲν βασιλεῦσι προστιθεμένων ὅσον ἀντιβῆναι πρὸς δημοκρατίαν, αὖθις δὲ ὑπὲρ τοῦ μὴ γενέσθαι τυραννίδα τὸν δῆμον ἀναρρωννύντων. τοσούτους δέ φησι κατασταθῆναι τοὺς γέροντας Ἀριστοτέλης, ὅτι τριάκοντα τῶν πρώτων μετὰ Λυκούργου γενομένων δύο τὴν πρᾶξιν ἐγκατέλιπον ἀποδειλιάσαντες. ὁ δὲ Σφαῖρος ἐξ ἀρχῆς φησι τοσούτους γενέσθαι τοὺς τῆς γνώμης μετασχόντας. εἴη δ’ ἂν τι καὶ τὸ τοῦ ἀριθμοῦ δι’ ἑβδομάδος τετράδι πολλαπλασιασθείσης ἀποτελούμενον, καὶ ὅτι τοῖς αὑτοῦ μέρεσιν ἴσος ὢν μετὰ τὴν ἑξάδα τέλειός ἐστιν. ἐμοὶ δὲ δοκεῖ μάλιστα τοσούτους ἀποδεῖξαι τοὺς γέροντας ὅπως οἱ πάντες εἶεν τριάκοντα, τοῖς ὀκτὼ καὶ εἴκοσι τοῖν δυοῖν βασιλέοιν προστιθεμένοιν.", "st": "Lyc. 5.6"}, {"sp": "N", "t": "οὕτω δὲ περὶ ταύτην ἐσπούδασε τὴν ἀρχὴν ὁ Λυκοῦργος ὥστε μαντείαν ἐκ Δελφῶν κομίσαι περὶ αὐτῆς, ἣν ῥήτραν καλοῦσιν. ἔχει δὲ οὕτως· Διὸς Συλλανίου καὶ Ἀθανᾶς Συλλανίας ἱερὸν ἱδρυσάμενον, φυλὰς φυλάξαντα καὶ ὠβὰς ὠβάξαντα, τριάκοντα γερουσίαν σὺν ἀρχαγέταις καταστήσαντα, ὥρας ἐξ ὥρας ἀπελλάζειν μεταξὺ Βαβύκας τε καὶ Κνακιῶνος, οὕτως εἰσφέρειν τε καὶ ἀφίστασθαι δάμῳ δὲ τὰν κυρίαν ἦμεν καὶ κράτος ἐν τούτοις τὸ μὲν φυλὰς φυλάξαι καὶ ὠβὰς ὠβάξαι διελεῖν ἐστι καὶ κατανεῖμαι τὸ πλῆθος εἰς μερίδας, ὧν τὰς μὲν φυλάς, τὰς δὲ ὠβὰς προσηγόρευκεν. ἀρχαγέται δὲ οἱ βασιλεῖς λέγονται, τὸ δὲ ἀπελλάζειν ἐκκλησιάζειν· ὅτι τὴν ἀρχὴν καὶ τὴν αἰτίαν τῆς πολιτείας εἰς τὸν Πύθιον ἀνῆψε. τὴν δὲ Βαβύκαν Χείμαρρος, καὶ τὸν Κνακιῶνα νῦν Οἰνοῦντα προσαγορεύουσιν· Ἀριστοτέλης δὲ τὸν μὲν Κνακιῶνα ποταμόν, τὴν δὲ Βαβύκαν γέφυραν. ἐν μέσῳ δὲ τούτων τὰς ἐκκλησίας ἦγον, οὔτε παστάδων οὐσῶν οὔτε ἄλλης τινὸς κατασκευῆς, οὐθὲν γάρ ᾤετο ταῦτα πρὸς εὐβουλίαν εἶναι, μᾶλλον δὲ βλάπτειν, φλυαρώδεις ἀπεργαζόμενα καὶ χαύνους φρονήματι κενῷ τὰς διανοίας τῶν συμπορευομένων, ὅταν εἰς ἀγάλματα καὶ γραφὰς ἢ προσκήνια θεάτρων ἢ στέγας βουλευτηρίων ἠσκημένας περιττῶς ἐκκλησιάζοντες ἀποβλέπωσι. τοῦ δὲ πλήθους ἀθροισθέντος εἰπεῖν μὲν οὐδενὶ γνώμην τῶν ἄλλων ἐφεῖτο, τὴν δ’ ὑπὸ τῶν γερόντων καὶ τῶν βασιλέων προτεθεῖσαν ἐπικρῖναι κύριος ἦν ὁ δῆμος. ὕστερον μέντοι τῶν πολλῶν ἀφαιρέσει καὶ προσθέσει τὰς γνώμας διαστρεφόντων καὶ παραβιαζομένων, Πολύδωρος καὶ Θεόπομπος οἱ βασιλεῖς τάδε τῇ ῥήτρᾳ παρενέγραψαν· αἰ δὲ σκολιὰν ὁ δᾶμος ἕλοιτο, τοὺς πρεσβυγενέας καὶ ἀρχαγέτας ἀποστατῆρας ἦμεν, τοῦτ’ ἔστι μὴ κυροῦν, ἀλλ’ ὅλως ἀφίστασθαι καὶ διαλύειν τὸν δῆμον, ὡς ἐκτρέποντα καὶ μεταποιοῦντα τὴν γνώμην παρὰ τὸ βέλτιστον. ἔπεισαν δὲ καὶ αὐτοὶ τὴν πόλιν ὡς τοῦ θεοῦ ταῦτα προστάσσοντος, ὥς που Τυρταῖος ἐπιμέμνηται διὰ τούτων", "st": "Lyc. 6.1"}, {"sp": "N", "t": "Φοίβου ἀκούσαντες Πυθωνόθεν οἴκαδ’ ἔνεικαν<br>μαντείας τε θεοῦ καὶ τελέεντ’ ἔπεα·<br>ἄρχειν μὲν βουλῆς θεοτιμήτους βασιλῆας,<br>οἷσι μέλει Σπάρτας ἱμερόεσσα πόλις,<br>πρεσβύτας τε γέροντας, ἔπειτα δὲ δημότας<br>ἄνδρας,<br>εὐθείαις ῥήτραις ἀνταπαμειβομένους.", "st": "Lyc. 6.1b"}, {"sp": "N", "t": "οὕτω τὸ πολίτευμα τοῦ Λυκούργου μίξαντος, ὅμως ἄκρατον ἔτι τὴν ὀλιγαρχίαν καὶ ἰσχυρὰν οἱ μετ’ αὐτὸν ὁρῶντες σπαργῶσαν καὶ θυμουμένην, ὥς φησιν ὁ Πλάτων, οἷον ψάλιον ἐμβάλλουσιν αὐτῇ τὴν τῶν ἐφόρων δύναμιν, ἔτεσί που μάλιστα τριάκοντα καὶ ἑκατὸν μετὰ Λυκοῦργον πρώτων τῶν περὶ Ἔλατον ἐφόρων κατασταθέντων ἐπὶ Θεοπόμπου βασιλεύοντος· ὃν καὶ φασιν ὑπὸ τῆς ἑαυτοῦ γυναικὸς ὀνειδιζόμενον ὡς ἐλάττω παραδώσοντα τοῖς παισὶ τὴν βασιλείαν ἢ παρέλαβε, μείζω μὲν οὖν, εἰπεῖν, ὅσῳ χρονιωτέραν. τῷ γὰρ ὄντι τὸ ἄγαν ἀποβαλοῦσα μετὰ τοῦ φθόνου διέφυγε τὸν κίνδυνον, ὥστε μὴ παθεῖν ἃ Μεσσήνιοι καὶ Ἀργεῖοι τοὺς παρ’ αὐτοῖς βασιλεῖς ἔδρασαν, μηδὲν ἐνδοῦναι μηδὲ χαλάσαι τῆς ἐξουσίας ἐπὶ τὸ δημοτικὸν ἐθελήσαντας. ὃ καὶ μάλιστα τὴν Λυκούργου σοφίαν καὶ πρόνοιαν ἐποίησε φανερὰν εἰς τὰς Μεσσηνίων καὶ Ἀργείων, συγγενῶν καὶ γειτόνων, δήμων καὶ βασιλέων στάσεις καὶ κακοπολιτείας ἀφορῶσιν, οἳ τῶν ἴσων ἀπ’ ἀρχῆς τετυχηκότες, ἐν δὲ τῷ κλήρῳ καὶ πλέον ἔχειν ἐκείνων δόξαντες, οὐκ ἐπὶ πολὺν χρόνον εὐδαιμόνησαν, ἀλλ’ ὕβρει μὲν τῶν βασιλέων, οὐκ εὐπειθείᾳ δὲ τῶν ὄχλων, τὰ καθεστῶτα συνταράξαντες ἔδειξαν ὅτι θεῖον ἦν ὡς ἀληθῶς εὐτύχημα τοῖς Σπαρτιάταις ὁ τὴν πολιτείαν ἁρμοσάμενος καὶ κεράσας παρ’ αὐτοῖς. ταῦτα μὲν οὖν ὕστερον.", "st": "Lyc. 7.1"}, {"sp": "N", "t": "δεύτερον δὲ τῶν Λυκούργου πολιτευμάτων καὶ νεανικώτατον ὁ τῆς γῆς ἀναδασμός ἐστι. δεινῆς γάρ οὔσης ἀνωμαλίας καὶ πολλῶν ἀκτημόνων καὶ ἀπόρων ἐπιφερομένων τῇ πόλει, τοῦ δὲ πλούτου παντάπασιν εἰς ὀλίγους συνερρυηκότος, ὕβριν καὶ φθόνον καὶ κακουργίαν καὶ τρυφὴν καὶ τὰ τούτων ἔτι πρεσβύτερα καὶ μείζω νοσήματα πολιτείας, πλοῦτον καὶ πενίαν, ἐξελαύνων, συνέπεισε τὴν χώραν ἅπασαν εἰς μέσον θέντας ἐξ ἀρχῆς ἀναδάσασθαι, καὶ ζῆν μετ’ ἀλλήλων ἅπαντας ὁμαλεῖς καὶ ἰσοκλήρους τοῖς βίοις γενομένους, τὸ δὲ πρωτεῖον ἀρετῇ μετιόντας, ὡς ἄλλης ἑτέρῳ πρὸς ἕτερον οὐκ οὔσης διαφορᾶς οὐδὲ ἀνισότητος, πλὴν ὅσην αἰσχρῶν ψόγος ὁρίζει καὶ καλῶν ἔπαινος.", "st": "Lyc. 8.1"}, {"sp": "N", "t": "ἐπάγων δὲ τῷ λόγῳ τὸ ἔργον ἔνειμε τὴν μὲν ἄλλην τοῖς περιοίκοις Λακωνικὴν τρισμυρίους κλήρους, τὴν δὲ εἰς τὸ ἄστυ τὴν Σπάρτην συντελοῦσαν ἐνακισχιλίους· τοσοῦτοι γάρ ἐγένοντο κλῆροι Σπαρτιατῶν ἔνιοι δέ φασι τὸν μὲν Λυκοῦργον ἑξακισχιλίους νεῖμαι, τρισχιλίους δὲ μετὰ ταῦτα προσθεῖναι Πολύδωρον οἱ δὲ τοὺς μὲν ἡμίσεις τῶν ἐνακισχιλίων τοῦτον, τοὺς δὲ ἡμίσεις Λυκοῦργον. ὁ δὲ κλῆρος ἦν ἑκάστου τοσοῦτος ὥστε ἀποφορὰν φέρειν ἀνδρὶ μὲν ἑβδομήκοντα κριθῶν μεδίμνους, γυναικὶ δὲ δώδεκα, καὶ τῶν ὑγρῶν καρπῶν ἀναλόγως τὸ πλῆθος. ἀρκέσειν γὰρ ᾤετο τοσοῦτον αὐτοῖς, τῆς τροφῆς πρὸς εὐεξίαν καὶ ὑγείαν ἱκανῆς, ἄλλου δὲ μηδενὸς δεησομένοις. λέγεται δ’ αὐτὸν ὕστερόν ποτε χρόνῳ τὴν χώραν διερχόμενον ἐξ ἀποδημίας ἄρτι τεθερισμένην, ὁρῶντα τοὺς σωροὺς παραλλήλους καὶ ὁμαλεῖς, μειδιᾶσαι, καὶ εἰπεῖν πρὸς τοὺς παρόντας ὡς ἡ Λακωνικὴ φαίνεται πᾶσα πολλῶν ἀδελφῶν εἶναι νεωστὶ νενεμημένων.", "st": "Lyc. 8.3"}, {"sp": "N", "t": "ἐπιχειρήσας δὲ καὶ τὰ ἔπιπλα διαιρεῖν, ὅπως παντάπασιν ἐξέλοι τὸ ἄνισον καὶ ἀνώμαλον, ἐπεὶ χαλεπῶς ἑώρα προσδεχομένους τὴν ἄντικρυς ἀφαίρεσιν, ἑτέρᾳ περιῆλθεν ὁδῷ καὶ κατεπολιτεύσατο τὴν ἐν τούτοις πλεονεξίαν. πρῶτον μὲν γάρ ἀκυρώσας πᾶν νόμισμα χρυσοῦν καὶ ἀργυροῦν μόνῳ χρῆσθαι τῷ σιδηρῷ προσέταξε· καὶ τούτῳ δὲ ἀπὸ πολλοῦ σταθμοῦ καὶ ὄγκου δύναμιν ὀλίγην ἔδωκεν, ὥστε δέκα μυῶν ἀμοιβὴν ἀποθήκης τε μεγάλης ἐν οἰκίᾳ δεῖσθαι καὶ ζεύγους ἄγοντος. τούτου δὲ κυρωθέντος ἐξέπεσεν ἀδικημάτων γένη πολλὰ τῆς Λακεδαίμονος. τίς γὰρ ἢ κλέπτειν ἔμελλεν ἢ δωροδοκεῖν ἢ ἀποστερεῖν ἢ ἁρπάζειν ὃ μήτε κατακρύψαι δυνατὸν ἦν μήτε κεκτῆσθαι ζηλωτόν, ἀλλὰ μηδὲ κατακόψαι λυσιτελές· ὄξει γάρ, ὡς λέγεται, διαπύρου σιδήρου τὸ στόμωμα κατασβέσας ἀφείλετο τὴν εἰς τἆλλα χρείαν καὶ δύναμιν, ἀδρανοῦς καὶ δυσέργου γενομένου.", "st": "Lyc. 9.1"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο τῶν ἀχρήστων καὶ περισσῶν ἐποιεῖτο τεχνῶν ξενηλασίαν. ἔμελλον δέ που καὶ μηδενὸς ἐξελαύνοντος αἱ πολλαὶ τῷ κοινῷ νομίσματι συνεκπεσεῖσθαι, διάθεσιν τῶν ἔργων οὐκ ἐχόντων, τὸ γάρ σιδηροῦν ἀγώγιμον οὐκ ἦν πρὸς τοὺς ἄλλους Ἕλληνας οὐδ’ εἶχε τιμὴν καταγελώμενον, ὥστε οὐδὲ πρίασθαί τι τῶν ξενικῶν καὶ ῥωπικῶν ὑπῆρχεν, οὐδ’ εἰσέπλει φόρτος ἐμπορικὸς εἰς τοὺς λιμένας, οὐδὲ ἐπέβαινε τῆς Λακωνικῆς οὐ σοφιστὴς λόγων, οὐ μάντις ἀγυρτικός, οὐχ ἑταιρῶν τροφεύς, οὐ χρυσῶν τίς, οὐκ ἀργυρῶν καλλωπισμάτων δημιουργός, ἅτε δὴ νομίσματος οὐκ ὄντος. ἀλλὰ οὕτως ἀπερημωθεῖσα κατὰ μικρὸν ἡ τρυφὴ τῶν ζωπυρούντων καὶ τρεφόντων αὐτὴ δι’ αὑτῆς ἐμαραίνετο· καὶ πλεῖον οὐδὲν ἦν τοῖς πολλὰ κεκτημένοις, ὁδὸν οὐκ ἐχούσης εἰς μέσον τῆς εὐπορίας, ἀλλ’ ἐγκατῳκοδομημένης καὶ ἀργούσης. διὸ καὶ τὰ πρόχειρα τῶν σκευῶν καὶ ἀναγκαῖα ταῦτα, κλιντῆρες καὶ δίφροι καὶ τράπεζαι, βέλτιστα παρ’ αὐτοῖς ἐδημιουργεῖτο, καὶ κώθων ὁ Λακωνικὸς εὐδοκίμει μάλιστα πρὸς τὰς στρατείας, ὥς φησι Κριτίας. τὰ γὰρ ἀναγκαίως πινόμενα τῶν ὑδάτων καὶ δυσωποῦντα τὴν ὄψιν ἀπεκρύπτετο τῇ χρόᾳ, καὶ τοῦ θολεροῦ προσκόπτοντος ἐντὸς καὶ προσισχομένου τοῖς ἄμβωσι, καθαρώτερον ἐπλησίαζε τῷ στόματι τὸ πινόμενον. αἴτιος δὲ καὶ τούτων ὁ νομοθέτης· ἀπηλλαγμένοι γὰρ οἱ δημιουργοὶ τῶν ἀχρήστων ἐν τοῖς ἀναγκαίοις ἐπεδείκνυντο τὴν καλλιτεχνίαν.", "st": "Lyc. 9.3"}, {"sp": "N", "t": "ἔτι δὲ μᾶλλον ἐπιθέσθαι τῇ τρυφῇ καὶ τὸν ζῆλον ἀφελέσθαι τοῦ πλούτου διανοηθείς, τὸ τρίτον πολίτευμα καὶ κάλλιστον ἐπῆγε, τὴν τῶν συσσιτίων κατασκευήν, ὥστε δειπνεῖν μετ’ ἀλλήλων συνιόντας ἐπὶ κοινοῖς καὶ τεταγμένοις ὄψοις καὶ σιτίοις, οἴκοι δὲ μὴ διαιτᾶσθαι κατακλινέντας εἰς στρωμνὰς πολυτελεῖς καὶ τραπέζας, χερσὶ δημιουργῶν καὶ μαγείρων ὑπὸ σκότος, ὥσπερ ἀδηφάγα ζῷα, πιαινομένους, καὶ διαφθείροντας ἅμα τοῖς ἤθεσι τὰ σώματα πρὸς πᾶσαν ἐπιθυμίαν ἀνειμένα καὶ πλησμονήν, μακρῶν μὲν ὕπνων, θερμῶν δὲ λουτρῶν, πολλῆς δὲ ἡσυχίας καὶ τρόπον τινὰ νοσηλείας καθημερινῆς δεομένην. μέγα μὲν οὖν καὶ τοῦτο ἦν, μεῖζον δὲ τὸ τὸν πλοῦτον ἄζηλον, ὥς φησι Θεόφραστος, καὶ ἄπλουτον ἀπεργάσασθαι τῇ κοινότητι τῶν δείπνων καὶ τῇ περὶ τὴν δίαιταν εὐτελείᾳ. χρῆσις γάρ οὐκ ἦν οὐδὲ ἀπόλαυσις οὐδὲ ὄψις ὅλως ἢ ἐπίδειξις τῆς πολλῆς παρασκευῆς, ἐπὶ τὸ αὐτὸ δεῖπνον τῷ πένητι τοῦ πλουσίου βαδίζοντος· ὥστε τοῦτο δὴ τὸ θρυλούμενον ἐν μόνῃ τῶν ὑπὸ τὸν ἥλιον πόλεων τῇ Σπάρτῃ βλέπεσθαι, τυφλὸν ὄντα τὸν πλοῦτον καὶ κείμενον ὥσπερ γραφὴν ἄψυχον καὶ ἀκίνητον. οὐδὲ γὰρ οἴκοι προδειπνήσαντας ἐξῆν βαδίζειν ἐπὶ τὰ συσσίτια πεπληρωμένους, ἀλλ’ ἐπιμελῶς οἱ λοιποὶ παραφυλάττοντες τὸν μὴ πίνοντα μηδὲ ἐσθίοντα μετ’ αὐτῶν ἐκάκιζον ὡς ἀκρατῆ καὶ πρὸς τὴν κοινὴν ἀπομαλακιζόμενον δίαιταν.", "st": "Lyc. 10.1"}, {"sp": "N", "t": "διὸ καὶ μάλιστά φασι τῷ Λυκούργῳ πρὸς τοῦτο τὸ πολίτευμα χαλεποὺς γενέσθαι τοὺς εὐπόρους, καὶ συστάντας ἐπ’ αὐτὸν ἀθρόους καταβοᾶν καὶ ἀγανακτεῖν τέλος δὲ βαλλόμενος ὑπὸ πολλῶν ἐξέπεσε τῆς ἀγορᾶς δρόμῳ. καὶ τοὺς μὲν ἄλλους ἔφθασεν εἷς ἱερὸν καταφυγών εἷς δέ τις νεανίσκος, ἄλλως μὲν οὐκ ἀφυής, ὀξὺς δὲ καὶ θυμοειδής, Ἄλκανδρος, ἐπικείμενος καὶ διώκων ἐπιστραφέντος αὐτοῦ τῇ βακτηρίᾳ πατάξας τὸν ὀφθαλμὸν ἐξέκοψεν. ὁ μὲν οὖν Λυκοῦργος οὐδὲν ἐνδοὺς πρὸς τὸ πάθος, ἀλλὰ στὰς ἐναντίος ἔδειξε τοῖς πολίταις τὸ πρόσωπον ᾑμαγμένον καὶ διεφθαρμένην τὴν ὄψιν αἰδὼς δὲ πολλὴ καὶ κατήφεια τοὺς ἰδόντας ἔσχεν, ὥστε παραδοῦναι τὸν Ἄλκανδρον αὐτῷ καὶ προπέμψαι μέχρι τῆς οἰκίας συναγανακτοῦντας. ὁ δὲ Λυκοῦργος ἐκείνους μὲν ἐπαινέσας ἀφῆκε, τὸν δὲ Ἄλκανδρον εἰσαγαγὼν οἴκαδε κακὸν μὲν οὐδὲν οὔτ’ ἐποίησεν οὔτ’ εἶπεν, ἀπαλλάξας δὲ τοὺς συνήθεις ὑπηρέτας καὶ θεραπευτῆρας ἐκεῖνον ἐκέλευσεν ὑπηρετεῖν. ὁ δὲ οὐκ ὢν ἀγεννὴς ἐποίει τὸ προσταττόμενον σιωπῇ, καὶ παραμένων ἅμα τῷ Λυκούργῳ καὶ συνδιαιτώμενος ἐν τῷ κατανοεῖν τὴν πρᾳότητα καὶ τὸ ἀπαθὲς αὐτοῦ τῆς ψυχῆς καὶ τὸ περὶ τὴν δίαιταν αὐστηρὸν καὶ τὸ πρὸς τοὺς πόνους ἄκαμπτον, αὐτός τε δεινῶς διετέθη περὶ τὸν ἄνδρα, καὶ πρὸς τοὺς συνήθεις καὶ φίλους ἔλεγεν ὡς οὐ σκληρὸς οὐδ’ αὐθάδης ὁ Λυκοῦργος, ἀλλὰ μόνος ἥμερος καὶ πρᾷός ἐστι τοῖς ἄλλοις. οὕτω μὲν οὖν οὗτος ἐκεκόλαστο καὶ τοιαύτην ὑπεσχήκει δίκην, ἐκ πονηροῦ νέου καὶ αὐθάδους ἐμμελέστατος ἀνὴρ καὶ σωφρονικώτατος γενόμενος, τοῦ δὲ πάθους ὑπόμνημα Λυκοῦργος ἱδρύσατο τῆς Ἀθηνᾶς ἱερόν, ἣν Ὀπτιλῖτιν προσηγόρευσε· τοὺς γὰρ ὀφθαλμοὺς ὀπτίλους οἱ τῇδε Δωριεῖς καλοῦσιν. ἔνιοι μέντοι τὸν Λυκοῦργον, ὧν καὶ Διοσκορίδης ἐστὶν ὁ συντεταγμένος τὴν Λακωνικὴν πολιτείαν, πληγῆναι μέν φασιν, οὐ τυφλωθῆναι δὲ τὸν ὀφθαλμόν, ἀλλὰ καὶ τὸ ἱερὸν τῇ θεῷ τῆς ἀκέσεως χαριστήριον ἱδρύσασθαι. τὸ μέντοι φέρειν βακτηρίαν ἐκκλησιάζοντες οἱ Σπαρτιᾶται μετὰ τὴν συμφορὰν ἐκείνην ἀπέμαθον.", "st": "Lyc. 11.1"}, {"sp": "N", "t": "τὰ δὲ συσσίτια Κρῆτες μὲν ἀνδρεῖα, Λακεδαιμόνιοι δὲ φιδίτια προσαγορεύουσιν, εἴτε ὡς φιλίας καὶ φιλοφροσύνης ὑπαρχόντων, ἀντὶ τοῦ λ τὸ δ λαμβάνοντες, εἴτε ὡς πρὸς εὐτέλειαν καὶ φειδὼ συνεθιζόντων. οὐδὲν δὲ κωλύει καὶ τὸν πρῶτον ἔξωθεν ἐπικεῖσθαι φθόγγον, ὥσπερ ἔνιοί φασιν, ἐδιτίων παρὰ τὴν δίαιταν καὶ τὴν ἐδωδὴν λεγομένων. συνήρχοντο δὲ ἀνὰ πεντεκαίδεκα καὶ βραχεῖ τούτων ἐλάττους ἢ πλείους. ἔφερε δὲ ἕκαστος κατὰ μῆνα τῶν συσσίτων ἀλφίτων μέδιμνον, οἴνου χόας ὀκτώ, τυροῦ πέντε μνᾶς, σύκων ἡμιμναῖα πέντε, πρὸς δὲ τούτοις εἰς ὀψωνίαν μικρόν τι κομιδῇ νομίσματος· ἄλλως δὲ καὶ θύσας τις ἀπαρχὴν καὶ θηρεύσας μέρος ἔπεμψεν εἰς τὸ συσσίτιον. ἐξῆν γὰρ οἴκοι δειπνεῖν ὁπότε θύσας τις ἢ κυνηγῶν ὀψίσειε, τοὺς δὲ ἄλλους ἔδει παρεῖναι. καὶ μέχρι γε πολλοῦ τὰς συσσιτήσεις ἀκριβῶς διεφύλαττον. Ἄγιδος γοῦν τοῦ βασιλέως, ὡς ἐπανῆλθεν ἀπὸ τῆς στρατείας καταπεπολεμηκὼς Ἀθηναίους, βουλομένου παρὰ τῇ γυναικὶ δειπνεῖν καὶ μεταπεμπομένου τὰς μερίδας, οὐκ ἔπεμψαν οἱ πολέμαρχοι, τοῦ δὲ μεθ’ ἡμέραν ὑπ’ ὀργῆς μὴ θύσαντος ἣν ἔδει θυσίαν, ἐζημίωσαν αὐτόν.", "st": "Lyc. 12.1"}, {"sp": "N", "t": "εἰς δὲ τὰ συσσίτια καὶ παῖδες ἐφοίτων, ὥσπερ εἰς διδασκαλεῖα σωφροσύνης ἀγόμενοι, καὶ λόγων ἠκροῶντο πολιτικῶν καὶ παιδευτὰς ἐλευθερίας ἑώρων, αὐτοί τε παίζειν εἰθίζοντο καὶ σκώπτειν ἄνευ βωμολοχίας καὶ σκωπτόμενοι μὴ δυσχεραίνειν. σφόδρα γάρ ἐδόκει καὶ τοῦτο Λακωνικὸν εἶναι, σκώμματος ἀνέχεσθαι μὴ φέροντα δὲ ἐξῆν παραιτεῖσθαι, καὶ ὁ σκώπτων ἐπέπαυτο. τῶν δ’ εἰσιόντων ἑκάστῳ δείξας ὁ πρεσβύτατος τὰς θύρας, διὰ τούτων φησίν, ἔξω λόγος οὐκ ἐκπορεύεται δοκιμάζεσθαι δὲ τὸν βουλόμενον τοῦ συσσιτίου μετασχεῖν οὕτω φασί. λαβὼν τῶν συσσίτων ἕκαστος ἀπομαγδαλίαν εἰς τὴν χεῖρα, τοῦ διακόνου φέροντος ἀγγεῖον ἐπὶ τῆς κεφαλῆς, ἔβαλλε σιωπῇ καθάπερ ψῆφον, ὁ μὲν δοκιμάζων ἁπλῶς, ὁ δ’ ἐκκρίνων σφόδρα τῇ χειρὶ πιέσας. ἡ γὰρ πεπιεσμένη τὴν τῆς τετρημένης ἔχει δύναμιν. κἂν μίαν εὕρωσι τοιαύτην, οὐ προσδέχονται τὸν ἐπεισιόντα, βουλόμενοι πάντας ἡ δομένους ἀλλήλοις συνεῖναι. τὸν δὲ οὕτως ἀποδοκιμασθέντα κεκαδδίσθαι λέγουσι· κάδδιχος γὰρ καλεῖται τὸ ἀγγεῖον εἰς ὃ τὰς ἀπομαγδαλίας ἐμβάλλουσι, τῶν δὲ ὄψων εὐδοκίμει μάλιστα παρ’ αὐτοῖς ὁ μέλας ζωμός, ὥστε μηδὲ κρεαδίου δεῖσθαι τοὺς πρεσβυτέρους, ἀλλὰ παραχωρεῖν τοῖς νεανίσκοις, αὐτοὺς δὲ τοῦ ζωμοῦ καταχεομένους ἑστιᾶσθαι. λέγεται δέ τινα τῶν Ποντικῶν βασιλέων ἕνεκα τοῦ ζωμοῦ καὶ πρίασθαι Λακωνικὸν μάγειρον εἶτα γευσάμενον δυσχερᾶναι· καὶ τὸν μάγειρον εἰπεῖν ὦ βασιλεῦ, τοῦτον δεῖ τὸν ζωμὸν ἐν τῷ Εὐρώτᾳ λελουμένους ἐποψᾶσθαι. πιόντες δὲ μετρίως ἀπίασι δίχα λαμπάδος, οὐ γάρ ἔξεστι πρὸς φῶς βαδίζειν, οὔτε ταύτην οὔτε ἄλλην ὁδόν, ὅπως ἐθίζωνται σκότους καὶ νυκτὸς εὐθαρσῶς καὶ ἀδεῶς ὁδεύειν. τὰ μὲν οὖν συσσίτια τοιαύτην ἔχει τάξιν.", "st": "Lyc. 12.4"}, {"sp": "N", "t": "νόμους δὲ γεγραμμένους ὁ Λυκοῦργος οὐκ ἔθηκεν, ἀλλὰ μία τῶν καλουμένων ῥητρῶν ἔστιν αὕτη. τὰ μὲν γάρ κυριώτατα καὶ μέγιστα πρὸς εὐδαιμονίαν πόλεως καὶ ἀρετήν, ἐν τοῖς ἤθεσιν ᾤετο καὶ ταῖς ἀγωγαῖς τῶν πολιτῶν ἐγκατεστοιχειωμένα, μένειν ἀκίνητα καὶ βέβαια, ἔχοντα τὴν προαίρεσιν δεσμὸν ἰσχυρότερον τῆς ἀνάγκης, ἣν ἡ παίδευσις ἐμποιεῖ τοῖς νέοις, νομοθέτου διάθεσιν ἀπεργαζομένη περὶ ἕκαστον αὐτῶν. τὰ δὲ μικρὰ καὶ χρηματικὰ συμβόλαια καὶ μεταπίπτοντα ταῖς χρείαις ἄλλοτε ἄλλως, βέλτιον ἦν μὴ καταλαμβάνειν ἐγγράφοις ἀνάγκαις μηδὲ ἀκινήτοις ἔθεσιν, ἀλλ’ ἐᾶν ἐπὶ τῶν καιρῶν, προσθέσεις λαμβάνοντα καὶ ἀφαιρέσεις, ἃς ἂν οἱ πεπαιδευμένοι δοκιμάσωσι. τὸ γὰρ ὅλον καὶ πᾶν τῆς νομοθεσίας ἔργον εἰς τὴν παιδείαν ἀνῆψε.", "st": "Lyc. 13.1"}, {"sp": "N", "t": "μία μὲν οὖν τῶν ῥητρῶν ἦν, ὥσπερ εἴρηται, μὴ χρῆσθαι νόμοις ἐγγράφοις. ἑτέρα δὲ πάλιν κατὰ τῆς πολυτελείας, ὅπως οἰκίᾳ πᾶσα τὴν μὲν ὀροφὴν ἀπὸ πελέκεως εἰργασμένην ἔχῃ, τὰς δὲ θύρας ἀπὸ πρίονος μόνου καὶ μηδενὸς τῶν ἄλλων ἐργαλείων, ὅπερ γάρ ὕστερον Ἐπαμεινώνδαν εἰπεῖν λέγουσιν ἐπὶ τῆς ἑαυτοῦ τραπέζης, ὡς τὸ τοιοῦτον ἄριστον οὐ χωρεῖ προδοσίαν, τοῦτο πρῶτος ἐνόησε Λυκοῦργος, ὡς οἰκίᾳ τοιαύτη τρυφὴν οὐ χωρεῖ καὶ πολυτέλειαν, οὐδ’ ἔστιν οὐδεὶς οὕτως ἀπειρόκαλος καὶ ἀνόητος ὥστε εἰς οἰκίαν ἀφελῆ καὶ δημοτικὴν εἰσφέρειν κλίνας ἀργυρόποδας καὶ στρωμνὰς ἁλουργεῖς καὶ χρυσᾶς κύλικας καὶ τὴν τούτοις ἑπομένην πολυτέλειαν, ἀλλ’ ἀνάγκη συναρμόζεσθαι καὶ συνεξομοιοῦν τῇ μὲν οἰκίᾳ τὴν κλίνην, τῇ δὲ κλίνῃ τὴν ἐσθῆτα, ταύτῃ δὲ τὴν ἄλλην χορηγίαν καὶ κατασκευήν. ἐκ δὲ ταύτης τῆς συνηθείας φασὶ καὶ Λεωτυχίδην τὸν πρεσβύτερον ἐν Κορίνθῳ δειπνοῦντα, καὶ θεασάμενον τῆς στέγης τοῦ οἴκου τὴν κατασκευὴν πολυτελῆ καὶ φατνωματικήν, ἐρωτῆσαι τὸν ξένον εἰ τετράγωνα παρ’ αὐτοῖς τὰ ξύλα φύεται.", "st": "Lyc. 13.3"}, {"sp": "N", "t": "τρίτην δὲ ῥήτραν διαμνημονεύουσι τοῦ Λυκούργου, τὴν κωλύουσαν ἐπὶ τοὺς αὐτοὺς πολεμίους πολλάκις στρατεύειν, ἵνα μὴ πολλάκις ἀμύνεσθαι συνεθιζόμενοι πολεμικοὶ γένωνται. καὶ τοῦτό γε μάλιστα κατηγοροῦσιν Ἀγησιλάου τοῦ βασιλέως ὕστερον, ὡς ταῖς συνεχέσι καὶ πυκναῖς εἰς τὴν Βοιωτίαν ἐμβολαῖς καὶ στρατείαις τοὺς Θηβαίους ἀντιπάλους τοῖς Λακεδαιμονίοις κατασκευάσαντος, διὸ καὶ τετρωμένον αὐτὸν ἰδὼν Ἀνταλκίδας, καλά, ἔφη, τὰ διδασκάλια παρὰ Θηβαίων ἀπολαμβάνεις, μὴ βουλομένους αὐτοὺς μηδὲ εἰδότας μάχεσθαι διδάξας. τὰ μὲν οὖν τοιαῦτα νομοθετήματα ῥήτρας ὠνόμασεν, ὡς παρὰ τοῦ θεοῦ κομιζόμενα καὶ χρησμοὺς ὄντα.", "st": "Lyc. 13.6"}, {"sp": "N", "t": "τῆς δὲ παιδείας, ἣν μέγιστον ἡγεῖτο τοῦ νομοθέτου καὶ κάλλιστον ἔργον εἶναι, πόρρωθεν ἀρχόμενος εὐθὺς ἐπεσκόπει τὰ περὶ τοὺς γάμους καὶ τὰς γενέσεις, οὐ γάρ, ὡς Ἀριστοτέλης φησίν, ἐπιχειρήσας σωφρονίζειν τὰς γυναῖκας, ἐπαύσατο μὴ κρατῶν τῆς πολλῆς ἀνέσεως καὶ γυναικοκρατίας διὰ τὰς πολλὰς στρατείας τῶν ἀνδρῶν, ἐν αἷς ἠναγκάζοντο κυρίας ἀπολείπειν ἐκείνας, καὶ διὰ τοῦτο μᾶλλον τοῦ προσήκοντος αὐτὰς ἐθεράπευον καὶ δεσποίνας προσηγόρευον ἀλλὰ καὶ τούτων τὴν ἐνδεχομένην ἐπιμέλειαν ἐποιήσατο. τὰ μέν γε σώματα τῶν παρθένων δρόμοις καὶ πάλαις καὶ βολαῖς δίσκων καὶ ἀκοντίων διεπόνησεν, ὡς ἥ τε τῶν γεννωμένων ῥίζωσις ἰσχυρὰν ἐν ἰσχυροῖς σώμασιν ἀρχὴν λαβοῦσα βλαστάνοι βέλτιον, αὐταί τε μετὰ ῥώμης τοὺς τόκους ὑπομένουσαι καλῶς ἅμα καὶ ῥᾳδίως ἀγωνίζοιντο πρὸς τὰς ὠδῖνας. ἀφελὼν δὲ θρύψιν καὶ σκιατραφίαν καὶ θηλύτητα πᾶσαν οὐδὲν ἧττον εἴθισε τῶν κόρων τὰς κόρας γυμνάς τε πομπεύειν καὶ πρὸς ἱεροῖς τισιν ὀρχεῖσθαι καὶ ἄδειν τῶν νέων παρόντων καὶ θεωμένων. ἔστι δὲ ὅτε καὶ σκώμματα λέγουσαι πρὸς ἕκαστον εὐχρήστως ἐπελαμβάνοντο τῶν ἁμαρτανομένων καὶ πάλιν εἰς τοὺς ἀξίους αὐτῶν ἐγκώμια μετ’ ᾠδῆς πεποιημένα διεξιοῦσαι, φιλοτιμίαν πολλὴν καὶ ζῆλον ἐνεποίουν τοῖς νεανίσκοις, ὁ γάρ ἐγκωμιασθεὶς ἐπ’ ἀνδραγαθίᾳ καὶ κλεινὸς ἐν ταῖς παρθένοις γεγονὼς ἀπῄει μεγαλυνόμενος ὑπὸ τῶν ἐπαίνων αἱ δὲ μετὰ παιδιᾶς καὶ σκωμμάτων δήξεις οὐδὲν ἀμβλύτεραι τῶν μετὰ σπουδῆς νουθετημάτων ἦσαν, ἅτε δὴ πρὸς τὴν θέαν ὁμοῦ τοῖς ἄλλοις πολίταις καὶ τῶν βασιλέων καὶ τῶν γερόντων συμπορευομένων.", "st": "Lyc. 14.1"}, {"sp": "N", "t": "ἡ δὲ γύμνωσις τῶν παρθένων οὐδὲν αἰσχρὸν εἶχεν, αἰδοῦς μὲν παρούσης, ἀκρασίας δὲ ἀπούσης, ἀλλ’ ἐθισμὸν ἀφελῆ καὶ ζῆλον εὐεξίας ἐνειργάζετο, καὶ φρονήματος τὸ θῆλυ παρέγευεν οὐκ ἀγεννοῦς, ὡς μηδὲν ἧττον αὐτῷ καὶ ἀρετῆς καὶ φιλοτιμίας μετουσίαν οὖσαν. ὅθεν αὐταῖς καὶ λέγειν ἐπῄει καὶ φρονεῖν οἷα καὶ περὶ Γοργοῦς ἱστόρηται τῆς Λεωνίδου γυναικός, εἰπούσης γάρ τινος, ὡς ἔοικε, ξένης πρὸς αὐτὴν ὡς μόναι τῶν ἀνδρῶν ἄρχετε ὑμεῖς αἱ Λάκαιναι, μόναι γάρ, ἔφη, τίκτομεν ἄνδρας.", "st": "Lyc. 14.4"}, {"sp": "N", "t": "ἦν μὲν οὖν καὶ ταῦτα παρορμητικὰ πρὸς γάμον λέγω δὲ τὰς πομπὰς τῶν παρθένων καὶ τὰς ἀποδύσεις καὶ τοὺς ἀγῶνας ἐν ὄψει τῶν νέων, ἀγομένων οὐ γεωμετρικαῖς, ἀλλ’ ἐρωτικαῖς, ὥς φησιν ὁ Πλάτων, ἀνάγκαις· οὐ μὴν ἀλλὰ καὶ ἀτιμίαν τινὰ προσέθηκε τοῖς ἀγάμοις. εἴργοντο γὰρ ἐν ταῖς γυμνοπαιδίαις τῆς θέας· τὸν δὲ χειμῶνος οἱ μὲν ἄρχοντες αὑτοὺς ἐκέλευον ἐν κύκλῳ γυμνοὺς περιϊέναι τὴν ἀγοράν, οἱ δὲ περιϊόντες ᾖδον εἰς αὑτοὺς ᾠδήν τινα πεποιημένην, ὡς δίκαια πάσχοιεν, ὅτι τοῖς νόμοις ἀπειθοῦσι· τιμῆς δὲ καὶ θεραπείας ἣν νέοι πρεσβυτέροις παρεῖχον, ἐστέρηντο. ὅθεν καὶ τὸ πρὸς Δερκυλλίδαν ῥηθὲν οὐδεὶς ἐμέμψατο, καίπερ εὐδόκιμον ὄντα στρατηγόν. ἐπιόντι γὰρ αὐτῷ τῶν νεωτέρων τις ἕδρας οὐχ ὑπεῖξεν, εἰπών, οὐδὲ γὰρ ἐμοὶ σὺ τὸν ὑπείξοντα γεγέννηκας.", "st": "Lyc. 15.1"}, {"sp": "N", "t": "ἐγάμουν δὲ δι’ ἁρπαγῆς, οὐ μικρὰς Οὐδὲ ἀώρους πρὸς γάμον, ἀλλὰ καὶ ἀκμαζούσας καὶ πεπείρους. τὴν δὲ ἁρπασθεῖσαν ἡ νυμφεύτρια καλουμένη παραλαβοῦσα, τὴν μὲν κεφαλὴν ἐν χρῷ περιέκειρεν, ἱματίῳ δὲ ἀνδρείῳ καὶ ὑποδήμασιν ἐνσκευάσασα κατέκλινεν ἐπὶ στιβάδα μόνην ἄνευ φωτός. ὁ δὲ νυμφίος οὐ μεθύων Οὐδὲ θρυπτόμενος, ἀλλὰ νήφων, ὥσπερ ἀεί, δεδειπνηκὼς ἐν τοῖς φιδιτίοις, παρεισελθὼν ἔλυε τὴν ζώνην καὶ μετήνεγκεν ἀράμενος ἐπὶ τὴν κλίνην. συνδιατρίψας δὲ χρόνον οὐ πολὺν ἀπῄει κοσμίως ο ὑπὲρ εἰώθει τὸ πρότερον, καθευδήσων μετὰ τῶν ἄλλων νέων. καὶ τὸ λοιπὸν οὕτως ἔπραττε, τοῖς μὲν ἡλικιώταις συνδιημερεύων καὶ συναναπαυόμενος, πρὸς δὲ τὴν νύμφην κρύφα μετ’ εὐλαβείας φοιτῶν, αἰσχυνόμενος καὶ δεδοικὼς μή τις αἴσθοιτο τῶν ἔνδον, ἅμα καὶ τῆς νύμφης ἐπιτεχνωμένης καὶ συνευπορούσης ὅπως ἂν ἐν καιρῷ καὶ λανθάνοντες ἀλλήλοις συμπορεύοιντο. καὶ τοῦτο ἔπραττον οὐκ ὀλίγον χρόνον, ἀλλ’ ὥστε καὶ παῖδας γενέσθαι ἐνίοις πρὶν ἐς ἡμέραν θεάσασθαι τὰς ἑαυτῶν γυναῖκας, ἡ δὲ τοιαύτη σύνοδος οὐ μόνον ἐγκρατείας καὶ σωφροσύνης ἄσκησις ἦν, ἀλλὰ τοῖς τε σώμασι γονίμους καὶ τῷ φιλεῖν ἀεὶ καινοὺς καὶ προσφάτους ἦγεν ἐπὶ τὴν κοινωνίαν, οὐ διακορεῖς οὐδ’ ἐξιτήλους ταῖς ἀνέδην κοινωνίαις, ἀλλ’ ἀεὶ τι λείψανον καὶ ὑπέκκαυμα πόθου καὶ χάριτος ἐναπολείποντας ἀλλήλοις.", "st": "Lyc. 15.3"}, {"sp": "N", "t": "τοσαύτην δὲ τοῖς γάμοις ἐπιστήσας αἰδῶ καὶ τάξιν, οὐδὲν ἧττον ἐξέβαλε τὴν κενὴν καὶ γυναικώδη ζηλοτυπίαν, ἐν καλῷ καταστήσας ὕβριν μὲν καὶ ἀναξίαν πᾶσαν εἴργειν ἀπὸ τοῦ γάμου, παίδων δὲ καὶ τεκνώσεως κοινωνεῖν τοῖς ἀξίοις, καταγελῶντας τῶν ὡς ἄμικτα καὶ ἀκοινώνητα ταῦτα μετιόντων σφαγαῖς καὶ πολέμοις. ἐξῆν μὲν γὰρ ἀνδρὶ πρεσβυτέρῳ νέας γυναικός, εἰ δὴ τινα τῶν καλῶν καὶ ἀγαθῶν ἀσπάσαιτο νέων καὶ δοκιμάσειεν, εἰσαγαγεῖν παρ’ αὐτὴν καὶ πλήσαντα γενναίου σπέρματος ἴδιον αὑτοῖς ποιήσασθαι τὸ γεννηθέν. ἐξῆν δὲ πάλιν ἀνδρὶ χρηστῷ, τῶν εὐτέκνων τινὰ καὶ σωφρόνων θαυμάσαντι γυναικῶν ἑτέρῳ γεγαμημένην, πεῖσαι τὸν ἄνδρα συνελθεῖν, ὥσπερ ἐν χώρᾳ, καλλικάρπῳ φυτεύοντα καὶ ποιούμενον παῖδας ἀγαθούς, ἀγαθῶν ὁμαίμους καὶ συγγενεῖς ἐσομένους. πρῶτον μὲν γάρ οὐκ ἰδίους ἡγεῖτο τῶν πατέρων τοὺς παῖδας, ἀλλὰ κοινοὺς τῆς πόλεως ὁ Λυκοῦργος, ὅθεν οὐκ ἐκ τῶν τυχόντων, ἀλλ’ ἐκ τῶν ἀρίστων ἐβούλετο γεγονότας εἶναι τοὺς πολίτας. ἔπειτα πολλὴν ἀβελτερίαν καὶ τῦφον ἐνεώρα τοῖς περὶ ταῦτα τῶν ἄλλων νομοθετήμασιν, οἳ κύνας μὲν καὶ ἵππους ὑπὸ τοῖς κρατίστοις τῶν ὀχείων βιβάζουσι χάριτι πείθοντες ἢ μισθῷ τοὺς κυρίους, τὰς δὲ γυναῖκας ἐγκλεισάμενοι φρουροῦσιν, ἐξ αὐτῶν μόνων τίκτειν ἀξιοῦντες, κἂν ἄφρονες ὦσι, κἂν παρήλικες, κἂν νοσώδεις, ὡς οὐχὶ πρώτοις τοῖς κεκτημένοις καὶ τρέφουσι τῶν παίδων γινομένων πονηρῶν, ἐὰν ἐκ πονηρῶν γένωνται, καὶ τοὐναντίον χρηστῶν, ἂν τοιαύτης τύχωσι γενέσεως, ταῦτα δὲ οὕτως πραττόμενα φυσικῶς καὶ πολιτικῶς τότε τοσοῦτον ἀπεῖχε τῆς ὕστερον λεγομένης γενέσθαι περὶ τὰς γυναῖκας εὐχερείας ὥστε ὅλως ἄπιστον εἶναι τὸ τῆς μοιχείας παρ’ αὑτοῖς. καὶ λόγος ἀπομνημονεύεται Γεράδα τινὸς Σπαρτιάτου τῶν σφόδρα παλαιῶν, ὃς ἐρωτηθεὶς ὑπὸ ξένου τί πάσχουσιν οἱ μοιχοὶ παρ’ αὑτοῖς, εἶπεν· ὦ ξένε, οὐδεὶς γίνεται μοιχὸς παρ’ ἡμῖν. ἐκείνου δὲ ὑπολαβόντος, ἐὰν οὖν γένηται; ταῦρον, ἔφη ὁ Γεράδας, ἐκτίνει μέγαν, ὃς ὑπερκύψας τὸ Ταΰγετον ἀπὸ τοῦ Εὐρώτα πίεται. θαυμάσαντος δ’ ἐκείνου καὶ φήσαντος· πῶς δὲ ἂν γένοιτο βοῦς τηλικοῦτος; γελάσας ὁ Γεράδας, πῶς δ’ ἄν, ἔφη, ἐν Σπάρτῃ μοιχὸς γένοιτο; ταῦτα μὲν οὖν ἱστόρηται περὶ τῶν γάμων.", "st": "Lyc. 15.6"}, {"sp": "N", "t": "τὸ δὲ γεννηθὲν οὐκ ἦν κύριος ὁ γεννήσας τρέφειν, ἀλλ’ ἔφερε λαβὼν εἰς τόπον τινὰ λέσχην καλούμενον, ἐν ᾧ καθήμενοι τῶν φυλετῶν οἱ πρεσβύτατοι καταμαθόντες τὸ παιδάριον, εἰ μὲν εὐπαγὲς εἴη καὶ ῥωμαλέον, τρέφειν ἐκέλευον, κλῆρον αὐτῷ τῶν ἐνακισχιλίων προσνείμαντες εἰ δ’ ἀγεννὲς καὶ ἄμορφον, ἀπέπεμπον εἰς τὰς λεγομένας Ἀποθέτας, παρὰ Ταΰγετον βαραθρώδη τόπον, ὡς οὔτε αὐτῷ ζῆν ἄμεινον ὂν οὔτε τῇ πόλει τὸ μὴ καλῶς εὐθὺς ἐξ ἀρχῆς πρὸς εὐεξίαν καὶ ῥώμην πεφυκός. ὅθεν οὐδὲ ὕδατι τὰ βρέφη, ἀλλ’ οἴνῳ περιέλουον αἱ γυναῖκες, βάσανόν τινα ποιούμεναι τῆς κράσεως αὐτῶν. λέγεται γὰρ ἐξίστασθαι τὰ ἐπιληπτικὰ καὶ νοσώδη πρὸς τὸν ἄκρατον ἀποσφακελίζοντα, τὰ δ’ ὑγιεινὰ μᾶλλον στομοῦσθαι καὶ κρατύνεσθαι τὴν ἕξιν. ἦν δὲ περὶ τὰς τροφοὺς ἐπιμέλειά τις μετὰ τέχνης, ὥστ’ ἄνευ σπαργάνων ἐκτρεφούσας τὰ βρέφη τοῖς μέλεσι καὶ τοῖς εἴδεσιν ἐλευθέρια ποιεῖν, ἔτι δὲ εὔκολα ταῖς διαίταις καὶ ἄσικχα καὶ ἀθαμβῆ σκότου καὶ πρὸς ἐρημίαν ἄφοβα καὶ ἄπειρα δυσκολίας ἀγεννοῦς καὶ κλαυθμυρισμῶν. διὸ καὶ τῶν ἔξωθεν ἔνιοι τοῖς τέκνοις Λακωνικὰς ἐωνοῦντο τίτθας· καὶ τήν γε τὸν Ἀθηναῖον Ἀλκιβιάδην τιτθεύσασαν Ἀμύκλαν ἱστοροῦσι γεγονέναι Λάκαιναν.", "st": "Lyc. 16.1"}, {"sp": "N", "t": "ἀλλὰ τούτῳ μὲν, ὡς Πλάτων φησί, Ζώπυρον ἐπέστησε παιδαγωγὸν Περικλῆς, οὐδέν τι τῶν ἄλλων διαφέροντα δούλων τοὺς δὲ Σπαρτιατῶν παῖδας οὐκ ἐπὶ ὠνητοῖς οὐδὲ μισθίοις ἐποιήσατο παιδαγωγοῖς ὁ Λυκοῦργος, οὐδ’ ἐξῆν ἑκάστῳ τρέφειν οὐδὲ παιδεύειν ὡς ἐβούλετο τὸν υἱόν, ἀλλὰ πάντας εὐθὺς ἑπταετεῖς γενομένους παραλαμβάνων αὐτὸς εἰς ἀγέλας κατελόχιζε, καὶ συννόμους ποιῶν καὶ συντρόφους μετ’ ἀλλήλων εἴθιζε συμπαίζειν καὶ συσχολάζειν. ἄρχοντα δ’ αὑτοῖς παρίστατο τῆς ἀγέλης τὸν τῷ φρονεῖν διαφέροντα καὶ θυμοειδέστατον ἐν τῷ μάχεσθαι· καὶ πρὸς τοῦτον ἀφεώρων καὶ προστάττοντος ἠκροῶντο καὶ κολάζοντος ἐκαρτέρουν, ὥστε τὴν παιδείαν εἶναι μελέτην εὐπειθείας. ἐπεσκόπουν δὲ οἱ πρεσβύτεροι παίζοντας αὐτούς, καὶ τὰ πολλὰ μάχας τινὰς ἐμβάλλοντες ἀεὶ καὶ φιλονεικίας, οὐ παρέργως κατεμάνθανον ὁποῖός ἐστι τὴν φύσιν ἕκαστος αὐτῶν πρὸς τὸ τολμᾶν καὶ μὴ φυγομαχεῖν ἐν ταῖς ἁμίλλαις.", "st": "Lyc. 16.4"}, {"sp": "N", "t": "γράμματα μὲν οὖν ἕνεκα τῆς χρείας ἐμάνθανον ἡ δ’ ἄλλη πᾶσα παιδεία πρὸς τὸ ἄρχεσθαι καλῶς ἐγίνετο καὶ καρτερεῖν πονοῦντα καὶ νικᾶν μαχόμενον. διὸ καὶ τῆς ἡλικίας προερχομένης ἐπέτεινον αὐτῶν τὴν ἄσκησιν, ἐν χρῷ τε κείροντες καὶ βαδίζειν ἀνυποδήτους παίζειν τε γυμνοὺς ὡς τὰ πολλὰ συνεθίζοντες. γενόμενοι δὲ δωδεκαετεῖς ἄνευ χιτῶνος ἤδη διετέλουν, ἓν ἱμάτιον εἰς τὸν ἐνιαυτὸν λαμβάνοντες, αὐχμηροὶ τὰ σώματα καὶ λουτρῶν καὶ ἀλειμμάτων ἄπειροι· πλὴν ὀλίγας ἡμέρας τινὰς τοῦ ἐνιαυτοῦ τῆς τοιαύτης φιλανθρωπίας μετεῖχον. ἐκάθευδον δὲ ὁμοῦ κατ’ ἴλην καὶ ἀγέλην ἐπὶ στιβάδων, ἃς αὑτοῖς συνεφόρουν, τοῦ παρὰ τὸν Εὐρώταν πεφυκότος καλάμου τὰ ἄκρα ταῖς χερσὶν ἄνευ σιδήρου κατακλάσαντες. ἐν δὲ τῷ χειμῶνι τοὺς λεγομένους λυκόφονας ὑπεβάλλοντο καὶ κατεμίγνυσαν ταῖς στιβάσι, θερμαντικὸν ἔχειν τι τῆς ὕλης δοκούσης.", "st": "Lyc. 16.6"}, {"sp": "N", "t": "ἤδη δὲ τοῖς τηλικούτοις ἐρασταὶ τῶν εὐδοκίμων νέων συνανεστρέφοντο· καὶ προσεῖχον οἱ πρεσβύτεροι, καὶ μᾶλλον ἐπιφοιτῶντες εἰς τὰ γυμνάσια, καὶ μαχομένοις καὶ σκώπτουσιν ἀλλήλους παρατυγχάνοντες, οὐ παρέργως, ἀλλὰ τρόπον τινὰ πάντες οἰόμενοι πάντων καὶ πατέρες εἶναι καὶ παιδαγωγοὶ καὶ ἄρχοντες, ὥστε μήτε καιρὸν ἀπολείπεσθαι μήτε χωρίον ἔρημον τοῦ νουθετοῦντος τὸν ἁμαρτάνοντα καὶ κολάζοντος. οὐ μὴν ἀλλὰ καὶ παιδονόμος ἐκ τῶν καλῶν καὶ ἀγαθῶν ἀνδρῶν ἐτάττετο, καὶ κατ’ ἀγέλας αὐτοὶ προΐσταντο τῶν λεγομένων εἰρένων ἀεὶ τὸν σωφρονέστατον καὶ μαχιμώτατον. εἴρενας δὲ καλοῦσι τοὺς ἔτος ἤδη δεύτερον ἐκ παίδων γεγονότας, μελλείρενας δὲ τῶν παίδων τοὺς πρεσβυτάτους. οὗτος οὖν ὁ εἴρην, εἴκοσι ἔτη γεγονώς, ἄρχει τε τῶν ὑποτεταγμένων ἐν ταῖς μάχαις, καὶ κατ’ οἶκον ὑπηρέταις χρῆται πρὸς τὸ δεῖπνον. ἐπιτάσσει δὲ τοῖς μὲν ἁδροῖς ξύλα φέρειν, τοῖς δὲ μικροτέροις λάχανα, καὶ φέρουσι κλέπτοντες, οἱ μὲν ἐπὶ τοὺς κήπους βαδίζοντες, οἱ δὲ εἰς τὰ τῶν ἀνδρῶν συσσίτια παρεισρέοντες εὖ μάλα πανούργως καὶ πεφυλαγμένως· ἂν δ’ ἁλῷ, πολλὰς λαμβάνει πληγὰς τῇ μάστιγι, ῥᾳθύμως δοκῶν κλέπτειν καὶ ἀτέχνως. κλέπτουσι δὲ καὶ τῶν σιτίων ὅ τι ἂν δύνωνται, μανθάνοντες εὐφυῶς ἐπιτίθεσθαι τοῖς καθεύδουσιν ἢ ῥᾳθύμως φυλάττουσι. τῷ δὲ ἁλόντι ζημία πληγαὶ καὶ τὸ πεινῆν. γλίσχρον γὰρ αὐτοῖς ἐστι δεῖπνον, ὅπως δι’ αὑτῶν ἀμυνόμενοι τὴν ἔνδειαν ἀναγκάζωνται τολμᾶν καὶ πανουργεῖν.", "st": "Lyc. 17.1"}, {"sp": "N", "t": "καὶ τοῦτο μὲν ἔργον τῆς ὀλιγοσιτίας· παρέργον δέ φασι τὴν τῶν σωμάτων αὔξησιν. φέρεται, γάρ εἰς μῆκος, ὅταν τὸ πνεῦμα μὴ πολλὴν σχῇ διατριβὴν καὶ ἀσχολίαν ὑπὸ πλήθους τροφῆς εἰς βάθος καὶ πλάτος πιεζόμενον, ἀλλ’ ἄνω βαδίζῃ διὰ κουφότητα, τοῦ σώματος ἐκλύτως καὶ ῥᾳδίως ἐπιδιδόντος. τὸ δ’ αὐτὸ τοῦτο καὶ καλοὺς δοκεῖ ποιεῖν αἱ γὰρ ἰσχναὶ καὶ διάκενοι μᾶλλον ἕξεις ὑπακούουσι πρὸς τὴν διάρθρωσιν, αἱ δὲ ὀγκώδεις καὶ πολύτροφοι διὰ βάρος ἀντιβαίνουσιν, ὥσπερ ἀμέλει καὶ τῶν ἐν τῷ κύειν καθαιρομένων γυναικῶν ἰσχνὰ μὲν, εὐειδῆ δὲ καὶ γλαφυρὰ γίνεται τὰ βρέφη, διὰ τὴν ἐλαφρότητα τῆς ὕλης κρατουμένης μᾶλλον ὑπὸ τοῦ τυποῦντος, ἀλλὰ γὰρ ἡ μὲν αἰτία τοῦ συμβαίνοντος ἐν μέσῳ προκείσθω σκοπεῖν.", "st": "Lyc. 17.5"}, {"sp": "N", "t": "οὕτω δὲ κλέπτουσι πεφροντισμένως οἱ παῖδες, ὥστε λέγεταί τίς ἤδη σκύμνον ἀλώπεκος κεκλοφὼς καὶ τῷ τριβωνίῳ περιστέλλων, σπαρασσόμενος ὑπὸ τοῦ θηρίου τὴν γαστέρα τοῖς ὄνυξι καὶ τοῖς ὀδοῦσιν, ὑπὲρ τοῦ λαθεῖν ἐγκαρτερῶν ἀποθανεῖν. καὶ τοῦτο μὲν οὐδὲ ἀπὸ τῶν νῦν ἐφήβων ἄπιστόν ἐστιν, ὧν πολλοὺς ἐπὶ τοῦ βωμοῦ τῆς Ὀρθίας ἑωράκαμεν ἐναποθνήσκοντας ταῖς πληγαῖς.", "st": "Lyc. 18.1"}, {"sp": "N", "t": "δειπνήσας δὲ ὁ εἴρην κατακείμενος τῷ μὲν ᾆσαι προσέταξε τῶν παίδων, τῷ δὲ ἐρώτημά τι προὔβαλε πεφροντισμένης δεόμενον ἀποκρίσεως· οἷον, ὅστις ἄριστος ἐν τοῖς ἀνδράσιν, ἢ ποία τίς ἡ τοῦδε πρᾶξις. ἐκ τούτου δὲ καὶ κρίνειν τὰ καλὰ καὶ πολυπραγμονεῖν εὐθὺς ἐξ ἀρχῆς εἰθίζοντο περὶ τῶν πολιτῶν, τὸ γὰρ ἐρωτηθέντα, τίς πολίτης ἀγαθός, ἢ τίς οὐκ εὐδόκιμος, ἀπορεῖν τοῦ ἀποκρίνασθαι, νωθρᾶς ἐποιοῦντο καὶ πρὸς ἀρετὴν ἀφιλοτίμου ψυχῆς σημεῖον. ἔδει δὲ τὴν ἀπόκρισιν καὶ μετ’ αἰτίας εἶναι καὶ ἀποδείξεως εἰς βραχύν τινα συνηγμένης λόγον καὶ σύντομον ὁ δὲ πλημμελῶς ἀποκρινάμενος ἐκολάζετο δῆγμα λαμβάνων ὑπὸ τοῦ εἴρενος εἰς τὸν ἀντίχειρα, πολλάκις δὲ καὶ πρεσβυτέρων παρόντων καὶ ἀρχόντων ὁ εἴρην ἐκόλαζε τοὺς παῖδας, ἀπόδειξιν διδοὺς εἰ μετὰ λόγου καὶ ὡς δεῖ κολάζει, καὶ κολάζων μὲν οὐκ ἐκωλύετο, τῶν δὲ παίδων ἀπελθόντων εὐθύνας ὑπεῖχεν, εἰ τραχύτερον τοῦ δέοντος ἐπετίμησεν ἢ τοὐναντίον ἐκλελυμένως καὶ ἀτόνως.", "st": "Lyc. 18.2"}, {"sp": "N", "t": "ἐκοινώνουν δὲ οἱ ἐρασταὶ τοῖς παισὶ τῆς δόξης ἐπ’ ἀμφότερα· καὶ λέγεταί ποτε παιδὸς ἐν τῷ μάχεσθαι φωνὴν ἀγεννῆ προεμένου ζημιωθῆναι τὸν ἐραστὴν ὑπὸ τῶν ἀρχόντων, οὕτω δὲ τοῦ ἐρᾶν ἐγκεκριμένου παρ’ αὐτοῖς, ὥστε καὶ τῶν παρθένων ἐρᾶν τὰς καλὰς καὶ ἀγαθὰς γυναῖκας, τὸ ἀντερᾶν οὐκ ἦν, ἀλλὰ μᾶλλον ἀρχὴν ἐποιοῦντο φιλίας πρὸς ἀλλήλους οἱ τῶν αὐτῶν ἐρασθέντες, καὶ διετέλουν κοινῇ σπουδάζοντες ὅπως ἄριστον ἀπεργάσαιντο τὸν ἐρώμενον.", "st": "Lyc. 18.4"}, {"sp": "N", "t": "ἐδίδασκον δὲ τοὺς παῖδας καὶ λόγῳ χρῆσθαι πικρίαν ἔχοντι μεμιγμένην χάριτι καὶ πολλὴν ἀπὸ βραχείας λέξεως ἀναθεώρησιν, τὸ μὲν γάρ σιδηροῦν νόμισμα μικρὰν ἔχειν ἐποίησεν ἀπὸ πολλοῦ σταθμοῦ δύναμιν ὁ Λυκοῦργος, ὡς εἴρηται, τὸ δὲ τοῦ λόγου νόμισμα τοὐναντίον ἀπ’ εὐτελοῦς καὶ ὀλίγης λέξεως εἰς πολλὴν καὶ περιττὴν κατεσκεύασε διάνοιαν, τῇ πολλῇ σιωπῇ τοὺς παῖδας ἀποφθεγματικοὺς καὶ πεπαιδευμένους πρὸς τὰς ἀποκρίσεις μηχανώμενος, ὡς γάρ τὸ σπέρμα τῶν πρὸς τὰς συνουσίας ἀκολάστων ἄγονον ὡς τὰ πολλὰ καὶ ἄκαρπόν ἐστιν, οὕτως ἡ πρὸς τὸ λαλεῖν ἀκρασία κενὸν τὸν λόγον ποιεῖ καὶ ἀνόητον. Ἆγις μὲν οὖν ὁ βασιλεύς, σκώπτοντος Ἀττικοῦ τινος τὰς Λακωνικὰς μαχαίρας εἰς τὴν μικρότητα, καὶ λέγοντος ὅτι ῥᾳδίως αὐτὰς οἱ θαυματοποιοὶ καταπίνουσιν ἐν τοῖς θεάτροις, καὶ μὴν μάλιστα, εἶπεν, ἡμεῖς ἐφικνούμεθα τοῖς ἐγχειριδίοις τῶν πολεμίων· ἐγὼ δὲ καὶ τὸν λόγον ὁρῶ τὸν Λακωνικὸν βραχὺν μὲν εἶναι δοκοῦντα, μάλιστα δὲ τῶν πραγμάτων ἐφικνούμενον, καὶ τῆς διανοίας ἁπτόμενον τῶν ἀκροωμένων,", "st": "Lyc. 19.1"}, {"sp": "N", "t": "καὶ γὰρ ὁ Λυκοῦργος αὐτὸς βραχυλόγος τις ἔοικε γενέσθαι καὶ ἀποφθεγματικός, εἰ δεῖ τεκμαίρεσθαι τοῖς ἀπομνημονεύμασιν οἷόν ἐστι τὸ περὶ τὰς πολιτείας πρὸς τὸν ἀξιοῦντα ποιεῖν δημοκρατίαν ἐν τῇ πόλει· σὺ γάρ, ἔφη, πρῶτος ἐν τῇ οἰκίᾳ σου ποίησον δημοκρατίαν καὶ περὶ τῶν θυσιῶν πρὸς τὸν πυθόμενον διὰ τί μικρὰς οὕτω καὶ εὐτελεῖς ἔταξεν, ἵνα μή ποτε, ἔφη, τιμῶντες τὸ θεῖον διαλίπωμεν. καὶ περὶ τῶν ἀθλημάτων, ταῦτα μόνα μὴ κωλύσαντος ἀγωνίζεσθαι τοὺς πολίτας ἐν οἷς χεὶρ οὐκ ἀνατείνεται. φέρονται δὲ αὐτοῦ καὶ δι’ ἐπιστολῶν ἀποκρίσεις τοιαῦται πρὸς τοὺς πολίτας. πῶς ἂν πολεμίων ἔφοδον ἀλεξοίμεθα; ἂν πτωχοὶ μένητε καὶ μὴ μέσδων ἅτερος θατέρω ἐρᾶτε ἦμεν. καὶ πάλιν περὶ τῶν τειχῶν οὐκ ἂν εἴη ἀτείχιστος πόλις ἅτις ἄνδρεσσι, καὶ οὐ πλίνθοις ἐστεφάνωται. περὶ μὲν οὖν τούτων καὶ τῶν τοιούτων ἐπιστολῶν οὔτε ἀπιστῆσαι ῥᾴδιον οὔτε πιστεῦσαι.", "st": "Lyc. 19.3"}, {"sp": "N", "t": "τῆς δὲ πρὸς τὰ μήκη τῶν λόγων διαβολῆς δείγματα τοιαῦτα τῶν ἀποφθεγμάτων ἐστί. Λεωνίδας ὁ βασιλεὺς ἀκαίρως τινὸς περὶ πραγμάτων οὐκ ἀχρήστων διαλεχθέντος, ὦ ξένε, εἶπεν, οὐκ ἐν δέοντι χρέῃ τῷ δέοντι. Χαρίλαος δὲ ὁ ἀδελφιδοῦς τοῦ Λυκούργου περὶ τῆς ὀλιγότητος αὑτοῦ τῶν νόμων ἐρωτηθείς, εἶπεν ὡς οἱ λόγοις μὴ χρώμενοι πολλοῖς οὐδὲ νόμων δέονται πολλῶν. Ἀρχιδαμίδας δὲ μεμφομένων τινῶν Ἑκαταῖον τὸν σοφιστὴν ὅτι παραληφθεὶς εἰς τὸ συσσίτιον οὐδὲν ἔλεγεν, ὁ εἰδώς, ἔφη, λόγον καὶ καιρὸν οἶδεν. ἃ δὲ τῶν πικρῶν ἔφην ἀπομνημονευμάτων οὐκ ἀμοιρεῖν χάριτος, τοιαῦτ’ ἐστί. Δημάρατος ἀνθρώπου πονηροῦ κόπτοντος αὐτὸν ἀκαίροις ἐρωτήμασι καὶ δὴ τοῦτο πολλάκις ἐρωτῶντος, τίς ἄριστος Σπαρτιατῶν; ἔφη· ὁ τὶν ἀνομοιότατος Ἆγις δέ, ἐπαινούντων τινῶν τοὺς Ἠλείους ὡς καλῶς τὰ Ὀλύμπια καὶ δικαίως ἄγοντας, καὶ τί μέγα, ἔφη, Ἠλεῖοι ποιοῦντι δι’ ἐτῶν πέντε ἁμέρᾳ μιᾷ χρώμενοι τᾷ δικαιοσύνᾳ; Θεόπομπος δὲ ξένου τινὸς εὔνοιαν ἐνδεικνυμένου, καὶ φάσκοντος ὡς παρὰ τοῖς αὑτοῦ πολίταις φιλολάκων καλεῖται, κάλλιον ἦν τοι, εἶπεν, ὦ ξένε, φιλοπολίταν καλεῖσθαι. Πλειστῶναξ δὲ ὁ Παυσανίου, ῥήτορος Ἀθηναίου τοὺς Λακεδαιμονίους ἀμαθεῖς ἀποκαλοῦντος, ὀρθῶς, ἔφη, λέγεις· μόνοι γάρ Ἑλλάνων ἄμμες οὐδὲν κακὸν μεμαθήκαμεν παρ’ ὑμῶν Ἀρχιδαμίδας δὲ πρὸς τὸν πυθόμενον πόσοι εἰσὶ Σπαρτιᾶται, ἱκανοί, εἶπεν, ὦ ξένε, τοὺς κακοὺς ἀπερύκειν.", "st": "Lyc. 20.1"}, {"sp": "N", "t": "ἔστι δὲ καὶ τοῖς μετὰ παιδιᾶς εἰρημένοις ὑπ’ αὐτῶν τεκμήρασθαι τὸν ἐθισμόν, εἰθίζοντο γάρ μηδέποτε χρῆσθαι τῷ λόγῳ παρέργως, μηδὲ ἀφιέναι φωνὴν ἥτις οὐκ ἁμῶς γέ πως εἶχέ τινος θεωρίας ἀξίαν διάνοιαν. ὁ μὲν γάρ ἀκοῦσαι τοῦ μιμουμένου τὴν ἀηδόνα παρακαλούμενος, αὐτᾶς, ἔφη, ἄκουκα τήνας. ὁ δὲ ἀναγνοὺς τὸ ἐπίγραμμα τοῦτο·", "st": "Lyc. 20.5"}, {"sp": "N", "t": "σβεννύντας ποτὲ τούσδε τυραννίδα χάλκεος Ἄρης<br>εἷλε· Σελινοῦντος δ’ ἀμφὶ πύλας ἔθανον,", "st": "Lyc. 20.5b"}, {"sp": "N", "t": "δικαίως, εἶπε, τεθνάκαντι τοὶ ἄνδρες· ἔδει γὰρ ἀφέμεν ὅλαν αὐτὰν κατακαᾶμεν. νεανίσκος δὲ πρὸς τὸν ἐπαγγελλόμενον αὐτῷ δώσειν ἀλεκτρυόνας ἀποθνήσκοντας ἐν τῷ μάχεσθαι, μὴ σὺ γε, εἶπεν, ἀλλὰ δός μοι τῶν ἀποκτεινόντων ἐν τῷ μάχεσθαι. ἕτερος δέ τις ἰδὼν ἐν ἀποχωρήσει θακεύοντας ἐπὶ δίφρων ἀνθρώπους, μὴ γένοιτο, εἶπεν, ἐνταῦθα καθίσαι ὅθεν οὐκ ἔστιν ὑπεξαναστῆναι πρεσβυτέρῳ. τὸ μὲν οὖν τῶν ἀποφθεγμάτων εἶδος ἦν τοιοῦτον ὥστε καὶ λέγειν τινὰς οὐκ ἀτόπως ὅτι μᾶλλόν ἐστι τὸ φιλοσοφεῖν ἢ τὸ φιλογυμναστεῖν λακωνίζειν.", "st": "Lyc. 20.6"}, {"sp": "N", "t": "ἡ δὲ περὶ τὰς ᾠδὰς καὶ τὰ μέλη παίδευσις οὐχ ἧττον ἐσπουδάζετο τῆς ἐν τοῖς λόγοις εὐζηλίας καὶ καθαριότητος, ἀλλὰ καὶ τὰ μέλη κέντρον εἶχεν ἐγερτικὸν θυμοῦ καὶ παραστατικὸν ὁρμῆς ἐνθουσιώδους καὶ πραγματικῆς, καὶ ἡ λέξις ἦν ἀφελὴς καὶ ἄθρυπτος ἐπὶ πράγμασι σεμνοῖς καὶ ἠθοποιοῖς. ἔπαινοι γάρ ἦσαν ὡς τὰ πολλὰ τῶν τεθνηκότων ὑπὲρ τῆς Σπάρτης εὐδαιμονιζομένων, καὶ ψόγοι τῶν τρεσάντων, ὡς ἀλγεινὸν καὶ κακοδαίμονα βιούντων βίον, ἐπαγγελία τε καὶ μεγαλαυχία πρὸς ἀρετὴν πρέπουσα ταῖς ἡλικίαις· ὧν ἕνεκα δείγματος οὐ χεῖρόν ἐστιν ἕν τι προενέγκασθαι. τριῶν γάρ χορῶν κατὰ τὰς τρεῖς ἡλικίας συνισταμένων ἐν ταῖς ἑορταῖς, ὁ μὲν τῶν γερόντων ἀρχόμενος ᾖδεν", "st": "Lyc. 21.1"}, {"sp": "N", "t": "ἄμμες πόκ’ ἦμες ἄλκιμοι νεανίαι.", "st": "Lyc. 21.1b"}, {"sp": "N", "t": "ὁ δὲ τῶν ἀκμαζόντων ἀμειβόμενος ἔλεγεν<br>ἄμμες δὲ γ’ εἰμὲν αἰ δὲ λῇς, αὐγάσδεο.", "st": "Lyc. 21.1c"}, {"sp": "N", "t": "ὁ δὲ τρίτος ὁ τῶν παίδων<br>ἄμμες δὲ γ’ ἐσσόμεσθα πολλῷ κάρρονες.", "st": "Lyc. 21.1d"}, {"sp": "N", "t": "ὅλως δὲ ἄν τις ἐπιστήσας τοῖς Λακωνικοῖς ποιήμασιν, ὧν ἔτι καθ’ ἡμᾶς ἔνια διεσώζετο, καὶ τοὺς ἐμβατηρίους ῥυθμοὺς ἀναλαβών, οἷς ἐχρῶντο πρὸς τὸν αὐλὸν ἐπάγοντες τοῖς πολεμίοις, οὐ κακῶς ἡγήσαιτο καὶ τὸν Τέρπανδρον καὶ τὸν Πίνδαρον τὴν ἀνδρείαν τῇ μουσικῇ συνάπτειν. ὁ μὲν γὰρ οὕτως πεποίηκε περὶ τῶν Λακεδαιμονίων", "st": "Lyc. 21.3"}, {"sp": "N", "t": "ἔνθ’ αἰχμά τε νέων θάλλει καὶ μοῦσα λίγεια<br>καὶ δίκα εὐρυάγυια", "st": "Lyc. 21.3b"}, {"sp": "N", "t": "Πίνδαρος δέ φησιν<br>ἔνθα βουλαὶ γερόντων<br>καὶ νέων ἀνδρῶν ἀριστεύοντι αἰχμαὶ<br>καὶ χοροὶ καὶ Μοῦσα καὶ ἀγλαΐα.", "st": "Lyc. 21.4"}, {"sp": "N", "t": "Μουσικωτάτους γὰρ ἅμα καὶ πολεμικωτάτους ἀποφαίνουσιν αὐτούς·", "st": "Lyc. 21.4b"}, {"sp": "N", "t": "ῥέπει γὰρ ἄντα τῶ σιδάρω τὸ καλῶς κιθαρίσδεν,", "st": "Lyc. 21.4c"}, {"sp": "N", "t": "ὡς ὁ Λακωνικὸς ποιητὴς εἴρηκε. καὶ γὰρ ἐν ταῖς μάχαις προεθύετο ταῖς Μούσαις ὁ βασιλεύς, ἀναμιμνήσκων, ὡς ἔοικε, τῆς παιδείας καὶ τῶν κρίσεων, ἵνα ὦσι πρόχειροι παρὰ τὰ δεινὰ καὶ λόγου τινὸς ἀξίας παρέχωσι τὰς πράξεις τῶν μαχομένων.", "st": "Lyc. 21.4d"}, {"sp": "N", "t": "τότε δὲ καὶ τοῖς νέοις τὰ σκληρότατα τῆς ἀγωγῆς ἐπανιέντες, οὐκ ἐκώλυον καλλωπίζεσθαι περὶ κόμην καὶ κόσμον ὅπλων καὶ ἱματίων, χαίροντες, ὥσπερ ἵπποις, γαυριῶσι καὶ φρυαττομένοις πρὸς τοὺς ἀγῶνας, διὸ κομῶντες εὐθὺς ἐκ τῆς τῶν ἐφήβων ἡλικίας, μάλιστα περὶ τοὺς κινδύνους ἐθεράπευον τὴν κόμην λιπαράν τε φαίνεσθαι καὶ διακεκριμένην, ἀπομνημονεύοντές τινα καὶ Λυκούργου λόγον περὶ τῆς κόμης, ὅτι τοὺς μὲν καλοὺς εὐπρεπεστέρους ποιεῖ, τοὺς δὲ αἰσχροὺς φοβερωτέρους. ἐχρῶντο δὲ καὶ γυμνασίοις μαλακωτέροις παρὰ τὰς στρατείας, καὶ τὴν ἄλλην δίαιταν οὐχ οὕτω κεκολασμένην οὐδ’ ὑπεύθυνον τοῖς νέοις παρεῖχον, ὥστε μόνοις ἀνθρώπων ἐκείνοις τῆς εἰς τὸν πόλεμον ἀσκήσεως ἀνάπαυσιν εἶναι τὸν πόλεμον. ἤδη δὲ συντεταγμένης τῆς φάλαγγος αὐτῶν καὶ τῶν πολεμίων παρόντων, ὁ βασιλεὺς ἅμα τήν τε χίμαιραν ἐσφαγιάζετο καὶ στεφανοῦσθαι παρήγγελλε πᾶσι καὶ τοὺς αὐλητὰς αὐλεῖν ἐκέλευε τὸ Καστόρειον μέλος· ἅμα δ’ ἐξῆρχεν ἐμβατηρίου παιᾶνος, ὥστε σεμνὴν ἅμα καὶ καταπληκτικὴν τὴν ὄψιν εἶναι, ῥυθμῷ τε πρὸς τὸν αὐλὸν ἐμβαινόντων καὶ μήτε διάσπασμα ποιούντων ἐν τῇ φάλαγγι μήτε ταῖς ψυχαῖς θορυβουμένων, ἀλλὰ πρᾴως καὶ ἱλαρῶς ὑπὸ τοῦ μέλους ἀγομένων ἐπὶ τὸν κίνδυνον. οὔτε γάρ φόβον οὔτε θυμὸν ἐγγίνεσθαι πλεονάζοντα τοῖς οὕτω διακειμένοις εἰκός ἐστιν, ἀλλ’ εὐσταθὲς φρόνημα μετ’ ἐλπίδος καὶ θράσους, ὡς τοῦ θεοῦ συμπαρόντος.", "st": "Lyc. 22.1"}, {"sp": "N", "t": "ἐχώρει δὲ ὁ βασιλεὺς ἐπὶ τοὺς πολεμίους ἔχων μεθ’ ἑαυτοῦ στεφανίτην ἀγῶνα νενικηκότα. καὶ φασὶ γέ τινα χρημάτων πολλῶν ἐν Ὀλυμπίοις διδομένων αὐτῷ μὴ δεξάμενον, ἀλλὰ πολλῷ πόνῳ καταπαλαίσαντα τὸν ἀνταγωνιστήν, ὥς τις εἶπεν αὐτῷ, τί σοι πλέον, ὦ Λάκων, γέγονε διὰ τῆς νίκης; φάναι μειδιάσαντα, πρὸ τοῦ βασιλέως τεταγμένος μαχοῦμαι τοῖς πολεμίοις. τρεψάμενοι δὲ καὶ νικήσαντες ἐδίωκον ὅσον ἐκβεβαιώσασθαι τὸ νίκημα τῇ φυγῇ τῶν πολεμίων, εἶτα εὐθὺς ἀνεχώρουν, οὔτε γενναῖον οὔτε Ἑλληνικὸν ἡγούμενοι κόπτειν καὶ φονεύειν ἀπολεγομένους καὶ παρακεχωρηκότας. ἦν δὲ οὐ μόνον καλὸν τοῦτο καὶ μεγαλόψυχον, ἀλλὰ καὶ χρήσιμον. εἰδότες γὰρ οἱ μαχόμενοι πρὸς αὐτοὺς ὅτι τοὺς ὑφισταμένους ἀναιροῦσι, φείδονται δὲ τῶν ἐνδιδόντων, τοῦ μένειν τὸ φεύγειν ἡγοῦντο λυσιτελέστερον.", "st": "Lyc. 22.4"}, {"sp": "N", "t": "αὐτὸν δὲ τὸν Λυκοῦργον Ἱππίας μὲν ο σοφιστὴς πολεμικώτατόν φησι γενέσθαι καὶ πολλῶν ἔμπειρον στρατειῶν, Φιλοστέφανος δὲ καὶ τὴν κατ’ οὐλαμοὺς τῶν ἱππέων διανομὴν Λυκούργῳ προστίθησιν εἶναι δὲ τὸν οὐλαμόν, ὡς ἐκεῖνος συνέστησεν, ἱππέων πεντήκοντα πλῆθος ἐν τετραγώνῳ σχήματι τεταγμένων, ὁ δὲ Φαληρεὺς Δημήτριος, οὐδεμιᾶς ἁψάμενον πολεμικῆς πράξεως ἐν εἰρήνῃ καταστήσασθαι τὴν πολιτείαν. ἔοικε δὲ καὶ τῆς Ὀλυμπιακῆς ἐκεχειρίας ἡ ἐπίνοια πρᾴου καὶ πρὸς εἰρήνην οἰκείως ἔχοντος ἀνδρὸς εἶναι, καίτοι φασί τινες, ὡς Ἕρμιππος μνημονεύει, τὸν Λυκοῦργον οὐ προσέχειν οὐδὲ κοινωνεῖν ἐν ἀρχῇ τοῖς περὶ τὸν Ἴφιτον, ἀλλὰ τυγχάνειν ἄλλως ἐπιδημοῦντα καὶ θεώμενον ἀκοῦσαι δὲ φωνὴν ὥσπερ ἀνθρώπου τινὸς ἐξόπισθεν ἐπιτιμῶντος αὐτῷ καὶ θαυμάζοντος ὅτι τοὺς πολίτας οὐ προτρέπεται κοινωνεῖν τῆς πανηγύρεως· ὡς δὲ μεταστραφέντος οὐδαμοῦ φανερὸς ὁ φθεγξάμενος ἦν, θεῖον ἡγησάμενον, οὕτω πρὸς τὸν Ἴφιτον τραπέσθαι καὶ συνδιακοσμήσαντα τὴν ἑορτὴν ἐνδοξοτέραν καὶ βεβαιοτέραν καταστῆσαι.", "st": "Lyc. 23.1"}, {"sp": "N", "t": "ἡ δὲ παιδεία μέχρι τῶν ἐνηλίκων διέτεινεν. οὐδεὶς γὰρ ἦν ἀφειμένος ὡς ἐβούλετο ζῆν, ἀλλ’ οἷον ἐν στρατοπέδῳ τῇ πόλει καὶ δίαιταν ἔχοντες ὡρισμένην καὶ διατριβὴν περὶ τὰ κοινά, καὶ ὅλως νομίζοντες οὐχ αὑτῶν, ἀλλὰ τῆς πατρίδος εἶναι διετέλουν, εἰ μή τι πράττειν ἕτερον εἴη προστεταγμένον, ἐπισκοποῦντες τοὺς παῖδας, καὶ διδάσκοντές τι τῶν χρησίμων ἢ μανθάνοντες αὐτοὶ παρὰ τῶν πρεσβυτέρων. καὶ γὰρ ἕν τι τοῦτο τῶν καλῶν ἦν καὶ μακαρίων ἃ παρεσκεύασε τοῖς ἑαυτοῦ πολίταις ὁ Λυκοῦργος, ἀφθονία σχολῆς, οἷς τέχνης μὲν ἅψασθαι βαναύσου τὸ παράπαν οὐκ ἐφεῖτο, χρηματισμοῦ δὲ συναγωγὴν ἔχοντος ἐργώδη καὶ πραγματείαν οὐδ’ ὁτιοῦν ἔδει, διὰ τὸ κομιδῇ τὸν πλοῦτον ἄζηλον γεγονέναι καὶ ἄτιμον. οἱ δὲ εἵλωτες αὐτοῖς εἰργάζοντο τὴν γῆν, ἀποφορὰν τὴν εἰρημένην τελοῦντες, ἐπιδημῶν δὲ τίς Ἀθήνησι δικαστηρίων ὄντων, καὶ πυθόμενός τινα δίκην ἀργίας ὠφληκότα βαδίζειν ἀθυμοῦντα καὶ προπεμπόμενον ὑπὸ τῶν φίλων συναχθομένων καὶ βαρέως φερόντων, ἐδεῖτο δεῖξαι τοὺς συμπαρόντας αὐτῷ τίς ἐστιν ὁ τὴν ἐλευθερίας ἑαλωκὼς δίκην. οὕτω δουλοπρεπὲς ἡγοῦντο τὴν περὶ τὰς τέχνας καὶ τὸν χρηματισμὸν ἀσχολίαν. δίκαι δέ, ὡς εἰκός, ἐξέλιπον ἅμα τῷ νομίσματι, μήτε πλεονεξίας μήτε ἀπορίας αὐτοῖς παρούσης, ἰσότητος δὲ ἐν εὐπορίᾳ καὶ ῥᾳστώνης δι’ εὐτέλειαν γεγενημένης. χοροὶ δὲ καὶ θαλίαι καὶ εὐωχίαι καὶ διατριβαὶ περί τε θήρας καὶ γυμνάσια καὶ λέσχας τὸν ἅπαντα χρόνον ἐπεχωρίαζον, ὅτε μὴ στρατευόμενοι τύχοιεν.", "st": "Lyc. 24.1"}, {"sp": "N", "t": "οἱ μέν γε νεώτεροι τριάκοντα ἐτῶν τὸ παράπαν οὐ κατέβαινον εἰς ἀγοράν, ἀλλὰ διὰ τῶν συγγενῶν καὶ τῶν ἐραστῶν ἐποιοῦντο τᾶς ἀναγκαίας οἰκονομίας. τοῖς δὲ πρεσβυτέροις αἰσχρὸν ἦν συνεχῶς ὁρᾶσθαι περὶ ταῦτα διατρίβουσιν, ἀλλὰ μὴ τὸ πλεῖστον τῆς ἡμέρας περὶ τὰ γυμνάσια καὶ τᾶς καλουμένας λέσχας ἀναστρέφεσθαι. καὶ γάρ εἰς ταύτας συνιόντες ἐπιεικῶς ἐσχόλαζον μετ’ ἀλλήλων, οὐδενὸς μεμνημένοι τῶν πρὸς χρηματισμὸν ἢ χρείαν ἀγοραῖον συντελούντων· ἀλλὰ τὸ πλεῖστον ἦν τῆς τοιαύτης διατριβῆς ἔργον ἐπαινεῖν τι τῶν καλῶν, ἢ τῶν αἰσχρῶν ψέγειν, μετὰ παιδιᾶς καὶ γέλωτος, ἐλαφρῶς ὑποφέροντος εἰς νουθεσίαν καὶ διόρθωσιν. οὐδὲ γὰρ αὐτὸς ἦν ἀκράτως αὐστηρὸς ὁ Λυκοῦργος· ἀλλὰ καὶ τὸ τοῦ Γέλωτος ἀγαλμάτιον ἐκεῖνον ἱδρύσασθαι Σωσίβιος ἱστορεῖ, τὴν παιδιὰν ὥσπερ ἥδυσμα τοῦ πόνου καὶ τῆς διαίτης ἐμβαλόντα κατὰ καιρὸν εἰς τὰ συμπόσια καὶ τᾶς τοιαύτας διατριβάς.", "st": "Lyc. 25.1"}, {"sp": "N", "t": "τὸ δὲ ὅλον εἴθιζε τοὺς πολίτας μὴ βούλεσθαι μηδὲ ἐπίστασθαι κατ’ ἰδίαν ζῆν, ἀλλ’ ὥσπερ τᾶς μελίττας τῷ κοινῷ συμφυεῖς ὄντας ἀεὶ καὶ μετ’ ἀλλήλων εἱλουμένους περὶ τὸν ἄρχοντα, μικροῦ δεῖν ἐξεστῶτας ἑαυτῶν ὑπ’ ἐνθουσιασμοῦ καὶ φιλοτιμίας, ὅλους εἶναι τῆς πατρίδος· ὡς ἔστι καὶ φωναῖς τισιν αὐτῶν ἀποθεωρῆσαι τὴν διάνοιαν. ὁ μέν γὰρ Παιδάρητος οὐκ ἐγκριθεὶς εἰς τοὺς τριακοσίους ἀπῄει μάλα φαιδρός, ὥσπερ χαίρων ὅτι βελτίονας αὐτοῦ τριακοσίους ἡ πόλις ἔχει· Πολυκρατίδας δὲ ὁ πρεσβεύων πρὸς τοὺς βασιλέως στρατηγοὺς μεθ’ ἑτέρων, ἐρομένων αὐτῶν πότερον ἰδίᾳ πάρεισιν ἢ δημοσίᾳ πεμφθέντες, εἶπεν, αἴκα τύχω μέν, δημοσίᾳ, Αἴκα ἀποτύχωμεν, ἰδίᾳ. ἡ δὲ Βρασίδου μήτηρ Ἀργιλεωνίς, ὡς ἀφικόμενοί τινες εἰς Λακεδαίμονα τῶν ἐξ Ἀμφιπόλεως εἰσῆθλον πρὸς αὐτήν, ἠρώτησεν εἰ καλῶς ὁ Βρασίδας ἀπέθανε καὶ τᾶς Σπάρτας ἀξίως· μεγαλυνόντων δὲ ἐκείνων τὸν ἄνδρα καὶ λεγόντων ὡς οὐκ ἔχει τοιοῦτον ἄλλον ἡ Σπάρτη· μὴ λέγετε, εἶπεν, ὦ ξένοι· καλὸς μέν γάρ ἦν καὶ ἀγαθὸς ὁ Βρασίδας, πολλοὺς δὲ ἄνδρας Λακεδαίμων ἔχει τήνου κάρρονας.", "st": "Lyc. 25.3"}, {"sp": "N", "t": "τοὺς δὲ γέροντας αὐτὸς μέν, ὡς εἴρηται, κατέστησε τὸ πρῶτον ἐκ τῶν μετασχόντων τοῦ βουλεύματος· ὕστερον δὲ ἀντὶ τοῦ τελευτῶντος ἔταξε καθιστάναι τὸν ἄριστον ἀρετῇ κριθέντα τῶν ὑπὲρ ἑξήκοντα ἔτη γεγονότων, καὶ μέγιστος ἐδόκει τῶν ἐν ἀνθρώποις ἀγώνων οὗτος εἶναι καὶ περιμαχητότατος· οὐ γὰρ ἐν ταχέσι τάχιστον οὐδ’ ἐν ἰσχυροῖς ἰσχυρότατον, ἀλλ’ ἐν ἀγαθοῖς καὶ σώφροσιν ἄριστον καὶ σωφρονέστατον ἔδει κριθέντα νικητήριον ἔχειν τῆς ἀρετῆς διὰ βίου τὸ σύμπαν, ὡς εἰπεῖν, κράτος ἐν τῇ πολιτείᾳ, κύριον ὄντα καὶ θανάτου καὶ ἀτιμίας καὶ ὅλως τῶν μεγίστων, ἐγίνετο δὲ ἡ κρίσις τόνδε τὸν τρόπον. ἐκκλησίας ἀθροισθείσης ἄνδρες αἱρετοὶ καθείργνυντο πλησίον εἰς οἴκημα, τὴν μὲν ὄψιν οὐχ ὁρῶντες οὐδὲ ὁρώμενοι, τὴν δὲ κραυγὴν μόνον ἀκούοντες ἐκκλησιαζόντων. βοῇ γάρ ὡς τἆλλα καὶ τοὺς ἁμιλλωμένους ἔκρινον, οὐχ ὁμοῦ πάντων, ἀλλ’ ἑκάστου κατὰ κλῆρον εἰσαγομένου καὶ σιωπῇ διαπορευομένου τὴν ἐκκλησίαν. ἔχοντες οὖν οἱ κατάκλειστοι γραμματεῖα, καθ’ ἕκαστον ἐπεσημαίνοντο τῆς κραυγῆς τὸ μέγεθος, οὐκ εἰδότες ὅτῳ γένοιτο, πλὴν ὅτι πρῶτος ἢ δεύτερος ἢ τρίτος ἢ ὁποστοσοῦν εἴη τῶν εἰσαγομένων. ὅτῳ δὲ πλείστη γένοιτο καὶ μεγίστη, τοῦτον ἀνηγόρευον. ὁ δὲ στεφανωσάμενος περιῄει τοὺς θεούς· εἵποντο δὲ πολλοὶ νέοι ζηλοῦντες τὸν ἄνδρα καὶ μεγαλύνοντες, πολλαί τε γυναῖκες ἐγκωμιάζουσαι δι’ ᾠδῆς τὴν ἀρετὴν καὶ τὸν βίον εὐδαιμονίζουσαι. τῶν δὲ ἐπιτηδείων ἕκαστος αὐτῷ δεῖπνον παρατιθεὶς ἔλεγεν ὅτι ἡ πόλις ταύτῃ τιμᾷ τῇ τραπέζῃ. περιελθὼν δὲ εἰς τὸ συσσίτιον ἀπῄει· καὶ τὰ μὲν ἄλλα ἐγίνετο συνήθως, δευτέρας δὲ μερίδος αὐτῷ παρατεθείσης ἐφύλαττεν ἀράμενος· καὶ μετὰ τὸ δεῖπνον ἐπὶ ταῖς θύραις τοῦ φιδιτίου τῶν οἰκείων παρουσῶν γυναικῶν, ἣν μάλιστα τυγχάνοι τιμῶν προσεκαλεῖτο, καὶ διδοὺς τὴν μοῖραν ἔλεγεν ὅτι ταύτην αὐτὸς λαβὼν ἀριστεῖον ἐκείνῃ δίδωσιν, ὥστε κἀκείνην ζηλουμένην ὑπὸ τῶν ἄλλων προπέμπεσθαι γυναικῶν.", "st": "Lyc. 26.1"}, {"sp": "N", "t": "καὶ μὴν καὶ τὰ περὶ τὰς ταφὰς ἄριστα διεκόσμησεν αὐτοῖς. πρῶτον μὲν γάρ ἀνελὼν δεισιδαιμονίαν ἅπασαν ἐν τῇ πόλει θάπτειν τοὺς νεκρούς, καὶ πλησίον ἔχειν τὰ μνήματα τῶν ἱερῶν οὐκ ἐκώλυσε, συντρόφους ποιῶν ταῖς τοιαύταις ὄψεσι καὶ συνήθεις τοὺς νέους, ὥστε μὴ ταράττεσθαι μηδ’ ὀρρωδεῖν τὸν θάνατον ὡς μιαίνοντα τοὺς ἁψαμένους νεκροῦ σώματος ἢ διὰ τάφων διελθόντας. ἔπειτα συνθάπτειν οὐδὲν εἴασεν, ἀλλὰ ἐν φοινικίδι καὶ φύλλοις ἐλαίας θέντες τὸ σῶμα περιέστελλον. ἐπιγράψαι δὲ τοὔνομα θάψαντας οὐκ ἐξῆν τοῦ νεκροῦ, πλὴν ἀνδρὸς ἐν πολέμῳ καὶ γυναικὸς τῶν ἱερῶν ἀποθανόντων, χρόνον δὲ πένθους ὀλίγον προσώρισεν, ἡμέρας ἕνδεκα· τῇ δὲ δωδεκάτῃ θύσαντας ἔδει Δήμητρι λύειν τὸ πάθος. οὐδὲν γάρ ἦν ἀργὸν οὐδὲ ἀφειμένον, ἀλλὰ πᾶσι κατεμίγνυε τοῖς ἀναγκαίοις ἀρετῆς τινα ζῆλον ἢ κακίας διαβολὴν καὶ κατεπύκνου παραδειγμάτων πλήθει τὴν πόλιν, οἷς ἀναγκαῖον ἦν ἐντυγχάνοντας ἀεὶ καὶ συντρεφομένους ἄγεσθαι καὶ κατασχηματίζεσθαι ἰόντας πρὸς τὸ καλόν.", "st": "Lyc. 27.1"}, {"sp": "N", "t": "ὅθεν οὐδ’ ἀποδημεῖν ἔδωκε τοῖς βουλομένοις καὶ πλανᾶσθαι, ξενικὰ συνάγοντας ἤθη καὶ μιμήματα βίων ἀπαιδεύτων καὶ πολιτευμάτων διαφόρων, ἀλλὰ καὶ τοὺς ἀθροιζομένους ἐπ’ οὐδενὶ χρησίμῳ καὶ παρεισρέοντας εἰς τὴν πόλιν ἀπήλαυνεν, οὐχ, ὡς Θουκυδίδης φησί, δεδιὼς μὴ τῆς πολιτείας μιμηταὶ γένωνται καὶ πρὸς ἀρετήν τι χρήσιμον ἐκμάθωσιν, ἀλλὰ μᾶλλον ὅπως μὴ διδάσκαλοι κακοῦ τινος ὑπάρξωσιν. ἅμα γάρ ξένοις σώμασιν ἀνάγκη λόγους ἐπεισιέναι ξένους· λόγοι δὲ καινοὶ κρίσεις καινὰς ἐπιφέρουσιν. ἐξ ὧν ἀνάγκη πάθη πολλὰ φύεσθαι καὶ προαιρέσεις ἀπᾳδούσας πρὸς τὴν καθεστῶσαν πολιτείαν, ὥσπερ ἁρμονίαν. διὸ μᾶλλον ᾤετο χρῆναι φυλάττειν τὴν πόλιν ὅπως ἠθῶν οὐκ ἀναπλησθήσεται πονηρῶν ἢ σωμάτων νοσερῶν ἔξωθεν ἐπεισιόντων.", "st": "Lyc. 27.3"}, {"sp": "N", "t": "ἐν μὲν οὖν τούτοις οὐδέν ἐστιν ἀδικίας ἴχνος οὐδὲ πλεονεξίας, ἣν ἐγκαλοῦσιν ἔνιοι τοῖς Λυκούργου νόμοις, ὡς ἱκανῶς ἔχουσι πρὸς ἀνδρείαν, ἐνδεῶς δὲ πρὸς δικαιοσύνην. ἡ δὲ καλουμένη κρυπτεία παρ’ αὐτοῖς, εἴ γε δὴ τοῦτο τῶν Λυκούργου πολιτευμάτων ἕν ἐστιν, ὡς Ἀριστοτέλης ἱστόρηκε, ταύτην ἂν εἴη καὶ τῷ Πλάτωνι περὶ τῆς πολιτείας καὶ τοῦ ἀνδρὸς ἐνειργασμένη δόξαν. ἦν δὲ τοιαύτη· τῶν νέων οἱ ἄρχοντες διὰ χρόνου τοὺς μάλιστά νοῦν ἔχειν δοκοῦντας εἰς τὴν χώραν ἄλλως ἐξέπεμπον, ἔχοντας ἐγχειρίδια καὶ τροφὴν ἀναγκαίαν, ἄλλο δὲ οὐδέν· οἱ δὲ μεθ’ ἡμέραν μὲν εἰς ἀσυνδήλους διασπειρόμενοι τόπους, ἀπέκρυπτον ἑαυτοὺς καὶ ἀνεπαύοντο, νύκτωρ δὲ κατιόντες εἰς τὰς ὁδοὺς τῶν εἱλώτων τὸν ἁλισκόμενον ἀπέσφαττον. πολλάκις δὲ καὶ τοῖς ἀγροῖς ἐπιπορευόμενοι τοὺς ῥωμαλεωτάτους καὶ κρατίστους αὐτῶν ἀνῄρουν. ὥσπερ καὶ Θουκυδίδης ἐν τοῖς Πελοποννησιακοῖς ἱστορεῖ τοὺς ἐπ’ ἀνδρείᾳ προκριθέντας ὑπὸ τῶν Σπαρτιατῶν στεφανώσασθαι μὲν ὡς ἐλευθέρους γεγονότας καὶ περιελθεῖν τὰ τῶν θεῶν ἱερά, μικρὸν δὲ ὕστερον ἅπαντας ἀφανεῖς γενέσθαι, πλείονας ἢ δισχιλίους ὄντας, ὡς μήτε παραχρῆμα μήτε ὕστερον ἔχειν τινὰ λέγειν ὅτῳ τρόπῳ διεφθάρησαν. Ἀριστοτέλης δὲ μάλιστά φησι καὶ τοὺς ἐφόρους, ὅταν εἰς τὴν ἀρχὴν καταστῶσι πρῶτον, τοῖς εἵλωσι καταγγέλλειν πόλεμον, ὅπως εὐαγὲς ᾖ τὸ ἀνελεῖν.", "st": "Lyc. 28.1"}, {"sp": "N", "t": "καὶ τἆλλα δὲ τραχέως προσεφέροντο καὶ σκληρῶς αὐτοῖς, ὥστε καὶ πίνειν ἀναγκάζοντες πολὺν ἄκρατον εἰς τὰ συσσίτια παρεισῆγον, ἐπιδεικνύμενοι τὸ μεθύειν οἷόν ἐστι τοῖς νέοις. καὶ ᾠδὰς ἐκέλευον ᾄδειν καὶ χορείας χορεύειν ἀγεννεῖς καὶ καταγελάστους, ἀπέχεσθαι δὲ τῶν ἐλευθέρων. διὸ καί φασιν ὕστερον ἐν τῇ Θηβαίων εἰς τὴν Λακωνικὴν στρατείᾳ τοὺς ἁλισκομένους εἵλωτας κελευομένους ᾄδειν τὰ Τερπάνδρου καὶ Ἀλκμᾶνος καὶ Σπένδοντος τοῦ Λάκωνος παραιτεῖσθαι, φάσκοντας οὐκ ἐθέλειν τοὺς δεσποσύνους. ὥστε τοὺς λέγοντας, ἐν Λακεδαίμονι καὶ τὸν ἐλεύθερον μάλιστά ἐλεύθερον εἶναι καὶ τὸν δοῦλον μάλιστά δοῦλον, οὐ φαύλως τεθεωρηκέναι τὴν διαφοράν. τὰς μὲν οὖν τοιαύτας χαλεπότητας ὕστερον ἐγγενέσθαι τοῖς Σπαρτιάταις νομίζω, μάλιστά μετὰ τὸν μέγαν σεισμόν, ᾧ συνεπιθέσθαι τοὺς εἵλωτας μετὰ Μεσσηνίων ἱστοροῦσι, καὶ πλεῖστα κακὰ τὴν χώραν ἐργάσασθαι καὶ μέγιστον τῇ πόλει περιστῆσαι κίνδυνον. οὐ γὰρ ἂν ἔγωγε προσθείην Λυκούργῳ μιαρὸν οὕτω τῆς κρυπτείας ἔργον ἀπὸ τῆς ἄλλης αὐτοῦ πρᾳότητος καὶ δικαιοσύνης τεκμαιρόμενος τὸν τρόπον, ᾧ καὶ τὸ δαιμόνιον ἐπεμαρτύρησε.", "st": "Lyc. 28.5"}, {"sp": "N", "t": "κατειλημμένων δὲ τοῖς ἐθισμοῖς ἤδη τῶν κυριωτάτων ὑπ’ αὐτοῦ, καὶ τῆς πολιτείας ἐκτεθραμμένης ἱκανῶς καὶ δυναμένης φέρειν ἑαυτὴν καὶ σώζειν δι’ ἑαυτῆς, ὥσπερ ὁ Πλάτων φησὶν ἐπὶ τῷ κόσμῳ γενομένῳ καὶ κινηθέντι τὴν πρώτην κίνησιν εὐφρανθῆναι τὸν θεόν, οὕτως ἀγασθεὶς καὶ ἀγαπήσας τὸ τῆς νομοθεσίας κάλλος καὶ μέγεθος ἐν ἔργῳ γενομένης καὶ ὁδῷ βαδιζούσης, ἐπεθύμησεν, ὡς ἀνυστὸν ἐξ ἀνθρωπίνης προνοίας, ἀθάνατον αὐτὴν ἀπολιπεῖν καὶ ἀκίνητον εἰς τὸ μέλλον. συναγαγὼν οὖν ἅπαντας εἰς ἐκκλησίαν, τὰ μὲν ἄλλα μετρίως ἔχειν ἔφη καὶ ἱκανῶς πρὸς εὐδαιμονίαν καὶ ἀρετὴν τῆς πόλεως, ὃ δὲ κυριώτατόν ἐστι καὶ μέγιστον οὐκ ἂν ἐξενεγκεῖν πρότερον πρὸς αὐτοὺς ἢ χρήσασθαι τῷ θεῷ. δεῖν οὖν ἐκείνους ἐμμένειν τοῖς καθεστῶσι νόμοις καὶ μηδὲν ἀλλάσσειν μηδὲ μετακινεῖν ἕως ἐπάνεισιν ἐκ Δελφῶν αὐτός· ἐπανελθὼν γάρ ὅ τι ἂν τῷ θεῷ δοκῇ ποιήσειν. ὁμολογούντων δὲ πάντων καὶ κελευόντων βαδίζειν, ὅρκους λαβὼν παρὰ τῶν βασιλέων καὶ τῶν γερόντων, ἔπειτα παρὰ τῶν ἄλλων πολιτῶν, ἐμμενεῖν καὶ χρήσεσθαι τῇ καθεστώσῃ πολιτείᾳ μέχρις ἂν ἐπανέλθῃ ὁ Λυκοῦργος, ἀπῆρεν εἰς Δελφούς.", "st": "Lyc. 29.1"}, {"sp": "N", "t": "παραγενόμενος δὲ πρὸς τὸ μαντεῖον καὶ τῷ θεῷ θύσας, ἠρώτησεν εἰ καλῶς οἱ νόμοι καὶ ἱκανῶς πρὸς εὐδαιμονίαν καὶ ἀρετὴν πόλεως κείμενοι τυγχάνουσιν. ἀποκριναμένου δὲ τοῦ θεοῦ καὶ τοὺς νόμους καλῶς κεῖσθαι καὶ τὴν πόλιν ἐνδοξοτάτην διαμενεῖν τῇ Λυκούργου χρωμένην πολιτείᾳ, τὸ μάντευμα γραψάμενος εἰς Σπάρτην ἀπέστειλεν. αὐτὸς δὲ τῷ θεῷ πάλιν θύσας καὶ τοὺς φίλους ἀσπασάμενος καὶ τὸν υἱόν, ἔγνω μηκέτι τοῖς πολίταις ἀφεῖναι τὸν ὅρκον, αὐτοῦ δὲ καταλῦσαι τὸν βίον ἑκουσίως, ἡλικίας γεγονὼς ἐν ᾗ καὶ βιοῦν ἔτι καὶ πεπαῦσθαι βουλομένοις ὡραῖόν ἐστι, καὶ τῶν περὶ αὐτὸν ἱκανῶς πρὸς εὐδαιμονίαν ἔχειν δοκούντων. ἐτελεύτησεν οὖν ἀποκαρτερήσας, ἡγούμενος χρῆναι τῶν πολιτικῶν ἀνδρῶν μηδὲ τὸν θάνατον ἀπολίτευτον εἶναι μηδὲ ἀργὸν τὸ τοῦ βίου τέλος, ἀλλ’ ἐν ἀρετῆς μερίδι καὶ πράξεως γενόμενον. αὑτῷ τε γὰρ ἐξειργασμένῳ τὰ κάλλιστα τὴν τελευτὴν ὡς ἀληθῶς ἐπιτελείωσιν εἶναι τῆς εὐδαιμονίας, καὶ τοῖς πολίταις ὧν διὰ τοῦ βίου παρεσκεύασε καλῶν καὶ ἀγαθῶν φύλακα τὸν θάνατον ἀπολείψειν, ὀμωμοκόσι χρῆσθαι τῇ πολιτείᾳ μέχρις ἂν ἐκεῖνος ἐπανέλθῃ. καὶ οὐ διεψεύσθη τῶν λογισμῶν τοσοῦτον ἐπρώτευσεν ἡ πόλις τῆς Ἑλλάδος εὐνομίᾳ, καὶ δόξῃ, χρόνον ἐτῶν πεντακοσίων τοῖς Λυκούργου χρησαμένη νόμοις, οὓς δεκατεσσάρων βασιλέων μετ’ ἐκεῖνον εἰς Ἆγιν τὸν Ἀρχιδάμου γενομένων οὐδεὶς ἐκίνησεν. ἡ γάρ τῶν ἐφόρων κατάστασις οὐκ ἄνεσις ἦν, ἀλλ’ ἐπίτασις τῆς πολιτείας, καὶ δοκοῦσα πρὸς τοῦ δήμου γεγονέναι σφοδροτέραν ἐποίησε τὴν ἀριστοκρατίαν.", "st": "Lyc. 29.4"}, {"sp": "N", "t": "Ἄγιδος δὲ βασιλεύοντος εἰσερρύη νόμισμα πρῶτον εἰς τὴν Σπάρτην, καὶ μετὰ τοῦ νομίσματος πλεονεξία καὶ πλούτου ζῆλος ἐπέβη διὰ Λύσανδρον, ὃς αὐτὸς ὢν ἀνάλωτος ὑπὸ χρημάτων, ἐνέπλησε τὴν πατρίδα φιλοπλουτίας καὶ τρυφῆς, χρυσὸν καὶ ἄργυρον ἐκ τοῦ πολέμου καταγαγὼν καὶ τοὺς Λυκούργου καταπολιτευσάμενος νόμους. ὧν ἐπικρατούντων πρότερον οὐ πόλεως ἡ Σπάρτη πολιτείαν, ἀλλ’ ἀνδρὸς ἀσκητοῦ καὶ σοφοῦ βίον ἔχουσα, μᾶλλον δ’, ὥσπερ οἱ ποιηταὶ τὸν Ἡρακλέα μυθολογοῦσι δέρμα καὶ ξύλον ἔχοντα τὴν οἰκουμένην ἐπιπορεύεσθαι, κολάζοντα τοὺς παρανόμους καὶ θηριώδεις τυράννους, οὕτως ἡ πόλις ἀπὸ σκυτάλης μιᾶς καὶ τρίβωνος ἄρχουσα τῆς Ἑλλάδος ἑκούσης καὶ βουλομένης, κατέλυε τὰς ἀδίκους δυναστείας καὶ τυραννίδας ἐν τοῖς πολιτεύμασι, καὶ πολέμους ἐβράβευε καὶ στάσεις κατέπαυε, πολλάκις οὐδ’ ἀσπίδα κινήσασα μίαν, ἀλλ’ ἕνα πέμψασα πρεσβευτήν, ᾧ πάντες εὐθὺς ἐποίουν τὸ προστασσόμενον, ὥσπερ αἱ μέλισσαι φανέντος ἡγεμόνος, συντρέχοντες καὶ κατακοσμούμενοι. τοσοῦτον περιῆν εὐνομίας τῇ πόλει καὶ δικαιοσύνης.", "st": "Lyc. 30.1"}, {"sp": "N", "t": "ὅθεν ἔγωγε θαυμάζω τῶν λεγόντων ὡς ἄρχεσθαι μὲν ᾔδεσαν, ἄρχειν δὲ οὐκ ἠπίσταντο Λακεδαιμόνιοι, καὶ τὸν Θεοπόμπου τοῦ βασιλέως ἐπαινούντων λόγον, ὅς, εἰπόντος τινὸς σώζεσθαι τὴν Σπάρτην διὰ τοὺς βασιλεῖς ἀρχικοὺς γεγονότας, μᾶλλον, εἶπε, διὰ τοὺς πολίτας πειθαρχικοὺς ὄντας· οὐ γὰρ ἀκούειν ὑπομένουσι τῶν προστατεῖν μὴ δυναμένων, ἀλλ’ ἡ πειθαρχία μάθημα μέν ἐστιν τοῦ ἄρχοντος ἐμποιεῖ γάρ ὁ καλῶς ἄγων τὸ καλῶς ἕπεσθαι· καὶ καθάπερ ἱππικῆς τέχνης ἀποτέλεσμα πρᾷον ἵππον καὶ πειθήνιον παρασχεῖν, οὕτω βασιλικῆς ἐπιστήμης ἔργον ἀνθρώποις εὐπείθειαν ἐνεργάσασθαι, Λακεδαιμόνιοι δὲ οὐκ εὐπείθειαν, ἀλλ’ ἐπιθυμίαν ἐνειργάζοντο τοῖς ἄλλοις τοῦ ἄρχεσθαι καὶ ὑπακούειν αὐτοῖς. ᾔτουν γάρ οὐ ναῦς οὐδὲ χρήματα παρ’ αὐτῶν οὐδὲ ὁπλίτας πέμποντες, ἀλλὰ ἕνα Σπαρτιάτην ἡγεμόνα· καὶ λαβόντες ἐχρῶντο μετὰ τιμῆς καὶ δέους, ὥσπερ Γυλίππῳ Σικελιῶται καὶ Βρασίδᾳ Χαλκιδεῖς, Λυσάνδρῳ δὲ καὶ Καλλικρατίδᾳ καὶ Ἀγησιλάῳ πάντες οἱ τὴν Ἀσίαν οἰκοῦντες Ἕλληνες, τοὺς μὲν ἄνδρας ἁρμοστὰς καὶ σωφρονιστὰς τῶν ἑκασταχοῦ δήμων καὶ ἀρχόντων ὀνομάζοντες, πρὸς δὲ σύμπασαν τὴν τῶν Σπαρτιατῶν πόλιν ὥσπερ παιδαγωγὸν ἢ διδάσκαλον εὐσχήμονος βίου καὶ τεταγμένης πολιτείας ἀποβλέποντες. εἰς ὃ καὶ Στρατόνικος ἐπισκῶψαι δοκεῖ, μετὰ παιδιᾶς νομοθετῶν καὶ κελεύων Ἀθηναίους ἄγειν μυστήρια καὶ πομπάς, Ἠλείους δὲ ἀγωνοθετεῖν, ὡς κάλλιστα τοῦτο ποιοῦντας, Λακεδαιμονίους δέ, ἂν ἁμαρτάνωσιν οὗτοι, δέρεσθαι. καὶ τοῦτο μὲν εἴρηται χάριν τοῦ γελοίου· Ἀντισθένης δὲ ὁ Σωκρατικὸς ἀπὸ τῆς ἐν Λεύκτροις μάχης ὁρῶν τοὺς Θηβαίους μέγα φρονοῦντας, οὐδὲν αὐτοὺς ἔφη διαφέρειν παιδαρίων ἐπὶ τῷ συγκόψαι τὸν παιδαγωγὸν γαυριώντων.", "st": "Lyc. 30.3"}, {"sp": "N", "t": "οὐ μὴν τοῦτό γε τῷ Λυκούργῳ κεφάλαιον ἦν τότε, πλείστων ἡγουμένην ἀπολιπεῖν τὴν πόλιν ἀλλ’ ὥσπερ ἑνὸς ἀνδρὸς βίῳ καὶ πόλεως ὅλης νομίζων εὐδαιμονίαν ἀπ’· ἀρετῆς ἐγγίνεσθαι καὶ ὁμονοίας τῆς πρὸς αὑτήν, πρὸς τοῦτο συνέταξε καὶ συνήρμοσεν, ὅπως ἐλευθέριοι καὶ αὐτάρκεις γενόμενοι καὶ σωφρονοῦντες ἐπὶ πλεῖστον χρόνον διατελῶσι. ταύτην καὶ Πλάτων ἔλαβε τῆς πολιτείας ὑπόθεσιν καὶ Διογένης καὶ Ζήνων καὶ πάντες ὅσοι τι περὶ τούτων ἐπιχειρήσαντες εἰπεῖν ἐπαινοῦνται, γράμματα καὶ λόγους ἀπολιπόντες μόνον, ὁ δὲ οὐ γράμματα καὶ λόγους, ἀλλ’ ἔργῳ πολιτείαν ἀμίμητον εἰς φῶς προενεγκάμενος, καὶ τοῖς ἀνύπαρκτον εἶναι τὴν λεγομένην περὶ τὸν σοφὸν διάθεσιν ὑπολαμβάνουσιν ἐπιδείξας ὅλην τὴν πόλιν φιλοσοφοῦσαν, εἰκότως ὑπερῆρε τῇ δόξῃ τοὺς πώποτε πολιτευσαμένους ἐν τοῖς Ἕλλησι. δι’ ὅπερ καὶ Ἀριστοτέλης ἐλάττονας σχεῖν φησι τιμὰς ἢ προσῆκον ἦν αὐτὸν ἔχειν ἐν Λακεδαίμονι, καίπερ ἔχοντα τὰς μεγίστας. ἱερόν τε γάρ ἐστιν αὐτοῦ, καὶ θύουσι καθ’ ἕκαστον ἐνιαυτὸν ὡς θεῷ. λέγεται δὲ καὶ τῶν λειψάνων αὐτοῦ κομισθέντων οἴκαδε κεραυνὸν εἰς τὸν τάφον κατασκῆψαι· τοῦτο δὲ οὐ ῥᾳδίως ἑτέρῳ τινὶ τῶν ἐπιφανῶν πλὴν Εὐριπίδῃ συμπεσεῖν ὕστερον, τελευτήσαντι καὶ ταφέντι τῆς Μακεδονίας περὶ Ἀρέθουσαν. ὥστε ἀπολόγημα καὶ μαρτύριον μέγα εἶναι τοῖς ἀγαπῶσι τὸν Εὐριπίδην τὸ μόνῳ συμπεσεῖν αὐτῷ μετὰ τελευτὴν ἃ τῷ θεοφιλεστάτῳ καὶ ὁσιωτάτῳ πρότερον συνέπεσε.", "st": "Lyc. 31.1"}, {"sp": "N", "t": "τελευτῆσαι δὲ τὸν Λυκοῦργον οἱ μὲν ἐν Κίρρᾳ λέγουσιν, Ἀπολλόθεμις δὲ εἰς Ἦλιν κομισθέντα, Τίμαιος δὲ καὶ Ἀριστόξενος ἐν Κρήτῃ καταβιώσαντα καὶ τάφον Ἀριστόξενος αὐτοῦ δείκνυσθαί φησιν ὑπὸ Κρητῶν τῆς Περγαμίας περὶ τὴν ξενικὴν ὁδόν. υἱὸν δὲ λέγεται μονογενῆ καταλιπεῖν Ἀντίωρον οὗ τελευτήσαντος ἀτέκνου τὸ γένος ἐξέλιπεν. οἱ δ’ ἑταῖροι καὶ οἰκεῖοι διαδοχήν τινα καὶ σύνοδον ἐπὶ πολλοὺς χρόνους διαμείνασαν κατέστησαν, καὶ τὰς ἡμέρας ἐν αἷς συνήρχοντο Λυκουργίδας προσηγόρευσαν. Ἀριστοκράτης δὲ ὁ Ἱππάρχου φησὶ τοὺς ξένους τοῦ Λυκούργου τελευτήσαντος ἐν Κρήτῃ καῦσαι τὸ σῶμα καὶ διασπεῖραι τὴν τέφραν εἰς τὴν θάλατταν, αὐτοῦ δεηθέντος καὶ φυλαξαμένου μή ποτε ἄρα τῶν λειψάνων εἰς Λακεδαίμονα κομισθέντων, ὡς ἐπανήκοντος αὐτοῦ καὶ τῶν ὅρκων λελυμένων, μεταβάλωσι τὴν πολιτείαν. ταῦτα μὲν οὖν περὶ τοῦ Λυκούργου.", "st": "Lyc. 31.4"}, {"sp": "HDR", "t": "Νομᾶς"}, {"sp": "N", "t": "ἔστι δὲ καὶ περὶ τῶν Νομᾶ τοῦ βασιλέως χρόνων, καθ’ οὓς γέγονε, νεανικὴ διαφορά, καίπερ ἐξ ἀρχῆς εἰς τοῦτον κατάγεσθαι τῶν στεμμάτων ἀκριβῶς δοκούντων. ἀλλὰ Κλώδιός τις ἐν ἐλέγχῳ χρόνων οὕτω γάρ πως ἐπιγέγραπται τὸ βιβλίον ἰσχυρίζεται τὰς μὲν ἀρχαίας ἐκείνας ἀναγραφὰς ἐν τοῖς Κελτικοῖς πάθεσι τῆς πόλεως ἠφανίσθαι, τὰς δὲ νῦν φαινομένας οὐκ ἀληθῶς συγκεῖσθαι δι’ ἀνδρῶν χαριζομένων τισὶν εἰς τὰ πρῶτα γένη καὶ τοὺς ἐπιφανεστάτους οἴκους ἐξ οὐ προσηκόντων εἰσβιαζομένοις. λεγομένου δὲ οὖν ὡς Νομᾶς γένοιτο Πυθαγόρου συνήθης, οἱ μὲν ὅλως ἀξιοῦσι μηδὲν Ἑλληνικῆς παιδεύσεως Νομᾷ μετεῖναι, καθάπερ ἢ φύσει δυνατὸν καὶ αὐτάρκη γενέσθαι πρὸς ἀρετὴν ἢ βελτίονι Πυθαγόρου βαρβάρῳ τινὶ τὴν τοῦ βασιλέως ἀποδοῦναι παίδευσιν οἱ δὲ Πυθαγόραν μὲν ὀψὲ γενέσθαι, τῶν Νομᾶ χρόνων ὁμοῦ τι πέντε γενεαῖς ἀπολειπόμενον, Πυθαγόρου δὲ τὸν Σπαρτιάτην Ὀλύμπια νενικηκότα στάδιον ἐπὶ τῆς ἑκκαιδεκάτης Ὀλυμπιάδος, ἧς ἔτει τρίτῳ Νομᾶς εἰς τὴν βασιλείαν κατέστη, πλανηθέντα περὶ τὴν Ἰταλίαν συγγενέσθαι τῷ Νομᾷ καὶ συνδιακοσμῆσαι τὴν πολιτείαν, ὅθεν οὐκ ὀλίγα τοῖς Ῥωμαϊκοῖς ἐπιτηδεύμασι τῶν Λακωνικῶν ἀναμεμῖχθαι Πυθαγόρου διδάξαντος, ἄλλως δὲ Νομᾶς γένος μὲν ἦν ἐκ Σαβίνων, Σαβῖνοι δὲ βούλονται Λακεδαιμονίων ἑαυτοὺς ἀποίκους γεγονέναι. τοὺς μὲν οὖν χρόνους ἐξακριβῶσαι χαλεπόν ἐστι, καὶ μάλιστα τοὺς ἐκ τῶν Ὀλυμπιονικῶν ἀναγομένους, ὧν τὴν ἀναγραφὴν ὀψέ φασιν Ἱππίαν ἐκδοῦναι τὸν Ἠλεῖον, ἀπ’ οὐδενὸς ὁρμώμενον ἀναγκαίου πρὸς πίστιν ἃ δὲ παρειλήφαμεν ἡμεῖς ἄξια λόγου περὶ Νομᾶ, διέξιμεν ἀρχὴν οἰκείαν λαβόντες.", "st": "Num. 1.1"}, {"sp": "N", "t": "ἕβδομον ἐνιαυτὸν ἡ Ῥώμη καὶ τριακοστὸν ἤδη Ῥωμύλου βασιλεύοντος ᾠκεῖτο· πέμπτῃ δὲ ἱσταμένου μηνός, ἣν νῦν ἡμέραν νώνας Καπρατίνας καλοῦσι, θυσίαν τινὰ δημοτελῆ πρὸ τῆς πόλεως ὁ Ῥωμύλος ἔθυε περὶ τὸ καλούμενον Αἰγὸς ἕλος, καὶ παρῆν ἥ τε βουλὴ καὶ τοῦ δήμου τὸ πλεῖστον. ἐξαίφνης δὲ μεγάλης περὶ τὸν ἀέρα τροπῆς γενομένης καὶ νέφους ἐπὶ τὴν γῆν ἐρείσαντος ἅμα πνεύματι καὶ ζάλῃ, τὸν μὲν ἄλλον ὅμιλον ἐκπλαγέντα συνέβη φυγεῖν καὶ σκεδασθῆναι, τὸν δὲ Ῥωμύλον ἀφανῆ γενέσθαι, καὶ μήτε αὐτὸν ἔτι μήτε σῶμα τεθνηκότος εὑρεθῆναι, χαλεπὴν δὲ τιν’ ὑπόνοιαν ἅψασθαι τῶν πατρικίων, καὶ ῥυῆναι λόγον ἐν τῷ δήμῳ κατ’ αὑτῶν ὡς πάλαι βαρυνόμενοι τὸ βασιλεύεσθαι καὶ μεταστῆσαι τὸ κράτος εἰς αὑτοὺς θέλοντες ἀνέλοιεν τὸν βασιλέα, καὶ γάρ ἐδόκει τραχύτερον ἤδη προσφέρεσθαι καὶ μοναρχικώτερον αὐτοῖς. ἀλλὰ ταύτην μὲν τὴν ὑποψίαν ἐθεράπευον εἰς θεῶν τιμὰς ἀνάγοντες ὡς οὐ τεθνηκότα τὸν Ῥωμύλον, ἀλλὰ κρείττονος ὄντα μοίρας· καὶ Πρόκλος, ἀνὴρ ἐπιφανής, διωμόσατο Ῥωμύλον ἰδεῖν εἰς οὐρανὸν σὺν τοῖς ὅπλοις ἀναφερόμενον, καὶ φωνῆς ἀκοῦσαι κελεύοντος αὐτὸν ὀνομάζεσθαι Κυρῖνον.", "st": "Num. 2.1"}, {"sp": "N", "t": "ἑτέρα δὲ ταραχὴ καὶ στάσις κατελάμβανε τὴν πόλιν ὑπὲρ τοῦ μέλλοντος ἀποδειχθήσεσθαι βασιλέως, οὔπω τῶν ἐπηλύδων κομιδῇ τοῖς πρώτοις συγκεκραμένων πολίταις, ἀλλ’ ἔτι τοῦ τε δήμου πολλὰ κυμαίνοντος ἐν ἑαυτῷ καὶ τῶν πατρικίων ἐν ὑποψίαις ἐκ τοῦ διαφόρου πρὸς ἀλλήλους ὄντων, οὐ μὴν ἀλλὰ βασιλεύεσθαι μὲν ἐδόκει πᾶσιν, ἤρισαν δὲ καὶ διέστησαν οὐχ ὑπὲρ ἀνδρὸς μόνον, ἀλλὰ καὶ γένους, ὁπότερον παρέξει τὸν ἡγεμόνα, καὶ γάρ οἱ μετὰ Ῥωμύλου· πρῶτοι συνοικίσαντες τὴν πόλιν οὐκ ἀνασχετὸν ἐποιοῦντο πόλεως καὶ χώρας τοὺς Σαβίνους μεταλαβόντας ἄρχειν βιάζεσθαι τῶν ἐπὶ ταῦτα δεξαμένων, καὶ τοῖς Σαβίνοις ἦν τις εὐγνώμων λόγος, ἐπεὶ Τατίου τοῦ βασιλέως αὑτῶν ἀποθανόντος οὐκ ἐστασίασαν πρὸς Ῥωμύλον, ἀλλ’ εἴασαν ἄρχειν μόνον, αὖθις ἀξιούντων τὸν ἄρχοντα γενέσθαι παρ’ αὑτῶν, οὔτε γάρ ἐκ ταπεινοτέρων κρείττοσι προσγενέσθαι, καὶ προσγενόμενοι πλήθει τε ῥῶσαι καὶ προαγαγεῖν εἰς ἀξίωμα πόλεως ἐκείνους μεθ’ ἑαυτῶν, ὑπὲρ μὲν οὖν τούτων ἐστασίαζον.", "st": "Num. 2.4"}, {"sp": "N", "t": "ὅπως δὲ μὴ σύγχυσιν ἐκ τῆς ἀναρχίας ἡ στάσις ἀπεργάσεται, μετεώρου τοῦ πολιτεύματος ὄντος, ἔταξαν οἱ πατρίκιοι, πεντήκοντα καὶ ἑκατὸν ὄντων αὑτῶν, ἕκαστον ἐν μέρει τοῖς βασιλικοῖς παρασήμοις κοσμούμενον θύειν τε τοῖς θεοῖς τὰ νενομισμένα καὶ χρηματίζειν ἓξ μὲν ὥρας τῆς νυκτός, ἓξ δὲ τῆς ἡμέρας. καὶ γὰρ ἡ διανομὴ τῶν καιρῶν ἑκατέρου πρὸς ἱσότητα καλῶς ἔχειν ἐδόκει τοῖς ἄρχουσι, καὶ πρὸς τὸν δῆμον ἡ μεταβολὴ τῆς ἐξουσίας ἀφαιρεῖν τὸν φθόνον, ὁρῶντα τῆς αὐτῆς ἡμέρας καὶ νυκτὸς τὸν αὐτὸν ἰδιώτην ἐκ βασιλέως γινόμενον. τὸ δὲ σχῆμα τοῦτο τῆς ἀρχῆς μεσοβασιλείαν Ῥωμαῖοι καλοῦσιν.", "st": "Num. 2.6"}, {"sp": "N", "t": "ἀλλὰ καίπερ οὕτω πολιτικῶς καὶ ἀνεπαχθῶς ἀφηγεῖσθαι δοκοῦντες, ὑπονοίαις καὶ θορύβοις περιέπιπτον, ὡς μεθιστάντες εἰς ὀλιγαρχίαν τὰ πράγματα καὶ διαπαιδαγωγοῦντες ἐν σφίσιν αὐτοῖς τὴν πολιτείαν, βασιλεύεσθαι δὲ οὐκ ἐθέλοιεν. ἐκ τούτου συνέβησαν ἀμφότεραι πρὸς ἀλλήλας αἱ στάσεις, ὥστε τὴν ἑτέραν ἐκ τῆς ἑτέρας ἀποδεῖξαι βασιλέα· μάλιστα γάρ ἂν οὕτως ἔν τε τῷ παρόντι παύσασθαι τὴν φιλονεικίαν, καὶ τὸν ἀποδειχθέντα πρὸς ἀμφοτέρους ἴσον γενέσθαι, τοὺς μὲν ὡς ἑλομένους ἀγαπῶντα, τοῖς δὲ εὔνουν ὄντα διὰ συγγένειαν, ἐπιτρεψάντων δὲ προτέροις τοῖς Ῥωμαίοις τῶν Σαβίνων τὴν αἵρεσιν, ἔδοξε μᾶλλον ἑλέσθαι Σαβῖνον αὐτοὺς ἀποδείξαντας ἢ παρασχεῖν Ῥωμαῖον ἐκείνων ἑλομένων. καὶ βουλευσάμενοι καθ’ ἑαυτοὺς ἀποδεικνύουσιν ἐκ Σαβίνων Νομᾶν Πομπίλιον, ἄνδρα τῶν μὲν εἰς Ῥώμην ἀπῳκισμένων οὐ γενόμενον. γνώριμον δ’ οὕτω δι’ ἀρετὴν ὄντα πᾶσιν ὥστε τῶν ἑλομένων προθυμότερον ὀνομασθέντος αὐτοῦ δέξασθαι τοὺς Σαβίνους, φράσαντες οὖν τῷ δήμῳ τὰ δεδογμένα, πρέσβεις ἐκπέμπουσι πρὸς τὸν ἄνδρα κοινῇ τοὺς πρωτεύοντας ἀπ’ ἀμφοτέρων, ἥκειν δεησομένους καὶ παραλαβεῖν τὴν βασιλείαν.", "st": "Num. 3.1"}, {"sp": "N", "t": "ἦν δὲ πόλεως μὲν ὁ Νομᾶς ἐπιφανοῦς ἐν Σαβίνοις τῆς Κύρεων, ἀφ’ ἧς καὶ Κυρίτας Ῥωμαῖοι σφᾶς αὐτοὺς ἅμα τοῖς ἀνακραθεῖσι Σαβίνοις προσηγόρευσαν, υἱὸς δὲ Πόμπωνος, ἀνδρὸς εὐδοκίμου, τεσσάρων ἀδελφῶν νεώτατος· ἡμέρᾳ δὲ γεγονὼς κατὰ δή τινα θείαν τύχην ἐν ᾗ τὴν Ῥώμην ἔκτισαν οἱ περὶ Ῥωμύλον αὕτη δὲ ἐστι πρὸ δεκαμιᾶς καλανδῶν Μαΐων. φύσει δὲ πρὸς πᾶσαν ἀρετὴν εὖ κεκραμένος τὸ ἦθος, ἔτι μᾶλλον αὑτὸν ἐξημέρωσε διὰ παιδείας καὶ κακοπαθείας καὶ φιλοσοφίας, οὐ μόνον τὰ λοιδορούμενα πάθη τῆς ψυχῆς, ἀλλὰ καὶ τὴν εὐδοκιμοῦσαν ἐν τοῖς βαρβάροις βίαν καὶ πλεονεξίαν ἐκποδὼν ποιησάμενος, ἀνδρείαν δὲ ἀληθῆ τὴν ὑπὸ λόγου τῶν ἐπιθυμιῶν ἐν αὑτῷ κάθειρξιν ἡγούμενος. ἐκ δὲ τούτου πᾶσαν οἴκοθεν ἅμα τρυφὴν καὶ πολυτέλειαν ἐξελαύνων, παντὶ δὲ πολίτῃ καὶ ξένῳ χρῆσθαι παρέχων ἑαυτὸν ἄμεμπτον δικαστὴν καὶ σύμβουλον, αὐτὸς δ’ ἑαυτῷ σχολάζοντι χρώμενος οὐδὲν πρὸς ἡδυπαθείας καὶ πορισμούς, ἀλλὰ θεραπείαν θεῶν καὶ θεωρίαν διὰ λόγου φύσεώς τε αὐτῶν καὶ δυνάμεως, ὄνομα μέγα καὶ δόξαν εἶχεν, ὥστε καὶ Τάτιον τὸν ἐν Ῥώμῃ συμβασιλεύσαντα Ῥωμύλῳ, μιᾶς αὐτῷ θυγατρὸς οὔσης Τατίας, ποιήσασθαι γαμβρὸν ἐκεῖνον. οὐ μὴν ἐπήρθη γε τῷ γάμῳ μετοικίσασθαι πρὸς τὸν πενθερόν, ἀλλ’ αὐτοῦ περιέπων πατέρα γηραιὸν ἐν Σαβίνοις ὑπέμενεν, ἅμα καὶ τῆς Τατίας ἑλομένης τὴν τοῦ ἀνδρὸς ἰδιωτεύοντος ἡσυχίαν πρὸ τῆς ἐν Ῥώμῃ διὰ τὸν πατέρα τιμῆς καὶ δόξης, αὕτη μὲν οὖν λέγεται τρίτῳ καὶ δεκάτῳ μετὰ τὸν γάμον ἔτει τελευτῆσαι.", "st": "Num. 3.4"}, {"sp": "N", "t": "ὁ δὲ Νομᾶς ἐκλείπων τὰς ἐν ἄστει διατριβὰς ἀγραυλεῖν τὰ πολλὰ καὶ πλανᾶσθαι μόνος ἤθελεν, ἐν ἄλσεσι θεῶν καὶ λειμῶσιν ἱεροῖς καὶ τόποις ἐρήμοις ποιούμενος τὴν δίαιταν. ὅθεν οὐχ ἥκιστα τὴν ἀρχὴν ὁ περὶ τῆς θεᾶς ἔλαβε λόγος, ὡς ἄρα Νομᾶς ἐκεῖνος οὐκ ἀδημονίᾳ τινὶ ψυχῆς καὶ πλάνῃ τὸν μετὰ ἀνθρώπων ἀπολέλοιπε βίον, ἀλλὰ σεμνοτέρας γεγευμένος ὁμιλίας καὶ γάμων θείων ἠξιωμένος, Ἠγερίᾳ δαίμονι συνὼν ἐρώσῃ καὶ συνδιαιτώμενος, εὐδαίμων ἀνήρ καὶ τὰ θεῖα πεπνυμένος γέγονεν. ὅτι μὲν οὖν ταῦτα πολλοῖς τῶν πάνυ παλαιῶν μύθων ἔοικεν, οὓς οἱ Φρύγες τε περὶ Ἄττεω καὶ Βιθυνοὶ περὶ Ἡροδότου καὶ περὶ Ἐνδυμίωνος Ἀρκάδες ἄλλοι τε περὶ ἄλλων εὐδαιμόνων δή τινων καὶ θεοφιλῶν γενέσθαι δοκούντων παραλαβόντες ἠγάπησαν, οὐκ ἄδηλόν ἔστι. καί που λόγον ἔχει τὸν θεόν, οὐ φίλιππον οὐδὲ φίλορνιν, ἀλλὰ φιλάνθρωπον ὄντα, τοῖς διαφερόντως ἀγαθοῖς ἐθέλειν συνεῖναι, καὶ μὴ δυσχεραίνειν μηδὲ ἀτιμάζειν ἀνδρὸς ὁσίου καὶ σώφρονος ὁμιλίαν. ὡς δὲ καὶ σώματος ἀνθρωπίνου καὶ ὥρας ἐστί τις θεῷ καὶ δαίμονι κοινωνία καὶ χάρις, ἔργον ἤδη καὶ τοῦτο πεισθῆναι.", "st": "Num. 4.1"}, {"sp": "N", "t": "καίτοι δοκοῦσιν οὐκ ἀπιθάνως Αἰγύπτιοι διαιρεῖν ὡς γυναικὶ μὲν οὐκ ἀδύνατον πνεῦμα πλησιάσαι θεοῦ καί τινας ἐντεκεῖν ἀρχὰς γενέσεως, ἀνδρὶ δὲ οὐκ ἔστι σύμμιξις πρὸς θεὸν οὐδὲ ὁμιλία σώματος. ἀγνοοῦσι δὲ ὅτι τὸ μιγνύμενον ᾧ μίγνυται τὴν ἴσην ἀνταποδίδωσι κοινωνίαν. οὐ μὴν ἀλλὰ φιλίαν γε πρὸς ἄνθρωπον εἶναι θεῷ καὶ τὸν ἐπὶ ταύτῃ λεγόμενον ἔρωτα καὶ φυόμενον εἰς ἐπιμέλειαν ἤθους καὶ ἀρετῆς, πρέπον ἂν εἴη. καὶ οὐ πλημμελοῦσιν οἱ τὸν Φόρβαντα καὶ τὸν Ὑάκινθον καὶ τὸν Ἄδμητον ἐρωμένους Ἀπόλλωνος γεγονέναι μυθολογοῦντες, ὥσπερ αὖ καὶ τὸν Σικυώνιον Ἱππόλυτον, ᾧ δὴ καί φασιν, ὁσάκις τύχοι διαπλέων εἰς Κίρραν ἐκ Σικυῶνος, τὴν Πυθίαν, οἷον αἰσθανομένου τοῦ θεοῦ καὶ χαίροντος, ἀποθεσπίζειν τόδε τὸ ἡρῷον", "st": "Num. 4.4"}, {"sp": "N", "t": "καὶ δ’ αὖθ’ Ἱππολύτοιο φίλον κάρα εἰς ἅλα βαίνει.", "st": "Num. 4.4b"}, {"sp": "N", "t": "Πινδάρου δὲ καὶ τῶν μελῶν ἐραστὴν γενέσθαι τὸν Πᾶνα μυθολογοῦσιν. ἀπέδωκε δέ τινα τιμὴν καὶ Ἀρχιλόχῳ καὶ Ἡσιόδῳ τελευτήσασι διὰ τὰς Μούσας τὸ δαιμόνιον. Σοφοκλεῖ δὲ καὶ ζῶντι τὸν Ἀσκληπιὸν ἐπιξενωθῆναι λόγος ἐστὶ πολλὰ μέχρι δεῦρο διασώζων τεκμήρια, καὶ τελευτήσαντι τυχεῖν ταφῆς ἄλλος θεός, ὡς λέγεται, παρέσχεν. ἆρα οὖν ἄξιον ἔστι, ταῦτα συγχωροῦντας ἐπὶ τούτων, ἀπιστεῖν εἰ Ζαλεύκῳ καὶ Μίνῳ καὶ Ζωροάστρῃ καὶ Νομᾷ καὶ Λυκούργῳ βασιλείας κυβερνῶσι καὶ πολιτείας διακοσμοῦσιν εἰς τὸ αὐτὸ ἐφοίτα τὸ δαιμόνιον, ἢ τούτοις μὲν εἰκὸς ἔστι καὶ σπουδάζοντας θεοὺς ὁμιλεῖν ἐπὶ διδασκαλίᾳ καὶ παραινέσει τῶν βελτίστων, ποιηταῖς δὲ καὶ λυρικοῖς μινυρίζουσιν, εἴπερ ρ ἄρα, χρῆσθαι παίζοντας; εἰ δὲ λέγει τις ἄλλως, κατὰ Βακχυλίδην, πλατεῖα κέλευθος. οὐδὲ γὰρ ἅτερος λόγος ἔχει τι φαῦλον, ὃν περὶ Λυκούργου καὶ Νομᾶ καὶ τοιούτων ἄλλων ἀνδρῶν λέγουσιν, ὡς δυσκάθεκτα καὶ δυσάρεστα πλήθη χειρούμενοι καὶ μεγάλας ς ἐπιφέροντες ταῖς πολιτείαις καινοτομίας, προσεποιήσαντο τὴν ἀπὸ τοῦ θεοῦ δόξαν, αὐτοῖς ἐκείνοις πρὸς οὓς ἐσχηματίζοντο σωτήριον οὖσαν.", "st": "Num. 4.6"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἔτος ἤδη διατελοῦντι τῷ Νομᾷ τεσσαρακοστὸν ἧκον ἀπὸ Ῥώμης οἱ πρέσβεις παρακαλοῦντες ἐπὶ τὴν βασιλείαν. τοὺς δὲ λόγους ἐποιήσατο Πρόκλος καὶ Οὐέλεσος, ὧν πρότερον ἐπίδοξος ἦν ὁ δῆμος αἱρήσεσθαι τὸν ἕτερον βασιλέα, Πρόκλῳ μὲν τῶν Ῥωμύλου λαῶν, Οὐελέσῳ δὲ τῶν Τατίου μάλιστα προσεχόντων. οὗτοι μὲν οὖν βραχέα διελέχθησαν, οἰόμενοι τῷ Νομᾷ τὴν συντυχίαν ἀσπαζομένῳ γεγονέναι· ἦν δ’ οὐ μικρόν, ὡς ἔοικεν, ἔργον, ἀλλὰ καὶ λόγων πολλῶν καὶ δεήσεως τὸ πεῖσαι καὶ μεταστῆσαι γνώμην ἀνδρὸς ἐν ἡσυχία καὶ εἰρήνῃ βεβιωκότος εἰς ἀρχὴν πόλεως τρόπον τινὰ καὶ γεγενημένης πολέμῳ καὶ συνηυξημένης. ἔλεγεν οὖν τοῦ τε πατρὸς αὐτοῦ παρόντος καὶ Μαρκίου, τῶν συγγενῶν ἑνός, ὡς πᾶσα μὲν ἀνθρωπίνου βίου μεταβολὴ σφαλερὸν ᾧ δὲ μήτ’ ἄπεστί τι τῶν ἱκανῶν μήτε μεμπτόν ἐστι τῶν παρόντων, τοῦτον οὐδὲν ἄλλο πλὴν ἄνοια μετακοσμεῖ καὶ μεθίστησιν ἐκ τῶν συνήθων οἷς κἂν εἰ μηδὲν ἕτερον προσείη, τῷ βεβαιοτέρῳ διαφέρει τῶν ἀδήλων, ἀλλ’ οὐδὲ ἄδηλα τὰ τῆς βασιλείας τοῖς Ῥωμύλου τεκμαιρομένῳ παθήμασιν, ὡς πονηρὰν μὲν αὐτὸς ἔλαβε δόξαν ἐπιβουλεῦσαι τῷ συνάρχοντι Τατίῳ, πονηρὰν δὲ τοῖς ὁμοτίμοις περιεποίησεν ὡς ἀνῃρημένος ὑπ’ αὐτῶν, καίτοι Ῥωμύλον μὲν οὗτοι παῖδα θεῶν ὑμνοῦσι φήμαις, καὶ τροφήν τινα δαιμόνιον αὐτοῦ καὶ σωτηρίαν ἄπιστον ἔτι νηπίου λέγουσιν ἐμοὶ δὲ καὶ γένος θνητόν ἐστι καὶ τροφὴ καὶ παίδευσις ὑπ’ ἀνθρώπων ὧν οὐκ ἀγνοεῖτε γεγενημένη· τὰ δ’ ἐπαινούμενα τοῦ τρόπου βασιλεύειν πόρρω μέλλοντος ἀνδρός, ἡσυχία τε πολλὴ καὶ διατριβὴ περὶ λόγους ἀπράγμονας, ὅ τε δεινὸς οὗτος καὶ σύντροφος εἰρήνης ἔρως καὶ πραγμάτων ἀπολέμων καὶ ἀνθρώπων ἐπὶ τιμῇ θεῶν καὶ φιλοφροσύναις εἰς τὸ αὐτὸ συνιόντων, τὰ δὲ ἄλλα καθ’ ἑαυτοὺς γεωργούντων ἢ νεμόντων. ὑμῖν δέ, ὦ Ῥωμαῖοι, πολλοὺς μὲν ἴσως ἀβουλήτους ἀπολέλοιπε πολέμους Ῥωμύλος, οἷς ἀντερείδοντος ἡ πόλις ἐμπείρου δεῖται βασιλέως καὶ ἀκμάζοντος· πολλὴ δὲ καὶ συνήθεια καὶ προθυμία δι’ εὐτυχίαν γέγονε τῷ δήμῳ, καὶ οὐδένα λέληθεν αὔξεσθαι καὶ κρατεῖν ἑτέρων βουλόμενος, ὥστε καὶ γέλως ἂν εἴη τἀμά, θεραπεύοντος θεούς, καὶ δίκην τιμᾶν, βίαν δὲ καὶ πόλεμον ἐχθαίρειν διδάσκοντος πόλιν στρατηλάτου μᾶλλον ἢ βασιλέως δεομένην.", "st": "Num. 5.1"}, {"sp": "N", "t": "τοιούτοις λόγοις ἀφοσιουμένου τὴν βασιλείαν τοῦ ἀνδρός, οἵ τε Ῥωμαῖοι πᾶσαν ἐποιοῦντο σπουδὴν ἀντιβολοῦντες καὶ δεόμενοι μὴ σφᾶς αὖθις εἰς στάσιν ἐμβαλεῖν καὶ πόλεμον ἐμφύλιον, οὐκ ὄντος ἑτέρου πρὸς ὃν ἀμφότεραι συννεύσουσιν αἱ στάσεις, ὅ τε πατήρ καὶ ὁ Μάρκιος ἐκείνων μεταστάντων ἰδίᾳ προσκείμενοι τὸν Νομᾶν ἔπειθον δέχεσθαι μέγα καὶ θεῖον δῶρον. εἰ δὲ αὐτὸς οὔτε πλούτου δέῃ δι’ αὐτάρκειαν οὔτε δόξαν ἀρχῆς καὶ δυναστείας ἐζήλωκας κρείσσονα τὴν ἀπ’ ἀρετῆς ἔχων, ἀλλ’ ὑπηρεσίαν γε θεοῦ τὸ βασιλεύειν ἡγούμενος, ὅς γε ἀνίστησι καὶ οὐκ ἐᾷ κεῖσθαι καὶ ἀργεῖν τὴν ἐν σοὶ τοσαύτην δικαιοσύνην, μὴ φεῦγε μηδὲ ἀποδίδρασκε τὴν ἀρχήν, ἀνδρὶ φρονίμῳ πράξεων καλῶν καὶ μεγάλων οὖσαν χώραν, ἐν ᾗ καὶ θεραπεῖαι θεῶν μεγαλοπρεπεῖς εἰσι καὶ πρὸς εὐσέβειαν ἀνθρώπων ἡμερώσεις ῥᾷστα καὶ τάχιστα μετακοσμουμένων ὑπὸ τὸν κρατοῦντος, οὗτοι καὶ Τάτιον ἔστερξαν ἔπηλυν ἡγεμόνα, καὶ τὴν Ῥωμύλου μνήμην ἀποθεοῦσι ταῖς τιμαῖς. τίς δὲ οἶδεν εἰ καὶ νικῶντι δήμῳ πολέμου κόρος ἐστί, καὶ μεστοὶ θριάμβων καὶ λαφύρων γεγονότες ἡγεμόνα πρᾷον καὶ δίκης ἑταῖρον ἐπ’ εὐνομίᾳ καὶ εἰρήνῃ ποθοῦσιν; εἰ δὲ δὴ καὶ παντάπασιν ἀκρατῶς ἔχουσι καὶ μανικῶς πρὸς πόλεμον, ἆρ’ οὐχὶ βέλτιον ἀλλαχόσε τὴν ὁρμὴν αὐτῶν τρέπειν, διὰ χειρὸς ἔχοντα τὰς ἡ νίας, τῇ δὲ πατρίδι καὶ παντὶ τῷ Σαβίνων ἔθνει σύνδεσμον εὐνοίας καὶ φιλίας πρὸς πόλιν ἀκμάζουσαν καὶ δυνατὴν γενέσθαι; τούτοις προσῆν, ὡς λέγεται, σημεῖά τε χρηστὰ καὶ σπουδὴ τῶν πολιτῶν καὶ ζῆλος, ὡς ἐπύθοντο τὴν πρεσβείαν, δεομένων βαδίζειν καὶ παραλαμβάνειν τὴν βασιλείαν ἐπὶ κοινωνίᾳ καὶ συγκράσει τῶν πολιτῶν.", "st": "Num. 6.1"}, {"sp": "N", "t": "ὡς οὖν ἐδέδοκτο, θύσας τοῖς θεοῖς προῆγεν εἰς τὴν Ῥώμην. ἀπήντα δὲ ἡ βουλὴ καὶ ὁ δῆμος ἔρωτι θαυμαστῷ τοῦ ἀνδρός, εὐφημίαι τε πρέπουσαι γυναικῶν ἐγίνοντο καὶ θυσίαι πρὸς ἱεροῖς καὶ χαρὰ πάντων, ὥσπερ οὐ βασιλέα τῆς πόλεως, ἀλλὰ βασιλείαν δεχομένης, ἐπεὶ δὲ εἰς τὴν ἀγορὰν κατέστησαν, ὁ μὲν ταῖς ὥραις ἐκείναις συνειληχὼς μεσοβασιλεὺς Σπόριος Οὐέττιος ψῆφον ἐπέδωκε τοῖς πολίταις καὶ πάντες ἤνεγκαν, προσφερομένων δ’ αὐτῷ τῶν βασιλικῶν παρασήμων ἐπισχεῖν κελεύσας ἔφη δεῖσθαι καὶ θεοῦ τὴν βασιλείαν ἐμπεδοῦντος αὐτῷ. παραλαβὼν δὲ μάντεις καὶ ἱερεῖς ἀνέβαινεν εἰς τὸ Καπιτώλιον Ταρπήϊον αὐτὸ λόφον οἱ τότε Ῥωμαῖοι προσηγόρευον. ἐνταῦθα τῶν μάντεων ὁ πρωτεύων τὸν μὲν εἰς μεσημβρίαν τρέψας ἐγκεκαλυμμένον, αὐτὸς δὲ παραστὰς ἐξόπισθεν καὶ τῇ δεξιᾷ τῆς κεφαλῆς ἐφαπτόμενος αὐτοῦ κατεύξατο, καὶ περιεσκόπει τὰ παρὰ τῶν θεῶν ἐν οἰωνοῖς ἢ συμβόλοις προφαινόμενα, πανταχόσε τὰς ὄψεις περιφέρων. σιγὴ δὲ ἄπιστος ἐν πλήθει τοσούτῳ τὴν ἀγορὰν κατεῖχε καραδοκούντων καὶ συναιωρουμένων τῷ μέλλοντι, μέχρι οὗ προὐφάνησαν ὄρνιθες ἀγαθοὶ καὶ δεξιοὶ ἐπέτρεψαν οὕτω δὲ τὴν βασιλικὴν ἀναλαβὼν ἐσθῆτα κατέβαινε Νομᾶς εἰς τὸ πλῆθος ἀπὸ τῆς ἄκρας, τότε δὲ καὶ φωναὶ καὶ δεξιώσεις ἦσαν ὡς εὐσεβέστατον καὶ θεοφιλέστατον δεχομένων.", "st": "Num. 7.1"}, {"sp": "N", "t": "παραλαβὼν δὲ τὴν ἀρχὴν πρῶτον μὲν τὸ τῶν τριακοσίων σύστημα διέλυσεν, οὓς Ῥωμύλος ἔχων ἀεὶ περὶ τὸ σῶμα Κέλερας προσηγόρευσεν, ὅπερ ἐστὶ ταχεῖς· οὔτε γὰρ ἀπιστεῖν πιστεύουσιν οὔτε βασιλεύειν ἀπιστούντων ἠξίου. δεύτερον δὲ τοῖς οὖσιν ἱερεῦσι Διὸς καὶ Ἄρεως τρίτον Ῥωμύλου προσκατέστησεν, ὃν Φλάμινα Κυρινάλιον ὠνόμασεν. ἐκάλουν δὲ καὶ τοὺς προγενεστέρους Φλάμινας ἀπὸ τῶν περικρανίων πίλων οὓς περὶ ταῖς κεφαλαῖς φοροῦσι, πιλαμένας τινὰς ὄντας, ὡς ἱστοροῦσι, τῶν Ἑλληνικῶν ὀνομάτων τότε μᾶλλον ἢ νῦν τοῖς Λατίνοις ἀνακεκραμένων. καὶ γάρ ἃς ἐφόρουν οἱ ἱερεῖς λαίνας ὁ Ἰόβας χλαίνας φησὶν εἶναι, καὶ τὸν ὑπηρετοῦντα τῷ ἱερεῖ τοῦ Διὸς ἀμφιθαλῆ παῖδα λέγεσθαι Κάμιλλον, ὡς καὶ τὸν Ἑρμῆν οὕτως ἔνιοι τῶν Ἑλλήνων Κάμιλλον ἀπὸ τῆς διακονίας προσηγόρευον.", "st": "Num. 7.4"}, {"sp": "N", "t": "ταῦτα δὲ ὁ Νομᾶς ἐπ’ εὐνοίᾳ καὶ χάριτι τοῦ δήμου πολιτευσάμενος εὐθὺς ἐπεχείρει τὴν πόλιν, ὥσπερ σίδηρον, ἐκ σκληρᾶς καὶ πολεμικῆς μαλακωτέραν ποιῆσαι καὶ δικαιοτέραν. ἀτεχνῶς γὰρ ἣν Πλάτων ἀποκαλεῖ φλεγμαίνουσαν πόλιν ἐκείνη τότ’ ἦν, συστᾶσα μὲν εὐθὺς ἐξ ἀρχῆς τόλμῃ τινὶ καὶ παραβόλῳ θρασύτητι τῶν θρασυτάτων καὶ μαχιμωτάτων ἐκεῖ πανταχόθεν ὠσαμένων, ταῖς δὲ πολλαῖς στρατείαις καὶ τοῖς συνεχέσι πολέμοις τροφῇ χρησαμένη καὶ αὐξήσει τῆς δυνάμεως, καὶ καθάπερ τὰ καταπηγνύμενα τῷ σείεσθαι μᾶλλον ἑδράζεται, ῥώννυσθαι δοκοῦσα διὰ τῶν κινδύνων, οὕτω δὴ μετέωρον καὶ τετραχυμένον δῆμον οὐ μικρᾶς οὐδὲ φαύλης οἰόμενος εἶναι πραγματείας μεταχειρίσασθαι καὶ μετακοσμῆσαι πρὸς εἰρήνην, ἐπηγάγετο τὴν ἀπὸ τῶν θεῶν βοήθειαν, τὰ μὲν πολλὰ θυσίαις καὶ πομπαῖς καὶ χορείαις, ἃς αὐτὸς ὠργίασε καὶ κατέστησεν, ἅμα σεμνότητι διαγωγὴν ἐπίχαριν καὶ φιλάνθρωπον ἡδονὴν ἐχούσαις, δημαγωγῶν καὶ τιθασεύων τὸ θυμοειδὲς καὶ φιλοπόλεμον ἔστι δ’ ὅτε καὶ φόβους τινὰς ἀπαγγέλλων παρὰ τοῦ θεοῦ καὶ φάσματα δαιμόνων ἀλλόκοτα καὶ φωνὰς οὐκ εὐμενεῖς, ἐδούλου καὶ ταπεινὴν ἐποίει τὴν διάνοιαν αὐτῶν ὑπὸ δεισιδαιμονίας. ἐξ ὧν καὶ μάλιστα λόγον ἔσχεν ἡ σοφία καὶ ἡ παίδευσις τοῦ ἀνδρός, ὡς Πυθαγόρᾳ συγγεγονότος. μέγα γὰρ ἦν μέρος, ὡς ἐκείνῳ τῆς φιλοσοφίας, καὶ τούτῳ τῆς πολιτείας ἡ περὶ τὸ θεῖον ἁγιστεία καὶ διατριβή. λέγεται δὲ καὶ τὸν ἔξωθεν ὄγκον καὶ σχηματισμὸν ἀπὸ τῆς αὐτῆς Πυθαγόρᾳ διανοίας περιβαλέσθαι. καὶ γάρ ἐκεῖνος ἀετόν τε δοκεῖ πραῦναι, φωναῖς τισιν ἐπιστήσας καὶ καταγαγὼν ὑπεριπτάμενον, τόν τε μηρὸν ὑποφῆναι χρυσοῦν Ὀλυμπίασι διαπορευόμενος τὴν πανήγυριν· ἄλλας τε τερατώδεις μηχανὰς αὐτοῦ καὶ πράξεις ἀναγγέλλουσιν, ἐφ’ αἷς καὶ Τίμων ὁ Φλιάσιος ἔγραψε·", "st": "Num. 8.1"}, {"sp": "N", "t": "Πυθαγόρην δὲ γόητας ἀποκλίνοντ’ ἐπὶ δόξας<br>θήρῃ ἐπ’ ἀνθρώπων, σεμνηγορίης ὀαριστὴν", "st": "Num. 8.1b"}, {"sp": "N", "t": "τῷ δὲ Νομᾷ δρᾶμα θεᾶς τινος ἢ νύμφης ὀρείας ἔρως ἦν καὶ συνουσία πρὸς αὐτὸν ἀπόρρητος, ὥσπερ εἴρηται, καὶ κοιναὶ μετὰ Μουσῶν διατριβαί. τὰ γὰρ· πλεῖστα τῶν μαντευμάτων εἰς Μούσας ἀνῆγε, καὶ μίαν Μοῦσαν ἰδίως καὶ διαφερόντως ἐδίδαξε σέβεσθαι τοὺς Ῥωμαίους, Τακίταν προσαγορεύσας, οἷον σιωπηλὴν ἢ ἐνεάν· ὅπερ εἶναι δοκεῖ τὴν Πυθαγόρειον ἀπομνημονεύοντος ἐχεμυθίαν καὶ τιμῶντος.", "st": "Num. 8.6"}, {"sp": "N", "t": "ἔστι δὲ καὶ τὰ περὶ τῶν ἀφιδρυμάτων νομοθετήματα παντάπασιν ἀδελφὰ τῶν Πυθαγόρου δογμάτων, οὔτε γὰρ ἐκεῖνος αἰσθητὸν ἢ παθητόν, ἀόρατον δὲ καὶ ἄκτιστον καὶ νοητὸν ὑπελάμβανεν εἶναι τὸ πρῶτον, οὗτός τε διεκώλυσεν ἀνθρωποειδῆ καὶ ζῳόμορφον εἰκόνα θεοῦ Ῥωμαίους νομίζειν. οὐδ’ ἦν παρ’ αὑτοῖς οὔτε γραπτὸν οὔτε πλαστὸν εἶδος θεοῦ πρότερον, ἀλλ’ ἐν ἑκατὸν ἑβδομήκοντα τοῖς πρώτοις ἔτεσι ναοὺς μὲν οἰκοδομούμενοι καὶ καλιάδας ἱερὰς ἱστῶντες, ἄγαλμα δὲ οὐδὲν ἔμμορφον ποιούμενοι διετέλουν, ὡς οὔτε ὅσιον ἀφομοιοῦν τὰ βελτίονα τοῖς χείροσιν οὔτε ἐφάπτεσθαι θεοῦ δυνατὸν ἄλλως ἢ νοήσει, κομιδῆ δὲ καὶ τὰ τῶν θυσιῶν ἔχεται τῆς Πυθαγορικῆς ἁγιστείας· ἀναίμακτοι γάρ ἦσαν αἵ γε πολλαί, δι’ ἀλφίτου καὶ σπονδῆς καὶ τῶν εὐτελεστάτων πεποιημέναι.", "st": "Num. 8.7"}, {"sp": "N", "t": "χωρὶς δὲ τούτων ἑτέροις ἔξωθεν ἐπαγωνίζονται τεκμηρίοις οἱ τὸν ἄνδρα τῷ ἀνδρὶ συνοικειοῦντες. ὧν ἓν μέν ἐστιν ὅτι Πυθαγόραν Ῥωμαῖοι τῇ πολιτείᾳ προσέγραψαν, ὡς ἱστόρηκεν Ἐπίχαρμος ὁ κωμικὸς ἔν τινὶ λόγῳ πρὸς Ἀντήνορα γεγραμμένῳ, παλαιὸς ἀνήρ καὶ τῆς Πυθαγορικῆς διατριβῆς μετεσχηκώς ἕτερον δὲ ὅτι τεσσάρων υἱῶν βασιλεῖ Νομᾷ γενομένων ἕνα Μάμερκον ἐπὶ τῷ Πυθαγόρου παιδὶ προσηγόρευσεν. ἀπ’ ἐκείνου δὲ καὶ τὸν Αἰ μιλίων οἶκον ἀναμιχθέντα τοῖς πατρικίοις ὀνομασθῆναί φασιν, οὕτως ὑποκοριζομένου τοῦ βασιλέως τὴν ἐν τοῖς λόγοις τοῦ ἀνδρὸς αἱμυλίαν καὶ χάριν, αὐτοὶ δ’ ἀκηκόαμεν πολλῶν ἐν Ῥώμῃ διεξιόντων ὅτι χρησμοῦ ποτε Ῥωμαίοις γενομένου τὸν φρονιμώτατον καὶ τὸν ἀνδρειότατον Ἑλλήνων ἱδρύσασθαι παρ’ αὑτοῖς, ἔστησαν ἐπὶ τῆς ἀγορᾶς εἰκόνας χαλκᾶς δύο, τὴν μὲν Ἀλκιβιάδου, τὴν δὲ Πυθαγόρου. ταῦτα μὲν οὖν ἀμφισβητήσεις ἔχοντα πολλὰς καὶ τὸ κινεῖν διὰ μακροτέρων καὶ τὸ πιστοῦσθαι μειρακιώδους ἔστι φιλονεικίας.", "st": "Num. 8.9"}, {"sp": "N", "t": "Νομᾷ δὲ καὶ τὴν τῶν ἀρχιερέων, οὓς Ποντίφικας καλοῦσι, διάταξιν καὶ κατάστασιν ἀποδιδόασι, καί φασιν αὐτὸν ἕνα τούτων τὸν πρῶτον γεγονέναι. κεκλῆσθαι δὲ τοὺς Ποντίφικας οἱ μὲν ὅτι τοὺς θεοὺς θεραπεύουσι δυνατοὺς καὶ κυρίους ἁπάντων ὄντας· ὁ γάρ δυνατὸς ὑπὸ Ῥωμαίων ὀνομάζεται πότηνς· ἕτεροι δέ φασι πρὸς ὑπεξαίρεσιν γεγονέναι τοὔνομα τῶν δυνατῶν, ὡς τοῦ νομοθέτου τὰς δυνατὰς ἐπιτελεῖν ἱερουργίας τοὺς ἱερεῖς κελεύοντος, ἂν δὲ ᾖ τι κώλυμα μεῖζον, οὐ συκοφαντοῦντος. οἱ δὲ πλεῖστοι μάλιστα καὶ τὸ γελώμενον τῶν ὀνομάτων δοκιμάζουσιν, ὡς οὐδὲν ἀλλ’ ἢ γεφυροποιοὺς τοὺς ἄνδρας ἐπικληθέντας ἀπὸ τῶν ποιουμένων περὶ τὴν γέφυραν ἱερῶν, ἁγιωτάτων καὶ παλαιοτάτων ὄντων πόντεμ γάρ οἱ Λατῖνοι τὴν γέφυραν ὀνομάζουσιν. εἶναι μέντοι καὶ τὴν τήρησιν αὐτῆς καὶ τὴν ἐπισκευήν, ὥσπερ ἄλλο τι τῶν ἀκινήτων καὶ πατρίων ἱερῶν, προσήκουσαν τοῖς ἱερεῦσιν. οὐ γάρ θεμιτόν, ἀλλ’ ἐπάρατον ἡγεῖσθαι Ῥωμαίους τὴν κατάλυσιν τῆς ξυλίνης γεφύρας, λέγεται δὲ καὶ τὸ πάμπαν ἄνευ σιδήρου κατὰ δή τι λόγιον συγγεγομφῶσθαι διὰ τῶν ξύλων, ἡ δὲ λιθίνη πολλοῖς ὕστερον ἐξειργάσθη χρόνοις ὑπ’ Αἰμιλίου ταμιεύοντος. οὐ μὴν ἀλλὰ καὶ τὴν ξυλίνην τῶν Νομᾶ χρόνων ἀπολείπεσθαι λέγουσιν, ὑπὸ Μαρκίου τοῦ Νομᾶ θυγατριδοῦ βασιλεύοντος ἀποτελεσθεῖσαν.", "st": "Num. 9.1"}, {"sp": "N", "t": "ὁ δὲ μέγιστος τῶν Ποντιφίκων οἷον ἐξηγητοῦ καὶ προφήτου, μᾶλλον δὲ ἱεροφάντου τάξιν εἴληχεν, οὐ μόνον τῶν δημοσίᾳ δρωμένων ἐπιμελούμενος, ἀλλὰ καὶ τοὺς ἰδίᾳ θύοντας ἐπισκοπῶν καὶ κωλύων παρεκβαίνειν τὰ νενομισμένα, καὶ διδάσκων ὅτου τις δέοιτο πρὸς θεῶν τιμὴν ἢ παραίτησιν. ἦν δὲ καὶ τῶν ἱερῶν παρθένων ἐπίσκοπος, ἃς Ἑστιάδας προσαγορεύουσι. Νομᾷ γὰρ δὴ καὶ τὴν τῶν Ἑστιάδων παρθένων καθιέρωσιν καὶ ὅλως τὴν περὶ τὸ πῦρ τὸ ἀθάνατον, ὃ φυλάττουσιν αὗται, θεραπείαν τε καὶ τιμὴν ἀποδιδόασιν, εἴτε ὡς καθαρὰν καὶ ἄφθαρτον τὴν τοῦ πυρὸς οὐσίαν ἀκηράτοις καὶ ἀμιάντοις παρατιθεμένου σώμασιν, εἴτε τὸ ἄκαρπον καὶ ἄγονον τῇ παρθενίᾳ συνοικειοῦντος. ἐπεί τοι τῆς Ἑλλάδος ὅπου πῦρ ἄσβεστόν ἐστιν, ὡς Πυθοῖ καὶ Ἀθήνησιν, οὐ παρθένοι, γυναῖκες δὲ πεπαυμέναι γάμων ἔχουσι τὴν ἐπιμέλειαν· ἐὰν δὲ ὑπὸ τύχης τινὸς ἐκλίπῃ, καθάπερ Ἀθήνησι μὲν ἐπὶ τῆς Ἀριστίωνος λέγεται τυραννίδος ἀποσβεσθῆναι τὸν ἱερὸν λύχνον, ἐν Δελφοῖς δὲ τοῦ ναοῦ καταπρησθέντος ὑπὸ Μήδων, περὶ δὲ τὰ Μιθριδατικὰ καὶ τὸν ἐμφύλιον Ῥωμαίων πόλεμον ἅμα τῷ βωμῷ τὸ πῦρ ἠφανίσθη, οὔ φασι δεῖν ἀπὸ ἑτέρου πυρὸς ἐναύεσθαι, καινὸν δὲ ποιεῖν καὶ νέον, ἀνάπτοντας ἀπὸ τοῦ ἡλίου φλόγα καθαρὰν καὶ ἀμίαντον. ἐξάπτουσι δὲ μάλιστα τοῖς σκαφείοις, ἃ κατασκευάζεται μὲν ἀπὸ πλευρᾶς ἰσοσκελοῦς ὀρθογωνίου τριγώνου κοιλαινόμενα, συννεύει δ’ εἰς ἓν ἐκ τῆς περιφερείας κέντρον. ὅταν οὖν θέσιν ἐναντίαν λάβῃ πρὸς τὸν ἥλιον, ὥστε τὰς αὐγὰς πανταχόθεν ἀνακοπτομένας ἀθροίζεσθαι καὶ συμπλέκεσθαι περὶ τὸ κέντρον, αὐτόν τε διακρίνει τὸν ἀέρα λεπτυνόμενον, καὶ τὰ κουφότατα καὶ ξηρότατα τῶν προστιθεμένων ὀξέως ἀνάπτει κατὰ τὴν ἀντέρεισιν, σῶμα καὶ πληγὴν πυρώδη τῆς αὐγῆς λαβούσης. ἔνιοι μὲν οὖν οὐδὲν ὑπὸ τῶν ἱερῶν παρθένων ἀλλ’ ἢ τὸ ἄσβεστον ἐκεῖνο φρουρεῖσθαι πῦρ νομίζουσιν ἔνιοι δὲ εἶναί τινὰ φασιν ἀθέατα τοῖς ἄλλοις ἱερὰ κρυπτόμενα, περὶ ὧν ὅσα καὶ πυθέσθαι καὶ φράσαι θεμιτὸν ἐν τῷ Καμίλλου βίῳ γέγραπται.", "st": "Num. 9.5"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ὑπὸ Νομᾶ καθιερωθῆναι λέγουσι Γεγανίαν καὶ Βερηνίαν, δεύτερον δὲ Κανουληΐαν καὶ Ταρπηΐαν· ὕστερον δὲ Σερβίου δύο προσθέντος ἄλλας τῷ ἀριθμῷ διατηρεῖσθαι μέχρι τῶν χρόνων τούτων τὸ πλῆθος, ὡρίσθη δὲ ταῖς ἱεραῖς παρθένοις ὑπὸ τοῦ βασιλέως ἁγνεία τριακονταέτις, ἐν ᾗ τὴν μὲν πρώτην δεκαετίαν ἃ χρὴ δρᾶν μανθάνουσι, τὴν δὲ μέσην ἃ μεμαθήκασι δρῶσι, τὴν δὲ τρίτην ἑτέρας αὐταὶ διδάσκουσιν. εἶτα ἀνεῖται τῇ βουλομένῃ μετὰ τὸν χρόνον τοῦτον ἤδη καὶ γάμου μεταλαμβάνειν καὶ πρὸς ἕτερον τραπέσθαι βίον, ἀπαλλαγείσῃ τῆς ἱερουργίας, λέγονται δὲ οὐ πολλαὶ ταύτην ἀσπάσασθαι τὴν ἄδειαν, οὐδὲ ἀσπασαμέναις χρηστὰ πράγματα συντυχεῖν, ἀλλὰ μετανοίᾳ καὶ κατηφείᾳ συνοῦσαι τὸν λοιπὸν βίον ἐμβαλεῖν τὰς ἄλλας εἰς δεισιδαιμονίαν, ὥστε μέχρι γήρως καὶ θανάτου διατελεῖν ἐγκαρτερούσας καὶ παρθενευομένας.", "st": "Num. 10.1"}, {"sp": "N", "t": "τιμὰς δὲ μεγάλας ἀπέδωκεν αὐταῖς, ὧν ἔστι καὶ τὸ διαθέσθαι ζῶντος ἐξεῖναι πατρὸς καὶ τἆλλα πράττειν ἄνευ προστάτου διαγούσας, ὥσπερ αἱ τρίπαιδες. ῥαβδουχοῦνται δὲ προϊοῦσαι· κἂν ἀγομένῳ τινὶ πρὸς θάνατον αὐτομάτως συντύχωσιν, οὐκ ἀναιρεῖται, δεῖ δὲ ἀπομόσαι τὴν παρθένον ἀκούσιον καὶ τυχαίαν καὶ οὐκ ἐξεπίτηδες γεγονέναι τὴν ἀπάντησιν. ὁ δὲ ὑπελθὼν κομιζομένων ὑπὸ τὸ φορεῖον ἀποθνήσκει. κόλασις δὲ τῶν μὲν ἄλλων ἁμαρτημάτων πληγαὶ ταῖς παρθένοις, τοῦ μεγίστου Ποντίφικος κολάζοντος ἔστιν ὅτε καὶ γυμνὴν τὴν πλημμελήσασαν, ὀθόνης ἐν παλινσκίῳ παρατεινομένης· ἡ δὲ τὴν παρθενίαν καταισχύνασα ζῶσα κατορύττεται παρὰ τὴν Κολλίνην λεγομένην πύλην ἐν ᾗ τις ἔστιν ἐντὸς τῆς πόλεως ὀφρὺς γεώδης παρατείνουσα πόρρω· καλεῖται δὲ χῶμα διαλέκτῳ τῇ Λατίνων, ἐνταῦθα κατασκευάζεται κατάγειος οἶκος οὐ μέγας, ἔχων ἄνωθεν κατάβασιν. κεῖται δὲ ἐν αὐτῷ κλίνη τε ὑπεστρωμένη καὶ λύχνος καιόμενος, ἀπαρχαί τε τῶν πρὸς τὸ ζῆν ἀναγκαίων βραχεῖαί τινες, οἷον ἄρτος, ὕδωρ ἐν ἀγγείῳ, γάλα, ἔλαιον, ὥσπερ ἀφοσιουμένων τὸ μὴ λιμῷ διαφθείρειν σῶμα ταῖς μεγίσταις καθιερωμένον ἁγιστείαις. αὐτὴν δὲ τὴν κολαζομένην εἰς φορεῖον ἐνθέμενοι καὶ καταστεγάσαντες ἔξωθεν καὶ καταλαβόντες ἱμᾶσιν, ὡς μηδὲ φωνὴν ἐξάκουστον γενέσθαι, κομίζουσι δι’ ἀγορᾶς, ἐξίστανται δὲ πάντες σιωπῇ καὶ παραπέμπουσιν ἄφθογγοι μετά τινος δεινῆς κατηφείας οὐδὲ ἔστιν ἕτερον θέαμα φρικτότερον, οὐδ’ ἡμέραν ἡ πόλις ἄλλην ἄγει στυγνοτέραν ἐκείνης. ὅταν δὲ πρὸς τὸν τόπον κομισθῇ τὸ φορεῖον, οἱ μὲν ὑπηρέται τοὺς δεσμοὺς ἐξέλυσαν, ὁ δὲ τῶν ἱερέων ἔξαρχος εὐχάς τινας ἀπορρήτους ποιησάμενος καὶ χεῖρας ἀνατείνας θεοῖς πρὸ τῆς ἀνάγκης, ἐξάγει συγκεκαλυμμένην καὶ καθίστησιν ἐπὶ κλίμακος εἰς τὸ οἴκημα κάτω φερούσης. εἶτα αὐτὸς μὲν ἀποτρέπεται μετὰ τῶν ἄλλων ἱερέων τῆς δὲ καταβάσης ἥ τε κλίμαξ ἀναιρεῖται καὶ κατακρύπτεται τὸ οἴκημα γῆς πολλῆς ἄνωθεν ἐπιφορουμένης, ὥστε ἰσόπεδον τῷ λοιπῷ χώματι γενέσθαι τὸν τόπον, οὕτω μὲν αἱ προέμεναι τὴν ἱερὰν παρθενίαν κολάζονται.", "st": "Num. 10.3"}, {"sp": "N", "t": "Νομᾶς δὲ λέγεται καὶ τὸ τῆς Ἑστίας ἱερὸν ἐγκύκλιον περιβαλέσθαι τῷ ἀσβέστῳ πυρὶ φρουράν, ἀπομιμούμενος οὐ τὸ σχῆμα τῆς γῆς ὡς Ἑστίας οὔσης, ἀλλὰ τοῦ σύμπαντος κόσμου, οὗ μέσον οἱ Πυθαγορικοὶ τὸ πῦρ ἱδρῦσθαι νομίζουσι, καὶ τοῦτο Ἑστίαν καλοῦσι καὶ μονάδα· τὴν δὲ γῆν οὔτε ἀκίνητον οὔτε ἐν μέσῳ τῆς περιφορᾶς οὖσαν, ἀλλὰ κύκλῳ περὶ τὸ πῦρ αἰωρουμένην οὐ τῶν τιμιωτάτων οὐδὲ τῶν πρώτων τοῦ κόσμου μορίων ὑπάρχειν. ταῦτα δὲ καὶ Πλάτωνά φασι πρεσβύτην γενόμενον διανενοῆσθαι περὶ τῆς γῆς ὡς ἐν ἑτέρᾳ χώρᾳ καθεστώσης, τὴν δὲ μέσην καὶ κυριωτάτην ἑτέρῳ τινὶ κρείττονι προσήκουσαν.", "st": "Num. 11.1"}, {"sp": "N", "t": "οἱ δὲ Ποντίφικες καὶ τὰ περὶ τὰς ταφὰς πάτρια τοῖς χρῄζουσιν ἀφηγοῦνται, Νομᾶ διδάξαντος μηδὲν ἡγεῖσθαι μίασμα τῶν τοιούτων, ἀλλὰ καὶ τοὺς ἐκεῖ θεοὺς σέβεσθαι τοῖς νενομισμένοις, ὡς τὰ κυριώτατα τῶν ἡμετέρων ὑποδεχομένους ἐξαιρέτως δὲ τὴν προσαγορευομένην Λιβίτιναν, ἐπίσκοπον τῶν περὶ τοὺς θνήσκοντας ὁσίων θεὸν οὖσαν, εἴτε Περσεφόνην εἴτε μᾶλλον, ὡς οἱ λογιώτατοι Ῥωμαίων ὑπολαμβάνουσιν, Ἀφροδίτην, οὐ κακῶς εἰς μιᾶς δύναμιν θεοῦ τὰ περὶ τὰς γενέσεις καὶ τὰς τελευτὰς ἀνάπτοντες. αὐτὸς δὲ καὶ τὰ πένθη καθ’ ἡλικίας καὶ χρόνους ἔταξεν οἷον παῖδα μὴ πενθεῖν νεώτερον τριετοῦς, μηδὲ πρεσβύτερον πλείονας μῆνας ὧν ἐβίωσεν ἐνιαυτῶν μέχρι τῶν δέκα, καὶ περαιτέρω μηδεμίαν ἡλικίαν, ἀλλὰ τοῦ μακροτάτου πένθους χρόνον εἶναι δεκαμηνιαῖον, ἐφ’ ὅσον καὶ χηρεύουσιν αἱ τῶν ἀποθανόντων γυναῖκες, ἡ δὲ πρότερον γαμηθεῖσα βοῦν ἐγκύμονα κατέθυεν ἐκείνου νομοθετήσαντος.", "st": "Num. 12.1"}, {"sp": "N", "t": "πολλὰς δὲ καὶ ἄλλας Νομᾶ καταδείξαντος ἱερωσύνας ἔτι δυεῖν μνησθήσομαι, τῆς τε Σαλίων καὶ τῆς τῶν Φιτιαλέων, αἱ μάλιστα τὴν εὐσέβειαν τοῦ ἀνδρὸς ἐμφαίνουσιν. οἱ μὲν γάρ Φιτιαλεῖς εἰρηνοφύλακές τινες ὄντες, ὡς δ’ ἐμοὶ δοκεῖ, καὶ τοὔνομα λαβόντες ἀπὸ τῆς πράξεως, λόγῳ τὰ νείκη κατέπαυον, οὐκ ἐῶντες στρατεύειν πρότερον ἢ πᾶσαν ἐλπίδα δίκης ἀποκοπῆναι. καὶ γὰρ εἰρήνην Ἕλληνες καλοῦσιν ὅταν λόγῳ, μὴ βίᾳ, πρὸς ἀλλήλους χρώμενοι λύσωσι τὰς διαφοράς, οἱ δὲ Ῥωμαίων Φιτιαλεῖς πολλάκις μὲν ἐβάδιζον ὡς τοὺς ἀδικοῦντας αὐτοὶ πείθοντες εὐγνωμονεῖν· ἀγνωμονούντων δὲ μαρτυράμενοι θεούς, καὶ κατευξάμενοι πολλὰ καὶ δεινὰ καθ’ αὑτῶν αὐτοὶ καὶ τῆς πατρίδος εἰ μὴ δικαίως ἐπεξίασιν, οὕτω κατήγγελλον αὐτοῖς τὸν πόλεμον. κωλυόντων δὲ τούτων ἢ μὴ συναινούντων, οὔτε στρατιώτῃ θεμιτὸν οὔτε βασιλεῖ Ῥωμαίων ὅπλα κινεῖν, ἀλλὰ παρὰ τούτων ἔδει τὴν ἀρχὴν τοῦ πολέμου δεξάμενον ὡς δικαίου τὸν ἄρχοντα, τότε σκοπεῖν περὶ τοῦ συμφέροντος, λέγεται δὲ καὶ τὸ Κελτικὸν ἐκεῖνο πάθος τῇ πόλει γενέσθαι τούτων τῶν ἱερέων παρανομηθέντων.", "st": "Num. 12.3"}, {"sp": "N", "t": "ἔτυχον μὲν γὰρ οἱ βάρβαροι Κλουσίνους πολιορκοῦντες· ἐπέμφθη δὲ πρεσβευτὴς Φάβιος Ἄμβουστος εἰς τὸ στρατόπεδον διαλύσεις πράξων ὑπὲρ τῶν πολιορκουμένων. λαβὼν δὲ ἀποκρίσεις οὐκ ἐπιεικεῖς καὶ πέρας σχεῖν αὑτῷ τὴν πρεσβείαν οἰόμενος, ἐνεανιεύσατο πρὸ τῶν Κλουσίνων ὅπλα λαβὼν προκαλέσασθαι τὸν ἀριστεύοντα τῶν βαρβάρων. τὰ μὲν οὖν τῆς μάχης εὐτυχεῖτο καὶ καταβαλὼν ἐσκύλευσε τὸν ἄνδρα γνωρίσαντες δὲ οἱ Κελτοὶ πέμπουσιν εἰς Ῥώμην κήρυκα τοῦ Φαβίου κατηγοροῦντες ὡς ἐκσπόνδου καὶ ἀπίστου καὶ ἀκατάγγελτον ἐξενηνοχότος πρὸς αὐτοὺς πόλεμον. ἐνταῦθα τὴν μὲν σύγκλητον οἱ Φιτιαλεῖς ἔπειθον ἐκδιδόναι τὸν ἄνδρα τοῖς Κελτοῖς, καταφυγὼν δὲ ἐκεῖνος εἰς τοὺς πολλοὺς καὶ τῷ δήμῳ σπουδάζοντι χρησάμενος διεκρούσατο τὴν δίκην. μετ’ ὀλίγον δὲ ἐπελθόντες οἱ Κελτοὶ τὴν Ῥώμην πλὴν τοῦ Καπιτωλίου διεπόρθησαν. ἀλλὰ ταῦτα μὲν ἐν τοῖς περὶ Καμίλλου μᾶλλον ἀκριβοῦται.", "st": "Num. 12.6"}, {"sp": "N", "t": "τοὺς δὲ Σαλίους ἱερεῖς ἐκ τοιαύτης λέγεται συστήσασθαι προφάσεως. ἔτος ὄγδοον αὐτοῦ βασιλεύοντος λοιμώδης νόσος περιϊοῦσα τὴν Ἰταλίαν ἐστρόβησε καὶ τὴν Ῥώμην. ἀθυμούντων δὲ τῶν ἀνθρώπων ἱστορεῖται χαλκῆν πέλτην ἐξ οὐρανοῦ καταφερομένην εἰς τὰς Νομᾶ πεσεῖν χεῖρας. ἐπὶ δὲ αὐτῇ θαυμάσιόν τινα λόγον λέγεσθαι ὑπὸ τοῦ βασιλέως, ὃν Ἠγερίας τε καὶ τῶν Μουσῶν πυθέσθαι. τὸ μὲν γάρ ὅπλον ἥκειν ἐπὶ σωτηρίᾳ τῆς πόλεως, καὶ δεῖν αὐτὸ φρουρεῖσθαι γενομένων ἄλλων ἕνδεκα καὶ σχῆμα καὶ μέγεθος καὶ μορφὴν ἐκείνῳ παραπλησίων, ὅπως ἄπορον εἴη τῷ κλέπτῃ δι’ ὁμοιότητα τοῦ διοπετοῦς ἐπιτυχεῖν ἔτι δὲ χρῆναι Μούσαις καθιερῶσαι τὸ χωρίον ἐκεῖνο καὶ τοὺς περὶ αὐτὸ λειμῶνας, ὅπου τὰ πολλὰ φοιτῶσαι συνδιατρίβουσιν αὐτῷ. τὴν δὲ πηγὴν ἣ κατάρδει τὸ χωρίον, ὕδωρ ἱερὸν ἀποδεῖξαι ταῖς Ἑστιάσι παρθένοις, ὅπως λαμβάνουσαι καθ’ ἡμέραν ἁγνίζωσι καὶ ῥαίνωσι τὸ ἀνάκτορον. τούτοις μὲν οὖν μαρτυρῆσαι λέγουσι καὶ τὰ τῆς νόσου παραχρῆμα παυσάμενα. τὴν δὲ πέλτην προθέντος αὐτοῦ καὶ κελεύσαντος ἁμιλλᾶσθαι τοὺς τεχνίτας ὑπὲρ τῆς ὁμοιότητος, τοὺς μὲν ἄλλους ἀπειπεῖν, Οὐετούριον δὲ Μαμούριον ἕνα α τῶν ἄκρων δημιουργῶν οὕτως ἐφικέσθαι τῆς ἐμφερείας, καὶ κατασκευάσαι πάσας ὁμοίας, ὥστε μηδ’ αὐτὸν ἔτι τὸν Νομᾶν διαγινώσκειν. τούτων οὖν φύλακας καὶ ἀμφιπόλους ἀπέδειξε τοὺς Σαλίους ἱερεῖς. σάλιοι δὲ ἐκλήθησαν, οὐχ, ὡς ἔνιοι μυθολογοῦσι, Σαμόθρᾳκος ἀνδρὸς ἢ Μαντινέως, ὄνομα Σαλίου, πρώτου τὴν ἐνόπλιον ἐκδιδάξαντος ὄρχησιν, ἀλλὰ μᾶλλον ἀπὸ τῆς ὀρχήσεως αὐτῆς, ἁλτικῆς οὔσης, ἣν ὑπορχοῦνται διαπορευόμενοι τὴν πόλιν, ὅταν τὰς ἱερὰς πέλτας ἀναλάβωσιν ἐν τῷ Μαρτίῳ μηνί, φοινικοῦς μὲν ἐνδεδυμένοι χιτωνίσκους, μίτραις δὲ χαλκαῖς ἐπεζωσμένοι πλατείαις καὶ κράνη χαλκᾶ φοροῦντες, ἐγχειριδίοις δὲ μικροῖς τὰ ὅπλα κρούοντες. ἡ δὲ ἄλλη τῆς ὀρχήσεως ποδῶν ἔργον ἐστί· κινοῦνται γάρ ἐπιτερπῶς, ἑλιγμούς τινας καὶ μεταβολὰς ἐν ῥυθμῷ τάχος ἔχοντι καὶ πυκνότητα μετὰ ῥώμης καὶ κουφότητος ἀποδιδόντες.", "st": "Num. 13.1"}, {"sp": "N", "t": "αὐτὰς ς δὲ τὰς πέλτας ἀγκύλια καλοῦσι διὰ τὸ σχῆμα· κύκλος γάρ οὐκ ἔστιν οὐδὲ ἀποδίδωσιν, ὡς πέλτη, τὴν περιφέρειαν, ἀλλ’ ἐκτομὴν ἔχει γραμμῆς ἑλικοειδοῦς, ἧς αἱ κεραῖαι καμπὰς ἔχουσαι καὶ συνεπιστρέφουσαι τῇ πυκνότητι πρὸς ἀλλήλας ἀγκύλον τὸ σχῆμα ποιοῦσιν· ἢ διὰ τὸν ἀγκῶνα περὶ ὃν περιφέρονται, ταῦτα γάρ ὁ Ἰόβας εἴρηκε γλιχόμενος ἐξελληνίσαι τοὔνομα. δύναιτο δὲ ἂν τῆς ἀνέκαθεν φορᾶς πρῶτον ἐπώνυμον γεγονέναι, καὶ τῆς ἀκέσεως τῶν νοσούντων, καὶ τῆς τῶν αὐχμῶν λύσεως, ἔτι δὲ τῆς τῶν δεινῶν ἀνασχέσεως, καθ’ ὃ καὶ τοὺς Διοσκούρους Ἄνακας Ἀθηναῖοι προσηγόρευσαν, εἴ γε δεῖ πρὸς τὴν Ἑλληνικὴν διάλεκτον ἐξάγειν τοὔνομα.", "st": "Num. 13.6"}, {"sp": "N", "t": "τῷ δὲ Μαμουρίῳ λέγουσι μισθὸν γενέσθαι τῆς τέχνης ἐκείνης μνήμην τινὰ δι’ ᾠδῆς ὑπὸ τῶν Σαλίων ἅμα τῇ πυρρίχῃ διαπεραινομένης. οἱ δὲ οὐ Οὐετούριον Μαμούριον εἶναί φασι τὸν ᾀδόμενον, ἀλλὰ οὐετέρεμ μεμορίαμ, ὅπερ ἐστί, παλαιὰν μνήμην.", "st": "Num. 13.7"}, {"sp": "N", "t": "ἐπεὶ δὲ διεκόσμησε τὰς ἱερωσύνας, ἐδείματο πλησίον τοῦ τῆς Ἑστίας ἱεροῦ τὴν καλουμένην Ῥηγίαν, οἷόν τι βασίλειον οἴκημα· καὶ τὸ πλεῖστον αὐτόθι τοῦ χρόνου διέτριβεν ἱερουργῶν ἢ διδάσκων τοὺς ἱερεῖς ἢ πρὸς ἐννοίᾳ τινὶ τῶν θείων πρὸς αὑτὸν σχολάζων. οἰκίαν δ’ εἶχεν ἑτέραν περὶ τὸν Κυρίνου λόφον, ἧς ἔτι νῦν τὸν τόπον ἐπιδεικνύουσιν. ἐν δὲ ταῖς προπομπαῖς καὶ ὅλως τῶν ἱερέων ταῖς πομπαῖς προηγοῦντο κήρυκες ἀνὰ τὴν πόλιν ἐλινύειν κελεύοντες καὶ τὰ ἔργα καταπαύοντες. ὡς γάρ φασι τοὺς Πυθαγορικοὺς οὐκ ἐᾶν ἐκ παρόδου προσκυνεῖν καὶ προσεύχεσθαι τοῖς θεοῖς, ἀλλ’ οἴκοθεν εὐθὺς ἐπὶ τοῦτο γνώμῃ παρεσκευασμένους βαδίζειν, οὕτως ᾤετο Νομᾶς χρῆναι τοὺς πολίτας μήτε ἀκούειν τι τῶν θείων μήτε ὁρᾶν ἐν παρέργῳ καὶ ἀμελῶς, ἀλλὰ σχολὴν ἄγοντας ἀπὸ τῶν ἄλλωι καὶ προσέχοντας τὴν διάνοιαν ὡς πράξει μεγίστῃ τῇ περὶ τὴν εὐσέβειαν, ψόφων τε καὶ πατάγων καὶ στεναγμῶν, καὶ ὅσα τοιαῦτα τοῖς ἀναγκαίοις καὶ βαναύσοις πόνοις ἕπεται, καθαρὰς τὰς ὁδοὺς ταῖς ἱερουργίαις παρέχοντας, ὧν ἴχνος τι μέχρι νῦν διασώζοντες, ὅταν ἄρχων πρὸς ὄρνισιν ἢ θυσίαις διατρίβῃ, βοῶσιν Ὃκ ἄγε· σημαίνει δὲ ἡ φωνὴ τοῦτο πρᾶσσε, συνεπιστρέφουσα καὶ κατακοσμοῦσα τοὺς προστυγχάνοντας.", "st": "Num. 14.1"}, {"sp": "N", "t": "ἦν δὲ καὶ τῶν ἄλλων παραγγελμάτων αὐτοῦ πολλὰ τοῖς Πυθαγορικοῖς ἐοικότα. ὡς γὰρ ἐκεῖνοι παρῄνουν ἐπὶ χοίνικος μὴ καθῆσθαι, καὶ μαχαίρᾳ πῦρ μὴ σκαλεύειν, καὶ βαδίζοντας εἰς ἀποδημίας μὴ μεταστρέφεσθαι, καὶ τοῖς μὲν οὐρανίοις περισσά, θύειν, ἄρτια δὲ τοῖς χθονίοις, ὧν ἑκάστου τὴν διάνοιαν ἀπεκρύπτοντο πρὸς τοὺς πολλούς, οὕτως ἔνια τῶν Νομᾶ πατρίων ἀπόρρητον ἔχει τὸν λόγον οἷον τὸ μὴ σπένδειν θεοῖς ἐξ ἀμπέλων ἀτμήτων μηδὲ θύειν ἄτερ ἀλφίτων καὶ τὸ προσκυνεῖν περιστρεφομένους καὶ τὸ καθῆσθαι προσκυνήσαντας. τὰ μὲν οὖν πρῶτα δύο τὴν γῆς ἐξημέρωσιν ἔοικε διδάσκειν, ὡς μόριον εὐσεβείας οὖσαν ἡ δὲ περιστροφὴ τῶν προσκυνούντων λέγεται μὲν ἀπομίμησις εἶναι τῆς τοῦ κόσμου περιφορᾶς, δόξειε δ’ ἂν μᾶλλον ὁ προσκυνῶν, ἐπεὶ πρὸς ἕω τῶν ἱερῶν βλεπόντων ἀπέστραπται τὰς ἀνατολάς, μεταβάλλειν ἑαυτὸν ἐνταῦθα καὶ περιστρέφειν ἐπὶ τὸν θεόν, κύκλον ποιῶν καὶ συνάπτων τὴν ἐπιτελείωσιν τῆς εὐχῆς δι’ ἀμφοῖν· εἰ μὴ νὴ Δία τοῖς Αἰγυπτίοις τροχοῖς αἰνίττεταί τι καὶ διδάσκει παραπλήσιον ἡ μεταβολὴ τοῦ σχήματος, ὡς οὐδενὸς ἑστῶτος τῶν ἀνθρωπίνων, ἀλλ’ ὅπως ἂν στρέφῃ καὶ ἀνελίττῃ τὸν βίον ἡμῶν ὁ θεός, ἀγαπᾶν καὶ δέχεσθαι προσῆκον, τὸ δὲ καθέζεσθαι προσκυνήσαντας οἰωνισμὸν εἶναι λέγουσι τοῦ βεβαιότητα ταῖς εὐχαῖς καὶ διαμονὴν τοῖς ἀγαθοῖς ἐπιγίνεσθαι. λέγουσι δὲ καὶ πράξεων διορισμὸν εἶναι τὴν ἀνάπαυσιν· ὡς οὖν τῇ προτέρᾳ, πράξει πέρας ἐπιτιθέντας καθέζεσθαι παρὰ τοῖς θεοῖς, ἵνα ἑτέρας πάλιν ἀρχὴν παρ’ ἐκείνων λάβωσι. δύναται δὲ καὶ τοῦτο τοῖς εἰρημένοις ὁμολογεῖν, ἐθίζοντος ἡμᾶς τοῦ νομοθέτου μὴ ποιεῖσθαι τὰς πρὸς τὸ θεῖον ἐντεύξεις ἐν ἀσχολίᾳ, καὶ παρέργως οἷον σπεύδοντας, ἀλλ’ ὅταν χρόνον ἔχωμεν καὶ σχολὴν ἄγωμεν.", "st": "Num. 14.3"}, {"sp": "N", "t": "ἐκ δὲ τῆς τοιαύτης παιδαγωγίας πρὸς τὸ θεῖον οὕτως ἡ πόλις ἐγεγόνει χειροήθης καὶ κατατεθαμβημένη τὴν τοῦ Νομᾶ δύναμιν, ὥστε μύθοις ἐοικότας τὴν ἀτοπίαν λόγους παραδέχεσθαι, καὶ νομίζειν μηδὲν ἄπιστον εἶναι μηδὲ ἀμήχανον ἐκείνου. βουληθέντος. λέγεται γοῦν ποτε καλέσας ἐπὶ τὴν τράπεζαν οὐκ ὀλίγους τῶν πολιτῶν, σκεύη τε φαῦλα καὶ δεῖπνον εὐτελὲς πάνυ προθέσθαι καὶ δημοτικὸν ἀρξαμένων δὲ δειπνεῖν ἐμβαλὼν λόγον ὡς ἡ θεὸς ᾗ σύνεστιν ἥκοι πρὸς αὐτόν, αἰφνίδιον ἐπιδεῖξαι τόν τε οἶκον ἐκπωμάτων πλήρη πολυτελῶν καὶ τὰς τραπέζας ὄψων τε παντοδαπῶν καὶ παρασκευῆς δαψιλοῦς γεμούσας. πᾶσαν δὲ ὑπερβέβληκεν ἀτοπίαν τὸ ὑπὲρ τῆς τοῦ Διὸς ὁμιλίας ἱστορούμενον. μυθολογοῦσι γάρ εἰς τὸν Ἀβεντῖνον λόφον οὔπω μέρος ὄντα τῆς πόλεως οὐδὲ συνοικούμενον, ἀλλ’ ἔχοντα πηγάς τε δαψιλεῖς ἐν αὑτῷ καὶ νάπας σκιεράς, φοιτᾶν δύο δαίμονάς, Πῖκον καὶ Φαῦνον οὓς τὰ μὲν ἄλλα Σατύρων ἄν τις ἢ Πανῶν γένει προσεικάσειε, δυνάμει δὲ φαρμάκων καὶ δεινότητι τῆς περὶ τὰ θεῖα γοητείας λέγονται ταὐτὰ τοῖς ὑφ’ Ἑλλήνων προσαγορευθεῖσιν Ἰδαίοις Δακτύλοις σοφιζόμενοι περιϊέναι τὴν Ἰταλίαν. τούτους φασὶ χειρώσασθαι τὸν Νομᾶν, οἴνῳ καὶ μέλιτι κεράσαντα τὴν κρήνην ἀφ’ ἧς ἔπινον συνήθως. ληφθέντας δὲ πολλὰς μὲν ἰδέας τρέπεσθαι καὶ μετεκδύεσθαι τὴν αὑτῶν φύσιν, ἀλλόκοτα φάσματα καὶ φοβερὰ τῆς ὄψεως προβαλλομένους· ἐπεὶ δὲ ἔγνωσαν ἑαλωκότες ἰσχυρὰν καὶ ἄφυκτον ἅλωσιν, ἄλλα τε προθεσπίσαι πολλὰ τῶν μελλόντων καὶ τὸν ἐπὶ τοῖς κεραυνοῖς ἐκδιδάξαι καθαρμόν, ὃς ποιεῖται μέχρι νῦν διὰ κρομμύων καὶ τριχῶν καὶ μαινίδων. ἔνιοι δὲ οὐ τοὺς δαίμονάς φασὶν ὑποθέσθαι τὸν καθαρμόν, ἀλλ’ ἐκείνους μὲν καταγαγεῖν τὸν Δία μαγεύσαντας, τὸν δὲ θεὸν ὀργιζόμενον τῷ Νομᾷ προστάσσειν ὡς χρὴ γενέσθαι τὸν καθαρμὸν κεφαλαῖς· ὑπολαβόντος δὲ τοῦ Νομᾶ, κρομμύων; εἰπεῖν, ἀνθρώπων τὸν δὲ αὖθις ἐκτρέποντα τὸ τοῦ προστάγματος δεινὸν ἐπερέσθαι, θριξίν; ἀποκριναμένου δὲ τοῦ Διός, ἐμψύχοις, ἐπαγαγεῖν τὸν Νομᾶν, μαινίσι; ταῦτα λέγειν ὑπὸ τῆς Ἠγερίας δεδιδαγμένον. καὶ τὸν μὲν θεὸν ἀπελθεῖν ἵλεω γενόμενον, τὸν δὲ τόπον Ἰλίκιον ἀπ’ ἐκείνου προσαγορευθῆναι καὶ τὸν καθαρμὸν οὕτω συντελεῖσθαι. ταῦτα μὲν οὖν τὰ μυθώδη καὶ γελοῖα τὴν τῶν τότε ἀνθρώπων ἐπιδείκνυται διάθεσιν πρὸς τὸ θεῖον, ἣν ὁ ἐθισμὸς αὐτοῖς ἐνεποίησεν. αὐτὸν δὲ τὸν Νομᾶν οὕτω φασὶν εἰς τὸ θεῖον ἀνηρτῆσθαι ταῖς ἐλπίσιν, ὥστε καὶ προσαγγελίας αὐτῷ ποτε γενομένης ὡς ἐπέρχονται πολέμιοι, μειδιᾶσαι καὶ εἰπεῖν· ἐγὼ δὲ θύω.", "st": "Num. 15.1"}, {"sp": "N", "t": "πρῶτον δέ φασι καὶ Πίστεως καὶ Τέρμονος ἱερὸν ἱδρύσασθαι. καὶ τὴν μὲν Πίστιν ὅρκον ἀποδεῖξαι Ῥωμαίοις μέγιστον, ᾧ χρώμενοι μέχρι νῦν διατελοῦσιν· ὁ δὲ Τέρμων ὅρος ἄν τις εἴη, καὶ θύουσιν αὐτῷ δημοσίᾳ καὶ ἰδίᾳ κατὰ τοὺς τῶν ἀγρῶν περιορισμούς, νῦν μὲν ἔμψυχα, τὸ παλαιὸν δὲ ἀναίμακτος ἦν ἡ θυσία, Νομᾶ φιλοσοφήσαντος ὡς χρὴ τὸν ὅριον θεὸν εἰρήνης φύλακα καὶ δικαιοσύνης μάρτυν ὄντα φόνου καθαρὸν εἶναι. δοκεῖ δὲ καὶ ὅλως οὗτος ὁρίσαι τὴν χώραν ὁ βασιλεύς, Ῥωμύλου μὴ βουληθέντος ἐξομολογήσασθαι τῷ μέτρῳ τοῦ οἰκείου τὴν ἀφαίρεσιν τοῦ ἀλλοτρίου· δεσμὸν γάρ εἶναι τῆς δυνάμεως τὸν ὅρον, ἂν φυλάττηται, μὴ φυλαττόμενον δὲ τῆς ἀδικίας ἔλεγχον. οὐ μὴν οὐδὲ ἦν δαψιλὴς χώρᾳ τῇ πόλει κατ’ ἀρχάς, ἀλλὰ τὴν πολλὴν αἰχμῇ προσεκτήσατο Ῥωμύλος· καὶ ταύτην πᾶσαν ὁ Νομᾶς διένειμε τοῖς ἀπόροις τῶν πολιτῶν, ὡς ἀνάγκην τῆς ἀδικίας ἀφαιρῶν τὴν ἀπορίαν, καὶ τρέπων ἐπὶ γεωργίαν τὸν δῆμον ἅμα τῇ χώρᾳ συνεξημερούμενον. οὐδὲν γάρ ἄλλο τῶν ἐπιτηδευμάτων οὕτως ἔρωτα δριμὺν εἰρήνης ἐργάζεται καὶ ταχὺν ὡς ὁ ἀπὸ γῆς βίος, ἐν ᾧ καὶ τῆς πολεμικῆς εὐτολμίας τὸ μὲν ὑπερμαχητικὸν τοῦ οἰκείου διαμένει καὶ πάρεστι, τὸ δὲ εἰς ἀδικίαν καὶ πλεονεξίαν ἀνειμένον ἐκκέκοπται. διὸ καὶ τὴν γεωργίαν ὁ Νομᾶς οἷον εἰρήνης φίλτρον ἐμμίξας τοῖς πολίταις καὶ μᾶλλον ὡς ἠθοποιὸν ἢ πλουτοποιὸν ἀγαπήσας τέχνην, εἰς μέρη τὴν χώραν διεῖλεν, ἃ πάγους προσηγόρευσε, καὶ καθ’ ἕκαστον ἐπισκόπους ἔταξε καὶ περιπόλους, ἔστι δ’ ὅτε καὶ αὐτὸς ἐφορῶν καὶ τεκμαιρόμενος ἀπὸ τῶν ἔργων τοὺς τρόπους τῶν πολιτῶν τοὺς μὲν εἰς τιμὰς καὶ πίστεις ἀνῆγε, τοὺς δὲ ῥᾳθύμους καὶ ἀμελεῖς ψέγων καὶ κακίζων ἐσωφρόνιζε.", "st": "Num. 16.1"}, {"sp": "N", "t": "τῶν δὲ ἄλλων αὐτοῦ πολιτευμάτων ἡ κατὰ τέχνας διανομὴ τοῦ πλήθους μάλιστα θαυμάζεται, τῆς γάρ πόλεως ἐκ δυεῖν γενῶν, ὥσπερ εἴρηται, συνεστάναι δοκούσης, διεστώσης δὲ μᾶλλον καὶ μηδενὶ τρόπῳ μιᾶς γενέσθαι βουλομένης μηδὲ οἷον ἐξαλεῖψαι τὴν ἑτερότητα καὶ διαφοράν, ἀλλὰ συγκρούσεις ἀπαύστους καὶ φιλονεικίας τῶν μερῶν ἐχούσης, διανοηθεὶς ὅτι καὶ τῶν σωμάτων τὰ φύσει δύσμικτα καὶ σκληρὰ καταθραύοντες καὶ διαιροῦντες ἀναμιγνύουσιν, ὑπὸ μικρότητος ἀλλήλοις συμβαίνοντα μᾶλλον, ἔγνω κατατεμεῖν τομὰς πλείονας τὸ σύμπαν πλῆθος ἐκ δὲ τούτων εἰς ἑτέρας ἐμβαλὼν διαφορὰς τὴν πρώτην ἐκείνην καὶ μεγάλην ἀφανίσαι ταῖς ἐλάττοσιν ἐνδιασπαρεῖσαν. ἦν δὲ ἡ διανομὴ κατὰ τὰς τέχνας, αὐλητῶν, χρυσοχόων, τεκτόνων, βαφέων, σκυτοτόμων, σκυτοδεψῶν, χαλκέων, κεραμέων, τὰς δὲ λοιπὰς τέχνας εἰς ταὐτὸ συναγαγὼν ἓν αὐτῶν ἐκ πασῶν ἀπέδειξε σύστημα. κοινωνίας δὲ καὶ συνόδους καὶ θεῶν τιμὰς ἀποδοὺς ἑκάστῳ γένει πρεπούσας, τότε πρῶτον ἐκ τῆς πόλεως ἀνεῖλε τὸ λέγεσθαι καὶ νομίζεσθαι τοὺς μὲν Σαβίνους, τοὺς δὲ Ῥωμαίους, καὶ τοὺς μὲν Τατίου, τοὺς δὲ Ῥωμύλου πολίτας, ὥστε τὴν διαίρεσιν εὐαρμοστίαν καὶ ἀνάμιξιν πάντων γενέσθαι πρὸς πάντας.", "st": "Num. 17.1"}, {"sp": "N", "t": "ἐπαινεῖται δὲ τῶν πολιτικῶν αὐτοῦ καὶ τὸ περὶ τὸν νόμον διόρθωμα τὸν διδόντα τοῖς πατράσι τοὺς παῖδας πιπράσκειν, ὑπεξελομένου τοὺς γεγαμηκότας, εἰ τοῦ πατρὸς ἐπαινοῦντος καὶ κελεύοντος ὁ γάμος γένοιτο, δεινὸν γὰρ ἡγεῖτο τὴν ὡς ἐλευθέρῳ γεγαμημένην γυναῖκα δούλῳ συνοικεῖν.", "st": "Num. 17.4"}, {"sp": "N", "t": "ἥψατο δὲ καὶ τῆς περὶ τὸν οὐρανὸν πραγματείας οὔτε ἀκριβῶς οὔτε παντάπασιν ἀθεωρήτως. Ῥωμύλου γὰρ βασιλεύοντος ἀλόγως ἐχρῶντο τοῖς μησὶ καὶ ἀτάκτως, τοὺς μὲν οὐδὲ εἴκοσιν ἡμερῶν, τοὺς δὲ πέντε καὶ τριάκοντα, τοὺς δὲ πλειόνων λογιζόμενοι, τῆς δὲ γινομένης ἀνωμαλίας περὶ τὴν σελήνην καὶ τὸν ἥλιον ἔννοιαν οὐκ ἔχοντες, ἀλλ’ ἓν φυλάττοντες μόνον, ὅπως ἑξήκοντα καὶ τριακοσίων ἡμερῶν ὁ ἐνιαυτὸς ἔσται. Νομᾶς δὲ τὸ παράλλαγμα τῆς ἀνωμαλίας ἡμερῶν ἕνδεκα γίνεσθαι λογιζόμενος, ὡς τοῦ μὲν σεληνιακοῦ τριακοσίας πεντήκοντα τέσσαρας ἔχοντος ἡμέρας, τοῦ δὲ ἡλιακοῦ τριακοσίας ἑξήκοντα πέντε, τὰς ἕνδεκα ταύτας ἡμέρας διπλασιάζων ἐπήγαγε παρ’ ἐνιαυτὸν ἐπὶ τῷ Φεβρουαρίῳ μηνὶ τὸν ἐμβόλιμον, ὑπὸ Ῥωμαίων Μερκηδῖνον καλούμενον, εἴκοσι καὶ δυοῖν ἡμερῶν ὄντα. καὶ τοῦτο μὲν αὐτῷ τὸ ἴαμα τῆς ἀνωμαλίας μειζόνων ἔμελλεν ἰαμάτων δεήσεσθαι.", "st": "Num. 18.1"}, {"sp": "N", "t": "μετεκίνησε δὲ καὶ τὴν τάξιν τῶν μηνῶν τὸν γάρ Μάρτιον πρῶτον ὄντα τρίτον ἔταξε, πρῶτον δὲ τὸν Ἰανουάριον, ὃς ἦν ἑνδέκατος ἐπὶ Ῥωμύλου, δωδέκατος δὲ καὶ τελευταῖος ὁ Φεβρουάριος, ᾧ νῦν δευτέρῳ χρῶνται. πολλοὶ δέ εἰσιν οἳ καὶ προστεθῆναι τούτους ὑπὸ Νομᾶ τοὺς μῆνας λέγουσι, τόν τε Ἰανουάριον καὶ τὸν Φεβρουάριον, ἐξ ἀρχῆς δὲ χρῆσθαι δέκα μόνον εἰς τὸν ἐνιαυτόν, ὡς ἔνιοι τῶν βαρβάρων τρισί, καὶ τῶν Ἑλλήνων Ἀρκάδες μὲν τέσσαρσιν, ἓξ δὲ Ἀκαρνᾶνες, Αἰγυπτίοις δὲ μηνιαῖος ἦν ὁ ἐνιαυτός, εἶτα τετράμηνος, ὥς φασι. διὸ καὶ νεωτάτην χώραν οἰκοῦντες ἀρχαιότατοι δοκοῦσιν εἶναι καὶ πλῆθος ἀμήχανον ἐτῶν ἐπὶ ταῖς γενεαλογίαις καταφέρουσιν, ἅτε δὴ τοὺς μῆνας εἰς ἐτῶν ἀριθμὸν τιθέμενοι.", "st": "Num. 18.4"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ ὅτι μὲν δέκα μῆνας εἰς τὸν ἐνιαυτὸν ἔταττον, οὐ δώδεκα, τεκμήριον ἡ τοῦ τελευταίου προσηγορία· δέκατον γάρ αὐτὸν ἄχρι νῦν καλοῦσιν ὅτι δὲ τὸν Μάρτιον πρῶτον, ἡ τάξις· τὸν γάρ ἀπ’ ἐκείνου πέμπτον ἐκάλουν πέμπτον ἕκτον δὲ τὸν ἕκτον καὶ τῶν ἄλλων ἑξῆς ὁμοίως ἕκαστον, ἐπεὶ τὸν Ἰανουάριον καὶ τὸν Φεβρουάριον πρὸ τοῦ Μαρτίου τιθεμένοις συνέβαινεν αὐτοῖς τὸν εἰρημένον μῆνα πέμπτον μὲν ὀνομάζειν, ἕβδομον δὲ ἀριθμεῖν. ἄλλως δὲ καὶ λόγον εἶχε τὸν Μάρτιον Ἄρει καθιερωμένον ὑπὸ τοῦ Ῥωμύλου πρῶτον ὀνομάζεσθαι· δεύτερον δὲ τὸν Ἀπρίλλιον, ἐπώνυμον ὄντα τῆς Ἀφροδίτης, ἐν ᾧ θύουσί τε τῇ θεῷ καὶ ταῖς καλάνδαις αἱ γυναῖκες ἐστεφανωμέναι μυρσίνῃ λούονται, τινὲς δὲ οὐ διὰ τὴν Ἀφροδίτην τὸν Ἀπρίλλιόν φασιν, ἀλλ’ ὥσπερ ἔχει τοὔνομα ψιλόν, Ἀπρίλλιον κεκλῆσθαι τὸν μῆνα τῆς ἐαρινῆς ὥρας ἀκμαζούσης ἀνοίγοντα καὶ ἀνακαλύπτοντα τοὺς βλαστοὺς τῶν φυτῶν τοῦτο γὰρ ἡ γλῶττα σημαίνει. τῶν δ’ ἐφεξῆς τὸν μὲν Μάϊον καλοῦσιν ἀπὸ Μαίας· Ἑρμῇ γὰρ ἀνιέρωται τὸν δὲ Ἰούνιον ἀπὸ τῆς Ἥρας. εἰσὶ δέ τινες οἱ τούτους ἡλικίας ἐπωνύμους εἶναι λέγοντες πρεσβυτέρας καὶ νεωτέρας· μαϊώρεις γὰρ οἱ πρεσβύτεροι παρ’ αὐτοῖς, ἰουνιώρεις δὲ οἱ νεώτεροι καλοῦνται, τῶν δὲ λοιπῶν ἕκαστον ἀπὸ τῆς τάξεως, ὥσπερ ἀριθμοῦντες, ὠνόμαζον πέμπτον, ἕκτον, ἕβδομον, ὄγδοον, ἔνατον, δέκατον· εἶτα ὁ πέμπτος ἀπὸ Καίσαρος τοῦ καταγωνισαμένου Πομπήϊον Ἰούλιος· ὁ δὲ ἕκτος Αὔγουστος ἀπὸ τοῦ δευτέρου μὲν ἄρξαντος, Σεβαστοῦ δὲ ἐπικληθέντος, ὠνομάσθη. τοὺς δὲ ἐφεξῆς Δομετιανὸς εἰσεποίησε ταῖς αὑτοῦ προσωνυμίαις οὐ πολὺν χρόνον, ἀλλὰ τὰς αὑτῶν ἀναλαβόντες πάλιν ἐκείνου σφαγέντος ὁ μὲν ἕβδομος, ὁ δὲ ὄγδοος καλοῦνται, μόνοι δ’ οἱ τελευταῖοι δύο τὴν ἀπὸ τῆς τάξεως κλῆσιν, ὥσπερ ἔσχον ἐξ ἀρχῆς, διεφύλαξαν.", "st": "Num. 19.1"}, {"sp": "N", "t": "τῶν δὲ ὑπὸ Νομᾶ προστεθέντων ἢ μετατεθέντων ὁ μὲν Φεβρουάριος οἷον καθάρσιος ἄν τις εἴη· καὶ γάρ ἡ λέξις ἔγγιστα τοῦτο σημαίνει, καὶ τοῖς φθιτοῖς ἐναγίζουσι τότε καὶ τὴν τῶν Λουπερκαλίων ἑορτὴν εἰς τὰ πολλὰ καθαρμῷ προσεοικυῖαν τελοῦσιν ὁ δὲ πρῶτος Ἰανουάριος ἀπὸ τοῦ Ἰανοῦ, δοκεῖ δέ μοι τὸν Μάρτιον ὁ Νομᾶς ἐπώνυμον ὄντα τοῦ Ἄρεως ἐκ τῆς προεδρίας μεταστῆσαι, βουλόμενος ἐν παντὶ τῆς πολεμικῆς δυνάμεως προτιμᾶσθαι τὴν πολιτικήν. ὁ γὰρ Ἰανὸς ἐν τοῖς πάνυ παλαιοῖς εἴτε δαίμων εἴτε βασιλεὺς γενόμενος πολιτικὸς καὶ κοινωνικὸς ἐκ τοῦ θηριώδους καὶ ἀγρίου λέγεται μεταβαλεῖν τὴν δίαιταν. καὶ διὰ τοῦτο πλάττουσιν αὐτὸν ἀμφιπρόσωπον, ὡς ἑτέραν ἐξ ἑτέρας τῷ βίῳ περιποιήσαντα τὴν μορφὴν καὶ διάθεσιν.", "st": "Num. 19.5"}, {"sp": "N", "t": "ἔστι δὲ αὐτοῦ καὶ νεὼς ἐν Ῥώμῃ δίθυρος, ὃν πολέμου πύλην καλοῦσι. νομίζεται γάρ ἀνεῷχθαι μὲν αὐτὸν ὅταν ᾖ πόλεμος, κεκλεῖσθαι δὲ εἰρήνης γενομένης, ὃ δὴ χαλεπὸν ἦν καὶ σπανίως γινόμενον, ἀεί τινι συνηρτημένης πολέμῳ τῆς ἡγεμονίας, διὰ μέγεθος τοῖς κύκλῳ περικεχυμένοις γένεσι βαρβάροις ἀντερειδούσης. πλὴν ἐπί γε τοῦ Σεβαστοῦ Καίσαρος ἐκλείσθη καθελόντος Ἀντώνιον καὶ πρότερον ὑπατευόντων Μάρκου Ἀτιλίου καὶ Τίτου Μαλλίου χρόνον οὐ πολὺν εἶτα εὐθὺς ἀνεῴχθη πολέμου συρραγέντος. ἀλλ’ ἐπί γε τῆς Νομᾶ βασιλείας οὐδεμίαν ἡμέραν ἀνεῳγμένος ὤφθη, τρία δὲ καὶ τετταράκοντα ἔτη συνεχῶς ἔμεινε κεκλεισμένος· οὕτως ἐξῄρητο παντελῶς τὰ τοῦ πολέμου καὶ πανταχόθεν. οὐ γάρ μόνον ὁ Ῥωμαίων ἡμέρωτο καὶ κατεκεκήλητο τῇ δικαιοσύνῃ καὶ πρᾳότητι τοῦ βασιλέως δῆμος, ἀλλὰ καὶ τὰς κύκλῳ πόλεις, ὥσπερ αὔρας τινὸς ἐκεῖθεν ἢ πνεύματος ὑγιεινοῦ φέροντος, ἀρχὴ μεταβολῆς ἔλαβε καὶ πόθος εἰσερρύη πάντας εὐνομίας καὶ εἰρήνης καὶ γῆν φυτεύειν καὶ τέκνα τρέφειν ἐν ἡσυχίᾳ καὶ σέβεσθαι θεούς. ἑορταὶ δὲ καὶ θαλίαι καὶ παρ’ ἀλλήλους ἀδεῶς ἰόντων καὶ ἀναμιγνυμένων ὑποδοχαὶ καὶ φιλοφροσύναι τὴν Ἰταλίαν κατεῖχον, οἷον ἐκ πηγῆς τῆς Νομᾶ σοφίας τῶν καλῶν καὶ δικαίων ἐπεισρεόντων εἰς ἅπαντας καὶ διαχεομένης τῆς περὶ ἐκεῖνον γαλήνης·", "st": "Num. 20.1"}, {"sp": "N", "t": "ὥστε καὶ τὰς ποιητικὰς ὑπερβολὰς ἐνδεῖν πρὸς τὴν τότε κατάστασιν λέγουσιν· ἐν δὲ σιδαροδέτοις πόρπαξιν αἰθᾶν ἀραχνᾶν ἔργα· καί, εὐρὼς δάμναται ἔγχεά τε λογχωτὰ ξίφεά τ’ ἀμφήκεα, χαλκεᾶν δὲ οὐκέτι σαλπίγγων κτύπος, οὐδὲ συλᾶται μελίφρων ὕπνος ἀπὸ βλεφάρων. οὔτε γάρ πόλεμος οὔτε στάσις οὔτε νεωτερισμὸς περὶ πολιτείαν ἱστόρηται Νομᾶ βασιλεύοντος· οὐ μὴν οὐδ’ ἐπ’ αὐτὸν ἐκεῖνον ἔχθρα τις ἢ φθόνος ἢ δι’ ἔρωτα βασιλείας ἐπιβουλὴ καὶ σύστασις ἀνδρῶν, ἀλλ’ εἴτε φόβος θεῶν προκήδεσθαι δοκούντων τοῦ ἀνδρὸς εἴτε τῆς ἀρετῆς αἰδὼς εἴτε δαιμόνιος τύχη, πάσης κακίας ἄθικτον ἐπ’ ἐκείνου καὶ καθαρὸν διαφυλάττουσα τὸν βίον, ἐναργὲς ἐξήνεγκε παράδειγμα καὶ τεκμήριον τῆς Πλατωνικῆς φωνῆς, ἣν ὕστερον ἐκεῖνος οὐκ ὀλίγοις χρόνοις γενόμενος ἐτόλμησεν ἀφεῖναι περὶ πολιτείας, ὡς μία κακῶν παῦλα καὶ λύσις ἀνθρώποις ἐστίν, ἔκ τινος τύχης θείας εἰς ταὐτὸ διανοίᾳ φιλοσόφῳ βασιλικὴν συμπεσοῦσαν δύναμιν ἐγκρατῆ καὶ ὑπερδέξιον τῆς κακίας τὴν ἀρετὴν καταστῆσαι.", "st": "Num. 20.5"}, {"sp": "N", "t": "μακάριος μὲν γὰρ αὐτός ὁ σώφρων ὡς ἀληθῶς, μακάριοι δὲ οἱ συνήκοοι τῶν ἔκ τοῦ σωφρονοῦντος στόματος ἰόντων λόγων. τάχα γὰρ οὐδὲ ἀνάγκης τινὸς δεῖ πρὸς τοὺς πολλοὺς οὐδὲ ἀπειλῆς, αὐτοὶ δὲ τὴν ἀρετὴν ἐν εὐδήλῳ παραδείγματι καὶ λαμπρῷ τῷ βίῳ τοῦ ἄρχοντος ὁρῶντες, ἑκουσίως σωφρονοῦσι καὶ συμμετασχηματίζονται πρὸς τὸν ἐν φιλίᾳ καὶ ὁμονοίᾳ τῇ πρὸς αὐτοὺς μετὰ δικαιοσύνης καὶ μετριότητος ἀμύμονα καὶ μακάριον βίον, ἐν ᾧ τὸ κάλλιστον ἁπάσης πολιτείας τέλος ἐστί, καὶ βασιλικώτατος ἁπάντων ὁ τοῦτον τὸν βίον καὶ ταύτην τὴν διάθεσιν τοῖς ὑπηκόοις ἐνεργάσασθαι δυνάμενος. ταῦτα μὲν οὖν Νομᾶς παντὸς μᾶλλον φαίνεται συνεωρακώς.", "st": "Num. 20.8"}, {"sp": "N", "t": "περὶ δὲ παίδων αὐτοῦ καὶ γάμων ἀντιλογίαι γεγόνασι τοῖς ἱστορικοῖς. οἱ μὲν γὰρ οὔτε γάμον ἄλλον ἢ τὸν Τατίας λαβεῖν αὐτὸν οὔτε παιδὸς ἑτέρου γενέσθαι πατέρα πλὴν μιᾶς θυγατρὸς Πομπιλίας λέγουσιν· οἱ δὲ πρὸς ταύτῃ τέσσαρας υἱοὺς ἀναγράφουσιν αὐτοῦ, Πόμπωνα, Πῖνον, Κάλπον, Μάμερκον, ὧν ἕκαστον οἴκου διαδοχὴν καὶ γένους ἐντίμου καταλιπεῖν. εἶναι γάρ ἀπὸ μὲν τοῦ Πόμπωνος τοὺς Πομπωνίους, ἀπὸ δὲ Πίνου τοὺς Πιναρίους, ἀπὸ δὲ Κάλπου τοὺς Καλπουρνίους, ἀπὸ δὲ Μαμέρκου τοὺς Μαμερκίους, οἷς διὰ τοῦτο καὶ Ῥῆγας γενέσθαι παρωνύμιον, ὅπερ ἐστὶ βασιλέας, τρίτοι δέ εἰσιν οἱ τούτων μὲν κατηγοροῦντες ὡς χαριζομένων τοῖς γένεσι καὶ προστιθέντων οὐκ ἀληθῆ στέμματα τῆς ἀπὸ Νομᾶ διαδοχῆς, τὴν δὲ Πομπιλίαν οὐκ ἐκ Τατίας γεγονέναι λέγοντες, ἀλλ’ ἐξ ἑτέρας γυναικός, ἣν ἤδη βασιλεύων ἔγημε, Λουκρητίας· πάντες δ’ οὖν ὁμολογοῦσι τὴν Πομπιλίαν Μαρκίῳ γαμηθῆναι. παῖς δὲ ἦν ὁ Μάρκιος ἐκείνου Μαρκίου τοῦ Νομᾶν παρορμήσαντος ἐπὶ τὴν βασιλείαν καὶ γὰρ συμμετῴκησεν εἰς Ῥώμην αὐτῷ καὶ τῆς συγκλήτου μετέσχε τιμώμενος, καὶ μετὰ τὴν Νομᾶ τελευτὴν Ὁστιλίῳ περὶ τῆς βασιλείας εἰς ἀγῶνα καταστὰς καὶ ἡττηθεὶς ἀπεκαρτέρησεν. ὁ δὲ υἱὸς αὐτοῦ Μάρκιος ἔχων τὴν Πομπιλίαν κατέμεινεν ἐν Ῥώμῃ καὶ Μάρκιον Ἄγκον ἐγέννησεν, ὃς μετὰ Τύλλον Ὁστίλιον ἐβασίλευσε. τοῦτον, ὡς λέγεται, πενταετῆ καταλιπὼν ὁ Νομᾶς ἐτελεύτησεν, οὐ ταχείας οὐδ’ αἰφνιδίου γενομένης αὐτῷ τῆς τελευτῆς, ἀλλὰ κατὰ μικρὸν ὑπὸ γήρως καὶ νόσου μαλακῆς ἀπομαραινόμενος, ὡς ἱστόρηκε Πείσων. ἐτελεύτησε δὲ χρόνον οὐ πολὺν τοῖς ὀγδοήκοντα προσβιώσας.", "st": "Num. 21.1"}, {"sp": "N", "t": "ζηλωτὸν δὲ αὐτοῦ καὶ τῷ τάφῳ τὸν βίον ἐποίησαν οἵ τε σύμμαχοι καὶ φίλοι δῆμοι, συνελθόντες ἐπὶ τὰς ταφὰς ἅμα δημοσίαις ἐπιφοραῖς καὶ στεφάνοις, οἵ τε πατρίκιοι τὸ λέχος ἀράμενοι, καὶ συμπαρόντες οἱ τῶν θεῶν ἱερεῖς καὶ παραπέμποντες, ὁ δ’ ἄλλος ὅμιλος ἀναμεμιγμένων καὶ γυναικῶν καὶ παίδων οὐχ ὡς βασιλέως ταφαῖς γηραιοῦ παρόντες, ἀλλ’ ὥς τινα τῶν φιλτάτων ἕκαστος ἐν ἀκμῇ βίου ποθούμενον θάπτων, μετ’ οἰμωγῆς καὶ κλαυθμῶν ἑπόμενοι. πυρὶ μὲν οὖν οὐκ ἔδοσαν τὸν νεκρὸν αὐτοῦ κωλύσαντος, ὡς λέγεται, δύο δὲ ποιησάμενοι λιθίνας σοροὺς ὑπὸ τὸ Ἰάνοκλον ἔθηκαν, τὴν μὲν ἑτέραν ἔχουσαν τὸ σῶμα, τὴν δὲ ἑτέραν τὰς ἱερὰς βίβλους ἃς ἐγράψατο μὲν αὐτός, ὥσπερ οἱ τῶν Ἑλλήνων νομοθέται τοὺς κύρβεις, ἐκδιδάξας δὲ τοὺς ἱερεῖς ἔτι ζῶν τὰ γεγραμμένα καὶ πάντων ἕξιν τε καὶ γνώμην ἐνεργασάμενος αὐτοῖς, ἐκέλευσε συνταφῆναι μετὰ τοῦ σώματος, ὡς οὐ καλῶς ἐν ἀψύχοις γράμμασι φρουρουμένων τῶν ἀπορρήτων. ᾧ λογισμῷ φασι μηδὲ τοὺς Πυθαγορικοὺς εἰς γραφὴν κατατίθεσθαι τὰ συντάγματα, μνήμην δὲ καὶ παίδευσιν αὐτῶν ἄγραφον ἐμποιεῖν τοῖς ἀξίοις. καὶ τῆς γε περὶ τὰς ἀπόρους καὶ ἀρρήτους λεγομένας ἐν γεωμετρίᾳ μεθόδους πραγματείας πρός τινα τῶν ἀναξίων ἐκδοθείσης, ἔφασαν ἐπισημαίνειν τὸ δαιμόνιον μεγάλῳ τινὶ καὶ κοινῷ κακῷ τὴν γεγενημένην παρανομίαν καὶ ἀσέβειαν ἐπεξερχόμενον. ὥστε συγγνώμην ἔχειν πολλὴν τοῖς εἰς τὸ αὐτὸ Πυθαγόρᾳ Νομᾶν φιλοτιμουμένοις συνάγειν ἐπὶ τοσαύταις ὁμοιότησιν.", "st": "Num. 22.1"}, {"sp": "N", "t": "οἱ δὲ περὶ Ἀντίαν ἱστοροῦσι δώδεκα μὲν εἶναι βίβλους ἱεροφαντικάς, δώδεκα δὲ ἄλλας Ἑλληνικὰς φιλοσόφους τὰς εἰς τὴν σορὸν συντεθείσας. τετρακοσίων δέ που διαγενομένων ἐτῶν ὕπατοι μὲν ἦσαν Πόπλιος Κορνήλιος καὶ Μάρκος Βαίβιος· ὄμβρων δὲ μεγάλων ἐπιπεσόντων καὶ χώματος περιρραγέντος ἐξέωσε τὰς σοροὺς τὸ ῥεῦμα· καὶ τῶν ἐπιθημάτων ἀποπεσόντων ἡ μὲν ἑτέρᾳ κενὴ παντάπασιν ὤφθη καὶ μέρος οὐδὲν οὐδὲ λείψανον ἔχουσα τοῦ σώματος, ἐν δὲ τῇ ἑτέρᾳ τῶν γραμμάτων εὑρεθέντων ἀναγνῶναι μὲν αὐτὰ λέγεται Πετίλιος στρατηγῶν τότε, πρὸς δὲ τὴν σύγκλητον κομίσαι, μὴ δοκεῖν αὐτῷ θεμιτὸν εἶναι λέγων μηδὲ ὅσιον ἔκπυστα πολλοῖς τὰ γεγραμμένα γενέσθαι· διὸ καὶ κομισθείσας εἰς τὸ Κομίτιον τὰς βίβλους κατακαῆναι.", "st": "Num. 22.5"}, {"sp": "N", "t": "πᾶσι μὲν οὖν ἕπεται τοῖς δικαίοις καὶ ἀγαθοῖς ἀνδράσι μείζων ὁ κατόπιν καὶ μετὰ τὴν τελευτὴν ἔπαινος, τοῦ φθόνου πολὺν χρόνον οὐκ ἐπιζῶντος, ἐν ίων δὲ καὶ προαποθνήσκοντος· οὐ μὴν ἀλλ’ ἐκείνου γε τὴν δόξαν αἱ τῶν ὕστερον βασιλέων τύχαι λαμπροτέραν ἐποίησαν, πέντε γάρ γενομένων μετ’ αὐτὸν ὁ μὲν ἔσχατος ἐκπεσὼν τῆς ἀρχῆς ἐν φυγῇ κατεγήρασε, τῶν δὲ τεσσάρων οὐδεὶς κατὰ φύσιν ἐτελεύτησεν, ἀλλ’ οἱ μὲν τρεῖς ἐπιβουλευθέντες ἐσφάγησαν, Ὁστίλιος δὲ Τύλλος, ὃς μετὰ Νομᾶν ἐβασίλευσε, καὶ τὰ πλεῖστα τῶν ἐκείνου καλῶν, ἐν δὲ πρώτοις καὶ μάλιστα τὴν περὶ τὸ θεῖον εὐλάβειαν, ἐπιχλευάσας καὶ καθυβρίσας ὡς ἀργοποιὸν καὶ γυναικώδη, πρὸς πόλεμον ν ἔτρεψε τοὺς πολίτας, οὐδ’ αὐτὸς ἐνέμεινε τοῖς νεανιεύμασι τούτοις, ἀλλ’ ὑπὸ νόσου χαλεπῆς καὶ πολυτρόπου τὴν γνώμην ἀλλασσόμενος εἰς δεισιδαιμονίαν ἐνέδωκεν οὐδέν τι τῇ κατὰ Νομᾶν εὐσεβείᾳ προσήκουσαν, ἔτι δὲ μᾶλλον ἐνεποίησε τοῖς ἄλλοις τὸ τοιοῦτον πάθος, ὡς λέγεται, καταφλεχθεὶς ὑπὸ κεραυνῶν.", "st": "Num. 22.6"}, {"sp": "HDR", "t": "Λυκούργου καὶ Νομᾶ σύγκρισις"}, {"sp": "N", "t": "ἀλλ’ ἐπεὶ τὸν Νομᾶ καὶ Λυκούργου διεληλύθαμεν βίον, ἐκκειμένων ἀμφοῖν, εἰ καὶ χαλεπὸν ἔργον, οὐκ ἀποκνητέον συναγαγεῖν τὰς διαφοράς, αἱ μὲν γὰρ κοινότητες ἐπιφαίνονται ταῖς πράξεσιν, οἷον ἡ σωφροσύνη τῶν ἀνδρῶν, ἡ εὐσέβεια, τὸ πολιτικόν, τὸ παιδευτικόν, τὸ μίαν ἀρχὴν παρὰ τῶν θεῶν ἀμφοτέρους λαβεῖν τῆς νομοθεσίας· τῶν δὲ ἰδίᾳ ἑκατέρου καλῶν πρῶτόν ἐστι Νομᾷ μὲν ἡ παράληψις τῆς βασιλείας, Λυκούργῳ δὲ ἡ παράδοσις. ὁ μὲν γὰρ οὐκ αἰτῶν ἔλαβεν, ὁ δὲ ἔχων ἀπέδωκε. καὶ τὸν μὲν ἕτεροι κύριον αὑτῶν κατέστησαν ἰδιώτην καὶ ξένον ὄντα, ὁ δὲ αὐτὸς αὑτὸν ἰδιώτην ἐκ βασιλέως ἐποίησε. καλὸν μὲν οὖν τὸ κτήσασθαι δικαιοσύνῃ τὴν βασιλείαν, καλὸν δὲ τὸ προτιμῆσαι τὴν δικαιοσύνην τῆς βασιλείας, ἡ γὰρ ἀρετὴ τὸν μὲν οὕτως ἔνδοξον κατέστησεν ὥστε βασιλείας ἀξιωθῆναι, τὸν δὲ οὕτω μέγαν ἐποίησεν ὥστε βασιλείας καταφρονῆσαι.", "st": "Comp. Lyc.–Num. 1.1"}, {"sp": "N", "t": "δεύτερον τοίνυν, ἐπεὶ καθάπερ ἁρμονικοὶ λύρας, ὁ μὲν ἐκλελυμένην καὶ τρυφῶσαν ἐπέτεινε τὴν Σπάρτην, ὁ δὲ τῆς Ῥώμης τὸ σφοδρὸν ἀνῆκε καὶ σύντονον, ἡ μὲν χαλεπότης τοῦ ἔργου τῷ Λυκούργῳ πρόσεστιν. οὐ γὰρ θώρακας ἐκδῦναι καὶ ξίφη τοὺς πολίτας καταθέσθαι ἔπειθεν, ἀλλὰ χρυσὸν καὶ ἄργυρον ἀφεῖναι καὶ στρωμνὰς ἐκβαλεῖν πολυτελεῖς καὶ τραπέζας, οὐδὲ παυσαμένους πολέμων ἑορτάζειν καὶ θύειν, ἀλλὰ δεῖπνα καὶ πότους ἐάσαντας ἐν τοῖς ὅπλοις καὶ ταῖς παλαίστραις διαπονεῖσθαι καὶ ἀσκεῖν. ὅθεν ὁ μὲν δι’ εὐνοίας καὶ τιμῆς ἅπαντα πείθων ἔπραξεν, ὁ δὲ κινδυνεύων καὶ βαλλόμενος μόγις ἐπεκράτησεν·", "st": "Comp. Lyc.–Num. 1.3"}, {"sp": "N", "t": "ἥμερος μέντοι καὶ φιλάνθρωπος ἡ τοῦ Νομᾶ μοῦσα πρὸς εἰρήνην καὶ δικαιοσύνην μεθαρμοσαμένου καὶ καταπραΰναντος ἐξ ἀκρατῶν καὶ διαπύρων ἠθῶν τοὺς πολίτας. εἰ δὲ καὶ τὸ περὶ τοὺς Εἵλωτας ἀναγκάσει τις ἡμᾶς εἰς τὴν Λυκούργου θέσθαι πολιτείαν, ὠμότατον ἔργον καὶ παρανομώτατον, μακρῷ τινι τὸν Νομᾶν ἑλληνικώτερον γεγονέναι νομοθέτην φήσομεν, ὅς γε καὶ τοὺς ὡμολογημένους δούλους ἔγευσε τιμῆς ἐλευθέρας, ἐν τοῖς Κρονίοις ἑστιᾶσθαι μετὰ τῶν δεσποτῶν ἀναμεμιγμένους ἐθίσας. καὶ γὰρ τοῦτο τῶν Νομᾶ πατρίων ἓν εἶναι λέγουσιν, ἐπὶ τὰς τῶν ἐτησίων ἀπολαύσεις καρπῶν τοὺς συνεργοὺς παραλαμβάνοντος, ἔνιοι δὲ τοῦτο ὑπόμνημα τῆς Κρονικῆς ἐκείνης ἰσονομίας ἀποσώζεσθαι μυθολογοῦσιν, ὡς μηδενὸς δούλου μηδὲ δεσπότου, πάντων δὲ συγγενῶν καὶ ἰσοτίμων νομιζομένων.", "st": "Comp. Lyc.–Num. 1.5"}, {"sp": "N", "t": "ὅλως δὲ φαίνονται πρὸς τὴν αὐτάρκειαν ἀμφότεροι καὶ σωφροσύνην ὁμοίως ἄγοντες τὰ πλήθη, τῶν δὲ ἄλλων ἀρετῶν ὁ μὲν τὴν ἀνδρείαν μᾶλλον, ὁ δὲ τὴν δικαιοσύνην ἠγαπηκώς· εἰ μὴ νὴ Δία διὰ τὴν ὑποκειμένην τῶν πολιτευμάτων ἑκατέρου φύσιν ἢ συνήθειαν, οὐχ ὁμοίαν οὖσαν, ἀνομοίας ἔδει παρασκευῆς. οὔτε γὰρ Νομᾶς διὰ δειλίαν κατέλυσε τὸ πολεμεῖν, ἀλλ’ ἐπὶ τῷ μὴ ἀδικεῖν, οὔτε Λυκοῦργος εἰς ἀδικίαν κατεσκεύασε πολεμικούς, ἀλλ’ ὑπὲρ τοῦ μὴ ἀδικεῖσθαι. τὰς οὖν ὑπερβολὰς ἀφαιροῦντες ἀμφότεροι καὶ τὰς ἐνδείας ἀναπληροῦντες τῶν ὑπαρχόντων περὶ τοὺς πολίτας, ἠναγκάζοντο μεγάλαις χρῆσθαι μεταβολαῖς.", "st": "Comp. Lyc.–Num. 2.1"}, {"sp": "N", "t": "καὶ μὴν τῆς τε διατάξεως καὶ τῆς διαιρέσεως τῶν πολιτευμάτων ὀχλικὴ μὲν ἀκράτως ἡ τὸν Νομᾶ καὶ θεραπευτικὴ τὸν πλήθους, ἐκ χρυσοχόων καὶ αὐλητῶν καὶ σκυτοτόμων συμμιγῆ τινα καὶ παμποίκιλον ἀποφαίνοντος δῆμον, αὐστηρὰ δὲ ἡ Λυκούργειος καὶ ἀριστοκρατική, τὰς μὲν βαναύσους ἀποκαθαίρουσα τέχνας εἰς οἰκετῶν καὶ μετοίκων χεῖρας αὐτοὺς δὲ τοὺς πολίτας εἰς τὴν ἀσπίδα καὶ τὸ δόρυ συνάγουσα, πολέμου χειροτέχνας καὶ θεράποντας Ἄρεως ὄντας, ἄλλο δὲ οὐδὲν εἰδότας οὐδὲ μελετῶντας ἢ πείθεσθαι τοῖς ἄρχουσι καὶ κρατεῖν τῶν πολεμίων. οὐδὲ γὰρ χρηματίζεσθαι τοῖς ἐλευθέροις ἐξῆν, ἵνα ἐλεύθεροι παντελῶς καὶ καθάπαξ ὦσιν, ἀλλ’ ἦν ἡ περὶ τὰ χρήματα κατασκευὴ δεδομένη δούλοις καὶ Εἵλωσιν, ὥσπερ ἡ περὶ τὸ δεῖπνον καὶ ὄψον διακονία. Νομᾶς δὲ οὐδὲν διέκρινε τοιοῦτον, ἀλλὰ τὰς μὲν στρατιωτικὰς ἔπαυσε πλεονεξίας, τὸν δὲ ἄλλον οὐκ ἐκώλυσε χρηματισμόν, οὐδὲ τὴν τοιαύτην κατεστόρεσεν ἀνωμαλίαν, ἀλλὰ καὶ πλούτῳ προϊέναι μέχρι παντὸς ἐφῆκε, καὶ πενίας πολλῆς ἀθροιζομένης καὶ ὑπορρεούσης εἰς τὴν πόλιν ἠμέλησε, δέον εὐθὺς ἐν ἀρχῇ, μηδέπω πολλῆς μηδὲ μεγάλης ἀνισότητος οὔσης, ἀλλ’ ἔτι τοῖς βίοις ὁμαλῶν καὶ παραπλησίων ὄντων, ἐνστῆναι πρὸς τὴν πλεονεξίαν, ὥσπερ Λυκοῦργος, καὶ φυλάξασθαι τὰς ἀπ’ αὐτῆς βλάβας, οὐ μικρὰς γενομένας, ἀλλὰ τῶν πλείστων καὶ μεγίστων κακῶν, ὅσα συνηνέχθη, σπέρμα καὶ ἀρχὴν παρασχούσας. ὁ δὲ τῆς γῆς ἀναδασμὸς οὔτε τὸν Λυκοῦργον, ἐμοὶ δοκεῖν, ποιεῖ ψεκτὸν γενόμενος οὔτε τὸν Νομᾶν μὴ γενόμενος, τῷ μὲν γὰρ ἕδραν καὶ κρηπῖδα τῆς πολιτείας ἡ ἰσότης αὕτη παρέσχε, τὸν δὲ προσφάτου τῆς κληρουχίας οὔσης οὐδὲν ἤπειγεν ἄλλον ἐμβαλεῖν ἀναδασμὸν οὐδὲ κινεῖν τὴν πρώτην νέμησιν, ὡς εἰκός ἐστι, κατὰ χώραν μένουσαν.", "st": "Comp. Lyc.–Num. 2.3"}, {"sp": "N", "t": "τῆς δὲ περὶ τοὺς γάμους καὶ τὰς τεκνώσεις κοινωνίας τὸ ἀζηλότυπον ὀρθῶς καὶ πολιτικῶς ἐμποιοῦντες ἀμφότεροι τοῖς ἀνδράσιν οὐ κατὰ πᾶν εἰς τοῦτο συνηνέχθησαν, ἀλλ’ ὁ Ῥωμαῖος μὲν ἀνὴρ ἱκανῶς ἔχων παιδοτροφίας, ὑφ’ ἑτέρου δὲ πεισθεὶς δεομένου τέκνων, ἐξίστατο τῆς γυναικός, ἐκδόσθαι καὶ μετεκδόσθαι κύριος ὑπάρχων, ὁ δὲ Λάκων, οἴκοι τῆς γυναικὸς οὔσης παρ’ αὐτῷ καὶ τοῦ γάμου μένοντος ἐπὶ τῶν ἐξ ἀρχῆς δικαίων, μετεδίδου τῷ πείσαντι τῆς κοινωνίας εἰς τέκνωσιν. πολλοὶ δέ, ὥσπερ εἴρηται, καὶ παρακαλοῦντες εἰσῆγον ἐξ ὧν ἂν ἐδόκουν μάλιστα παῖδας εὐειδεῖς καὶ ἀγαθοὺς γενέσθαι, τίς οὖν ἡ διάκρισις τῶν ἐθισμῶν; ἢ ταῦτα μὲν ἰσχυρὰ καὶ ἄκρατος ἀπάθεια πρὸς γαμετὴν καὶ τὰ ταράττοντα καὶ κατακαίοντα ζηλοτυπίαις τοὺς πολλούς, ἐκεῖνα δὲ ὥσπερ αἰσχυνομένη ἀτυφία τίς, παρακάλυμμα τὴν ἐγγύην ἐφελκομένη καὶ τὸ δυσκαρτέρητον ἐξομολογουμένη τῆς κοινωνίας;", "st": "Comp. Lyc.–Num. 3.1"}, {"sp": "N", "t": "ἔτι δὲ μᾶλλον ἡ περὶ τὰς παρθένους φυλακὴ κατέσταλται τῷ Νομᾷ πρὸς τὸ θῆλυ καὶ κόσμιον ἡ δὲ τοῦ Λυκούργου παντάπασιν ἀναπεπταμένη καὶ ἄθηλυς οὖσα τοῖς ποιηταῖς λόγον παρέσχηκε. φαινομηρίδας τε γὰρ αὐτὰς ἀποκαλοῦσιν, ὡς Ἴβυκος, καὶ ἀνδρομανεῖς λοιδοροῦσιν, ὡς Εὐριπίδης, λέγων·", "st": "Comp. Lyc.–Num. 3.3"}, {"sp": "N", "t": "αἳ σὺν νέοισιν ἐξερημοῦσιν δόμους<br>γυμνοῖσι μηροῖς καὶ πέπλοις ἀνειμένοις.", "st": "Comp. Lyc.–Num. 3.3b"}, {"sp": "N", "t": "τῷ γὰρ ὄντι τοῦ παρθενικοῦ χιτῶνος αἱ πτέρυγες οὐκ ἦσαν συνερραμμέναι κάτωθεν, ἀλλ’ ἀνεπτύσσοντο καὶ συνανεγύμνουν ὅλον ἐν τῷ βαδίζειν τὸν μηρόν. καὶ σαφέστατα τὸ γινόμενον εἴρηκε Σοφοκλῆς ἐν τούτοις·", "st": "Comp. Lyc.–Num. 3.4"}, {"sp": "N", "t": "καὶ τὰν νέορτον, ἇς ἔτ’ ἄστολος χιτὼν<br>θυραῖον ἀμφὶ μηρὸν<br>πτύσσεται, Ἑρμιόναν.", "st": "Comp. Lyc.–Num. 3.4b"}, {"sp": "N", "t": "διὸ καὶ θρασύτεραι λέγονται γενέσθαι καὶ πρὸς αὐτοὺς πρῶτον ἀνδρώδεις τοὺς ἄνδρας, ἅτε δὴ τῶν μὲν οἴκων ἄρχουσαι κατὰ κράτος, ἐν δὲ τοῖς δημοσίοις πράγμασι καὶ γνώμης μεταλαμβάνουσαι καὶ παρρησίας περὶ τῶν μεγίστων, ὁ δὲ Νομᾶς ταῖς γαμεταῖς τὸ μὲν ἀξίωμα καὶ τὴν τιμὴν ἐτήρησε πρὸς τοὺς ἄνδρας, ἣν εἶχον ἀπὸ Ῥωμύλου θεραπευόμεναι διὰ τὴν ἁρπαγήν, αἰδῶ δὲ πολλὴν ἐπέστησεν αὐταῖς καὶ πολυπραγμοσύνην ἀφεῖλε καὶ νήφειν ἐδίδαξε καὶ σιωπᾶν εἴθισεν, οἴνου μὲν ἀπεχομένας τὸ πάμπαν, λόγῳ δὲ μηδὲ ὑπὲρ τῶν ἀναγκαίων ἀνδρὸς ἄνευ χρωμένας. λέγεται γοῦν ποτε γυναικὸς εἰπούσης δίκην ἰδίαν ἐν ἀγορᾷ πέμψαι τὴν σύγκλητον εἰς θεοῦ, πυνθανομένην τίνος ἄρα τῇ πόλει σημεῖον εἴη τὸ γεγενημένον. καὶ τῆς ἄλλης εὐπειθείας καὶ πρᾳότητος αὐτῶν μέγα τεκμήριον ἡ μνήμη τῶν χειρόνων. ὡς γὰρ παρ’ ἡμῖν οἱ ἱστορικοὶ γράφουσι τοὺς πρώτους ἢ φόνον ἐμφύλιον ἐργασαμένους ἢ πολεμήσαντας ἀδελφοῖς ἢ πατρὸς αὐτόχειρας ἢ μητρὸς γενομένους, οὕτω Ῥωμαῖοι μνημονεύουσιν ὅτι πρῶτος μὲν ἀπεπέμψατο γυναῖκα Σπόριος Καρβίλιος, μετὰ τὴν Ῥώμης κτίσιν ἔτεσι τριάκοντα καὶ διακοσίοις οὐδενὸς τοιούτου γεγονότος, πρώτη δὲ γυνὴ Πιναρίου Θαλαία τοὔνομα διηνέχθη πρὸς ἑκυρὰν αὑτῆς Γεγανίαν Ταρκυνίου Σουπέρβου βασιλεύοντος, οὕτω καλῶς καὶ κοσμίως τεταγμένα τὰ τῶν γάμων ἦν ὑπὸ τοῦ νομοθέτου.", "st": "Comp. Lyc.–Num. 3.5"}, {"sp": "N", "t": "τῇ δὲ ἄλλῃ τῶν παρθένων ἀγωγῇ καὶ τὰ περὶ τὰς ἐκδόσεις ὁμολογεῖ, τοῦ μὲν Λυκούργου πεπείρους καὶ ὀργώσας νυμφεύοντος, ὅπως ἥ τε ὁμιλία, δεομένης ἤδη τῆς φύσεως, χάριτος ᾖ καὶ φιλίας ἀρχὴ μᾶλλον ἢ μίσους καὶ φόβου παρὰ φύσιν βιαζομένων καὶ τὰ σώματα ῥώμην ἔχῃ πρός τὸ τὰς κυήσεις ἀναφέρειν καὶ τὰς ὠδῖνας, ὡς ἐπ’ οὐδέν ἄλλο γαμουμένων ἢ τὸ τῆς τεκνώσεως ἔργον, τῶν δὲ Ῥωμαίων δωδεκαετεῖς καὶ νεωτέρας ἐκδιδόντων οὕτω γὰρ ἂν μάλιστα καὶ τὸ σῶμα καὶ τὸ ἦθος καθαρὸν καὶ ἄθικτον ἐπὶ τῷ γαμοῦντι γίνεσθαι. δῆλον οὖν ὅτι τὸ μὲν φυσικώτερον πρὸς τέκνωσιν, τὸ δὲ ἠθικώτερον πρός συμβίωσιν.", "st": "Comp. Lyc.–Num. 4.1"}, {"sp": "N", "t": "ἀλλὰ μὴν ἐπιστασίαις τε παίδων καὶ συναγελασμοῖς καὶ παιδαγωγίαις καὶ κοινωνίαις, περί τε δεῖπνα καὶ γυμνάσια καὶ παιδιὰς αὐτῶν ἐμμελείαις καὶ διακοσμήσεσιν, οὐδέν τι τοῦ προστυχόντος νομοθέτου βελτίονα τὸν Νομᾶν ὁ Λυκοῦργος ἀποδείκνυσιν, ἐπὶ ταῖς τῶν πατέρων ποιησάμενον ἐπιθυμίαις ἢ χρείαις τὰς τῶν νέων ἀγωγάς, εἴτε τις ἐργάτην γῆς βούλοιτο ποιεῖν τὸν υἱὸν εἴτε ναυπηγὸν ἢ χαλκέα διδάσκειν ἢ αὐλητήν, ὥσπερ οὐ πρός ἓν τέλος ὀφείλοντας ἐξ ἀρχῆς ἄγεσθαι καὶ συνεπιστρέφεσθαι τοῖς ἤθεσιν, ἀλλ’ οἷον εἰς ναῦν ἐπιβάτας ἕτερον ἐξ ἑτέρας ἥκοντα χρείας καὶ προαιρέσεως ἐν τοῖς κινδύνοις μόνον φόβῳ τοῦ ἰδίου συνίστασθαι πρός τὸ κοινόν, ἄλλως δὲ τὸ καθ’ αὑτὸν σκοπεῖν ἕκαστον. καὶ τοῖς μὲν πολλοῖς οὐκ ἄξιον ἐγκαλεῖν νομοθέταις ἐλλείπουσιν ἢ δι’ ἄγνοιαν ἢ δι’ ἀσθένειαν ἀνδρὶ δὲ σοφῷ βασιλείαν παραλαβόντι δήμου νεωστὶ συνισταμένου καὶ πρός μηδὲν ἀντιτείνοντος, περὶ τί πρῶτον ἦν σπουδάσαι προσῆκον ἢ παίδων ἐκτροφὴν καὶ νέων ἄσκησιν, ὅπως μὴ διάφοροι μηδὲ ταραχώδεις γένοιντο τοῖς ἤθεσιν, ἀλλ’ εἰς ἕν τι κοινὸν ἀρετῆς ἴχνος εὐθὺς ἐξ ἀρχῆς πλαττόμενοι καὶ τυπούμενοι συμβαίνοιεν ἀλλήλοις; ὃ δὴ πρός τε τὰ ἄλλα καὶ σωτηρίαν νόμων ὠφέλησε τὸν Λυκοῦργον. μικρὸς γὰρ ἦν ὁ τῶν ὅρκων φόβος, εἰ μὴ διὰ τῆς παιδείας καὶ τῆς ἀγωγῆς οἷον ἀνέδευσε τοῖς ἤθεσι τῶν παίδων τοὺς νόμους, καὶ συνῳκείωσε τῇ τροφῇ τὸν ζῆλον τῆς πολιτείας, ὥστε πεντακοσίων ἐτῶν πλείω χρόνον τὰ κυριώτατα καὶ μέγιστα διαμεῖναι τῆς νομοθεσίας, ὥσπερ βαφῆς ἀκράτου καὶ ἰσχυρῶς καθαψαμένης.", "st": "Comp. Lyc.–Num. 4.3"}, {"sp": "N", "t": "Νομᾷ δὲ ὅπερ ἦν τέλος τῆς πολιτείας, ἐν εἰρήνῃ καὶ φιλίᾳ τὴν Ῥώμην ὑπάρχειν, εὐθὺς συνεξέλιπε· καὶ μετὰ τὴν τελευτὴν ἐκείνου τὸν ἀμφίθυρον οἶκον, ὃν κεκλεισμένον αὐτὸς συνεῖχεν, ὥσπερ ὄντως ἐν αὐτῷ τιθασεύων καθειργμένον τὸν πόλεμον, ἐξ ἀμφοτέρων ἀναπετάσαντες αἵματος καὶ νεκρῶν τὴν Ἰταλίαν ἐνέπλησαν· καὶ οὐδὲ ὀλίγον χρόνον ἡ καλλίστη καὶ δικαιοτάτη κατάστασις ἔμεινεν, ἅτε δὴ καὶ τὸ συνδετικὸν ἐν αὑτῇ, τὴν παιδείαν, οὐκ ἔχουσα.", "st": "Comp. Lyc.–Num. 4.6"}, {"sp": "N", "t": "τί οὖν, φήσει τις, οὐκ ἐπὶ τὸ βέλτιον ἡ Ῥώμη προῆλθε τοῖς πολεμικοῖς; ἐρωτῶν ἐρώτημα μακρᾶς ἀποκρίσεως δεόμενον πρός ἀνθρώπους τὸ βέλτιον ἐν πλούτῳ καὶ τρυφῇ καὶ ἡγεμονίᾳ μᾶλλον ἢ σωτηρίᾳ καὶ πρᾳότητι καὶ τῇ μετὰ δικαιοσύνης αὐταρκείᾳ τιθεμένους, οὐ μὴν ἀλλὰ καὶ τοῦτο Λυκούργῳ που δόξει βοηθεῖν, τὸ Ῥωμαίους μὲν τὴν ἐπὶ Νομᾶ κατάστασιν ἐξαλλάξαντας ἐπιδοῦναι τοῖς πράγμασι τοσοῦτον, Λακεδαιμονίους δὲ ἅμα τῷ πρῶτον ἐκβῆναι τὴν Λυκούργου διάταξιν, ἐκ μεγίστων ταπεινοτάτους γενέσθαι καὶ τὴν τῶν Ἑλλήνων ἡγεμονίαν ἀποβαλόντας κινδυνεῦσαι περί ἀναστάσεως, ἐκεῖνο μέντοι τῷ Νομᾷ μέγα καὶ θεῖον ὡς ἀληθῶς ὑπάρχει, τὸ ξένῳ τε μεταπέμπτῳ γενέσθαι καὶ πάντα πειθοῖ μεταβαλεῖν, καὶ κρατῆσαι πόλεως οὔπω συμπεπνευκυίας, μήτε ὅπλων δεηθέντα μήτε βίας τινός, ὡς Λυκοῦργος ἐπὶ τὸν δῆμον ἦγε τοὺς ἀρίστους, ἀλλὰ σοφίᾳ καὶ δικαιοσύνῃ πάντας προσαγαγόμενον καὶ συναρμόσαντα.", "st": "Comp. Lyc.–Num. 4.7"}, {"sp": "HDR", "t": "Σόλων"}, {"sp": "N", "t": "δίδυμος ὁ γραμματικὸς ἐν τῇ περὶ τῶν ἀξόνων τῶν Σόλωνος ἀντιγραφῇ πρὸς Ἀσκληπιάδην Φιλοκλέους τινὸς τέθεικε λέξιν, ἐν ᾗ τὸν Σόλωνα πατρὸς Εὐφορίωνος ἀποφαίνει παρὰ τὴν τῶν ἄλλων δόξαν, ὅσοι μέμνηνται Σόλωνος. Ἐξηκεστίδου γὰρ αὐτὸν ἅπαντες ὁμαλῶς γεγονέναι λέγουσιν, ἀνδρὸς οὐσίᾳ μέν, ὥς φασι, καὶ δυνάμει μέσου τῶν πολιτῶν, οἰκίας δὲ πρώτης κατὰ γένος· ἦν γὰρ Κοδρίδης ἀνέκαθεν. τὴν δὲ μητέρα τοῦ Σόλωνος Ἡρακλείδης ὁ Ποντικὸς ἱστορεῖ τῆς Πεισιστράτου μητρὸς ἀνεψιὰν γενέσθαι. καὶ φιλία τὸ πρῶτον ἦν αὐτοῖς πολλὴ μὲν διὰ τὴν συγγένειαν, πολλὴ δὲ διὰ τὴν εὐφυΐαν καὶ ὥραν, ὡς ἔνιοί φασιν, ἐρωτικῶς τὸν Πεισίστρατον ἀσπαζομένου τοῦ Σόλωνος. ὅθεν ὕστερον, ὡς ἔοικεν, εἰς διαφορὰν αὐτῶν ἐν τῇ πολιτείᾳ καταστάντων οὐδὲν ἤνεγκεν ἡ ἔχθρα σκληρὸν οὐδ’ ἄγριον πάθος, ἀλλὰ παρέμεινεν ἐκεῖνα τὰ δίκαια ταῖς ψυχαῖς, καὶ παρεφύλαξε,", "st": "Sol. 1.1"}, {"sp": "N", "t": "τυφόμενα Δίου πυρὸς ἔτι ζῶσαν φλόγα,", "st": "Sol. 1.1b"}, {"sp": "N", "t": "τὴν ἐρωτικὴν μνήμην καὶ χάριν. ὅτι δὲ πρὸς τοὺς καλοὺς οὐκ ἦν ἐχυρὸς ὁ Σόλων οὐδ’ Ἔρωτι θαρραλέος ἀνταναστῆναι πύκτης ὅπως ἐς χεῖρας, ἔκ τε τῶν ποιημάτων αὐτοῦ λαβεῖν ἔστι, καὶ νόμον ἔγραψε διαγορεύοντα δοῦλον μὴ ξηραλοιφεῖν μηδὲ παιδεραστεῖν, εἰς τὴν τῶν καλῶν μερίδα καὶ σεμνῶν ἐπιτηδευμάτων τιθέμενος τὸ πρᾶγμα, καὶ τρόπον τινὰ τοὺς ἀξίους προκαλούμενος ὧν τοὺς ἀναξίους ἀπήλαυνε. λέγεται δὲ καὶ Πεισίστρατος ἐραστὴς Χάρμου γενέσθαι, καὶ τὸ ἄγαλμα τοῦ Ἔρωτος ἐν Ἀκαδημείᾳ καθιερῶσαι, ὅπου τὸ πῦρ ἀνάπτουσιν οἱ τὴν ἱερὰν λαμπάδα διαθέοντες.", "st": "Sol. 1.3"}, {"sp": "N", "t": "ὁ δ’ οὖν Σόλων τὴν οὐσίαν τοῦ πατρὸς ἐλαττώσαντος εἰς φιλανθρωπίας τινάς, ὥς φησιν Ἕρμιππος, καὶ χάριτας, οὐκ ἂν ἀπορήσας τῶν βουλομένων ἐπαρκεῖν, αἰδούμενος δὲ λαμβάνειν παρ’ ἑτέρων ἐξ οἰκίας γεγονὼς εἰθισμένης ἑτέροις βοηθεῖν, ὥρμησε νέος ὢν ἔτι πρὸς ἐμπορίαν. καίτοι φασὶν ἔνιοι πολυπειρίας ἕνεκα μᾶλλον καὶ ἱστορίας ἢ χρηματισμοῦ πλανηθῆναι τὸν Σόλωνα. σοφίας μὲν γὰρ ἦν ὁμολογουμένως ἐραστής, ὅς γε καὶ πρεσβύτερος ὢν ἔλεγε γηράσκειν αἰεὶ πολλὰ διδασκόμενος· πλοῦτον δ’ οὐκ ἐθαύμαζεν, ἀλλὰ καί φησιν ὁμοίως πλουτεῖν ᾧ τε", "st": "Sol. 2.1"}, {"sp": "N", "t": "πολὺς ἄργυρός ἐστι<br>καὶ χρυσὸς καὶ γῆς πυροφόρου πεδία<br>ἵπποι θ’ ἡμίονοί τε, καὶ ᾧ μόνα ταῦτα πάρεστι,<br>γαστρί τε καὶ πλευρῇ καὶ ποσὶν ἁβρὰ παθεῖν,<br>παιδός τ’ ἠδὲ γυναικός, ἐπὴν καὶ ταῦτ’ ἀφίκηται,<br>ἥβη, σὺν δ’ ὥρη γίνεται ἁρμοδία.", "st": "Sol. 2.1b"}, {"sp": "N", "t": "ἀλλ’ ἑτέρωθι λέγει·<br>χρήματα δ’ ἱμείρω μὲν ἔχειν, ἀδίκως δὲ πεπᾶσθαι<br>οὐκ ἐθέλω· πάντως ὕστερον ἦλθε δίκη.", "st": "Sol. 2.3"}, {"sp": "N", "t": "κωλύει δὲ οὐδὲν τὸν ἀγαθὸν καὶ πολιτικὸν ἄνδρα μήτε τῶν περιττῶν τὴν κτῆσιν ἐν σπουδῇ τίθεσθαι μήτε τῆς χρείας τῶν ἀναγκαίων καὶ ἱκανῶν καταφρονεῖν. ἐν δὲ τοῖς τότε χρόνοις, καθ’ Ἡσίοδον, ἔργον οὐδὲν ἦν ὄνειδος, οὐδὲ τέχνη διαφορὰν ἔφερεν, ἐμπορία δὲ καὶ δόξαν εἶχεν οἰκειουμένη τὰ βαρβαρικὰ καὶ προξενοῦσα φιλίας βασιλέων καὶ πραγμάτων ἐμπείρους ποιοῦσα πολλῶν. ἔνιοι δὲ καὶ πόλεων οἰκισταὶ γεγόνασι μεγάλων, ὡς καὶ Μασσαλίας Πρῶτις ὑπὸ Κελτῶν τῶν περὶ τὸν Ῥοδανὸν ἀγαπηθείς. καὶ Θαλῆν δέ φασιν ἐμπορίᾳ χρήσασθαι καὶ Ἱπποκράτην τὸν μαθηματικόν, καὶ Πλάτωνι τῆς ἀποδημίας ἐφόδιον ἐλαίου τινὸς ἐν Αἰγύπτῳ διάθεσιν γενέσθαι.", "st": "Sol. 2.4"}, {"sp": "N", "t": "τὸ δ’ οὖν εὐδάπανον τῷ Σόλωνι καὶ ὑγρὸν πρὸς τὴν δίαιταν, καὶ τὸ φορτικώτερον ἢ φιλοσοφώτερον ἐν τοῖς ποιήμασι διαλέγεσθαι περὶ τῶν ἡδονῶν, τὸν ἐμπορικὸν οἴονται βίον προστετρῖφθαι· πολλοὺς γὰρ ἔχοντα κινδύνους καὶ μεγάλους ἀνταπαιτεῖν πάλιν εὐπαθείας τινὰς καὶ ἀπολαύσεις. ὅτι δ’ αὑτὸν ἐν τῇ τῶν πενήτων μερίδι μᾶλλον ἢ τῇ τῶν πλουσίων ἔταττε, δῆλόν ἐστιν ἐκ τούτων·", "st": "Sol. 3.1"}, {"sp": "N", "t": "πολλοὶ γὰρ πλουτεῦσι κακοί, ἀγαθοὶ δὲ πένονται·<br>ἀλλ’ ἡμεῖς αὐτοῖς οὐ διαμειψόμεθα<br>τῆς ἀρετῆς τὸν πλοῦτον· ἐπεὶ τὸ μὲν ἔμπεδον αἰεί,<br>χρήματα δ’ ἀνθρώπων ἄλλοτε ἄλλος ἔχει.", "st": "Sol. 3.1b"}, {"sp": "N", "t": "τῇ δὲ ποιήσει κατ’ ἀρχὰς μὲν εἰς οὐδὲν ἄξιον σπουδῆς, ἀλλὰ παίζων ἔοικε προσχρήσασθαι καὶ παράγων ἑαυτὸν ἐν τῷ σχολάζειν· ὕστερον δὲ καὶ γνώμας ἐνέτεινε φιλοσόφους καὶ τῶν πολιτικῶν πολλὰ συγκατέπλεκε τοῖς ποιήμασιν, οὐχ ἱστορίας ἕνεκεν καὶ μνήμης, ἀλλ’ ἀπολογισμούς τε τῶν πεπραγμένων ἔχοντα καὶ προτροπὰς ἐνιαχοῦ καὶ νουθεσίας καὶ ἐπιπλήξεις πρὸς τοὺς Ἀθηναίους. ἔνιοι δέ φασιν ὅτι καὶ τοὺς νόμους ἐπεχείρησεν ἐντείνας εἰς ἔπος ἐξενεγκεῖν, καὶ διαμνημονεύουσι τὴν ἀρχὴν οὕτως ἔχουσαν·", "st": "Sol. 3.3"}, {"sp": "N", "t": "πρῶτα μὲν εὐχώμεσθα Διῒ Κρονίδῃ βασιλῆϊ<br>θεσμοῖς τοῖσδε τύχην ἀγαθὴν καὶ κῦδος ὀπάσσαι.", "st": "Sol. 3.3b"}, {"sp": "N", "t": "φιλοσοφίας δὲ τοῦ ἠθικοῦ μάλιστα τὸ πολιτικόν, ὥσπερ οἱ πλεῖστοι τῶν σοφῶν, ἠγάπησεν. ἐν δὲ τοῖς φυσικοῖς ἁπλοῦς ἐστι λίαν καὶ ἀρχαῖος, ὡς δῆλον ἐκ τούτων·", "st": "Sol. 3.3c"}, {"sp": "N", "t": "ἐκ νεφέλης πέλεται χιόνος μένος ἠδὲ χαλάζης·<br>βροντὴ δ’ ἐκ λαμπρᾶς γίνεται ἀστεροπῆς.", "st": "Sol. 3.5"}, {"sp": "N", "t": "ἐξ ἀνέμων δὲ θάλασσα ταράσσεται· ἢν δέ τις αὐτὴν<br>μὴ κινῇ, πάντων ἐστὶ δικαιοτάτη.", "st": "Sol. 3.5b"}, {"sp": "N", "t": "καὶ ὅλως ἔοικεν ἡ Θάλεω μόνου σοφία τότε περαιτέρω τῆς χρείας ἐξικέσθαι τῇ θεωρίᾳ· τοῖς δὲ ἄλλοις ἀπὸ τῆς πολιτικῆς ἀρετῆς τοὔνομα τῆς σοφίας ὑπῆρξε.", "st": "Sol. 3.5c"}, {"sp": "N", "t": "γενέσθαι δὲ μετ’ ἀλλήλων ἔν τε Δελφοῖς ὁμοῦ λέγονται καὶ πάλιν ἐν Κορίνθῳ, Περιάνδρου σύλλογόν τινα κοινὸν αὐτῶν καὶ συμπόσιον κατασκευάσαντος. ἔτι δὲ μᾶλλον εἰς ἀξίωμα καὶ δόξαν αὐτοὺς κατέστησεν ἡ τοῦ τρίποδος περίοδος καὶ διὰ πάντων ἀνακύκλησις καὶ ἀνθύπειξις μετ’ εὐμενείας φιλοτίμου γενομένη. Κῴων γάρ, ὥς φασι, καταγόντων σαγήνην, καὶ ξένων ἐκ Μιλήτου πριαμένων τὸν βόλον οὔπω φανερὸν ὄντα, χρυσοῦς ἐφάνη τρίπους ἑλκόμενος, ὃν λέγουσιν Ἑλένην πλέουσαν ἐκ Τροίας αὐτόθι καθεῖναι χρησμοῦ τινος ἀναμνησθεῖσαν παλαιοῦ. γενομένης δὲ τοῖς ξένοις πρῶτον ἀντιλογίας πρὸς τοὺς ἁλιέας περὶ τοῦ τρίποδος, εἶτα τῶν πόλεων ἀναδεξαμένων τὴν διαφορὰν ἄχρι πολέμου προελθοῦσαν, ἀνεῖλεν ἀμφοτέροις ἡ Πυθία τῷ σοφωτάτῳ τὸν τρίποδα ἀποδοῦναι. καὶ πρῶτον μὲν ἀπεστάλη πρὸς Θαλῆν εἰς Μίλητον, ἑκουσίως τῶν Κῴων ἑνὶ δωρουμένων ἐκείνῳ περὶ οὗ πρὸς ἅπαντας ὁμοῦ Μιλησίους ἐπολέμησαν. Θάλεω δὲ Βίαντα σοφώτερον ἀποφαίνοντος αὑτοῦ πρὸς ἐκεῖνον ἧκεν· ἀπ’ ἐκείνου δ’ αὖθις ἀπεστάλη πρὸς ἄλλον ὡς σοφώτερον. εἶτα περιϊὼν καὶ ἀναπεμπόμενος οὕτως ἐπὶ Θαλῆν τὸ δεύτερον ἀφίκετο, καὶ τέλος εἰς Θήβας ἐκ Μιλήτου κομισθεὶς τῷ Ἰσμηνίῳ Ἀπόλλωνι καθιερώθη.", "st": "Sol. 4.1"}, {"sp": "N", "t": "θεόφραστος δέ φησι, πρῶτον μὲν εἰς Πριήνην Βίαντι τὸν τρίποδα πεμφθῆναι, δεύτερον δ’ εἰς Μίλητον Θαλῇ Βίαντος ἀποπέμψαντος· οὕτω δὲ διὰ πάντων πάλιν εἰς Βίαντα περιελθεῖν, τέλος δὲ εἰς Δελφοὺς ἀποσταλῆναι. ταῦτα μὲν οὖν ὑπὸ πλειόνων τεθρύληται, πλὴν ὅτι τὸ δῶρον ἀντὶ τοῦ τρίποδος οἱ μὲν φιάλην ὑπὸ Κροίσου πεμφθεῖσαν, οἱ δὲ ποτήριον Βαθυκλέους ἀπολιπόντος εἶναι λέγουσιν.", "st": "Sol. 4.4"}, {"sp": "N", "t": "ἰδίᾳ δ’ Ἀναχάρσεώς τε πρὸς Σόλωνα καὶ πάλιν Θάλεω συνουσίαν τινὰ καὶ λόγους ἀναγράφουσι τοιούτους. Ἀνάχαρσιν μὲν εἰς Ἀθήνας φασὶν ἐπὶ τὴν Σόλωνος οἰκίαν ἐλθόντα κόπτειν, καὶ λέγειν ὡς ξένος ὢν ἀφῖκται φιλίαν ποιησόμενος καὶ ξενίαν πρὸς αὐτόν. ἀποκριναμένου δὲ τοῦ Σόλωνος ὡς οἴκοι βέλτιόν ἐστι ποιεῖσθαι φιλίας, οὐκοῦν, φάναι τὸν Ἀνάχαρσιν, αὐτὸς ὢν οἴκοι σὺ ποίησαι φιλίαν καὶ ξενίαν πρὸς ἡμᾶς. οὕτω δὴ θαυμάσαντα τὴν ἀγχίνοιαν τοῦ ἀνδρὸς τὸν Σόλωνα δέξασθαι φιλοφρόνως, καὶ χρόνον τινὰ κατασχεῖν παρ’ αὑτῷ, ἤδη τὰ δημόσια πράττοντα καὶ συνταττόμενον τοὺς νόμους. τὸν οὖν Ἀνάχαρσιν πυθόμενον καταγελᾶν τῆς πραγματείας τοῦ Σόλωνος, οἰομένου γράμμασιν ἐφέξειν τὰς ἀδικίας καὶ πλεονεξίας τῶν πολιτῶν, ἃ μηδὲν τῶν ἀραχνίων διαφέρειν, ἀλλ’ ὡς ἐκεῖνα τοὺς μὲν ἀσθενεῖς καὶ λεπτοὺς τῶν ἁλισκομένων καθέξειν, ὑπὸ δὲ τῶν δυνατῶν καὶ πλουσίων διαρραγήσεσθαι. τὸν δὲ Σόλωνα πρὸς ταῦτά φασιν εἰπεῖν ὅτι καὶ συνθήκας ἄνθρωποι φυλάττουσιν, ἃς οὐδετέρῳ λυσιτελές ἐστι παραβαίνειν τῶν θεμένων· καὶ τοὺς νόμους αὐτὸς οὕτως ἁρμόζεται τοῖς πολίταις ὥστε πᾶσι τοῦ παρανομεῖν βέλτιον ἐπιδεῖξαι τὸ δικαιοπραγεῖν. ἀλλὰ ταῦτα μὲν ὡς Ἀνάχαρσις εἴκαζεν ἀπέβη μᾶλλον ἢ κατ’ ἐλπίδα τοῦ Σόλωνος. ἔφη δὲ κἀκεῖνο θαυμάζειν ὁ Ἀνάχαρσις ἐκκλησίᾳ παραγενόμενος, ὅτι λέγουσι μὲν οἱ σοφοὶ παρ’ Ἕλλησι, κρίνουσι δὲ οἱ ἀμαθεῖς.", "st": "Sol. 5.1"}, {"sp": "N", "t": "πρὸς Θαλῆν δ’ εἰς Μίλητον ἐλθόντα τὸν Σόλωνα θαυμάζειν ὅτι γάμου καὶ παιδοποιΐας τὸ παράπαν ἠμέληκε. καὶ τὸν Θαλῆν τότε μὲν σιωπῆσαι, διαλιπόντα δ’ ὀλίγας ἡμέρας ἄνδρα παρασκευάσαι ξένον, ἀρτίως ἥκειν φάσκοντα δεκαταῖον ἐξ Ἀθηνῶν. πυθομένου δὲ τοῦ Σόλωνος εἰ δή τι καινὸν ἐν ταῖς Ἀθήναις, δεδιδαγμένον ἃ χρὴ λέγειν τὸν ἄνθρωπον, οὐδέν, εἰπεῖν, ἕτερον, εἰ μὴ νὴ Δία νεανίσκου τινὸς ἦν ἐκφορὰ καὶ προὔπεμπεν ἡ πόλις. ἦν γὰρ υἱός, ὡς ἔφασαν, ἀνδρὸς ἐνδόξου καὶ πρωτεύοντος ἀρετῇ τῶν πολιτῶν· οὐ παρῆν δέ, ἀλλ’ ἀποδημεῖν ἔφασαν αὐτὸν ἤδη πολὺν χρόνον. ὡς δυστυχὴς ἐκεῖνος, φάναι τὸν Σόλωνα. τίνα δὲ ὠνόμαζον αὐτόν; ἤκουσα, φάναι, τοὔνομα, τὸν ἄνθρωπον, ἀλλ’ οὐ μνημονεύω· πλὴν ὅτι πολὺς λόγος ἦν αὐτοῦ σοφίας καὶ δικαιοσύνης. οὕτω δὴ καθ’ ἑκάστην ἀπόκρισιν τῷ φόβῳ προσαγόμενον τὸν Σόλωνα καὶ τέλος ἤδη συντεταραγμένον αὐτὸν ὑποβάλλειν τοὔνομα τῷ ξένῳ, πυνθανόμενον μὴ Σόλωνος ὁ τεθνηκὼς υἱὸς ὠνομάζετο. φήσαντος δὲ τοῦ ἀνθρώπου, τὸν μὲν ὁρμῆσαι παίειν τὴν κεφαλὴν καὶ τἆλλα ποιεῖν καὶ λέγειν ἃ συμβαίνει τοῖς περιπαθοῦσι, τὸν δὲ Θαλῆν ἐπιλαβόμενον αὐτοῦ καὶ γελάσαντα, ταῦτά τοι, φάναι, ὦ Σόλων, ἐμὲ γάμου καὶ παιδοποιΐας ἀφίστησιν, ἃ καὶ σὲ κατερείπει τὸν ἐρρωμενέστατον. ἀλλὰ θάρρει τῶν λόγων ἕνεκα τούτων· οὐ γάρ εἰσιν ἀληθεῖς. ταῦτα μὲν οὖν Ἕρμιππος ἱστορεῖν φησι Πάταικον, ὃς ἔφασκε τὴν Αἰσώπου ψυχὴν ἔχειν.", "st": "Sol. 6.1"}, {"sp": "N", "t": "ἄτοπος δὲ καὶ ἀγεννὴς ὁ τῷ φόβῳ τῆς ἀποβολῆς τὴν κτῆσιν ὧν χρὴ προϊέμενος· οὕτω γὰρ ἄν τις οὐ πλοῦτον, οὐ δόξαν, οὐ σοφίαν ἀγαπήσειε παραγενομένην, δεδιὼς στέρεσθαι. καὶ γὰρ ἀρετήν, ἧς κτῆμα μεῖζον οὐδὲν οὐδ’ ἥδιον, ἐξισταμένην ὑπὸ νόσων καὶ φαρμάκων ὁρῶμεν· αὐτῷ τε Θαλῇ μὴ γήμαντι πλέον οὐδὲν εἰς ἀφοβίαν, εἰ μὴ καὶ φίλων κτῆσιν ἔφυγε καὶ οἰκείων καὶ πατρίδος. ἀλλὰ καὶ παῖδα θετὸν ἔσχε ποιησάμενος αὐτὸς τὸν τῆς ἀδελφῆς, ὥς φασι, Κύβισθον. ἐχούσης γάρ τι τῆς ψυχῆς ἀγαπητικὸν ἐν ἑαυτῇ καὶ πεφυκυίας, ὥσπερ αἰσθάνεσθαι καὶ διανοεῖσθαι καὶ μνημονεύειν, οὕτω καὶ φιλεῖν, ἐνδύεταί τι τούτῳ καὶ προσφύεται τῶν ἐκτὸς οἷς οἰκεῖον οὐδέν ἐστιν, καὶ καθάπερ οἶκον ἢ χώραν γνησίων ἔρημον διαδόχων, τὸ φιλόστοργον ἀλλότριοι καὶ νόθοι παῖδες ἢ θεράποντες εἰσοικισάμενοι καὶ καταλαβόντες ἅμα τῷ φιλεῖν τὸ φροντίζειν καὶ δεδιέναι περὶ αὐτῶν ἐνεποίησαν. ὥστ’ ἴδοις ἂν ἀνθρώπους στερροτέρα τῇ φύσει περὶ γάμου καὶ γενέσεως παίδων διαλεγομένους, εἶτα τοὺς αὐτοὺς ἐπὶ παισὶν οἰκοτρίβων ἢ θρέμμασι παλλακῶν νοσοῦσι καὶ θνήσκουσι παρατεινομένους πόθῳ καὶ φωνὰς ἀγεννεῖς ἀφιέντας. ἔνιοι δὲ καὶ κυνῶν θανάτῳ καὶ ἵππων αἰσχρῶς καὶ ἀβιώτως ὑπὸ λύπης διετέθησαν. ἀλλ’ ἕτεροί γε παῖδας ἀγαθοὺς ἀποβαλόντες οὐδὲν ἔπαθον δεινὸν οὐδ’ ἐποίησαν αἰσχρόν, ἀλλὰ καὶ χρώμενοι τῷ λοιπῷ βίῳ κατὰ λόγον διετέλεσαν. ἀσθένεια γάρ, οὐκ εὔνοια, λύπας ἀπεράντους ἐπάγεται καὶ φόβους ἀνθρώποις ἀνασκήτοις ὑπὸ λόγου πρὸς τύχην, οἷς οὐδ’ ἀπόλαυσις ἐγγίνεται τοῦ ποθουμένου παρόντος, τοῦ μέλλοντος ὠδῖνας ἀεὶ καὶ τρόμους καὶ ἀγῶνας, εἰ στερήσονται, παρέχοντος αὐτοῖς. δεῖ δὲ μήτε πενίᾳ πρὸς χρημάτων πεφράχθαι στέρησιν μήτε ἀφιλίᾳ πρὸς φίλων ἀποβολὴν μήτ’ ἀπαιδίᾳ πρὸς τέκνων θάνατον, ἀλλὰ τῷ λογισμῷ πρὸς πάντα. καὶ ταῦτα μέν, ὡς ἐν τῷ παρόντι, πλείονα τῶν ἱκανῶν.", "st": "Sol. 7.1"}, {"sp": "N", "t": "ἐπεὶ δὲ μακρόν τινα καὶ δυσχερῆ πόλεμον οἱ ἐν ἄστει περὶ τῆς Σαλαμινίων νήσου Μεγαρεῦσι πολεμοῦντες ἐξέκαμον, καὶ νόμον ἔθεντο μήτε γράψαι τινὰ μήτ’ εἰπεῖν αὖθις ὡς χρὴ τὴν πόλιν ἀντιποιεῖσθαι τῆς Σαλαμῖνος, ἢ θανάτῳ ζημιοῦσθαι, βαρέως φέρων τὴν ἀδοξίαν ὁ Σόλων, καὶ τῶν νέων ὁρῶν πολλοὺς δεομένους ἀρχῆς ἐπὶ τὸν πόλεμον, αὐτοὺς δὲ μὴ θαρροῦντας ἄρξασθαι διὰ τὸν νόμον, ἐσκήψατο μὲν ἔκστασιν τῶν λογισμῶν, καὶ λόγος εἰς τὴν πόλιν ἐκ τῆς οἰκίας διεδόθη παρακινητικῶς ἔχειν αὐτόν, ἐλεγεῖα δὲ κρύφα συνθεὶς καὶ μελετήσας ὥστε λέγειν ἀπὸ στόματος, ἐξεπήδησεν εἰς τὴν ἀγορὰν ἄφνω πιλίδιον περιθέμενος. ὄχλου δὲ πολλοῦ συνδραμόντος ἀναβὰς ἐπὶ τὸν τοῦ κήρυκος λίθον ἐν ᾠδῇ διεξῆλθε τὴν ἐλεγείαν, ἧς ἐστιν ἀρχή·", "st": "Sol. 8.1"}, {"sp": "N", "t": "αὐτὸς κῆρυξ ἦλθον ἀφ’ ἱμερτῆς Σαλαμῖνος,<br>κόσμον ἐπέων ᾠδὴν ἀντ’ ἀγορῆς θέμενος.", "st": "Sol. 8.1b"}, {"sp": "N", "t": "τοῦτο τὸ ποίημα Σαλαμὶς ἐπιγέγραπται καὶ στίχων ἑκατόν ἐστι, χαριέντως πάνυ πεποιημένον. τότε δὲ ᾀσθέντος αὐτοῦ καὶ τῶν φίλων τοῦ Σόλωνος ἀρξαμένων ἐπαινεῖν, μάλιστα δὲ τοῦ Πεισιστράτου τοῖς πολίταις ἐγκελευομένου καὶ παρορμῶντος πεισθῆναι τῷ λέγοντι, λύσαντες τὸν νόμον αὖθις ἥπτοντο τοῦ πολέμου, προστησάμενοι τὸν Σόλωνα.", "st": "Sol. 8.3"}, {"sp": "N", "t": "τὰ μὲν οὖν δημώδη τῶν λεγομένων τοιαῦτ’ ἐστίν, ὅτι πλεύσας ἐπὶ Κωλιάδα μετὰ τοῦ Πεισιστράτου, καὶ καταλαβὼν αὐτόθι πάσας τὰς γυναῖκας τῇ Δήμητρι τὴν πάτριον θυσίαν ἐπιτελούσας, ἔπεμψεν ἄνδρα πιστὸν εἰς Σαλαμῖνα προσποιούμενον αὐτόμολον εἶναι, κελεύοντα τοὺς Μεγαρεῖς, εἰ βούλονται τῶν Ἀθηναίων τὰς πρώτας λαβεῖν γυναῖκας, ἐπὶ Κωλιάδα μετ’ αὐτοῦ πλεῖν τὴν ταχίστην. ὡς δὲ πεισθέντες οἱ Μεγαρεῖς ἄνδρας ἐξέπεμψαν ἐν τῷ πλοίῳ καὶ κατεῖδεν ὁ Σόλων τὸ πλοῖον ἐλαυνόμενον ἀπὸ τῆς νήσου, τὰς μὲν γυναῖκας ἐκποδὼν ἀπελθεῖν ἐκέλευσε, τῶν δὲ νεωτέρων τοὺς μηδέπω γενειῶντας ἐνδύμασι καὶ μίτραις καὶ ὑποδήμασι τοῖς ἐκείνων σκευασαμένους καὶ λαβόντας ἐγχειρίδια κρυπτὰ παίζειν καὶ χορεύειν προσέταξε πρὸς τῇ θαλάσσῃ, μέχρις ἂν ἀποβῶσιν οἱ πολέμιοι καὶ γένηται τὸ πλοῖον ὑποχείριον. οὕτω δὴ τούτων πραττομένων, ὑπαχθέντες οἱ Μεγαρεῖς τῇ ὄψει καὶ προσμίξαντες ἐγγύς, ἐξεπήδων ὡς ἐπὶ γυναῖκας, ἁμιλλώμενοι πρὸς ἀλλήλους, ὥστε μηδένα διαφυγεῖν, ἀλλὰ πάντας ἀπολέσθαι, καὶ τὴν νῆσον ἐπιπλεύσαντας εὐθὺς ἔχειν τοὺς Ἀθηναίους.", "st": "Sol. 8.4"}, {"sp": "N", "t": "ἄλλοι δέ φασιν οὐ τοῦτον τὸν τρόπον γενέσθαι τὴν κατάληψιν, ἀλλὰ πρῶτον μὲν αὐτῷ τὸν ἐν Δελφοῖς θεὸν χρῆσαι·", "st": "Sol. 9.1"}, {"sp": "N", "t": "ἀρχηγοὺς χώρας θυσίαις ἥρωας ἐνοίκους<br>ἵλασο, τοὺς κόλποις Ἀσωπιὰς ἀμφικαλύπτει,<br>οἳ φθίμενοι δέρκονται ἐς ἠέλιον δύνοντα·", "st": "Sol. 9.1b"}, {"sp": "N", "t": "τὸν δὲ Σόλωνα διαπλεύσαντα νυκτὸς εἰς τὴν νῆσον ἐντεμεῖν σφάγια Περιφήμῳ καὶ Κυχρεῖ τοῖς ἥρωσιν. εἶτα παρὰ τῶν Ἀθηναίων ἐθελοντὰς λαβεῖν πεντακοσίους, δόγματος γενομένου τούτους, ἄν κατασχῶσι τὴν νῆσον, κυρίους εἶναι τοῦ πολιτεύματος. ἀναχθέντα δὲ συχναῖς ἁλιάσιν ἅμα τριακοντόρου συμπαραπλεούσης ὑφορμίσασθαι τῇ Σαλαμῖνι κατὰ χηλήν τινα πρὸς τὴν Εὔβοιαν ἀποβλέπουσαν. πυθομένους δὲ τοὺς ἐν Σαλαμῖνι Μεγαρεῖς ἔκ τινος φήμης οὐδὲν βέβαιον, αὐτοὺς μὲν εἰς τὰ ὅπλα θορυβουμένους βαδίζειν, ναῦν δ’ ἀποστεῖλαι κατασκεψομένην τῶν πολεμίων· ἧς ἐγγὺς ἐλθούσης κρατῆσαι τὸν Σόλωνα καὶ καθεῖρξαι τοὺς Μεγαρεῖς. ἐμβιβάσαι δὲ τῶν Ἀθηναίων τοὺς κρατίστους κελεύσαντα πλεῖν ἐπὶ τὴν πόλιν, ὡς ἂν ἐνδέχηται μάλιστα κρύπτοντας ἑαυτούς· ἅμα δὲ τοὺς ἄλλους Ἀθηναίους ἀναλαβόντα πεζῇ συμφέρεσθαι τοῖς Μεγαρεῦσι· καὶ τῆς μάχης ἔτι συνεστώσης φθάσαι τοὺς ἀπὸ τῆς νεὼς καταλαβόντας τὴν πόλιν.", "st": "Sol. 9.2"}, {"sp": "N", "t": "ἔοικε δὲ τῷ λόγῳ τούτῳ καὶ τὰ δρώμενα μαρτυρεῖν. ναῦς γάρ τις Ἀττικὴ προσέπλει σιωπῇ τὸ πρῶτον, εἶτα κραυγῇ καὶ ἀλαλαγμῷ προσφερομένων εἷς ἀνήρ ἔνοπλος ἐξαλλόμενος μετὰ βοῆς ἔθει πρὸς ἄκρον τὸ Σκιράδιον ἐκ γῆς προσφερομένοις. πλησίον δὲ τοῦ Ἐνυαλίου τὸ ἱερόν ἐστιν ἱδρυσαμένου Σόλωνος. ἐνίκησε γὰρ τοὺς Μεγαρέας, καὶ ὅσοι μὴ διεφθάρησαν ἐν τῇ μάχῃ, πάντας ὑποσπόνδους ἀφῆκεν.", "st": "Sol. 9.4"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τῶν Μεγαρέων ἐπιμενόντων πολλὰ κακὰ καὶ δρῶντες ἐν τῷ πολέμῳ καὶ πάσχοντες, ἐποιήσαντο Λακεδαιμονίους διαλλακτὰς καὶ δικαστάς. οἱ μὲν οὖν πολλοὶ τῷ Σόλωνι συναγωνίσασθαι λέγουσι τὴν Ὁμήρου δόξαν· ἐμβαλόντα γὰρ αὐτὸν ἔπος εἰς νεῶν κατάλογον ἐπὶ τῆς δίκης ἀναγνῶναι·", "st": "Sol. 10.1"}, {"sp": "N", "t": "Αἴας δ’ ἐκ Σαλαμῖνος ἄγεν δυοκαίδεκα νῆας,<br>στῆσε δ’ ἄγων ἵν’ Ἀθηναίων ἵσταντο φάλαγγες.", "st": "Sol. 10.1b"}, {"sp": "N", "t": "αὐτοὶ δ’ Ἀθηναῖοι ταῦτα μὲν οἴονται φλυαρίαν εἶναι, τὸν δὲ Σόλωνά φασιν ἀποδεῖξαι τοῖς δικασταῖς ὅτι Φιλαῖος καὶ Εὐρυσάκης, Αἴαντος υἱοί, Ἀθήνησι πολιτείας μεταλαβόντες παρέδοσαν τὴν νῆσον αὐτοῖς, καὶ κατῴκησαν ὁ μὲν ἐν Βραυρῶνι τῆς Ἀττικῆς, ὁ δὲ ἐν Μελίτῃ· καὶ δῆμον ἐπώνυμον Φιλαίου τῶν Φιλαϊδῶν ἔχουσιν, ὅθεν ἦν Πεισίστρατος. ἔτι δὲ μᾶλλον ἐξελέγξαι τοὺς Μεγαρέας βουλόμενον ἰσχυρίσασθαι περὶ τῶν νεκρῶν ὡς οὐχ ὃν τρόπον ἐκεῖνοι θάπτουσι κεκηδευμένων, ἀλλ’ ὃν αὐτοί. θάπτουσι δὲ Μεγαπεῖς πρὸς ἕω τοὺς νεκροὺς στρέφοντες, Ἀθηναῖοι δὲ πρὸς ἑσπέραν. Ἡρέας δὲ ὁ Μεγαρεὺς ἐνιστάμενος λέγει καὶ Μεγαρεῖς πρὸς ἑσπέραν τετραμμένα τὰ σώματα τῶν νεκρῶν τιθέναι· καὶ μεῖζον ἔτι τούτου, μίαν ἕκαστον Ἀθηναίων ἔχειν θήκην, Μεγαρέων δὲ καὶ τρεῖς καὶ τέσσαρας ἐν μιᾷ κεῖσθαι. τῷ μέντοι Σόλωνι καὶ Πυθικούς τινας βοηθῆσαι λέγουσι χρησμούς, ἐν οἷς ὁ θεὸς Ἰαονίαν τὴν Σαλαμῖνα προσηγόρευσε. ταύτην τὴν δίκην ἐδίκασαν Σπαρτιατῶν πέντε ἄνδρες, Κριτολαΐδας, Ἀμομφάρετος, Ὑψηχίδας, Ἀναξίλας, Κλεομένης.", "st": "Sol. 10.2"}, {"sp": "N", "t": "ἤδη μὲν οὖν καὶ ἀπὸ τούτων ἔνδοξος ἦν ὁ Σόλων καὶ μέγας. ἐθαυμάσθη δὲ καὶ διεβοήθη μᾶλλον ἐν τοῖς Ἕλλησιν εἰπὼν ὑπὲρ τοῦ ἱεροῦ τοῦ ἐν Δελφοῖς, ὡς χρὴ βοηθεῖν καὶ μὴ περιορᾶν Κιρραίους ὑβρίζοντας εἰς τὸ μαντεῖον, ἀλλὰ προσαμύνειν ὑπὲρ τοῦ θεοῦ Δελφοῖς. πεισθέντες γὰρ ὑπ’ ἐκείνου πρὸς τὸν πόλεμον ὥρμησαν οἱ Ἀμφικτύονες, ὡς ἄλλοι τε μαρτυροῦσι καὶ Ἀριστοτέλης ἐν τῇ τῶν Πυθιονικῶν ἀναγραφῇ Σόλωνι τὴν γνώμην ἀνατιθείς. οὐ μέντοι στρατηγὸς ἐπὶ τοῦτον ἀπεδείχθη τὸν πόλεμον, ὡς λέγειν φησὶν Ἕρμιππος Εὐάνθη τὸν Σάμιον· οὔτε γὰρ Αἰσχίνης ὁ ῥήτωρ τοῦτ’ εἴρηκεν, ἔν τε τοῖς Δελφῶν ὑπομνήμασιν Ἀλκμαίων, οὐ Σόλων, Ἀθηναίων στρατηγὸς ἀναγέγραπται.", "st": "Sol. 11.1"}, {"sp": "N", "t": "τὸ δὲ Κυλώνειον ἄγος ἤδη μὲν ἐκ πολλοῦ διετάραττε τὴν πόλιν, ἐξ οὗ τοὺς συνωμότας τοῦ Κύλωνος ἱκετεύοντας τὴν θεὸν Μεγακλῆς ὁ ἄρχων ἐπὶ δίκῃ κατελθεῖν ἔπεισεν· ἐξάψαντας δὲ τοῦ ἕδους κρόκην κλωστὴν καὶ ταύτης ἐχομένους, ὡς ἐγένοντο περὶ τὰς σεμνὰς θεὰς καταβαίνοντες, αὐτομάτως τῆς κρόκης ῥαγείσης, ὥρμησε συλλαμβάνειν ὁ Μεγακλῆς καὶ οἱ συνάρχοντες, ὡς τῆς θεοῦ τὴν ἱκεσίαν ἀπολεγομένης· καὶ τοὺς μὲν ἔξω κατέλευσαν, οἱ δὲ τοῖς βωμοῖς προσφυγόντες ἀπεσφάγησαν· μόνοι δ’ ἀφείθησαν οἱ τὰς γυναῖκας αὐτῶν ἱκετεύσαντες. ἐκ τούτου δὲ κληθέντες ἐναγεῖς ἐμισοῦντο· καὶ τῶν Κυλωνείων οἱ περιγενόμενοι πάλιν ἦσαν ἰσχυροί, καὶ στασιάζοντες ἀεὶ διετέλουν πρὸς τοὺς ἀπὸ τοῦ Μεγακλέους. ἐν δὲ τῷ τότε χρόνῳ τῆς στάσεως ἀκμὴν λαβούσης μάλιστα καὶ τοῦ δήμου διαστάντος, ἤδη δόξαν ἔχων ὁ Σόλων παρῆλθεν εἰς μέσον ἅμα τοῖς ἀρίστοις τῶν Ἀθηναίων, καὶ δεόμενος καὶ διδάσκων ἔπεισε τοὺς ἐναγεῖς λεγομένους δίκην ὑποσχεῖν καὶ κριθῆναι τριακοσίων ἀριστίνδην δικαζόντων. Μύρωνος δὲ τοῦ Φλυέως κατηγοροῦντος ἑάλωσαν οἱ ἄνδρες, καὶ μετέστησαν οἱ ζῶντες· τῶν δ’ ἀποθανόντων τοὺς νεκροὺς ἀνορύξαντες ἐξέρριψαν ὑπὲρ τοὺς ὅρους. ταύταις δὲ ταῖς ταραχαῖς καὶ Μεγαρέων συνεπιθεμένων ἀπέβαλόν τε Νίσαιαν οἱ Ἀθηναῖοι καὶ Σαλαμῖνος ἐξέπεσον αὖθις. καὶ φόβοι τινὲς ἐκ δεισιδαιμονίας ἅμα καὶ φάσματα κατεῖχε τὴν πόλιν, οἵ τε μάντεις ἄγη καὶ μιασμοὺς δεομένους καθαρμῶν προφαίνεσθαι διὰ τῶν ἱερῶν ἠγόρευον.", "st": "Sol. 12.1"}, {"sp": "N", "t": "οὕτω δὴ μετάπεμπτος αὐτοῖς ἧκεν ἐκ Κρήτης Ἐπιμενίδης ὁ Φαίστιος, ὃν ἕβδομον ἐν τοῖς σοφοῖς καταριθμοῦσιν ἔνιοι τῶν οὐ προσιεμένων τὸν Περίανδρον. ἐδόκει δέ τις εἶναι θεοφιλὴς καὶ σοφὸς περὶ τὰ θεῖα τὴν ἐνθουσιαστικὴν καὶ τελεστικὴν σοφίαν, διὸ καὶ παῖδα νύμφης ὄνομα Βάλτης καὶ Κούρητα νέον αὐτὸν οἱ τότε ἄνθρωποι προσηγόρευον. ἐλθὼν δὲ καὶ τῷ Σόλωνι χρησάμενος φίλῳ πολλὰ προσυπειργάσατο καὶ προωδοποίησεν αὐτῷ τῆς νομοθεσίας. καὶ γὰρ εὐσταλεῖς ἐποίησε τὰς ἱερουργίας καὶ περὶ τὰ πένθη πρᾳοτέρους, θυσίας τινὰς εὐθὺς ἀναμίξας πρὸς τὰ κήδη, καὶ τὸ σκληρὸν ἀφελὼν καὶ τὸ βαρβαρικὸν ᾧ συνείχοντο πρότερον αἱ πλεῖσται γυναῖκες. τὸ δὲ μέγιστον, ἱλασμοῖς τισι καὶ καθαρμοῖς καὶ ἱδρύσεσι κατοργιάσας καὶ καθοσιώσας τὴν πόλιν ὑπήκοον τοῦ δικαίου καὶ μᾶλλον εὐπειθῆ πρὸς ὁμόνοιαν κατέστησε. λέγεται δὲ τὴν Μουνυχίαν ἰδὼν καὶ καταμαθὼν πολὺν χρόνον, εἰπεῖν πρὸς τοὺς παρόντας ὡς τυφλόν ἐστι τοῦ μέλλοντος ἄνθρωπος· ἐκφαγεῖν γὰρ ἂν Ἀθηναίους τοῖς αὑτῶν ὀδοῦσιν, εἰ προῄδεσαν ὅσα τὴν πόλιν ἀνιάσει τὸ χωρίον· ὅμοιον δέ τι καὶ Θαλῆν εἰκάσαι λέγουσι· κελεῦσαι γὰρ αὐτὸν ἔν τινι τόπῳ τῆς Μιλησίας φαύλῳ καὶ παρορωμένῳ τελευτήσαντα θεῖναι, προειπὼν ὡς ἀγορά ποτε τοῦτο Μιλησίων ἔσται τὸ χωρίον. Ἐπιμενίδης μὲν οὖν μάλιστα θαυμασθείς, καὶ χρήματα διδόντων πολλὰ καὶ τιμὰς μεγάλας τῶν Ἀθηναίων, οὐδὲν ἢ θαλλὸν ἀπὸ τῆς ἱερᾶς ἐλαίας αἰτησάμενος καὶ λαβὼν ἀπῆλθεν.", "st": "Sol. 12.4"}, {"sp": "N", "t": "οἱ δ’ Ἀθηναῖοι τῆς Κυλωνείου πεπαυμένης ταραχῆς καὶ μεθεστώτων, ὥσπερ εἴρηται, τῶν ἐναγῶν, τὴν παλαιᾶν αὖθις στάσιν ὑπὲρ τῆς πολιτείας ἐστασίαζον, ὅσας ἡ χώρα διαφορὰς εἶχεν, εἰς τοσαῦτα μέρη τῆς πόλεως διαστάσης. ἦν γὰρ τὸ μὲν τῶν Διακρίων γένος δημοκρατικώτατον, ὀλιγαρχικώτατον δὲ τὸ τῶν Πεδιέων· τρίτοι δ’ οἱ Πάραλοι μέσον τινὰ καὶ μεμιγμένον αἱρούμενοι πολιτείας τρόπον, ἐμποδὼν ἦσαν καὶ διεκώλυον τοὺς ἑτέρους κρατῆσαι. τότε δὲ τῆς τῶν πενήτων πρὸς τοὺς πλουσίους ἀνωμαλίας ὥσπερ ἀκμὴν λαβούσης παντάπασιν ἐπισφαλῶς ἡ πόλις διέκειτο, καὶ μόνως ἂν ἐδόκει καταστῆναι καὶ παύσασθαι ταραττομένη τυραννίδος γενομένης. ἅπας μὲν γὰρ ὁ δῆμος ἦν ὑπόχρεως τῶν πλουσίων. ἢ γὰρ ἐγεώργουν ἐκείνοις ἕκτα τῶν γινομένων τελοῦντες, ἑκτημόριοι προσαγορευόμενοι καὶ θῆτες, ἢ χρέα λαμβάνοντες ἐπὶ τοῖς σώμασιν ἀγώγιμοι τοῖς δανείζουσιν ἦσαν, οἱ μὲν αὐτοῦ δουλεύοντες, οἱ δ’ ἐπὶ τὴν ξένην πιπρασκόμενοι. πολλοὶ δὲ καὶ παῖδας ἰδίους ἠναγκάζοντο πωλεῖν (οὐδεὶς γὰρ νόμος ἐκώλυε) καὶ τὴν πόλιν φεύγειν διὰ τὴν χαλεπότητα τῶν δανειστῶν. οἱ δὲ πλεῖστοι καὶ ῥωμαλεώτατοι συνίσταντο καὶ παρεκάλουν ἀλλήλους μὴ περιορᾶν, ἀλλ’ ἑλομένους ἕνα προστάτην ἄνδρα πιστὸν ἀφελέσθαι τοὺς ὑπερημέρους καὶ τὴν γῆν ἀναδάσασθαι καὶ ὅλως μεταστῆσαι τὴν πολιτείαν.", "st": "Sol. 13.1"}, {"sp": "N", "t": "ἐνταῦθα δὴ τῶν Ἀθηναίων οἱ φρονιμώτατοι συνορῶντες τὸν Σόλωνα μόνον μάλιστα τῶν ἁμαρτημάτων ἐκτὸς ὄντα, καὶ μήτε τοῖς πλουσίοις κοινωνοῦντα τῆς ἀδικίας μήτε ταῖς τῶν πενήτων ἀνάγκαις ἐνεχόμενον, ἐδέοντο τοῖς κοινοῖς προσελθεῖν καὶ καταπαῦσαι τὰς διαφοράς. καίτοι Φανίας ὁ Λέσβιος αὐτὸν ἱστορεῖ τὸν Σόλωνα, χρησάμενον ἀπάτῃ πρὸς ἀμφοτέρους ἐπὶ σωτηρίᾳ τῆς πόλεως, ὑποσχέσθαι κρύφα τοῖς μὲν ἀπόροις τὴν νέμησιν, τοῖς δὲ χρηματικοῖς βεβαίωσιν τῶν συμβολαίων. ἀλλ’ αὐτὸς ὁ Σόλων ὀκνῶν φησι τὸ πρῶτον ἅψασθαι τῆς πολιτείας, καὶ δεδοικὼς τῶν μὲν τὴν φιλοχρηματίαν, τῶν δὲ τὴν ὑπερηφανίαν. ᾑρέθη δὲ ἄρχων μετὰ Φιλόμβροτον ὁμοῦ καὶ διαλλακτὴς καὶ νομοθέτης, δεξαμένων προθύμως αὐτὸν ὡς μὲν εὔπορον τῶν πλουσίων, ὡς δὲ χρηστὸν τῶν πενήτων. λέγεται δὲ καὶ φωνή τις αὐτοῦ περιφερομένη πρότερον, εἰπόντος ὡς τὸ ἴσον πόλεμον οὐ ποιεῖ, καὶ τοῖς κτηματικοῖς ἀρέσκειν καὶ τοῖς ἀκτήμοσι, τῶν μὲν ἀξίᾳ καὶ ἀρετῇ, τῶν δὲ μέτρῳ καὶ ἀριθμῷ τὸ ἴσον ἕξειν προσδοκώντων· ὅθεν ἐπ’ ἐλπίδος μεγάλης ἑκατέρων γενομένων οἱ προϊστάμενοι προσέκειντο τῷ Σόλωνι τυραννίδα προξενοῦντες καὶ ἀναπείθοντες εὐτολμότερον ἅψασθαι τῆς πόλεως ἐγκρατῆ γενόμενον. πολλοὶ δὲ καὶ τῶν διὰ μέσου πολιτῶν, τὴν ὑπὸ λόγου καὶ νόμου μεταβολὴν ὁρῶντες ἐργώδη καὶ χαλεπὴν οὖσαν, οὐκ ἔφευγον ἕνα τὸν δικαιότατον καὶ φρονιμώτατον ἐπιστῆσαι τοῖς πράγμασιν. ἔνιοι δέ φασι καὶ μαντείαν γενέσθαι τῷ Σόλωνι Πυθοῖ τοιαύτην·", "st": "Sol. 14.1"}, {"sp": "N", "t": "ἧσο μέσην κατὰ νῆα κυβερνητήριον ἔργον<br>εὐθύνων· πολλοί τοι Ἀθηναίων ἐπίκουροι.", "st": "Sol. 14.1b"}, {"sp": "N", "t": "μάλιστα δὲ οἱ συνήθεις ἐκάκιζον εἰ διὰ τοὔνομα δυσωπεῖται τὴν μοναρχίαν, ὥσπερ οὐκ ἀρετῇ τοῦ λαβόντος εὐθὺς ἂν βασιλείαν γενομένην, καὶ γεγενημένην πρότερον μὲν Εὐβοεῦσι Τυννώνδαν, νῦν δὲ Μιτυληναίοις Πιττακὸν ᾑρημένοις τύραννον.", "st": "Sol. 14.1c"}, {"sp": "N", "t": "τούτων οὐδὲν ἐξέκρουσε τὸν Σόλωνα τῆς αὑτοῦ προαιρέσεως, ἀλλὰ πρὸς μὲν τοὺς φίλους εἶπεν, ὡς λέγεται, καλὸν μὲν εἶναι τὴν τυραννίδα χωρίον, οὐκ ἔχειν δὲ ἀπόβασιν, πρὸς δὲ Φῶκον ἐν τοῖς ποιήμασι γράφων·", "st": "Sol. 14.5"}, {"sp": "N", "t": "εἰ δὲ γῆς (φησίν) ἐφεισάμην<br>πατρίδος, τυραννίδος δὲ καὶ βίης ἀμειλίχου<br>οὐ καθηψάμην μιάνας καὶ καταισχύνας κλέος,<br>οὐδὲν αἰδεῦμαι· πλέον γὰρ ὧδε νικήσειν δοκέω πάντας ἀνθρώπους.", "st": "Sol. 14.5b"}, {"sp": "N", "t": "ὅθεν εὔδηλον ὅτι καὶ πρὸ τῆς νομοθεσίας μεγάλην δόξαν εἶχεν. ἃ δὲ φυγόντος αὐτοῦ τὴν τυραννίδα πολλοὶ καταγελῶντες ἔλεγον, γέγραφεν οὕτως·", "st": "Sol. 14.6"}, {"sp": "N", "t": "οὐκ ἔφυ Σόλων βαθύφρων οὐδὲ βουλήεις ἀνήρ·<br>ἐσθλὰ γὰρ θεοῦ διδόντος αὐτὸς οὐκ ἐδέξατο.", "st": "Sol. 14.6b"}, {"sp": "N", "t": "περιβαλὼν δ’ ἄγραν ἀγασθεὶς οὐκ ἐπέσπασεν μέγα<br>δίκτυον, θυμοῦ θ’ ἁμαρτῇ καὶ φρενῶν ἀποσφαλείς.", "st": "Sol. 14.6c"}, {"sp": "N", "t": "ἤθελον γάρ κεν κρατήσας, πλοῦτον ἄφθονον λαβὼν<br>καὶ τυραννεύσας Ἀθηνῶν μοῦνον ἡμέραν μίαν,<br>ἀσκὸς ὕστερον δεδάρθαι κἀπιτετρῖφθαι γένος.", "st": "Sol. 14.6d"}, {"sp": "N", "t": "ταῦτα τοὺς πολλοὺς καὶ φαύλους περὶ αὐτοῦ πεποίηκε λέγοντας. οὐ μὴν ἀπωσάμενός γε τὴν τυραννίδα τὸν πρᾳότατον ἐχρήσατο τρόπον τοῖς πράγμασιν, οὐδὲ μαλακῶς οὐδ’ ὑπείκων τοῖς δυναμένοις οὐδὲ πρὸς ἡδονὴν τῶν ἑλομένων ἔθετο τοὺς νόμους· ἀλλ’ ᾗ μὲν ἄριστον ἦν, οὐκ ἐπήγαγεν ἰατρείαν οὐδὲ καινοτομίαν, φοβηθεὶς μὴ συγχέας παντάπασι καὶ ταράξας τὴν πόλιν ἀσθενέστερος γένηται τοῦ καταστῆσαι πάλιν καὶ συναρμόσασθαι πρὸς τὸ ἄριστον· ἃ δὲ καὶ λέγων ἤλπιζε πειθομένοις καὶ προσάγων ἀνάγκην ὑπομένουσι χρήσασθαι, ταῦτ’ ἔπραττεν, ὥς φησιν αὐτός,", "st": "Sol. 15.1"}, {"sp": "N", "t": "ὁμοῦ βίην τε καὶ δίκην συναρμόσας.", "st": "Sol. 15.1b"}, {"sp": "N", "t": "ὅθεν ὕστερον ἐρωτηθεὶς εἰ τοὺς ἀρίστους Ἀθηναίοις νόμους ἔγραψεν, ὧν ἄν, ἔφη, προσεδέξαντο τοὺς ἀρίστους.", "st": "Sol. 15.1c"}, {"sp": "N", "t": "ἃ δ’ οὖ οἱ νεώτεροι τοὺς Ἀθηναίους λέγουσι τὰς τῶν πραγμάτων δυσχερείας ὀνόμασι χρηστοῖς καὶ φιλανθρώποις ἐπικαλύπτοντας ἀστείως ὑποκορίζεσθαι, τὰς μὲν πόρνας ἑταίρας, τοὺς δὲ φόρους συντάξεις, φυλακὰς δὲ τὰς φρουρὰς τῶν πόλεων, οἴκημα δὲ τὸ δεσμωτήριον καλοῦντας, πρώτου Σόλωνος ἦν, ὡς ἔοικε, σόφισμα τὴν τῶν χρεῶν ἀποκοπὴν σεισάχθειαν ὀνομάσαντος. τοῦτο γὰρ ἐποιήσατο πρῶτον πολίτευμα, γράψας τὰ μὲν ὑπάρχοντα τῶν χρεῶν ἀνεῖσθαι, πρὸς δὲ τὸ λοιπὸν ἐπὶ τοῖς σώμασι μηδένα δανείζειν. καίτοι τινὲς ἔγραψαν, ὧν ἐστὶν Ἀνδροτίων, οὐκ ἀποκοπῇ χρεῶν, ἀλλὰ τόκων μετριότητι κουφισθέντας ἀγαπῆσαι τοὺς πένητας, καὶ σεισάχθειαν ὀνομάσαι τὸ φιλανθρώπευμα τοῦτο καὶ τὴν ἅμα τούτῳ γενομένην τῶν τε μέτρων ἐπαύξησιν καὶ τοῦ νομίσματος τιμήν. ἑκατὸν γὰρ ἐποίησε δραχμῶν τὴν μνᾶν πρότερον ἑβδομήκοντα καὶ τριῶν οὖσαν, ὥστ’ ἀριθμῷ μὲν ἴσον, δυνάμει δ’ ἔλαττον ἀποδιδόντων, ὠφελεῖσθαι μὲν τοὺς ἐκτίνοντας μεγάλα, μηδὲν δὲ βλάπτεσθαι τοὺς κομιζομένους. οἱ δὲ πλεῖστοι πάντων ὁμοῦ φασι τῶν συμβολαίων ἀναίρεσιν γενέσθαι τὴν σεισάχθειαν, καὶ τούτοις συνᾴδει μᾶλλον τὰ ποιήματα. σεμνύνεται γὰρ Σόλων ἐν τούτοις ὅτι τῆς τε προϋποκειμένης γῆς", "st": "Sol. 15.3"}, {"sp": "N", "t": "ὅρους ἀνεῖλε πολλαχῆ πεπηγότας·<br>πρόσθεν δὲ δουλεύουσα, νῦν ἐλευθέρα·", "st": "Sol. 15.3b"}, {"sp": "N", "t": "καὶ τῶν ἀγωγίμων πρὸς ἀργύριον γεγονότων πολιτῶν τοὺς μὲν ἀνήγαγεν ἀπὸ ξένης,", "st": "Sol. 15.3c"}, {"sp": "N", "t": "γλῶσσαν οὐκέτ’ Ἀττικὴν<br>ἱέντας, ὡς ἂν πολλαχῆ πλανωμένους·<br>τοὺς δ’ ἐνθάδ’ αὐτοῦ δουλίην ἀεικέα ἔχοντας<br>ἐλευθέρους φησὶ ποιῆσαι.", "st": "Sol. 15.3d"}, {"sp": "N", "t": "πρᾶγμα δ’ αὐτῷ συμπεσεῖν λέγεται πάντων ἀνιαρότατον ἀπὸ τῆς πράξεως ἐκείνης. ὡς γὰρ ὥρμησεν ἀνιέναι τὰ χρέα καὶ λόγους ἁρμόττοντας ἐζήτει καὶ πρέπουσαν ἀρχήν, ἐκοινώσατο τῶν φίλων οἷς μάλιστα πιστεύων καὶ χρώμενος ἐτύγχανε, τοῖς περὶ Κόνωνα καὶ Κλεινίαν καὶ Ἱππόνικον, ὅτι γῆν μὲν οὐ μέλλει κινεῖν, χρεῶν δὲ ποιεῖν ἀποκοπὰς ἔγνωκεν. οἱ δὲ προλαβόντες εὐθὺς καὶ φθάσαντες ἐδανείσαντο συχνὸν ἀργύριον παρὰ τῶν πλουσίων καὶ μεγάλας συνεωνήσαντο χώρας. εἶτα τοῦ δόγματος ἐξενεχθέντος τὰ μὲν κτήματα καρπούμενοι, τὰ δὲ χρήματα τοῖς δανείσασιν οὐκ ἀποδιδόντες, εἰς αἰτίαν τὸν Σόλωνα μεγάλην καὶ διαβολήν, ὥσπερ οὐ συναδικούμενον, ἀλλὰ συναδικοῦντα, κατέστησαν. ἀλλὰ τοῦτο μὲν εὐθὺς ἐλύθη τὸ ἔγκλημα τοῖς πέντε ταλάντοις· τοσαῦτα γὰρ εὑρέθη δανείζων, καὶ ταῦτα πρῶτος ἀφῆκε κατὰ τὸν νόμον. ἔνιοι δὲ πεντεκαίδεκα λέγουσιν, ὧν καὶ Πολύζηλος ὁ Ῥόδιός ἐστι. τοὺς μέντοι φίλους αὐτοῦ χρεωκοπίδας καλοῦντες διετέλεσαν.", "st": "Sol. 15.6"}, {"sp": "N", "t": "ἤρεσε δ’ οὐδετέροις, ἀλλ’ ἐλύπησε καὶ τοὺς πλουσίους ἀνελὼν τὰ συμβόλαια, καὶ μᾶλλον ἔτι τοὺς πένητας, ὅτι γῆς ἀναδασμὸν οὐκ ἐποίησεν ἐλπίσασιν αὐτοῖς, οὐδὲ παντάπασιν, ὥσπερ ὁ Λυκοῦργος, ὁμαλοὺς τοῖς βίοις καὶ ἴσους κατέστησεν. ἀλλ’ ἐκεῖνος μὲν ἑνδέκατος ὢν ἀφ’ Ἡρακλέους καὶ βεβασιλευκὼς ἔτη πολλὰ τῆς Λακεδαίμονος, ἀξίωμα μέγα καὶ φίλους καὶ δύναμιν οἷς ἔγνω καλῶς περὶ τῆς πολιτείας ὑπηρετοῦσαν εἶχε, καὶ βίᾳ μᾶλλον ἢ πειθοῖ χρησάμενος, ὥστε καὶ τὸν ὀφθαλμὸν ἐκκοπῆναι, κατειργάσατο τὸ μέγιστον εἰς σωτηρίαν πόλεως καὶ ὁμόνοιαν, μηδένα πένητα μηδὲ πλούσιον εἶναι τῶν πολιτῶν· σόλων δὲ τούτου μὲν οὐκ ἐφίκετο τῇ πολιτεία δημοτικὸς ὢν καὶ μέσος, ἐνδεέστερον δὲ τῆς ὑπαρχούσης δυνάμεως οὐδὲν ἔπαξεν, ὁρμώμενος ἐκ μόνου τοῦ βούλεσθαι καὶ πιστεύειν αὐτῷ τοὺς πολίτας. ὅτι δ’ οὖν προσέκρουσε τοῖς πλείστοις ἕτερα προσδοκήσασιν, αὐτὸς εἴρηκε περὶ αὐτῶν, ὡς", "st": "Sol. 16.1"}, {"sp": "N", "t": "χαῦνα μὲν τότ’ ἐφράσαντο, νῦν δέ μοι χολούμενοι<br>λοξὸν ὀφθαλμοῖς ὁρῶσι πάντες ὥστε δήϊον.", "st": "Sol. 16.1b"}, {"sp": "N", "t": "καίτοι φησὶν ὡς, εἴ τις ἄλλος ἔσχε τὴν αὐτὴν δύναμιν,<br>οὐκ ἂν κατέσχε δῆμον, οὐδ’ ἐπαύσατο,<br>πρὶν ἀνταράξας, πῖαρ ἐξεῖλεν γάλα.", "st": "Sol. 16.1c"}, {"sp": "N", "t": "ταχὺ μέντοι τοῦ συμφέροντος αἰσθόμενοι καὶ τὰς ἰδίας αὑτῶν μέμψεις ἀφέντες ἔθυσάν τε κοινῇ, σεισάχθειαν τὴν θυσίαν ὀνομάσαντες, καὶ τὸν Σόλωνα τῆς πολιτείας διορθωτὴν καὶ νομοθέτην ἀπέδειξαν, οὐ τὰ μέν, τὰ δ’ οὐχί, πάντα δ’ ὁμαλῶς ἐπιτρέψαντες, ἀρχάς, ἐκκλησίας, δικαστήρια, βουλάς, καί τίμημα τούτων ἑκάστου καὶ ἀριθμὸν καὶ καιρὸν ὁρίσαι, λύοντα καὶ φυλάττοντα τῶν ὑπαρχόντων καὶ καθεστώτων ὅ τι δοκοίη.", "st": "Sol. 16.3"}, {"sp": "N", "t": "πρῶτον μὲν οὖν τοὺς Δράκοντος νόμους ἀνεῖλε πλὴν τῶν φονικῶν ἅπαντας, διὰ τὴν χαλεπότητα καὶ τὸ μέγεθος τῶν ἐπιτιμίων. μία γὰρ ὀλίγου δεῖν ἅπασιν ὥριστο τοῖς ἁμαρτάνουσι ζημία θάνατος, ὥστε καὶ τοὺς ἀργίας ἁλόντας ἀποθνήσκειν, καὶ τοὺς λάχανα κλέψαντας ἢ ὀπώραν ὁμοίως κολάζεσθαι τοῖς ἱεροσύλοις καὶ ἀνδροφόνοις. διὸ Δημάδης ὕστερον εὐδοκίμησεν εἰπὼν ὅτι δι’ αἵματος, οὐ διὰ μέλανος, τοὺς νόμους ὁ Δράκων ἔγραψεν. αὐτὸς δ’ ἐκεῖνος, ὥς φασιν, ἐρωτώμενος διὰ τί τοῖς πλείστοις ἀδικήμασι ζημίαν ἔταξε θάνατον, ἀπεκρίνατο τὰ μὲν μικρὰ ταύτης ἄξια νομίζειν, τοῖς δὲ μεγάλοις οὐκ ἔχειν μείζονα.", "st": "Sol. 17.1"}, {"sp": "N", "t": "δεύτερον δὲ Σόλων τὰς μὲν ἀρχὰς ἁπάσας, ὥσπερ ἦσαν, τοῖς εὐπόροις ἀπολιπεῖν βουλόμενος, τὴν δ’ ἄλλην μῖξαι πολιτείαν, ἧς ὁ δῆμος οὐ μετεῖχεν, ἔλαβε τὰ τιμήματα τῶν πολιτῶν, καὶ τοὺς μὲν ἐν ξηροῖς ὁμοῦ καὶ ὑγροῖς μέτρα πεντακόσια ποιοῦντας πρώτους ἔταξε καὶ πεντακοσιομεδίμνους προσηγόρευσε· δευτέρους δὲ τοὺς ἵππον τρέφειν δυναμένους ἢ μέτρα ποιεῖν τριακόσια· καὶ τούτους ἱππάδα τελοῦντας ἐκάλουν· ζευγῖται δ’ οἱ τοῦ τρίτου τιμήματος ὠνομάσθησαν, οἷς μέτρον ἦν συναμφοτέρων διακοσίων. οἱ δὲ λοιποὶ πάντες ἐκαλοῦντο θῆτες, οἷς οὐδεμίαν ἄρχειν ἔδωκεν ἀρχήν, ἀλλὰ τῷ συνεκκλησιάζειν καὶ δικάζειν μόνον μετεῖχον τῆς πολιτείας. ὃ κατ’ ἀρχὰς μὲν οὐδέν, ὕστερον δὲ παμμέγεθες ἐφάνη· τὰ γὰρ πλεῖστα τῶν διαφόρων ἐνέπιπτεν εἰς τοὺς δικαστάς. καὶ γὰρ ὅσα ταῖς ἀρχαῖς ἔταξε κρίνειν, ὁμοίως καὶ περὶ ἐκείνων εἰς τὸ δικαστήριον ἐφέσεις ἔδωκε τοῖς βουλομένοις. λέγεται δὲ καὶ τοὺς νόμους ἀσαφέστερον γράψας καὶ πολλὰς ἀντιλήψεις ἔχοντας αὐξῆσαι τὴν τῶν δικαστηρίων ἰσχύν· μὴ δυναμένους γὰρ ὑπὸ τῶν νόμων διαλυθῆναι περὶ ὧν διεφέροντο, συνέβαινεν ἀεὶ δεῖσθαι δικαστῶν καὶ πᾶν ἄγειν ἀμφισβήτημα πρὸς ἐκείνους, τρόπον τινὰ τῶν νόμων κυρίους ὄντας. ἐπισημαίνεται δ’ αὐτὸς αὑτῷ τὴν ἀξίωσιν οὕτως·", "st": "Sol. 18.1"}, {"sp": "N", "t": "δήμῳ μὲν γὰρ ἔδωκα τόσον κράτος ὅσσον ἀπαρκεῖ,<br>τιμῆς οὔτ’ ἀφελὼν οὔτ’ ἐπορεξάμενος·<br>οἳ δ’ εἶχον δύναμιν καὶ χρήμασιν ἦσαν ἀγητοί,<br>καὶ τοῖς ἐφρασάμην μηδὲν ἀεικὲς ἔχειν.", "st": "Sol. 18.1b"}, {"sp": "N", "t": "ἔστην δ’ ἀμφιβαλὼν κρατερὸν σάκος ἀμφοτέροισι·<br>νικᾶν δ’ οὐκ εἴασ’ οὐδετέρους ἀδίκως.", "st": "Sol. 18.1c"}, {"sp": "N", "t": "ἔτι μέντοι μᾶλλον οἰόμενος δεῖν ἐπαρκεῖν τῇ τῶν πολλῶν ἀσθενείᾳ, παντὶ λαβεῖν δίκην ὑπὲρ τοῦ κακῶς πεπονθότος ἔδωκε. καὶ γὰρ πληγέντος ἑτέρου καὶ βιασθέντος ἢ βλαβέντος ἐξῆν τῷ δυναμένῳ καὶ βουλομένῳ γράφεσθαι τὸν ἀδικοῦντα καὶ διώκειν, ὀρθῶς ἐθίζοντος τοῦ νομοθέτου τοὺς πολίτας ὥσπερ ἑνὸς μέρη σώματος συναισθάνεσθαι καὶ συναλγεῖν ἀλλήλοις. τούτῳ δὲ τῷ νόμῳ συμφωνοῦντα λόγον αὐτοῦ διαμνημονεύουσιν. ἐρωτηθεὶς γάρ, ὡς ἔοικεν, ἥτις οἰκεῖται κάλλιστα τῶν πόλεων, ἐκείνη, εἶπεν, ἐν ᾗ τῶν ἀδικουμένων οὐχ ἧττον οἱ μὴ ἀδικούμενοι προβάλλονται καὶ κολάζουσι τοὺς ἀδικοῦντας.", "st": "Sol. 18.5"}, {"sp": "N", "t": "συστησάμενος δὲ τὴν ἐν Ἀρείῳ πάγῳ βουλὴν ἐκ τῶν κατ’ ἐνιαυτὸν ἀρχόντων, ἧς διὰ τὸ ἄρξαι καὶ αὐτὸς μετεῖχεν, ἔτι δ’ ὁρῶν τὸν δῆμον οἰδοῦντα καὶ θρασυνόμενον τῇ τῶν χρεῶν ἀφέσει, δευτέραν προσκατένειμε βουλήν, ἀπὸ φυλῆς ἑκάστης, τεττάρων οὐσῶν, ἑκατὸν ἄνδρας ἐπιλεξάμενος, οὓς προβουλεύειν ἔταξε τοῦ δήμου καὶ μηδὲν ἐᾶν ἀπροβούλευτον εἰς ἐκκλησίαν εἰσφέρεσθαι. τὴν δ’ ἄνω βουλὴν ἐπίσκοπον πάντων καὶ φύλακα τῶν νόμων ἐκάθισεν, οἰόμενος ἐπὶ δυσὶ βουλαῖς ὥσπερ ἀγκύραις ὁρμοῦσαν ἧττον ἐν σάλῳ τὴν πόλιν ἔσεσθαι καὶ μᾶλλον ἀτρεμοῦντα τὸν δῆμον παρέξειν.", "st": "Sol. 19.1"}, {"sp": "N", "t": "οἱ μὲν οὖν πλεῖστοι τὴν ἐξ Ἀρείου πάγου βουλήν, ὥσπερ εἴρηται, Σόλωνα συστήσασθαί φασι· καὶ μαρτυρεῖν αὐτοῖς δοκεῖ μάλιστα τὸ μηδαμοῦ τὸν Δράκοντα λέγειν μηδ’ ὀνομάζειν Ἀρεοπαγίτας, ἀλλὰ τοῖς ἐφέταις ἀεὶ διαλέγεσθαι περὶ τῶν φονικῶν. ὁ δὲ τρισκαιδέκατος ἄξων τοῦ Σόλωνος τὸν ὄγδοον ἔχει τῶν νόμων οὕτως αὐτοῖς ὀνόμασι γεγραμμένον. ἀτίμων ὅσοι ἄτιμοι ἦσαν πρὶν ἢ Σόλωνα ἄρξαι, ἐπιτίμους εἶναι πλὴν ὅσοι ἐξ Ἀρείου πάγου ἢ ὅσοι ἐκ τῶν ἐφετῶν ἢ ἐκ πρυτανείου καταδικασθέντες ὑπὸ τῶν βασιλέων ἐπὶ φόνῳ ἢ σφαγαῖσιν ἢ ἐπὶ τυραννίδι ἔφευγον ὅτε ὁ θεσμὸς ἐφάνη ὅδε. ταῦτα δὴ πάλιν ὡς πρὸ τῆς Σόλωνος ἀρχῆς καὶ νομοθεσίας τὴν ἐξ Ἀρείου πάγου βουλὴν οὖσαν ἐνδείκνυται. τίνες γὰρ ἦσαν οἱ πρὸ Σόλωνος ἐν Ἀρείῳ πάγῳ καταδικασθέντες, εἰ πρῶτος Σόλων ἔδωκε τῇ ἐξ Ἀρείου πάγου βουλῇ τὸ κρίνειν; εἰ μὴ νὴ Δία γέγονέ τις ἀσάφεια τοῦ γράμματος ἢ ἔκλειψις, ὥστε τοὺς ἡλωκότας ἐπ’ αἰτίαις αἷς κρίνουσι νῦν οἱ Ἀρεοπαγῖται καὶ ἐφέται καὶ πρυτάνεις, ὅτε ὁ θεσμὸς ἐφάνη ὅδε, μένειν ἀτίμους, τῶν ἄλλων ἐπιτίμων γενομένων. ταῦτα μὲν οὖν καὶ αὐτὸς ἐπισκόπει.", "st": "Sol. 19.3"}, {"sp": "N", "t": "τῶν δ’ ἄλλων αὐτοῦ νόμων ἴδιος μὲν μάλιστα καὶ παράδοξος ὁ κελεύων ἄτιμον εἶναι τὸν ἐν στάσει μηδετέρας μερίδος γενόμενον. βούλεται δ’, ὡς ἔοικε, μὴ ἀπαθῶς μηδ’ ἀναισθήτως ἔχειν πρὸς τὸ κοινόν, ἐν ἀσφαλεῖ θέμενον τὰ οἰκεῖα καὶ τῷ μὴ συναλγεῖν μηδὲ συννοσεῖν τῇ πατρίδι καλλωπιζόμενον, ἀλλ’ αὐτόθεν τοῖς τὰ βελτίω καὶ δικαιότερα πράττουσι προσθέμενον, συγκινδυνεύειν καὶ βοηθεῖν, μᾶλλον ἢ περιμένειν ἀκινδύνως τὰ τῶν κρατούντων. ἄτοπος δὲ δοκεῖ καὶ γελοῖος ὁ τῇ ἐπικλήρῳ διδούς, ἂν ὁ κρατῶν καὶ κύριος γεγονὼς κατὰ τὸν νόμον αὐτὸς μὴ δυνατὸς ᾖ πλησιάζειν, ὑπὸ τῶν ἔγγιστα του ἀνδρὸς ὀπύεσθαι. καί τοῦτο δ’ ὀρθῶς ἔχειν τινές φασι πρός τοὺς μὴ δυναμένους συνεῖναι, χρημάτων δ’ ἕνεκα λαμβάνοντας ἐπικλήρους καὶ τῷ νόμῳ καταβιαζομένους τὴν φύσιν. ὁρῶντες γὰρ ᾧ βούλεται τὴν ἐπίκληρον συνοῦσαν ἢ προήσονται τὸν γάμον ἢ μετ’ αἰσχύνης καθέξουσι, φιλοπλουτίας καὶ ὕβρεως δίκην διδόντες. εὖ δ’ ἔχει καὶ τὸ μὴ πᾶσιν, ἀλλὰ τῶν συγγενῶν τοῦ ἀνδρὸς ᾧ βούλεται διαλέγεσθαι τὴν ἐπίκληρον, ὅπως οἰκεῖον ᾖ καὶ μετέχον τοῦ γένους τὸ τικτόμενον. εἰς τοῦτο δὲ συντελεῖ καὶ τὸ τὴν νύμφην τῷ νυμφίῳ συγκαθείργνυσθαι μήλου κυδωνίου κατατραγοῦσαν, καὶ τὸ τρὶς ἑκάστου μηνὸς ἐντυγχάνειν πάντως τῇ ἐπικλήρῳ τὸν λαβόντα. καὶ γὰρ εἰ μὴ γένοιντο παῖδες, ἀλλὰ τιμή τις ἀνδρὸς αὕτη πρὸς σώφρονα γυναῖκα, καὶ φιλοφροσύνη πολλὰ τῶν συλλεγομένων ἑκάστοτε δυσχερῶν ἀφαιροῦσα, καὶ ταῖς διαφοραῖς οὐκ ἐῶσα παντάπασιν ἀποστραφῆναι.", "st": "Sol. 20.1"}, {"sp": "N", "t": "τῶν δ’ ἄλλων γάμων ἀφεῖλε τὰς φερνάς, ἱμάτια τρία καὶ σκεύη μικροῦ νομίσματος ἄξια κελεύσας, ἕτερον δὲ μηδὲν ἐπιφέρεσθαι τὴν γαμουμένην. οὐ γὰρ ἐβούλετο μισθοφόρον οὐδ’ ὤνιον εἶναι τὸν γάμον, ἀλλ’ ἐπὶ τεκνώσει καὶ χάριτι καὶ φιλότητι γίνεσθαι τὸν ἀνδρὸς καὶ γυναικὸς συνοικισμόν. ὁ μὲν γὰρ Διονύσιος, ἀξιούσης τῆς μητρὸς αὐτοῦ δοθῆναί τινι τῶν πολιτῶν πρὸς γάμον, ἔφη τοὺς μὲν τῆς πόλεως νόμους λελυκέναι τυραννῶν, τοὺς δὲ τῆς φύσεως οὐκ εἶναι δυνατὸς βιάζεσθαι γάμους νυμφαγωγῶν παρ’ ἡλικίαν· ἐν δὲ ταῖς πόλεσι τὴν ἀταξίαν ταύτην οὐ δοτέον, οὐδὲ περιοπτέον ἀώρους καὶ ἀχαρίτους ἐπιπλοκὰς καὶ μηδὲν ἔργον γαμήλιον ἐχούσας μηδὲ τέλος. ἀλλὰ γέροντι νέαν ἀγομένῳ φαίη τις ἂν ἐμμελὴς ἄρχων ἢ νομοθέτης τὸ πρὸς τὸν Φιλοκτήτην·", "st": "Sol. 20.4"}, {"sp": "N", "t": "εὖ γοῦν ὡς γαμεῖν ἔχεις τάλας,", "st": "Sol. 20.4b"}, {"sp": "N", "t": "καὶ νέον ἐν δωματίῳ πλουσίας πρεσβύτιδος, ὥσπερ οἱ πέρδικες, ἀπὸ συνουσίας παχυνόμενον ἐξανευρὼν μετοικίσει πρὸς παρθένον νύμφην ἀνδρὸς δεομένην. ταῦτα μὲν οὖν περὶ τούτων.", "st": "Sol. 20.4c"}, {"sp": "N", "t": "ἐπαινεῖται δὲ τοῦ Σόλωνος καὶ ὁ κωλύων νόμος τὸν τεθνηκότα κακῶς ἀγορεύειν. καὶ γὰρ ὅσιον τοὺς μεθεστῶτας ἱεροὺς νομίζειν, καὶ δίκαιον ἀπέχεσθαι τῶν οὐχ ὑπαρχόντων, καὶ πολιτικὸν ἀφαιρεῖν τῆς ἔχθρας τὸ ἀΐδιον. ζῶντα δὲ κακῶς λέγειν ἐκώλυσε πρὸς ἱεροῖς καὶ δικαστηρίοις καὶ ἀρχείοις καὶ θεωρίας οὔσης ἀγώνων· ἤ τρεῖς δραχμὰς τῷ ἰδιώτῃ, δύο δ’ ἄλλας ἀποτίνειν εἰς τὸ δημόσιον ἔταξε. τὸ γὰρ μηδαμοῦ κρατεῖν ὀργῆς ἀπαίδευτον καὶ ἀκόλαστον· τὸ δὲ πανταχοῦ χαλεπόν, ἐνίοις δὲ ἀδύνατον· δεῖ δὲ πρὸς τὸ δυνατὸν γράφεσθαι τὸν νόμον, εἰ βούλεται χρησίμως ὀλίγους, ἀλλὰ μὴ πολλοὺς ἀχρήστως κολάζειν.", "st": "Sol. 21.1"}, {"sp": "N", "t": "εὐδοκίμησε δὲ κἀν τῷ περὶ διαθηκῶν νόμῳ· πρότερον γὰρ οὐκ ἐξῆν, ἀλλ’ ἐν τῷ γένει τοῦ τεθνηκότος ἔδει τὰ χρήματα καὶ τὸν οἶκον καταμένειν, ὁ δ’ ᾧ βούλεταί τις ἐπιτρέψας, εἰ μὴ παῖδες εἶεν αὐτῷ, δοῦναι τὰ αὑτοῦ, φιλίαν τε συγγενείας ἐτίμησε μᾶλλον καὶ χάριν ἀνάγκης, καὶ τὰ χρήματα κτήματα τῶν ἐχόντων ἐποίησεν. οὐ μὴν ἀνέδην γε πάλιν οὐδ’ ἁπλῶς τὰς δόσεις ἐφῆκεν, ἀλλ’ εἰ μὴ νόσων ἕνεκεν ἢ φαρμάκων ἢ δεσμῶν ἢ ἀνάγκῃ κατασχεθεὶς ἢ γυναικὶ πιθόμενος, εὖ πάνυ καὶ προσηκόντως τὸ πεισθῆναι παρὰ τὸ βέλτιστον οὐδὲν ἡγούμενος τοῦ βιασθῆναι διαφέρειν, ἀλλ’ εἰς ταὐτὸ τὴν ἀπάτην τῇ ἀνάγκῃ καὶ τῷ πόνῳ τὴν ἡδονὴν θέμενος, ὡς οὐχ ἧττον ἐκστῆσαι λογισμὸν ἀνθρώπου δυναμένων.", "st": "Sol. 21.2"}, {"sp": "N", "t": "ἐπέστησε δὲ καὶ ταῖς ἐξόδοις τῶν γυναικῶν καὶ τοῖς πένθεσι καὶ ταῖς ἑορταῖς νόμον ἀπείργοντα τὸ ἄτακτον καὶ ἀκόλαστον· ἐξιέναι μὲν ἱματίων τριῶν μὴ πλέον ἔχουσαν κελεύσας, μηδὲ βρωτὸν ἢ ποτὸν πλείονος ἢ ὀβολοῦ φερομένην, μηδὲ κάνητα πηχυαίου μείζονα, μηδὲ νύκτωρ πορεύεσθαι πλὴν ἁμάξῃ κομιζομένην λύχνου προφαίνοντος. ἀμυχὰς δὲ κοπτομένων καὶ τὸ θρηνεῖν πεποιημένα καὶ τὸ κωκύειν ἄλλον ἐν ταφαῖς ἑτέρων ἀφεῖλεν. ἐναγίζειν δὲ βοῦν οὐκ εἴασεν, οὐδὲ συντιθέναι πλέον ἱματίων τριῶν, οὐδ’ ἐπ’ ἀλλότρια μνήματα βαδίζειν χωρὶς ἐκκομιδῆς. ὧν τὰ πλεῖστα καὶ τοῖς ἡμετέροις νόμοις ἀπηγόρευται· πρόσκειται δὲ τοῖς ἡμετέροις ζημιοῦσθαι τοὺς τὰ τοιαῦτα ποιοῦντας ὑπὸ τῶν γυναικονόμων, ὡς ἀνάνδροις καὶ γυναικώδεσι τοῖς περὶ τὰ πένθη πάθεσι καὶ ἁμαρτήμασιν ἐνεχομένους.", "st": "Sol. 21.4"}, {"sp": "N", "t": "ὁρῶν δὲ τὸ μὲν ἄστυ πιμπλάμενον ἀνθρώπων ἀεὶ συρρεόντων πανταχόθεν ἐπ’ ἀδείας εἰς τὴν Ἀττικήν, τὰ δὲ πλεῖστα τῆς χώρας ἀγεννῆ καὶ φαῦλα, τοὺς δὲ χρωμένους τῇ θαλάττῃ μηδὲν εἰωθότας εἰσάγειν τοῖς μηδὲν ἔχουσιν ἀντιδοῦναι, πρὸς τὰς τέχνας ἔτρεψε τοὺς πολίτας, καὶ νόμον ἔγραψεν υἱῷ τρέφειν τὸν πατέρα μὴ διδαξάμενον τέχνην ἐπάναγκες μὴ εἶναι. τῷ μὲν γὰρ Λυκούργῳ καὶ πόλιν οἰκοῦντι καθαρὰν ὄχλου ξενικοῦ καὶ χώραν κεκτημένῳ", "st": "Sol. 22.1"}, {"sp": "N", "t": "πολλοῖσι πολλήν, δὶς τοσοῖσδε πλείονα,", "st": "Sol. 22.1b"}, {"sp": "N", "t": "κατ’ Εὐριπίδην, καὶ τὸ μέγιστον, εἱλωτικοῦ πλήθους, ὃ βέλτιον ἦν μὴ σχολάζειν, ἀλλὰ τριβόμενον ἀεὶ καὶ πονοῦν ταπεινοῦσθαι, περικεχυμένου τῇ Λακεδαίμονι, καλῶς εἶχεν ἀσχολιῶν ἐπιπόνων καὶ βαναύσων ἀπαλλάξαντα τοὺς πολίτας συνέχειν ἐν τοῖς ὅπλοις, μίαν τέχνην ταύτην ἐκμανθάνοντας καὶ ἀσκοῦντας· σόλων δὲ τοῖς πράγμασι τοὺς νόμους μᾶλλον ἢ τὰ πράγματα τοῖς νόμοις προσαρμόζων, καὶ τῆς χώρας τὴν φύσιν ὁρῶν τοῖς γεωργοῦσι γλίσχρως διαρκοῦσαν, ἀργὸν δὲ καὶ σχολαστὴν ὄχλον οὐ δυναμένην τρέφειν, ταῖς τέχναις ἀξίωμα περιέθηκε, καὶ τὴν ἐξ Ἀρείου πάγου βουλὴν ἔταξεν ἐπισκοπεῖν ὅθεν ἕκαστος ἔχει τὰ ἐπιτήδεια, καὶ τοὺς ἀργοὺς κολάζειν.", "st": "Sol. 22.3"}, {"sp": "N", "t": "ἐκεῖνο δ’ ἤδη σφοδρότερον, τὸ μηδὲ τοῖς ἐξ ἑταίρας γενομένοις ἐπάναγκες εἶναι τοὺς πατέρας τρέφειν, ὡς Ἡρακλείδης ἱστόρηκεν ὁ Ποντικός. ὁ γὰρ ἐν γάμῳ παρορῶν τὸ καλὸν οὐ τέκνων ἕνεκα δῆλός ἐστιν, ἀλλ’ ἡδονῆς ἀγόμενος γυναῖκα, τόν τε μισθὸν ἀπέχει, καὶ παρρησίαν αὑτῷ πρὸς τοὺς γενομένους οὐκ ἀπολέλοιπεν, οἷς αὐτὸ τὸ γενέσθαι πεποίηκεν ὄνειδος.", "st": "Sol. 22.4"}, {"sp": "N", "t": "ὅλως δὲ πλείστην ἔχειν ἀτοπίαν οἱ περὶ τῶν γυναικῶν νόμοι τῷ Σόλωνι δοκοῦσι. μοιχὸν μὲν γὰρ ἀνελεῖν τῷ λαβόντι δέδωκεν· ἐὰν δ’ ἁρπάσῃ τις ἐλευθέραν γυναῖκα καὶ βιάσηται, ζημίαν ἑκατὸν δραχμὰς ἔταξε· κἂν προαγωγεύῃ, δραχμὰς εἴκοσι, πλὴν ὅσαι πεφασμένως πωλοῦνται, λέγων δὴ τὰς ἑταίρας. αὗται γὰρ ἐμφανῶς φοιτῶσι πρὸς τοὺς διδόντας. ἔτι δ’ οὔτε θυγατέρας πωλεῖν οὔτ’ ἀδελφὰς δίδωσι, πλὴν ἂν μὴ λάβῃ παρθένον ἀνδρὶ συγγεγενημένην. τὸ δ’ αὐτὸ πρᾶγμα ποτὲ μὲν πικρῶς καὶ ἀπαραιτήτως κολάζειν, ποτὲ δ’ εὐκόλως καὶ παίζοντα, πρόστιμον ζημίαν τὴν τυχοῦσαν ὁρίζοντα, ἄλογόν ἐστι· πλὴν εἰ μὴ σπανίζοντος τότε τοῦ νομίσματος ἐν τῇ πόλει μεγάλας ἐποίει τὰς ἀργυρικὰς ζημίας τὸ δυσπόριστον. εἰς μέν γε τὰ τιμήματα τῶν θυσιῶν λογίζεται πρόβατον καὶ δραχμὴν ἀντὶ μεδίμνου· τῷ δ’ Ἴσθμια νικήσαντι δραχμὰς ἔταξεν ἑκατὸν δίδοσθαι, τῷ δ’ Ὀλύμπια πεντακοσίας· λύκον δὲ τῷ κομίσαντι πέντε δραχμὰς ἔδωκε, λυκιδέα δὲ μίαν, ὧν φησιν ὁ Φαληρεὺς Δημήτριος τὸ μὲν βοὸς εἶναι, τὸ δὲ προβάτου τιμήν. ἃς γὰρ ἐν τῷ ἑκκαιδεκάτῳ τῶν ἀξόνων ὁρίζει τιμὰς τῶν ἐκκρίτων ἱερείων, εἰκὸς μὲν εἶναι πολλαπλασίας, ἄλλως δὲ κἀκεῖναι πρὸς τὰς νῦν εὐτελεῖς εἰσιν. ἀρχαῖον δὲ τοῖς Ἀθηναίοις τὸ πολεμεῖν τοῖς λύκοις, βελτίονα νέμειν ἢ γεωργεῖν χώραν ἔχουσι. καὶ τὰς φυλὰς εἰσὶν οἱ λέγοντες οὐκ ἀπὸ τῶν Ἴωνος υἱῶν, ἀλλ’ ἀπὸ τῶν γενῶν, εἰς ἃ διῃρέθησαν οἱ βίοι τὸ πρῶτον, ὠνομάσθαι, τὸ μὲν μάχιμον Ὁπλίτας, τὸ δ’ ἐργατικὸν Ἐργάδεις· δυεῖν δὲ τῶν λοιπῶν Γελέοντας μὲν τοὺς γεωργούς, Αἰγικορεῖς δὲ τοὺς ἐπὶ νομαῖς καὶ προβατείαις διατρίβοντας.", "st": "Sol. 23.1"}, {"sp": "N", "t": "ἐπεὶ δὲ πρὸς ὕδωρ οὔτε ποταμοῖς ἐστιν ἀενάοις οὔτε λίμναις τισὶν οὔτ’ ἀφθόνοις πηγαῖς ἡ χώρα διαρκής, ἀλλ’ οἱ πλεῖστοι φρέασι ποιητοῖς ἐχρῶντο, νόμον ἔγραψεν, ὅπου μέν ἐστι δημόσιον φρέαρ ἐντὸς ἱππικοῦ, χρῆσθαι τούτῳ· τὸ δ’ ἱππικὸν διάστημα τεσσάρων ἦν σταδίων· ὅπου δὲ πλεῖον ἀπέχει, ζητεῖν ὕδωρ ἴδιον· ἐὰν δὲ ὀρύξαντες ὀργυιῶν δέκα βάθος παρ’ ἑαυτοῖς μὴ εὕρωσι, τότε λαμβάνειν παρὰ τοῦ γείτονος ἑξάχουν ὑδρίαν δὶς ἑκάστης ἡμέρας πληροῦντας· ἀπορίᾳ γὰρ ᾤετο δεῖν βοηθεῖν, οὐκ ἀργίαν ἐφοδιάζειν. ὥρισε δὲ καὶ φυτειῶν μέτρα μάλ’ ἐμπείρως, τοὺς μὲν ἄλλο τι φυτεύοντας ἐν ἀγρῷ πέντε πόδας ἀπέχειν τοῦ γείτονος κελεύσας, τοὺς δὲ συκῆν ἢ ἐλαίαν ἐννέα. πορρωτέρω γὰρ ἐξικνεῖται ταῦτα ταῖς ῥίζαις, καὶ οὐ πᾶσι γειτνιᾷ τοῖς φυτοῖς ἀσινῶς, ἀλλὰ καὶ τροφὴν παραιρεῖται καὶ βλάπτουσαν ἐνίοις ἀπορροὴν ἀφίησι. βόθρους δὲ καὶ τάφρους τὸν βουλόμενον ἐκέλευσεν ὀρύσσειν, ὅσον ἐμβάλλει βάθος, ἀφιστάμενον μῆκος τἀλλοτρίου· καὶ μελισσῶν σμήνη καθιστάμενον ἀπέχειν τῶν ὑφ’ ἑτέρου πρότερον ἱδρυμένων πόδας τριακοσίους.", "st": "Sol. 23.5"}, {"sp": "N", "t": "τῶν δὲ γινομένων διάθεσιν πρὸς ξένους ἐλαίου μόνον ἔδωκεν, ἄλλα δ’ ἐξάγειν ἐκώλυσε· καὶ κατὰ τῶν ἐξαγόντων ἀρὰς τὸν ἄρχοντα ποιεῖσθαι προσέταξεν, ἢ ἐκτίνειν αὐτὸν ἑκατὸν δραχμὰς εἰς τὸ δημόσιον. καὶ πρῶτος ἄξων ἐστὶν ὁ τοῦτον περιέχων τὸν νόμον. οὐκ ἂν οὖν τις ἡγήσαιτο παντελῶς ἀπιθάνους τοὺς λέγοντας ὅτι καὶ σύκων ἐξαγωγὴ τὸ παλαιὸν ἀπείρητο, καὶ τὸ φαίνειν ἐνδεικνύμενον τοὺς ἐξάγοντας κληθῆναι συκοφαντεῖν. ἔγραψε δὲ καὶ βλάβης τετραπόδων νόμον, ἐν ᾧ καὶ κύνα δακόντα παραδοῦναι κελεύει κλοιῷ τριπήχει δεδεμένον· τὸ μὲν ἐνθύμημα χάριεν πρὸς ἀσφάλειαν.", "st": "Sol. 24.1"}, {"sp": "N", "t": "παρέχει δ’ ἀπορίαν καὶ ὁ τῶν δημοποιήτων νόμος, ὅτι γενέσθαι πολίταις οὐ δίδωσι πλὴν τοῖς φεύγουσιν ἀειφυγίᾳ τὴν ἑαυτῶν ἢ πανεστίοις Ἀθήναζε μετοικιζομένοις ἐπὶ τέχνῃ. τοῦτο δὲ ποιῆσαί φασιν αὐτὸν οὐχ οὕτως ἀπελαύνοντα τοὺς ἄλλους ὡς κατακαλούμενον Ἀθήναζε τούτους ἐπὶ βεβαίῳ τῷ μεθέξειν τῆς πολιτείας, καὶ ἅμα πιστοὺς νομίζοντα τοὺς μὲν ἀποβεβληκότας τὴν ἑαυτῶν διὰ τὴν ἀνάγκην, τοὺς δ’ ἀπολελοιπότας διὰ τὴν γνώμην. ἴδιον δὲ τοῦ Σόλωνος καὶ τὸ περὶ τῆς ἐν δημοσίῳ σιτήσεως, ὅπερ αὐτὸς παρασιτεῖν κέκληκε. τὸν γὰρ αὐτὸν οὐκ ἐᾷ σιτεῖσθαι πολλάκις, ἐὰν δὲ ᾧ καθήκει μὴ βούληται, κολάζει, τὸ μὲν ἡγούμενος πλεονεξίαν, τὸ δ’ ὑπεροψίαν τῶν κοινῶν.", "st": "Sol. 24.2"}, {"sp": "N", "t": "ἰσχὺν δὲ τοῖς νόμοις πᾶσιν εἰς ἑκατὸν ἐνιαυτοὺς ἔδωκε· καὶ κατεγράφησαν εἰς ξυλίνους ἄξονας ἐν πλαισίοις περιέχουσι στρεφομένους, ὧν ἔτι καθ’ ἡμᾶς ἐν Πρυτανείῳ λείψανα μικρὰ διεσώζετο· καὶ προσηγορεύθησαν, ὡς Ἀριστοτέλης φησί, κύρβεις. καὶ Κρατῖνος ὁ κωμικὸς εἴρηκέ που·", "st": "Sol. 25.1"}, {"sp": "N", "t": "πρὸς τοῦ Σόλωνος καὶ Δράκοντος οἷσι νῦν<br>φρύγουσιν ἤδη τὰς κάχρυς τοῖς κύρβεσιν.", "st": "Sol. 25.1b"}, {"sp": "N", "t": "ἔνιοι δέ φασιν ἰδίως ἐν οἷς ἱερὰ καὶ θυσίαι περιέχονται, κύρβεις, ἄξονας δὲ τοὺς ἄλλους ὠνομάσθαι, κοινὸν μὲν οὖν ὤμνυεν ὅρκον ἡ βουλὴ τοὺς Σόλωνος νόμους ἐμπεδώσειν, ἴδιον δ’ ἕκαστος τῶν θεσμοθετῶν ἐν ἀγορᾷ πρὸς τῷ λίθῳ, καταφατίζων, εἴ τι παραβαίη τῶν θεσμῶν, ἀνδριάντα χρυσοῦν ἰσομέτρητον ἀναθήσειν ἐν Δελφοῖς.", "st": "Sol. 25.2"}, {"sp": "N", "t": "συνιδὼν δὲ τοῦ μηνὸς τὴν ἀνωμαλίαν, καὶ τὴν κίνησιν τῆς σελήνης οὔτε δυομένῳ τῷ ἡλίῳ πάντως οὔτ’ ἀνίσχοντι συμφερομένην, ἀλλὰ πολλάκις τῆς αὐτῆς ἡμέρας καὶ καταλαμβάνουσαν καὶ παρερχομένην τὸν ἥλιον, αὐτὴν μὲν ἔταξε ταύτην ἕνην καὶ νέαν καλεῖσθαι, τὸ μὲν πρὸ συνόδου μόριον αὐτῆς τῷ παυομένῳ μηνί, τὸ δὲ λοιπὸν ἤδη τῷ ἀρχομένῳ προσήκειν ἡγούμενος, πρῶτος, ὡς ἔοικεν, ὀρθῶς ἀκούσας Ὁμήρου λέγοντος,", "st": "Sol. 25.3"}, {"sp": "N", "t": "τοῦ μὲν φθίνοντος μηνός, τοῦ δ’ ἱσταμένοιο,", "st": "Sol. 25.3b"}, {"sp": "N", "t": "τὴν δ’ ἐφεξῆς ἡμέραν νουμηνίαν ἐκάλεσε. τὰς δ’ ἀπ’ εἰκάδος οὐ προστιθείς, ἀλλ’ ἀφαιρῶν καὶ ἀναλύων, ὥσπερ τὰ φῶτα τῆς σελήνης ἑώρα, μέχρι τριακάδος ἠρίθμησεν.", "st": "Sol. 25.3c"}, {"sp": "N", "t": "ἐπεὶ δὲ τῶν νόμων εἰσενεχθέντων ἔνιοι τῷ Σόλωνι καθ’ ἑκάστην προσῄεσαν ἡμέραν, ἐπαινοῦντες ἢ ψέγοντες ἢ συμβουλεύοντες ἐμβάλλειν τοῖς γεγραμμένοις ὅ τι τύχοιεν ἢ ἀφαιρεῖν, πλεῖστοι δ’ ἦσαν οἱ πυνθανόμενοι καὶ ἀνακρίνοντες καὶ κελεύοντες αὐτὸν ὅπως ἕκαστον ἔχει καὶ πρὸς ἣν κεῖται διάνοιαν ἐπεκδιδάσκειν καὶ σαφηνίζειν, ὁρῶν ὅτι ταῦτα καὶ τὸ πράττειν ἄτοπον καὶ τὸ μὴ πράττειν ἐπίφθονον, ὅλως δὲ ταῖς ἀπορίαις ὑπεκστῆναι βουλόμενος καὶ διαφυγεῖν τὸ δυσάρεστον καὶ φιλαίτιον τῶν πολιτῶν (ἔργμασι γὰρ ἐν μεγάλοις πᾶσιν ἁδεῖν χαλεπόν, ὡς αὐτὸς εἴρηκε), πρόσχημα τῆς πλάνης τὴν ναυκληρίαν ποιησάμενος ἐξέπλευσε, δεκαετῆ παρὰ τῶν Ἀθηναίων ἀποδημίαν αἰτησάμενος. ἤλπιζε γὰρ ἐν τῷ χρόνῳ τούτῳ καὶ τοῖς νόμοις αὐτοὺς ἔσεσθαι συνήθεις.", "st": "Sol. 25.4"}, {"sp": "N", "t": "πρῶτον μὲν οὖν εἰς Αἴγυπτον ἀφίκετο καὶ διέτριψεν, ὡς αὐτός φησι,", "st": "Sol. 26.1"}, {"sp": "N", "t": "Νείλου ἐπὶ προχοῇσι Κανωβίδος ἐγγύθεν ἀκτῆς.", "st": "Sol. 26.1b"}, {"sp": "N", "t": "χρόνον δέ τινα καὶ τοῖς περὶ Ψένωφιν τὸν Ἡλιουπολίτην καὶ Σῶγχιν τὸν Σαΐτην, λογιωτάτοις οὖσι τῶν ἱερέων, συνεφιλοσόφησε· παρ’ ὧν καὶ τὸν Ἀτλαντικὸν ἀκούσας λόγον, ὡς Πλάτων φησίν, ἐπεχείρησε διὰ ποιήματος ἐξενεγκεῖν εἰς τοὺς Ἕλληνας. ἔπειτα πλεύσας εἰς Κύπρον ἠγαπήθη διαφερόντως ὑπὸ Φιλοκύπρου τινὸς τῶν ἐκεῖ βασιλέων, ὃς εἶχεν οὐ μεγάλην πόλιν, ᾠκισμένην ὑπὸ Δημοφῶντος τοῦ Θησέως, περὶ τὸν Κλάριον ποταμὸν ἐν χωρίοις ὀχυροῖς μέν, ἄλλως δὲ δυσχερέσι καὶ φαύλοις κειμένην. ἔπεισεν οὖν αὐτὸν ὁ Σόλων ὑποκειμένου καλοῦ πεδίου μεταθέντα τὴν πόλιν ἡδίονα καὶ μείζονα κατασκευάσαι. καὶ παρὼν ἐπεμελήθη τοῦ συνοικισμοῦ, καὶ συνδιεκόσμησε πρός τε διαγωγὴν ἄριστα καὶ πρὸς ἀσφάλειαν, ὥστε πολλοὺς μὲν οἰκήτορας τῷ Φιλοκύπρῳ συνελθεῖν, ζηλῶσαι δὲ τοὺς ἄλλους βασιλέας· διὸ καὶ τῷ Σόλωνι τιμὴν ἀποδιδοὺς Αἰπεῖαν τὴν πόλιν καλουμένην πρότερον ἀπ’ ἐκείνου Σόλους προσηγόρευσε. καὶ αὐτὸς δὲ μέμνηται τοῦ συνοικισμοῦ· προσαγορεύσας γὰρ ἐν ταῖς ἐλεγείαις τὸν Φιλόκυπρον,", "st": "Sol. 26.2"}, {"sp": "N", "t": "νῦν δὲ (φησί) σὺ μὲν Σολίοισι πολὺν χρόνον ἐνθάδ’ ἀνάσσων<br>τήνδε πόλιν ναίοις καὶ γένος ὑμέτερον·<br>αὐτὰρ ἐμὲ ξὺν νηῒ θοῇ κλεινῆς ἀπὸ νήσου<br>ἀσκηθῆ πέμποι Κύπρις ἰοστέφανος·", "st": "Sol. 26.2b"}, {"sp": "N", "t": "οἰκισμῷ δ’ ἐπὶ τῷδε χάριν καὶ κῦδος ὀπάζοι<br>ἐσθλὸν καὶ νόστον πατρίδ’ ἐς ἡμετέρην.", "st": "Sol. 26.2c"}, {"sp": "N", "t": "τὴν δὲ πρὸς Κροῖσον ἔντευξιν αὐτοῦ δοκοῦσιν ἔνιοι τοῖς χρόνοις ὡς πεπλασμένην ἐλέγχειν. ἐγὼ δὲ λόγον ἔνδοξον οὕτω καὶ τοσούτους μάρτυρας ἔχοντα, καὶ, ὃ μεῖζόν ἐστι, πρέποντα τῷ Σόλωνος ἤθει καὶ τῆς ἐκείνου μεγαλοφροσύνης καὶ σοφίας ἄξιον, οὔ μοι δοκῶ προήσεσθαι χρονικοῖς τισι λεγομένοις κανόσιν, οὓς μυρίοι διορθοῦντες ἄχρι σήμερον εἰς οὐδὲν αὑτοῖς ὁμολογούμενον δύνανται καταστῆσαι τὰς ἀντιλογίας. τὸν δ’ οὖν Σόλωνά φασιν εἰς Σάρδεις δεηθέντι τῷ Κροίσῳ παραγενόμενον, παθεῖν τι παραπλήσιον ἀνδρὶ χερσαίῳ κατιόντι πρῶτον ἐπὶ θάλατταν. ἐκεῖνός τε γὰρ ὁρῶν ἄλλον ἐξ ἄλλου ποταμὸν ᾤετο τὴν θάλασσαν εἶναι, καὶ τῷ Σόλωνι τὴν αὐλὴν διαπορευομένῳ καὶ πολλοὺς ὁρῶντι τῶν βασιλικῶν κεκοσμημένους πολυτελῶς, καὶ σοβοῦντας ἐν ὄχλῳ προπομπῶν καὶ δορυφόρων, ἕκαστος ἐδόκει Κροῖσος εἶναι, μέχρι πρὸς αὐτὸν ἤχθη, πᾶν ὅσον ἐν λίθοις, ἐν βαφαῖς ἐσθῆτος, ἐν τέχναις χρυσοῦ περὶ κόσμον ἐκπρεπὲς ἔχειν ἢ περιττὸν ἢ ζηλωτὸν ἐδόκει περικείμενον, ὡς δὴ θέαμα σεμνότατον ὀφθείη καὶ ποικιλώτατον. ἐπεὶ δ’ ὁ Σόλων ἄντικρυς καταστὰς οὔτ’ ἔπαθεν οὐδὲν οὔτ’ εἶπε πρὸς τὴν ὄψιν ὧν ὁ Κροῖσος προσεδόκησεν, ἀλλὰ καὶ δῆλος ἦν τοῖς εὖ φρονοῦσι τῆς ἀπειροκαλίας καὶ μικροπρεπείας καταφρονῶν, ἐκέλευσεν αὐτῷ τούς τε θησαυροὺς ἀνοῖξαι τῶν χρημάτων, καὶ τὴν ἄλλην ἄγοντας ἐπιδεῖξαι μηδὲν δεομένῳ κατασκευὴν καὶ πολυτέλειαν.", "st": "Sol. 27.1"}, {"sp": "N", "t": "ἤρκει γὰρ αὐτὸς ἐν ἑαυτῷ τοῦ τρόπου κατανόησιν παρασχεῖν. ὡς δ’ οὖν αὖθις ἤχθη γεγονὼς ἁπάντων θεατής, ἠρώτησεν αὐτὸν ὁ Κροῖσος εἴ τινα οἶδεν ἀνθρώπων αὐτοῦ μακαριώτερον. ἀποφηναμένου δὲ τοῦ Σόλωνος ὅτι οἶδε Τέλλον αὑτοῦ πολίτην, καὶ διεξελθόντος ὅτι χρηστὸς ἀνὴρ ὁ Τέλλος γενόμενος καὶ παῖδας εὐδοκίμους καταλιπὼν καὶ βίον οὐδενὸς ἐνδεᾶ τῶν ἀναγκαίων, ἐτελεύτησεν ἐνδόξως ἀριστεύσας ὑπὲρ τῆς πατρίδος, ἤδη μὲν ἀλλόκοτος ἐδόκει εἶναι τῷ Κροίσῳ καὶ ἄγροικος, εἰ μὴ πρὸς ἀργύριον πολὺ μηδὲ χρυσίον τῆς εὐδαιμονίας ποιεῖται τὴν ἀναμέτρησιν, ἀλλὰ δημοτικοῦ καὶ ἰδιώτου βίον καὶ θάνατον ἀνθρώπου μᾶλλον ἢ τοσαύτην ἀγαπῴη δύναμιν καὶ ἀρχήν. οὐ μὴν ἀλλὰ πάλιν ἠρώτησεν αὐτὸν εἰ μετὰ Τέλλον ἄλλον ἔγνωκεν ἀνθρώπων εὐδαιμονέστερον.", "st": "Sol. 27.4"}, {"sp": "N", "t": "πάλιν δὲ τοῦ Σόλωνος εἰπόντος εἰδέναι Κλέοβιν καὶ Βίτωνα, φιλαδέλφους καὶ φιλομήτορας διαφερόντως ἄνδρας, οἳ τὴν μητέρα τῶν βοῶν βραδυνόντων ὑποδύντες αὐτοὶ τῷ ζυγῷ τῆς ἁμάξης ἐκόμισαν πρὸς τὸ τῆς Ἥρας ἱερὸν εὐδαιμονιζομένην ὑπὸ τῶν πολιτῶν καὶ χαίρουσαν, εἶτα θύσαντες καὶ πιόντες οὐκ ἔτι μεθ’ ἡμέραν ἀνέστησαν, ἀλλὰ τεθνηκότες ἀναλγῆ καὶ ἄλυπον ἐπὶ δόξῃ τοσαύτῃ θάνατον ὤφθησαν, ἡμᾶς δέ, εἶπεν ἤδη πρὸς ὀργὴν ὁ Κροῖσος, εἰς οὐδένα τίθης εὐδαιμόνων ἀριθμὸν ἀνθρώπων; καὶ ὁ Σόλων οὔτε κολακεύειν βουλόμενος αὐτὸν οὔτε περαιτέρω παροξύνειν, Ἕλλησιν, εἶπεν, ὦ βασιλεῦ Λυδῶν, πρός τε τἆλλα μετρίως ἔχειν ὁ θεὸς ἔδωκε, καὶ σοφίας τινὸς ἀθαρσοῦς, ὡς ἔοικε, καὶ δημοτικῆς, οὐ βασιλικῆς οὐδὲ λαμπρᾶς, ὑπὸ μετριότητος ἡμῖν μέτεστιν, ἣ τύχαις ὁρῶσα παντοδαπαῖς χρώμενον ἀεὶ τὸν βίον, οὐκ ἐᾷ τοῖς παροῦσιν ἀγαθοῖς μέγα φρονεῖν, οὐδὲ θαυμάζειν ἀνδρὸς εὐτυχίαν μεταβολῆς χρόνον ἔχουσαν.", "st": "Sol. 27.6"}, {"sp": "N", "t": "ἔπεισι γὰρ ἑκάστῳ ποικίλον ἐξ ἀδήλου τὸ μέλλον· ᾧ δ’ εἰς τέλος ὁ δαίμων ἔθετο τὴν εὐπραξίαν, τοῦτον εὐδαίμονα νομίζομεν. ὁ δὲ ζῶντος ἔτι καὶ κινδυνεύοντος ἐν τῷ βίῳ μακαρισμός, ὥσπερ ἀγωνιζομένου κήρυγμα καὶ στέφανος, ἐστὶν ἀβέβαιος καὶ ἄκυρος. ταῦτ’ εἰπὼν ὁ Σόλων ἀπηλλάττετο λυπήσας μέν, οὐ νουθετήσας δὲ τὸν Κροῖσον.", "st": "Sol. 27.7"}, {"sp": "N", "t": "ὁ δὲ λογοποιὸς Αἴσωπος, ἐτύγχανε γὰρ εἰς Σάρδεις μετάπεμπτος γεγονὼς ὑπὸ Κροίσου καὶ τιμώμενος, ἠχθέσθη τῷ Σόλωνι μηδεμιᾶς τυχόντι φιλανθρωπίας· καὶ προτρέπων αὐτόν, ὦ Σόλων, ἔφη, τοῖς βασιλεῦσι δεῖ ὡς ἥκιστα ἢ ὡς ἥδιστα ὁμιλεῖν. καὶ ὁ Σόλων, μὰ Δί’, εἶπεν, ἀλλ’ ὡς ἥκιστα ἢ ὡς ἄριστα.", "st": "Sol. 28.1"}, {"sp": "N", "t": "τότε μὲν οὖν ὁ Κροῖσος οὕτω τοῦ Σόλωνος κατεφρόνησεν· ἐπεὶ δὲ Κύρῳ συμβαλὼν ἐκρατήθη μάχῃ, καὶ τὴν πόλιν ἀπώλεσε, καὶ ζῶν ἁλοὺς αὐτὸς ἔμελλε καταπίμπρασθαι, καὶ γενομένης πυρᾶς ἀνεβιβάσθη δεδεμένος θεωμένων Περσῶν ἁπάντων καὶ Κύρου παρόντος, ἐφ’ ὅσον ἐξικνεῖτο καὶ δυνατὸς ἦν τῇ φωνῇ φθεγξάμενος ἀνεβόησε τρίς, ὦ Σόλων. θαυμάσας οὖν ὁ Κῦρος ἔπεμψε τοὺς ἐρησομένους ὅστις ἀνθρώπων ἢ θεῶν οὗτός ἐστιν ὁ Σόλων, ὃν ἐν τύχαις ἀπόροις μόνον ἀνακαλεῖται. καὶ ὁ Κροῖσος οὐδὲν ἀποκρυψάμενος εἶπεν ὅτι τῶν παρ’ Ἕλλησι σοφῶν εἷς οὗτος ἦν ὁ ἀνήρ, ὃν ἐγὼ μετεπεμψάμην οὐκ ἀκοῦσαί τι βουλόμενος οὐδὲ μαθεῖν ὧν ἐνδεὴς ἤμην, ἀλλ’ ὡς δή μοι θεατὴς γένοιτο καὶ μάρτυς ἀπίοι τῆς εὐδαιμονίας ἐκείνης, ἣν ἀποβαλεῖν ἄρα μεῖζον ἦν κακὸν ἢ λαβεῖν ἀγαθόν. λόγος γὰρ ἦν καὶ δόξα τἀγαθὸν παρούσης· αἱ μεταβολαὶ δέ μοι αὐτῆς εἰς πάθη δεινὰ καὶ συμφορὰς ἀνηκέστους ἔργῳ τελευτῶσι. καὶ ταῦτ’ ἐκεῖνος ὁ ἀνὴρ ἐκ τῶν τότε τὰ νῦν τεκμαιρόμενος, ἐκέλευε τὸ τέλος τοῦ βίου σκοπεῖν καὶ μὴ θρασυνόμενον ἀβεβαίοις ὑπονοίαις ὑβρίζειν. ἐπεὶ δὲ τοῦτ’ ἀνηνέχθη πρὸς τὸν Κῦρον, ἅτε δὴ σοφώτερος ὢν τοῦ Κροίσου καὶ τὸν λόγον τοῦ Σόλωνος ἰσχυρὸν ἐν τῷ παραδείγματι βλέπων, οὐ μόνον ἀφῆκε τὸν Κροῖσον, ἀλλὰ καὶ τιμῶν ἐφ’ ὅσον ἔζη διετέλεσε· καὶ δόξαν ἔσχεν ὁ Σόλων ἑνὶ λόγῳ τὸν μὲν σώσας, τὸν δὲ παιδεύσας τῶν βασιλέων.", "st": "Sol. 28.2"}, {"sp": "N", "t": "οἱ δὲ ἐν ἄστει πάλιν ἐστασίαζον ἀποδημοῦντος τοῦ Σόλωνος· καὶ προειστήκει τῶν μὲν Πεδιέων Λυκοῦργος, τῶν δὲ Παράλων Μεγακλῆς ὁ Ἀλκμαίωνος, Πεισίστρατος δὲ τῶν Διακρίων, ἐν οἷς ἦν ὁ θητικὸς ὄχλος καὶ μάλιστα τοῖς πλουσίοις ἀχθόμενος· ὥστε χρῆσθαι μὲν ἔτι τοῖς νόμοις τὴν πόλιν, ἤδη δὲ πράγματα νεώτερα προσδοκᾶν καὶ ποθεῖν ἅπαντας ἑτέραν κατάστασιν, οὐκ ἴσον ἐλπίζοντας, ἀλλὰ πλέον ἕξειν ἐν τῇ μεταβολῇ καὶ κρατήσειν παντάπασι τῶν διαφερομένων. οὕτω δὲ τῶν πραγμάτων ἐχόντων ὁ Σόλων παραγενόμενος εἰς τὰς Ἀθήνας, αἰδῶ μὲν εἶχε καὶ τιμὴν παρὰ πᾶσιν, ἐν δὲ κοινῷ λέγειν καὶ πράσσειν ὁμοίως οὐκ ἔτ’ ἦν δυνατὸς οὐδὲ πρόθυμος ὑπὸ γήρως, ἀλλ’ ἐντυγχάνων ἰδίᾳ τοῖς προεστῶσι τῶν στάσεων ἀνδράσιν ἐπειρᾶτο διαλύειν καὶ συναρμόττειν, μάλιστα τοῦ Πεισιστράτου προσέχειν δοκοῦντος αὐτῷ. καὶ γὰρ αἱμύλον τι καὶ προσφιλὲς εἶχεν ἐν τῷ διαλέγεσθαι, καὶ βοηθητικὸς ἦν τοῖς πένησι καὶ πρὸς τὰς ἔχθρας ἐπιεικὴς καὶ μέτριος. ἃ δὲ φύσει μὴ προσῆν αὐτῷ, καὶ ταῦτα μιμούμενος ἐπιστεύετο μᾶλλον τῶν ἐχόντων, ὡς εὐλαβὴς καὶ κόσμιος ἀνὴρ καὶ μάλιστα δὴ τὸ ἴσον ἀγαπῶν, καὶ δυσχεραίνων εἴ τις τὰ παρόντα κινοίη καὶ νεωτέρων ὀρέγοιτο· τούτοις γὰρ ἐξηπάτα τοὺς πολλούς. ὁ δὲ Σόλων ταχὺ τὸ ἦθος ἐφώρασεν αὐτοῦ καὶ τὴν ἐπιβουλὴν πρῶτος ἐγκατεῖδεν· οὐ μὴν ἐμίσησεν, ἀλλ’ ἐπειρᾶτο πραΰνειν καὶ νουθετεῖν, καὶ πρὸς αὐτὸν ἔλεγε καὶ πρὸς ἑτέρους ὡς εἴ τις ἐξέλοι τὸ φιλόπρωτον αὐτοῦ τῆς ψυχῆς καὶ τὴν ἐπιθυμίαν ἰάσαιτο τῆς τυραννίδος, οὐκ ἔστιν ἄλλος εὐφυέστερος πρὸς ἀρετὴν οὐδὲ βελτίων πολίτης.", "st": "Sol. 29.1"}, {"sp": "N", "t": "ἀρχομένων δὲ τῶν περὶ Θέσπιν ἤδη τὴν τραγῳδίαν κινεῖν, καὶ διὰ τὴν καινότητα τοὺς πολλοὺς ἄγοντος τοῦ πράγματος, οὔπω δ’ εἰς ἅμιλλαν ἐναγώνιον ἐξηγμένου, φύσει φιλήκοος ὢν καὶ φιλομαθὴς ὁ Σόλων, ἔτι μᾶλλον ἐν γήρᾳ σχολῇ καὶ παιδιᾷ καὶ νὴ Δία πότοις καὶ μουσικῇ παραπέμπων ἑαυτόν, ἐθεάσατο τὸν Θέσπιν αὐτὸν ὑποκρινόμενον, ὥσπερ ἔθος ἦν τοῖς παλαιοῖς. μετὰ δὲ τὴν θέαν προσαγορεύσας αὐτὸν ἠρώτησεν εἰ τοσούτων ἐναντίον οὐκ αἰσχύνεται τηλικαῦτα ψευδόμενος. φήσαντος δὲ τοῦ Θέσπιδος μὴ δεινὸν εἶναι τὸ μετὰ παιδιᾶς λέγειν τὰ τοιαῦτα καὶ πράσσειν, σφόδρα τῇ βακτηρίᾳ τὴν γῆν ὁ Σόλων πατάξας· ταχὺ μέντοι τὴν παιδιάν, ἔφη, ταύτην ἐπαινοῦντες οὕτω καὶ τιμῶντες εὑρήσομεν ἐν τοῖς συμβολαίοις.", "st": "Sol. 29.4"}, {"sp": "N", "t": "ἐπεὶ δὲ κατατρώσας αὐτὸς ἑαυτὸν ὁ Πεισίστρατος ἧκεν εἰς ἀγορὰν ἐπὶ ζεύγους κομιζόμενος, καὶ παρώξυνε τὸν δῆμον ὡς διὰ τὴν πολιτείαν ὑπὸ τῶν ἐχθρῶν ἐπιβεβουλευμένος, καὶ πολλοὺς εἶχεν ἀγανακτοῦντας καὶ βοῶντας, προσελθὼν ἐγγὺς ὁ Σόλων καὶ παραστάς, οὐ καλῶς, εἶπεν, ὦ παῖ Ἱπποκράτους, ὑποκρίνῃ τὸν Ὁμηρικὸν Ὀδυσσέα· ταῦτα γὰρ ποιεῖς τοὺς πολίτας παρακρουόμενος οἷς ἐκεῖνος τοὺς πολεμίους ἐξηπάτησεν, αἰκισάμενος ἑαυτόν. ἐκ τούτου τὸ μὲν πλῆθος ἦν ἕτοιμον ὑπερμαχεῖν τοῦ Πεισιστράτου, καὶ συνῆλθεν εἰς ἐκκλησίαν ὁ δῆμος. Ἀρίστωνος δὲ γράψαντος ὅπως δοθῶσι πεντήκοντα κορυνηφόροι τῷ Πεισιστράτῳ φυλακὴ τοῦ σώματος, ἀντεῖπεν ὁ Σόλων ἀναστὰς καὶ πολλὰ διεξῆλθεν ὅμοια τούτοις οἷς διὰ τῶν ποιημάτων γέγραφεν·", "st": "Sol. 30.1"}, {"sp": "N", "t": "εἰς γὰρ γλῶσσαν ὁρᾶτε καὶ εἰς ἔπη αἱμύλοι ἀνδρός.", "st": "Sol. 30.1b"}, {"sp": "N", "t": "ὑμῶν δ’ εἷς μὲν ἕκαστος ἀλώπεκος ἴχνεσι βαίνει,<br>σύμπασιν δ’ ὑμῖν χαῦνος ἔνεστι νόος.", "st": "Sol. 30.1c"}, {"sp": "N", "t": "ὁρῶν δὲ τοὺς μὲν πένητας ὡρμημένους χαρίζεσθαι τῷ Πεισιστράτῳ καὶ θορυβοῦντας, τοὺς δὲ πλουσίους ἀποδιδράσκοντας καὶ ἀποδειλιῶντας, ἀπῆλθεν εἰπὼν ὅτι τῶν μέν ἐστι σοφώτερος, τῶν δὲ ἀνδρειότερος· σοφώτερος μὲν τῶν μὴ συνιέντων τὸ πραττόμενον, ἀνδρειότερος δὲ τῶν συνιέντων μέν, ἐναντιοῦσθαι δὲ τῇ τυραννίδι φοβουμένων. τὸ δὲ ψήφισμα κυρώσας ὁ δῆμος οὐδὲ περὶ τοῦ πλήθους ἔτι τῶν κορυνηφόρων διεμικρολογεῖτο πρὸς τὸν Πεισίστρατον, ἀλλ’ ὅσους ἐβούλετο τρέφοντα καὶ συνάγοντα φανερῶς περιεώρα, μέχρι τὴν ἀκρόπολιν κατέσχε.", "st": "Sol. 30.3"}, {"sp": "N", "t": "γενομένου δὲ τούτου καὶ τῆς πόλεως συνταραχθείσης, ὁ μὲν Μεγακλῆς εὐθὺς ἔφυγε μετὰ τῶν ἄλλων Ἀλκμαιωνιδῶν, ὁ δὲ Σόλων ἤδη μὲν ἦν σφόδρα γέρων καὶ τοὺς βοηθοῦντας οὐκ εἶχεν, ὅμως δὲ προῆλθεν εἰς ἀγορὰν καὶ διελέχθη πρὸς τοὺς πολίτας, τὰ μὲν κακίζων τὴν ἀβουλίαν αὐτῶν καὶ μαλακίαν, τὰ δὲ παροξύνων ἔτι καὶ παρακαλῶν μὴ προέσθαι τὴν ἐλευθερίαν· ὅτε καὶ τὸ μνημονευόμενον εἶπεν, ὡς πρώην μὲν ἦν εὐμαρέστερον αὐτοῖς τὸ κωλῦσαι τὴν τυραννίδα συνισταμένην, νῦν δὲ μεῖζόν ἐστι καὶ λαμπρότερον ἐκκόψαι καὶ ἀνελεῖν συνεστῶσαν ἤδη καὶ πεφυκυῖαν. οὐδενὸς δὲ προσέχοντος αὐτῷ διὰ τὸν φόβον ἀπῆλθεν εἰς τὴν οἰκίαν τὴν ἑαυτοῦ, καὶ λαβὼν τὰ ὅπλα καὶ πρὸ τῶν θυρῶν θέμενος εἰς τὸν στενωπόν, ἐμοὶ μέν, εἶπεν, ὡς δυνατὸν ἦν βεβοήθηται τῇ πατρίδι καὶ τοῖς νόμοις. καὶ τὸ λοιπὸν ἡσυχίαν ἦγε, καὶ τῶν φίλων φεύγειν παραινούντων οὐ προσεῖχεν, ἀλλὰ ποιήματα γράφων ὠνείδιζε τοῖς Ἀθηναίοις·", "st": "Sol. 30.4"}, {"sp": "N", "t": "εἰ δὲ πεπόνθατε λυγρὰ δι’ ὑμετέρην κακότητα,<br>μή τι θεοῖς τούτων μῆνιν ἐπαμφέρετε.<br>αὐτοὶ γὰρ τούτους ηὐξήσατε ῥύματα δόντες,<br>καὶ διὰ ταῦτα κακὴν ἔσχετε δουλοσύνην.", "st": "Sol. 30.4b"}, {"sp": "N", "t": "ἐπὶ τούτοις δὲ πολλῶν νουθετούντων αὐτὸν ὡς ἀποθανούμενον ὑπὸ τοῦ τυράννου, καὶ πυνθανομένων τίνι πιστεύων οὕτως ἀπονοεῖται, τῷ γήρᾳ, εἶπεν. οὐ μὴν ἀλλ’ ὁ Πεισίστρατος ἐγκρατὴς γενόμενος τῶν πραγμάτων οὕτως ἐξεθεράπευσε τὸν Σόλωνα, τιμῶν καὶ φιλοφρονούμενος καὶ μεταπεμπόμενος, ὥστε καὶ σύμβουλον εἶναι καὶ πολλὰ τῶν πρασσομένων ἐπαινεῖν. καὶ γὰρ ἐφύλαττε τοὺς πλείστους νόμους τοῦ Σόλωνος, ἐμμένων πρῶτος αὐτὸς καὶ τοὺς φίλους ἀναγκάζων· ὅς γε καὶ φόνου προσκληθεὶς εἰς Ἄρειον πάγον, ἤδη τυραννῶν, ἀπήντησε κοσμίως ἀπολογησόμενος, ὁ δὲ κατήγορος οὐχ ὑπήκουσε· καὶ νόμους αὐτὸς ἑτέρους ἔγραψεν, ὧν ἐστι καὶ ὁ τοὺς πηρωθέντας ἐν πολέμῳ δημοσίᾳ τρέφεσθαι κελεύων. τοῦτο δέ φησιν Ἡρακλείδης καὶ πρότερον ἐπὶ Θερσίππῳ πηρωθέντι τοῦ Σόλωνος ψηφισαμένου μιμήσασθαι τὸν Πεισίστρατον. ὡς δὲ Θεόφραστος ἱστόρηκε, καὶ τὸν τῆς ἀργίας νόμον οὐ Σόλων ἔθηκεν, ἀλλὰ Πεισίστρατος, ᾧ τήν τε χώραν ἐνεργοτέραν καὶ τὴν πόλιν ἠρεμαιοτέραν ἐποίησεν.", "st": "Sol. 31.1"}, {"sp": "N", "t": "ὁ δὲ Σόλων ἁψάμενος μεγάλης τῆς περὶ τὸν Ἀτλαντικὸν λόγον ἢ μῦθον πραγματείας, ὃν διήκουσε τῶν περὶ Σάϊν λογίων προσήκοντα τοῖς Ἀθηναίοις, ἐξέκαμεν, οὐ δι’ ἀσχολίαν, ὡς Πλάτων φησίν, ἀλλὰ μᾶλλον ὑπὸ γήρως, φοβηθεὶς τὸ μέγεθος τῆς γραφῆς. ἐπεὶ σχολῆς γε περιουσίαν αὐτοῦ μηνύουσιν αἱ τοιαῦται φωναί·", "st": "Sol. 31.3"}, {"sp": "N", "t": "γηράσκω δ’ αἰεὶ πολλὰ διδασκόμενος·<br>καί,<br>ἔργα δὲ Κυπρογενοῦς νῦν μοι φίλα καὶ Διονύσου<br>καὶ Μουσέων, ἃ τίθησ’ ἀνδράσιν εὐφροσύνας.", "st": "Sol. 31.3b"}, {"sp": "N", "t": "ὡς δὲ χώρας καλῆς ἔδαφος ὁ Πλάτων ἔρημον, αὐτῷ δέ πως κατὰ συγγένειαν προσῆκον, ἐξεργάσασθαι καὶ διακοσμῆσαι φιλοτιμούμενος τὴν Ἀτλαντικὴν ὑπόθεσιν, πρόθυρα μὲν μεγάλα καὶ περιβόλους καὶ αὐλὰς τῇ ἀρχῇ περιέθηκεν, οἷα λόγος οὐδεὶς ἄλλος ἔσχεν οὐδὲ μῦθος οὐδὲ ποίησις, ὀψὲ δὲ ἀρξάμενος προκατέλυσε τοῦ ἔργου τὸν βίον, ὅσῳ μᾶλλον εὐφραίνει τὰ γεγραμμένα, τοσούτῳ μᾶλλον τοῖς ἀπολειφθεῖσιν ἀνιάσας. ὡς γὰρ ἡ πόλις τῶν Ἀθηναίων τὸ Ὀλυμπιεῖον, οὕτως ἡ Πλάτωνος σοφία τὸν Ἀτλαντικὸν ἐν πολλοῖς καλοῖς μόνον ἔργον ἀτελὲς ἔσχηκεν.", "st": "Sol. 32.1"}, {"sp": "N", "t": "ἐπεβίωσε δ’ οὖν ὁ Σόλων ἀρξαμένου τοῦ Πεισιστράτου τυραννεῖν, ὡς μὲν Ἡρακλείδης ὁ Ποντικὸς ἱστορεῖ, συχνὸν χρόνον, ὡς δὲ Φανίας ὁ Ἐρέσιος, ἐλάττονα δυοῖν ἐτῶν. ἐπὶ Κωμίου μὲν γὰρ ἤρξατο τυραννεῖν Πεισίστρατος, ἐφ’ Ἡγεστράτου δὲ Σόλωνά φησιν ὁ Φανίας ἀποθανεῖν τοῦ μετὰ Κωμίαν ἄρξαντος. ἡ δὲ διασπορὰ κατακαυθέντος αὐτοῦ τῆς τέφρας περὶ τὴν Σαλαμινίων νῆσον ἔστι μὲν διὰ τὴν ἀτοπίαν ἀπίθανος παντάπασι καὶ μυθώδης, ἀναγέγραπται δ’ ὑπό τε ἄλλων ἀνδρῶν ἀξιολόγων καὶ Ἀριστοτέλους τοῦ φιλοσόφου.", "st": "Sol. 32.3"}, {"sp": "HDR", "t": "Ποπλικόλας"}, {"sp": "N", "t": "τοιούτῳ δὴ γενομένῳ τῷ Σόλωνι τὸν Ποπλικόλαν παραβάλλομεν, ᾧ τοῦτο μὲν ὕστερον ὁ Ῥωμαίων δῆμος ἐξεῦρεν ἐπὶ τιμῇ τοὔνομα, πρὸ τοῦ δὲ Πόπλιος Οὐαλλέριος ἐκαλεῖτο, Οὐαλλερίου δοκῶν ἀπόγονος εἶναι τῶν παλαιῶν ἀνδρὸς αἰτιωτάτου γενομένου Ῥωμαίους καὶ Σαβίνους ἐκ πολεμίων ἕνα γενέσθαι δῆμον· ὁ γὰρ μάλιστα τοὺς βασιλεῖς εἰς ταὐτὸ πείσας συνελθεῖν καὶ διαλλάξας ἐκεῖνός ἐστι. τούτῳ δὴ κατὰ γένος προσήκων ὁ Οὐαλλέριος, ὥς φασι, βασιλευομένης μὲν ἔτι τῆς Ῥώμης ἐπιφανὴς ἦν διὰ λόγον καὶ πλοῦτον, ὧν τῷ μὲν ὀρθῶς καὶ μετὰ παρρησίας ἀεὶ χρώμενος ὑπὲρ τῶν δικαίων, ἀφ’ οὗ δὲ τοῖς δεομένοις ἐλευθερίως καὶ φιλανθρώπως ἐπαρκῶν, δῆλος ἦν εὐθύς, εἰ γένοιτο δημοκρατία, πρωτεύσων.", "st": "Publ. 1.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Ταρκύνιον Σούπερβον οὔτε λαβόντα τὴν ἀρχήν καλῶς, ἀλλ’ ἀνοσίως καὶ παρανόμως, οὔτε χρώμενον αὐτῇ βασιλικῶς, ἀλλ’ ὑβρίζοντα καὶ τυραννοῦντα, μισῶν ὁ δῆμος καὶ βαρυνόμενος, ἀρχήν ἀποστάσεως ἔλαβε τὸ Λουκρητίας πάθος αὑτὴν ἐπὶ τῷ βιασθῆναι διεργασαμένης, καὶ Λεύκιος Βροῦτος ἁπτόμενος τῶν πραγμάτων τῆς μεταβολῆς ἐπὶ πρῶτον ἦλθε τὸν Οὐαλλέριον καὶ χρησάμενος αὐτῷ προθυμοτάτῳ συνεξέβαλε τοὺς βασιλεῖς, μέχρι μὲν ἐπίδοξος ἦν ὁ δῆμος ἕνα χειροτονήσειν ἀντὶ τοῦ βασιλέως στρατηγόν, ἡσυχίαν ἦγεν ὁ Οὐαλλέριος, ὡς τῷ Βρούτῳ μᾶλλον ἄρχειν προσῆκον ἡγεμόνι τῆς ἐλευθερίας γεγενημένῳ· δυσχεραινομένου δὲ τοῦ τῆς μοναρχίας ὀνόματος, καὶ δοκοῦντος ἂν ἀλυπότερον τοῦ δήμου μερισθεῖσαν ὑπομεῖναι τὴν ἀρχήν καὶ δύο προβαλλομένου καὶ καλοῦντος, ἐλπίζων μετὰ τὸν Βροῦτον αἱρεθήσεσθαι καὶ συνυπατεύσειν διήμαρτεν. ᾑρέθη γὰρ ἄκοντι τῷ Βρούτῳ συνάρχων ἀντὶ τοῦ Οὐαλλερίου Ταρκύνιος Κολλατῖνος, ὁ Λουκρητίας ἀνήρ, οὐδὲν ἀρετῇ Οὐαλλερίου διαφέρων, ἀλλ’ οἱ δυνατοί δεδιότες τοὺς βασιλεῖς ἔτι πολλὰ πειρῶντας ἔξωθεν καὶ μαλάσσοντας τὴν πόλιν, ἐβούλοντο τὸν ἐντονώτατον αὐτοῖς ἐχθρὸν ἔχειν στρατηγὸν ὡς οὐχ ὑφησόμενον.", "st": "Publ. 1.3"}, {"sp": "N", "t": "ἀγανακτῶν οὖν ὁ Οὐαλλέριος, εἰ μὴ πιστεύεται πάντα πράττειν ἕνεκα τῆς πατρίδος, ὅτι μηδὲν ἰδίᾳ κακὸν ὑπὸ τῶν τυράννων πέπονθε, τῆς τε βουλῆς ἀπέστη καὶ τὰς συνηγορίας ἀπεῖπε καὶ τὸ πράττειν τὰ κοινὰ παντελῶς ἐξέλιπεν, ὥστε καὶ λόγον τοῖς πολλοῖς παρασχεῖν καὶ φροντίδα, φοβουμένοις μὴ δι’ ὀργὴν προσθέμενος τοῖς βασιλεῦσιν ἀνατρέψῃ τὰ πράγματα καὶ τὴν πόλιν ἐπισφαλῶς ἔχουσαν· ἐπεὶ δὲ καὶ πρὸς ἑτέρους τινὰς ὑποψίαν ἔχων ὁ Βροῦτος ἐβούλετο διὰ σφαγίων ὁρκῶσαι τὴν βουλὴν καὶ προεῖπεν ἡμέραν, καταβὰς μάλα φαιδρὸς εἰς ἀγορὰν ὁ Οὐαλλέριος, καὶ πρῶτος ὀμόσας μηδὲν ἐνδώσειν μηδ’ ὑφήσεσθαι Ταρκυνίοις, ἀλλὰ πολεμήσειν κατὰ κράτος ὑπὲρ τῆς ἐλευθερίας, ἡδονήν τε τῇ βουλῇ καὶ θάρσος ἅμα τοῖς ἄρχουσι παρέσχεν. εὐθὺς δὲ καὶ τὰ ἔργα τὸν ὅρκον ἐβεβαίου. πρέσβεις γὰρ ἧκον ἀπὸ Ταρκυνίου γράμματα κομίζοντες ἐπαγωγὰ τοῦ δήμου καὶ λόγους ἐπιεικεῖς, οἷς μάλιστα τοὺς πολλοὺς ᾤοντο διαφθείρειν, λεγομένοις παρὰ βασιλέως ἀφεικέναι τὸ φρόνημα καὶ μετρίων δεῖσθαι δοκοῦντος. τούτους εἰς τὸ πλῆθος οἰομένων δεῖν τῶν ὑπάτων προαγαγεῖν οὐκ εἴασεν ὁ Οὐαλλέριος, ἀλλ’ ἐνέστη καὶ διεκώλυσεν ἀνθρώποις πένησι καὶ βαρυνομένοις μᾶλλον τῆς τυραννίδος τὸν πόλεμον ἀρχὰς καὶ προφάσεις νεωτερισμῶν ἐγγενέσθαι.", "st": "Publ. 2.1"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα πρέσβεις ἧκον ἕτεροι τῆς τε βασιλείας ἀφίστασθαι καὶ πολεμοῦντα παύσασθαι τὸν Ταρκύνιον λέγοντες, ἀπαιτεῖν δὲ τὰ χρήματα καὶ τὰς οὐσίας αὑτῷ καὶ φίλοις καὶ οἰκείοις, ἀφ’ ὧν διαβιώσονται φεύγοντες. ἐπικλωμένων δὲ πολλῶν καὶ μάλιστα τοῦ Κολλατίνου συναγορεύοντος, ἄτρεπτος ὢν ἀνὴρ καὶ τραχὺς ὀργὴν ὁ Βροῦτος ἐξέδραμεν εἰς ἀγοράν, προδότην ἀποκαλῶν τὸν συνάρχοντα, πολέμου καὶ τυραννίδος ἀφορμὰς χαριζόμενον οἷς δεινὸν ἦν ὄντως ἐφόδια φυγῆς ψηφίσασθαι. συνελθόντων δὲ τῶν πολιτῶν πρῶτος ἰδιώτης ἀνὴρ εἶπεν ἐν δήμῳ τότε Γάιος Μινούκιος, τῷ τε Βρούτῳ διακελευόμενος καὶ τοῖς Ῥωμαίοις παραινῶν ὁρᾶν ὅπως τὰ χρήματα μετ’ αὐτῶν ὄντα πολεμοίη πρὸς τοὺς τυράννους μᾶλλον ἢ μετ’ ἐκείνων πρὸς αὐτούς. οὐ μὴν ἀλλ’ ἔδοξε τοῖς Ῥωμαίοις τὴν ἐλευθερίαν ἔχουσιν, ὑπὲρ ἧς ἐπολέμουν, μὴ προέσθαι τὴν εἰρήνην ἕνεκα χρημάτων, ἀλλὰ συνεκβαλεῖν καὶ ταῦτα τοῖς τυράννοις.", "st": "Publ. 3.1"}, {"sp": "N", "t": "ἦν δὲ ἄρα Ταρκυνίῳ λόγος μὲν ἐλάχιστος τῶν χρημάτων, ἡ δ’ ἀπαίτησις ἅμα πεῖρα τοῦ δήμου καὶ κατασκευὴ προδοσίας, καὶ ταῦτ’ ἔπραττον οἱ πρέσβεις ὑπομένοντες ἐπὶ τῇ τῶν χρημάτων προφάσει, τὰ μὲν ἀποδίδοσθαι, τὰ δὲ φυλάττειν, τὰ δ’ ἀποπέμπειν φάσκοντες, ἄχρι οὗ διέφθειραν οἴκους δύο τῶν καλῶν κἀγαθῶν νομιζομένων, τὸν Ἀκυλλίων τρεῖς ἔχοντα βουλευτάς καὶ δύο τὸν Οὐιτελλίων. οὗτοι πάντες ἦσαν ἀπὸ μητέρων ἀδελφιδοῖ Κολλατίνου τοῦ ὑπατεύοντος, ἰδίᾳ δὲ Οὐιτελλίοις ἑτέρα πρὸς Βροῦτον οἰκειότης ὑπῆρχεν. ἀδελφὴν γὰρ αὐτῶν ὁ Βροῦτος εἶχε καὶ παῖδας ἐξ αὐτῆς πλείονας· ὧν δύο τοὺς ἐν ἡλικίᾳ συγγενεῖς ὄντας ἅμα καὶ συνήθεις οἱ Οὐιτέλλιοι προσηγάγοντο καὶ συνέπεισαν ἐν τῇ προδοσίᾳ γενέσθαι καὶ καταμίξαντας ἑαυτοὺς εἰς γένος μέγα τὸ τῶν Ταρκυνίων καὶ βασιλικὰς ἐλπίδας ἀπαλλαγῆναι τῆς τοῦ πατρὸς ἀβελτερίας καὶ χαλεπότητος· χαλεπότητα μὲν τὸ ἀπαραίτητον αὐτοῦ πρὸς τοὺς πονηροὺς λέγοντες, τῇ δ’ ἀβελτερίᾳ προσποιήματι καὶ παρακαλύμματι πολὺν χρόνον, ὡς ἔοικε, χρησάμενος ἀσφαλείας ἕνεκα πρὸς τοὺς τυράννους, οὐδ’ ὕστερον ἔφυγεν αὐτῆς τὴν ἐπωνυμίαν.", "st": "Publ. 3.3"}, {"sp": "N", "t": "ὡς δ’ οὖν συνεπείσθη τὰ μειράκια καὶ τοῖς Ἀκυλλίοις εἰς λόγους ἦλθεν, ὅρκον ὀμόσαι μέγαν ἔδοξε πᾶσι καὶ δεινόν, ἀνθρώπου σφαγέντος ἐπισπείσαντας αἷμα καὶ τῶν σπλάγχνων θιγόντας, ἐπὶ τούτοις εἰς τὴν Ἀκυλλίων οἰκίαν συνῆλθον. ἦν δ’ ὁ οἶκος, ἐν ᾧ ταῦτα δράσειν ἔμελλον, οἷον εἰκὸς, ὑπέρημος καὶ σκοτώδης. ἔλαθεν οὖν αὐτοὺς οἰκέτης ὄνομα Οὐινδίκιος ἔνδον κατακρύψας ἑαυτόν, οὐ κατ’ ἐπιβουλὴν ἢ προαίσθησίν τινα τοῦ μέλλοντος, ἀλλ’ ἔνδον ὢν ἔτυχε καὶ προσιοῦσιν αὐτοῖς μετὰ σπουδῆς ὀφθῆναι φοβηθείς ὑπέστη, λάρνακα κειμένην πρὸ αὑτοῦ ποιησάμενος, ὥστε καὶ τῶν πραττομένων θεατὴς γενέσθαι καὶ τῶν βουλευμάτων ἐπήκοος. ἔδοξε δ’ αὐτοῖς τοὺς ὑπάτους ἀναιρεῖν, καὶ ταῦτα δηλούσας γράψαντες ἐπιστολὰς πρὸς τὸν Ταρκύνιον ἔδοσαν τοῖς πρέσβεσι· καὶ γὰρ ᾤκουν αὐτόθι, τῶν Ἀκυλλίων ξένοι γεγονότες, καὶ τότε τῇ συνωμοσίᾳ παρῆσαν.", "st": "Publ. 4.1"}, {"sp": "N", "t": "ὡς δὲ ταῦτα πράξαντες ἀπηλλάγησαν, ὑπεξελθὼν ὁ Οὐινδίκιος λάθρα, χρήσασθαι τοῖς προσπεσοῦσιν οὐκ εἶχεν, ἀλλ’ ἠπορεῖτο, δεινὸν μὲν ἡγούμενος, ὥσπερ ἦν, πρὸς πατέρα Βροῦτον υἱῶν ἐξάγιστα κατηγορεῖν ἢ πρὸς θεῖον ἀδελφιδῶν τὸν Κολλατῖνον, ἰδιώτην δὲ Ῥωμαίων οὐδένα νομίζων ἐχέγγυον ἀπορρήτων τηλικούτων. πᾶν δ’ αὖ μᾶλλον ἢ δυνατὸς ὢν ἡσυχίαν ἄγειν, ἐλαυνόμενος δὲ τῷ συνειδότι τοῦ πράγματος, ὥρμησέ πως πρὸς τὸν Οὐαλλέριον, μάλιστά τοῖς κοινοῖς καὶ φιλανθρώποις ἐπαχθεὶς τοῦ ἀνδρός, ὅτι πᾶσιν εὐπρόσοδος ἦν τοῖς δεομένοις, καὶ τὴν οἰκίαν ἀεὶ παρεῖχεν ἀνεῳγμένην, καὶ λόγον οὐδενὸς οὐδὲ χρείαν ἀπερρίπτει τῶν ταπεινῶν.", "st": "Publ. 4.3"}, {"sp": "N", "t": "ὡς οὖν ἀνέβη πρὸς αὐτὸν ὁ Οὐινδίκιος καὶ κατεῖπε πάντα, Μάρκου τε τοῦ ἀδελφοῦ παρόντος αὐτῷ μόνου καὶ τῆς γυναικός, ἐκπλαγεὶς καὶ δείσας ὁ Οὐαλλέριος οὐκέτι προήκατο τὸν ἄνθρωπον, ἀλλὰ κατακλείσας εἰς τὸ οἴκημα καὶ φύλακα τὴν ἑαυτοῦ γυναῖκα ταῖς θύραις ἐπιστήσας, τὸν μὲν ἀδελφὸν ἐκέλευσε τὴν βασιλικὴν ἔπαυλιν περισχόντα τὰ γράμματα λαβεῖν, ἂν δυνατὸν ᾖ, καὶ τοὺς οἰκέτας παραφυλάττειν αὐτὸς δὲ πελατῶν τε πολλῶν καὶ φίλων ἀεὶ περὶ αὐτὸν ὄντων καὶ θεραπείας συχνῆς, ἐβάδιζε πρὸς τὴν οἰκίαν τῶν Ἀκυλλίων οὐκ ἔνδον ὄντων. διὸ μηδενὸς ἂν προσδοκήσαντος ὠσάμενος διὰ θυρῶν ἐπιτυγχάνει τοῖς γράμμασι κειμένοις ὅπου κατέλυον οἱ πρέσβεις, ταῦτα δ’ αὐτοῦ πράττοντος οἱ Ἀκύλλιοι δρόμῳ προσεφέροντο, καὶ περὶ τὰς θύρας συμμίξαντες ἐζήτουν ἀφελέσθαι τὰς ἐπιστολάς. οἱ δ’ ἠμύνοντο, καὶ τὰ ἱμάτια περιβαλόντες αὐτῶν τοῖς τραχήλοις ὑπὸ βίας καὶ μόλις ὠθούμενοι καὶ ὠθοῦντες διὰ τῶν στενωπῶν εἰς τὴν ἀγορὰν ἐνέβαλον. τὰ δ’ αὐτὰ καὶ περὶ τὴν ἔπαυλιν ἅμα τὴν βασιλικὴν ἐγίνετο, τοῦ Μάρκου γραμμάτων ἑτέρων ἐν τοῖς σκεύεσι κομιζομένων ἐπιλαμβανομένου, καὶ τῶν βασιλικῶν ὅσους δυνατὸς ἦν ἕλκοντος εἰς τὴν ἀγοράν.", "st": "Publ. 5.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τὸν θόρυβον κατέπαυσαν οἱ ὕπατοι καὶ τοῦ Οὐαλλερίου κελεύσαντος ἐκ τῆς οἰκίας ὁ Οὐινδίκιος προήχθη, καί γενομένης κατηγορίας ἀνεγνώσθη τὰ γράμματα καί πρὸς οὐδὲν ἐτόλμησαν ἀντειπεῖν οἱ ἄνδρες, ἦν μὲν κατήφεια καί σιωπὴ τῶν ἄλλων, ὀλίγοι δὲ βουλόμενοι τῷ Βρούτῳ χαρίζεσθαι φυγῆς ἐμέμνηντο. καί τι καί Κολλατῖνος αὐτοῖς ἐλπίδος ἐπιεικοῦς ἐνεδίδου δεδακρυμένος καί Οὐαλλέριος σιωπῶν, ὁ δὲ Βροῦτος ὀνομαστὶ τῶν υἱῶν ἑκάτερον προσειπών, ἄγε, ὦ Τίτε, εἶπεν, ἄγε, ὦ Τιβέριε, τί οὐκ ἀπολογεῖσθε πρὸς τὴν κατηγορίαν; ὡς δ’ οὐδὲν ἀπεκρίναντο τρὶς ἐρωτηθέντες, οὕτως πρὸς τοὺς ὑπηρέτας ἀποστρέψας τὸ πρόσωπον, ὑμέτερον ἤδη, εἶπε, τὸ λοιπὸν ἔργον. οἱ δὲ εὐθὺς συλλαβόντες τοὺς νεανίσκους περιερρήγνυον τὰ ἱμάτια, τὰς χεῖρας ἀπῆγον ὀπίσω, ῥάβδοις ἔξαινον τὰ σώματα, τῶν μὲν ἄλλων οὐ δυναμένων προσορᾶν οὐδὲ καρτερούντων, ἐκεῖνον δὲ λέγεται μήτε τὰς ὄψεις ἀπαγαγεῖν ἀλλαχόσε μήτε οἴκτῳ τι τρέψαι τῆς περὶ τὸ πρόσωπον ὀργῆς καί βαρύτητος, ἀλλὰ δεινὸν ἐνορᾶν κολαζομένοις τοῖς παισίν ἄχρι οὗ κατατείναντες αὐτοὺς ἐπὶ τοὔδαφος πελέκει τὰς κεφαλὰς ἀπέκοψαν, οὕτω δὲ τοὺς ἄλλους ἐπὶ τῷ συνάρχοντι ποιησάμενος ᾤχετ’ ἐξαναστάς, ἔργον εἰργασμένος οὔτ’ ἐπαινεῖν βουλομένοις ἀξίως οὔτε ψέγειν ἐφικτόν. ἢ γὰρ ἀρετῆς ὕψος εἰς ἀπάθειαν ἐξέστησε τὴν ψυχήν, ἢ πάθους μέγεθος εἰς ἀναλγησίαν. οὐδέτερον δὲ μικρὸν οὐδ’ ἀνθρώπινον, ἀλλ’ ἢ θεῖον ἢ θηριῶδες. δίκαιον δὲ τῇ δόξῃ τοῦ ἀνδρὸς τὴν κρίσιν ἕπεσθαι μᾶλλον ἢ τὴν ἀρετὴν ἀσθενείᾳ τοῦ κρίνοντος ἀπιστεῖσθαι. Ῥωμαῖοι γὰρ οὐ τοσοῦτον ἔργον οἴονται Ῥωμύλου γενέσθαι τῆς πόλεως τὴν ἵδρυσιν, ὅσον Βρούτου τὴν κτίσιν τῆς πολιτείας καί κατάστασιν.", "st": "Publ. 6.1"}, {"sp": "N", "t": "ὡς δ’ οὖν ἀπῆλθεν ἐξ ἀγορᾶς τότε, πολὺν μὲν χρόνον ἔκπληξις εἶχε καὶ φρίκη καὶ σιωπὴ πάντας ἐπὶ τοῖς διαπεπραγμένοις· πρὸς δὲ τὴν Κολλατίνου μαλακίαν καὶ μέλλησιν ἀνεθάρρησαν οἱ Ἀκύλλιοι, καὶ χρόνον ἠξίουν λαβόντες ἀπολογήσασθαι, καὶ τὸν Οὐινδίκιον αὐτοῖς ἀποδοθῆναι δοῦλον ὄντα, καὶ μὴ παρὰ τοῖς κατηγόροις εἶναι. βουλομένου δὲ ταῦτα συγχωρεῖν καὶ διαλύοντος ἐπὶ τούτοις τὴν ἐκκλησίαν, ὁ Οὐαλλέριος οὔτε τὸν ἄνθρωπον οἷός τ’ ἦν ἀφεῖναι τῷ περὶ αὐτὸν ὄχλῳ καταμειγμένον, οὔτε τὸν δῆμον εἴα προέμενον τοὺς προδότας ἀπελθεῖν. τέλος δὲ τοῖς σώμασιν ἐπιβαλὼν τὰς χεῖρας ἐπεκαλεῖτο τὸν Βροῦτον, καὶ τὸν Κολλατῖνον ἐβόα δεινὰ ποιεῖν, εἰ τῷ συνάρχοντι παιδοφονίας ἀνάγκην προστριψάμενος αὐτὸς οἴεται δεῖν καταχαρίζεσθαι ταῖς γυναιξὶ τοὺς προδότας καὶ πολεμίους τῆς πατρίδος. ἀγανακτοῦντος δὲ τοῦ ὑπάτου καὶ κελεύοντος ἀπάγεσθαι τὸν Οὐινδίκιον, οἱ μὲν ὑπηρέται διωσάμενοι τὸν ὄχλον ἥπτοντο τοῦ ἀνθρώπου καὶ τοὺς ἀφαιρουμένους ἔτυπτον, οἱ δὲ φίλοι τοῦ Οὐαλλερίου προέστησαν ἀμυνόμενοι· καὶ ὁ δῆμος ἐβόα κελεύων παρεῖναι τὸν Βροῦτον. ἧκεν οὖν αὖθις ὑποστρέψας· καὶ γενομένης αὐτῷ σιωπῆς εἶπεν ὅτι τοῖς μὲν υἱοῖς αὐτὸς ἀποχρῶν ἦν δικαστής, περὶ δὲ τῶν ἄλλων τοῖς πολίταις ἐλευθέροις οὖσι ψῆφον δίδωσι· λεγέτω δὲ ὁ βουλόμενος καὶ πειθέτω τὸν δῆμον. οὐκέτι μέντοι λόγων ἐδέησεν, ἀλλὰ τῆς ψήφου δοθείσης πάσαις ἁλόντες ἐπελεκίσθησαν.", "st": "Publ. 7.1"}, {"sp": "N", "t": "ὁ δὲ Κολλατῖνος ἦν μὲν, ὡς ἔοικεν, ἐν ὑποψίᾳ τινὶ καὶ διὰ συγγένειαν τῶν βασιλέων, ἤχθοντο δ’ αὐτοῦ καὶ τῷ δευτέρῳ τῶν ὀνομάτων, ἀφοσιούμενοι τὸν Ταρκύνιον. ὡς δὲ καὶ ταῦτα συνέβη, παντάπασι προσκρούσας ἀφῆκε τὴν ἀρχὴν ἑκὼν καὶ τῆς πόλεως ὑπεξῆλθεν. οὕτω δὴ πάλιν ἀρχαιρεσιῶν γενομένων ὕπατος ἀπεδείχθη λαμπρῶς ὁ Οὐαλλέριος, ἀξίαν ἀπολαβὼν τῆς προθυμίας χάριν· ἧς οἰόμενός τι δεῖν ἀπολαῦσαι τὸν Οὐινδίκιον ἐψηφίσατο πρῶτον ἀπελεύθερον ἐκεῖνον ἐν Ῥώμῃ γενέσθαι πολίτην καὶ φέρειν ψῆφον ᾗ βούλοιτο φρατρίᾳ προσνεμηθέντα. τοῖς δ’ ἄλλοις ἀπελευθέροις ὀψὲ καὶ μετὰ πολὺν χρόνον ἐξουσίαν ψήφου δημαγωγῶν ἔδωκεν Ἄππιος ἡ δὲ παντελὴς ἀπελευθέρωσις ἄχρι νῦν οὐινδίκτα λέγεται δι’ ἐκεῖνον, ὥς φασι, τὸν Οὐινδίκιον.", "st": "Publ. 7.4"}, {"sp": "N", "t": "ἐκ τούτου τὰ μὲν χρήματα τῶν βασιλέων διαρπάσαι τοῖς Ῥωμαίοις ἔδωκαν, τὴν δὲ οἰκίαν κατέσκαψαν καὶ τὴν ἔπαυλιν τοῦ δ’ Ἀρείου πεδίου τὸ ἥδιστον ἐκέκτητο Ταρκύνιος, καὶ τοῦτο τῷ θεῷ καθιέρωσαν, ἔτυχε δὲ τεθερισμένον ἄρτι, καὶ κειμένων ἔτι τῶν δραγμάτων οὐκ ᾤοντο δεῖν ἀλοᾶν οὐδὲ χρῆσθαι διὰ τὴν καθιέρωσιν, ἀλλὰ συνδραμόντες ἐφόρουν τὰς ἀμάλλας εἰς τὸν ποταμόν. ὡς δ’ αὕτως καὶ τὰ δένδρα κόπτοντες ἐνέβαλλον, ἀργὸν παντάπασι τὸ χωρίον ἀνιέντες τῷ θεῷ καὶ ἄκαρπον. ὠθουμένων δὲ πολλῶν ἐπ’ ἀλλήλοις καὶ ἀθρόων ὑπήγαγεν ὁ ῥοῦς οὐ πολὺν τόπον, ἀλλ’ ὅπου τὰ πρῶτα συνενεχθέντα καὶ περιπεσόντα τοῖς στερεοῖς ὑπέστη, τῶν ἐπιφερομένων διέξοδον οὐκ ἐχόντων, ἀλλ’ ἐνισχομένων καὶ περιπλεκομένων, ἐλάμβανεν ἡ σύμπηξις ἰσχὺν καὶ ῥίζωσιν αὐξανομένην ὑπὸ τοῦ ῥεύματος. ἰλύν τε γὰρ ἐπήγαγε πολλήν, ἣ προσισταμένη τροφὴν παρεῖχεν ἅμα καὶ κόλλησιν, αἵ τε πληγαὶ σάλον οὐκ ἐποίουν, ἀλλὰ μαλακῶς πιέζουσαι συνήλαυνον εἰς ταὐτὸ πάντα καὶ συνέπλαττον. ὑπὸ δὲ μεγέθους καὶ στάσεως ἕτερον αὐτὸ μέγεθος ἐκτᾶτο καὶ χώραν ἀναδεχομένην τὰ πλεῖστα τῶν ὑπὸ τοῦ ποταμοῦ καταφερομένων. τοῦτο νῦν νῆσός ἐστιν ἱερὰ κατὰ τὴν πόλιν, ἔχει δὲ ναοὺς θεῶν καὶ περιπάτους, καλεῖται δὲ φωνῇ τῇ Λατίνων Μέση δυεῖν γεφυρῶν.", "st": "Publ. 8.1"}, {"sp": "N", "t": "ἔνιοι δὲ τοῦτο συμπεσεῖν ἱστοροῦσιν οὐχ ὅτε Ταρκυνίου καθιερώθη τὸ πεδίον, ἀλλὰ χρόνοις ὕστερον ἄλλο χωρίον ὁμοροῦν ἐκείνῳ Ταρκυνίας ἀνείσης. ἡ δὲ Ταρκυνία παρθένος ἦν ἱέρεια, μία τῶν Ἑστιάδων, ἔσχε δὲ τιμὰς ἀντὶ τούτου μεγάλας, ἐν αἷς ἦν καὶ τὸ μαρτυρίαν αὐτῆς δέχεσθαι μόνης γυναικῶν, τὸ δ’ ἐξεῖναι γαμεῖσθαι ψηφισαμένων οὐ προσεδέξατο. καὶ ταῦτα μὲν οὕτω γενέσθαι μυθολογοῦσι.", "st": "Publ. 8.4"}, {"sp": "N", "t": "Ταρκύνιον δὲ τὴν ἐκ προδοσίας ἀπογνόντα τῆς ἀρχῆς ἀνάληψιν ἐδέξαντο Τυρρηνοὶ προθύμως καὶ μεγάλῃ δυνάμει κατῆγον. ἀντεξῆγον δὲ τοὺς Ῥωμαίους οἱ ὕπατοι, καὶ παρέταξαν ἐν χωρίοις ἱεροῖς, ὧν τὸ μὲν Ἄρσιον ἄλσος, τὸ δὲ Αἰσούειον λειμῶνα προσαγορεύουσιν. ἀρχομένων δὲ αὑτῶν συνάγειν εἰς χεῖρας Ἄρρων ὁ Ταρκυνίου παῖς καὶ Βροῦτος ὁ Ῥωμαίων ὕπατος οὐ κατὰ τύχην ἀλλήλοις περιπεσόντες, ἀλλ’ ὑπ’ ἔχθους καὶ ὀργῆς, ὁ μὲν ὡς ἐπὶ τύραννον καὶ πολέμιον τῆς πατρίδος, ὁ δὲ τῆς φυγῆς ἀμυνόμενος, ὥρμησαν ὁμόσε τοῖς ἵπποις. θυμῷ δὲ μᾶλλον ἢ λογισμῷ προσμίξαντες ἠφείδησαν αὑτῶν καὶ συναπέθανον ἀλλήλοις. οὕτω δὲ δεινοῦ γενομένου τοῦ προάγωνος οὐκ ἔσχεν ὁ ἀγὼν τέλος ἐπιεικέστερον, ἀλλὰ καὶ δράσαντες ἴσα καὶ παθόντες οἱ στρατοὶ διεκρίθησαν ὑπὸ χειμῶνος.", "st": "Publ. 9.1"}, {"sp": "N", "t": "ἦν οὖν ἐν ἀπόροις ὁ Οὐαλλέριος, οὐκ εἰδὼς τὸ τῆς μάχης πέρας, ἀλλὰ τοὺς στρατιώτας ὁρῶν τοῖς μὲν αὑτῶν νεκροῖς ἀθυμοῦντας, ἐπαιρομένους δὲ τοῖς τῶν πολεμίων οὕτως ἄκριτος ἦν καὶ παράλληλος ὑπὸ πλήθους ὁ φόνος, οὐ μὴν ἀλλ’ ἑκατέροις ἐγγύθεν ὁρώμενα τὰ οἰκεῖα μᾶλλον ἐβεβαίου τὴν ἧτταν ἢ τὴν νίκην εἰκαζόμενα τὰ τῶν πολεμίων. ἐπελθούσης δὲ νυκτὸς οἵαν εἰκὸς οὕτω μεμαχημένοις, καὶ γενομένων ἐν ἡσυχίᾳ τῶν στρατοπέδων, λέγουσι σεισθῆναι τὸ ἄλσος, ἐκ δ’ αὐτοῦ φωνὴν ἐκπεσεῖν μεγάλην φράζουσαν ὡς ἑνὶ πλείους ἐν τῇ μάχῃ τεθνήκασι Τυρρηνῶν ἢ Ῥωμαίων, ἦν δ’ ἄρα θεῖόν τι τὸ φθεγξάμενον εὐθύς τε γὰρ ὑπ’ αὐτοῦ τοῖς μὲν ἀλαλάξαι παρέστη μέγα καὶ θαρραλέον, οἱ δὲ Τυρρηνοὶ περίφοβοι γενόμενοι καὶ συνταραχθέντες ἐξέπεσον ἐκ τοῦ στρατοπέδου καὶ διεσπάρησαν οἱ πλεῖστοι· τοὺς δὲ καταλειφθέντας ὀλίγῳ πεντακισχιλίων ἐλάσσους ἐπελθόντες εἷλον οἱ Ῥωμαῖοι, καὶ τἆλλα διήρπασαν. οἱ δὲ νεκροὶ διαριθμηθέντες εὑρέθησαν τριακόσιοι μὲν ἐπὶ χιλίοις καὶ μυρίοις οἱ τῶν πολεμίων, οἱ δὲ Ῥωμαίων παρ’ ἕνα τοσοῦτοι.", "st": "Publ. 9.3"}, {"sp": "N", "t": "ταύτην τὴν μάχην λέγουσι γενέσθαι πρὸ μιᾶς καλανδῶν Μαρτίων, ἐθριάμβευσε δ’ ἀπ’ αὐτῆς Οὐαλλέριος εἰσελάσας τεθρίππῳ πρῶτος ὑπάτων. καὶ τὸ πρᾶγμα σεμνὴν καὶ μεγαλοπρεπῆ παρέσχεν ὄψιν, οὐκ ἐπίφθονον οὐδ’ ἀνιάσασαν, ὡς ἔνιοι λέγουσι, τοὺς ὁρῶντας· οὐ γὰρ ἂν ἔσχε ζῆλον τοσοῦτον οὐδὲ φιλοτιμίαν εἰς ἔτη πάμπολλα διαμένουσαν. ἀπεδέξαντο δὲ τοῦ Οὐαλλερίου καὶ τὰς εἰς τὸν συνάρχοντα τιμάς, αἷς ἐκκομιζόμενον καὶ θαπτόμενον ἐκόσμησε· καὶ λόγον ἐπ’ αὐτῷ διεξῆλθεν ἐπιτάφιον, ὃς οὕτως ὑπὸ Ῥωμαίων ἠγαπήθη καὶ τοσαύτην ἔσχε χάριν ὥστε πᾶσι τοῖς ἀγαθοῖς καὶ μεγάλοις ὑπάρχειν ἐξ ἐκείνου τελευτήσασιν ὑπὸ τῶν ἀρίστων ἐγκωμιάζεσθαι. λέγεται δὲ καὶ τῶν Ἑλληνικῶν ἐπιταφίων ἐκεῖνος γενέσθαι πρεσβύτερος, εἴγε μὴ καὶ τοῦτο Σόλωνός ἐστιν, ὡς Ἀναξιμένης ὁ ῥήτωρ ἱστόρηκεν.", "st": "Publ. 9.6"}, {"sp": "N", "t": "ἀλλὰ δι’ ἐκεῖνα μᾶλλον ἤχθοντο τῷ Οὐαλλερίῳ καὶ προσέκρουον, ὅτι Βροῦτος μέν, ὃν πατέρα τῆς ἐλευθερίας ἐνόμιζεν ὁ δῆμος, οὐκ ἠξίωσε μόνος ἄρχειν, ἀλλὰ καὶ πρῶτον αὐτῷ συνάρχοντα προσείλετο καὶ δεύτερον οὑτοσὶ δ’, ἔφασαν, εἰς αὐτόν ἅπαντα συνενεγκάμενος οὐκ ἔστι τῆς Βρούτου κληρονόμος ὑπατείας μηδὲν αὐτῷ προσηκούσης, ἀλλὰ τῆς Ταρκυνίου τυραννίδος. καίτοι τί δεῖ λόγῳ μὲν Βροῦτον ἐγκωμιάζειν, ἔργῳ δὲ μιμεῖσθαι Ταρκύνιον, ὑπὸ ῥάβδοις ὁμοῦ πάσαις καὶ πελέκεσι κατιόντα μόνον ἐξ οἰκίας τοσαύτης τὸ μέγεθος ὅσην οὐ καθεῖλε τὴν τοῦ βασιλέως; καὶ γὰρ ὄντως ὁ Οὐαλλέριος ᾤκει τραγικώτερον ὑπὲρ τὴν καλουμένην Οὐελίαν οἰκίαν ἐπικρεμαμένην τῇ ἀγορᾷ καὶ καθορῶσαν ἐξ ὕψους ἅπαντα, δυσπρόσοδον δὲ πελάσαι καὶ χαλεπὴν ἔξωθεν, ὥστε καταβαίνοντος αὐτοῦ τὸ σχῆμα μετέωρον εἶναι καὶ βασιλικὸν τῆς προπομπῆς τὸν ὄγκον. ὅσον οὖν ἐν ἀρχῇ καὶ πράγμασι μεγάλοις ἀγαθὸν ἦν ἔχειν ὦτα παρρησίαν ἀντὶ κολακείας προσιέμενα καὶ λόγους ἀληθεῖς, ἔδειξεν. ἀκούσας γὰρ ὅτι τοῖς πολλοῖς ἁμαρτάνειν ἐδόκει τῶν φίλων διεξιόντων, οὐκ ἐφιλονείκησεν, οὐδ’ ἠγανάκτησεν, ἀλλὰ ταχὺ πολλοὺς συναγαγὼν τεχνίτας ἔτι νυκτὸς οὔσης κατέβαλε τὴν οἰκίαν καὶ κατέσκαψεν εἰς ἔδαφος πᾶσαν, ὥστε μεθ’ ἡμέραν τούς Ῥωμαίους ὁρῶντας καὶ συνισταμένους τοῦ μὲν ἀνδρὸς ἀγαπᾶν καὶ θαυμάζειν τὴν μεγαλοφροσύνην, ἄχθεσθαι δὲ τῆς οἰκίας καὶ ποθεῖν τὸ μέγεθος καὶ τὸ κάλλος, ὥσπερ ἀνθρώπου, διὰ φθόνον οὐ δικαίως καταλελυμένης, τοῦ δὲ ἄρχοντος, ὥσπερ ἀνεστίου, παρ’ ἑτέροις οἰκοῦντος. ἐδέχοντο γὰρ οἱ φίλοι τὸν Οὐαλλέριον ἄχρι οὗ τόπον ἔδωκεν ὁ δῆμος αὐτῷ καὶ κατεσκεύασεν οἰκίαν ἐκείνης μετριωτέραν, ὅπου νῦν ἱερόν ἐστιν Οὐίκας Πότας ὀνομαζόμενον.", "st": "Publ. 10.1"}, {"sp": "N", "t": "βουλόμενος δὲ μὴ μόνον ἑαυτὸν, ἀλλὰ καὶ τὴν ἀρχὴν ἀντὶ φοβερᾶς χειροήθη καὶ προσφιλῆ ποιεῖν τοῖς πολλοῖς, τούς τε πελέκεις ἀπέλυσε τῶν ῥάβδων, αὐτάς τε τὰς ῥάβδους εἰς ἐκκλησίαν παριὼν ὑφῆκε τῷ δήμῳ καὶ κατέκλινε, μέγα ποιῶν τὸ πρόσχημα τῆς δημοκρατίας, καὶ τοῦτο μέχρι νῦν διαφυλάττουσιν οἱ ἄρχοντες. ἐλάνθανε δὲ τούς πολλοὺς οὐχ ἑαυτὸν, ὡς ᾤοντο, ποιῶν ταπεινόν, ἀλλὰ τὸν φθόνον τῇ μετριότητι ταύτῃ καθαιρῶν καὶ κολούων, αὐτῷ δὲ προστιθεὶς τοσοῦτον μέγεθος δυνάμεως ὅσον ἀφαιρεῖν ἐδόκει τῆς ἐξουσίας, ὑποδυομένου μεθ’ ἡδονῆς αὐτῷ τοῦ δήμου καὶ φέροντος ἑκουσίως, ὥστε καὶ Ποπλικόλαν ἀνηγόρευσεν αὐτόν σημαίνει δὲ τοὔνομα δημοκηδῆ· καὶ τοῦτο μᾶλλον ἴσχυσε τῶν ἀρχαίων ὀνομάτων, ᾧ καὶ ἡμεῖς χρησόμεθα τὸν λοιπὸν βίον τοῦ ἀνδρὸς ἱστοροῦντες.", "st": "Publ. 10.5"}, {"sp": "N", "t": "ὑπατείαν μὲν γὰρ ἔδωκε μετιέναι καὶ παραγγέλλειν τοῖς βουλομένοις· πρὸ δὲ τῆς καταστάσεως τοῦ συνάρχοντος οὐκ εἰδὼς τὸν γενησόμενον, ἀλλὰ δεδιὼς ἀντίπραξιν ὑπὸ φθόνου τινὸς ἢ ἀγνοίας, ἐχρήσατο τῇ μοναρχίᾳ πρὸς τὰ κάλλιστα καὶ μέγιστα τῶν πολιτευμάτων, πρῶτον μὲν γὰρ ἀνεπλήρωσε τὴν βουλὴν ὀλιγανδροῦσαν ἐτεθνήκεσαν γὰρ οἱ μὲν ὑπὸ Ταρκυνίου πρότερον, οἱ δὲ ἔναγχος ἐν τῇ μάχῃ. τοὺς δ’ ἐγγραφέντας ὑπ’ αὐτοῦ λέγουσιν ἑκατὸν καὶ ἑξήκοντα τέσσαρας γενέσθαι. μετὰ δὲ ταῦτα νόμους ἔγραψεν, ὧν μάλιστα μὲν ἰσχυροὺς ἐποίησε τοὺς πολλοὺς ὁ τὸν δῆμον ἀπὸ τῶν ὑπάτων τῷ φεύγοντι δίκην ἐπικαλεῖσθαι διδούς· δεύτερος ὁ τοὺς ἀρχὴν ἀναλαβόντας, ἣν ὁ δῆμος οὐκ ἔδωκεν, ἀποθνῄσκειν κελεύων· τρίτος δὲ μετὰ τούτους, ὃς ἐβοήθησε τοῖς πένησιν, ᾧ τὰ τέλη τῶν πολιτῶν ἀφεῖλε καὶ προθυμότερον ἅπτεσθαι τῶν ἐργασιῶν ἐποίησεν ἅπαντας. ὁ δὲ γραφεὶς κατὰ τῶν ἀπειθούντων τοῖς ὑπάτοις οὐχ ἧττον ἔδοξε δημοτικὸς εἶναι, καὶ πρὸς τῶν πολλῶν μᾶλλον ἢ δυνατῶν γεγράφθαι. ζημίαν γὰρ ἀπειθείας ἔταξε βοῶν πέντε καὶ δυεῖν προβάτων ἀξίαν. ἦν δὲ τιμὴ προβάτου μὲν ὀβολοὶ δέκα, βοὸς δὲ ἑκατόν, οὔπω νομίσματι χρωμένων πολλῷ τότε Ῥωμαίων, ἀλλὰ προβατείαις καὶ κτηνοτροφίαις εὐθηνούντων. διὸ καὶ τὰς οὐσίας ἄχρι νῦν ἀπὸ τῶν προβάτων πεκούλια καλοῦσι, καὶ τῶν νομισμάτων τοῖς παλαιοτάτοις βοῦν ἐπεχάραττον ἢ πρόβατον ἢ σῦν. ἐτίθεντο δὲ καὶ παισὶν αὑτῶν Συΐλλους καὶ Βουβούλκους καὶ Καπραρίους ὀνόματα καὶ Πορκίους· κάπρας μὲν τὰς αἶγας, πόρκους δὲ τοὺς χοίρους ὀνομάζοντες.", "st": "Publ. 11.1"}, {"sp": "N", "t": "οὕτω δὲ περὶ ταῦτα δημοτικὸς γενόμενος νομοθέτης καὶ μέτριος, ἐν τῷ μὴ μετρίῳ τὴν τιμωρίαν ὑπερέτεινεν. ἔγραψε γὰρ νόμον ἄνευ κρίσεως κτεῖνια διδόντα τὸν βουλόμενον τυραννεῖν κτείναντα δὲ φόνου καθαρὸν ἐποίησεν, εἰ παράσχοιτο τοῦ ἀδικήματος τοὺς ἐλέγχους. ἐπεὶ γὰρ οὐ δυνατὸν ἐπιχειροῦντα τηλικούτοις λαθεῖν ἅπαντας, οὐκ ἀδύνατον δὲ τὸ μὴ λαθόντα τοῦ κριθῆναι φθάσαι κρείττονα γενόμενον, ἣν ἀναιρεῖ τὸ ἀδίκημα κρίσιν, προλαβεῖν ἔδωκε τῷ δυναμένῳ κατὰ τοῦ ἀδικοῦντος.", "st": "Publ. 12.1"}, {"sp": "N", "t": "ἐπῃνέθη δὲ καὶ διὰ τὸν ταμιευτικὸν νόμον. ἐπεὶ γὰρ ἔδει χρήματα πρὸς τὸν πόλεμον εἰσενεγκεῖν ἀπὸ τῶν οὐσιῶν τοὺς πολίτας, οὔτ’ αὐτὸς ἅψασθαι τῆς οἰκονομίας οὔτε τοὺς φίλους ἐᾶσαι βουλόμενος οὔθ’ ὅλως εἰς οἶκον ἰδιώτου παρελθεῖν δημόσια χρήματα, ταμιεῖον μὲν ἀπέδειξε τὸν τοῦ Κρόνου ναόν, ᾧ μέχρι νῦν χρώμενοι διατελοῦσι, ταμίας δὲ τῷ δήμῳ δύο τῶν νέων ἔδωκεν ἀποδεῖξαι· καὶ ἀπεδείχθησαν οἱ πρῶτοι Πούπλιος Ο ὐετούριος καὶ Μινούκιος Μᾶρκος καὶ χρήματα συνήχθη πολλά, τρισκαίδεκα γὰρ ἀπεγράψαντο μυριάδες, ὀρφανοῖς παισὶ καὶ χήραις γυναιξὶν ἀνεθείσης τῆς εἰσφορᾶς.", "st": "Publ. 12.2"}, {"sp": "N", "t": "ταῦτα δὲ διοικήσας ἀπέδειξεν ἑαυτῷ συνάρχοντα τὸν Λουκρητίας πατέρα Λουκρήτιον, ᾧ τῆς ἡγεμονικωτέρας ἐξιστάμενος ὄντι πρεσβυτέρῳ τάξεως παρέδωκε τοὺς καλουμένους φάσκης καὶ τοῦτο διέμεινεν εἰς ἡμᾶς τὸ πρεσβεῖον ἀπ’ ἐκείνου τοῖς γεραιτέροις φυλαττόμενον. ἐπεὶ δ’ ὀλίγαις ἡμέραις ὕστερον ἐτελεύτησεν ὁ Λουκρήτιος, πάλιν ἀρχαιρεσιῶν γενομένων ᾑρέθη Μᾶρκος Ὡράτιος, καὶ συνῆρχε τῷ Ποπλικόλᾳ τὸν ὑπολειπόμενον χρόνον τοῦ ἐνιαυτοῦ.", "st": "Publ. 12.4"}, {"sp": "N", "t": "Ταρκυνίου δὲ Ῥωμαίοις δεύτερον πόλεμον ἐν Τυρρηνίᾳ κινοῦντος μέγα σημεῖον λέγεται γενέσθαι· βασιλεύων γὰρ ἔτι καὶ τὸν νεὼν τοῦ Καπιτωλίου Διὸς ἔχων ὁ Ταρκύνιος ὅσον οὔπω συντετελεσμένον, εἴτε μαντείας γενομένης εἴτ’ αὐτῷ δόξαν ἄλλως, ἅρμα κατὰ κορυφὴν ἐπιστῆσαι κεραμεοῦν ἐξέδωκε Τυρρηνοῖς τισιν ἐξ Οὐηίων δημιουργοῖς, εἶτ’ ὀλίγον ὕστερον ἐξέπεσε τῆς ἀρχῆς. τῶν δὲ Τυρρηνῶν διαπεπλασμένον τὸ τέθριππον ἐμβαλόντων εἰς κάμινον, οὐκ ἔπαθεν ἃ προσήκει πάσχειν πηλὸν ἐν πυρί, πυκνοῦσθαι καὶ συνιζάνειν, ἐκτηκομένης τῆς ὑγρότητος, ἀλλ’ ἐξέστη καὶ ᾤδησε καὶ μέγεθος ἔσχεν ἅμα ῥώμῃ καὶ σκληρότητι τοσοῦτον ὥστε μόλις ἐξαιρεθῆναι τὴν ὀροφὴν ἀποσκευασαμένων τῆς καμίνου καὶ τῶν τοίχων περιαιρεθέντων. ὡς οὖν ἐδόκει τοῖς μάντεσι θεῖον εἶναι σημεῖον εὐτυχίας καὶ δυνάμεως παρ’ οἷς ἔσοιτο τὸ τέθριππον, ἔγνωσαν οἱ Οὐήιοι μὴ προέσθαι τοῖς Ῥωμαίοις ἀπαιτοῦσι, καὶ ἀπεκρίναντο τοῦτο Ταρκυνίοις, οὐ τοῖς Ταρκυνίους ἐκβαλοῦσι προσήκειν. ὀλίγαις δ’ ὕστερον ἡμέραις ἦσαν ἵππων ἀγῶνες αὐτοῖς. καὶ τὰ μὲν ἄλλα θέαν καὶ σπουδὴν εἰωθυῖαν παρεῖχε, τὸ δὲ νικῆσαν τέθριππον ὁ μὲν ἡνίοχος ἐξήλαυνε τοῦ ἱπποδρόμου σχέδην ἐστεφανωμένος, οἱ δὲ ἵπποι πτοηθέντες ἀπ’ οὐδεμιᾶς ἐμφανοῦς προφάσεως, ἀλλὰ κατά τι δαιμόνιον ἢ τύχην ἵεντο παντὶ τάχει πρὸς τὴν Ῥωμαίων πόλιν, ἔχοντες τὸν ἡνίοχον, ὡς οὐδὲν ἦν ἔργον αὐτοῦ κατατείνοντος οὐδὲ παρηγοροῦντος, ἀλλ’ ἥρπαστο, δόντα τῇ ῥύμῃ καὶ φερόμενον, ἄχρι οὗ τῷ Καπιτωλίῳ προσμίξαντες ἐξέβαλον αὐτὸν ἐνταῦθα παρὰ τὴν πύλην ἣν νῦν Ῥατουμέναν καλοῦσι. γενομένου δὲ τούτου θαυμάσαντες οἱ Οὐήιοι καὶ φοβηθέντες ἐπέτρεψαν ἀποδοῦναι τὸ ἅρμα τοῖς τεχνίταις.", "st": "Publ. 13.1"}, {"sp": "N", "t": "τὸν δὲ νεὼν τοῦ Καπιτωλίου Διὸς εὔξατο μὲν ἀναθήσειν Ταρκύνιος ὁ Δημαράτου πολεμῶν Σαβίνοις, ᾠκοδόμησε δὲ Ταρκύνιος ὁ Σούπερβος υἱὸς ὢν ἢ υἱωνὸς τοῦ εὐξαμένου· καθιερῶσαι δὲ οὐκ ἔφθασεν, ἀλλὰ μικρὸν ἀπελείπετο τοῦ τέλος ἔχειν ὅτε Ταρκύνιος ἐξέπιπτεν. ὡς οὖν ἀπείργαστο τελέως καὶ τὸν προσήκοντα κόσμον ἀπεῖχεν, ἦν τῷ Ποπλικόλᾳ φιλοτιμία πρὸς τὴν καθιέρωσιν. ἐφθόνουν δὲ πολλοὶ τῶν δυνατῶν, καὶ ἤχθοντο ταῖς μὲν ἄλλαις τιμαῖς ἧττον, ἃς νομοθετῶν καὶ στρατηγῶν ἐκ προσηκόντων ἔσχε· ταύτην δ’ οὖσαν ἀλλοτρίαν οὐκ ᾤοντο δεῖν αὐτῷ προσγενέσθαι, καὶ τὸν Ὡράτιον προετρέποντο καὶ παρώξυνον ἀντιποιεῖσθαι τῆς καθιερώσεως. γενομένης οὖν τῷ Ποπλικόλᾳ στρατείας ἀναγκαίας, ψηφισάμενοι τὸν Ὡράτιον καθιεροῦν ἀνῆγον εἰς τὸ Καπιτώλιον, ὡς οὐκ ἂν ἐκείνου περιγενόμενοι παρόντος. ἔνιοι δέ φασι κλήρῳ τῶν ὑπάτων λαχεῖν ἐκεῖνον ἐπὶ τὴν στρατείαν ἄκοντα, τοῦτον δὲ ἐπὶ τὴν καθιέρωσιν. ἔξεστι δὲ περὶ τούτων ὡς ἔσχεν εἰκάζειν τοῖς πραχθεῖσι περὶ τὴν καθιέρωσιν. εἰδοῖς οὖν Σεπτεμβρίαις, ὃ συντυγχάνει περὶ τὴν πανσέληνον μάλιστα τοῦ Μεταγειτνιῶνος, συνηθροισμένων ἁπάντων εἰς τὸ Καπιτώλιον, ὁ μὲν Ὡράτιος σιωπῆς γενομένης τά τ’ ἄλλα δράσας καὶ τῶν θυρῶν ἁψάμενος, ὥσπερ ἔθος ἐστίν, ἐπεφθέγγετο τὰς νενομισμένας ἐπὶ τῇ καθιερώσει φωνάς· ὁ δ’ ἀδελφὸς τοῦ Ποπλικόλα Μᾶρκος ἐκ πολλοῦ παρὰ τὰς θύρας ὑφεστὼς καὶ παραφυλάττων τὸν καιρόν, ὦ ὕπατε εἶπεν, ὁ υἱός σου τέθνηκεν ἐν τῷ στρατοπέδῳ νοσήσας. τοῦτο πάντας ἠνίασε τοὺς ἀκούσαντας ὁ δ’ Ὡράτιος οὐδὲν διαταραχθείς, ἀλλ’ ἢ τοσοῦτον μόνον εἰπών, ῥίψατε τοίνυν ὅποι βούλεσθε τὸν νεκρόν, ἐγὼ γὰρ οὐ προσίεμαι τὸ πένθος, ἐπέραινε τὴν λοιπὴν καθιέρωσιν. ἦν δὲ τὸ προσηγγελμένον οὐκ ἀληθές, ἀλλ’ ὁ Μᾶρκος ὡς ἀποστήσων τὸν Ὡράτιον ἐψεύσατο. θαυμαστὸς οὖν ὁ ἀνὴρ τῆς εὐσταθείας, εἴτε τὴν ἀπάτην ἐν καιρῷ βραχεῖ συνεῖδεν εἴτε πιστευθεὶς ὁ λόγος οὐκ ἐκίνησεν αὐτόν.", "st": "Publ. 14.1"}, {"sp": "N", "t": "ἔοικε δὲ καὶ περὶ τὸν δεύτερον ναὸν ὁμοία τύχη γενέσθαι τῆς καθιερώσεως, τὸν μὲν γὰρ πρῶτον, ὡς εἴρηται, Ταρκυνίου κατασκευάσαντος, Ὡρατίου δὲ καθιερώσαντος, ἐν τοῖς ἐμφυλίοις πολέμοις πῦρ ἀπώλεσε· τὸν δὲ δεύτερον ἀνέστησε μὲν Σύλλας, ἐπεγράφη δὲ τῇ καθιερώσει Κάτουλος Σύλλα προαποθανόντος. τούτου δὲ πάλιν ἐν ταῖς κατὰ Οὐιτέλλιον στάσεσι διαφθαρέντος τὸν τρίτον τῇ πρὸς τἆλλα καὶ τοῦτο χρησάμενος εὐποτμίᾳ Οὐεσπασιανὸς ἐξ ἀρχῆς ἄχρι τέλους ἀναγαγὼν, ἐπεῖδε γενόμενον καὶ φθειρόμενον μετ’ ὀλίγον οὐκ ἐπεῖδεν, ἀλλὰ τοσοῦτον εὐτυχίᾳ Σύλλαν παρῆλθεν ὅσον ἐκεῖνον μὲν τῆς ἀφιερώσεως τοῦ ἔργου, τοῦτον δὲ τῆς ἀναιρέσεως προαποθανεῖν. ἅμα γὰρ τῷ τελευτῆσαι Οὐεσπασιανὸν ἐνεπρήσθη τὸ Καπιτώλιον.", "st": "Publ. 15.1"}, {"sp": "N", "t": "ὁ δὲ τέταρτος οὗτος ὑπὸ Δομετιανοῦ καὶ συνετελέσθη καὶ καθιερώθη. λέγεται δὲ Ταρκύνιον εἰς τοὺς θεμελίους ἀναλῶσαι λίτρας ἀργυρίου τετρακισμυρίας· τούτου δὲ τοῦ καθ’ ἡμᾶς τὸν μέγιστον ἐν Ῥώμῃ τῶν ἰδιωτικῶν πλοῦτον ἐκλογισθέντα τὸ τῆς χρυσώσεως μὴ τελέσαι ἂν ἀνάλωμα, πλέον ἢ δισχιλίων καὶ μυρίων ταλάντων γενόμενον. οἱ δὲ κίονες ἐκ τοῦ Πεντελῆσιν ἐτμήθησαν λίθου, κάλλιστα τῷ πάχει πρὸς τὸ μῆκος ἔχοντες· εἴδομεν γὰρ αὐτοὺς Ἀθήνησιν. ἐν δὲ Ῥώμῃ πληγέντες αὖθις καὶ ἀναξυσθέντες οὐ τοσοῦτον ἔσχον γλαφυρίας ὅσον ἀπώλεσαν συμμετρίας καὶ τοῦ καλοῦ, διάκενοι καὶ λαγαροὶ φανέντες. ὁ μέντοι θαυμάσας τοῦ Καπιτωλίου τὴν πολυτέλειαν, εἰ μίαν εἶδεν ἐν οἰκίᾳ Δομετιανοῦ στοὰν ἢ βασιλικὴν ἢ βαλανεῖον ἢ παλλακίδων δίαιταν, οἷόν ἐστι τὸ λεγόμενον Ἐπιχάρμου πρὸς τὸν ἄσωτον,", "st": "Publ. 15.3"}, {"sp": "N", "t": "οὐ φιλάνθρωπος τύ γ’ ἐσσ’· ἔχεις νόσον χαίρεις διδούς,", "st": "Publ. 15.3b"}, {"sp": "N", "t": "τοιοῦτον ἄν τι πρὸς Δομετιανὸν εἰπεῖν προήχθη· οὐκ εὐσεβὴς οὐδὲ φιλότιμος τύ γ’ ἐσσί· ἔχεις νόσον χαίρεις κατοικοδομῶν, ὥσπερ ὁ Μίδας ἐκεῖνος, ἅπαντά σοι χρυσᾶ καὶ λίθινα βουλόμενος γίνεσθαι. ταῦτα μὲν οὖν περὶ τούτων.", "st": "Publ. 15.3c"}, {"sp": "N", "t": "ὁ δὲ Ταρκύνιος μετὰ τὴν μεγάλην μάχην ἐν ᾗ καὶ τὸν υἱὸν ἀπώλεσε μονομαχήσαντα Βρούτῳ, καταφυγὼν εἰς τὸ Κλούσιον ἱκέτευσε Λάραν Πορσίναν, ἄνδρα καὶ δύναμιν μεγίστην ἔχοντα τῶν Ἰταλικῶν βασιλέων καὶ δοκοῦντα χρηστὸν εἶναι καὶ φιλότιμον ὁ δ’ ὑπέσχετο βοηθήσειν. καὶ πρῶτον μὲν ἔπεμψεν εἰς Ῥώμην κελεύων δέχεσθαι τὸν Ταρκύνιον ὡς δ’ οὐχ ὑπήκουσαν οἱ Ῥωμαῖοι, καταγγείλας αὐτοῖς πόλεμον καὶ χρόνον ἐν ᾧ καὶ τόπον εἰς ὃν ἔμελλεν ἐμβαλεῖν, ἀφίκετο μετὰ πολλῆς δυνάμεως. Ποπλικόλας δ’ ᾑρέθη μὲν ἀπὼν ὕπατος τὸ δεύτερον, καὶ σὺν αὐτῷ Τίτος Λουκρήτιος· ἐπανελθὼν δὲ εἰς Ῥώμην καὶ βουλόμενος τῷ φρονήματι πρῶτον ὑπερβαλέσθαι τὸν Πορσίναν, ἔκτιζε πόλιν Σιγλιουρίαν ἤδη πλησίον ὄντος αὐτοῦ, καὶ τειχίσας μεγάλοις ἀναλώμασιν ἑπτακοσίους ἐποικοὺς ἀπέστειλεν, ὡς ῥᾳδίως φέρων καὶ ἀδεῶς τὸν πόλεμον. οὐ μὴν ἀλλὰ προσβολῆς ὀξείας τῷ τείχει γενομένης ἐξεώσθησαν οἱ φύλακες ὑπὸ τοῦ Πορσίνα, καὶ φεύγοντες ὀλίγου συνεπεσπάσαντο τοὺς πολεμίους εἰς τὴν πόλιν. ἔφθη δὲ πρὸ τῶν πυλῶν ἐκβοηθήσας ὁ Ποπλικόλας, καὶ μάχην συνάψας παρὰ τὸν ποταμόν ἀντεῖχε πλήθει βιαζομένοις τοῖς πολεμίοις, ἄχρι οὗ τραύμασι νεανικοῖς περιπεσὼν ἀπεκομίσθη φοράδην ἐκ τῆς μάχης. τὸ δ’ αὐτὸ καὶ Λουκρητίου τοῦ συνάρχοντος αὐτῷ παθόντος ἀθυμία τοῖς Ῥωμαίοις ἐνέπεσε, καὶ φυγῇ πρὸς τὴν πόλιν ἔσῳζον ἑαυτούς, ὠθουμένων δὲ τῶν πολεμίων διὰ τῆς ξυλίνης γεφύρας ἐκινδύνευσεν ἡ Ῥώμη κατὰ κράτος ἁλῶναι. πρῶτος δὲ Κόκλιος Ὡράτιος καὶ σὺν αὐτῷ δύο τῶν ἐπιφανεστάτων ἀνδρῶν, Ἑρμίνιος καὶ Λάρκιος, ἀντέστησαν περὶ τὴν ξυλίνην γέφυραν. ὁ δ’ Ὡράτιος τὸν Κόκλιον ἐπωνύμιον ἔσχεν ἐν πολέμῳ τῶν ὀμμάτων θάτερον ἐκ κοπείς· ὡς δ’ ἔνιοι λέγουσι, διὰ σιμότητα τῆς ῥινὸς ἐνδεδυκυίας ὥστε μηδὲν εἶναι τὸ διορίζον τὰ ὄμματα καὶ τὰς ὀφρῦς συγκεχύσθαι, Κύκλωπα βουλόμενοι καλεῖν αὐτὸν οἱ πολλοὶ τῆς γλώττης ὀλισθαινούσης ἐκράτησεν ὑπὸ πλήθους Κόκλιον καλεῖσθαι. οὗτος ἑστὼς πρὸ τῆς γεφύρας ἠμύνετο τοὺς πολεμίους, ἄχρι οὗ διέκοψαν οἱ σὺν αὐτῷ κατόπιν τὴν γέφυραν. οὕτω δὲ μετὰ τῶν ὅπλων ἀφεὶς ἑαυτὸν εἰς τὸν ποταμόν ἀπενήξατο, καὶ προσέμιξε τῇ πέραν ὄχθῃ δόρατι Τυρρηνικῷ βεβλημένος τὸν γλουτόν. ὁ δὲ Ποπλικόλας τὴν ἀρετὴν θαυμάσας αὐτίκα μὲν εἰσηγήσατο Ῥωμαίους ἅπαντας, ὅσην ἕκαστος ἐν ἡμέρᾳ τροφὴν ἀνήλισκε, δοῦναι συνεισενεγκόντας, ἔπειτα τῆς χώρας ἣν αὐτὸς περιαρόσειεν ἐν ἡμέρᾳ, πρὸς δὲ τούτοις εἰκόνα χαλκῆν ἔστησαν αὐτῷ ἐν τῷ ἱερῷ τοῦ Ἡφαίστου, τὴν γενομένην ἐκ τοῦ τραύματος τῷ ἀνδρὶ χωλότητα μετὰ τιμῆς παρηγοροῦντες.", "st": "Publ. 16.1"}, {"sp": "N", "t": "ἐπικειμένου δὲ Πορσίνα τῇ πόλει καί λιμὸς ἥπτετο τῶν Ῥωμαίων, καί Τυρρηνῶν ἕτερος στρατὸς αὐτὸς καθ’ αὑτὸν εἰς τὴν χώραν ἐνέβαλε. Ποπλικόλας δὲ τὸ τρίτον ὑπατεύων Πορσίνᾳ μὲν ἀτρεμῶν καί φυλάττων τὴν πόλιν ᾤετο δεῖν ἀντέχειν, τοῖς δὲ Τυρρηνοῖς ἐπεξῆλθε καί συμβαλὼν ἐτρέψατο καί πεντακισχιλίους αὐτῶν ἀνεῖλε.", "st": "Publ. 17.1"}, {"sp": "N", "t": "τὸ δὲ περὶ Μούκιον εἴρηται μὲν ὑπὸ πολλῶν καὶ διαφόρως, λεκτέον δὲ ᾗ μάλιστα πιστεύεται καί ἡμῖν. ἦν ἀνὴρ εἰς πᾶσαν ἀρετὴν ἀγαθός, ἐν δὲ τοῖς πολεμικοῖς ἄριστος· ἐπιβουλεύων δὲ τὸν Πορσίναν ἀνελεῖν παρεισῆλθεν εἰς τὸ στρατόπεδον Τυρρηνίδα φορῶν ἐσθῆτα καί φωνῇ χρώμενος ὁμοία περιελθὼν δὲ τὸ βῆμα τοῦ βασιλέως καθεζομένου, καί σαφῶς μὲν αὑτὸν οὐκ εἰδώς, ἐρέσθαι δὲ περὶ αὐτοῦ δεδιώς, ἐν ᾠήθη μάλιστα τῶν συγκαθεζομένων ἐκεῖνον εἶναι σπασάμενος τὸ ξίφος ἀπέκτεινεν. ἐπὶ τούτῳ δὲ συλληφθεὶς ἀνεκρίνετο· καί τινος ἐσχαρίδος πῦρ ἐχούσης μέλλοντι τῷ Πορσίνᾳ θύειν κεκομισμένης, ὑπερσχὼν τὴν δεξιὰν χεῖρα καιομένης τῆς σαρκὸς εἱστήκει πρὸς τὸν Πορσίναν ἀποβλέπων ἰταμῷ καί ἀτρέπτῳ τῷ προσώπῳ, μέχρι οὗ θαυμάσας ἀφῆκεν αὑτὸν καί τὸ ξίφος ἀποδιδοὺς ὤρεξεν ἀπὸ τοῦ βήματος· ὁ δὲ τὴν εὐώνυμον προτείνας ἐδέξατο. καί διὰ τοῦτό φασιν αὐτῷ γενέσθαι τὸν Σκαιόλαν ἐπίκλησιν, ὅπερ ἐστὶ Λαιόν. ἔφη δὲ τὸν φόβον τοῦ Πορσίνα νενικηκὼς ἡττᾶσθαι τῆς ἀρετῆς, καί χάριτι μηνύειν ἃ πρὸς ἀνάγκην οὐκ ἂν ἐξηγόρευσε. τριακόσιοι γὰρ Ῥωμαίων, ἔφη, τὴν αὐτὴν ἐμοὶ γνώμην ἔχοντες ἐν τῷ στρατοπέδῳ σου πλανῶνται καιρὸν ἐπιτηροῦντες· ἐγὼ δὲ κλήρῳ λαχὼν καί προεπιχειρήσας οὐκ ἄχθομαι τῇ τύχῃ, διαμαρτὼν ἀνδρὸς ἀγαθοῦ καί φίλου μᾶλλον ἢ πολεμίου Ῥωμαίοις εἶναι πρέποντος ταῦθ’ ὁ Πορσίνας ἀκούσας ἐπίστευσε καί πρὸς τὰς διαλύσεις ἥδιον ἔσχεν, οὐ τοσοῦτό, μοι δοκεῖ, φόβῳ τῶν τριακοσίων, ὅσον ἀγασθεὶς καί θαυμάσας τὸ φρόνημα, καὶ τὴν ἀρετὴν τῶν Ῥωμαίων.", "st": "Publ. 17.2"}, {"sp": "N", "t": "τοῦτον τὸν ἄνδρα Μούκιον ὁμοῦ τι πάντων καὶ Σκαιόλαν καλούντων Ἀθηνόδωρος ὁ Σάνδωνος ἐν τῷ πρὸς Ὀκταουίαν τὴν Καίσαρος ἀδελφὴν καὶ Ὀψίγονον ὠνομάσθαι φησίν.", "st": "Publ. 17.2b"}, {"sp": "N", "t": "ὁ μέντοι Ποπλικόλας αὐτός, οὐχ οὕτω πολέμιον ὄντα τὸν Πορσίναν βαρὺν ἡγούμενος ὡς ἄξιον πολλοῦ τῇ πόλει φίλον γενέσθαι καὶ σύμμαχον, οὐκ ἔφευγεν ἐπ’ αὐτοῦ δίκῃ κριθῆναι πρὸς Ταρκύνιον, ἀλλ’ ἐθάρρει καὶ προὐκαλεῖτο πολλάκις ὡς ἐξελέγξων κάκιστον ἀνδρῶν καὶ δικαίως ἀφαιρεθέντα τὴν ἀρχήν, ἀποκριναμένου δὲ τὸν Ταρκυνίου τραχύτερον, οὐδένα ποιεῖσθαι δικαστήν, ἥκιστα δὲ Πορσίναν, εἰ σύμμαχος ὢν μεταβάλλεται, δυσχεράνας καὶ καταγνοὺς ὁ Πορσίνας, ἅμα δὲ τὸν παιδὸς Ἄρροντος δεομένου καὶ σπουδάζοντος ὑπὲρ τῶν Ῥωμαίων, κατελύσατο τὸν πόλεμον ἐξισταμένοις ἧς ἀπετέμοντο τῆς Τυρρηνίδος χώρας καὶ τοὺς αἰχμαλώτους ἀποπέμπουσι, κομιζομένοις δὲ τοὺς αὐτομόλους, ἐπὶ τούτοις ὁμήρους ἔδωκαν ἐξ εὐπατριδῶν περιπορφύρους δέκα καὶ παρθένους τοσαύτας, ὧν ἦν καὶ Ποπλικόλα θυγάτηρ Οὐαλλερία.", "st": "Publ. 18.1"}, {"sp": "N", "t": "πραττομένων δὲ τούτων τοῦ τε Πορσίνα πᾶσαν ἤδη τὴν πολεμικὴν ἀνεικότος παρασκευὴν διὰ πίστιν, αἱ παρθένοι τῶν Ῥωμαίων κατῆλθον ἐπὶ λουτρόν ἔνθα δὴ μηνοειδής τις ὄχθη περιβάλλουσα τὸν ποταμὸν ἡσυχίαν μάλιστα καὶ γαλήνην τοῦ κύματος παρεῖχεν. ὡς δ’ οὔτε τινὰ φυλακὴν ἑώρων οὔτε παριόντας ἄλλως ἢ διαπλέοντας, ὁρμὴν ἔσχον ἀπονήξασθαι πρὸς ῥεῦμα πολὺ καὶ δίνας βαθείας. ἔνιοι δέ φασι μίαν αὐτῶν, ὄνομα Κλοιλίαν, ἵππῳ διεξελάσαι τὸν πόρον, ἐγκελευομένην ταῖς ἄλλαις νεούσαις καὶ παραθαρρύνουσαν. ἐπεὶ δὲ σωθεῖσαι πρὸς τὸν Ποπλικόλαν ἧκον, οὐκ ἐθαύμασεν οὐδ’ ἠγάπησεν, ἀλλ’ ἠνιάθη, ὅτι Πορσίνα κακίων ἐν πίστει φανεῖται, καὶ τὸ τόλμημα τῶν παρθένων αἰτίαν ἕξει κακούργημα Ῥωμαίων γεγονέναι. διὸ συλλαβὼν αὐτὰς πάλιν ἀπέστειλε πρὸς τὸν Πορσίναν. ταῦτα δ’ οἱ περὶ τὸν Ταρκύνιον προαισθόμενοι, καὶ καθίσαντες ἐνέδραν τοῖς ἄγουσι τὰς παῖδας, ἐν τῷ περᾶν ἐπέθεντο πλείονες ὄντες. ἐκείνων δὲ ὅμως ἀμυνομένων, ἡ Ποπλικόλα θυγάτηρ Οὐαλλερία διὰ μέσων ὁρμήσασα τῶν μαχομένων ἀπέφυγε, καὶ τρεῖς τινες οἰκέται συνδιεκπεσόντες ἔσῳζον αὐτήν, τῶν δ’ ἄλλων οὐκ ἀκινδύνως ἀναμεμιγμένων τοῖς μαχομένοις, αἰθόμενος Ἄρρων ὁ Πορσίνα υἱὸς ὀξέως προσεβοήθησε, καὶ φυγῆς γενομένης τῶν πολεμίων περιεποίησε τοὺς Ῥωμαίους.", "st": "Publ. 19.1"}, {"sp": "N", "t": "ὡς δὲ τὰς παρθένους κομισθείσας ὁ Πορσίνας εἶδε, τὴν καταρξαμένην τῆς πράξεως καὶ παρακελευσαμένην ταῖς ἄλλαις ἐζήτει. ἀκούσας δὲ τὸ ὄνομα τῆς Κλοιλίας προσέβλεψεν αὐτὴν ἵλεῳ καὶ φαιδρῷ τῷ προσώπῳ, καὶ κελεύσας ἵππον ἀχθῆναι τῶν βασιλικῶν κεκοσμημένον εὐπρεπῶς ἐδωρήσατο. τοῦτο ποιοῦνται μαρτύριον οἱ μόνην τὴν Κλοιλίαν λέγοντες ἵππῳ διεξελάσαι τὸν ποταμόν. οἱ δ’ οὔ φασιν, ἀλλὰ τιμῆσαι τὸ ἀνδρῶδες αὐτῆς τὸν Τυρρηνόν. ἀνάκειται δὲ τὴν ἱερὰν ὁδὸν πορευομένοις εἰς Παλάτιον ἀνδριὰς αὐτῆς ἔφιππος, ὅν τινες οὐ τῆς Κλοιλίας, ἀλλὰ τῆς Οὐαλλερίας εἶναι λέγουσιν.", "st": "Publ. 19.4"}, {"sp": "N", "t": "ὁ δὲ Πορσίνας διαλλαγεὶς τοῖς Ῥωμαίοις ἄλλην τε ἑαυτοῦ πολλὴν μεγαλοφροσύνην ἐπεδείξατο τῇ πόλει, καὶ τὰ ὅπλα τοὺς Τυρρηνοὺς ἀναλαβεῖν κελεύσας, ἄλλο δὲ μηδέν, ἀλλ’ ἐκλείπειν τὸν χάρακα σίτου τε πολλοῦ καὶ χρημάτων γέμοντα παντοδαπῶν, παρέδωκε τοῖς Ῥωμαίοις. διὸ καὶ καθ’ ἡμᾶς ἔτι πωλοῦντες τὰ δημόσια πρῶτα κηρύττουσι τὰ Πορσίνα χρήματα, τιμὴν τῷ ἀνδρὶ τῆς χάριτος ἀίδιον ἐν τῇ μνήμῃ διαφυλάττοντες. εἱστήκει δὲ καὶ χαλκοῦς ἀνδριὰς αὐτοῦ παρὰ τὸ βουλευτήριον, ἁπλοῦς καὶ ἀρχαϊκὸς τῇ ἐργασίᾳ.", "st": "Publ. 19.6"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Σαβίνων ἐμβαλόντων εἰς τὴν χώραν ὕπατος μὲν ἀπεδείχθη Μᾶρκος Οὐαλλέριος, ἀδελφὸς Ποπλικόλα, καὶ Ποστούμιος Τούβερτος. πραττομένων δὲ τῶν μεγίστων γνώμῃ καὶ παρουσίᾳ Ποπλικόλα δυσὶ μάχαις μεγάλαις ὁ Μᾶρκος ἐνίκησεν, ὧν ἐν τῇ δευτέρᾳ μηδένα Ῥωμαίων ἀποβαλὼν τρισχιλίους ἐπὶ μυρίοις τῶν πολεμίων ἀνεῖλε. καὶ γέρας ἔσχεν ἐπὶ τοῖς θριάμβοις οἰκίαν αὐτῷ γενέσθαι δημοσίοις ἀναλώμασιν ἐν Παλατίῳ. τῶν δ’ ἄλλων τότε θυρῶν εἴσω τῆς οἰκίας εἰς τὸ κλεισίον ἀνοιγομένων, ἐκείνης μόνης τῆς οἰκίας ἐποίησαν ἐκτὸς ἀπάγεσθαι τὴν αὔλειον, ὡς δὴ κατὰ τὸ συγχώρημα τῆς τιμῆς ἀεὶ τοῦ δημοσίου προσεπιλαμβάνοι.", "st": "Publ. 20.1"}, {"sp": "N", "t": "τὰς δ’ Ἑλληνικὰς πρότερον οὕτως ἔχειν ἁπάσας λέγουσιν, ἀπὸ τῶν κωμῳδιῶν λαμβάνοντες, ὅτι κόπτουσι καὶ ψοφοῦσι τὰς αὑτῶν θύρας ἔνδοθεν οἱ προϊέναι μέλλοντες, ὅπως αἴσθησις ἔξω γένοιτο τοῖς παρερχομένοις ἢ προεστῶσι καὶ μὴ καταλαμβάνοιντο προϊούσαις ταῖς κλεισιάσιν εἰς τὸν στενωπόν.", "st": "Publ. 20.3"}, {"sp": "N", "t": "τῷ δ’ ἑξῆς ἔτει πάλιν ὑπάτευε Ποπλικόλας τὸ τέταρτον· ἦν δὲ προσδοκία πολέμου Σαβίνων καί Λατίνων συνισταμένων. καί τις ἅμα δεισιδαιμονία τῆς πόλεως ἥψατο· πᾶσαι γὰρ αἱ κυοῦσαι τότε γυναῖκες ἐξέβαλλον ἀνάπηρα, καί τέλος οὐδεμία γένεσις ἔσχεν. ὅθεν ἐκ τῶν Σιβυλλείων ὁ Ποπλικόλας ἱλασάμενος τῷ Ἅιδῃ καί τινας ἀγῶνας πυθοχρήστους ἀναλαβὼν καί ταῖς ἐλπίσι πρὸς τὸ θεῖον ἡδίονα καταστήσας τὴν πόλιν, ἤδη τοῖς ἀπ’ ἀνθρώπων φοβεροῖς προσεῖχε. μεγάλη γὰρ ἐφαίνετο κατασκευὴ τῶν πολεμίων καί σύστασις.", "st": "Publ. 21.1"}, {"sp": "N", "t": "ἦν οὖν Ἄππιος Κλαῦσος ἐν Σαβίνοις, ἀνὴρ χρήμασί τε δυνατὸς καί σώματος ῥώμῃ πρὸς ἀλκὴν ἐπιφανής, ἀρετῆς δὲ δόξῃ μάλιστα καί λόγου δεινότητι πρωτεύων, ὃ δὲ πᾶσι συμβαίνει τοῖς μεγάλοις οὐ διέφυγε παθεῖν, ἀλλ’ ἐφθονεῖτο· καὶ τοῖς φθονοῦσιν αἰτίαν παρέσχε καταπαύων τὸν πόλεμον αὔξειν τὰ Ῥωμαίων, ἐπὶ τυραννίδι καί δουλώσει τῆς πατρίδος. αἰσθόμενος δὲ τοὺς λόγους τούτους βουλομένῳ τῷ πλήθει λεγομένους, καί προσκρούοντα τοῖς πολεμοποιοῖς καί στρατιωτικοῖς ἑαυτόν, ἐφοβεῖτο τὴν κρίσιν, ἑταιρείαν δὲ καί δύναμιν φίλων καί οἰκείων ἔχων ἀμύνουσαν περὶ αὑτὸν ἐστασίαζε. καί τοῦτ’ ἦν τοῦ πολέμου διατριβὴ καί μέλλησις τοῖς Σαβίνοις.", "st": "Publ. 21.2"}, {"sp": "N", "t": "ταῦτ’ οὖν ὁ Ποπλικόλας οὐ μόνον εἰδέναι ποιούμενος ἔργον, ἀλλὰ καί κινεῖν καί συνεξορμᾶν τὴν στάσιν, εἶχεν ἄνδρας ἐπιτηδείους οἳ τῷ Κλαύσῳ διελέγοντο παρ’ αὑτοῦ τοιαῦτα, ὡς ὁ Ποπλικόλας ἄνδρα σε χρηστὸν ὄντα καί δίκαιον οὐδενὶ κακῷ δεῖν οἴεται τοὺς σεαυτοῦ πολίτας ἀμύνεσθαι, καίπερ ἀδικούμενον· εἰ δὲ βούλοιο σῴζων ἑαυτὸν μεταστῆναι καί φυγεῖν τοὺς μισοῦντας, ὑποδέξεταί σε δημοσίᾳ καί ἰδίᾳ τῆς τε σῆς ἀρετῆς ἀξίως καί τῆς Ῥωμαίων λαμπρότητος. ταῦτα πολλάκις ἀνασκοποῦντι τῷ Κλαύσῳ βέλτιστα τῶν ἀναγκαίων ἐφαίνετο, καί τοὺς φίλους συμπαρακαλῶν, ἐκείνων τε πολλοὺς ὁμοίως συναναπειθόντων, πεντακισχιλίους οἴκους ἀναστήσας μετὰ παίδων καί γυναικῶν, ὅπερ ἦν ἐν Σαβίνοις ἀθόρυβον μάλιστα καί βίου πρᾴου καί καθεστῶτος οἰκεῖον, εἰς Ῥώμην ἦγε, προειδότος τοῦ Ποπλικόλα καί δεχομένου φιλοφρόνως καί προθύμως ἐπὶ πᾶσι δικαίοις. τοὺς μὲν γὰρ οἴκους εὐθὺς ἀνέμιξε τῷ πολιτεύματι, καί χώραν ἀπένειμεν ἑκάστῳ δυεῖν πλέθρων περὶ τὸν Ἀνίωνα ποταμόν, τῷ δὲ Κλαύσῳ πλέθρα πέντε καί εἴκοσι γῆς ἔδωκεν, αὑτὸν δὲ τῇ βουλῇ προσέγραψεν, ἀρχὴν πολιτείας λαμβάνοντα ταύτην, ᾗ χρώμενος ἐμφρόνως ἀνέδραμεν εἰς τὸ πρῶτον ἀξίωμα καί δύναμιν ἔσχε μεγάλην, καί γένος οὐδενὸς ἀμαυρότερον ἐν Ῥώμῃ τὸ Κλαυδίων ἀφ’ αὑτοῦ κατέλιπε.", "st": "Publ. 21.4"}, {"sp": "N", "t": "τὰ δὲ Σαβίνων οὕτω διακριθέντα τῷ μετοικισμῷ τῶν ἀνδρῶν, οὐκ εἴασαν οἱ δημαγωγοῦντες ἀτρεμῆσαι καί καταστῆναι, σχετλιάζοντες εἰ Κλαῦσος ἃ παρὼν οὐκ ἔπεισε διαπράξεται φυγὰς γενόμενος καί πολέμιος, μὴ δοῦναι δίκην Ῥωμαίους ὧν ὑβρίζουσιν. ἄραντες οὖν στρατῷ μεγάλῳ περὶ Φιδήνας κατηυλίσαντο, καί τινα λόχον θέμενοι πρὸ τῆς Ῥώμης ἐν χωρίοις συνηρεφέσι καί κοίλοις δισχιλίους ὁπλίτας, ἔμελλον ἅμ’ ἡμέρᾳ φανερῶς ὀλίγοις ἱππεῦσι λείαν ἐλαύνειν. εἴρητο δ’ αὐτοῖς, ὅταν τῇ πόλει προσελάσωσιν, ὑποφεύγειν ἕως ἐμβάλωσιν εἰς τὴν ἐνέδραν τοὺς πολεμίους· ταῦθ’ ὁ Ποπλικόλας αὐθημερὸν πυθόμενος παρ’ αὐτομόλων ταχὺ διηρμόσατο πρὸς πάντα καί διένειμε τὴν δύναμιν. Ποστούμιος μὲν γὰρ Βάλβος ὁ γαμβρὸς αὐτοῦ τρισχιλίοις ὁπλίταις ἑσπέρας ἔτι προελθὼν καί καταλαβὼν τοὺς ἀκρολόφους, ὑφ’ οἷς ἐνήδρευον οἱ Σαβῖνοι, παρεφύλαττεν· ὁ δὲ συνάρχων Λουκρήτιος ἔχων τὸ κουφότατον ἐν τῇ πόλει καί γενναιότατον ἐτάχθη τοῖς ἐλαύνουσι τὴν λείαν ἱππεῦσιν ἐπιχειρεῖν, αὐτὸς δὲ τὴν ἄλλην ἀναλαβὼν στρατιὰν κύκλῳ περιῆλθε τοὺς πολεμίους, καὶ κατὰ τύχην ὁμίχλης βαθείας ἐπιπεσούσης, περὶ ὄρθρον ἅμα Ποστούμιός τε τοὺς ἐνεδρεύοντας ἐμβοήσας ἔβαλεν ἀπὸ τῶν ἄκρων, καί τοῖς προϊππασαμένοις ἐφῆκε τοὺς περὶ αὑτὸν ὁ Λουκρήτιος, καί Ποπλικόλας προσέβαλε τοῖς στρατοπέδοις τῶν πολεμίων. πάντη μὲν οὖν ἐκακοῦτο τὰ Σαβίνων καί διεφθείρετο· τοὺς δ’ ἐνταῦθα μηδ’ ἀμυνομένους, ἀλλὰ φεύγοντας, εὐθὺς ἔκτεινον οἱ Ῥωμαῖοι, τῆς ἐλπίδος αὐτοῖς ὀλεθριωτάτης γενομένης. σῴζεσθαι γὰρ οἰόμενοι τοὺς ἑτέρους οἱ ἕτεροι τῷ μάχεσθαι καί μένειν οὐ προσεῖχον, ἀλλ’ οἱ μὲν ἐκ τῶν ἐρυμάτων πρὸς τοὺς ἐνεδρεύοντας, οἱ δὲ πάλιν ὡς ἐκείνους εἰς τὸ στρατόπεδον θέοντες ἐναντίοι φεύγουσιν ἐνέπιπτον πρὸς οὓς ἔφευγον καί βοηθείας δεομένοις οὓς ἤλπιζον αὐτοῖς βοηθήσειν. τὸ δὲ μὴ πάντας ἀπολέσθαι τοὺς Σαβίνους, ἀλλὰ καί περιγενέσθαι τινάς ἡ Φιδηνατῶν πόλις ἐγγὺς οὖσα παρέσχε, καί μάλιστα τοῖς ἐκ τῶν στρατοπέδων, ὅθ’ ἡλίσκετο, διεκπίπτουσιν. ὅσοι δὲ Φιδηνῶν διήμαρτον διεφθάρησαν ἢ ζῶντες ἀπήχθησαν ὑπὸ τῶν λαβόντων.", "st": "Publ. 22.1"}, {"sp": "N", "t": "τοῦτο τὸ κατόρθωμα Ῥωμαῖοι, καίπερ εἰωθότες ἅπασι τοῖς μεγάλοις ἐπιφημίζειν τὸ δαιμόνιον, ἑνὸς ἔργον ἡγοῦντο τοῦ στρατηγοῦ γεγονέναι. καὶ τῶν μεμαχημένων πρῶτον ἦν ἀκούειν ὅτι χωλοὺς καὶ τυφλοὺς αὐτοῖς καὶ μόνον οὐ καθείρξας τοὺς πολεμίους Ποπλικόλας παρέδωκε χρῆσθαι τοῖς ξίφεσιν. ἐρρώσθη δὲ καὶ χρήμασιν ὁ δῆμος ἐκ τῶν λαφύρων καὶ τῶν αἰχμαλώτων.", "st": "Publ. 23.1"}, {"sp": "N", "t": "ὁ δὲ Ποπλικόλας τόν τε θρίαμβον ἀγαγὼν καὶ τοῖς μετ’ αὐτὸν ἀποδειχθεῖσιν ὑπάτοις παραδοὺς τὴν πόλιν εὐθὺς ἐτελεύτησεν, ὡς ἐφικτόν ἐστιν ἀνθρώποις μάλιστα τοῖς νενομισμένοις καλοῖς καὶ ἀγαθοῖς, τόν ἑαυτοῦ βίον ἐκτελειώσας. ὁ δὲ δῆμος ὥσπερ οὐδὲν εἰς ζῶντα τῶν ἀξίων πεποιηκώς, ἀλλὰ πᾶσαν ὀφείλων χάριν, ἐψηφίσατο δημοσίᾳ ταφῆναι τὸ σῶμα, καὶ τεταρτημόριον ἕκαστον ἐπὶ τιμῇ συνεισενεγκεῖν. αἱ δὲ γυναῖκες, ἰδίᾳ πρὸς αὑτὰς συμφρονήσασαι, διεπένθησαν ἐνιαυτὸν ὅλον ἐπὶ τῷ ἀνδρὶ πένθος ἔντιμον καὶ ζηλωτόν. ἐτάφη δὲ καὶ οὕτως τῶν πολιτῶν ψηφισαμένων ἐντὸς ἄστεος παρὰ τὴν καλουμένην Οὐελίαν, ὥστε καὶ γένει παντὶ τῆς ταφῆς μετεῖναι· νῦν δὲ θάπτεται μὲν οὐδεὶς τῶν ἀπὸ γένους, κομίσαντες δὲ τόν νεκρὸν ἐκεῖ κατατίθενται καὶ δᾷδά τις ἡμμένην λαβὼν ὅσον ὑπήνεγκεν, εἶτα ἀναιρεῖται, μαρτυρόμενος ἔργῳ τὸ ἐξεῖναι, φείδεσθαι δὲ τῆς τιμῆς, καὶ τόν νεκρὸν οὕτως ἀποκομίζουσιν.", "st": "Publ. 23.2"}, {"sp": "HDR", "t": "Σόλωνος καὶ Ποπλικόλα σύγκρισις"}, {"sp": "N", "t": "ἆρ’ οὖν ἴδιόν τι περὶ ταύτην τὴν σύγκρισιν ὑπάρχει καὶ μὴ πάνυ συμβεβηκὸς ἑτέρᾳ τῶν ἀναγεγραμμένων, τὸν ἕτερον γεγονέναι μιμητὴν τοῦ ἑτέρου, τὸν ἕτερον δὲ μάρτυν; ὅρα γάρ ἣν ὁ Σόλων ἐξήνεγκε περὶ εὐδαιμονίας ἀπόφασιν πρὸς Κροῖσον, ὡς Ποπλικόλᾳ μᾶλλον ἢ Τέλλῳ προσήκει· Τέλλου μὲν γὰρ, ὃν εἶπε γεγονέναι μακαριώτατον δι’ εὐποτμίαν καὶ ἀρετὴν καὶ εὐτεκνίαν, οὔτ’ αὐτὸς ἐν τοῖς ποιήμασιν ὡς ἀνδρὸς ἀγαθοῦ λόγον ἔσχεν οὔτε παῖδες οὔτ’ ἀρχή τις εἰς δόξαν ἦλθεν Ποπλικόλας δὲ καὶ ζῶν ἐπρώτευσε δυνάμει καὶ δόξῃ δι’ ἀρετὴν Ῥωμαίων, καὶ τεθνηκότος ἐν τοῖς ἐπιφανεστάτοις γένεσι καὶ στέμμασιν ἔτι καθ’ ἡμᾶς Ποπλικόλαι καὶ Μεσσάλαι καὶ Οὐαλλέριοι δι’ ἐτῶν ἑξακοσίων τῆς εὐγενείας τὴν δόξαν ἀναφέρουσι. καὶ Τέλλος μὲν ὑπὸ τῶν πολεμίων ὡς ἀνὴρ ἀγαθὸς ἐν τάξει μένων καὶ μαχόμενος κατέστρεψε· Ποπλικόλας δὲ τοὺς μὲν πολεμίους κτείνας, ὃ τοῦ πεσεῖν εὐτυχέστερόν ἐστι, τὴν δὲ πατρίδα νικῶσαν ἐπιδὼν δι’ αὐτόν ἄρχοντα καὶ στρατηγοῦντα, τιμηθεὶς δὲ καὶ θριαμβεύσας ἔτυχε τῆς ζηλουμένης ὑπὸ Σόλωνος καὶ μακαριζομένης τελευτῆς. ἔτι τοίνυν οἷς πρὸς Μίμνερμον ἀντειπὼν περὶ χρόνου ζωῆς ἐπιπεφώνηκε,", "st": "Comp. Sol.–Publ. 1.1"}, {"sp": "N", "t": "μηδέ μοι ἄκλαυστος θάνατος μόλοι, ἀλλὰ φίλοισι<br>ποιήσαιμι θανὼν ἄλγεα καὶ στοναχάς", "st": "Comp. Sol.–Publ. 1.1b"}, {"sp": "N", "t": "ποιεῖ, τελευτήσας γὰρ οὐ φίλοις οὐδ’ οἰκείοις μόνον, ἀλλὰ τῇ πόλει πάσῃ, μυριάσι πολλαῖς, δάκρυα καὶ πόθον καὶ κατήφειαν ἐφ’ αὑτῷ παρέσχεν αἱ γάρ Ῥωμαίων γυναῖκες ἐπένθησαν αὐτόν ὥσπερ υ ἱὸν ἢ ἀδελφὸν ἢ πατέρα κοινὸν ἀποβαλοῦσαι. χρήματα δ’ ἱμείρω μὲν ἔχειν, φησὶν ὁ Σόλων, ἀδίκως δὲ πεπᾶσθαι οὐκ ἐθέλω, ὡς δίκης ἐπιούσης Ποπλικόλᾳ δ’ ὑπῆρχεν οὐ μόνον μὴ κακῶς πλουτεῖν, ἀλλὰ καὶ καλῶς ἀναλίσκειν εὖ ποιοῦντι τοὺς δεομένους, ὥστ’ εἰ σοφώτατος ἁπάντων ὁ Σόλων, εὐδαιμονέστατος ὁ Ποπλικόλας. ἃ γὰρ εὔξατο τῶν ἀγαθῶν ἐκεῖνος ὡς μέγιστα καὶ κάλλιστα, ταῦτα καὶ κτήσασθαι Ποπλικόλᾳ καὶ φυλάξαι χρωμένῳ μέχρι τέλους ὑπῆρξεν.", "st": "Comp. Sol.–Publ. 1.5"}, {"sp": "N", "t": "οὕτω μὲν ὁ Σόλων κεκόσμηκε τὸν Ποπλικόλαν, τὸν Σόλωνα δ’ αὖ πάλιν ἐκεῖνος ἐν τῇ πολιτείᾳ παραδειγμάτων κάλλιστον ἀνδρὶ κοσμοῦντι δημοκρατίαν θέμενος· τῆς μὲν γὰρ ἀρχῆς τὸν ὄγκον ἀφελών εὐμενῆ πᾶσι καὶ ἄλυπον κατέστησε, νόμοις δὲ πολλοῖς ἐχρήσατο τῶν ἐκείνου, καὶ γὰρ ἀρχόντων καταστάσεως κυρίους ἐποίησε τοὺς πολλούς, καὶ τοῖς φεύγουσι δίκην ἐπικαλεῖσθαι τὸν δῆμον, ὥσπερ ὁ Σόλων τοὺς δικαστάς, ἔδωκε. καὶ βουλὴν μὲν ἑτέραν οὐκ ἐποίησεν, ὥσπερ ὁ Σόλων, τὴν δ’ οὖσαν ηὔξησεν ἀριθμῷ μικροῦ διπλασιάσας. ἥ τε τᾶν ταμιῶν ἐπὶ τοῖς χρήμασι κατάστασις ἐκεῖθεν ἦλθεν, ὅπως ὁ ἄρχων μήτ’ εἰ χρηστός ἐστιν ἀσχολίαν ἔχῃ πρὸς τὰ μείζω, μήτ’ εἰ φαῦλος ἀφορμὰς τοῦ ἀδικεῖν μᾶλλον, καὶ τῶν πράξεων καὶ τῶν χρημάτων κύριος γενόμενος. τὸ δὲ μισοτύραννον ἐν τῷ Ποπλικόλᾳ σφοδρότερον. εἰ γάρ τις ἐπιχειροίη τυραννεῖν, ὁ μὲν ἁλόντι τὴν δίκην ἐπιτίθησιν, ὁ δὲ καὶ πρὸ τῆς κρίσεως ἀνελεῖν δίδωσι. σεμνυνομένου δὲ τοῦ Σόλωνος ὀρθῶς καὶ δικαίως ὅτι καὶ τῶν πραγμάτων αὐτῷ διδόντων τυραννεῖν καὶ τῶν πολιτῶν οὐκ ἀκουσίως δεχομένων ἀπεῖπεν, οὐχ ἧττον ὑπάρχει καλὸν τῷ Ποπλικόλᾳ τὸ λαβόντα τυραννικὴν ἀρχὴν ποιῆσαι δημοτικωτέραν καὶ μηδ’ οἷς ἐξῆν ἔχοντα χρήσασθαι. καὶ τοῦτο δ’ ἔοικε συνιδεῖν πρότερος ὁ Σόλων, ὅτι δῆμος", "st": "Comp. Sol.–Publ. 2.1"}, {"sp": "N", "t": "ὧδ’ ἂν ἄριστα σὺν ἡγεμόνεσσιν ἕποιτο,<br>μήτε λίην ἀνεθεὶς μήτε πιεζόμενος.", "st": "Comp. Sol.–Publ. 2.1b"}, {"sp": "N", "t": "ἴδιον δὲ τοῦ Σόλωνος ἡ τῶν χρεῶν ἄνεσις, ᾗ μάλιστα τὴν ἐλευθερίαν ἐβεβαίωσε τοῖς πολίταις. οὐδὲν γὰρ ὄφελος νόμων ἰσότητα παρεχόντων, ἣν ἀφαιρεῖται τὰ χρέα τοὺς πένητας· ἀλλ’ ὅποι· μάλιστα χρῆσθαι τῇ ἐλευθερίᾳ δοκοῦσι, δουλεύουσι μάλιστα τοῖς πλουσίοις, ἐν τῷ δικάζειν καὶ ἄρχειν καὶ λέγειν ἐπιταττόμενοι καὶ ὑπηρετοῦντες. τούτου δὲ μεῖζον, ὅτι πάσῃ χρεῶν ἀποκοπῇ στάσεως ἑπομένης, ἐκείνῃ μόνῃ, καθάπερ φαρμάκῳ παραβόλῳ μέν, ἰσχυρῷ δὲ χρησάμενος εὐκαίρως, καὶ τὴν οὖσαν στάσιν ἔλυσε, τῇ περὶ αὐτὸν ἀρετῇ καὶ δόξῃ τῆς τοῦ πράγματος ἀδοξίας καὶ διαβολῆς περιγενόμενος.", "st": "Comp. Sol.–Publ. 3.1"}, {"sp": "N", "t": "τῆς δ’ ὅλης πολιτείας τῇ μὲν ἀρχῇ λαμπρότερος ὁ Σόλων· ἡγήσατο γὰρ καὶ οὐκ ἠκολούθησε, καὶ καθ’ αὑτόν, οὐ μεθ’ ἑτέρων, ἔπραξε τὰ πλεῖστα καὶ μέγιστα τῶν κοινῶν τῷ τέλει δὲ ἅτερος εὐτυχὴς καὶ ζηλωτός. τὴν μὲν γὰρ Σόλωνος πολιτείαν αὐτὸς ἐπεῖδε Σόλων καταλυθεῖσαν, ἡ δὲ Ποπλικόλα μέχρι τῶν ἐμφυλίων πολέμων διεφύλαξεν ἐν κόσμῳ τὴν πόλιν ὁ μὲν γὰρ ἅμα τῷ θέσθαι τοὺς νόμους ἀπολιπὼν ἐν ξύλοις καὶ γράμμασιν ἐρήμους τοῦ βοηθοῦντος ᾤχετ’ ἀπιὼν ἐκ τῶν Ἀθηνῶν, ὁ δὲ μένων καὶ ἄρχων καὶ πολιτευόμενος ἵδρυσε καὶ κατέστησεν εἰς ἀσφαλὲς τὴν πολιτείαν. ἔτι δ’ ἐκείνῳ μὲν οὐδὲ μέλλοντα κωλῦσαι προαισθομένῳ Πεισίστρατον ὑπῆρξεν, ἀλλ’ ἡττήθη συνισταμένης τῆς τυραννίδος· οὗτος δὲ βασιλείαν ἰσχύουσαν ἐκ πολλῶν χρόνων ἤδη καὶ κρατοῦσαν ἐξέβαλε καὶ κατέλυσεν, ἀρετὴν μὲν ἴσην καὶ προαίρεσιν ὁμοίαν παρασχόμενος, τύχῃ δὲ καὶ δυνάμει τελεσιουργῷ πρὸς τὴν ἀρετὴν χρησάμενος.", "st": "Comp. Sol.–Publ. 3.3"}, {"sp": "N", "t": "τῶν μέντοι πολεμικῶν Σόλωνι μὲν οὐδὲ τὰ πρὸς Μεγαρεῖς Δαΐμαχος ὁ Πλαταιεὺς μεμαρτύρηκεν, ὥσπερ ἡμεῖς διεληλύθαμεν· Ποπλικόλας δὲ τοὺς μεγίστους ἀγῶνας αὐτὸς καὶ μαχόμενος καὶ στρατηγῶν κατώρθωσε, καὶ μὴν ἔτι πρὸς τὰς πολιτικὰς πράξεις ὁ μὲν ἐν παιδιᾶς τινι τρόπῳ καὶ προσποίημα μανίας ἀναλαβὼν, ὑπὲρ Σαλαμῖνος ἐρῶν προῆλθεν· ὁ δ’ αὐτόθεν ἀναρρίψας τὸν περὶ τῶν μεγίστων κίνδυνον ἐπανέστη τε Ταρκυνίοις καὶ τὴν προδοσίαν ἐφώρασε· καὶ τοῦ κολασθῆναι καὶ μὴ διαφυγεῖν τοὺς πονηροὺς αἰτιώτατος γενόμενος οὐ τὰ σώματα μόνον τῶν τυράννων ἐξέβαλε τῆς πόλεως, ἀλλὰ καὶ τὰς ἐλπίδας ἐξέκοψεν. οὕτω δὲ τοῖς δεχομένοις πράγμασιν ἀγῶνα καὶ θυμὸν καὶ ἀντίταξιν ἐρρωμένως καὶ ἀτενῶς ἀπαντήσας, ἔτι βέλτιον ἐχρήσατο τοῖς ὁμιλίας ἀπολέμου καὶ πειθοῦς ὑπεικούσης δεομένοις, Πορσίναν ἄμαχον ἄνδρα καὶ φοβερὸν ἐμμελῶς προσαγαγόμενος καὶ μεταστήσας εἰς φιλίαν.", "st": "Comp. Sol.–Publ. 4.1"}, {"sp": "N", "t": "καίτοι φήσει τις ἐνταῦθα τὸν μὲν Σόλωνα προεμένοις ἀναλαβεῖν Ἀθηναίοις Σαλαμῖνα, τὸν δὲ Ποπλικόλαν ἧς ἐκέκτηντο Ῥωμαῖοι χώρας ἀποστῆναι. δεῖ δὲ πρὸς τοὺς ὑποκειμένους καιροὺς τὰς πράξεις θεωρεῖν. ποικίλος γὰρ ὢν ὁ πολιτικὸς ᾧ τρόπῳ τῶν ὄντων ἕκαστον εὔληπτόν ἐστι μεταχειρίσεται, καὶ μέρους ἀφέσει πολλάκις ἔσωσε τὸ πᾶν καὶ μικρῶν ἀποστὰς μειζόνων ἔτυχεν, ὥσπερ ἐκεῖνος ὁ ἀνὴρ τότε τῆς μὲν ἀλλοτρίας χώρας ἀποστὰς ἔσωσε τὴν ἑαυτοῦ βεβαίως ἅπασαν, οἷς δ’ ἦν μέγα τὴν πόλιν διαφυλάξαι προσεκτήσατο τὸ τῶν πολιορκούντων στρατόπεδον, ἐπιτρέψας δὲ τῷ πολεμίῳ δικαστῇ γενέσθαι, καὶ περιγενόμενος τῇ δίκῃ, προσέλαβεν ὅσα δόντας ἀγαπητὸν ἦν νικῆσαι· καὶ γὰρ τὸν πόλεμον διέλυσε καὶ τὴν παρασκευὴν τοῦ πολέμου κατέλιπεν αὐτοῖς διὰ πίστιν ἀρετῆς καὶ καλοκαγαθίας, ἣν ὁ ἄρχων ὑπὲρ ἁπάντων ἐνεποίησεν αὐτῷ.", "st": "Comp. Sol.–Publ. 4.3"}, {"sp": "HDR", "t": "Θεμιστοκλῆς"}, {"sp": "N", "t": "Θεμιστοκλεῖ δὲ τὰ μὲν ἐκ γένους ἀμαυρότερα πρὸς δόξαν ὑπῆρχε· πατρὸς γὰρ ἦν Νεοκλέους οὐ τῶν ἄγαν ἐπιφανῶν Ἀθήνησι, Φρεαρρίου τῶν δήμων ἐκ τῆς Λεοντίδος φυλῆς, νόθος δὲ πρὸς μητρός, ὡς λέγουσιν·", "st": "Them. 1.1"}, {"sp": "N", "t": "Ἀβρότονον Θρήϊσσα γυνὴ γένος· ἀλλὰ τεκέσθαι<br>τὸν μέγαν Ἕλλησίν φημι Θεμιστοκλέα.", "st": "Them. 1.1b"}, {"sp": "N", "t": "Φανίας μέντοι τὴν μητέρα τοῦ Θεμιστοκλέους οὐ Θρᾷτταν, ἀλλὰ Καρίνην, οὐδ’ Ἀβρότονον ὄνομα, ἀλλ’ Εὐτέρπην ἀναγράφει. Νεάνθης δὲ καὶ πόλιν αὐτῇ τῆς Καρίας Ἀλικαρνασσὸν προστίθησι.", "st": "Them. 1.2"}, {"sp": "N", "t": "διὸ καὶ τῶν νόθων εἰς Κυνόσαργες συντελούντων (τοῦτο δ’ ἐστὶν ἔξω πυλῶν γυμνάσιον Ἡρακλέους, ἐπεὶ κἀκεῖνος οὐκ ἦν γνήσιος ἐν θεοῖς, ἀλλ’ ἐνείχετο νοθείᾳ διὰ τὴν μητέρα θνητὴν οὖσαν) ἔπειθέ τινας ὁ Θεμιστοκλῆς τῶν εὖ γεγονότων νεανίσκων καταβαίνοντας εἰς τὸ Κυνόσαργες ἀλείφεσθαι μετ’ αὐτοῦ. καὶ τούτου γενομένου δοκεῖ πανούργως τὸν τῶν νόθων καὶ γνησίων διορισμὸν ἀνελεῖν.", "st": "Them. 1.2b"}, {"sp": "N", "t": "ὅτι μέντοι τοῦ Λυκομιδῶν γένους μετεῖχε δῆλός ἐστι· τὸ γὰρ Φλυῆσι τελεστήριον, ὅπερ ἦν Λυκομιδῶν κοινόν, ἐμπρησθὲν ὑπὸ τῶν βαρβάρων αὐτὸς ἐπεσκεύασε καὶ γραφαῖς ἐκόσμησεν, ὡς Σιμωνίδης ἱστόρηκεν.", "st": "Them. 1.3"}, {"sp": "N", "t": "ἔτι δὲ παῖς ὢν ὁμολογεῖται φορᾶς μεστὸς εἶναι, καὶ τῇ μὲν φύσει συνετός, τῇ δὲ προαιρέσει μεγαλοπράγμων καὶ πολιτικός. ἐν γὰρ ταῖς ἀνέσεσι καὶ σχολαῖς ἀπὸ τῶν μαθημάτων γινόμενος οὐκ ἔπαιζεν οὐδ’ ἐρρᾳθύμει, καθάπερ οἱ λοιποὶ παῖδες, ἀλλ’ εὑρίσκετο λόγους τινὰς μελετῶν καὶ συνταττόμενος πρὸς ἑαυτόν. ἦσαν δ’ οἱ λόγοι κατηγορία τινὸς ἢ συνηγορία τῶν παίδων. ὅθεν εἰώθει λέγειν πρὸς αὐτὸν ὁ διδάσκαλος ὡς οὐδὲν ἔσῃ, παῖ, σὺ μικρόν, ἀλλὰ μέγα πάντως ἀγαθὸν ἢ κακόν. ἐπεὶ καὶ τῶν παιδεύσεων τὰς μὲν ἠθοποιοὺς ἢ πρὸς ἡδονήν τινα καὶ χάριν ἐλευθέριον σπουδαζομένας ὀκνηρῶς καὶ ἀπροθύμως ἐξεμάνθανε, τῶν δὲ εἰς σύνεσιν ἢ πρᾶξιν λεγομένων δῆλος ἦν ὑπερορῶν παρ’ ἡλικίαν, ὡς τῇ φύσει πιστεύων.", "st": "Them. 2.1"}, {"sp": "N", "t": "ὅθεν ὕστερον ἐν ταῖς ἐλευθερίοις καὶ ἀστείαις λεγομέναις διατριβαῖς ὑπὸ τῶν πεπαιδεῦσθαι δοκούντων χλευαζόμενος ἠναγκάζετο φορτικώτερον ἀμύνεσθαι, λέγων, ὅτι λύραν μὲν ἁρμόσασθαι καὶ μεταχειρίσασθαι ψαλτήριον οὐκ ἐπίσταται, πόλιν δὲ μικρὰν καὶ ἄδοξον παραλαβὼν ἔνδοξον καὶ μεγάλην ἀπεργάσασθαι. καίτοι Στησίμβροτος Ἀναξαγόρου τε διακοῦσαι τὸν Θεμιστοκλέα φησὶ καὶ περὶ Μέλισσον σπουδάσαι τὸν φυσικόν, οὐκ εὖ τῶν χρόνων ἁπτόμενος· Περικλεῖ γάρ, ὃς πολὺ νεώτερος ἦν Θεμιστοκλέους, Μέλισσος μὲν ἀντεστρατήγει πολιορκοῦντι Σαμίους, Ἀναξαγόρας δὲ συνδιέτριβε.", "st": "Them. 2.3"}, {"sp": "N", "t": "μᾶλλον οὖν ἄν τις προσέχοι τοῖς Μνησιφίλου τὸν Θεμιστοκλέα τοῦ Φρεαρρίου ζηλωτὴν γενέσθαι λέγουσιν, οὔτε ῥήτορος ὄντος οὔτε τῶν φυσικῶν κληθέντων φιλοσόφων, ἀλλὰ τὴν τότε καλουμένην σοφίαν, οὖσαν δὲ δεινότητα πολιτικὴν καὶ δραστήριον σύνεσιν, ἐπιτήδευμα πεποιημένου καὶ διασώζοντος ὥσπερ αἵρεσιν ἐκ διαδοχῆς ἀπὸ Σόλωνος· ἣν οἱ μετὰ ταῦτα δικανικαῖς μίξαντες τέχναις καὶ μεταγαγόντες ἀπὸ τῶν πράξεων τὴν ἄσκησιν ἐπὶ τοὺς λόγους, σοφισταὶ προσηγορεύθησαν. τούτῳ μὲν οὖν ἤδη πολιτευόμενος ἐπλησίαζεν.", "st": "Them. 2.4"}, {"sp": "N", "t": "ἐν δὲ ταῖς πρώταις τῆς νεότητος ὁρμαῖς ἀνώμαλος ἦν καὶ ἀστάθμητος, ἅτε τῇ φύσει καθ’ αὑτὴν χρώμενος ἄνευ λόγου καὶ παιδείας ἐπ’ ἀμφότερα μεγάλας ποιουμένῃ μεταβολὰς τῶν ἐπιτηδευμάτων καὶ πολλάκις ἐξισταμένῃ πρὸς τὸ χεῖρον, ὡς ὕστερον αὐτὸς ὡμολόγει, καὶ τοὺς τραχυτάτους πώλους ἀρίστους ἵππους γίνεσθαι φάσκων, ὅταν ἧς προσήκει τύχωσι παιδείας καὶ καταρτύσεως. ἃ δὲ τούτων ἐξαρτῶσιν ἔνιοι διηγήματα πλάττοντες, ἀποκήρυξιν μὲν ὑπὸ τοῦ πατρὸς αὐτοῦ, θάνατον δὲ τῆς μητρὸς ἑκούσιον ἐπὶ τῇ τοῦ παιδὸς ἀτιμίᾳ περιλύπου γενομένης, δοκεῖ κατεψεῦσθαι· καὶ τοὐναντίον εἰσὶν οἱ λέγοντες, ὅτι τοῦ τὰ κοινὰ πράττειν ἀποτρέπων αὐτὸν ὁ πατὴρ ἐπεδείκνυε πρὸς τῇ θαλάττῃ τὰς παλαιὰς τριήρεις ἐρριμμένας καὶ παρορωμένας, ὡς δὴ καὶ πρὸς τοὺς δημαγωγούς, ὅταν ἄχρηστοι φαίνωνται, τῶν πολλῶν ὁμοίως ἐχόντων.", "st": "Them. 2.5"}, {"sp": "N", "t": "ταχὺ μέντοι καὶ νεανικῶς ἔοικεν ἅψασθαι τοῦ Θεμιστοκλέους τὰ πολιτικὰ πράγματα καὶ σφόδρα ἡ πρὸς δόξαν ὁρμὴ κρατῆσαι. δι’ ἣν εὐθὺς ἐξ ἀρχῆς τοῦ πρωτεύειν ἐφιέμενος ἰταμῶς ὑφίστατο τὰς πρὸς τοὺς δυναμένους ἐν τῇ πόλει καὶ πρωτεύοντας ἀπεχθείας, μάλιστα δὲ Ἀριστείδην τὸν Λυσιμάχου, τὴν ἐναντίαν ἀεὶ πορευόμενον αὐτῷ. καίτοι δοκεῖ παντάπασιν ἡ πρὸς τοῦτον ἔχθρα μειρακιώδη λαβεῖν ἀρχήν· ἠράσθησαν γὰρ ἀμφότεροι τοῦ καλοῦ Στησίλεω, Κείου τὸ γένος ὄντος, ὡς Ἀρίστων ὁ φιλόσοφος ἱστόρηκεν. ἐκ δὲ τούτου διετέλουν καὶ περὶ τὰ δημόσια στασιάζοντες. οὐ μὴν ἀλλ’ ἡ τῶν βίων καὶ τῶν τρόπων ἀνομοιότης ἔοικεν αὐξῆσαι τὴν διαφοράν. πρᾷος γὰρ ὢν φύσει καὶ καλοκαγαθικὸς τὸν τρόπον ὁ Ἀριστείδης, καὶ πολιτευόμενος οὐ πρὸς χάριν οὐδὲ πρὸς δόξαν, ἀλλ’ ἀπὸ τοῦ βελτίστου μετὰ ἀσφαλείας καὶ δικαιοσύνης, ἠναγκάζετο τῷ Θεμιστοκλεῖ τὸν δῆμον ἐπὶ πολλὰ κινοῦντι καὶ μεγάλας ἐπιφέροντι καινοτομίας ἐναντιοῦσθαι πολλάκις, ἐνιστάμενος αὐτοῦ πρὸς τὴν αὔξησιν.", "st": "Them. 3.1"}, {"sp": "N", "t": "λέγεται γὰρ οὕτω παράφορος πρὸς δόξαν εἶναι καὶ πράξεων μεγάλων ὑπὸ φιλοτιμίας ἐραστής, ὥστε νέος ὢν ἔτι τῆς ἐν Μαραθῶνι μάχης πρὸς τοὺς βαρβάρους γενομένης καὶ τῆς Μιλτιάδου στρατηγίας διαβοηθείσης σύννους ὁρᾶσθαι τὰ πολλὰ πρὸς ἑαυτῷ καὶ τὰς νύκτας ἀγρυπνεῖν καὶ τοὺς πότους παραιτεῖσθαι τοὺς συνήθεις, καὶ λέγειν πρὸς τοὺς ἐρωτῶντας καὶ θαυμάζοντας τὴν περὶ τὸν βίον μεταβολήν, ὡς καθεύδειν αὐτὸν οὐκ ἐῴη τὸ τοῦ Μιλτιάδου τρόπαιον. οἱ μὲν γὰρ ἄλλοι πέρας ᾤοντο τοῦ πολέμου τὴν ἐν Μαραθῶνι τῶν βαρβάρων ἧτταν εἶναι, Θεμιστοκλῆς δὲ ἀρχὴν μειζόνων ἀγώνων, ἐφ’ οὓς ἑαυτὸν ὑπὲρ τῆς ὅλης Ἑλλάδος ἤλειφε καὶ τὴν πόλιν ἤσκει πόρρωθεν ἔτι προσδοκῶν τὸ μέλλον.", "st": "Them. 3.3"}, {"sp": "N", "t": "καὶ πρῶτον μὲν τὴν Λαυρεωτικὴν πρόσοδον ἀπὸ τῶν ἀργυρείων μετάλλων ἔθος ἐχόντων Ἀθηναίων διανέμεσθαι, μόνος εἰπεῖν ἐτόλμησε παρελθὼν εἰς τὸν δῆμον, ὡς χρὴ τὴν διανομὴν ἐάσαντας ἐκ τῶν χρημάτων τούτων κατασκευάσασθαι τριήρεις ἐπὶ τὸν πρὸς Αἰγινήτας πόλεμον. ἤκμαζε γὰρ οὗτος ἐν τῇ Ἑλλάδι μάλιστα καὶ κατεῖχον οἱ νησιῶται πλήθει νεῶν τὴν θάλασσαν. ᾗ καὶ ῥᾷον Θεμιστοκλῆς συνέπεισεν, οὐ Δαρεῖον οὐδὲ Πέρσας μακρὰν γὰρ ἦσαν οὗτοι καὶ δέος οὐ πάνυ βέβαιον ὡς ἀφιξόμενοι παρεῖχον ἐπισείων, ἀλλὰ τῇ πρὸς Αἰγινήτας ὀργῇ καὶ φιλονεικίᾳ τῶν πολιτῶν ἀποχρησάμενος εὐκαίρως ἐπὶ τὴν παρασκευήν. ἑκατὸν γὰρ ἀπὸ τῶν χρημάτων ἐκείνων ἐποιήθησαν τριήρεις, αἷς καὶ πρὸς Ξέρξην ἐναυμάχησαν.", "st": "Them. 4.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου κατὰ μικρὸν ὑπάγων καὶ καταβιβάζων τὴν πόλιν πρὸς τὴν θάλασσαν, ὡς τὰ πεζὰ μὲν οὐδὲ τοῖς ὁμόροις ἀξιομάχους ὄντας, τῇ δ’ ἀπὸ τῶν νεῶν ἀλκῇ καὶ τοὺς βαρβάρους ἀμύνασθαι καὶ τῆς Ἑλλάδος ἄρχειν δυναμένους, ἀντὶ μονίμων ὁπλιτῶν, ὥς φησιν ὁ Πλάτων, ναυβάτας καὶ θαλαττίους ἐποίησε, καὶ διαβολὴν καθ’ αὑτοῦ παρέσχεν, ὡς ἄρα Θεμιστοκλῆς τὸ δόρυ καὶ τὴν ἀσπίδα τῶν πολιτῶν παρελόμενος εἰς ὑπηρέσιον καὶ κώπην συνέστειλε τὸν Ἀθηναίων δῆμον. ἔπραξε δὲ ταῦτα Μιλτιάδου κρατήσας ἀντιλέγοντος, ὡς ἱστορεῖ Στησίμβροτος.", "st": "Them. 4.3"}, {"sp": "N", "t": "εἰ μὲν δὴ τὴν ἀκρίβειαν καὶ τὸ καθαρὸν τοῦ πολιτεύματος ἔβλαψεν ἢ μὴ ταῦτα πράξας, ἔστω φιλοσοφώτερον ἐπισκοπεῖν· ὅτι δὲ ἡ τότε σωτηρία τοῖς Ἕλλησιν ἐκ τῆς θαλάσσης ὑπῆρξε καὶ τὴν Ἀθηναίων πόλιν αὖθις ἀνέστησαν αἱ τριήρεις ἐκεῖναι, τά τ’ ἄλλα καὶ Ξέρξης αὐτὸς ἐμαρτύρησε. τῆς γὰρ πεζικῆς δυνάμεως ἀθραύστου διαμενούσης ἔφυγε μετὰ τὴν τῶν νεῶν ἧτταν, ὡς οὐκ ὢν ἀξιόμαχος, καὶ Μαρδόνιον ἐμποδὼν εἶναι τοῖς Ἕλλησι τῆς διώξεως μᾶλλον ἢ δουλωσόμενον αὐτούς, ὡς ἐμοὶ δοκεῖ, κατέλιπεν.", "st": "Them. 4.4"}, {"sp": "N", "t": "σύντονον δὲ αὐτὸν γεγονέναι χρηματιστὴν οἱ μέν τινές φασι δι’ ἐλευθεριότητα· καὶ γὰρ φιλοθύτην ὄντα καὶ λαμπρὸν ἐν ταῖς περὶ τοὺς ξένους δαπάναις ἀφθόνου δεῖσθαι χορηγίας· οἱ δὲ τοὐναντίον γλισχρότητα πολλὴν καὶ μικρολογίαν κατηγοροῦσιν, ὡς καὶ τὰ πεμπόμενα τῶν ἐδωδίμων πωλοῦντος. ἐπεὶ δὲ Φιλίδης ὁ ἱπποτρόφος αἰτηθεὶς ὑπ’ αὐτοῦ πῶλον οὐκ ἔδωκεν, ἠπείλησε τὴν οἰκίαν αὐτοῦ ταχὺ ποιήσειν δούρειον ἵππον, αἰνιξάμενος ἐγκλήματα συγγενικὰ καὶ δίκας τῷ ἀνθρώπῳ πρὸς οἰκείους τινὰς ταράξειν.", "st": "Them. 5.1"}, {"sp": "N", "t": "τῇ δὲ φιλοτιμίᾳ πάντας ὑπερέβαλεν, ὥστ’ ἔτι μὲν νέος ὢν καὶ ἀφανὴς Ἐπικλέα τὸν ἐξ Ἑρμιόνης κιθαριστὴν σπουδαζόμενον ὑπὸ τῶν Ἀθηναίων ἐκλιπαρῆσαι μελετᾶν παρ’ αὐτῷ, φιλοτιμούμενος πολλοὺς τὴν οἰκίαν ζητεῖν καὶ φοιτᾶν πρὸς αὐτόν. εἰς δ’ Ὀλυμπίαν ἐλθὼν καὶ διαμιλλώμενος τῷ Κίμωνι περὶ δεῖπνα καὶ σκηνὰς καὶ τὴν ἄλλην λαμπρότητα καὶ παρασκευήν, οὐκ ἤρεσκε τοῖς Ἕλλησιν. ἐκείνῳ μὲν γὰρ ὄντι νέῳ καὶ ἀπ’ οἰκίας μεγάλης ᾤοντο δεῖν τὰ τοιαῦτα συγχωρεῖν· ὁ δὲ μήπω γνώριμος γεγονώς, ἀλλὰ δοκῶν ἐξ οὐχ ὑπαρχόντων καὶ παρ’ ἀξίαν ἐπαίρεσθαι προσωφλίσκανεν ἀλαζονείαν. ἐνίκησε δὲ καὶ χορηγῶν τραγῳδοῖς, μεγάλην ἤδη τότε σπουδὴν καὶ φιλοτιμίαν τοῦ ἀγῶνος ἔχοντος, καὶ πίνακα τῆς νίκης ἀνέθηκε τοιαύτην ἐπιγραφὴν ἔχοντα· Θεμιστοκλῆς Φρεάρριος ἐχορήγει, Φρύνιχος ἐδίδασκεν, Ἀδείμαντος ἦρχεν.", "st": "Them. 5.3"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τοῖς πολλοῖς ἐνήρμοττε, τοῦτο μὲν ἑκάστου τῶν πολιτῶν τοὔνομα λέγων ἀπὸ στόματος, τοῦτο δὲ κριτὴν ἀσφαλῆ περὶ τὰ συμβόλαια παρέχων ἑαυτόν, ὥστε που καὶ πρὸς Σιμωνίδην τὸν Κεῖον εἰπεῖν, αἰτούμενόν τι τῶν οὐ μετρίων παρ’ αὐτοῦ στρατηγοῦντος, ὡς οὔτ’ ἐκεῖνος ἂν γένοιτο ποιητὴς ἀγαθὸς ᾄδων παρὰ μέλος οὔτ’ αὐτὸς ἀστεῖος ἄρχων παρὰ νόμον χαριζόμενος. πάλιν δέ ποτε τὸν Σιμωνίδην ἐπισκώπτων ἔλεγε νοῦν οὐκ ἔχειν, Κορινθίους μὲν λοιδοροῦντα μεγάλην οἰκοῦντας πόλιν, αὑτοῦ δὲ ποιούμενον εἰκόνας οὕτως ὄντος αἰσχροῦ τὴν ὄψιν. αὐξόμενος δὲ καὶ τοῖς πολλοῖς ἀρέσκων τέλος κατεστασίασε καὶ μετέστησεν ἐξοστρακισθέντα τὸν Ἀριστείδην.", "st": "Them. 5.5"}, {"sp": "N", "t": "ἤδη δὲ τοῦ Μήδου καταβαίνοντος ἐπὶ τὴν Ἑλλάδα καὶ τῶν Ἀθηναίων βουλευομένων περὶ στρατηγοῦ, τοὺς μὲν ἄλλους ἑκόντας ἐκστῆναι τῆς στρατηγίας λέγουσιν ἐκπεπληγμένους τὸν κίνδυνον, Ἐπικύδην δὲ τὸν Εὐφημίδου, δημαγωγὸν ὄντα δεινὸν μὲν εἰπεῖν, μαλακὸν δὲ τὴν ψυχὴν καὶ χρημάτων ἥττονα, τῆς ἀρχῆς ἐφίεσθαι καὶ κρατήσειν ἐπίδοξον εἶναι τῇ χειροτονίᾳ. τὸν οὖν Θεμιστοκλέα δείσαντα, μὴ τὰ πράγματα διαφθαρείη παντάπασι τῆς ἡγεμονίας εἰς ἐκεῖνον ἐμπεσούσης, χρήμασι τὴν φιλοτιμίαν ἐξωνήσασθαι παρὰ τοῦ Ἐπικύδους.", "st": "Them. 6.1"}, {"sp": "N", "t": "ἐπαινεῖται δ’ αὐτοῦ καὶ τὸ περὶ τὸν δίγλωττον ἔργον ἐν τοῖς πεμφθεῖσιν ὑπὸ βασιλέως ἐπὶ γῆς καὶ ὕδατος αἴτησιν. ἑρμηνέα γὰρ ὄντα συλλαβὼν διὰ ψηφίσματος ἀπέκτεινεν ὅτι φωνὴν Ἑλληνίδα βαρβάροις προστάγμασιν ἐτόλμησε χρῆσαι. ἔτι δὲ καὶ τὸ περὶ Ἄρθμιον τὸν Ζελείτην· Θεμιστοκλέους γὰρ εἰπόντος καὶ τοῦτον εἰς τοὺς ἀτίμους καὶ παῖδας αὐτοῦ καὶ γένος ἐνέγραψαν, ὅτι τὸν ἐκ Μήδων χρυσὸν εἰς τοὺς Ἕλληνας ἐκόμισε. μέγιστον δὲ πάντων τὸ καταλῦσαι τοὺς Ἑλληνικοὺς πολέμους καὶ διαλλάξαι τὰς πόλεις ἀλλήλαις, πείσαντα τὰς ἔχθρας διὰ τὸν πόλεμον ἀναβαλέσθαι· πρὸς ὃ καὶ Χείλεων τὸν Ἀρκάδα μάλιστα συναγωνίσασθαι λέγουσι.", "st": "Them. 6.2"}, {"sp": "N", "t": "παραλαβὼν δὲ τὴν ἀρχὴν εὐθὺς μὲν ἐπεχείρει τοὺς πολίτας ἐμβιβάζειν εἰς τὰς τριήρεις, καὶ τὴν πόλιν ἔπειθεν ἐκλιπόντας ὡς προσωτάτω τῆς Ἑλλάδος ἀπαντᾶν τῷ βαρβάρῳ κατὰ θάλατταν. ἐνισταμένων δὲ πολλῶν ἐξήγαγε πολλὴν στρατιὰν εἰς τὰ Τέμπη μετὰ Λακεδαιμονίων, ὡς αὐτόθι προκινδυνευσόντων τῆς Θετταλίας οὔπω τότε μηδίζειν δοκούσης· ἐπεὶ δ’ ἀνεχώρησαν ἐκεῖθεν ἄπρακτοι καὶ Θετταλῶν βασιλεῖ προσγενομένων ἐμήδιζε τὰ μέχρι Βοιωτίας, μᾶλλον ἤδη τῷ Θεμιστοκλεῖ προσεῖχον οἱ Ἀθηναῖοι περὶ τῆς θαλάσσης, καὶ πέμπεται μετὰ νεῶν ἐπ’ Ἀρτεμίσιον τὰ στενὰ φυλάξων.", "st": "Them. 7.1"}, {"sp": "N", "t": "ἔνθα δὴ τῶν μὲν Ἑλλήνων Εὐρυβιάδην καὶ Λακεδαιμονίους ἡγεῖσθαι κελευόντων, τῶν δ’ Ἀθηναίων, ὅτι πλήθει τῶν νεῶν σύμπαντας ὁμοῦ τι τοὺς ἄλλους ὑπερέβαλλον, οὐκ ἀξιούντων ἑτέροις ἕπεσθαι, συνιδὼν τὸν κίνδυνον ὁ Θεμιστοκλῆς αὐτός τε τὴν ἀρχὴν τῷ Εὐρυβιάδῃ παρῆκε καὶ κατεπράϋνε τοὺς Ἀθηναίους, ὑπισχνούμενος, ἂν ἄνδρες ἀγαθοὶ γένωνται πρὸς τὸν πόλεμον, ἑκόντας αὐτοῖς παρέξειν εἰς τὰ λοιπὰ πειθομένους τοὺς Ἕλληνας. διόπερ δοκεῖ τῆς σωτηρίας αἰτιώτατος γενέσθαι τῇ Ἑλλάδι καὶ μάλιστα τοὺς Ἀθηναίους προαγαγεῖν εἰς δόξαν, ὡς ἀνδρείᾳ μὲν τῶν πολεμίων, εὐγνωμοσύνῃ δὲ τῶν συμμάχων περιγενομένους.", "st": "Them. 7.3"}, {"sp": "N", "t": "ἐπεὶ δὲ ταῖς Ἀφεταῖς τοῦ βαρβαρικοῦ στόλου προσμίξαντος ἐκπλαγεὶς ὁ Εὐρυβιάδης τῶν κατὰ στόμα νεῶν τὸ πλῆθος, ἄλλας δὲ πυνθανόμενος διακοσίας ὑπὲρ Σκιάθου περιπλεῖν, ἐβούλετο τὴν ταχίστην εἴσω τῆς Ἑλλάδος κομισθεὶς ἅψασθαι Πελοποννήσου καὶ τὸν πεζὸν στρατὸν ταῖς ναυσὶ προσπεριβαλέσθαι, παντάπασιν ἀπρόσμαχον ἡγούμενος τὴν κατὰ θάλατταν ἀλκὴν βασιλέως, δείσαντες οἱ Εὐβοεῖς, μὴ σφᾶς οἱ Ἕλληνες πρόωνται, κρύφα τῷ Θεμιστοκλεῖ διελέγοντο, Πελάγοντα μετὰ χρημάτων πολλῶν πέμψαντες. ἃ λαβὼν ἐκεῖνος, ὡς Ἡρόδοτος ἱστόρηκε, τοῖς περὶ τὸν Εὐρυβιάδην ἔδωκεν.", "st": "Them. 7.4"}, {"sp": "N", "t": "ἐναντιουμένου δ’ αὐτῷ μάλιστα τῶν πολιτῶν Ἀρχιτέλους, ὃς ἦν μὲν ἐπὶ τῆς ἱερᾶς νεὼς τριήραρχος, οὐκ ἔχων δὲ χρήματα τοῖς ναύταις χορηγεῖν ἔσπευδεν ἀποπλεῦσαι, παρώξυνεν ἔτι μᾶλλον ὁ Θεμιστοκλῆς τοὺς τριηρίτας ἐπ’ αὐτόν, ὥστε τὸ δεῖπνον ἁρπάσαι συνδραμόντας. τοῦ δ’ Ἀρχιτέλους ἀθυμοῦντος ἐπὶ τούτῳ καὶ βαρέως φέροντος, εἰσέπεμψεν ὁ Θεμιστοκλῆς πρὸς αὐτὸν ἐν κίστῃ δεῖπνον ἄρτων καὶ κρεῶν, ὑποθεὶς κάτω τάλαντον ἀργυρίου καὶ κελεύσας αὐτόν τε δειπνεῖν ἐν τῷ παρόντι καὶ μεθ’ ἡμέραν ἐπιμεληθῆναι τῶν τριηριτῶν· εἰ δὲ μή, καταβοήσειν αὐτοῦ πρὸς τοὺς παρόντας ὡς ἔχοντος ἀργύριον παρὰ τῶν πολεμίων. ταῦτα μὲν οὖν Φανίας ὁ Λέσβιος εἴρηκεν.", "st": "Them. 7.6"}, {"sp": "N", "t": "αἱ δὲ γενόμεναι τότε πρὸς τὰς τῶν βαρβάρων ναῦς περὶ τὰ στενὰ μάχαι κρίσιν μὲν εἰς τὰ ὅλα μεγάλην οὐκ ἐποίησαν, τῇ δὲ πείρᾳ μέγιστα τοὺς Ἕλληνας ὤνησαν, ὑπὸ τῶν ἔργων παρὰ τοὺς κινδύνους διδαχθέντας, ὡς οὔτε πλήθη νεῶν οὔτε κόσμοι καὶ λαμπρότητες ἐπισήμων οὔτε κραυγαὶ κομπώδεις ἢ βάρβαροι παιᾶνες ἔχουσι τι δεινὸν ἀνδράσιν ἐπισταμένοις εἰς χεῖρας ἰέναι καὶ μάχεσθαι τολμῶσιν, ἀλλὰ δεῖ τῶν τοιούτων καταφρονοῦντας ἐπ’ αὐτὰ τὰ σώματα φέρεσθαι καὶ πρὸς ἐκεῖνα διαγωνίζεσθαι συμπλακέντας. ὃ δὴ καὶ Πίνδαρος οὐ κακῶς ἔοικε συνιδὼν ἐπὶ τῆς ἐν Ἀρτεμισίῳ μάχης εἰπεῖν·", "st": "Them. 8.1"}, {"sp": "N", "t": "ὅθι παῖδες Ἀθαναίων ἐβάλοντο φαεννὰν<br>κρηπῖδ’ ἐλευθερίας·", "st": "Them. 8.1b"}, {"sp": "N", "t": "ἀρχὴ γὰρ ὄντως τοῦ νικᾶν τὸ θαρρεῖν.", "st": "Them. 8.1c"}, {"sp": "N", "t": "ἔστι δὲ τῆς Εὐβοίας τὸ Ἀρτεμίσιον ὑπὲρ τὴν Ἑστίαιαν αἰγιαλὸς εἰς βορέαν ἀναπεπταμένος, ἀντιτείνει δ’ αὐτῷ μάλιστα τῆς ὑπὸ Φιλοκτήτῃ γενομένης χώρας Ὀλιζών. ἔχει δὲ ναὸν οὐ μέγαν Ἀρτέμιδος ἐπίκλησιν Προσηῴας, καὶ δένδρα περὶ αὐτῷ πέφυκε καὶ στῆλαι κύκλῳ λίθου λευκοῦ πεπήγασιν· ὁ δὲ λίθος τῇ χειρὶ τριβόμενος καὶ χρόαν καὶ ὀσμὴν κροκίζουσαν ἀναδίδωσιν. ἐν μιᾷ δὲ τῶν στηλῶν ἐλεγεῖον ἦν τόδε γεγραμμένον·", "st": "Them. 8.3"}, {"sp": "N", "t": "παντοδαπῶν ἀνδρῶν γενεὰς Ἀσίας ἀπὸ χώρας παῖδες Ἀθηναίων τῷδέ ποτ’ ἐν πελάγει<br>ναυμαχίῃ δαμάσαντες, ἐπεὶ στρατὸς ὤλετο Μήδων,<br>σήματα ταῦτ’ ἔθεσαν παρθένῳ Ἀρτέμιδι.", "st": "Them. 8.3b"}, {"sp": "N", "t": "δείκνυται δὲ τῆς ἀκτῆς τόπος ἐν πολλῇ τῇ πέριξ θινὶ κόνιν τεφρώδη καὶ μέλαιναν ἐκ βάθους ἀναδιδούς, ὥσπερ πυρίκαυστον, ἐν ᾧ τὰ ναυάγια καὶ νεκροὺς καῦσαι δοκοῦσι.", "st": "Them. 8.3c"}, {"sp": "N", "t": "τῶν μέντοι περὶ Θερμοπύλας εἰς τὸ Ἀρτεμίσιον ἀπαγγελλόντων πυθόμενοι Λεωνίδαν τε κεῖσθαι καὶ κρατεῖν Ξέρξην τῶν κατὰ γῆν παρόδων, εἴσω τῆς Ἑλλάδος ἀνεκομίζοντο, τῶν Ἀθηναίων ἐπὶ πᾶσι τεταγμένων δι’ ἀρετὴν καὶ μέγα τοῖς πεπραγμένοις φρονούντων. παραπλέων δὲ τὴν χώραν ὁ Θεμιστοκλῆς, ᾗπερ κατάρσεις ἀναγκαίας καὶ καταφυγὰς ἑώρα τοῖς πολεμίοις, ἐνεχάραττε κατὰ τῶν λίθων ἐπιφανῆ γράμματα, τοὺς μὲν εὑρίσκων ἀπὸ τύχης, τοὺς δ’ αὐτὸς ἱστὰς περὶ τὰ ναύλοχα καὶ τὰς ὑδρείας, ἐπισκήπτων Ἴωσι διὰ τῶν γραμμάτων, εἰ μὲν οἷόν τε, μετατάξασθαι πρὸς αὐτοὺς πατέρας ὄντας καὶ προκινδυνεύοντας ὑπὲρ τῆς ἐκείνων ἐλευθερίας, εἰ δὲ μή, κακοῦν τὸ βαρβαρικὸν ἐν ταῖς μάχαις καὶ συνταράττειν. ταῦτα δ’ ἤλπιζεν ἢ μεταστήσειν τοὺς Ἴωνας ἢ ταράξειν ὑποπτοτέρους τοῖς βαρβάροις γενομένους.", "st": "Them. 9.1"}, {"sp": "N", "t": "Ξέρξου δὲ διὰ τῆς Δωρίδος ἄνωθεν ἐμβαλόντος εἰς τὴν Φωκίδα καὶ τὰ τῶν Φωκέων ἄστη πυρπολοῦντος οὐ προσήμυναν οἱ Ἕλληνες, καίπερ τῶν Ἀθηναίων δεομένων εἰς τὴν Βοιωτίαν ἀπαντῆσαι πρὸ τῆς Ἀττικῆς, ὥσπερ αὐτοὶ κατὰ θάλατταν ἐπ’ Ἀρτεμίσιον ἐβοήθησαν. μηδενὸς δ’ ὑπακούοντος αὐτοῖς, ἀλλὰ τῆς Πελοποννήσου περιεχομένων καὶ πᾶσαν ἐντὸς Ἰσθμοῦ τὴν δύναμιν ὡρμημένων συνάγειν, καὶ διατειχιζόντων τὸν Ἰσθμὸν εἰς θάλατταν ἐκ θαλάττης, ἅμα μὲν ὀργὴ τῆς προδοσίας εἶχε τοὺς Ἀθηναίους, ἅμα δὲ δυσθυμία καὶ κατήφεια μεμονωμένους. μάχεσθαι μὲν γὰρ οὐ διενοοῦντο μυριάσι στρατοῦ τοσαύταις· ὃ δ’ ἦν μόνον ἀναγκαῖον ἐν τῷ παρόντι, τὴν πόλιν ἀφέντας ἐμφῦναι ταῖς ναυσίν, οἱ πολλοὶ χαλεπῶς ἤκουον, ὡς μήτε νίκης δεόμενοι μήτε σωτηρίαν ἐπιστάμενοι θεῶν τε ἱερὰ καὶ πατέρων ἠρία προϊεμένων.", "st": "Them. 9.3"}, {"sp": "N", "t": "ἔνθα δὴ Θεμιστοκλῆς ἀπορῶν τοῖς ἀνθρωπίνοις λογισμοῖς προσάγεσθαι τὸ πλῆθος, ὥσπερ ἐν τραγῳδίᾳ μηχανὴν ἄρας, σημεῖα δαιμόνια καὶ χρησμοὺς ἐπῆγεν αὐτοῖς· σημεῖον μὲν λαμβάνων τὸ τοῦ δράκοντος, ὃς ἀφανὴς ἐκείναις ταῖς ἡμέραις ἐκ τοῦ σηκοῦ δοκεῖ γενέσθαι· καὶ τὰς καθ’ ἡμέραν αὐτῷ προτιθεμένας ἀπαρχὰς εὑρίσκοντες ἀψαύστους οἱ ἱερεῖς, ἐξήγγελλον εἰς τοὺς πολλούς, τοῦ Θεμιστοκλέους λόγον διδόντος, ὡς ἀπολέλοιπε τὴν πόλιν ἡ θεὸς ὑφηγουμένη πρὸς τὴν θάλατταν αὐτοῖς. τῷ δὲ χρησμῷ πάλιν ἐδημαγώγει, λέγων μηδὲν ἄλλο δηλοῦσθαι ξύλινον τεῖχος ἢ τὰς ναῦς· διὸ καὶ τὴν Σαλαμῖνα θείαν, οὐχὶ δεινὴν οὐδὲ σχετλίαν καλεῖν τὸν θεόν, ὡς εὐτυχήματος μεγάλου τοῖς Ἕλλησιν ἐπώνυμον ἐσομένην. κρατήσας δὲ τῇ γνώμῃ ψήφισμα γράφει, τὴν μὲν πόλιν παρακαταθέσθαι τῇ Ἀθηνᾷ τῇ Ἀθηνάων μεδεούσῃ, τοὺς δ’ ἐν ἡλικίᾳ πάντας ἐμβαίνειν εἰς τὰς τριήρεις, παῖδας δὲ καὶ γυναῖκας καὶ ἀνδράποδα σώζειν ἕκαστον ὡς δυνατόν. κυρωθέντος δὲ τοῦ ψηφίσματος οἱ πλεῖστοι τῶν Ἀθηναίων ὑπεξέθεντο γενεὰς καὶ γυναῖκας εἰς Τροιζῆνα, φιλοτίμως πάνυ τῶν Τροιζηνίων ὑποδεχομένων· καὶ γὰρ τρέφειν ἐψηφίσαντο δημοσίᾳ, δύο ὀβολοὺς ἑκάστῳ διδόντες, καὶ τῆς ὀπώρας λαμβάνειν τοὺς παῖδας ἐξεῖναι πανταχόθεν, ἔτι δ’ ὑπὲρ αὐτῶν διδασκάλοις τελεῖν μισθούς. τὸ δὲ ψήφισμα Νικαγόρας ἔγραψεν.", "st": "Them. 10.1"}, {"sp": "N", "t": "οὐκ ὄντων δὲ δημοσίων χρημάτων τοῖς Ἀθηναίοις, Ἀριστοτέλης μέν φησι τὴν ἐξ Ἀρείου πάγου βουλὴν πορίσασαν ὀκτὼ δραχμὰς ἑκάστῳ τῶν στρατευομένων αἰτιωτάτην γενέσθαι τοῦ πληρωθῆναι τὰς τριήρεις, Κλείδημος δὲ καὶ τοῦτο τοῦ Θεμιστοκλέους ποιεῖται στρατήγημα. καταβαινόντων γὰρ εἰς Πειραιᾶ τῶν Ἀθηναίων, φησὶν ἀπολέσθαι τὸ Γοργόνειον ἀπὸ τῆς θεοῦ τοῦ ἀγάλματος· τὸν οὖν Θεμιστοκλέα προσποιούμενον ζητεῖν καὶ διερευνώμενον ἅπαντα χρημάτων ἀνευρίσκειν πλῆθος ἐν ταῖς ἀποσκευαῖς ἀποκεκρυμμένον, ὧν εἰς μέσον κομισθέντων εὐπορῆσαι τοὺς ἐμβαίνοντας εἰς τὰς ναῦς ἐφοδίων.", "st": "Them. 10.4"}, {"sp": "N", "t": "ἐκπλεούσης δὲ τῆς πόλεως τοῖς μὲν οἶκτον τὸ θέαμα, τοῖς δὲ θαῦμα τῆς τόλμης παρεῖχε, γενεὰς μὲν ἄλλῃ προπεμπόντων, αὐτῶν δ’ ἀκάμπτων πρὸς οἰμωγὰς καὶ δάκρυα γονέων καὶ περιβολὰς διαπερώντων εἰς τὴν νῆσον. καίτοι πολλοὶ μὲν διὰ γῆρας ὑπολειπόμενοι τῶν πολιτῶν ἔλεον εἶχον· ἦν δέ τις καὶ ἀπὸ τῶν ἡμέρων καὶ συντρόφων ζῴων ἐπικλῶσα γλυκυθυμία, μετ’ ὠρυγῆς καὶ πόθου συμπαραθεόντων ἐμβαίνουσι τοῖς ἑαυτῶν τροφεῦσιν. ἐν οἷς ἱστορεῖται κύων Ξανθίππου τοῦ Περικλέους πατρὸς οὐκ ἀνασχόμενος τὴν ἀπ’ αὐτοῦ μόνωσιν ἐναλέσθαι τῇ θαλάττῃ καὶ τῇ τριήρει παρανηχόμενος ἐκπεσεῖν εἰς τὴν Σαλαμῖνα καὶ λιποθυμήσας ἀποθανεῖν εὐθύς· οὗ καὶ τὸ δεικνύμενον ἄχρι νῦν καὶ καλούμενον Κυνὸς σῆμα τάφον εἶναι λέγουσι.", "st": "Them. 10.5"}, {"sp": "N", "t": "ταῦτά τε δὴ μεγάλα τοῦ Θεμιστοκλέους, καὶ τοὺς πολίτας αἰσθόμενος ποθοῦντας Ἀριστείδην καὶ δεδιότας, μὴ δι’ ὀργὴν τῷ βαρβάρῳ προσθεὶς ἑαυτὸν ἀνατρέψῃ τὰ πράγματα τῆς Ἑλλάδος (ἐξωστράκιστο γὰρ πρὸ τοῦ πολέμου καταστασιασθεὶς ὑπὸ Θεμιστοκλέους), γράφει ψήφισμα, τοῖς ἐπὶ χρόνῳ μεθεστῶσιν ἐξεῖναι κατελθοῦσι πράττειν καὶ λέγειν τὰ βέλτιστα τῇ Ἑλλάδι μετὰ τῶν ἄλλων πολιτῶν.", "st": "Them. 11.1"}, {"sp": "N", "t": "Εὐρυβιάδου δὲ τὴν μὲν ἡγεμονίαν τῶν νεῶν ἔχοντος διὰ τὸ τῆς Σπάρτης ἀξίωμα, μαλακοῦ δὲ περὶ τὸν κίνδυνον ὄντος, αἴρειν δὲ βουλομένου καὶ πλεῖν ἐπὶ τὸν Ἰσθμόν, ὅπου καὶ τὸ πεζὸν ἤθροιστο τῶν Πελοποννησίων, ὁ Θεμιστοκλῆς ἀντέλεγεν· ὅτε καὶ τὰ μνημονευόμενα λεχθῆναί φασι. τοῦ γὰρ Εὐρυβιάδου πρὸς αὐτὸν εἰπόντος· ὦ Θεμιστόκλεις, ἐν τοῖς ἀγῶσι τοὺς προεξανισταμένους ῥαπίζουσι, ναὶ, εἶπεν ὁ Θεμιστοκλῆς, ἀλλὰ τοὺς ἀπολειφθέντας οὐ στεφανοῦσιν. ἐπαραμένου δὲ τὴν βακτηρίαν ὡς πατάξοντος, ὁ Θεμιστοκλῆς ἔφη· πάταξον μέν, ἄκουσον δέ. θαυμάσαντος δὲ τὴν πρᾳότητα τοῦ Εὐρυβιάδου καὶ λέγειν κελεύσαντος, ὁ μὲν Θεμιστοκλῆς ἀνῆγεν αὐτὸν ἐπὶ τὸν λόγον. εἰπόντος δέ τινος, ὡς ἀνὴρ ἄπολις οὐκ ὀρθῶς διδάσκει τοὺς ἔχοντας ἐγκαταλιπεῖν καὶ προέσθαι τὰς πατρίδας, ὁ Θεμιστοκλῆς ἐπιστρέψας τὸν λόγον· ἡμεῖς τοι, εἶπεν, ὦ μοχθηρέ, τὰς μὲν οἰκίας καὶ τὰ τείχη καταλελοίπαμεν, οὐκ ἀξιοῦντες ἀψύχων ἕνεκα δουλεύειν, πόλις δ’ ἡμῖν ἔστι μεγίστη τῶν Ἑλληνίδων, αἱ διακόσιαι τριήρεις, αἳ νῦν μὲν ὑμῖν παρεστᾶσι βοηθοὶ σώζεσθαι δι’ αὐτῶν βουλομένοις, εἰ δ’ ἄπιτε δεύτερον ἡμᾶς προδόντες, αὐτίκα πεύσεταί τις Ἑλλήνων Ἀθηναίους καὶ πόλιν ἐλευθέραν καὶ χώραν οὐ χείρονα κεκτημένους ἧς ἀπέβαλον. ταῦτα τοῦ Θεμιστοκλέους εἰπόντος ἔννοια καὶ δέος ἔσχε τὸν Εὐρυβιάδην τῶν Ἀθηναίων, μὴ σφᾶς ἀπολείποντες οἴχονται. τοῦ δ’ Ἐρετριέως πειρωμένου τι λέγειν πρὸς αὐτόν, ἦ γάρ, ἔφη, καὶ ὑμῖν περὶ πολέμου τίς ἐστι λόγος, οἳ καθάπερ αἱ τευθίδες μάχαιραν μὲν ἔχετε, καρδίαν δὲ οὐκ ἔχετε;", "st": "Them. 11.2"}, {"sp": "N", "t": "λέγεται δ’ ὑπό τινων τὸν μὲν Θεμιστοκλέα περὶ τούτων ἀπὸ τοῦ καταστρώματος ἄνωθεν τῆς νεὼς διαλέγεσθαι, γλαῦκα δ’ ὀφθῆναι διαπετομένην ἀπὸ δεξιᾶς τῶν νεῶν καὶ τοῖς καρχησίοις ἐπικαθίζουσαν· διὸ δὴ καὶ μάλιστα προσέθεντο τῇ γνώμῃ καὶ παρεσκευάζοντο ναυμαχήσοντες. ἀλλ’ ἐπεὶ τῶν πολεμίων ὅ τε στόλος τῇ Ἀττικῇ κατὰ τὸ Φαληρικὸν προσφερόμενος τοὺς πέριξ ἀπέκρυψεν αἰγιαλούς, αὐτός τε βασιλεὺς μετὰ τοῦ πεζοῦ στρατοῦ καταβὰς ἐπὶ τὴν θάλατταν ἅθρους ὤφθη, τῶν δὲ δυνάμεων ὁμοῦ γενομένων, ἐξερρύησαν οἱ τοῦ Θεμιστοκλέους λόγοι τῶν Ἑλλήνων καὶ πάλιν ἐπάπταινον οἱ Πελοποννήσιοι πρὸς τὸν Ἰσθμόν, εἴ τις ἄλλο τι λέγοι χαλεπαίνοντες, ἐδόκει δὲ τῆς νυκτὸς ἀποχωρεῖν καὶ παρηγγέλλετο πλοῦς τοῖς κυβερνήταις, ἔνθα δὴ βαρέως φέρων ὁ Θεμιστοκλῆς, εἰ τὴν ἀπὸ τοῦ τόπου καὶ τῶν στενῶν προέμενοι βοήθειαν οἱ Ἕλληνες διαλυθήσονται κατὰ πόλεις, ἐβουλεύετο καὶ συνετίθει τὴν περὶ τὸν Σίκιννον πραγματείαν.", "st": "Them. 12.1"}, {"sp": "N", "t": "ἦν δὲ τῷ μὲν γένει Πέρσης ὁ Σίκιννος, αἰχμάλωτος, εὔνους δὲ τῷ Θεμιστοκλεῖ καὶ τῶν τέκνων αὐτοῦ παιδαγωγός. ὃν ἐκπέμπει πρὸς τὸν Ξέρξην κρύφα, κελεύσας λέγειν, ὅτι Θεμιστοκλῆς ὁ τῶν Ἀθηναίων στρατηγὸς αἱρούμενος τὰ βασιλέως ἐξαγγέλλει πρῶτος αὐτῷ τοὺς Ἕλληνας ἀποδιδράσκοντας, καὶ διακελεύεται μὴ παρεῖναι φυγεῖν αὐτοῖς, ἀλλ’ ἐν ᾧ ταράττονται τῶν πεζῶν χωρὶς ὄντες ἐπιθέσθαι καὶ διαφθεῖραι τὴν ναυτικὴν δύναμιν. ταῦτα δ’ ὁ Ξέρξης ὡς ἀπ’ εὐνοίας λελεγμένα δεξάμενος ἥσθη, καὶ τέλος εὐθὺς ἐξέφερε πρὸς τοὺς ἡγεμόνας τῶν νεῶν, τὰς μὲν ἄλλας πληροῦν καθ’ ἡσυχίαν, διακοσίαις δ’ ἀναχθέντας ἤδη περιβαλέσθαι τὸν πόρον ἐν κύκλῳ πάντα καὶ διαζῶσαι τὰς νήσους, ὅπως ἐκφύγοι μηδεὶς τῶν πολεμίων.", "st": "Them. 12.4"}, {"sp": "N", "t": "τούτων δὲ πραττομένων Ἀριστείδης ὁ Λυσιμάχου πρῶτος αἰσθόμενος ἧκεν ἐπὶ τὴν σκηνὴν τοῦ Θεμιστοκλέους, οὐκ ὢν φίλος, ἀλλὰ καὶ δι’ ἐκεῖνον ἐξωστρακισμένος, ὥσπερ εἴρηται· προελθόντι δὲ τῷ Θεμιστοκλεῖ φράζει τὴν κύκλωσιν. ὁ δὲ τήν τε ἄλλην καλοκαγαθίαν τοῦ ἀνδρὸς εἰδὼς καὶ τῆς τότε παρουσίας ἀγάμενος λέγει τὰ περὶ τὸν Σίκιννον αὐτῷ καὶ παρεκάλει τῶν Ἑλλήνων συνεπιλαμβάνεσθαι καὶ συμπροθυμεῖσθαι πίστιν ἔχοντα μᾶλλον, ὅπως ἐν τοῖς στενοῖς ναυμαχήσωσιν. ὁ μὲν οὖν Ἀριστείδης ἐπαινέσας τὸν Θεμιστοκλέα τοὺς ἄλλους ἐπῄει στρατηγοὺς καὶ τριηράρχους ἐπὶ τὴν μάχην παροξύνων. ἔτι δ’ ὅμως ἀπιστούντων ἐφάνη Τηνία τριήρης αὐτόμολος, ἧς ἐναυάρχει Παναίτιος, ἀπαγγέλλουσα τὴν κύκλωσιν, ὥστε καὶ θυμῷ τοὺς Ἕλληνας ὁρμῆσαι μετὰ τῆς ἀνάγκης πρὸς τὸν κίνδυνον.", "st": "Them. 12.6"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ Ξέρξης μὲν ἄνω καθῆστο τὸν στόλον ἐποπτεύων καὶ τὴν παράταξιν, ὡς μὲν Φανόδημός φησιν, ὑπὲρ τὸ Ἡράκλειον, ᾗ βραχεῖ πόρῳ διείργεται τῆς Ἀττικῆς ἡ νῆσος, ὡς δ’ Ἀκεστόδωρος, ἐν μεθορίῳ τῆς Μεγαρίδος ὑπὲρ τῶν καλουμένων Κεράτων, χρυσοῦν δίφρον θέμενος καὶ γραμματεῖς πολλοὺς παραστησάμενος, ὧν ἔργον ἦν ἀπογράφεσθαι τὰ κατὰ τὴν μάχην πραττόμενα.", "st": "Them. 13.1"}, {"sp": "N", "t": "Θεμιστοκλεῖ δὲ παρὰ τὴν ναυαρχίδα τριήρη σφαγιαζομένῳ τρεῖς προσήχθησαν αἰχμάλωτοι, κάλλιστοι μὲν ἰδέσθαι τὴν ὄψιν, ἐσθῆσι δὲ καὶ χρυσῷ κεκοσμημένοι διαπρεπῶς. ἐλέγοντο δὲ Σανδαύκης παῖδες εἶναι τῆς βασιλέως ἀδελφῆς καὶ Ἀρταΰκτου. τούτους ἰδὼν Εὐφραντίδης ὁ μάντις, ὡς ἅμα μὲν ἀνέλαμψεν ἐκ τῶν ἱερῶν μέγα καὶ περιφανὲς πῦρ, ἅμα δὲ πταρμὸς ἐκ δεξιῶν ἐσήμηνε, τὸν Θεμιστοκλέα δεξιωσάμενος ἐκέλευσε τῶν νεανίσκων κατάρξασθαι καὶ καθιερεῦσαι πάντας ὠμηστῇ Διονύσῳ προσευξάμενον· οὕτω γὰρ ἅμα σωτηρίαν τε καὶ νίκην ἔσεσθαι τοῖς Ἕλλησιν. ἐκπλαγέντος δὲ τοῦ Θεμιστοκλέους ὡς μέγα τὸ μάντευμα καὶ δεινόν, οἷον εἴωθεν ἐν μεγάλοις ἀγῶσι καὶ πράγμασι χαλεποῖς, μᾶλλον ἐκ τῶν παραλόγων ἤ τῶν εὐλόγων τὴν σωτηρίαν ἐλπίζοντες οἱ πολλοὶ τὸν θεὸν ἅμα κοινῇ κατεκαλοῦντο φωνῇ καὶ τοὺς αἰχμαλώτους τῷ βωμῷ προσαγαγόντες ἠνάγκασαν, ὡς ὁ μάντις ἐκέλευσε, τὴν θυσίαν συντελεσθῆναι. ταῦτα μὲν οὖν ἀνὴρ φιλόσοφος καὶ γραμμάτων οὐκ ἄπειρος ἱστορικῶν Φανίας ὁ Λέσβιος εἴρηκε.", "st": "Them. 13.2"}, {"sp": "N", "t": "περὶ δὲ τοῦ πλήθους τῶν βαρβαρικῶν νεῶν Αἰσχύλος ὁ ποιητὴς ὡς ἂν εἰδὼς καὶ διαβεβαιούμενος ἐν τραγῳδίᾳ Πέρσαις λέγει ταῦτα·", "st": "Them. 14.1"}, {"sp": "N", "t": "Ξέρξῃ δέ, καὶ γὰρ οἶδα, χιλιὰς μὲν ἦν<br>ὧν ἦγε πλῆθος· αἱ δ’ ὑπέρκομποι τάχει<br>ἑκατὸν δὶς ἦσαν ἑπτά θ’· ὧδ’ ἔχει λόγος.", "st": "Them. 14.1b"}, {"sp": "N", "t": "τῶν δ’ Ἀττικῶν ἑκατὸν ὀγδοήκοντα τὸ πλῆθος οὐσῶν ἑκάστη τοὺς ἀπὸ τοῦ καταστρώματος μαχομένους ὀκτωκαίδεκα εἶχεν, ὧν τοξόται τέσσαρες ἦσαν, οἱ λοιποὶ δ’ ὁπλῖται.", "st": "Them. 14.1c"}, {"sp": "N", "t": "δοκεῖ δ’ οὐκ ἧττον εὖ τὸν καιρὸν ὁ Θεμιστοκλῆς ἢ τὸν τόπον συνιδὼν καὶ φυλάξας μὴ πρότερον ἀντιπρῴρους καταστῆσαι ταῖς βαρβαρικαῖς τὰς τριήρεις, ἢ τὴν εἰωθυῖαν ὥραν παραγενέσθαι, τὸ πνεῦμα λαμπρὸν ἐκ πελάγους ἀεὶ καὶ κῦμα διὰ τῶν στενῶν κατάγουσαν· ὃ τὰς μὲν Ἑλληνικὰς οὐκ ἔβλαπτε ναῦς ἁλιτενεῖς οὔσας καὶ ταπεινοτέρας, τὰς δὲ βαρβαρικὰς ταῖς τε πρύμναις ἀνεστώσας καὶ τοῖς καταστρώμασιν ὑψορόφους καὶ βαρείας ἐπιφερομένας ἔσφαλλε προσπῖπτον καὶ παρεδίδου πλαγίας τοῖς Ἕλλησιν ὀξέως προσφερομένοις καὶ τῷ Θεμιστοκλεῖ προσέχουσιν, ὡς ὁρῶντι μάλιστα τὸ συμφέρον, καὶ ὅτι κατ’ ἐκεῖνον ὁ Ξέρξου ναύαρχος Ἀριαμένης ναῦν ἔχων μεγάλην ὥσπερ ἀπὸ τείχους ἐτόξευε καὶ ἠκόντιζεν, ἀνὴρ ἀγαθὸς ὢν καὶ τῶν βασιλέως ἀδελφῶν πολὺ κράτιστός τε καὶ δικαιότατος. τοῦτον μὲν οὖν Ἀμεινίας ὁ Δεκελεὺς καὶ Σωκλῆς ὁ Παιανιεὺς ὁμοῦ πλέοντες, ὡς αἱ νῆες ἀντίπρῳροι προσπεσοῦσαι καὶ συνερείσασαι τοῖς χαλκώμασιν ἐνεσχέθησαν, ἐπιβαίνοντα τῆς αὐτῶν τριήρους ὑποστάντες καὶ τοῖς δόρασι τύπτοντες εἰς τὴν θάλασσαν ἐξέβαλον· καὶ τὸ σῶμα μετ’ ἄλλων διαφερόμενον ναυαγίων Ἀρτεμισία γνωρίσασα πρὸς Ξέρξην ἀνήνεγκεν.", "st": "Them. 14.2"}, {"sp": "N", "t": "ἐν δὲ τούτῳ τοῦ ἀγῶνος ὄντος φῶς μὲν ἐκλάμψαι μέγα λέγουσιν Ἐλευσινόθεν, ἦχον δὲ καὶ φωνὴν τὸ Θριάσιον κατέχειν πεδίον ἄχρι θαλάττης, ὡς ἀνθρώπων ὁμοῦ πολλῶν τὸν μυστικὸν ἐξαγόντων Ἴακχον. ἐκ δὲ τοῦ πλήθους τῶν φθεγγομένων κατὰ μικρὸν ἀπὸ γῆς ἀναφερόμενον νέφος ἔδοξεν αὖθις ὑπονοστεῖν καὶ κατασκήπτειν εἰς τὰς τριήρεις. ἕτεροι δὲ φάσματα καὶ εἴδωλα καθορᾶν ἔδοξαν ἐνόπλων ἀνδρῶν ἀπ’ Αἰγίνης τὰς χεῖρας ἀνεχόντων πρὸ τῶν Ἑλληνικῶν τριηρῶν· οὓς εἴκαζον Αἰακίδας εἶναι παρακεκλημένους εὐχαῖς πρὸ τῆς μάχης ἐπὶ τὴν βοήθειαν.", "st": "Them. 15.1"}, {"sp": "N", "t": "πρῶτος μὲν οὖν λαμβάνει ναῦν Λυκομήδης, ἀνὴρ Ἀθηναῖος τριηραρχῶν, ἧς τὰ παράσημα περικόψας ἀνέθηκεν Ἀπόλλωνι δαφνηφόρῳ Φλυῆσιν. οἱ δ’ ἄλλοι τοῖς βαρβάροις ἐξισούμενοι τὸ πλῆθος ἐν στενῷ κατὰ μέρος προσφερομένους καὶ περιπίπτοντας ἀλλήλοις ἐτρέψαντο, μέχρι δείλης ἀντισχόντας, ὡς εἴρηκε Σιμωνίδης, τὴν καλὴν ἐκείνην καὶ περιβόητον ἀράμενοι νίκην, ἧς οὔθ’ Ἕλλησιν οὔτε βαρβάροις ἐνάλιον ἔργον εἴργασται λαμπρότερον, ἀνδρείᾳ μὲν καὶ προθυμίᾳ κοινῇ τῶν ναυμαχησάντων, γνώμῃ δὲ καὶ δεινότητι τῇ Θεμιστοκλέους.", "st": "Them. 15.2"}, {"sp": "N", "t": "μετὰ δὲ τὴν ναυμαχίαν Ξέρξης μὲν ἔτι θυμομαχῶν πρὸς τὴν ἀπότευξιν ἐπεχείρει διὰ χωμάτων ἐπάγειν τὸ πεζὸν τοῖς Ἕλλησιν εἰς Σαλαμῖνα, ἐμφράξας τὸν διὰ μέσου πόρον· Θεμιστοκλῆς δ’ ἀποπειρώμενος Ἀριστείδου λόγῳ γνώμην ἐποιεῖτο λύειν τὸ ζεῦγμα ταῖς ναυσὶν ἐπιπλεύσαντας εἰς Ἑλλήσποντον, ὅπως, ἔφη, τὴν Ἀσίαν ἐν τῇ Εὐρώπῃ λάβωμεν. δυσχεραίνοντος δὲ τοῦ Ἀριστείδου καὶ λέγοντος ὅτι, νῦν μὲν τρυφῶντι τῷ βαρβάρῳ πεπολεμήκαμεν, ἂν δὲ κατακλείσωμεν εἰς τὴν Ἑλλάδα καὶ καταστήσωμεν εἰς ἀνάγκην ὑπὸ δέους ἄνδρα τηλικούτων δυνάμεων κύριον, οὐκέτι καθήμενος ὑπὸ σκιάδι χρυσῇ θεάσεται τὴν μάχην ἐφ’ ἡσυχίας, ἀλλὰ πάντα τολμῶν καὶ πᾶσιν αὐτὸς παρὼν διὰ τὸν κίνδυνον ἐπανορθώσεται τὰ παρειμένα καὶ βουλεύσεται βέλτιον ὑπὲρ τῶν ὅλων· οὐ τὴν οὖσαν οὖν, ἔφη, δεῖ γέφυραν, ὦ Θεμιστόκλεις, ἡμᾶς ἀναιρεῖν, ἀλλ’ ἑτέραν, εἴπερ οἷόν τε, προσκατασκευάσαντας ἐκβαλεῖν διὰ τάχους τὸν ἄνθρωπον ἐκ τῆς Εὐρώπης. οὐκοῦν, εἶπεν ὁ Θεμιστοκλῆς, εἰ δοκεῖ ταῦτα συμφέρειν, ὥρα σκοπεῖν καὶ μηχανᾶσθαι πάντας ἡμᾶς, ὅπως ἀπαλλαγήσεται τὴν ταχίστην ἐκ τῆς Ἑλλάδος.", "st": "Them. 16.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ταῦτα ἔδοξε, πέμπει τινὰ τῶν βασιλικῶν εὐνούχων ἐν τοῖς αἰχμαλώτοις ἀνευρών, Ἀρνάκην ὄνομα, φράζειν βασιλεῖ κελεύσας, ὅτι τοῖς μὲν Ἕλλησι δέδοκται τῷ ναυτικῷ κεκρατηκότας ἀναπλεῖν εἰς τὸν Ἑλλήσποντον ἐπὶ τὸ ζεῦγμα καὶ λύειν τὴν γέφυραν, Θεμιστοκλῆς δὲ κηδόμενος βασιλέως παραινεῖ σπεύδειν ἐπὶ τὴν ἑαυτοῦ θάλατταν καὶ περαιοῦσθαι, μέχρις αὐτὸς ἐμποιεῖ τινας διατριβὰς τοῖς συμμάχοις καὶ μελλήσεις πρὸς τὴν δίωξιν. ταῦθ’ ὁ βάρβαρος ἀκούσας καὶ γενόμενος περίφοβος διὰ τάχους ἐποιεῖτο τὴν ἀναχώρησιν. καὶ πεῖραν ἡ Θεμιστοκλέους καὶ Ἀριστείδου φρόνησις ἐν Μαρδονίῳ παρέσχεν, εἴγε πολλοστημορίῳ τῆς Ξέρξου δυνάμεως διαγωνισάμενοι Πλαταιᾶσιν εἰς τὸν περὶ τῶν ὅλων κίνδυνον κατέστησαν.", "st": "Them. 16.4"}, {"sp": "N", "t": "πόλεων μὲν οὖν τὴν Αἰγινητῶν ἀριστεῦσαί φησιν Ἡρόδοτος, Θεμιστοκλεῖ δέ, καίπερ ἄκοντες ὑπὸ φθόνου, τὸ πρωτεῖον ἀπέδοσαν ἅπαντες. ἐπεὶ γὰρ ἀναχωρήσαντες εἰς τὸν Ἰσθμὸν ἀπὸ τοῦ βωμοῦ τὴν ψῆφον ἔφερον οἱ στρατηγοί, πρῶτον μὲν ἕκαστος ἑαυτὸν ἀπέφαινεν ἀρετῇ, δεύτερον δὲ μεθ’ ἑαυτὸν Θεμιστοκλέα. Λακεδαιμόνιοι δ’ εἰς τὴν Σπάρτην αὐτὸν καταγαγόντες Εὐρυβιάδῃ μὲν ἀνδρείας, ἐκείνῳ δὲ σοφίας ἀριστεῖον ἔδοσαν θαλλοῦ στέφανον, καὶ τῶν κατὰ τὴν πόλιν ἁρμάτων τὸ πρωτεῦον ἐδωρήσαντο καὶ τριακοσίους τῶν νέων πομποὺς ἄχρι τῶν ὅρων συνεξέπεμψαν. λέγεται δ’ Ὀλυμπίων τῶν ἐφεξῆς ἀγομένων καὶ παρελθόντος εἰς τὸ στάδιον τοῦ Θεμιστοκλέους, ἀμελήσαντας τῶν ἀγωνιστῶν τοὺς παρόντας ὅλην τὴν ἡμέραν ἐκεῖνον θεᾶσθαι καὶ τοῖς ξένοις ἐπιδεικνύειν ἅμα θαυμάζοντας καὶ κροτοῦντας, ὥστε καὶ αὐτὸν ἡσθέντα πρὸς τοὺς φίλους ὁμολογῆσαι τὸν καρπὸν ἀπέχειν τῶν ὑπὲρ τῆς Ἑλλάδος αὐτῷ πονηθέντων.", "st": "Them. 17.1"}, {"sp": "N", "t": "καὶ γὰρ ἦν τῇ φύσει φιλοτιμότατος, εἰ δεῖ τεκμαίρεσθαι διὰ τῶν ἀπομνημονευομένων. αἱρεθεὶς γὰρ ναύαρχος ὑπὸ τῆς πόλεως οὐδὲν οὔτε τῶν ἰδίων οὔτε τῶν κοινῶν κατὰ μέρος ἐχρημάτιζεν, ἀλλ’ ἐπανεβάλλετο τὸ προσπῖπτον εἰς τὴν ἡμέραν ἐκείνην, καθ’ ἣν ἐκπλεῖν ἔμελλεν, ἵν’ ὁμοῦ πολλὰ πράττων πράγματα καὶ παντοδαποῖς ἀνθρώποις ὁμιλῶν μέγας εἶναι δοκῇ καὶ πλεῖστον δύνασθαι.", "st": "Them. 18.1"}, {"sp": "N", "t": "τῶν δὲ νεκρῶν τοὺς ἐκπεσόντας ἐπισκοπῶν παρὰ τὴν θάλατταν, ὡς εἶδε περικειμένους ψέλια χρυσᾶ καὶ στρεπτούς, αὐτὸς μὲν παρῆλθε, τῷ δ’ ἑπομένῳ φίλῳ δείξας εἶπεν· ἀνελοῦ σαυτῷ· σὺ γὰρ οὐκ εἶ Θεμιστοκλῆς. πρὸς δέ τινα τῶν καλῶν γεγονότων, Ἀντιφάτην, ὑπερηφάνως αὐτῷ κεχρημένον πρότερον, ὕστερον δὲ θεραπεύοντα διὰ τὴν δόξαν, ὦ μειράκιον, εἶπεν, ὀψὲ μέν, ἀμφότεροι δ’ ἅμα νοῦν ἐσχήκαμεν. ἔλεγε δὲ τοὺς Ἀθηναίους οὐ τιμᾶν αὐτὸν οὐδὲ θαυμάζειν, ἀλλ’ ὥσπερ πλατάνῳ χειμαζομένους μὲν ὑποτρέχειν κινδυνεύοντας, εὐδίας δὲ περὶ αὐτοὺς γενομένης τίλλειν καὶ κολούειν. τοῦ δὲ Σεριφίου πρὸς αὐτὸν εἰπόντος, ὡς οὐ δι’ αὑτὸν ἔσχηκε δόξαν, ἀλλὰ διὰ τὴν πόλιν, ἀληθῆ λέγεις, εἶπεν, ἀλλ’ οὔτ’ ἂν ἐγὼ Σερίφιος ὢν ἐγενόμην ἔνδοξος, οὔτε σὺ Ἀθηναῖος.", "st": "Them. 18.2"}, {"sp": "N", "t": "ἑτέρου δέ τινος τῶν στρατηγῶν, ὡς ἔδοξέ τι χρήσιμον διαπεπρᾶχθαι τῇ πόλει, θρασυνομένου πρὸς τὸν Θεμιστοκλέα καὶ τὰς ἑαυτοῦ ταῖς ἐκείνου πράξεσιν ἀντιπαραβάλλοντος, ἔφη τῇ ἑορτῇ τὴν ὑστεραίαν ἐρίσαι λέγουσαν, ὡς ἐκείνη μὲν ἀσχολιῶν τε μεστὴ καὶ κοπώδης ἐστίν, ἐν αὐτῇ δὲ πάντες ἀπολαύουσι τῶν παρεσκευασμένων σχολάζοντες· τὴν δ’ ἑορτὴν πρὸς ταῦτ’ εἰπεῖν· ἀληθῆ λέγεις· ἀλλ’ ἐμοῦ μὴ γενομένης σὺ οὐκ ἂν ἦσθα· κἀμοῦ τοίνυν, ἔφη, τότε μὴ γενομένου, ποῦ ἂν ἦτε νῦν ὑμεῖς; τὸν δὲ υἱὸν ἐντρυφῶντα τῇ μητρὶ καὶ δι’ ἐκείνην αὐτῷ σκώπτων ἔλεγε πλεῖστον τῶν Ἑλλήνων δύνασθαι· τοῖς μὲν γὰρ Ἕλλησιν ἐπιτάττειν Ἀθηναίους, Ἀθηναίοις δ’ αὐτόν, αὐτῷ δὲ τὴν ἐκείνου μητέρα, τῇ μητρὶ δ’ ἐκεῖνον. ἴδιος δέ τις ἐν πᾶσι βουλόμενος εἶναι χωρίον μὲν πιπράσκων ἐκέλευε κηρύττειν, ὅτι καὶ γείτονα χρηστὸν ἔχει· τῶν δὲ μνωμένων αὐτοῦ τὴν θυγατέρα τὸν ἐπιεικῆ τοῦ πλουσίου προκρίνας ἔφη ζητεῖν ἄνδρα χρημάτων δεόμενον μᾶλλον ἢ χρήματα ἀνδρός. ἐν μὲν οὖν τοῖς ἀποφθέγμασι τοιοῦτός τις ἦν.", "st": "Them. 18.4"}, {"sp": "N", "t": "γενόμενος δ’ ἀπὸ τῶν πράξεων ἐκείνων εὐθὺς ἐπεχείρει τὴν πόλιν ἀνοικοδομεῖν καὶ τειχίζειν, ὡς μὲν ἱστορεῖ Θεόπομπος, χρήμασι πείσας μὴ ἐναντιωθῆναι τοὺς ἐφόρους, ὡς δ’ οἱ πλεῖστοι, παρακρουσάμενος. ἧκε μὲν γὰρ εἰς Σπάρτην ὄνομα πρεσβείας ἐπιγραψάμενος· ἐγκαλούντων δὲ τῶν Σπαρτιατῶν, ὅτι τειχίζουσι τὸ ἄστυ, καὶ Πολυάρχου κατηγοροῦντος ἐπίτηδες ἐξ Αἰγίνης ἀποσταλέντος, ἠρνεῖτο καὶ πέμπειν ἐκέλευεν εἰς Ἀθήνας τοὺς κατοψομένους, ἅμα μὲν ἐμβάλλων τῷ τειχισμῷ χρόνον ἐκ τῆς διατριβῆς, ἅμα δὲ βουλόμενος ἀντ’ αὐτοῦ τοὺς πεμπομένους ὑπάρχειν τοῖς Ἀθηναίοις. ὃ καὶ συνέβη· γνόντες γὰρ οἱ Λακεδαιμόνιοι τὸ ἀληθὲς οὐκ ἠδίκησαν αὐτόν, ἀλλ’ ἀδήλως χαλεπαίνοντες ἀπέπεμψαν.", "st": "Them. 19.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου τὸν Πειραιᾶ κατεσκεύαζε, τὴν τῶν λιμένων εὐφυΐαν κατανοήσας καὶ τὴν πόλιν ὅλην ἁρμοττόμενος πρὸς τὴν θάλατταν, καὶ τρόπον τινὰ τοῖς παλαιοῖς βασιλεῦσι τῶν Ἀθηναίων ἀντιπολιτευόμενος. ἐκεῖνοι μὲν γάρ, ὡς λέγεται, πραγματευόμενοι τοὺς πολίτας ἀποσπάσαι τῆς θαλάττης καὶ συνεθίσαι ζῆν μὴ πλέοντας, ἀλλὰ τὴν χώραν φυτεύοντας, τὸν περὶ τῆς Ἀθηνᾶς διέδοσαν λόγον, ὡς ἐρίσαντα περὶ τῆς χώρας τὸν Ποσειδῶ δείξασα τὴν μορίαν τοῖς δικασταῖς ἐνίκησε. Θεμιστοκλῆς δ’ οὐχ, ὡς Ἀριστοφάνης ὁ κωμικὸς λέγει, τῇ πόλει τὸν Πειραιᾶ προσέμαξεν, ἀλλὰ τὴν πόλιν ἐξῆψε τοῦ Πειραιῶς καὶ τὴν γῆν τῆς θαλάττης· ὅθεν καὶ τὸν δῆμον ηὔξησε κατὰ τῶν ἀρίστων καὶ θράσους ἐνέπλησεν, εἰς ναύτας καὶ κελευστὰς καὶ κυβερνήτας τῆς δυνάμεως ἀφικομένης. διὸ καὶ τὸ βῆμα τὸ ἐν Πνυκὶ πεποιημένον ὥστ’ ἀποβλέπειν πρὸς τὴν θάλασσαν ὕστερον οἱ τριάκοντα πρὸς τὴν χώραν ἀπέστρεψαν, οἰόμενοι τὴν μὲν κατὰ θάλατταν ἀρχὴν γένεσιν εἶναι δημοκρατίας, ὀλιγαρχίᾳ δ’ ἧττον δυσχεραίνειν τοὺς γεωργοῦντας.", "st": "Them. 19.3"}, {"sp": "N", "t": "Θεμιστοκλῆς δὲ καὶ μεῖζόν τι περὶ τῆς ναυτικῆς διενοήθη δυνάμεως. ἐπεὶ γὰρ ὁ τῶν Ἑλλήνων στόλος ἀπηλλαγμένου Ξέρξου κατῆρεν εἰς Παγασὰς καὶ διεχείμαζε, δημηγορῶν ἐν τοῖς Ἀθηναίοις ἔφη τινα πρᾶξιν ἔχειν ὠφέλιμον μὲν αὐτοῖς καὶ σωτήριον, ἀπόρρητον δὲ πρὸς τοὺς πολλούς. τῶν δ’ Ἀθηναίων Ἀριστείδῃ φράσαι μόνῳ κελευόντων, κἂν ἐκεῖνος δοκιμάσῃ περαίνειν, ὁ μὲν Θεμιστοκλῆς ἔφρασε τῷ Ἀριστείδῃ, τὸ νεώριον ἐμπρῆσαι διανοεῖσθαι τῶν Ἑλλήνων· ὁ δ’ Ἀριστείδης εἰς τὸν δῆμον παρελθὼν ἔφη τῆς πράξεως, ἣν διανοεῖται πράττειν ὁ Θεμιστοκλῆς, μηδεμίαν εἶναι μήτε λυσιτελεστέραν μήτ’ ἀδικωτέραν. οἱ μὲν οὖν Ἀθηναῖοι διὰ ταῦτα παύσασθαι τῷ Θεμιστοκλεῖ προσέταξαν.", "st": "Them. 20.1"}, {"sp": "N", "t": "ἐν δὲ τοῖς Ἀμφικτυονικοῖς συνεδρίοις τῶν Λακεδαιμονίων εἰσηγουμένων, ὅπως ἀπείργωνται τῆς Ἀμφικτυονίας αἱ μὴ συμμαχήσασαι κατὰ τοῦ Μήδου πόλεις, φοβηθείς, μὴ Θετταλοὺς καὶ Ἀργείους, ἔτι δὲ Θηβαίους ἐκβαλόντες τοῦ συνεδρίου παντελῶς ἐπικρατήσωσι τῶν ψήφων καὶ γένηται τὸ δοκοῦν ἐκείνοις, συνεῖπε ταῖς πόλεσι καὶ μετέθηκε τὰς γνώμας τῶν πυλαγόρων, διδάξας, ὡς τριάκοντα καὶ μία μόναι πόλεις εἰσὶν αἱ μετασχοῦσαι τοῦ πολέμου, καὶ τούτων αἱ πλείους παντάπασι μικραί· δεινὸν οὖν, εἰ τῆς ἄλλης Ἑλλάδος ἐκσπόνδου γενομένης ἐπὶ ταῖς μεγίσταις δυσὶν ἢ τρισὶ πόλεσιν ἔσται τὸ συνέδριον. ἐκ τούτου μὲν οὖν μάλιστα τοῖς Λακεδαιμονίοις προσέκρουσε· διὸ καὶ τὸν Κίμωνα προῆγον ταῖς τιμαῖς, ἀντίπαλον ἐν τῇ πολιτείᾳ τῷ Θεμιστοκλεῖ καθιστάντες.", "st": "Them. 20.3"}, {"sp": "N", "t": "ἦν δὲ καὶ τοῖς συμμάχοις ἐπαχθὴς περιπλέων τε τὰς νήσους καὶ χρηματιζόμενος ἀπ’ αὐτῶν· οἷα καὶ πρὸς Ἀνδρίους ἀργύριον αἰτοῦντά φησιν αὐτὸν Ἡρόδοτος εἰπεῖν τε καὶ ἀκοῦσαι. δύο γὰρ ἥκειν ἔφη θεοὺς κομίζων, Πειθὼ καὶ Βίαν· οἱ δ’ ἔφασαν εἶναι καὶ παρ’ αὐτοῖς θεοὺς μεγάλους δύο, Πενίαν καὶ Ἀπορίαν, ὑφ’ ὧν κωλύεσθαι δοῦναι χρήματα ἐκείνῳ.", "st": "Them. 21.1"}, {"sp": "N", "t": "Τιμοκρέων δ’ ὁ Ῥόδιος μελοποιὸς ἐν ᾄσματι καθάπτεται πικρότερον τοῦ Θεμιστοκλέους, ὡς ἄλλους μὲν ἐπὶ χρήμασι φυγάδας διαπραξαμένου κατελθεῖν, αὐτὸν δὲ ξένον ὄντα καὶ φίλον προεμένου δι’ ἀργύριον. λέγει δ’ οὕτως·", "st": "Them. 21.2"}, {"sp": "N", "t": "ἀλλ’ εἰ τύγε Παυσανίαν ἢ καὶ τύγε Ξάνθιππον αἰνεῖς<br>ἢ τύγε Λευτυχίδαν, ἐγὼ δ’ Ἀριστείδαν ἐπαινέω<br>ἄνδρ’ ἱερᾶν ἀπ’ Ἀθανᾶν<br>ἐλθεῖν ἕνα λῷστον· ἐπεὶ Θεμιστοκλῆ ἤχθαρε Λατώ,", "st": "Them. 21.2b"}, {"sp": "N", "t": "ψεύσταν, ἄδικον, προδόταν, ὃς Τιμοκρέοντα ξεῖνον ἐόντ’<br>ἀργυρίοις σκυβαλικτοῖσι πεισθεὶς οὐ κατᾶγεν<br>εἰς πάτραν Ἰαλυσόν,<br>λαβὼν δὲ τρί’ ἀργυρίου τάλαντ’ ἔβα πλέων εἰς ὄλεθρον,<br>τοὺς μὲν κατάγων ἀδίκως, τοὺς δ’ ἐκδιώκων, τοὺς δὲ καίνων,", "st": "Them. 21.3"}, {"sp": "N", "t": "ἀργυρίων ὑπόπλεως, Ἰσθμοῖ δ’ ἐπανδόκευε γελοίως ψυχρὰ κρέα παρέχων·", "st": "Them. 21.3b"}, {"sp": "N", "t": "οἱ δ’ ἤσθιον κηὔχοντο μὴ ὥραν Θεμιστοκλεῦς γενέσθαι.", "st": "Them. 21.3c"}, {"sp": "N", "t": "πολὺ δ’ ἀσελγεστέρᾳ καὶ ἀναπεπταμένῃ μᾶλλον εἰς τὸν Θεμιστοκλέα βλασφημίᾳ κέχρηται μετὰ τὴν φυγὴν αὐτοῦ καὶ τὴν καταδίκην ὁ Τιμοκρέων ᾆσμα ποιήσας, οὗ ἐστιν ἀρχή·", "st": "Them. 21.4"}, {"sp": "N", "t": "Μοῦσα τοῦδε τοῦ μέλεος<br>κλέος ἀν’ Ἕλλανας τίθει,<br>ὡς ἐοικὸς καὶ δίκαιον.", "st": "Them. 21.4b"}, {"sp": "N", "t": "λέγεται δ’ ὁ Τιμοκρέων ἐπὶ μηδισμῷ φυγεῖν συγκαταψηφισαμένου τοῦ Θεμιστοκλέους. ὡς οὖν ὁ Θεμιστοκλῆς αἰτίαν ἔσχε μηδίζειν, ταῦτ’ ἐποίησεν εἰς αὐτόν·", "st": "Them. 21.5"}, {"sp": "N", "t": "οὐκ ἄρα Τιμοκρέων μοῦνος Μήδοισιν ὁρκιατομεῖ,<br>ἀλλ’ ἐντὶ κἆλλοι δὴ πονηροί· οὐκ ἐγὼ μόνα κόλουρις·<br>ἐντὶ καὶ ἄλλαι ἀλώπεκες.", "st": "Them. 21.5b"}, {"sp": "N", "t": "ἤδη δὲ καὶ τῶν πολιτῶν διὰ τὸ φθονεῖν ἡδέως τὰς διαβολὰς προσιεμένων ἠναγκάζετο λυπηρὸς εἶναι τῶν αὑτοῦ πράξεων πολλάκις ἐν τῷ δήμῳ μνημονεύων· καὶ πρὸς τοὺς δυσχεραίνοντας τί κοπιᾶτε, εἶπεν, ὑπὸ τῶν αὐτῶν πολλάκις εὖ πάσχοντες; ἠνίασε δὲ τοὺς πολλοὺς καὶ τὸ τῆς Ἀρτέμιδος ἱερὸν εἱσάμενος, ἣν Ἀριστοβούλην μὲν προσηγόρευσεν, ὡς ἄριστα τῇ πόλει καὶ τοῖς Ἕλλησι βουλευσάμενος, πλησίον δὲ τῆς οἰκίας κατεσκεύασεν ἐν Μελίτῃ τὸ ἱερὸν, οὗ νῦν τὰ σώματα τῶν θανατουμένων οἱ δήμιοι προβάλλουσι καὶ τὰ ἱμάτια καὶ τοὺς βρόχους τῶν ἀπαγχομένων καὶ καθαιρεθέντων ἐκφέρουσιν. ἔκειτο δὲ καὶ τοῦ Θεμιστοκλέους εἰκόνιον ἐν τῷ ναῷ τῆς Ἀριστοβούλης ἔτι καθ’ ἡμᾶς· καὶ φαίνεταί τις οὐ τὴν ψυχὴν μόνον, ἀλλὰ καὶ τὴν ὄψιν ἡρωϊκὸς γενόμενος.", "st": "Them. 22.1"}, {"sp": "N", "t": "τὸν μὲν οὖν ἐξοστρακισμὸν ἐποιήσαντο κατ’ αὐτοῦ κολούοντες τὸ ἀξίωμα καὶ τὴν ὑπεροχήν, ὥσπερ εἰώθεσαν ἐπὶ πάντων, οὓς ᾤοντο τῇ δυνάμει βαρεῖς καὶ πρὸς ἰσότητα δημοκρατικὴν ἀσυμμέτρους εἶναι. κόλασις γὰρ οὐκ ἦν ὁ ἐξοστρακισμός, ἀλλὰ παραμυθία φθόνου καὶ κουφισμὸς ἡδομένου τῷ ταπεινοῦν τοὺς ὑπερέχοντας καὶ τὴν δυσμένειαν εἰς ταύτην τὴν ἀτιμίαν ἀποπνέοντος.", "st": "Them. 22.3"}, {"sp": "N", "t": "ἐκπεσόντος δὲ τῆς πόλεως αὐτοῦ καὶ διατρίβοντος ἐν Ἄργει τὰ περὶ Παυσανίαν συμπεσόντα κατ’ ἐκείνου παρέσχε τοῖς ἐχθροῖς ἀφορμάς. ὁ δὲ γραψάμενος αὐτὸν προδοσίας Λεωβώτης ἦν ὁ Ἀλκμαίωνος Ἀγραυλῆθεν, ἅμα συνεπαιτιωμένων τῶν Σπαρτιατῶν. ὁ γὰρ Παυσανίας πράττων ἐκεῖνα δὴ τὰ περὶ τὴν προδοσίαν πρότερον μὲν ἀπεκρύπτετο τὸν Θεμιστοκλέα, καίπερ ὄντα φίλον· ὡς δ’ εἶδεν ἐκπεπτωκότα τῆς πολιτείας καὶ φέροντα χαλεπῶς ἐθάρσησεν ἐπὶ τὴν κοινωνίαν τῶν πραττομένων παρακαλεῖν, γράμματα τοῦ βασιλέως ἐπιδεικνύμενος αὐτῷ καὶ παροξύνων ἐπὶ τοὺς Ἕλληνας ὡς πονηροὺς καὶ ἀχαρίστους. ὁ δὲ τὴν μὲν δέησιν ἀπετρίψατο τοῦ Παυσανίου καὶ τὴν κοινωνίαν ὅλως ἀπείπατο, πρὸς οὐδένα δὲ τοὺς λόγους ἐξήνεγκεν οὐδὲ κατεμήνυσε τὴν πρᾶξιν, εἴτε παύσεσθαι προσδοκῶν αὐτόν, εἴτ’ ἄλλως καταφανῆ γενήσεσθαι σὺν οὐδενὶ λογισμῷ πραγμάτων ἀτόπων καὶ παραβόλων ὀρεγόμενον.", "st": "Them. 23.1"}, {"sp": "N", "t": "οὕτω δὴ τοῦ Παυσανίου θανατωθέντος ἐπιστολαί τινες ἀνευρεθεῖσαι καὶ γράμματα περὶ τούτων εἰς ὑποψίαν ἐνέβαλον τὸν Θεμιστοκλέα· καὶ κατεβόων μὲν αὐτοῦ Λακεδαιμόνιοι, κατηγόρουν δ’ οἱ φθονοῦντες τῶν πολιτῶν, οὐ παρόντος, ἀλλὰ διὰ γραμμάτων ἀπολογουμένου μάλιστα ταῖς προτέραις κατηγορίαις. διαβαλλόμενος γὰρ ὑπὸ τῶν ἐχθρῶν πρὸς τοὺς πολίτας ἔγραφεν, ὡς ἄρχειν μὲν ἀεὶ ζητῶν, ἄρχεσθαι δὲ μὴ πεφυκὼς μηδὲ βουλόμενος, οὐκ ἄν ποτε βαρβάροις αὑτὸν οὐδὲ πολεμίοις ἀποδόσθαι μετὰ τῆς Ἑλλάδος. οὐ μὴν ἀλλὰ συμπεισθεὶς ὑπὸ τῶν κατηγορούντων ὁ δῆμος ἔπεμψεν ἄνδρας, οἷς εἴρητο συλλαμβάνειν καὶ ἀνάγειν αὐτὸν κριθησόμενον ἐν τοῖς Ἕλλησιν.", "st": "Them. 23.3"}, {"sp": "N", "t": "προαισθόμενος δ’ ἐκεῖνος εἰς Κέρκυραν διεπέρασεν, οὔσης αὐτῷ πρὸς τὴν πόλιν εὐεργεσίας. γενόμενος γὰρ αὐτῶν κριτὴς πρὸς Κορινθίους ἐχόντων διαφοράν, ἔλυσε τὴν ἔχθραν εἴκοσι τάλαντα κρίνας τοὺς Κορινθίους καταβαλεῖν καὶ Λευκάδα κοινῇ νέμειν ἀμφοτέρων ἄποικον. ἐκεῖθεν δ’ εἰς Ἤπειρον ἔφυγε· καὶ διωκόμενος ὑπὸ τῶν Ἀθηναίων καὶ τῶν Λακεδαιμονίων ἔρριψεν αὑτὸν εἰς ἐλπίδας χαλεπὰς καὶ ἀπόρους καταφυγὼν πρὸς Ἄδμητον, ὃς βασιλεὺς μὲν ἦν Μολοττῶν, δεηθεὶς δέ τι τῶν Ἀθηναίων καὶ προπηλακισθεὶς ὑπὸ τοῦ Θεμιστοκλέους, ὅτ’ ἤκμαζεν ἐν τῇ πολιτείᾳ, δι’ ὀργῆς εἶχεν αὐτὸν ἀεὶ καὶ δῆλος ἦν, εἰ λάβοι, τιμωρησόμενος. ἐν δὲ τῇ τότε τύχῃ μᾶλλον ὁ Θεμιστοκλῆς φοβηθεὶς συγγενῆ καὶ πρόσφατον φθόνον ὀργῆς παλαιᾶς καὶ βασιλικῆς, ταύτῃ φέρων ὑπέθηκεν ἑαυτόν, ἱκέτης τοῦ Ἀδμήτου καταστὰς ἴδιόν τινα καὶ παρηλλαγμένον τρόπον. ἔχων γὰρ αὐτοῦ τὸν υἱὸν ὄντα παῖδα πρὸς τὴν ἑστίαν προσέπεσε, ταύτην μεγίστην καὶ μόνην σχεδὸν ἀναντίρρητον ἡγουμένων ἱκεσίαν τῶν Μολοσσῶν. ἔνιοι μὲν οὖν Φθίαν τὴν γυναῖκα τοῦ βασιλέως λέγουσιν ὑποθέσθαι τῷ Θεμιστοκλεῖ τὸ ἱκέτευμα τοῦτο καὶ τὸν υἱὸν ἐπὶ τὴν ἑστίαν καθίσαι μετ’ αὐτοῦ· τινὲς δ’ αὐτὸν τὸν Ἄδμητον, ὡς ἀφοσιώσαιτο πρὸς τοὺς διώκοντας τὴν ἀνάγκην, δι’ ἣν οὐκ ἐκδίδωσι τὸν ἄνδρα, διαθεῖναι καὶ συντραγῳδῆσαι τὴν ἱκεσίαν.", "st": "Them. 24.1"}, {"sp": "N", "t": "ἐκεῖ δ’ αὐτῷ τὴν γυναῖκα καὶ τοὺς παῖδας ἐκκλέψας ἐκ τῶν Ἀθηνῶν Ἐπικράτης ὁ Ἀχαρνεὺς ἀπέστειλεν· ὃν ἐπὶ τούτῳ Κίμων ὕστερον κρίνας ἐθανάτωσεν, ὡς ἱστορεῖ Στησίμβροτος. εἶτ’ οὐκ οἶδ’ ὅπως ἐπιλαθόμενος τούτων ἢ τὸν Θεμιστοκλέα ποιῶν ἐπιλαθόμενον πλεῦσαί φησιν εἰς Σικελίαν καὶ παρ’ Ἱέρωνος αἰτεῖν τοῦ τυράννου τὴν θυγατέρα πρὸς γάμον, ὑπισχνούμενον αὐτῷ τοὺς Ἕλληνας ὑπηκόους ποιήσειν· ἀποτριψαμένου δὲ τοῦ Ἱέρωνος, οὕτως εἰς τὴν Ἀσίαν ἀπᾶραι.", "st": "Them. 24.4"}, {"sp": "N", "t": "ταῦτα δ’ οὐκ εἰκός ἐστιν οὕτω γενέσθαι. Θεόφραστος γὰρ ἐν τοῖς Περὶ βασιλείας ἱστορεῖ τὸν Θεμιστοκλέα πέμψαντος εἰς Ὀλυμπίαν Ἱέρωνος ἵππους ἀγωνιστὰς καὶ σκηνήν τινα κατεσκευασμένην πολυτελῶς στήσαντος, εἰπεῖν ἐν τοῖς Ἕλλησι λόγον, ὡς χρὴ τὴν σκηνὴν διαρπάσαι τοῦ τυράννου καὶ κωλῦσαι τοὺς ἵππους ἀγωνίσασθαι. Θουκυδίδης δέ φησι καὶ πλεῦσαι αὐτὸν ἐπὶ τὴν ἑτέραν καταβάντα θάλασσαν ἀπὸ Πύδνης, οὐδενὸς εἰδότος ὅστις εἴη τῶν πλεόντων, μέχρι οὗ πνεύματι τῆς ὁλκάδος εἰς Νάξον καταφερομένης ὑπὸ Ἀθηναίων πολιορκουμένην τότε φοβηθεὶς ἀναδείξειεν ἑαυτὸν τῷ τε ναυκλήρῳ καὶ τῷ κυβερνήτῃ, καὶ τὰ μὲν δεόμενος, τὰ δ’ ἀπειλῶν καὶ λέγων, ὅτι κατηγορήσοι καὶ καταψεύσοιτο πρὸς τοὺς Ἀθηναίους, ὡς οὐκ ἀγνοοῦντες, ἀλλὰ χρήμασι πεισθέντες ἐξ ἀρχῆς, ἀναλάβοιεν αὐτόν, οὕτως ἀναγκάσειε παραπλεῦσαι καὶ λαβέσθαι τῆς Ἀσίας. τῶν δὲ χρημάτων αὐτῷ πολλὰ μὲν ὑπεκκλαπέντα διὰ τῶν φίλων εἰς Ἀσίαν ἔπλει· τῶν δὲ φανερῶν γενομένων καὶ συναχθέντων εἰς τὸ δημόσιον Θεόπομπος μὲν ἑκατὸν τάλαντα, Θεόφραστος δὲ ὀγδοήκοντά φησι γενέσθαι τὸ πλῆθος, οὐδὲ τριῶν ἄξια ταλάντων κεκτημένου τοῦ Θεμιστοκλέους πρὶν ἅπτεσθαι τῆς πολιτείας.", "st": "Them. 25.1"}, {"sp": "N", "t": "ἐπεὶ δὲ κατέπλευσεν εἰς Κύμην καὶ πολλοὺς ᾔσθετο τῶν ἐπὶ θαλάττῃ παραφυλάττοντας αὐτὸν λαβεῖν, μάλιστα δὲ τοὺς περὶ Ἐργοτέλη καὶ Πυθόδωρον (ἦν γὰρ ἡ θήρα λυσιτελὴς τοῖς τὸ κερδαίνειν ἀπὸ παντὸς ἀγαπῶσι, διακοσίων ἐπικεκηρυγμένων αὐτῷ ταλάντων ὑπὸ τοῦ βασιλέως), ἔφυγεν εἰς Αἰγάς, Αἰολικὸν πολισμάτιον, ὑπὸ πάντων ἀγνοούμενος πλὴν τοῦ ξένου Νικογένους, ὃς Αἰολέων πλείστην οὐσίαν ἐκέκτητο καὶ τοῖς ἄνω δυνατοῖς γνώριμος ὑπῆρχε. παρὰ τούτῳ κρυπτόμενος ἡμέρας ὀλίγας διέτριψεν· εἶτα μετὰ τὸ δεῖπνον ἐκ θυσίας τινος Ὄλβιος ὁ τῶν τέκνων τοῦ Νικογένους παιδαγωγὸς ἔκφρων γενόμενος καὶ θεοφόρητος ἀνεφώνησεν ἐν μέτρῳ ταυτί·", "st": "Them. 26.1"}, {"sp": "N", "t": "νυκτὶ φωνήν, νυκτὶ βουλήν, νυκτὶ τὴν νίκην δίδου.", "st": "Them. 26.1b"}, {"sp": "N", "t": "Καὶ μετὰ ταῦτα κοιμηθεὶς ὁ Θεμιστοκλῆς ὄναρ ἔδοξεν ἰδεῖν δράκοντα κατὰ τῆς γαστρὸς αὐτοῦ περιελιττόμενον καὶ προσανέρποντα τῷ τραχήλῳ· γενόμενον δ’ ἀετόν, ὡς ἥψατο τοῦ προσώπου, περιβαλόντα τὰς πτέρυγας ἐξᾶραι καὶ κομίζειν πολλὴν ὁδόν, εἶτα χρυσοῦ τινὸς κηρυκείου φανέντος, ἐπὶ τούτου στῆσαι βεβαίως αὐτὸν ἀμηχάνου δείματος καὶ ταραχῆς ἀπαλλαγέντα.", "st": "Them. 26.3"}, {"sp": "N", "t": "πέμπεται δ’ οὖν ὑπὸ τοῦ Νικογένους μηχανησαμένου τι τοιόνδε. τοῦ βαρβαρικοῦ γένους τὸ πολὺ καὶ μάλιστα τὸ Περσικὸν εἰς ζηλοτυπίαν τὴν περὶ τὰς γυναῖκας ἄγριον φύσει καὶ χαλεπόν ἐστιν. οὐ γὰρ μόνον τὰς γαμετάς, ἀλλὰ καὶ τὰς ἀργυρωνήτους καὶ παλλακευομένας ἰσχυρῶς παραφυλάττουσιν, ὡς ὑπὸ μηδενὸς ὁρᾶσθαι τῶν ἐκτός, ἀλλ’ οἴκοι μὲν διαιτᾶσθαι κατακεκλεισμένας, ἐν δὲ ταῖς ὁδοιπορίαις ὑπὸ σκηνὰς κύκλῳ περιπεφραγμένας ἐπὶ τῶν ἁρμαμαξῶν ὀχεῖσθαι τοιαύτης τῷ Θεμιστοκλεῖ κατασκευασθείσης ἀπήνης καταδὺς ἐκομίζετο, τῶν περὶ αὐτὸν ἀεὶ τοῖς ἐντυγχάνουσι καὶ πυνθανομένοις λεγόντων, ὅτι γύναιον Ἑλληνικὸν ἄγουσιν ἀπ’ Ἰωνίας πρός τινα τῶν ἐπὶ θύραις βασιλέως.", "st": "Them. 26.4"}, {"sp": "N", "t": "Θουκυδίδης μὲν οὖν καὶ Χάρων ὁ Λαμψακηνὸς ἱστοροῦσι τεθνηκότος Ξέρξου πρὸς τὸν υἱὸν αὐτοῦ τῷ Θεμιστοκλεῖ γενέσθαι τὴν ἔντευξιν· Ἔφορος δὲ καὶ Δείνων καὶ Κλείταρχος καὶ Ἡρακλείδης, ἔτι δ’ ἄλλοι πλείονες, πρὸς αὐτὸν ἀφικέσθαι τὸν Ξέρξην. τοῖς δὲ χρονικοῖς δοκεῖ μᾶλλον ὁ Θουκυδίδης συμφέρεσθαι, καίπερ οὐδ’ αὐτοῖς ἀτρέμα συνταττομένοις. ὁ δ’ οὖν Θεμιστοκλῆς γενόμενος παρ’ αὐτὸ τὸ δεινὸν ἐντυγχάνει πρῶτον Ἀρταβάνῳ τῷ χιλιάρχῳ λέγων, Ἕλλην μὲν εἶναι, βούλεσθαι δ’ ἐντυχεῖν βασιλεῖ περὶ μεγίστων πραγμάτων καὶ πρὸς ἃ τυγχάνει μάλιστα σπουδάζων ἐκεῖνος. ὁ δέ φησιν· ὦ ξένε, νόμοι διαφέρουσιν ἀνθρώπων· ἄλλα δ’ ἄλλοις καλά· καλὸν δὲ πᾶσι τὰ οἰκεῖα κοσμεῖν καὶ σώζειν. ὑμᾶς μὲν οὖν ἐλευθερίαν μάλιστα θαυμάζειν καὶ ἰσότητα λόγος· ἡμῖν δὲ πολλῶν νόμων καὶ καλῶν ὄντων κάλλιστος οὗτός ἐστι, τιμᾶν βασιλέα, καὶ προσκυνεῖν ὡς εἰκόνα θεοῦ τοῦ τὰ πάντα σώζοντος. εἰ μὲν οὖν ἐπαινῶν τὰ ἡμέτερα προσκυνήσεις, ἔστι σοι καὶ θεάσασθαι βασιλέα καὶ προσειπεῖν· εἰ δ’ ἄλλο τι φρονεῖς, ἀγγέλοις ἑτέροις χρήσῃ πρὸς αὐτόν. βασιλεῖ γὰρ οὐ πάτριον ἀνδρὸς ἀκροᾶσθαι μὴ προσκυνήσαντος. ταῦτα ὁ Θεμιστοκλῆς ἀκούσας λέγει πρὸς αὐτόν· ἀλλ’ ἔγωγε τὴν βασιλέως, ὦ Ἀρτάβανε, φήμην καὶ δύναμιν αὐξήσων ἀφῖγμαι, καὶ αὐτός τε πείσομαι τοῖς ὑμετέροις νόμοις, ἐπεὶ θεῷ τῷ μεγαλύνοντι Πέρσας οὕτω δοκεῖ, καὶ δι’ ἐμὲ πλείονες τῶν νῦν βασιλέα προσκυνήσουσιν. ὥστε τοῦτο μηδὲν ἐμποδὼν ἔστω τοῖς λόγοις, οὓς βούλομαι πρὸς ἐκεῖνον εἰπεῖν. τίνα δ’, εἶπεν ὁ Ἀρτάβανος, Ἑλλήνων ἀφῖχθαί σε φῶμεν; οὐ γὰρ ἰδιώτῃ τὴν γνώμην ἔοικας. καὶ ὁ Θεμιστοκλῆς· τοῦτ’ οὐκέτ’ ἄν, ἔφη, πύθοιτό τις, Ἀρτάβανε, πρότερος βασιλέως.", "st": "Them. 27.1"}, {"sp": "N", "t": "οὕτω μὲν ὁ Φανίας φησίν. ὁ δ’ Ἐρατοσθένης ἐν τοῖς Περὶ πλούτου προσιστόρησε, διὰ γυναικὸς Ἐρετρικῆς, ἣν ὁ χιλίαρχος εἶχε, τῷ Θεμιστοκλεῖ τὴν πρὸς αὐτὸν ἔντευξιν γενέσθαι καὶ σύστασιν.", "st": "Them. 27.1b"}, {"sp": "N", "t": "ἐπεὶ δ’ οὖν εἰσήχθη πρὸς βασιλέα καὶ προσκυνήσας ἔστη σιωπῇ, προστάξαντος τῷ ἑρμηνεῖ τοῦ βασιλέως ἐρωτῆσαι, τίς ἐστι, καὶ τοῦ ἑρμηνέως ἐρωτήσαντος, εἶπεν· ἥκω σοι, βασιλεῦ, Θεμιστοκλῆς ὁ Ἀθηναῖος ἐγὼ φυγὰς ὑφ’ Ἑλλήνων διωχθείς, ᾧ πολλὰ μὲν ὀφείλουσι Πέρσαι κακά, πλείω δὲ ἀγαθὰ κωλύσαντι τὴν δίωξιν, ὅτε τῆς Ἑλλάδος ἐν ἀσφαλεῖ γενομένης παρέσχε τὰ οἴκοι σωζόμενα χαρίσασθαί τι καὶ ὑμῖν. ἐμοὶ μὲν οὖν πάντα πρέποντα ταῖς παρούσαις συμφοραῖς ἐστι, καὶ παρεσκευασμένος ἀφῖγμαι δέξασθαί τε χάριν εὐμενῶς διαλλαττομένου καὶ παραιτεῖσθαι μνησικακοῦντος ὀργῆν· σὺ δὲ τοὺς ἐμοὺς ἐχθροὺς μάρτυρας θέμενος ὧν εὐεργέτησα Πέρσας, νῦν ἀπόχρησαι ταῖς ἐμαῖς τύχαις πρὸς ἐπίδειξιν ἀρετῆς μᾶλλον ἢ πρὸς ἀποπλήρωσιν ὀργῆς. σώσεις μὲν γὰρ ἱκέτην σόν, ἀπολεῖς δ’ Ἑλλήνων πολέμιον γενόμενον. ταῦτ’ εἰπὼν ὁ Θεμιστοκλῆς ἐπεθείασε τῷ λόγῳ προσδιελθὼν τὴν ὄψιν, ἣν εἶδεν ἐν Νικογένους, καὶ τὸ μάντευμα τοῦ Δωδωναίου Διός, ὡς κελευσθεὶς πρὸς τὸν ὁμώνυμον τοῦ θεοῦ βαδίζειν συμφρονήσειε πρὸς ἐκεῖνον ἀναπέμπεσθαι· μεγάλους γὰρ ἀμφοτέρους εἶναί τε καὶ λέγεσθαι βασιλέας.", "st": "Them. 28.1"}, {"sp": "N", "t": "ἀκούσας δ’ ὁ Πέρσης, ἐκείνῳ μὲν οὐδὲν ἀπεκρίνατο, καίπερ θαυμάσας τὸ φρόνημα καὶ τὴν τόλμαν αὐτοῦ· μακαρίσας δὲ πρὸς τοὺς φίλους ἑαυτόν, ὡς ἐπ’ εὐτυχίᾳ μεγίστῃ, καὶ κατευξάμενος ἀεὶ τοῖς πολεμίοις τοιαύτας φρένας διδόναι τὸν Ἀριμάνιον, ὅπως ἐλαύνωσι τοὺς ἀρίστους ἐξ ἑαυτῶν, θῦσαί τε τοῖς θεοῖς λέγεται καὶ πρὸς πόσιν εὐθὺς τραπέσθαι καὶ νύκτωρ ὑπὸ χαρᾶς διὰ μέσων τῶν ὕπνων βοῆσαι τρίς· ἔχω Θεμιστοκλέα τὸν Ἀθηναῖον.", "st": "Them. 28.4"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ συγκαλέσας τοὺς φίλους εἰσῆγεν αὐτὸν οὐδὲν ἐλπίζοντα χρηστὸν ἐξ ὧν ἑώρα τοὺς ἐπὶ θύραις, ὡς ἐπύθοντο τοὔνομα παρόντος αὐτοῦ, χαλεπῶς διακειμένους καὶ κακῶς λέγοντας. ἔτι δὲ Ῥωξάνης ὁ χιλίαρχος, ὡς κατ’ αὐτὸν ἦν ὁ Θεμιστοκλῆς προσιών, καθημένου βασιλέως καὶ τῶν ἄλλων σιωπώντων, ἀτρέμα στενάξας εἶπεν· ὄφις Ἕλλην ὁ ποικίλος, ὁ βασιλέως σε δαίμων δεῦρο ἤγαγεν. οὐ μὴν ἀλλ’ εἰς ὄψιν ἐλθόντος αὐτοῦ καὶ πάλιν προσκυνήσαντος, ἀσπασάμενος καὶ προσειπὼν φιλοφρόνως ὁ βασιλεύς, ἤδη μὲν ἔφησεν αὐτῷ διακόσια τάλαντα ὀφείλειν· κομίσαντα γὰρ αὑτὸν ἀπολήψεσθαι δικαίως τὸ ἐπικηρυχθὲν τῷ ἀγαγόντι· πολλῷ δὲ πλείω τούτων ὑπισχνεῖτο καὶ παρεθάρρυνε καὶ λέγειν ἐδίδου περὶ τῶν Ἑλληνικῶν, ἃ βούλοιτο, παρρησιαζόμενον.", "st": "Them. 29.1"}, {"sp": "N", "t": "ὁ δὲ Θεμιστοκλῆς ἀπεκρίνατο, τὸν λόγον ἐοικέναι τοῦ ἀνθρώπου τοῖς ποικίλοις στρώμασιν· ὡς γὰρ ἐκεῖνα καὶ τοῦτον ἐκτεινόμενον μὲν ἐπιδείκνυσθαι τὰ εἴδη, συστελλόμενον δὲ κρύπτειν καὶ διαφθείρειν· ὅθεν αὐτῷ χρόνου δεῖν. ἐπεὶ δέ, ἡσθέντος τοῦ βασιλέως τῇ εἰκασίᾳ καὶ λαμβάνειν κελεύσαντος, ἐνιαυτὸν αἰτησάμενος καὶ τὴν Περσίδα γλῶτταν ἀποχρώντως ἐκμαθὼν ἐνετύγχανε βασιλεῖ δι’ αὑτοῦ, τοῖς μὲν ἐκτὸς δόξαν παρέσχε περὶ τῶν Ἑλληνικῶν πραγμάτων διειλέχθαι, πολλῶν δὲ καινοτομουμένων περὶ τὴν αὐλὴν καὶ τοὺς φίλους ὑπὸ τοῦ βασιλέως ἐν ἐκείνῳ τῷ καιρῷ, φθόνον ἔσχε παρὰ τοῖς δυνατοῖς, ὡς καὶ κατ’ ἐκείνων παρρησίᾳ χρήσασθαι πρὸς αὐτὸν ἀποτετολμηκώς. οὐδὲν γὰρ ἦσαν αἱ τιμαὶ ταῖς τῶν ἄλλων ἐοικυῖαι ξένων, ἀλλὰ καὶ κυνηγεσίων βασιλεῖ μετέσχε καὶ τῶν οἴκοι διατριβῶν, ὥστε καὶ μητρὶ τῇ βασιλέως εἰς ὄψιν ἐλθεῖν καὶ γενέσθαι συνήθης, διακοῦσαι δὲ καὶ τῶν μαγικῶν λόγων τοῦ βασιλέως κελεύσαντος. ἐπεὶ δὲ Δημάρατος ὁ Σπαρτιάτης αἰτήσασθαι δωρεὰν κελευσθεὶς ᾐτήσατο τὴν κίταριν, ὥσπερ οἱ βασιλεῖς, ἐπαράμενος εἰσελάσαι διὰ Σάρδεων, Μιθροπαύστης μὲν ἀνεψιὸς ὢν βασιλέως εἶπε τοῦ Δημαράτου τῆς τιάρας ἁψάμενος· αὕτη μὲν ἡ κίταρις οὐκ ἔχει ἐγκέφαλον, ὃν ἐπικαλύψει· σὺ δ’ οὐκ ἔσῃ Ζεὺς ἂν λάβῃς κεραυνόν· ἀπωσαμένου δὲ τὸν Δημάρατον ὀργῇ διὰ τὸ αἴτημα τοῦ βασιλέως καὶ δοκοῦντος ἀπαραιτήτως ἔχειν πρὸς αὐτόν, ὁ Θεμιστοκλῆς δεηθεὶς ἔπεισε καὶ διήλλαξε.", "st": "Them. 29.3"}, {"sp": "N", "t": "λέγεται δὲ καὶ τοὺς ὕστερον βασιλεῖς, ἐφ’ ὧν μᾶλλον αἱ Περσικαὶ πράξεις ταῖς Ἑλληνικαῖς ἀνεκράθησαν, ὁσάκις δεηθεῖεν ἀνδρὸς Ἕλληνος, ἐπαγγέλλεσθαι καὶ γράφειν ἕκαστον, ὡς μείζων ἔσοιτο παρ’ αὐτῷ Θεμιστοκλέους. αὐτὸν δὲ τὸν Θεμιστοκλέα φασὶν ἤδη μέγαν ὄντα καὶ θεραπευόμενον ὑπὸ πολλῶν λαμπρᾶς ποτε τραπέζης αὐτῷ παρατεθείσης πρὸς τοὺς παῖδας εἰπεῖν· ὦ παῖδες, ἀπωλόμεθα ἄν, εἰ μὴ ἀπωλόμεθα. πόλεις δ’ αὐτῷ τρεῖς μὲν οἱ πλεῖστοι δοθῆναι λέγουσιν εἰς ἄρτον καὶ οἶνον καὶ ὄψον, Μαγνησίαν καὶ Λάμψακον καὶ Μυοῦντα· δύο δ’ ἄλλας προστίθησιν ὁ Κυζικηνὸς Νεάνθης καὶ Φανίας, Περκώτην καὶ Παλαίσκηψιν εἰς στρωμνὴν καὶ ἀμπεχόνην.", "st": "Them. 29.7"}, {"sp": "N", "t": "καταβαίνοντι δ’ αὐτῷ πρὸς τὰς Ἑλληνικὰς πράξεις ἐπὶ θάλατταν Πέρσης ἀνὴρ Ἐπιξύης ὄνομα, σατραπεύων τῆς ἄνω Φρυγίας, ἐπεβούλευσε, παρεσκευακὼς ἔκπαλαι Πισίδας τινὰς ἀποκτενοῦντας, ὅταν ἐν τῇ καλουμένῃ κώμῃ Λεοντοκεφάλῳ γενόμενος καταυλισθῇ. τῷ δὲ λέγεται καθεύδοντι μεσημβρίας τὴν μητέρα τῶν θεῶν ὄναρ φανεῖσαν εἰπεῖν· ὦ Θεμιστόκλεις, ὑστέρει κεφαλῆς λεόντων, ἵνα μὴ λέοντι περιπέσῃς. ἐγὼ δὲ ἀντὶ τούτου σε αἰτῶ θεράπαιναν Μνησιπτολέμαν. διαταραχθεὶς οὖν ὁ Θεμιστοκλῆς προσευξάμενος τῇ θεῷ τὴν μὲν λεωφόρον ἀφῆκεν, ἑτέρᾳ δὲ περιελθὼν καὶ παραλλάξας τὸν τόπον ἐκεῖνον ἤδη νυκτὸς οὔσης κατηυλίσατο.", "st": "Them. 30.1"}, {"sp": "N", "t": "τῶν δὲ τὴν σκηνὴν κομιζόντων ὑποζυγίων ἑνὸς εἰς τὸν ποταμὸν ἐμπεσόντος, οἱ τοῦ Θεμιστοκλέους οἰκέται τὰς αὐλαίας διαβρόχους γενομένας ἐκπετάσαντες ἀνέψυχον. οἱ δὲ Πισίδαι τὰ ξίφη λαβόντες ἐν τούτῳ προσεφέροντο, καὶ τὰ ψυχόμενα πρὸς τὴν σελήνην οὐκ ἀκριβῶς ἰδόντες ᾠήθησαν εἶναι τὴν σκηνὴν τὴν Θεμιστοκλέους κἀκεῖνον ἔνδον εὑρήσειν ἀναπαυόμενον. ὡς δ’ ἐγγὺς γενόμενοι τὴν αὐλαίαν ἀνέστελλον, ἐπιπίπτουσιν αὐτοῖς οἱ παραφυλάσσοντες καὶ συλλαμβάνουσι. διαφυγὼν δὲ τὸν κίνδυνον οὕτω καὶ θαυμάσας τὴν ἐπιφάνειαν τῆς θεοῦ ναὸν κατεσκεύασεν ἐν Μαγνησίᾳ Δινδυμήνης καὶ τὴν θυγατέρα Μνησιπτολέμαν ἱέρειαν ἀπέδειξεν.", "st": "Them. 30.3"}, {"sp": "N", "t": "ὡς δ’ ἦλθεν εἰς Σάρδεις καὶ σχολὴν ἄγων ἐθεᾶτο τῶν ἱερῶν τὴν κατασκευὴν καὶ τῶν ἀναθημάτων τὸ πλῆθος, εἶδε δὲ ἐν μητρὸς ἱερῷ τὴν καλουμένην ὑδροφόρον κόρην χαλκῆν, μέγεθος δίπηχυν, ἣν αὐτὸς ὅτε τῶν Ἀθήνησιν ὑδάτων ἐπιστάτης ἦν, ἑλὼν τοὺς ὑφαιρουμένους τὸ ὕδωρ καὶ παροχετεύοντας, ἀνέθηκεν ἐκ τῆς ζημίας ποιησάμενος, εἴτε δὴ παθών τι πρὸς τὴν αἰχμαλωσίαν τοῦ ἀναθήματος εἴτε βουλόμενος ἐνδείξασθαι τοῖς Ἀθηναίοις, ὅσην ἔχει τιμὴν καὶ δύναμιν ἐν τοῖς βασιλέως πράγμασι, λόγον τῷ Λυδίας σατράπῃ προσήνεγκεν αἰτούμενος ἀποστεῖλαι τὴν κόρην εἰς τὰς Ἀθήνας. χαλεπαίνοντος δὲ τοῦ βαρβάρου καὶ βασιλεῖ γράψειν φήσαντος ἐπιστολήν, φοβηθεὶς ὁ Θεμιστοκλῆς εἰς τὴν γυναικωνῖτιν κατέφυγε καὶ τὰς παλλακίδας αὐτοῦ θεραπεύσας χρήμασιν ἐκεῖνόν τε κατεπράϋνε τῆς ὀργῆς καὶ πρὸς τὰ ἄλλα παρεῖχεν ἑαυτὸν εὐλαβέστερον, ἤδη καὶ τὸν φθόνον τῶν βαρβάρων δεδοικώς. οὐ γὰρ πλανώμενος περὶ τὴν Ἀσίαν, ὥς φησι Θεόπομπος, ἀλλ’ ἐν Μαγνησίᾳ μὲν οἰκῶν, καρπούμενος δὲ δωρεὰς μεγάλας καὶ τιμώμενος ὅμοια Περσῶν τοῖς ἀρίστοις, ἐπὶ πολὺν χρόνον ἀδεῶς διῆγεν, οὐ πάνυ τι τοῖς Ἑλληνικοῖς πράγμασι βασιλέως προσέχοντος ὑπ’ ἀσχολιῶν περὶ τὰς ἄνω πράξεις.", "st": "Them. 31.1"}, {"sp": "N", "t": "ὡς δ’ Αἴγυπτός τε ἀφισταμένη βοηθούντων Ἀθηναίων καὶ τριήρεις Ἑλληνικαὶ μέχρι Κύπρου καὶ Κιλικίας ἀναπλέουσαι καὶ Κίμων θαλαττοκρατῶν ἐπέστρεψεν αὐτὸν ἀντεπιχειρεῖν τοῖς Ἕλλησι καὶ κωλύειν αὐξανομένους ἐπ’ αὐτόν, ἤδη δὲ καὶ δυνάμεις ἐκινοῦντο καὶ στρατηγοὶ διεπέμποντο καὶ κατέβαινον ἀγγελίαι πρὸς Θεμιστοκλέα, τῶν Ἑλληνικῶν ἐξάπτεσθαι κελεύοντος βασιλέως καὶ βεβαιοῦν τὰς ὑποσχέσεις, οὔτε δι’ ὀργήν τινα παροξυνθεὶς κατὰ τῶν πολιτῶν οὔτε ἐπαρθεὶς τιμῇ τοσαύτῃ καὶ δυνάμει πρὸς τὸν πόλεμον, ἀλλ’ ἴσως μὲν οὐδ’ ἐφικτὸν ἡγούμενος τὸ ἔργον, ἄλλους τε μεγάλους τῆς Ἑλλάδος ἐχούσης στρατηγοὺς τότε καὶ Κίμωνος ὑπερφυῶς εὐημεροῦντος ἐν τοῖς πολεμικοῖς, τὸ δὲ πλεῖστον αἰδοῖ τῆς τε δόξης τῶν πράξεων τῶν ἑαυτοῦ καὶ τῶν τροπαίων ἐκείνων, ἄριστα βουλευσάμενος ἐπιθεῖναι τῷ βίῳ τὴν τελευτὴν πρέπουσαν, ἔθυσε τοῖς θεοῖς, καὶ τοὺς φίλους συναγαγὼν καὶ δεξιωσάμενος, ὡς μὲν ὁ πολὺς λόγος, αἷμα ταύρειον πιών, ὡς δ’ ἔνιοι, φάρμακον ἐφήμερον προσενεγκάμενος, ἐν Μαγνησίᾳ κατέστρεψε πέντε πρὸς τοῖς ἑξήκοντα βεβιωκὼς ἔτη καὶ τὰ πλεῖστα τούτων ἐν πολιτείαις καὶ ἡγεμονίαις. τὴν δ’ αἰτίαν τοῦ θανάτου καὶ τὸν τρόπον πυθόμενον βασιλέα λέγουσιν ἔτι μᾶλλον θαυμάσαι τὸν ἄνδρα καὶ τοῖς φίλοις αὐτοῦ καὶ οἰκείοις χρώμενον διατελεῖν φιλανθρώπως.", "st": "Them. 31.3"}, {"sp": "N", "t": "ἀπέλιπε δὲ Θεμιστοκλῆς παῖδας ἐκ μὲν Ἀρχίππης τῆς Λυσάνδρου τοῦ Ἀλωπεκῆθεν Ἀρχέπτολιν καὶ Πολύευκτον καὶ Κλεόφαντον, οὗ καὶ Πλάτων ὁ φιλόσοφος ὡς ἱππέως ἀρίστου, τἆλλα δ’ οὐδενὸς ἀξίου γενομένου μνημονεύει. τῶν δὲ πρεσβυτάτων Νεοκλῆς μὲν ἔτι παῖς ὢν ὑφ’ ἵππου δηχθεὶς ἀπέθανε, Διοκλέα δὲ Λύσανδρος ὁ πάππος υἱὸν ἐποιήσατο. θυγατέρας δὲ πλείους ἔσχεν, ὧν Μνησιπτολέμαν μὲν ἐκ τῆς ἐπιγαμηθείσης γενομένην Ἀρχέπτολις ὁ ἀδελφὸς οὐκ ὢν ὁμομήτριος ἔγημεν, Ἰταλίαν δὲ Πανθοίδης ὁ Χῖος, Σύβαριν δὲ Νικομήδης ὁ Ἀθηναῖος· Νικομάχην δὲ Φρασικλῆς ὁ ἀδελφιδοῦς Θεμιστοκλέους, ἤδη τετελευτηκότος ἐκείνου, πλεύσας εἰς Μαγνησίαν ἔλαβε παρὰ τῶν ἀδελφῶν, νεωτάτην δὲ πάντων τῶν τέκνων Ἀσίαν ἔθρεψε.", "st": "Them. 32.1"}, {"sp": "N", "t": "καὶ τάφον μὲν αὐτοῦ λαμπρὸν ἐν τῇ ἀγορᾷ Μάγνητες ἔχουσι· περὶ δὲ τῶν λειψάνων οὔτ’ Ἀνδοκίδῃ προσέχειν ἄξιον ἐν τῷ Πρὸς τοὺς ἑταίρους λέγοντι, φωράσαντας τὰ λείψανα διαρρῖψαι τοὺς Ἀθηναίους (ψεύδεται γὰρ ἐπὶ τὸν δῆμον παροξύνων τοὺς ὀλιγαρχικούς), ὅ τε Φύλαρχος, ὥσπερ ἐν τραγῳδίᾳ τῇ ἱστορίᾳ μονονοὺ μηχανὴν ἄρας καὶ προαγαγὼν Νεοκλέα τινὰ καὶ Δημόπολιν, υἱοὺς Θεμιστοκλέους, ἀγῶνα βούλεται κινεῖν καὶ πάθος, ὃ οὐδ’ ἂν ὁ τυχὼν ἀγνοήσειεν ὅτι πέπλασται. Διόδωρος δ’ ὁ περιηγητὴς ἐν τοῖς Περὶ μνημάτων εἴρηκεν ὡς ὑπονοῶν μᾶλλον ἢ γινώσκων, ὅτι περὶ τὸν μέγαν λιμένα τοῦ Πειραιῶς ἀπὸ τοῦ κατὰ τὸν Ἄλκιμον ἀκρωτηρίου πρόκειταί τις οἷον ἀγκών, καὶ κάμψαντι τοῦτον ἐντός, ᾗ τὸ ὑπεύδιον τῆς θαλάττης, κρηπίς ἐστιν εὐμεγέθης καὶ τὸ περὶ αὐτὴν βωμοειδὲς τάφος τοῦ Θεμιστοκλέους. οἴεται δὲ καὶ Πλάτωνα τὸν κωμικὸν αὐτῷ μαρτυρεῖν ἐν τούτοις·", "st": "Them. 32.3"}, {"sp": "N", "t": "ὁ σὸς δὲ τύμβος ἐν καλῷ κεχωσμένος<br>τοῖς ἐμπόροις πρόσρησις ἔσται πανταχοῦ,<br>τούς τ’ ἐκπλέοντας εἰσπλέοντάς τ’ ὄψεται,<br>χὠπόταν ἅμιλλα τῶν νεῶν θεάσεται.", "st": "Them. 32.3b"}, {"sp": "N", "t": "τοῖς δ’ ἀπὸ γένους τοῦ Θεμιστοκλέους καὶ τιμαί τινες ἐν Μαγνησίᾳ φυλαττόμεναι μέχρι τῶν ἡμετέρων χρόνων ἦσαν, ἃς ἐκαρποῦτο Θεμιστοκλῆς Ἀθηναῖος, ἡμέτερος συνήθης καὶ φίλος παρ’ Ἀμμωνίῳ τῷ φιλοσόφῳ γενόμενος.", "st": "Them. 32.3c"}, {"sp": "HDR", "t": "Κάμιλλος"}, {"sp": "N", "t": "περὶ δὲ Φουρίου Καμίλλου πολλῶν καὶ μεγάλων λεγομένων ἴδιον εἶναι δοκεῖ μάλιστα καὶ παράδοξον, ὅτι πλεῖστα μὲν ἐν ἡγεμονίαις καὶ μέγιστα κατορθώσας, δικτάτωρ δὲ πεντάκις αἱρεθείς, θριαμβεύσας δὲ τετράκις, κτίστης δὲ τῆς Ῥώμης ἀναγραφεὶς δεύτερος, οὐδὲ ἅπαξ ὑπάτευσε. τούτου δ’ αἴτιον ἡ τῆς τότε πολιτείας κατάστασις, ἐκ διαφορᾶς τοῦ δήμου πρὸς τὴν σύγκλητον ὑπάτους μὲν ἐρίσαντος μὴ ἀποδείκνυσθαι, χιλιάρχους δὲ χειροτονοῦντος ἐπὶ τὴν ἡγεμονίαν, ὧν, καίπερ ἀπ’ ἐξουσίας καὶ δυνάμεως ὑπατικῆς ἅπαντα πραττόντων, ἧττον ἦν ἐπαχθὴς ἡ ἀρχὴ διὰ τὸ πλῆθος, τὸ γὰρ ἓξ ἄνδρας, ἀλλὰ μὴ δύο, τοῖς πράγμασιν ἐφιστάναι, παρεμυθεῖτο τοὺς βαρυνομένους τὴν ὀλιγαρχίαν.", "st": "Cam. 1.1"}, {"sp": "N", "t": "κατὰ τοῦτο δὴ καιροῦ μάλιστα τῇ δόξῃ καὶ τοῖς πράγμασιν ἀκμάσας ὁ Κάμιλλος ὕπατος μὲν οὐκ ἠξίωσεν ἄκοντι τῷ δήμῳ γενέσθαι, καίπερ ἐν τῷ διὰ μέσου δεξαμένης ὑπατικὰς ἀρχαιρεσίας τῆς πολιτείας πολλάκις, ἐν δὲ ταῖς ἄλλαις ἡγεμονίαις πολλαῖς καὶ παντοδαπαῖς γενομέναις τοιοῦτον αὑτὸν παρέσχεν, ὥστε τὴν μὲν ἐξουσίαν καὶ μοναρχοῦντος εἶναι κοινήν, τὴν δὲ δόξαν ἰδίαν καὶ μεθ’ ἑτέρων στρατηγοῦντος· ὧν τοῦ μὲν ἡ μετριότης αἴτιον ἀνεπιφθόνως ἄρχοντος, τοῦ δ’ ἡ φρόνησις, δι’ ἣν ὁμολογουμένως ἐπρώτευεν.", "st": "Cam. 1.3"}, {"sp": "N", "t": "οὔπω δὲ τότε περὶ τὸν τῶν Φουρίων οἶκον οὔσης μεγάλης ἐπιφανείας αὐτὸς ἀφ’ ἑαυτοῦ πρῶτος εἰς δόξαν προῆλθεν ἐν τῇ μεγάλῃ μάχῃ πρὸς Αἰκανοὺς καὶ Οὐολούσκους ὑπὸ δικτάτορι Ποστουμίῳ Τουβέρτῳ στρατευόμενος, προϊππεύων γὰρ τοῦ στρατοῦ καὶ πληγῇ περιπεσὼν εἰς τὸν μηρόν οὐκ ἀνῆκεν, ἀλλ’ ἐγκείμενον τῷ τραύματι παρέλκων τὸ ἀκόντισμα καὶ συμπλεκόμενος τοῖς ἀρίστοις τῶν πολεμίων τροπὴν ἐποίησεν. ἐκ δὲ τούτου τῶν τ’ ἄλλων γερῶν ἔτυχε καὶ τιμητὴς ἀπεδείχθη, μέγα τῆς ἀρχῆς ἀξίωμα ταύτης ἐπὶ τῶν τότε χρόνων ἐχούσης. μνημονεύεται δὲ αὐτοῦ τιμητεύοντος καλὸν μὲν ἔργον τὸ τοὺς ἀγάμους λόγοις τε πείθοντα καὶ ζημίαις ἀπειλοῦντα συγκαταζεῦξαι ταῖς χηρευούσαις γυναιξί πολλαὶ δ’ ἦσαν αὗται διὰ τοὺς πολέμους, ἀναγκαῖον δὲ τὸ καὶ τοὺς ὀρφανοὺς ὑποτελεῖς ποιῆσαι πρότερον ἀνεισφόρους ὄντας. αἴτιαι δ’ ἦσαν αἱ συνεχεῖς στρατεῖαι μεγάλων ἀναλωμάτων δεόμεναι, καὶ μάλιστα κατήπειγεν ἡ Οὐηΐων πολιορκία, τούτους ἔνιοι Οὐηιεντανοὺς καλοῦσιν.", "st": "Cam. 2.1"}, {"sp": "N", "t": "ἦν δὲ πρόσχημα τῆς Τυρρηνίας ἡ πόλις, ὅπλων μὲν ἀριθμῷ καὶ πλήθει τῶν στρατευομένων οὐκ ἀποδέουσα τῆς Ῥώμης, πλούτῳ δὲ καὶ βίων ἁβρότητι καὶ τρυφαῖς καὶ πολυτελείαις ἀγαλλομένη πολλοὺς καὶ καλοὺς ἀγῶνας ἠγωνίσατο περὶ δόξης καὶ δυναστείας πολεμοῦσα Ῥωμαίοις. ἐν δὲ τῷ τότε χρόνῳ τῆς μὲν φιλοτιμίας ἀφειστήκει συντριβεῖσα μεγάλαις μάχαις· ἐπαράμενοι δὲ τείχη μεγάλα καὶ καρτερά καὶ τὴν πόλιν ὅπλων καὶ βελῶν καὶ σίτου καὶ παρασκευῆς ἁπάσης ἐμπλήσαντες, ἀδεῶς ὑπέμενον τὴν πολιορκίαν, μακρὰν μὲν οὖσαν, οὐχ ἧττον δὲ τοῖς πολιορκοῦσιν ἐργώδη καὶ χαλεπὴν γενομένην. εἰθισμένοι γὰρ οὐ πολὺν χρόνον ἅμα ὥρᾳ θέρους ἔξω στρατεύειν, οἴκοι δὲ διαχειμάζειν, τότε πρῶτον ἠναγκάσθησαν ὑπὸ τῶν χιλιάρχων φρούρια κατασκευασάμενοι καὶ τὸ στρατόπεδον τειχίσαντες ἐν τῇ πολεμίᾳ χειμῶνα καὶ θέρος συνάπτειν, ἤδη σχεδὸν ἔτους ἑβδόμου τῷ πολέμῳ τελευτῶντος. ὥστε καὶ τοὺς ἄρχοντας ἐν αἰτίᾳ, γενέσθαι καὶ μαλακῶς πολιορκεῖν δοκοῦντας ἀφαιρεθῆναι τὴν ἀρχήν, ἑτέρων αἱρεθέντων ἐπὶ τὸν πόλεμον ὧν ἦν καὶ Κάμιλλος τότε χιλιαρχῶν τὸ δεύτερον. ἔπραξε δὲ περὶ τὴν πολιορκίαν οὐδὲν ἐν ἐκείνῳ τῷ χρόνῳ, λαχὼν Φαλερίοις καὶ Καπηνάταις πολεμεῖν, οἳ δι’ ἀσχολίαν τότε πολλὰ τὴν χώραν καθυβρίσαντες καὶ παρὰ πάντα τὸν Τυρρηνικὸν πόλεμον ἐνοχλήσαντες ἐπιέσθησαν ὑπὸ τοῦ Καμίλλου καὶ συνεστάλησαν εἰς τὰ τείχη πολλοὺς ἀποβαλόντες.", "st": "Cam. 2.4"}, {"sp": "N", "t": "ἐκ τούτου τὸ περὶ τὴν Ἀλβανίδα λίμνην πάθος ἀκμάζοντι τῷ πολέμῳ συνενεχθέν οὐδενὸς ἧττον τῶν ἀπίστων πυθέσθαι θαυμάτων αἰτίας κοινῆς ἀπορίᾳ, καὶ λόγου φυσικὴν ἔχοντος ἀρχὴν ἐφόβησεν, ἦν μὲν γὰρ ὥρα μετοπωρινή, καὶ τὸ θέρος ἔληγεν οὔτ’ ἔπομβρον οὔτε πνεύμασι νοτίοις χαλεπὸν ἐπιδήλως γενόμενον· πολλὰς δὲ λίμνας καὶ ποταμοὺς καὶ νάματα παντοδαπὰ τῆς Ἰταλίας ἐχούσης τὰ μὲν ἐξέλιπε κομιδῇ, τὰ δ’ ἀντέσχε γλίσχρως καὶ μόλις, οἱ δὲ ποταμοὶ πάντες ὥσπερ ἀεὶ κοῖλοι καὶ ταπεινοὶ διὰ θέρους ἐρρύησαν. τὸ δὲ τῆς Ἀλβανίδος λίμνης ἀρχὴν ἔχον ἐν ἑαυτῷ καὶ τελευτήν, ὄρεσιν εὐγείοις περιεχόμενον, ἀπ’ οὐδενὸς αἰτίου, πλὴν εἴ τι θεῖον, αὐξόμενον ἐπιδήλως διωγκοῦτο καὶ προσίστατο ταῖς ὑπωρείαις καὶ τῶν ἀνωτάτω λόφων ὁμαλῶς ἐπέψαυεν, ἄνευ σάλου καὶ κλύδωνος ἐξανιστάμενον. καὶ πρῶτον μὲν ἦν ποιμένων θαῦμα καὶ βοτήρων ἐπεὶ δέ, τοῦ διείργοντος ἀπὸ τῆς κάτω χώρας οἷον ἰσθμοῦ τὴν λίμνην ὑπεκραγέντος ὑπὸ τοῦ πλήθους καὶ βάρους, μέγα ῥεῦμα κατέβαινε διὰ τῶν ἀρουμένων καὶ φυτευομένων ἐπὶ τὴν θάλατταν, οὐ μόνον αὐτοῖς παρεῖχε Ῥωμαίοις ἔκπληξιν, ἀλλὰ καὶ πᾶσιν ἐδόκει τοῖς τὴν Ἰταλίαν κατοικοῦσι μηδενὸς μικροῦ σημεῖον εἶναι, πλεῖστος δ’ αὐτοῦ λόγος ἦν ἐν τῷ στρατοπέδῳ τῷ πολιορκοῦντι τοὺς Οὐηΐους, ὥστε κἀκείνοις ἔκπυστον γενέσθαι τὸ περὶ τὴν λίμνην πάθος.", "st": "Cam. 3.1"}, {"sp": "N", "t": "οἷα δ’ ἐν πολιορκίᾳ διὰ χρόνου μῆκος ἐπιμιξίας τε πολλὰς ἐχούσῃ καὶ κοινολογίας πρὸς τοὺς πολεμίους, ἐγεγόνει τινὶ Ῥωμαίῳ συνήθεια καὶ παρρησία πρὸς ἕνα τῶν πολιτῶν, ἄνθρωπον ἔμπειρόν τε λογίων παλαιῶν καί τι καὶ πλέον εἰδέναι τῶν ἄλλων ἀπὸ μαντικῆς δοκοῦντα. τοῦτον οὖν ὁ Ῥωμαῖος, ὡς ἤκουσε τὴν ἐπίδοσιν τῆς λίμνης, ὁρῶν ὑπερηδόμενόν τε καὶ καταγελῶντα τῆς πολιορκίας, οὐ ταῦτ’ ἔφη μόνον ἐνηνοχέναι θαυμαστὰ τὸν παρόντα χρόνον, ἀλλ’ ἕτερα τούτων ἀτοπώτερα σημεῖα Ῥωμαίοις γεγονέναι, περὶ ὧν ἐθέλειν ἐκείνῳ κοινωσάμενος, εἴ τι δύναιτο, θέσθαι τῶν ἰδίων ἄμεινον ἐν τοῖς κοινοῖς νοσοῦσιν. ὑπακούσαντος δὲ τοῦ ἀνθρώπου προθύμως καὶ διδόντος ἑαυτὸν εἰς κοινολογίαν, ὡς ἀπορρήτων τινῶν ἀκροατὴν ἐσόμενον, κατὰ μικρὸν οὕτω διαλεγόμενος καὶ ὑπάγων αὐτόν, ὡς πορρωτέρω τῶν πυλῶν ἐγεγόνεισαν, αἴρει τε μετέωρον εὐρωστότερος ὢν καί τινῶν ἀπὸ στρατοπέδου προσδραμόντων χειρωσάμενος καὶ κρατήσας παρέδωκε τοῖς στρατηγοῖς. ἐν τούτῳ δ’ ἀνάγκης γεγονὼς ὁ ἄνθρωπος καὶ μαθὼν ἄρα τὸ πεπρωμένον ὡς ἄφυκτον εἴη, λόγια προὔφαινεν ἀπόρρητα περὶ τῆς ἑαυτοῦ πατρίδος, ὡς οὐκ οὔσης ἁλωσίμου πρότερον ἢ τὴν Ἀλβανίδα λίμνην ἐκχυθεῖσαν καὶ φερομένην ὁδοὺς ἑτέρας ὤσαντες ὀπίσω καὶ περισπάσαντες οἱ πολέμιοι κωλύσουσι μίγνυσθαι τῇ θαλάττῃ.", "st": "Cam. 4.1"}, {"sp": "N", "t": "ταῦτα τῇ συγκλήτῳ πυθομένῃ καὶ διαπορούσῃ καλῶς ἔχειν ἔδοξε πέμψαντας εἰς Δελφοὺς ἐρέσθαι τὸν θεόν. οἱ δὲ πεμφθέντες ἄνδρες ἔνδοξοι καὶ μεγάλοι, Κόσσος Λικίννιος καὶ Οὐαλλέριος Ποτῖτος καὶ Φάβιος Ἄμβουστος, πλῷ τε χρησάμενοι καὶ τῶν παρὰ τοῦ θεοῦ τυχόντες ἧκον ἄλλας τε μαντείας κομίζοντες, αἳ πατρίων τινῶν περὶ τὰς καλουμένας Λατίνας ἑορτὰς ὀλιγωρίαν ἔφραζον αὐτοῖς, καὶ τὸ τῆς Ἀλβανίδος ὕδωρ ἐκέλευον εἴργοντας ὡς ἀνυστόν ἐστι τῆς θαλάσσης ἀνωθεῖν εἰς τὸν ἀρχαῖον πόρον, ἢ τοῦτο μὴ δυναμένους ὀρύγμασι καὶ τάφροις παράγειν εἰς τὸ πεδίον καὶ καταναλίσκειν· ἀπαγγελθέντων δὲ τούτων οἱ μὲν ἱερεῖς τὰ περὶ τὰς θυσίας ἔπραττον, ὁ δὲ δῆμος ἐχώρει πρὸς τὰ ἔργα καὶ τὸ ὕδωρ ἐξέτρεπεν.", "st": "Cam. 4.4"}, {"sp": "N", "t": "ἡ δὲ σύγκλητος εἰς τὸ δέκατον ἔτος τοῦ πολέμου καταλύσασα τὰς ἄλλας ἀρχὰς δικτάτορα Κάμιλλον ἀπέδειξεν ἵππαρχον δ’ ἐκεῖνος αὑτῷ προσελόμενος Κορνήλιον Σκηπίωνα, πρῶτον μὲν εὐχὰς ἐποιήσατο τοῖς θεοῖς ἐπὶ τῷ πολέμῳ τέλος εὐκλεὲς λαβόντι τὰς μεγάλας θέας ἄξειν καὶ νεὼν θεᾶς, ἣν Μητέρα Ματοῦταν καλοῦσι Ῥωμαῖοι, καθιερώσειν.", "st": "Cam. 5.1"}, {"sp": "N", "t": "ταύτην ἄν τις ἀπὸ τῶν δρωμένων ἱερῶν μάλιστα Λευκοθέαν νομίσειεν εἶναι, καὶ γὰρ θεράπαιναν εἰς τὸν σηκὸν εἰσάγουσαι ῥαπίζουσιν, εἶτ’ ἐξελαύνουσι καὶ τὰ τῶν ἀδελφῶν τέκνα πρὸ τῶν ἰδίων ἐναγκαλίζονται καὶ δρῶσι περὶ τὴν θυσίαν ἃ ταῖς Διονύσου τροφοῖς καὶ τοῖς διὰ τὴν παλλακὴν πάθεσι τῆς Ἰνοῦς προσέοικε.", "st": "Cam. 5.2"}, {"sp": "N", "t": "μετὰ δὲ τὰς εὐχὰς ὁ Κάμιλλος εἰς τὴν Φαλίσκων ἐνέβαλε, καὶ μάχῃ μεγάλῃ τούτους τε καὶ Καπηνάτας προσβοηθήσαντας αὐτοῖς ἐνίκησεν. ἔπειτα πρὸς τὴν πολιορκίαν τραπόμενος τῶν Οὐηΐων καὶ τὸν ἐκ προσβολῆς ἀγῶνα χαλεπὸν καὶ δύσεργον ὁρῶν ὑπονόμους ἔτεμνε, τῶν περὶ τὴν πόλιν χωρίων ἐνδιδόντων τοῖς ὀρύγμασι καὶ καταδεχομένων εἰς βάθος ἄγειν ἄδηλον τοῖς πολεμίοις τὰ ἔργα. διὸ καὶ προϊούσης ὁδῷ τῆς ἐλπίδος αὐτὸς μὲν ἔξωθεν προσέβαλλεν, ἐκκαλούμενος ἐπὶ τὰ τείχη τοὺς πολεμίους, ἄλλοι δ’ ἀδήλως ὑποπορευόμενοι διὰ τῶν ὑπονόμων ἔλαθον ἐντὸς γενόμενοι τῆς ἄκρας κατὰ τὸ τῆς Ἥρας ἱερόν, ὃ μέγιστον ἦν ἐν τῇ πόλει καὶ μάλιστα τιμώμενον.", "st": "Cam. 5.3"}, {"sp": "N", "t": "ἐνταῦθα λέγεται τυχεῖν κατ’ ἐκεῖνο καιροῦ τὸν ἡγεμόνα τῶν Τυρρηνῶν ἐφ’ ἱεροῖς· τὸν δὲ μάντιν εἰς τὰ σπλάγχνα κατιδόντα καὶ μέγα φθεγξάμενον εἰπεῖν, ὅτι νίκην ὁ θεὸς δίδωσι τῷ κατακολουθήσαντι τοῖς ἱεροῖς ἐκείνοις· ταύτης δὲ τῆς φωνῆς τοὺς ἐν τοῖς ὑπονόμοις Ῥωμαίους ἐπακούσαντας ταχὺ διασπάσαι τὸ ἔδαφος, καὶ μετὰ βοῆς καὶ ψόφου τῶν ὅπλων ἀναδύντας, ἐκπλαγέντων τῶν πολεμίων καὶ φυγόντων, ἁρπάσαντας τὰ σπλάγχνα κομίσαι πρὸς τὸν Κάμιλλον. ἀλλὰ ταῦτα μὲν ἴσως ἐοικέναι δόξει μυθεύμασιν.", "st": "Cam. 5.4"}, {"sp": "N", "t": "ἁλούσης δὲ τῆς πόλεως κατὰ κράτος καὶ τῶν Ῥωμαίων ἀγόντων καὶ φερόντων ἄπειρόν τινα πλοῦτον, ἐφορῶν ὁ Κάμιλλος ἀπὸ τῆς ἄκρας τὰ πραττόμενα, πρῶτον μὲν ἑστὼς ἐδάκρυσεν, εἶτα μακαρισθεὶς ὑπὸ τῶν παρόντων ἀνέσχε τὰς χεῖρας τοῖς θεοῖς καὶ προσευχόμενος εἶπε· Ζεῦ μέγιστε καὶ θεοὶ χρηστῶν ἐπίσκοποι καὶ πονηρῶν ἔργων, αὐτοί που σύνιστε Ῥωμαίοις, ὡς οὐ παρὰ δίκην, ἀλλὰ κατ’ ἀνάγκην ἀμυνόμενοι μετερχόμεθα δυσμενῶν ἀνδρῶν καὶ παρανόμων πόλιν. εἰ δ’ ἄρα τις, ἔφη, καὶ ἡμῖν ἀντίστροφος ὀφείλεται τῆς παρούσης νέμεσις εὐπραξίας, εὔχομαι ταύτην ὑπέρ τε πόλεως καὶ στρατοῦ Ῥωμαίων εἰς ἐμαυτὸν ἐλαχίστῳ κακῷ τελευτῆσαι. ταῦτ’ εἰπών, καθάπερ ἐστὶ Ῥωμαίοις ἔθος ἐπευξαμένοις καὶ προσκυνήσασιν ἐπὶ δεξιὰ ἐξελίττειν, ἐσφάλη περιστρεφόμενος, διαταραχθέντων δὲ τῶν παρόντων πάλιν ἀναλαβὼν ἑαυτὸν ἐκ τοῦ πτώματος εἶπεν, ὡς γέγονεν αὐτῷ κατ’ εὐχὴν σφάλμα μικρὸν ἐπ’ εὐτυχίᾳ μεγίστῃ.", "st": "Cam. 5.6"}, {"sp": "N", "t": "διαπορθήσας δὲ τὴν πόλιν ἔγνω τὸ ἄγαλμα τῆς Ἥρας μεταφέρειν εἰς Ῥώμην, ὥσπερ εὔξατο. καὶ συνελθόντων ἐπὶ τούτῳ τῶν τεχνιτῶν, ὁ μὲν ἔθυε καὶ προσεύχετο τῇ θεῷ δέχεσθαι τὴν προθυμίαν αὐτῶν καὶ εὐμενῆ γενέσθαι σύνοικον τοῖς λαχοῦσι τὴν Ῥώμην θεοῖς, τὸ δ’ ἄγαλμά φασιν ὑποφθεγξάμενον εἰπεῖν. ὅτι καὶ βούλεται καὶ συγκαταινεῖ. Λίουιος δέ φησιν εὔχεσθαι μὲν τὸν Κάμιλλον ἁπτόμενον τῆς θεοῦ καὶ παρακαλεῖν, ἀποκρίνασθαι δέ τινας τῶν παρόντων, ὅτι καὶ βούλεται καὶ συνακολουθεῖ καὶ συνακολουθεῖ προθύμως.", "st": "Cam. 6.1"}, {"sp": "N", "t": "οἱ δ’ ἰσχυριζόμενοι καὶ τῷ παραδόξῳ βοηθοῦντες μεγίστην μὲν ἔχουσι συνήγορον τὴν τύχην τῆς πόλεως, ἣν ἀπὸ μικρᾶς καὶ καταφρονουμένης ἀρχῆς ἐπὶ τοσοῦτον δόξης καὶ δυνάμεως προελθεῖν δίχα θεοῦ πολλαῖς καὶ μεγάλαις ἐπιφανείαις ἑκάστοτε συμπαρόντος ἀμήχανον· οὐ μὴν ἀλλὰ καὶ συνάγουσιν ὁμοειδῆ τινα, τοῦτο μὲν ἱδρῶτας ἀγαλμάτων πολλάκις ἐκχυθέντας, τοῦτο δὲ στεναγμοὺς ἀκουσθέντας ἀποστροφάς τε δεικνύντες καὶ καταμύσεις ξοάνων, ἃς ἱστορήκασιν οὐκ ὀλίγοι τῶν πρότερον. πολλὰ δὲ καὶ τῶν καθ’ ἡμᾶς ἀκηκοότες ἀνθρώπων λέγειν ἔχομεν ἄξια θαύματος, ὧν οὐκ ἄν τις εἰκῇ καταφρονήσειεν. ἀλλὰ τοῖς τοιούτοις καὶ τὸ πιστεύειν σφόδρα καὶ τὸ λίαν ἀπιστεῖν ἐπισφαλές ἐστι διὰ τὴν ἀνθρωπίνην ἀσθένειαν ὅρον οὐκ ἔχουσαν οὐδὲ κρατοῦσαν αὑτῆς, ἀλλ’ ἐκφερομένην ὅπου μὲν εἰς δεισιδαιμονίαν καὶ τῦφον, ὅπου δ’ εἰς ὀλιγωρίαν τῶν θεῶν καὶ περιφρόνησιν ἡ δ’ εὐλάβεια καὶ τὸ μηδὲν ἄγαν ἄριστον.", "st": "Cam. 6.3"}, {"sp": "N", "t": "ὁ δὲ Κάμιλλος εἴτε μεγέθει τοῦ ἔργου, πόλιν ἀντίπαλον τῆς Ῥώμης ἔτει δεκάτῳ τῆς πολιορκίας καθῃρηκώς, εἴτε ὑπὸ τῶν εὐδαιμονιζόντων αὐτὸν εἰς ὄγκον ἐξαρθεὶς καὶ φρόνημα νομίμου καὶ πολιτικῆς ἀρχῆς ἐπαχθέστερον, τά τε ἄλλα σοβαρῶς ἐθριάμβευσε καί τέθριππον ὑποζευξάμενος λευκόπωλον ἐπέβη καὶ διεξήλασε τῆς Ῥώμης, οὐδενὸς τοῦτο ποιήσαντος ἡγεμόνος πρότερον οὐδ’ ὕστερον, ἱερὸν γὰρ ἡγοῦνται τὸ τοιοῦτον ὄχημα τῷ βασιλεῖ καὶ πατρὶ τῶν θεῶν ἐπιπεφημισμένον. ἔκ τε δὴ τούτου διεβλήθη πρὸς τοὺς πολίτας οὐκ εἰθισμένους ἐντρυφᾶσθαι, καὶ δευτέραν ἔλαβεν αἰτίαν ἐνιστάμενος νόμῳ διοικίζοντι τήν πόλιν. εἰσηγοῦντο γὰρ οἱ δήμαρχοι τόν τε δῆμον καὶ τήν σύγκλητον ἴσα μέρη δύο νεμηθῆναι, καὶ τοὺς μὲν αὐτόθι κατοικεῖν, τοὺς δὲ κλήρῳ λαχόντας εἰς τήν αἰχμάλωτον μεταστῆναι πόλιν, ὡς εὐπορωτέρων ἐσομένων καὶ δυσὶ μεγάλοις καὶ καλοῖς ἄστεσι τήν τε χώραν ὁμοῦ καὶ τήν ἄλλην εὐδαιμονίαν φυλαξόντων. ὁ μὲν οὖν δῆμος ἤδη πολὺς γεγονὼς καὶ ἀχρήματος ἄσμενος ἐδέξατο, καὶ συνεχὴς ἦν τοῖς περὶ τὸ βῆμα θορύβοις αἰτῶν τήν ψῆφον ἡ δὲ βουλὴ καὶ τῶν ἄλλων οἱ κράτιστοι πολιτῶν οὐ διαίρεσιν, ἀλλ’ ἀναίρεσιν ἡγούμενοι τῆς Ῥώμης πολιτεύεσθαι τοὺς δημάρχους καὶ δυσανασχετοῦντες ἐπὶ τόν Κάμιλλον κατέφυγον. κἀκεῖνος ὀρρωδῶν τόν ἀγῶνα προφάσεις ἐνέβαλλε τῷ δήμῳ καὶ ἀσχολίας, δι’ ὧν ἀεὶ τόν νόμον ἐξέκρουεν.", "st": "Cam. 7.1"}, {"sp": "N", "t": "ἦν μὲν οὖν διὰ ταῦτα λυπηρός. ἡ δὲ φανερωτάτη καὶ μεγίστη τῶν ἀπεχθειῶν αὐτῷ πρὸς τόν δῆμον ἐκ τῆς δεκάτης τῶν λαφύρων ὑπῆρξεν, οὐκ ἄλογον, εἰ καὶ μὴ πάνυ δικαίαν ἀρχὴν τῶν πολλῶν λαβόντων. εὔξατο μὲν γὰρ ἐπὶ τοὺς Οὐηΐους, ὡς ἔοικε, βαδίζων, εἰ τήν πόλιν ἕλοι, τῷ θεῷ τούτων τήν δεκάτην καθιερώσειν, ἁλούσης δὲ τῆς πόλεως καὶ διαρπασθείσης, εἴτ’ ὀκνήσας ἐνοχλῆσαι τοῖς πολίταις, εἴτε λήθη τις αὐτὸν ὑπὸ τῶν παρόντων πραγμάτων ἔλαβε τῆς εὐχῆς, περιεῖδεν ὠφεληθέντας. ὕστερον δὲ χρόνῳ τῆς ἀρχῆς ἐκείνης ἤδη πεπαυμένος ἀνήνεγκε περὶ τούτων εἰς τήν σύγκλητον, οἵ τε μάντεις ἤγγελλον ἐπὶ τοῖς ἱεροῖς προφαίνεσθαι θεῶν μῆνιν ἱλασμοῦ καὶ χαριστηρίων δεομένην.", "st": "Cam. 7.5"}, {"sp": "N", "t": "ψηφισαμένης δὲ τῆς βουλῆς τὴν μὲν ὠφέλειαν χαλεπὸν γὰρ ἦν ἀνάδαστον μὴ γενέσθαι, τοὺς δὲ λαβόντας αὐτοὺς σὺν ὅρκῳ τὴν δεκάτην παραφέρειν εἰς μέσον, ἐγίνετο πολλὰ λυπηρὰ καὶ βίαια περὶ τοὺς στρατιώτας, ἀνθρώπους πένητας καὶ πολλὰ πεπονηκότας, ἀναγκαζομένους ὧν ἐκέκτηντο καὶ κατεκέχρηντο μέρος εἰσφέρειν τοσοῦτον. θορυβουμένῳ δ’ ὑπ’ αὐτῶν τῷ Καμίλλῳ καὶ προφάσεως ἀποροῦντι βελτίονος εἰς τὸν ἀτοπώτατον τῶν λόγων συνέβαινε καταφεύγειν, ὁμολογοῦντι ἐπιλαθέσθαι τῆς εὐχῆς, οἱ δ’ ἐχαλέπαινον, εἰ τὰ τῶν πολεμίων δεκατεύσειν εὐξάμενος τότε νῦν δεκατεύει τὰ τῶν πολιτῶν, οὐ μὴν ἀλλὰ πάντων ὅσον ἔδει μέρος εἰσενεγκόντων ἔδοξε κρατῆρα χρυσοῦν κατασκευάσαντας εἰς Δελφοὺς ἀποστεῖλαι. χρυσίου δ’ ἦν σπάνις ἐν τῇ πόλει καὶ τῶν ἀρχόντων ὅθεν ἂν πορισθείη σκοπούντων, αἱ γυναῖκες αὐταὶ καθ’ αὑτὰς βουλευσάμεναι τὸν ὄντα χρυσοῦν ἑκάστῃ περὶ τὸ σῶμα κόσμον ἐπέδωκαν εἰς τὸ ἀνάθημα, σταθμῷ χρυσίου γενόμενον ὀκτὼ ταλάντων, καὶ ταύταις μὲν ἡ σύγκλητος ἀποδιδοῦσα τιμὴν πρέπουσαν ἐψηφίσατο μετὰ θάνατον ὥσπερ ἐπὶ τοῖς ἀνδράσι καὶ ταῖς γυναιξὶ λέγεσθαι τὸν ἄξιον ἔπαινον οὐ γὰρ ἦν εἰθισμένον πρότερον ἐγκωμιάζεσθαι γυναῖκα δημοσίᾳ τελευτήσασαν· ἑλόμενοι δὲ τρεῖς ἄνδρας ἐκ τῶν ἀρίστων θεωρούς καὶ ναῦν μακρὰν εὐανδροῦντι πληρώματι καὶ κόσμῳ πανηγυρικῷ κατασκευάσαντες ἐξέπεμψαν.", "st": "Cam. 8.1"}, {"sp": "N", "t": "ἦν δ’ ἄρα καὶ χειμὼν καὶ γαλήνη θαλάσσης ἀργαλέον, ὡς ἐκείνοις συνέτυχε τότε παρ’ οὐδὲν ἐλθόντας ἀπολέσθαι διαφυγεῖν αὖθις ἀπροσδοκήτως τὸν κίνδυνον. ἐπέπλευσαν γὰρ αὐτοῖς Λιπαρέων τριήρεις περὶ τὰς Αἰόλου νήσους τοῦ πνεύματος ἐκλιπόντος ὡς λῃσταῖς. δεομένων δὲ καὶ προϊσχομένων χεῖρας ἐμβολῆς μὲν ἔσχοντο, τὴν δὲ ναῦν ἀναψάμενοι καὶ καταγαγόντες ἀπεκήρυττον, ἅμα καὶ τὰ χρήματα καὶ τὰ σώματα, πειρατικὰ κρίναντες εἶναι. μόλις δ’ ἑνὸς ἀνδρὸς ἀρετῇ καὶ δυνάμει Τιμησιθέου τοῦ στρατηγοῦ πεισθέντες μεθῆκαν. ὁ δὲ καὶ προσκαθελκύσας ἰδίᾳ πλοῖα παρέπεμψε καὶ συγκαθιέρωσε τὸ ἀνάθημα· δι’ ὃ καὶ τιμὰς ἔσχεν, ἃς εἰκὸς ἦν, ἐν Ῥώμῃ.", "st": "Cam. 8.5"}, {"sp": "N", "t": "τῶν δὲ δημάρχων αὖθις ἐπεγειρόντων τὸν περὶ τοῦ διοικισμοῦ νόμον, ὁ πρὸς Φαλίσκους πόλεμος ἐν καιρῷ παραφανεὶς ἔδωκε τοῖς πρώτοις ἀνδράσιν ἀρχαιρεσιάσαι κατὰ γνώμην καὶ Κάμιλλον ἀποδείξαι μεθ’ ἑτέρων πέντε χιλίαρχον, ὡς τῶν πραγμάτων ἡγεμόνος δεομένων ἀξίωμα καὶ δόξαν μετ’ ἐμπειρίας ἔχοντος. ψηφισαμένου δὲ τοῦ δήμου λαβὼν δύναμιν ὁ Κάμιλλος εἰς τὴν Φαλίσκων ἐνέβαλε· καὶ πόλιν ἐρυμνὴν κατεσκευασμένην πᾶσιν εἰς πόλεμον καλῶς Φαλερίους ἐπολιόρκει, τὸ μὲν ἑλεῖν οὐ μικρὸν ἔργον οὐδὲ χρόνου τοῦ τυχόντος ἡγούμενος, ἄλλως δὲ τρίβειν τοὺς πολίτας καὶ περισπᾶν βουλόμενος, ὡς μὴ σχολάζοιεν οἴκοι καθήμενοι δημαγωγεῖσθαι καὶ στασιάζειν. ἐπιεικῶς γὰρ ἀεὶ φαρμάκῳ τούτῳ χρώμενοι διετέλουν, ὥσπερ ἰατροὶ, τὰ ταρακτικὰ πάθη τῆς πολιτείας ἔξω τρέποντες.", "st": "Cam. 9.1"}, {"sp": "N", "t": "οὕτως δὲ τῆς πολιορκίας κατεφρόνουν οἱ Φαλέριοι τῷ πανταχόθεν ἐξωχυρῶσθαι πιστεύοντες, ὥστε πλὴν τῶν τὰ τείχη φυλαττόντων τοὺς ἄλλους ἐν ἱματίοις κατὰ τὴν πόλιν ἀναστρέφεσθαι, τοὺς δὲ παῖδας αὐτῶν εἴς τε τὰ διδασκαλεῖα φοιτᾶν καὶ παρὰ τὰ τείχη περιπατήσοντας καὶ γυμνασομένους ὑπὸ τοῦ διδασκάλου καταβιβάζεσθαι. κοινῷ γὰρ ἐχρῶντο τῷ διδασκάλῳ, ὥσπερ Ἕλληνες, οἱ Φαλέριοι, βουλόμενοι συντρέφεσθαι καὶ συναγελάζεσθαι μετ’ ἀλλήλων εὐθὺς ἐξ ἀρχῆς τοὺς παῖδας. οὗτος οὖν ὁ διδάσκαλος ἐπιβουλεύων τοῖς Φαλερίοις διὰ τῶν παίδων ἐξῆγεν αὐτοὺς ἡμέρας ἑκάστης ὑπὸ τὸ τεῖχος ἐγγὺς τὸ πρῶτον, εἶτ’ ἀπῆγεν αὖθις εἴσω γυμνασαμένους, ἐκ δὲ τούτου κατὰ μικρὸν ὑπάγων εἴθισε θαρρεῖν ὡς πολλῆς οὔσης ἀδείας, καὶ τέλος ἔχων ἅπαντας εἰς τοὺς προφύλακας τῶν Ῥωμαίων ἐνέβαλε καὶ παρέδωκεν, ἄγειν κελεύσας πρὸς τὸν Κάμιλλον. ἀχθεὶς δὲ καὶ καταστὰς εἰς μέσον ἔλεγε παιδευτὴς μέν εἶναι καὶ διδάσκαλος, τὴν δὲ πρὸς ἐκεῖνον χάριν ἀντὶ τούτων ἑλόμενος τῶν δικαίων, ἥκειν αὐτῷ τὴν πόλιν ἐν τοῖς παισὶ κομίζων, δεινὸν οὖν ἀκούσαντι τὸ ἔργον ἐφάνη Καμίλλῳ· καὶ πρὸς τοὺς παρόντας εἰπών, ὡς χαλεπὸν μέν ἐστι πόλεμος καὶ διὰ πολλῆς ἀδικίας καὶ βιαίων περαινόμενος ἔργων, εἰσὶ δὲ καὶ πολέμων ὅμως τινὲς νόμοι τοῖς ἀγαθοῖς ἀνδράσι, καὶ τὸ νικᾶν οὐχ οὕτω διωκτέον, ὥστε μὴ φεύγειν τὰς ἐκ κακῶν καὶ ἀσεβῶν ἔργων χάριτας ἀρετῇ γὰρ οἰκείᾳ τὸν μέγαν στρατηγόν, οὐκ ἀλλοτρίᾳ θαρροῦντα κακίᾳ χρῆναι στρατεύειν, προσέταξε τοῖς ὑπηρέταις τοῦ μέν ἀνθρώπου καταρρηγνύναι τὰ ἱμάτια καὶ τὰς χεῖρας ὀπίσω περιάγειν, τοῖς δὲ παισὶ διαδοῦναι ῥάβδους καὶ μάστιγας, ὅπως κολάζοντες τὸν προδότην ἐλαύνωσιν εἰς τὴν πόλιν.", "st": "Cam. 10.1"}, {"sp": "N", "t": "ἄρτι δὲ τῶν Φαλερίων ᾐσθημένων τὴν τοῦ διδασκάλου προδοσίαν καὶ τὴν μέν πόλιν, οἷον εἰκὸς, ἐπὶ συμφορᾷ τηλικαύτῃ θρήνου κατέχοντος, ἀνδρῶν δ’ ὁμοῦ καὶ γυναικῶν ἐπὶ τὰ τείχη καὶ τὰς πύλας σὺν οὐδενὶ λογισμῷ φερομένων, προσῆγον οἱ παῖδες τὸν διδάσκαλον γυμνὸν καὶ δεδεμένον προπηλακίζοντες, τὸν δὲ Κάμιλλον σωτῆρα καὶ πατέρα καὶ θεὸν ἀνακαλοῦντες, ὥστε μὴ μόνον τοῖς γονεῦσι τῶν παίδων, ἀλλὰ καὶ τοῖς ἄλλοις πολίταις ταῦθ’ ὁρῶσι θαῦμα τε καὶ πόθον ἐμπεσεῖν τῆς τοῦ Καμίλλου δικαιοσύνης. καὶ συνδραμόντες εἰς ἐκκλησίαν πρέσβεις ἔπεμψαν ἐκείνῳ τὰ καθ’ ἑαυτοὺς ἐπιτρέποντες, οὓς ὁ Κάμιλλος ἀπέστειλεν εἰς Ῥώμην. ἐν δὲ τῇ βουλῇ καταστάντες εἶπον, ὅτι, Ῥωμαῖοι τῆς νίκης τὴν δικαιοσύνην προτιμήσαντες ἐδίδαξαν αὐτοὺς τὴν ἧτταν ἀγαπῆσαι πρὸ τῆς ἐλευθερίας, οὐ τοσοῦτον τῇ δυνάμει λείπεσθαι δοκοῦντας, ὅσον ἡττᾶσθαι τῆς ἀρετῆς ὁμολογοῦντας. ἀποδούσης δὲ τῆς βουλῆς πάλιν ἐκείνῳ τὸ κρῖναι καὶ διαιτῆσαι ταῦτα, χρήματα λαβὼν παρὰ τῶν Φαλερίων καὶ φιλίαν πρὸς ἅπαντας Φαλίσκους θέμενος ἀνεχώρησεν.", "st": "Cam. 10.5"}, {"sp": "N", "t": "οἱ δὲ στρατιῶται διαρπάσειν προσδοκήσαντες τοὺς Φαλερίους, ὡς ἐπανῆλθον εἰς Ῥώμην κεναῖς χερσί, κατηγόρουν τοῦ Καμίλλου πρὸς τοὺς ἄλλους πολίτας ὡς μισοδήμου καὶ φθονήσαντος ὠφεληθῆναι τοῖς πένησιν. ἐπεὶ δὲ τὸν περὶ τοῦ διοικισμοῦ νόμον οἱ δήμαρχοι προθέντες αὖθις ἐπὶ τὴν ψῆφον ἐκάλουν τὸν δῆμον, ὁ δὲ Κάμιλλος οὐδεμιᾶς ἀπεχθείας οὐδὲ παρρησίας φεισάμενος ἐφάνη μάλιστα πάντων ἐκβιαζόμενος τοὺς πολλούς, τὸν μὲν νόμον ἄκοντες ἀπεψηφίσαντο, τὸν δὲ Κάμιλλον δι’ ὀργῆς εἶχον, ὥστε καὶ δυστυχήσαντος αὐτοῦ περὶ τὰ οἰκεῖα τῶν γὰρ υἱῶν ἀπέβαλε τὸν ἕτερον νοσήσαντα μηδὲν οἴκτῳ τῆς ὀργῆς ὑφέσθαι. καίτοι τὸ πάθος οὐ μετρίως ἤνεγκεν ἀνὴρ ἥμερος φύσει καὶ χρηστός, ἀλλὰ τῆς δίκης προγεγραμμένης αὐτῷ διὰ πένθος οἰκούρει καθειργμένος μετὰ τῶν γυναικῶν.", "st": "Cam. 11.1"}, {"sp": "N", "t": "ὁ μὲν οὖν κατήγορος ἦν Λεύκιος Ἀπουλήιος, ἔγκλημα δὲ κλοπῆς περὶ τὰ Τυρρηνικὰ χρήματα, καὶ δῆτα καὶ θύραι τινὲς ἐλέγοντο χαλκαῖ παρ’ αὐτῷ φανῆναι τῶν αἰχμαλώτων, ὁ δὲ δῆμος ἐξηρέθιστο καὶ δῆλος ἦν ἐκ πάσης προφάσεως κατ’ αὐτοῦ τῇ ψήφῳ χρησόμενος. οὕτως οὖν συναγαγὼν τούς τε φίλους καὶ τούς συστρατευσαμένους οὐκ ὀλίγους τὸ πλῆθος ὄντας, ἐδεῖτο μὴ περιιδεῖν αὐτὸν ἀδίκως ἐπ’ αἰτίαις πονηραῖς ὀφλόντα καὶ καταγέλαστον ὑπὸ τῶν ἐχθρῶν γενόμενον. ἐπεὶ δ’ οἱ φίλοι βουλευσάμενοι καὶ διαλεχθέντες ἑαυτοῖς ἀπεκρίναντο, πρὸς μὲν τὴν κρίσιν αὐτῷ μηδὲν οἴεσθαι βοηθήσειν, τὴν δὲ ζημίαν ὀφλόντι συνεκτίσειν, οὐκ ἀνασχόμενος ἔγνω μεταστῆναι καὶ φυγεῖν ἐκ τῆς πόλεως πρὸς ὀργήν. ἀσπασάμενος οὖν τὴν γυναῖκα καὶ τὸν υἱὸν ἐπὶ τῆς οἰκίας προῄει σιωπῇ μέχρι τῆς πύλης· ἐκεῖ δὲ ἐπέστη, καὶ μεταστραφεὶς ὀπίσω καὶ τὰς χεῖρας ἀνατείνας πρὸς τὸ Καπιτώλιον ἐπεύξατο τοῖς θεοῖς, εἰ μὴ δικαίως, ἀλλ’ ὕβρει δήμου καὶ φθόνῳ προπηλακιζόμενος ἐκπίπτει, ταχὺ Ῥωμαίους μετανοῆσαι καὶ πᾶσιν ἀνθρώποις φανεροὺς γενέσθαι δεομένους αὐτοῦ καὶ ποθοῦντας Κάμιλλον.", "st": "Cam. 12.1"}, {"sp": "N", "t": "ἐκεῖνος μὲν οὖν, ὥσπερ ὁ Ἀχιλλεὺς, ἀρὰς θέμενος ἐπὶ τοὺς πολίτας καὶ μεταστὰς ὦφλε τὴν δίκην ἐρήμην, τίμημα μυρίων καὶ πεντακισχιλίων ἀσσαρίων ἔχουσαν.", "st": "Cam. 13.1"}, {"sp": "N", "t": "ὃ γίνεται πρὸς ἀργυρίου λόγον χίλιαι δραχμαὶ καὶ πεντακόσιαι· ἀσσάριον γὰρ ἦν τὸ ἀργύριον, καὶ τὸ δεκάχαλκον οὕτως ἐκαλεῖτο δηνάριον.", "st": "Cam. 13.1b"}, {"sp": "N", "t": "οὐδεὶς δ’ ἔστι Ῥωμαίων, ὃς οὐ νομίζει τὰς εὐχὰς τοῦ Καμίλλου ταχὺ τὴν Δίκην ὑπολαβεῖν, καὶ γενέσθαι τιμωρίαν αὐτῷ τῆς ἀδικίας οὐκ ἡδεῖαν, ἀλλ’ ἀνιαράν, ὀνομαστὴν δὲ καὶ περιβόητον· τοσαύτη περιῆλθε τὴν Ῥώμην νέμεσις, καὶ τοσοῦτον ἄγων φθόρον καὶ κίνδυνον ἅμα μετ’ αἰσχύνης ἐφάνη καιρὸς ἐπὶ τὴν πόλιν, εἴτε τῆς τύχης οὕτω συνελθούσης, εἴτε καὶ θεῶν τινος ἔργον ἔστι μὴ παραμελεῖν ἀρετῆς ἀχαριστουμένης.", "st": "Cam. 13.2"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἔδοξε σημεῖον γεγονέναι κακοῦ μεγάλου προσιόντος ἡ Ἰουλίου τοῦ τιμητοῦ τελευτή· μάλιστα γὰρ δὴ Ῥωμαῖοι σέβονται καὶ νομίζουσιν ἱερὰν τὴν τῶν τιμητῶν ἀρχήν, δεύτερον δὲ πρὸ τῆς Καμίλλου φυγῆς ἀνὴρ οὐκ ἐπιφανὴς μὲν οὐδὲ ἐκ τῆς βουλῆς, ἐπιεικὴς δὲ καὶ χρηστὸς εἶναι δοκῶν, Μᾶρκος Καιδίκιος, ἀνήνεγκε πρὸς τοὺς χιλιάρχους πρᾶγμα φροντίδος ἄξιον. ἔφη γὰρ ἐν τῇ παρῳχημένῃ νυκτὶ καθ’ ὁδὸν βαδίζων, ἣν Καινὴν ὀνομάζουσι, κληθεὶς ὑπό τινος φθεγξαμένου μεταστραφῆναι, καὶ θεάσασθαι μὲν οὐδένα, φωνῆς δὲ μείζονος ἢ κατ’ ἀνθρωπίνην ἀκοῦσαι τάδε λεγούσης· ἄγε, Μᾶρκε Καιδίκιε, λέγε πρὸς τοὺς ἄρχοντας ἕωθεν ἐλθὼν ὀλίγου χρόνου Γαλάτας προσδέχεσθαι. ταῦτ’ ἀκούσαντες οἱ χιλίαρχοι γέλωτα καὶ παιδιὰν ἐποιοῦντο. καὶ μετ’ ὀλίγον συνέβη τὰ περὶ Κάμιλλον.", "st": "Cam. 14.1"}, {"sp": "N", "t": "οἱ δὲ Γαλάται τοῦ Κελτικοῦ γένους ὄντες ὑπὸ πλήθους λέγονται τὴν αὑτῶν ἀπολιπόντες, οὐκ οὖσαν αὐτάρκη τρέφειν ἅπαντας, ἐπὶ γῆς ζήτησιν ἑτέρας ὁρμῆσαι· μυριάδες δὲ πολλαὶ γενόμενοι νέων ἀνδρῶν καὶ μαχίμων, ἔτι δὲ πλείους παίδων καὶ γυναικῶν ἄγοντες, οἱ μὲν ἐπὶ τὸν βόρειον Ὠκεανὸν ὑπερβαλόντες τὰ Ῥιπαῖα ὄρη ῥυῆναι καὶ τὰ ἔσχατα τῆς Εὐρώπης κατασχεῖν, οἱ δὲ μεταξὺ Πυρρήνης ὄρους καὶ τῶν Ἄλπεων ἱδρυθέντες ἐγγὺς Σενώνων καὶ Κελτορίων κατοικεῖν χρόνον πολύν ὀψὲ δ’ οἴνου γευσάμενοι τότε πρῶτον ἐξ Ἰταλίας διακομισθέντος οὕτως ἄρα θαυμάσαι τὸ πόμα καὶ πρὸς τὴν καινότητα τῆς ἡδονῆς ἔκφρονες γενέσθαι πάντες, ὥστε ἀράμενοι τὰ ὅπλα καὶ γενεὰς ἀναλαβόντες ἐπὶ τὰς Ἄλπεις φέρεσθαι καὶ ζητεῖν ἐκείνην τὴν γῆν, ἣ τοιοῦτον καρπὸν ἀναδίδωσι, τὴν δ’ ἄλλην ἄκαρπον ἡγεῖσθαι καὶ ἀνήμερον.", "st": "Cam. 15.1"}, {"sp": "N", "t": "ὁ δ’ εἰσαγαγὼν τὸν οἶνον πρὸς αὐτοὺς καὶ παροξύνας ἐπὶ τὴν Ἰταλίαν μάλιστα καὶ πρῶτος Ἄρρων λέγεται γενέσθαι Τυρρηνός, ἀνὴρ ἐπιφανὴς καὶ φύσει μὲν οὐ πονηρός, συμφορᾷ δὲ τοιαύτῃ χρησάμενος. ἦν ἐπίτροπος παιδὸς ὀρφανοῦ πλούτῳ τε πρώτου τῶν πολιτῶν καὶ θαυμαζομένου κατ’ εἶδος, ὄνομα Λουκούμωνος. οὗτος ἐκ νέου παρὰ τῷ Ἄρρωνι δίαιταν εἶχε, καὶ μειράκιον ὢν οὐκ ἀπέλιπε τὴν οἰκίαν, ἀλλὰ προσεποιεῖτο χαίρειν συνὼν ἐκείνῳ. καὶ πολύν χρόνον ἐλάνθανε διεφθαρκὼς αὐτοῦ τὴν γυναῖκα καὶ διεφθαρμένος ὑπ’ ἐκείνης· ἤδη δὲ πόρρω τοῦ πάθους ἀμφοτέρων γεγονότων καὶ μήτ’ ἀφεῖναι τὴν ἐπιθυμίαν μήτε κρύπτειν ἔτι δυναμένων, ὁ μὲν νεανίσκος ἐπεχείρει φανερῶς ἀποσπάσας ἔχειν τὴν ἄνθρωπον, ὁ δ’ ἀνὴρ ἐπὶ δίκην ἐλθὼν καὶ κρατούμενος πλήθει φίλων καὶ χρημάτων δαπάναις ὑπὸ τοῦ Λουκούμωνος ἐξέλιπε τὴν ἑαυτοῦ· καὶ πυθόμενος τὰ τῶν Γαλατῶν ἧκεν εἰς αὐτοὺς καὶ καθηγήσατο τῆς εἰς τὴν Ἰταλίαν στρατείας.", "st": "Cam. 15.3"}, {"sp": "N", "t": "οἱ δ’ ἐμβαλόντες εὐθὺς ἐκράτουν τῆς χώρας ὅσην τὸ παλαιὸν οἱ Τυρρηνοὶ κατεῖχον, ἀπὸ τῶν Ἄλπεων ἐπ’ ἀμφοτέρας καθήκουσαν τὰς θαλάσσας, ὡς καὶ τοὔνομα μαρτυρεῖ τῷ λόγῳ, τὴν μὲν γὰρ βόρειον θάλατταν Ἀδρίαν καλοῦσιν ἀπὸ Τυρρηνικῆς πόλεως Ἀδρίας, τὴν δὲ πρὸς νότον κεκλιμένην ἄντικρυς Τυρρηνικὸν πέλαγος. πᾶσα δ’ ἐστὶ δενδρόφυτος αὕτη καὶ θρέμμασιν εὔβοτος καὶ κατάρρυτος ποταμοῖς. καὶ πόλεις εἶχεν ὀκτωκαίδεκα καλὰς καὶ μεγάλας καὶ κατεσκευασμένας πρός τε χρηματισμὸν ἐργατικῶς καὶ πρὸς δίαιταν πανηγυρικῶς, ἃς οἱ Γαλάται τοὺς Τυρρηνοὺς ἐκβαλόντες αὐτοὶ κατέσχον. ἀλλὰ ταῦτα μὲν ἐπράχθη συχνῷ τινι χρόνῳ πρότερον.", "st": "Cam. 16.1"}, {"sp": "N", "t": "οἱ δὲ Γαλάται τότε πρὸς πόλιν Τυρρηνίδα Κλούσιον στρατεύσαντες ἐπολιόρκουν, οἱ δὲ Κλουσῖνοι καταφυγόντες ἐπὶ τοὺς Ῥωμαίους ᾐτήσαντο πρέσβεις παρ’ αὐτῶν καὶ γράμματα πρὸς τοὺς βαρβάρους. ἐπέμφθησαν δὲ τοῦ Φαβίων γένους τρεῖς ἄνδρες εὐδόκιμοι καὶ τιμὰς μεγάλας ἔχοντες ἐν τῇ πόλει. τούτους ἐδέξαντο μὲν οἱ Γαλάται φιλανθρώπως διὰ τὸ τῆς Ῥώμης ὄνομα, καὶ παυσάμενοι τῆς πρὸς τὰ τείχη μάχης εἰς λόγους συνῆλθον. πυνθανομένων δ’ αὐτῶν, ὅ τι παθόντες ὑπὸ Κλουσίνων ἥκοιεν ἐπὶ τὴν πόλιν, γελάσας ὁ βασιλεὺς τῶν Γαλατῶν Βρέννος, ἀδικοῦσιν ἡμᾶς, ἔφη, Κλουσῖνοι γῆν καὶ χώραν ὀλίγην μὲν γεωργεῖν δυνάμενοι, πολλὴν δὲ κατέχειν ἀξιοῦντες καὶ μὴ μεταδιδόντες ἡμῖν ξένοις οὖσι καὶ πολλοῖς καὶ πένησι. ταῦτα δ’ ἄρα καὶ ὑμᾶς ἠδίκουν, ὦ Ῥωμαῖοι, πρότερον μὲν Ἀλβανοὶ καὶ Φιδηνᾶται καὶ Ἀρδεᾶται, νῦν δὲ Οὐήϊοι καὶ Καπηνᾶται καὶ πολλοὶ Φαλίσκων καὶ Οὐολούσκων· ἐφ’ οὓς ὑμεῖς στρατεύοντες, ἐὰν μὴ μεταδιδῶσιν ὑμῖν τῶν ἀγαθῶν, ἀνδραποδίζεσθε καὶ λεηλατεῖτε καὶ κατασκάπτετε τὰς πόλεις αὐτῶν, οὐδὲν οὐδὲ ὑμεῖς γε δεινὸν οὐδὲ ἄδικον ποιοῦντες, ἀλλὰ τῷ πρεσβυτάτῳ τῶν νόμων ἀκολουθοῦντες, ὃς τῷ κρείττονι τὰ τῶν ἡττόνων δίδωσιν ἀρχόμενος ἀπὸ τοῦ θεοῦ καὶ τελευτῶν εἰς τὰ θηρία, καὶ γὰρ τούτοις ἐκ φύσεως ἔνεστι τὸ ζητεῖν πλέον ἔχειν τὰ κρείττονα τῶν ὑποδεεστέρων. Κλουσίνους δὲ παύσασθε πολιορκουμένους οἰκτείροντες, ὡς μὴ καὶ Γαλάτας διδάξητε χρηστοὺς καὶ φιλοικτίρμονας γενέσθαι τοῖς ὑπὸ Ῥωμαίων ἀδικουμένοις.", "st": "Cam. 17.1"}, {"sp": "N", "t": "ἐκ τούτων τῶν λόγων ἔγνωσαν οἱ Ῥωμαῖοι τὸν Βρέννον ἀσυμβάτως ἔχοντα, καὶ παρελθόντες εἰς τὸ Κλούσιον ἐθάρρυνον καὶ παρώρμων τοὺς ἄνδρας ἐπεξελθεῖν τοῖς βαρβάροις μετ’ αὐτῶν, εἴτε τὴν ἐκείνων ἀλκὴν καταμαθεῖν εἴτε τὴν ἑαυτῶν ἐπιδείξασθαι θέλοντες. ἐκδρομῆς δὲ τῶν Κλουσίνων καὶ μάχης παρὰ τὰ τείχη γενομένης εἷς τῶν Φαβίων, Κόιντος Ἄμβουστος, ἵππον ἔχων ἐλήλασεν ἀντίος ἀνδρὶ μεγάλῳ καὶ καλῷ Γαλάτῃ πολὺ προϊππεύοντι τῶν ἄλλων, ἀγνοηθεὶς ἐν ἀρχῇ διὰ τὸ τὴν σύνοδον ὀξεῖαν γενέσθαι καὶ τὰ ὅπλα περιλάμποντα τὴν ὄψιν ἀποκρύπτειν. ὡς δ’ ἐπικρατήσας τῇ μάχῃ καὶ καταβαλὼν ἐσκύλευε τὸν ἄνθρωπον, γνωρίσας ὁ Βρέννος αὐτὸν ἐπεμαρτύρατο θεούς, ὡς παρὰ τὰ κοινὰ καὶ νενομισμένα πᾶσιν ἀνθρώποις ὅσια καὶ δίκαια πρεσβευτοῦ μὲν ἥκοντος, πολέμια δὲ εἰργασμένου. καταπαύσας δὲ τὴν μάχην αὐτίκα Κλουσίνους μὲν εἴα χαίρειν, ἐπὶ δὲ τὴν Ῥώμην τὸν στρατὸν ἦγεν. οὐ βουλόμενος δὲ δόξαι τὴν ἀδικίαν αὐτοῖς ὥσπερ ἀσμένοις γεγονέναι καὶ δεομένοις προφάσεως, ἔπεμψεν ἐξαιτῶν ἐπὶ τιμωρίᾳ τὸν ἄνδρα καὶ προῆγεν ἅμα σχολαίως.", "st": "Cam. 17.5"}, {"sp": "N", "t": "ἐν δὲ Ῥώμῃ τῆς βουλῆς συναχθείσης ἄλλοι τε πολλοὶ τοῦ Φαβίου κατηγόρουν, καὶ τῶν ἱερέων οἱ καλούμενοι Φητιαλεῖς ἐνῆγον ἐπιθειάζοντες καὶ κελεύοντες τὸ τῶν πεπραγμένων ἄγος τήν σύγκλητον εἰς ἕνα τὸν αἴτιον τρέψασαν ὑπὲρ τῶν ἄλλων ἀφοσιώσασθαι.", "st": "Cam. 18.1"}, {"sp": "N", "t": "τούτους τοὺς Φητιαλεῖς Πομπίλιος Νομᾶς, βασιλέων ἡμερώτατος γενόμενος καὶ δικαιότατος, κατέστησε φύλακας μὲν εἰρήνης, ἐπιγνώμονας δὲ καὶ βεβαιωτὰς αἰτιῶν, αἳ σὺν δίκῃ πόλεμον συνάπτουσι.", "st": "Cam. 18.1b"}, {"sp": "N", "t": "τῆς δὲ βουλῆς ἐπὶ τὸν δῆμον ἀνενεγκαμένης τὸ πρᾶγμα καὶ τῶν ἱερέων ὅμοια τοῦ Φαβίου κατηγορούντων, οὕτω περιύβρισαν οἱ πολλοὶ τὰ θεῖα καὶ κατεγέλασαν, ὥστε καὶ χιλίαρχον ἀποδεῖξαι τὸν Φάβιον μετὰ τῶν ἀδελφῶν, οἱ δὲ Κελτοὶ πυθόμενοι ταῦτα καὶ χαλεπῶς φέροντες οὐδὲν ἐμποδὼν ἐποιοῦντο τῆς σπουδῆς, ἀλλ’ ἐχώρουν παντὶ τάχει· καὶ πρὸς τὸ πλῆθος αὐτῶν καὶ τήν λαμπρότητα τῆς παρασκευῆς καὶ βίαν καὶ θυμὸν ἐκπεπληγμένων τῶν διὰ μέσου, καὶ τήν τε χώραν ἀπολωλέναι πᾶσαν ἤδη καὶ τὰς πόλεις εὐθὺς ἀπολεῖσθαι δοκούντων, παρ’ ἐλπίδας οὐδὲν ἠδίκουν οὐδ’ ἐλάμβανον ἐκ τῶν ἀγρῶν, ἀλλὰ καὶ παρὰ τὰς πόλεις ἐγγὺς παρεξιόντες ἐβόων ἐπὶ τήν Ῥώμην πορεύεσθαι καὶ μόνοις πολεμεῖν Ῥωμαίοις, τοὺς δ’ ἄλλους φίλους ἐπίστασθαι.", "st": "Cam. 18.2"}, {"sp": "N", "t": "τοιαύτῃ δὲ χρωμένων ὁρμῇ τῶν βαρβάρων ἐξῆγον οἱ χιλίαρχοι τοὺς Ῥωμαίους ἐπὶ τὸν ἀγῶνα, πλήθει μὲν οὐκ ἐνδεεῖς ἐγένοντο γὰρ ὁπλῖται τετρακισμυρίων οὐκ ἐλάσσους, ἀνασκήτους δὲ τοὺς πολλοὺς καὶ τότε πρῶτον ἁπτομένους ὅπλων. ἔτι δ’ ἐξημέλητο τὰ τῶν θεῶν αὐτοῖς οὔτε καλλιερήσασιν οὔτε μάντεις ἃ πρὸ κινδύνου καὶ μάχης εἰκὸς ἦν ἐρομένοις. οὐδενὸς δὲ ἧττον ἐπετάραττεν ἡ πολυαρχία τὰ πραττόμενα. καίτοι πρότερόν γε καὶ πρὸς ἐλάττονας ἀγῶνας εἵλοντο πολλάκις μονάρχους, οὓς δικτάτορας καλοῦσιν, οὐκ ἀγνοοῦντες, ὅσον ἐστὶν εἰς ἐπισφαλῆ καιρὸν ὄφελος μιᾷ χρωμένους γνώμῃ πρὸς ἀνυπεύθυνον ἀρχὴν ἐν χερσὶ τήν δίκην ἔχουσαν εὐτακτεῖν. οὐχ ἥκιστα δὲ καὶ Κάμιλλος ἀγνωμονηθεὶς ἔβλαψε τὰ πράγματα, τοῦ μὴ πρὸς χάριν μηδὲ κολακεύοντας ἄρχειν φοβεροῦ γενομένου.", "st": "Cam. 18.4"}, {"sp": "N", "t": "προελθόντες οὖν ἀπὸ τῆς πόλεως σταδίους ἐνενήκοντα παρὰ τὸν Ἀλίαν ποταμὸν ηὐλίσθησαν, οὐ πόρρω τοῦ στρατοπέδου τῷ Θύμβριδι συμφερόμενον. ἐνταῦθα δὲ τῶν βαρβάρων ἐπιφανέντων αἰσχρῶς ἀγωνισάμενοι δι’ ἀταξίαν ἐτράποντο. καὶ τὸ μὲν ἀριστερὸν κέρας εὐθὺς ἐμβαλόντες εἰς τὸν ποταμὸν οἱ Κελτοὶ διέφθειραν τὸ δὲ δεξιὸν ὑπεκκλῖναν τήν ἐπιφορὰν ἐκ τοῦ πεδίου πρὸς τοὺς λόφους ἧττον ἐξεκόπη καὶ διεξέπεσον ἀπὸ τούτων εἰς τήν πόλιν οἱ πολλοί, τοῖς δ’ ἄλλοις, ὅσοι τῶν πολεμίων ἀπειπόντων πρὸς τὸν φόνον ἐσώθησαν, εἰς Οὐηΐους αἱ φυγαὶ διὰ νυκτὸς ἦσαν, ὡς τῆς Ῥώμης οἰχομένης καὶ τῶν ἐκεῖ πάντων ἀπολωλότων.", "st": "Cam. 18.7"}, {"sp": "N", "t": "ἐγένετο δ’ ἡ μάχη μετὰ τροπὰς θερινὰς περὶ τήν πανσέληνον, ᾗ καὶ πρότερον ἡμέρᾳ μέγα πάθος συνέβη τὸ περὶ τοὺς Φαβίους· τριακόσιοι γὰρ ἐκ τοῦ γένους ἄνδρες ὑπὸ Τυρρηνῶν ἀνῃρέθησαν. ἐκράτησε δὲ τήν ἡμέραν ἀπὸ τῆς δευτέρας ἥττης Ἀλιάδα μέχρι νῦν καλεῖσθαι διὰ τὸν ποταμόν.", "st": "Cam. 19.1"}, {"sp": "N", "t": "περὶ δ’ ἡμερῶν ἀποφράδων εἴτε χρὴ τίθεσθαί τινας, εἴτε ὀρθῶς Ἡράκλειτος ἐπέπληξεν Ἡσιόδῳ τὰς μὲν ἀγαθὰς ποιουμένῳ, τὰς δὲ φαύλας, ὡς ἀγνοοῦντι φύσιν ἡμέρας ἁπάσης μίαν οὖσαν, ἑτέρωθι διηπόρηται. τῇ δ’ ὑποκειμένῃ γραφῇ τὸ μνημονεῦσαι παραδειγμάτων ὀλίγων ἴσως ἂν ἁρμόσειε. τοῦτο μὲν τοίνυν Βοιωτοῖς Ἱπποδρομίου μηνός, ὡς δ’ Ἀθηναῖοι καλοῦσιν Ἑκατομβαιῶνος, ἱσταμένου πέμπτῃ δύο λαβεῖν συνέβη νίκας ἐπιφανεστάτας, αἷς τοὺς Ἕλληνας ἠλευθέρωσαν, τήν τε περὶ Λεῦκτρα καὶ τήν ἐπὶ Κερησσῷ ταύτης πρότερον ἔτεσι πλείοσιν ἢ διακοσίοις, ὅτε Λατταμύαν καὶ Θεσσαλοὺς ἐνίκησαν. τοῦτο δ’ αὖ πάλιν Πέρσαι μηνὸς Βοηδρομιῶνος ἕκτῃ μὲν ἐν Μαραθῶνι, τρίτῃ δ’ ἐν Πλαταιαῖς ἅμα καὶ περὶ Μυκάλην ἡττήθησαν ὑπὸ τῶν Ἑλλήνων, πέμπτῃ δὲ φθίνοντος ἐν Ἀρβήλοις. οἱ δ’ Ἀθηναῖοι καὶ τήν περὶ Νάξον ἐνίκων ναυμαχίαν, ἧς Χαβρίας ἐστρατήγει, τοῦ Βοηδρομιῶνος περὶ τήν πανσέληνον, ἐν δὲ Σαλαμῖνι περὶ τὰς εἰκάδας, ὡς ἡμῖν ἐν τῷ Περὶ ἡμερῶν ἀποδέδεικται. ἐνήνοχε δὲ καὶ ὁ Θαργηλιὼν μὴν τοῖς βαρβάροις ἐπιδήλως ἀτυχίας· καὶ γὰρ Ἀλέξανδρος ἐπὶ Γρανικῷ τοὺς βασιλέως στρατηγοὺς Θαργηλιῶνος ἐνίκησε, καὶ Καρχηδόνιοι περὶ Σικελίαν ὑπὸ Τιμολέοντος ἡττῶντο τῇ ἑβδόμῃ φθίνοντος, περὶ ἣν δοκεῖ καὶ τὸ Ἴλιον ἁλῶναι, Θαργηλιῶνος, ὡς Ἔφορος καὶ Καλλισθένης καὶ Δαμάστης καὶ Φύλαρχος ἱστορήκασιν. ἀνάπαλιν δ’ ὁ Μεταγειτνιών, ὃν Βοιωτοὶ Πάνεμον καλοῦσιν, τοῖς Ἕλλησιν οὐκ εὐμενὴς γέγονε. τούτου γὰρ τοῦ μηνὸς ἑβδόμῃ καὶ τήν ἐν Κρανῶνι μάχην ἡττηθέντες ὑπ’ Ἀντιπάτρου τελέως ἀπώλοντο, καὶ πρότερον ἐν Χαιρωνείᾳ μαχόμενοι πρὸς Φίλιππον ἠτύχησαν. τῆς δ’ αὐτῆς ἡμέρας ταύτης ἐν τῷ Μεταγειτνιῶνι κατὰ τὸν αὐτὸν ἐνιαυτὸν οἱ μετ’ Ἀρχιδάμου διαβάντες εἰς Ἰταλίαν ὑπὸ τῶν ἐκεῖ βαρβάρων διεφθάρησαν. Καρχηδόνιοι δὲ τὴν ἐνάτην φθίνοντος ὡς τὰ πλεῖστα καὶ μέγιστα τῶν ἀτυχημάτων αὐτοῖς ἀεὶ φέρουσαν παραφυλάττουσιν.", "st": "Cam. 19.2"}, {"sp": "N", "t": "οὐκ ἀγνοῶ δ’ ὅτι περὶ τὸν τῶν μυστηρίων καιρὸν αὖθις Θῆβαί τε κατεσκάφησαν ὑπὸ Ἀλεξάνδρου, καὶ μετὰ ταῦτα φρουρὰν Ἀθηναῖοι Μακεδόνων ἐδέξαντο περὶ αὐτὴν τήν εἰκάδα τοῦ Βοηδρομιῶνος, ᾗ τὸν μυστικὸν Ἴακχον ἐξάγουσιν. ὁμοίως δὲ Ῥωμαῖοι τῆς αὐτῆς ἡμέρας πρότερον μὲν ὑπὸ Κίμβρων τὸ μετὰ Καιπίωνος ἀπέβαλον στρατόπεδον, ὕστερον δὲ Λουκούλλου στρατηγοῦντος Ἀρμενίους καὶ Τιγράνην ἐνίκησαν. Ἄτταλος δ’ ὁ βασιλεὺς καὶ Πομπήιος Μᾶγνος ἐν τοῖς ἑαυτῶν γενεθλίοις ἀπέθανον. καὶ ὅλως ἐστὶ πολλοὺς ἐπ’ ἀμφότερα ταῖς αὐταῖς χρησαμένους ἀποδεῖξαι περιόδοις.", "st": "Cam. 19.7"}, {"sp": "N", "t": "ἀλλὰ Ῥωμαίοις αὕτη μία τῶν μάλιστα ἀποφράδων ἐστί, καὶ δι’ αὐτὴν ἑκάστου μηνὸς ἕτεραι δύο, τῆς πρὸς τὸ συμβὰν εὐλαβείας καὶ δεισιδαιμονίας ἐπὶ πλεῖον, ὥσπερ εἴωθε, ῥυείσης. ταῦτα μὲν οὖν ἐν τῷ Περὶ αἰτίων Ῥωμαϊκῶν ἐπιμελέστερον διῄρηται.", "st": "Cam. 19.8"}, {"sp": "N", "t": "μετὰ δὲ τὴν μάχην ἐκείνην εἰ μὲν εὐθὺς ἐπηκολούθησαν οἱ Γαλάται τοῖς φεύγουσιν, οὐδὲν ἂν ἐκώλυσε τὴν Ῥώμην ἄρδην ἀναιρεθῆναι καὶ πάντας ἀπολέσθαι τοὺς ἐν αὐτῇ καταλειφθέντας· τοσοῦτον οἱ φεύγοντες ἐνειργάζοντο δεῖμα τοῖς ὑποδεχομένοις, καὶ τοσαύτης πάλιν ἐνεπίμπλαντο ταραχῆς καὶ παραφροσύνης. νυνὶ δ’ ἀπιστίᾳ τοῦ μεγέθους οἱ βάρβαροι τῆς νίκης καὶ πρὸς εὐπάθειαν ἐκ τοῦ περιχαροῦς ἅμα καὶ νεμήσεις τῶν ἑαλωκότων ἐν τῷ στρατοπέδῳ χρημάτων τραπόμενοι, τῷ μὲν ἐκπίπτοντι τῆς πόλεως ὄχλῳ ῥᾳστώνην φυγῆς παρέσχον, ἐλπίσαι δ’ ἔτι καὶ παρασκευάσασθαι τοῖς ὑπομένουσι τὴν γὰρ ἄλλην πόλιν προέμενοι τὸ Καπιτώλιον ἐφράξαντο βέλεσι καὶ διατειχίσμασιν. ἐν πρώτοις δὲ τῶν ἱερῶν ἃ μὲν εἰς τὸ Καπιτώλιον ἀνεσκευάσαντο, τὸ δὲ πῦρ τῆς Ἑστίας αἱ παρθένοι μετὰ τῶν ἱερῶν ἔφευγον ἁρπασάμεναι.", "st": "Cam. 20.1"}, {"sp": "N", "t": "καίτοι τινὲς οὐδὲν εἶναι τὸ φρουρούμενον ὑπ’ αὐτῶν ἕτερον ἢ πῦρ ἄφθιτον ἱστοροῦσι, Νομᾶ τοῦ βασιλέως καταστήσαντος ὡς ἀρχὴν ἁπάντων σέβεσθαι. κινητικώτατον γὰρ ἐν τῇ φύσει τοῦτο· κίνησις δέ τις ἢ σύν τινι κινήσει πάντως ἡ γένεσις· τὰ δ’ ἄλλα τῆς ὕλης μόρια θερμότητος ἐπιλιπούσης ἀργὰ κείμενα καὶ νεκροῖς ἐοικότα ποθεῖ τὴν τοῦ πυρὸς δύναμιν, ὡς ψυχήν, καὶ προσελθούσης ἁμῶς γέ πως ἐπὶ τὸ δρᾶν τι καὶ πάσχειν τρέπεται, τοῦτ’ οὖν ἅτε δὴ περιττὸν ἄνδρα τὸν Νομᾶν καὶ λόγον ἔχοντα ταῖς Μούσαις συνεῖναι διὰ σοφίαν ἐξοσιῶσαι καὶ φρουρεῖν ἀκοίμητον ἐν εἰκόνι τῆς τὰ πάντα κοσμούσης ἀιδίου δυνάμεως. οἱ δὲ τὸ μὲν πῦρ, ὥσπερ παρ’ Ἕλλησι, πρὸ ἱερῶν αἴθεσθαι καθάρσιον, ἄλλα δὲ τὰ ἐντὸς ἀθέατα κρύπτεσθαι πᾶσι, πλὴν ταύταις ταῖς παρθένοις, ἃς Ἑστιάδας ἐπονομάζουσι· καὶ πλεῖστος μὲν λόγος κατεῖχε τὸ Τρωικὸν ἐκεῖνο Παλλάδιον ἀποκεῖσθαι δι’ Αἰνείου κομισθὲν εἰς Ἰταλίαν. εἰσὶ δ’ οἱ τὰ Σαμοθρᾴκια μυθολογοῦντες Δάρδανον μὲν εἰς Τροίαν ἐξενεγκάμενον ὀργιάσαι καὶ καθιερῶσαι κτίσαντα τὴν πόλιν, Αἰνείαν δὲ περὶ τὴν ἅλωσιν ἐκκλέψαντα διασῶσαι μέχρι τῆς ἐν Ἰταλίᾳ κατοικήσεως. οἱ δὲ προσποιούμενοί πλέον ἐπίστασθαι τι περὶ τούτων δύο φασὶν οὐ μεγάλους ἀποκεῖσθαι πίθους, ὧν τὸν μὲν ἀνεῳγότα καὶ κενὸν, τὸν δὲ πλήρη καὶ κατασεσημασμένον, ἀμφοτέρους δὲ ταῖς παναγέσι μόναις παρθένοις ὁρατούς εἶναι. ἄλλοι δὲ τούτους διεψεῦσθαι νομίζουσι τῷ τὰ πλεῖστα τῶν ἱερῶν τότε τὰς κόρας ἐμβαλούσας εἰς πίθους δύο κρύψαι κατὰ γῆς ὑπὸ τὸν νεὼν τοῦ Κυρίνου, καὶ τὸν τόπον ἐκεῖνον ἔτι καὶ νῦν τῶν Πιθίσκων φέρεσθαι τὴν ἐπωνυμίαν.", "st": "Cam. 20.4"}, {"sp": "N", "t": "τὰ δὲ κυριώτατα καὶ μέγιστα τῶν ἱερῶν αὗται λαβοῦσαι φυγῇ παρὰ τὸν ποταμὸν ἐποιοῦντο τὴν ἀποχώρησιν. ἐνταῦθα Λεύκιος Ἀλβίνιος ἀνὴρ δημοτικὸς ἐν τοῖς φεύγουσιν ἔτυχε τέκνα νήπια καὶ γυναῖκα μετὰ χρημάτων ἀναγκαίων ἐφ’ ἁμάξης ὑπεκκομίζων. ὡς δ’ εἶδε τὰς παρθένους ἐν τοῖς κόλποις φερούσας τὰ τῶν θεῶν ἱερά θεραπείας ἐρήμους παραπορευομένας καὶ κακοπαθούσας, ταχὺ τὴν γυναῖκα μετὰ τῶν παίδων καὶ τῶν χρημάτων καθελὼν ἀπὸ τῆς ἁμάξης ἐκείναις παρέδωκεν ἐπιβῆναι καὶ διαφυγεῖν εἴς τινα τῶν Ἑλληνίδων πόλεων. τὴν μὲν οὖν Ἀλβινίου πρὸς τὸ θεῖον εὐλάβειαν καὶ τιμὴν ἐν τοῖς ἐπισφαλεστάτοις καιροῖς ἐκφανῆ γενομένην οὐκ ἄξιον ἦν ἀμνημόνευτον παρελθεῖν.", "st": "Cam. 21.1"}, {"sp": "N", "t": "οἱ δὲ τῶν ἄλλων θεῶν ἱερεῖς οἵ τε γηραιοὶ τῶν ὑπατικῶν καὶ θριαμβικῶν ἀνδρῶν τὴν μὲν πόλιν ἐκλιπεῖν οὐχ ὑπέμειναν, ἱερὰς δὲ καὶ λαμπρὰς ἀναλαβόντες ἐσθῆτας, ἐξηγουμένου Φαβίου τοῦ ἀρχιερέως, ἐπευξάμενοι τοῖς θεοῖς, ὡς ἑαυτοὺς ὑπὲρ τῆς πατρίδος τῷ δαίμονι καθιεροῦντες, ἐπὶ τῶν ἐλεφαντίνων δίφρων ἐν ἀγορᾷ ἐκάθηντο κεκοσμημένοι, τὴν ἐπιοῦσαν τύχην ὑπομένοντες.", "st": "Cam. 21.1b"}, {"sp": "N", "t": "τρίτῃ δ’ ἀπὸ τῆς μάχης ἡμέρᾳ παρῆν ὁ Βρέννος ἄγων ἐπὶ τὴν πόλιν τὸ στράτευμα· καὶ τάς τε πύλας εὑρὼν ἀνεῳγμένας καὶ τὰ τείχη φυλάκων ἔρημα, πρῶτον μὲν ἔδεισεν ἐνέδραν καὶ δόλον, ἀπιστῶν οὕτω παντάπασιν ἀπειρηκέναι τοὺς Ῥωμαίους, ἐπεὶ δ’ ἔγνω τὸ ἀληθές, εἰσελάσας διὰ τῆς Κολλίνης πύλης εἷλε τὴν Ῥώμην ἑξήκοντα καὶ τριακοσίων ἐτῶν πλείονα βραχὺ χρόνον ἀπὸ τῆς κτίσεως ἔχουσαν, εἴ τῳ πιστόν ἀποσῴζεσθαί τινα τῶν χρόνων ἀκρίβειαν, οἷς καὶ περὶ νεωτέρων ἄλλων ἀμφισβήτησιν ἡ σύγχυσις ἐκείνη παρέσχε. τοῦ μέντοι πάθους αὐτοῦ καὶ τῆς ἁλώσεως ἔοικεν ἀμυδρά τις εὐθὺς εἰς τὴν Ἑλλάδα φήμη διελθεῖν. Ἡρακλείδης γὰρ ὁ Ποντικὸς οὐ πολὺ τῶν χρόνων ἐκείνων ἀπολειπόμενος ἐν τῷ Περὶ ψυχῆς συγγράμματί φησιν ἀπὸ τῆς ἑσπέρας λόγον κατασχεῖν, ὡς στρατὸς ἐξ Ὑπερβορέων ἐλθὼν ἔξωθεν ᾑρήκοι πόλιν Ἑλληνίδα Ῥώμην, ἐκεῖ που κατῳκημένην περὶ τὴν μεγάλην θάλασσαν. οὐκ ἂν οὖν θαυμάσαιμι μυθώδη καὶ πλασματίαν ὄντα τὸν Ἡρακλείδην ἀληθεῖ λόγῳ τῷ περὶ τῆς ἁλώσεως ἐπικομπάσαι τοὺς Ὑπερβορέους καὶ τὴν μεγάλην θάλατταν. Ἀριστοτέλης δὲ ὁ φιλόσοφος τὸ μὲν ἁλῶναι τὴν πόλιν ὑπὸ Κελτῶν ἀκριβῶς δῆλός ἐστιν ἀκηκοώς, τὸν δὲ σώσαντα Λεύκιον εἶναί φησιν ἦν δὲ Μᾶρκος, οὐ Λεύκιος, ὁ Κάμιλλος. ἀλλὰ ταῦτα μὲν εἰκασμῷ λέλεκται.", "st": "Cam. 22.1"}, {"sp": "N", "t": "κατασχὼν δὲ τὴν Ῥώμην ὁ Βρέννος τῷ μὲν Καπιτωλίῳ φρουρὰν περιέστησεν, αὐτὸς δὲ καταβαίνων δι’ ἀγορᾶς ἐθαύμαζε τοὺς προκαθημένους ἄνδρας ἐν κόσμῳ καὶ σιωπῇ θεώμενος, ὡς οὔθ’ ὑπεξανέστησαν ἐπιόντων πολεμίων οὔτ’ ὄψιν ἢ χρόαν ἔτρεψαν, ἀλλὰ ῥᾳθύμως καὶ ἀδεῶς ἐγκεκλιμένοι τοῖς σκίπωσιν, οὓς ἐφόρουν, καὶ προσβλέποντες ἀλλήλοις ἡσύχαζον. ἦν οὖν θαῦμα τοῖς Γαλάταις πρὸς τὴν ἀτοπίαν, καὶ πολὺν χρόνον ὀκνοῦντες ἅψασθαι καὶ προσελθεῖν ὡς κρείττοσι διηπόρουν. ἐπεὶ δὲ τολμήσας τις ἐξ αὐτῶν ἐγγὺς παρέστη Παπειρίῳ Μάρκῳ καὶ προσαγαγὼν τὴν χεῖρα πρᾴως ἥψατο τοῦ γενείου καὶ κατῆγε τὴν ὑπήνην βαθεῖαν οὖσαν, ὁ μὲν Παπείριος τῇ βακτηρίᾳ τὴν κεφαλὴν αὐτοῦ πατάξας συνέτριψεν, ὁ δὲ βάρβαρος σπασάμενος τὴν μάχαιραν ἀπέκτεινεν ἐκεῖνον. ἐκ δὲ τούτου καὶ τοὺς λοιποὺς ἀνῄρουν προσπεσόντες, καὶ τῶν ἄλλων ὅσοις ἐπιτύχοιεν διεχρῶντο, καὶ τάς οἰκίας ἐπόρθουν ἐφ’ ἡμέρας πολλὰς ἄγοντες καὶ φέροντες, εἶτα κατεπίμπρασαν καὶ κατέσκαπτον ὀργιζόμενοι τοῖς ἔχουσι τὸ Καπιτώλιον, ὅτι καλούντων αὐτῶν οὐχ ὑπήκουον, ἀλλὰ καὶ προσβάλλουσι πληγὰς ἔδοσαν ἀπὸ τοῦ διατειχίσματος ἀμυνόμενοι, διὰ ταῦτα μὲν οὖν ἐλυμήναντο τὴν πόλιν καὶ προσδιέφθειραν τοὺς ἁλισκομένους, ὁμοίως μὲν ἄνδρας καὶ γυναῖκας, ὁμοίως δὲ πρεσβύτας καὶ παῖδας.", "st": "Cam. 22.4"}, {"sp": "N", "t": "τῆς δὲ πολιορκίας μῆκος λαμβανούσης ἐπισιτισμοῦ τοῖς Γαλάταις ἔδει· καὶ διελόντες ἑαυτοὺς οἱ μὲν τῷ βασιλεῖ παραμένοντες ἐφρούρουν τὸ Καπιτώλιον, οἱ δὲ τὴν χώραν περιιόντες ἐλεηλάτουν καὶ τὰς κώμας ἐπόρθουν προσπίπτοντες, οὐχ ὁμοῦ πάντες, ἄλλοι δ’ ἄλλῃ καθ’ ἡγεμονίας καὶ συντάγματα, τῷ μέγα φρονεῖν ὑπὸ τῶν εὐτυχημάτων καὶ δεδιέναι μηδὲν ἀποσκιδνάμενοι. τὸ δὲ πλεῖστον αὐτῶν καὶ μάλιστα συντεταγμένον ἐχώρει πρὸς τὴν Ἀρδεατῶν πόλιν, ἐν ᾗ διέτριβε Κάμιλλος ἀργῶν ταῖς πράξεσι μετὰ τὴν φυγὴν καὶ ἰδιωτεύων, ἐλπίδας δὲ λαμβάνων καὶ διαλογισμοὺς οὐχὶ τὸ λαθεῖν καὶ διαφυγεῖν τοὺς πολεμίους ἀγαπῶντος ἀνδρός, ἀλλ’ ὅπως, εἰ παραγένοιτο καιρὸς, ἀμυνεῖται σκοποῦντος. διὸ καὶ τοὺς Ἀρδεάτας ὁρῶν πλήθει μὲν ἱκανοὺς ὄντας, ἐνδεεῖς δὲ τόλμης δι’ ἀπειρίαν καὶ μαλακίαν τῶν στρατηγῶν, ἐνέβαλε λόγον εἰς τοὺς νέους πρῶτον, ὡς οὐ χρὴ τὴν Ῥωμαίων ἀτυχίαν ἀνδρείαν Κελτῶν νομίζειν, οὐδ’ ἃ κακῶς φρονήσασι συνέβη παθεῖν ἐκείνοις ἔργα τῶν οὐδὲν εἰς τὸ νικῆσαι παρασχόντων, ἀλλὰ τύχης ἐπίδειξιν ἡγεῖσθαι. καλὸν μὲν οὖν εἶναι καὶ διὰ κινδύνων ἀπώσασθαι πόλεμον ἀλλόφυλον καὶ βαρβαρικόν, ᾧ τοῦ κρατεῖν πέρας, ὥσπερ τῷ πυρὶ, διαφθαρῆναι τὸ νικώμενον οὐ μὴν ἀλλὰ καὶ θαρροῦσι καὶ προθυμουμένοις αὐτοῖς ἀκίνδυνον ἐν καιρῷ τὴν νίκην παρέξειν.", "st": "Cam. 23.1"}, {"sp": "N", "t": "τούτους τοὺς λόγους τῶν νέων δεξαμένων ἐπὶ τοὺς ἄρχοντας ᾔει καὶ τοὺς προβούλους τῶν Ἀρδεατῶν ὁ Κάμιλλος. ὡς δὲ κἀκείνους συνέπεισεν, ὥπλισε τοὺς ἐν ἡλικίᾳ πάντας καὶ συνεῖχε τοῦ τείχους ἐντός, ἀγνοεῖσθαι βουλόμενος ὑπὸ τῶν πολεμίων ἐγγὺς ὄντων. ἐπεὶ δὲ τὴν χώραν ἱππασάμενοι καὶ βαρεῖς ὄντες ὑπὸ πλήθους τῶν ἀγομένων καὶ φερομένων ἀμελῶς καὶ ὀλιγώρως ἐν τῷ πεδίῳ κατεστρατοπέδευσαν, ἐκ δὲ τούτου νὺξ ἐπῆλθε μεθύουσιν αὐτοῖς καὶ σιωπὴ κατέσχε τὸ στρατόπεδον, πυθόμενος ταῦτα παρὰ τῶν κατασκόπων ὁ Κάμιλλος ἐξῆγε τοὺς Ἀρδεάτας· καὶ διελθὼν καθ’ ἡσυχίαν τὸν μεταξὺ τόπον περὶ μέσας νύκτας προσέμιξε τῷ χάρακι κραυγῇ τε χρώμενος πολλῇ καὶ ταῖς σάλπιγξι πανταχόθεν ἐκταράττων ἀνθρώπους κακῶς ὑπὸ μέθης καὶ μόλις ἐκ τῶν ὕπνων ἀναφέροντας πρὸς τὸν θόρυβον. ὀλίγοι μὲν οὖν ἀνανήψαντες ἐν τῷ φόβῳ καὶ διασκευασάμενοι τοὺς περὶ τὸν Κάμιλλον ὑπέστησαν, ὥστ’ ἀμυνόμενοι πεσεῖν τοὺς δὲ πλείστους ἔτι κρατουμένους ὕπνῳ καὶ οἴνῳ καταλαμβάνοντες ἀνόπλους ἔκτεινον. ὅσοι δὲ νυκτὸς ἀπέδρασαν ἐκ τοῦ χάρακος οὐ πολλοί, τούτους μεθ’ ἡμέραν σποράδας ἐν τῇ χώρᾳ διαφερομένους ἐπελαύνοντες ἱππεῖς διέφθειρον.", "st": "Cam. 23.5"}, {"sp": "N", "t": "ἡ δὲ φήμη ταχὺ διαγγέλλουσα τὴν πρᾶξιν ἐπὶ τὰς πόλεις ἐξεκαλεῖτο πολλοὺς τῶν ἐν ἡλικίᾳ συνισταμένους, μάλιστα δὲ Ῥωμαίων ὅσοι διαφυγόντες ἐκ τῆς ἐπ’ Ἀλίᾳ μάχης ἐν Οὐηΐοις ἦσαν καὶ ὠδύροντο κατὰ σφᾶς αὐτούς, οἷον ἡγεμόνα τῆς Ῥώμης ὁ δαίμων ἀφελόμενος Ἀρδεάτας ἐκόσμησε τοῖς Καμίλλου κατορθώμασιν, ἡ δὲ γειναμένη καὶ θρέψασα τοιοῦτον ἄνδρα πόλις οἴχεται καὶ ἀπόλωλεν. ἡμεῖς δ’ ἀπορίᾳ στρατηγῶν ἀλλότρια τείχη περιβαλόμενοι καθήμεθα προέμενοι τὴν Ἰταλίαν. φέρε, πέμψαντες Ἀρδεάτας ἀπαιτῶμεν τὸν ἑαυτῶν στρατηγόν, ἢ λαβόντες αὐτοὶ τὰ ὅπλα πρὸς ἐκεῖνον βαδίζωμεν οὐκέτι γάρ ἐστι φυγὰς οὐδ’ ἡμεῖς πολῖται πατρίδος οὐκ οὔσης, ἀλλὰ κρατουμένης ὑπὸ τῶν πολεμίων. ταῦτ’ ἔδοξε καὶ πέμψαντες ἐδέοντο τοῦ Καμίλλου δέχεσθαι τὴν ἀρχήν. ὁ δὲ οὐκ ἔφη πρότερον ἢ τοὺς ἐν τῷ Καπιτωλίῳ πολίτας ἐπιψηφίσασθαι κατὰ τὸν νόμον. ἐκείνους γὰρ ἡγεῖσθαι πατρίδα σῳζομένους, καὶ κελεύουσι μὲν ὑπακούειν προθύμως, ἀκόντων δὲ μηδὲν πολυπραγμονήσειν. τῆς μὲν οὖν εὐλαβείας καὶ καλοκαγαθίας τὸν Κάμιλλον ἐθαύμασαν. ἦν δ’ ἀπορία τοῦ ταῦτα διαγγελοῦντος εἰς τὸ Καπιτώλιον μᾶλλον δ’ ὅλως ἀδύνατον ἐδόκει τῶν πολεμίων ἐχόντων τὴν πόλιν ἄγγελον εἰς τὴν ἀκρόπολιν παρελθεῖν.", "st": "Cam. 24.1"}, {"sp": "N", "t": "ἦν δέ τις ἐν τοῖς νέοις Πόντιος Κομίνιος, τῶν μέσων κατὰ γένος πολιτῶν, δόξης δὲ καὶ τιμῆς ἐραστής· οὗτος ὑπέστη τόν ἆθλον ἑκούσιος. καὶ γράμματα μὲν οὐκ ἔλαβε πρὸς τοὺς ἐν τῷ Καπιτωλίῳ, μὴ ληφθέντος αὐτοῦ φωράσωσιν οἱ πολέμιοι δι’ αὐτῶν τοῦ Καμίλλου τήν διάνοιαν, ἐσθῆτα δὲ φαύλην ἔχων καὶ φελλοὺς ὑπ’ αὐτῇ κομίζων τήν μὲν ἄλλην ὁδὸν ἡμέρας ἀδεῶς διῆλθεν, ἐγγὺς δὲ τῆς πόλεως γενόμενος ἤδη σκοταῖος, ἐπεὶ κατὰ γέφυραν οὐκ ἦν τόν ποταμὸν περᾶσαι τῶν βαρβάρων παραφυλαττόντων, τήν μὲν ἐσθῆτα τῇ κεφαλῇ περισπειράσας οὐ πολλὴν οὐδὲ βαρεῖαν, τοῖς δὲ φελλοῖς ἐφεὶς τὸ σῶμα καὶ συνεπικουφίζων τῷ περαιοῦσθαι πρὸς τήν πόλιν ἐξέβη. καὶ παραλλάττων ἀεὶ τοὺς ἐγρηγορότας, τοῖς φέγγεσι καὶ τῷ θορύβῳ τεκμαιρόμενος, ἐβάδιζε πρὸς τὴν Καρμεντίδα πύλην, ἣ πλείστην εἶχεν ἡσυχίαν, καὶ μάλιστα κατ’ αὐτὴν ὄρθιος ὁ τοῦ Καπιτωλίου λόφος ἀνέστηκε καὶ πέτρα κύκλῳ πολλὴ καὶ τραχεῖα περιπέφυκε· δι’ ἧς ἀνέβη λαθὼν καὶ προσέμιξε τοῖς φυλάττουσι τὸ διατείχισμα χαλεπῶς καὶ μόλις κατὰ τὸ λαγαρώτατον. ἀσπασάμενος δὲ τοὺς ἄνδρας καὶ φράσας ἑαυτὸν ἐξ ὀνόματος, ἀναληφθεὶς ἐχώρει πρὸς τοὺς ἐν τέλει τῶν Ῥωμαίων. ταχὺ δὲ συγκλήτου γενομένης παρελθὼν τήν τε νίκην ἀπήγγειλε τοῦ Καμίλλου πρότερον οὐ πυθομένοις, καὶ τὰ δοκοῦντα τοῖς στρατιώταις διηγεῖτο· καὶ παρεκάλει τῷ Καμίλλῳ βεβαιῶσαι τὴν ἀρχήν, ὡς μόνῳ πεισομένων ἐκείνῳ τῶν ἔξω πολιτῶν. οἱ δ’ ἀκούσαντες καὶ βουλευσάμενοι τόν τε Κάμιλλον ἀποδεικνύουσι δικτάτορα, καὶ τόν Πόντιον αὖθις ἀποπέμπουσι τήν αὐτὴν ὁδὸν ὁμοίως ἀγαθῇ τύχῃ χρησάμενον. ἔλαθε γὰρ τοὺς πολεμίους καὶ τὰ παρὰ τῆς βουλῆς ἀπήγγειλε τοῖς ἔξω Ῥωμαίοις.", "st": "Cam. 25.1"}, {"sp": "N", "t": "ἐκείνων δὲ δεξαμένων προθύμως ἀφικόμενος ὁ Κάμιλλος ἤδη μὲν ἐν ὅπλοις δισμυρίους κατέλαβε, πλείονας δὲ συνῆγεν ἀπὸ τῶν συμμάχων καὶ παρεσκευάζετο πρὸς τὴν ἐπίθεσιν. οὕτω μὲν ᾑρέθη δικτάτωρ ὁ Κάμιλλος τὸ δεύτερον καὶ πορευθεὶς εἰς Οὐηΐους ἐνέτυχε τοῖς στρατιώταις καὶ συνῆγε πλείους ἀπὸ τῶν συμμάχων ὡς ἐπιθησόμενος τοῖς πολεμίοις.", "st": "Cam. 26.1"}, {"sp": "N", "t": "ἐν δὲ τῇ Ῥώμῃ τῶν βαρβάρων τινὲς ἐκείνῃ κατὰ τύχην παρεξιόντες, ᾗ διὰ νυκτὸς ὁ Πόντιος προσέβη τῷ Καπιτωλίῳ, καταμαθόντες πολλαχῇ μὲν ἴχνη ποδῶν καὶ χειρῶν, ὡς ἀντελαμβάνετο καὶ περιεδράττετο, πολλαχῇ δὲ τῶν ἐπιπεφυκότων τοῖς κρημνοῖς ἀποτριβὰς καὶ περιολισθήσεις τῶν γεωδῶν, φράζουσι τῷ βασιλεῖ. κἀκεῖνος ἐπελθὼν καὶ θεασάμενος τότε μὲν ἡσύχαζεν, ἑσπέρας δὲ τοὺς ἐλαφροτάτους τοῖς σώμασι καὶ πεφυκότας ὀρειβατεῖν μάλιστα τῶν Κελτῶν συναγαγών, Τὴν μὲν ὁδόν, εἶπεν, ἡμῖν ἐφ’ ἑαυτοὺς ἀγνοουμένην οἱ πολέμιοι δεικνύουσιν ὡς οὔτ’ ἀπόρευτος οὔτε ἄβατος ἀνθρώποις ἐστίν, αἰσχύνη δὲ πολλὴ τὴν ἀρχὴν ἔχοντας ἐλλείπειν πρὸς τὸ τέλος καὶ προέσθαι τὸν τόπον ὡς ἀνάλωτον, αὐτῶν τῶν πολεμίων ᾗ ληπτός ἐστι διδασκόντων, ᾗ γὰρ ἑνὶ προσβῆναι ῥᾴδιον, οὐδὲ πολλοῖς καθ’ ἕνα δύσκολον, ἀλλὰ καὶ ῥώμη καὶ βοήθεια πολλὴ μετ’ ἀλλήλων ἐπιχειροῦσι. δωρεαὶ δὲ καὶ τιμαὶ πρέπουσαι τῆς ἀνδραγαθίας ἑκάστῳ δοθήσονται.", "st": "Cam. 26.2"}, {"sp": "N", "t": "τοιαῦτα τοῦ βασιλέως διαλεχθέντος ὑπέστησαν οἱ Γαλάται προθύμως, καὶ περὶ μέσας νύκτας ἐπιβάντες ἅμα πολλοὶ τῆς πέτρας ἐχώρουν ἄνω μετὰ σιωπῆς, ἐμφυόμενοι τοῖς χωρίοις ἀποτόμοις οὖσι καὶ χαλεποῖς, οὐ μὴν ἀλλὰ μᾶλλον ἢ προσεδοκήθη πειρωμένων αὐτῶν προσιεμένοις καὶ παρείκουσιν, ὥστε τοὺς πρώτους ἁψαμένους τῶν ἄκρων καὶ διασκευασαμένους ὅσον οὐκ ἤδη τοῦ προτειχίσματος ἅπτεσθαι καὶ τοῖς φύλαξιν ἐπιχειρεῖν κοιμωμένοις· ᾔσθετο γὰρ οὔτ’ ἄνθρωπος οὔτε κύων. ἀλλὰ χῆνες ἦσαν ἱεροὶ περὶ τὸν νεὼν τῆς Ἥρας τρεφόμενοι τὸν ἄλλον χρόνον ἀφθόνως, τότε δὲ τῶν σιτίων ἤδη γλίσχρως καὶ μόλις αὐτοῖς διαρκούντων ἀμελούμενοι κακῶς ἔπραττον. ἔστι μὲν οὖν καὶ φύσει πρὸς αἴσθησιν ὀξὺ καὶ ψοφοδεὲς τὸ ζῷον ἐκεῖνοι δὲ καὶ διὰ λιμὸν ἀγρυπνητικοὶ καὶ θορυβώδεις γεγονότες ταχὺ τὴν ἔφοδον ᾔσθοντο τῶν Γαλατῶν, καὶ μετὰ δρόμου καὶ κλαγγῆς φερόμενοι πρὸς αὐτούς ἐπήγειραν ἅπαντας, ἤδη καὶ τῶν βαρβάρων διὰ τὸ μὴ λανθάνειν ἀφειδούντων θορύβου καὶ βιαιότερον ἐπιτιθεμένων. ἁρπάσαντες οὖν ὑπὸ σπουδῆς ᾧ τις ἕκαστος ὅπλῳ προσετύγχανεν, ἐκ τοῦ παρόντος ἐβοήθουν. πάντων δὲ πρῶτος Μάλλιος, ἀνὴρ ὑπατικὸς, τό τε σῶμα ῥωμαλέος καὶ φρονήματι ψυχῆς ἐπιφανής, ἀπαντήσας δυσὶν ὁμοῦ τῶν πολεμίων τοῦ μὲν ἔφθασε διῃρμένου κοπίδα τῷ ξίφει τὴν δεξιὰν ἀποκόψας, τὸν δὲ τῷ θυρεῷ πατάξας εἰς τὸ πρόσωπον ἔωσεν ὀπίσω κατὰ τῆς πέτρας. ἐπιστὰς δὲ τῷ τείχει μετὰ τῶν συνδραμόντων καὶ γενομένων περὶ αὐτὸν ἀπέστρεψε τοὺς ἄλλους, οὔτε πολλοὺς ἄνω γενομένους οὔτε πράξαντάς τι τῆς τόλμης ἄξιον, οὕτω δὲ τὸν κίνδυνον ἐκφυγόντες ἅμ’ ἡμέρᾳ τὸν μὲν ἄρχοντα τῶν φυλάκων ἔρριψαν εἰς τοὺς πολεμίους κατὰ τῆς πέτρας, τῷ δὲ Μαλλίῳ τῆς νίκης ἀριστεῖα πρὸς τιμὴν μεγάλην μᾶλλον ἢ χρείαν ψηφισάμενοι συνήνεγκαν ὅσον ἡμέρας ἕκαστος ἐλάμβανεν εἰς τροφήν, σίτου μὲν ἡμίλιτρον ἐπιχωρίου οὕτω γὰρ καλοῦσιν αὐτό, οἴνου δὲ κοτύλης Ἑλληνικῆς τέταρτον.", "st": "Cam. 27.1"}, {"sp": "N", "t": "ἐκ τούτου τὰ τῶν Κελτῶν ἦν ἀθυμότερα. καὶ γὰρ ἐπιτηδείων ἐσπάνιζον εἰργόμενοι προνομῆς φόβῳ τοῦ Καμίλλου, καὶ νόσος ὑποικούρησεν αὐτοὺς ἐν νεκρῶν πλήθει χύδην καταβεβλημένων σκηνοῦντας ἐν ἐρειπίοις, τό τε βάθος τῆς τέφρας ἀέρα ξηρότητι καὶ δριμύτητι φαῦλον ὑπὸ πνευμάτων καὶ καυμάτων ἀναθυμιώσης ἐλυμαίνετο τὰ σώματα διὰ τῆς ἀναπνοῆς. μάλιστα δ’ ἡ μεταβολὴ τῆς συντρόφου διαίτης ἐκ τόπων σκιερῶν καὶ θέρους καταφυγὰς ἀλύπους ἐχόντων ἐμβαλόντας εἰς χώραν ταπεινὴν καὶ κεκραμένην ἀφυῶς πρὸς τὸ μετόπωρον ἐκίνησεν αὐτούς, ἥ τε πρὸς τῷ Καπιτωλίῳ καθέδρα καὶ σχολὴ γενομένη χρόνιος, ἕβδομον γὰρ ἐκεῖνον οἱκούρουν μῆνα πολιορκοῦντες. ὥστε φθορὰν εἶναι πολλὴν ἐν τῷ στρατοπέδῳ καὶ μηδὲ θάπτεσθαι διὰ πλῆθος ἔτι τοὺς ἀποθνῄσκοντας.", "st": "Cam. 28.1"}, {"sp": "N", "t": "οὐ μὴν παρὰ τοῦτο τὰ πράγματα βελτίω τοῖς πολιορκουμένοις ἦν. ἐπέτεινε γὰρ ὁ λιμός, ἥ τε τῶν περὶ Κάμιλλον ἄγνοια παρεῖχε δυσθυμίαν οὐδεὶς γὰρ ἐφοίτα παρ’ αὐτῶν διὰ τὸ φρουρεῖσθαι τὴν πόλιν ἀκριβῶς ὑπὸ τῶν βαρβάρων, ὅθεν οὕτω πράττουσιν ἀμφοτέροις ἐγίνοντο συμβατικοὶ λόγοι διὰ τῶν προφυλάκων τὸ πρῶτον ἀλλήλοις ἐντυγχανόντων· εἶτα, ὡς ἔδοξε τοῖς κρατίστοις, συνελθόντος εἰς λόγους Βρέννῳ Σουλπικίου τοῦ χιλιάρχου τῶν Ῥωμαίων, ὡμολογήθη τοὺς μὲν χιλίας λίτρας χρυσίου καταβαλεῖν, τοὺς δὲ λαβόντας ἐκ τῆς πόλεως αὐτίκα καὶ τῆς χώρας ἀναχωρεῖν. ἐπὶ τούτοις γενομένων ὅρκων καὶ τοῦ χρυσίου κομισθέντος, τῶν δὲ Κελτῶν περὶ τὸν σταθμὸν ἀγνωμονούντων κρύφα τὸ πρῶτον, εἶτα καὶ φανερῶς ἀφελκόντων καὶ διαστρεφόντων τὴν ῥοπήν, ἠγανάκτουν οἱ Ῥωμαῖοι πρὸς αὐτούς. ὁ δὲ Βρέννος οἷον ἐφυβρίζων καὶ καταγελῶν ἀποδυσάμενος τὴν μάχαιραν ἅμα καὶ τὸν ζωστῆρα προσέθηκε τοῖς σταθμοῖς. πυνθανομένου δὲ τοῦ Σουλπικίου, τί τοῦτο; τί γὰρ ἄλλο, εἶπεν, ἢ τοῖς νενικημένοις ὀδύνη; τοῦτο μὲν οὖν ἤδη παροιμιώδης λόγος γέγονε. τῶν δὲ Ῥωμαίων οἱ μὲν ἠγανάκτουν καὶ τὸ χρυσίον ᾤοντο δεῖν λαβόντας αὖθις ἀπιέναι καὶ τὴν πολιορκίαν ὑπομένειν οἱ δὲ συγχωρεῖν ἐκέλευον ἀδικουμένους μέτρια, καὶ μὴ τῷ πλέον διδόναι προσλογίζεσθαι τὸ αἰσχρόν, αὐτό γε τὸ δοῦναι διὰ τὸν καιρὸν οὐ καλῶς ἀλλ’ ἀναγκαίως ὑπομένοντας.", "st": "Cam. 28.3"}, {"sp": "N", "t": "οὔσης δὲ περὶ τούτων πρός τε τοὺς Κελτοὺς καὶ πρὸς αὑτοὺς διαφορᾶς ἄγων τὸν στρατὸν ὁ Κάμιλλος ἐν ταῖς πύλαις ἦν· καὶ πυθόμενος τὰ γινόμενα τοὺς ἄλλους ἐκέλευσεν ἐν τάξει καὶ σχέδην ἐπακολουθεῖν, αὐτὸς δὲ μετὰ τῶν ἀρίστων ἐπειγόμενος εὐθὺς ἐπορεύετο πρὸς τοὺς Ῥωμαίους. διαστάντων δὲ πάντων καὶ δεξαμένων αὐτόν ὡς αὐτοκράτορα κόσμῳ καὶ σιωπῇ, τὸ μὲν χρυσίον ἄρας ἀπὸ τοῦ ζυγοῦ τοῖς ὑπηρέταις ἔδωκε, τὸν δὲ ζυγὸν καὶ τὰ σταθμὰ τοὺς Κελτοὺς λαβόντας ἀποχωρεῖν ἐκέλευσεν εἰπὼν, ὡς σιδήρῳ πάτριόν ἐστι Ῥωμαίοις, οὐ χρυσῷ τὴν πατρίδα σῴζειν. ἀγανακτοῦντος δὲ τοῦ Βρέννου καὶ φάσκοντος ἀδικεῖσθαι λυομένης τῆς ὁμολογίας, ἀντεῖπε μὴ νομίμως γεγονέναι μηδὲ κυρίας εἶναι τὰς συνθήκας· ἤδη γὰρ αὐτοῦ δικτάτορος ᾑρημένου καὶ μηδενὸς ἄρχοντος ἑτέρου νόμῳ πρὸς οὐκ ἔχοντας ἐξουσίαν ὁμολογηθῆναι. νυνὶ δὲ χρῆναι λέγειν εἴ τι βούλονται· νόμῳ γὰρ ἥκειν κύριος γεγονὼς συγγνώμην τε δεομένοις δοῦναι καὶ δίκην, εἰ μὴ μετανοοῦσιν, ἐπιθεῖναι τοῖς αἰτίοις. πρὸς ταῦτα θορυβηθεὶς ὁ Βρέννος ἥψατο μὲν ἁψιμαχίας, καὶ προῆλθον ἄχρι ξιφουλκίας ἑκάτεροι καὶ διωθισμῶν ἀναμεμιγμένοι πρὸς ἀλλήλους, ὥσπερ εἰκός, ἐν οἰκίαις καὶ στενωποῖς ἀναστρεφόμενοι καὶ χωρίοις δέξασθαι παράταξιν οὐ δυναμένοις. ταχὺ δὲ συμφρονήσας ὁ Βρέννος ἀπήγαγε τοὺς Κελτοὺς εἰς τὸ στρατόπεδον οὐ πολλῶν πεσόντων, καὶ νυκτὸς ἀναστήσας ἅπαντας ἐξέλιπε τὴν πόλιν, καὶ προελθὼν ἑξήκοντα σταδίους κατεστρατοπέδευσε παρὰ τὴν Γαβινίαν ὁδόν. ἅμα δ’ ἡμέρᾳ παρῆν ὁ Κάμιλλος ἐπ’ αὐτόν ὡπλισμένος λαμπρῶς καὶ τεθαρρηκότας ἔχων τότε τοὺς Ῥωμαίους· καὶ γενομένης ἰσχυρᾶς μάχης ἐπὶ πολὺν χρόνον αὐτούς τε τρέπεται πολλῷ φόνῳ καὶ λαμβάνει τὸ στρατόπεδον. τῶν δὲ φευγόντων οἱ μὲν εὐθὺς ἀνῃρέθησαν καταδιωχθέντες, τοὺς δὲ πλείστους διασπαρέντας ἐπεκθέοντες ἐκ τῶν πέριξ κωμῶν καὶ πόλεων ἔκτεινον.", "st": "Cam. 29.1"}, {"sp": "N", "t": "οὕτω μὲν ἡ Ῥώμη παραλόγως ἥλω καὶ παραλογώτερον ἐσώθη, μῆνας ἑπτὰ τοὺς πάντας ὑπὸ τοῖς βαρβάροις γενομένη, παρελθόντες γὰρ εἰς αὐτὴν ὀλίγαις ἡμέραις ὕστερον τῶν Κυϊντιλίων εἰδῶν περὶ τὰς Φεβρουαρίας εἰδοὺς ἐξέπεσον. ὁ δὲ Κάμιλλος ἐθριάμβευσε μέν, ὡς εἰκὸς ἦν, τὸν ἀπολωλυίας σωτῆρα πατρίδος γενόμενον καὶ κατάγοντα τὴν πόλιν αὐτὴν εἰς ἑαυτήν· οἵ τε γὰρ ἔξωθεν ἅμα παισὶ καὶ γυναιξὶν εἰσελαύνοντος αὐτοῦ συγκατῄεσαν, οἵ τε πολιορκηθέντες ἐν τῷ Καπιτωλίῳ, μικροῦ δεήσαντες ἀπολέσθαι διὰ λιμόν, ἀπήντων περιβάλλοντες ἀλλήλους καὶ δακρύοντες ὑπὸ τῆς παρούσης ἡδονῆς, ἱερεῖς τε καὶ ζάκοροι θεῶν, ὅσα φεύγοντες αὐτόθι τῶν ἀβεβήλων ἔκρυψαν ἢ σὺν αὑτοῖς ἐξέκλεψαν, ἀνασωζόμενα κομίζοντες ἐπεδείκνυντο ποθουμένας ὄψεις τοῖς πολίταις δεχομένοις μετὰ χαρᾶς, ὥσπερ αὐτῶν τῶν θεῶν αὖθις εἰς τὴν Ῥώμην συγκατερχομένων· θύσας δὲ τοῖς θεοῖς καὶ καθάρας τὴν πόλιν ἐξηγουμένων τῶν περὶ ταῦτα δεινῶν, τὰ μὲν ὄντα τῶν ἱερῶν κατέστησεν, αὐτὸς δὲ ἱδρύσατο νεὼν Φήμης καὶ Κληδόνος, ἀνευρὼν ἐκεῖνον τὸν τόπον, ἐν ᾧ νύκτωρ ἡ καταγγέλλουσα τὴν τῶν βαρβάρων στρατιὰν ἐκ θεοῦ τῷ Καιδικίῳ Μάρκῳ φωνὴ προσέπεσε.", "st": "Cam. 30.1"}, {"sp": "N", "t": "χαλεπῶς μὲν οὖν καί μόλις αἱ τῶν ἱερῶν ἀνεκαλύπτοντο χῶραι φιλοτιμίᾳ τοῦ Καμίλλου καὶ πόνῳ πολλῷ τῶν ἱεροφαντῶν ὡς δὲ καὶ τήν πόλιν ἀνοικοδομεῖν ἔδει παντάπασι διεφθαρμένην, ἀθυμία πρὸς τὸ ἔργον ἐνέπιπτε τοῖς πολλοῖς καί μέλλησις ἦν ἐστερημένοις ἁπάντων καί τινος ἐν τῷ παρόντι ῥᾳστώνης καί ἀναπαύσεως ἐκ κακῶν δεομένοις μᾶλλον ἢ κάμνειν καί ἀποτρύχειν ἑαυτούς οὔτε χρήμασιν οὔτε σώμασιν ἐρρωμένους. οὕτω δὲ ἡσυχῇ πρὸς τοὺς Οὐηΐους αὖθις ἀποστρεφόμενοι, πόλιν ἅπασι κατεσκευασμένην καί διαμένουσαν, ἀρχὰς δημαγωγιῶν ἐνέδοσαν τοῖς πρὸς χάριν εἰθισμένοις ὁμιλεῖν, καί λόγων ἠκροῶντο στασιαστικῶν πρὸς τὸν Κάμιλλον, ὡς ἐκείνου φιλοτιμίας ἕνεκα καί δόξης ἰδίας ἀποστεροῦντος αὐτοὺς πόλεως ἑτοίμης καί βιαζομένου σκηνοῦν ἐρείπια καί πυρκαϊὰν τοσαύτην ἐγείρειν, ὅπως μὴ μόνον ἡγεμὼν Ῥώμης καί στρατηγός, ἀλλὰ καί κτίστης λέγηται παρώσας Ῥωμύλον.", "st": "Cam. 31.1"}, {"sp": "N", "t": "ἐκ τούτου φοβηθεῖσα τὸν θόρυβον ἡ βουλὴ τὸν μὲν Κάμιλλον οὐκ εἴασε βουλόμενον ἀποθέσθαι τὴν ἀρχὴν ἐντὸς ἐνιαυτοῦ καίπερ ἓξ μῆνας οὐδενὸς ὑπερβαλόντος ἑτέρου δικτάτορος, αὐτὴ δὲ παρεμυθεῖτο καί κατεπράυνε πείθουσα καί δεξιουμένη τὸν δῆμον, ἐπιδεικνυμένη μὲν ἠρία καί τάφους πατέρων, ὑπομιμνῄσκουσα δὲ χωρίων ἱερῶν καί τόπων ἁγίων, οὓς Ῥωμύλος ἢ Νομᾶς ἤ τις ἄλλος αὐτοῖς τῶν βασιλέων ἐπιθειάσας παρέδωκεν. ἐν πρώτοις δὲ τῶν θείων τήν τε νεοσφαγῆ κεφαλὴν προὔφερον ἐν τῇ θεμελιώσει τοῦ Καπιτωλίου φανεῖσαν, ὡς τῷ τόπῳ πεπρωμένον ἐκείνῳ τῆς Ἰταλίας κεφαλῇ γενέσθαι, καί τὸ τῆς Ἑστίας πῦρ, ὃ μετὰ τὸν πόλεμον ὑπὸ τῶν παρθένων ἀναπτόμενον αὖθις ἀφανίζειν καί σβεννύναι τοὺς προλιπόντας τήν πόλιν, ὄνειδος αὐτοῖς ἐσόμενον, ἄν τε ὑπ’ ἄλλων οἰκουμένην ὁρῶσιν ἐπηλύδων καί ξένων ἄν τ’ ἔρημον οὖσαν καί μηλόβοτον.", "st": "Cam. 31.3"}, {"sp": "N", "t": "τοιαῦτα καί πρὸς ἕκαστον ἰδίᾳ καί κοινῇ πολλάκις ἐν τῷ δήμῳ σχετλιάζοντες ἐπεκλῶντο πάλιν ὑπὸ τῶν πολλῶν τήν παροῦσαν ὀλοφυρομένων ἀμηχανίαν, καί δεομένων μὴ σφᾶς ὥσπερ ἐκ ναυαγίου γυμνοὺς καί ἀπόρους σωθέντας προσβιάζεσθαι τὰ λείψανα τῆς διεφθαρμένης συμπηγνύναι πόλεως, ἑτέρας ἑτοίμης παρούσης.", "st": "Cam. 31.5"}, {"sp": "N", "t": "ἔδοξεν οὖν βουλὴν προθεῖναι τῷ Καμίλλῳ· καὶ πολλὰ μὲν αὐτὸς διεξῆλθε παρακαλῶν ὑπὲρ τῆς πατρίδος, πολλὰ δὲ καὶ τῶν ἄλλων ὁ βουλόμενος τέλος δὲ τὸν πρῶτον εἰωθότα λέγειν γνώμην Λεύκιον Λουκρήτιον ἀναστήσας ἐκέλευσεν ἀποφήνασθαι πρῶτον, εἶτα τοὺς ἄλλους ἐφεξῆς. γενομένης δὲ σιωπῆς καὶ τοῦ Λουκρητίου μέλλοντος ἐνάρχεσθαι, κατὰ τύχην ἔξωθεν ἑκατοντάρχης ἄγων τάγμα φυλακῆς ἡμερινῆς παρεπορεύετο, καὶ τὸν φέροντα πρῶτον τὸ σημεῖον μεγάλῃ φωνῇ προσαγορεύσας ἐκέλευσεν αὐτοῦ μένειν καὶ τὸ σημεῖον τίθεσθαι· κάλλιστα γὰρ ἐνταῦθα καθεδεῖσθαι καὶ μενεῖν. ἅμα δὲ τῷ καιρῷ καὶ τῇ περὶ τοῦ μέλλοντος ἐννοίᾳ, καὶ ἀδηλότητι τῆς φωνῆς γενομένης, ὅ τε Λουκρήτιος ἔφη προσκυνήσας τῷ θεῷ προστίθεσθαι τὴν ἑαυτοῦ γνώμην καὶ τῶν ἄλλων ἕκαστος ἐπηκολούθησε. θαυμαστὴ δὲ καὶ τὸ πλῆθος ἔσχε μεταβολὴ τῆς ὁρμῆς, ἀλλήλους παρακαλούντων καὶ προτρεπομένων πρὸς τὸ ἔργον, οὐκ ἐκ διανομῆς τινος ἢ τάξεως, ἀλλ’ ὡς ἕκαστος ἑτοιμότητος ἢ βουλήσεως εἶχε τῶν χωρίων καταλαμβανομένων. διὸ καὶ τεταραγμένην τοῖς στενωποῖς καὶ συμπεφυρμένην ταῖς οἰκήσεσιν ἀνήγαγον τὴν πόλιν ὑπὸ σπουδῆς καὶ τάχους, ἐντὸς γὰρ ἐνιαυτοῦ λέγεται καὶ τοῖς τείχεσι καινὴ καὶ ταῖς ἰδιωτικαῖς οἰκοδομαῖς ἀναστῆναι πάλιν.", "st": "Cam. 32.1"}, {"sp": "N", "t": "οἱ δὲ τοὺς ἱεροὺς τόπους ἀναλαβεῖν καὶ ὁρίσαι ταχθέντες ὑπὸ τοῦ Καμίλλου, συγκεχυμένων ἁπάντων, ὡς ἧκον ἐπὶ τὴν καλιάδα τοῦ Ἄρεως περιοδεύοντες τὸ Παλάτιον, αὐτὴν μὲν, ὡς τὰ ἄλλα, διεφθαρμένην καὶ κατακεκαυμένην εὗρον ὑπὸ τῶν βαρβάρων, σκευωρούμενοι δὲ καὶ καθαίροντες τὸ χωρίον ἐντυγχάνουσι τῷ μαντικῷ ξύλῳ τοῦ Ῥωμύλου κατὰ τέφρας πολλῆς καὶ βαθείας καταδεδυκότι. τοῦτο δ’ ἔστι μὲν ἐπικαμπὲς ἐκ θατέρου πέρατος, καλεῖται δὲ λίτυον χρῶνται δ’ αὐτῷ πρὸς τὰς τῶν πλινθίων ὑπογραφάς ὅταν ἐπ’ ὄρνισι διαμαντευόμενοι καθέζωνται, ὡς κἀκεῖνος ἐχρῆτο μαντικώτατος ὤν. ἐπειδὴ δ’ ἐξ ἀνθρώπων ἠφανίσθη, παραλαβόντες οἱ ἱερεῖς τὸ ξύλον ὥσπερ ἄλλο τι τῶν ἱερῶν ἄψαυστον ἐφύλαττον. τοῦτο δὴ τότε τῶν ἄλλων ἀπολωλότων ἀνευρόντες διαπεφευγὸς τὴν φθοράν ἡδίους ἐγένοντο ταῖς ἐλπίσιν ὑπὲρ τῆς Ῥώμης, ὡς ἀίδιον αὐτῇ τὴν σωτηρίαν τοῦ σημείου βεβαιοῦντος.", "st": "Cam. 32.4"}, {"sp": "N", "t": "οὔπω δὲ τῆς Περὶ ταῦτα πεπαυμένοις ἀσχολίας αὐτοῖς ἐπιπίπτει πόλεμος, Αἰκανῶν μὲν ἅμα καὶ Οὐολούσκων καὶ Λατίνων εἰς τὴν χώραν ἐμβαλλόντων, Τυρρηνῶν δὲ πολιορκούντων Σούτριν, συμμαχίδα Ῥωμαίων πόλιν. ἐπειδὴ δ’ οἱ τὴν ἡγεμονίαν ἔχοντες χιλίαρχοι στρατοπεδευσάμενοι Περὶ τὸ Μάρκιον ὄρος ὑπὸ τῶν Λατίνων ἐπολιορκοῦντο καὶ κινδυνεύοντες ἀποβαλεῖν τὸ στρατόπεδον εἰς Ῥώμην ἔπεμψαν ἀποδείκνυται τὸ τρίτον Κάμιλλος δικτάτωρ· περὶ τούτου τοῦ πολέμου διττοὶ λόγοι λέγονται· δίειμι δὲ τὸν μυθώδη πρότερον.", "st": "Cam. 33.1"}, {"sp": "N", "t": "φασὶ τοὺς Λατίνους, εἴτε προφάσει χρωμένους εἴτε βουλομένους ὡς ἀληθῶς ἀναμίξασθαι τὰ γένη πάλιν ἐξ ὑπαρχῆς, πέμψαντας αἰτεῖν παρὰ τῶν Ῥωμαίων παρθένους ἐλευθέρας γυναῖκας, ἀπορούντων δὲ τῶν Ῥωμαίων, τί χρὴ ποιεῖν καὶ γὰρ τὸν πόλεμον ὠρρώδουν οὔπω καθεστῶτες οὐδ’ ἀνειληφότες αὑτούς, καὶ τὴν αἴτησιν τῶν γυναικῶν ὑπώπτευον ἐξομήρευσιν εἶναι, τοῦ δ’ εὐπρεποῦς χάριν ἐπιγαμίαν καλεῖσθαι, θεραπαινίδα τοὔνομα Τουτούλαν, ὡς δ’ ἔνιοι λέγουσι, Φιλωτίδα τοῖς ἄρχουσι παραινέσαι πέμπειν σὺν αὐτῇ τῶν δμωίδων τὰς ἐν ὥρᾳ μάλιστα καὶ ταῖς ὄψεσιν ἐλευθερίους, κοσμήσαντας ὡς νύμφας εὐγενεῖς, τὰ λοιπὰ δ’ αὐτῇ μελήσειν. πεισθέντας δὲ τοὺς ἄρχοντας ἐπιλέξασθαι τῶν θεραπαινίδων ὅσας ἐκείνη πρὸς τὴν χρείαν ἐδοκίμασε, καὶ κοσμήσαν· τὰς ἐσθῆτι καὶ χρυσῷ παραδοῦναι τοῖς Λατίνοις οὐ πάνυ πόρρω τῆς πόλεως στρατοπεδεύουσι. νύκτωρ δὲ τὰς μὲν ἄλλας ὑφελέσθαι τὰ ἐγχειρίδια τῶν πολεμίων, τὴν δ’ εἴτε Τουτούλαν εἴτε Φιλωτίδα προσβᾶσαν ἐρινεῷ μεγάλῳ καὶ παρατείνασαν ὀπίσω τὸ ἱμάτιον ἆραι πυρσὸν εἰς τὴν Ῥώμην, ὥσπερ ἦν συγκείμενον αὐτῇ πρὸς τοὺς ἄρχοντας, οὐδενὸς ἄλλου τῶν πολιτῶν εἰδότος. δι’ ὃ καὶ θορυβώδη γενέσθαι τὴν τῶν στρατιωτῶν ἔξοδον, ὡς κατήπειγον οἱ ἄρχοντες, ἀλλήλους ἀνακαλούντων καὶ μόλις εἰς τὴν τάξιν καθισταμένων, ἐπελθόντας δὲ τῷ χάρακι τῶν πολεμίων οὐ προσδεχομένων καὶ καθευδόντων ἑλεῖν τὸ στρατόπεδον καὶ διαφθεῖραι τοὺς πλείστους. τοῦτο δὲ γενέσθαι ταῖς νῦν Ἰουλίαις, τότε δὲ Κυϊντιλίαις νώναις, καὶ τὴν ἀγομένην ἑορτὴν ὑπόμνημα τῆς πράξεως ἐκείνης εἶναι, πρῶτον μὲν γὰρ ἐξιόντες ἀθρόοι διὰ τῆς πύλης πολλὰ τῶν ἐπιχωρίων καὶ κοινῶν ὀνομάτων βοῇ φθέγγονται, Γάιον, Μᾶρκον, Λούκιον καὶ τὰ τούτοις ὅμοια, μιμούμενοι τὴν τότε γενομένην μετὰ σπουδῆς ἀλλήλων ἀνάκλησιν· ἔπειτα κεκοσμημέναι λαμπρῶς αἱ θεραπαινίδες περιίασι παίζουσαι διὰ σκωμμάτων εἰς τοὺς ἀπαντῶντας, γίνεται δὲ καὶ μάχη τις αὐταῖς πρὸς ἀλλήλας, ὡς καὶ τότε τοῦ πρὸς τοὺς Λατίνους ἀγῶνος συνεπιλαμβανομέναις. ἑστιώμεναι δὲ καθέζονται κλάδοις συκῆς σκιαζόμεναι· καὶ τὴν ἡμέραν νώνας Καπρατίνας καλοῦσιν, ὡς οἴονται διὰ τὸν ἐρινεόν, ἀφ’ οὗ τὴν παιδίσκην τὸν πυρσὸν ἆραι· τὸν γὰρ ἐρινεὸν καπρίφικον ὀνομάζουσιν.", "st": "Cam. 33.3"}, {"sp": "N", "t": "ἕτεροι δὲ τούτων τὰ πλεῖστα δρᾶσθαι καὶ λέγεσθαί φασιν ἐπὶ τῷ τοῦ Ῥωμύλου πάθει· κατὰ ταύτην γὰρ ἀφανισθῆναι τὴν ἡμέραν αὐτὸν ἔξω πύλης, ζόφου καὶ θυέλλης ἄφνω περισχούσης, ὡς δ’ ἔνιοι νομίζουσιν, ἐκλείψεως ἡλίου γενομένης, καὶ τὴν ἡμέραν ἀπὸ τοῦ τόπου νώνας Καπρατίνας κληθῆναι, τὴν γὰρ αἶγα κάπραν ὀνομάζουσιν ὁ δὲ Ῥωμύλος ἠφανίσθη δημηγορῶν Περὶ τὸ τῆς αἰγὸς ἕλος προσαγορευόμενον, ὡς ἐν τοῖς Περὶ ἐκείνου γέγραπται.", "st": "Cam. 33.7"}, {"sp": "N", "t": "τὸν δ’ ἕτερον λόγον οἱ πλεῖστοι τῶν συγγραφέων δοκιμάζοντες οὕτω λέγουσιν. ἀποδειχθεὶς δικτάτωρ τὸ τρίτον ὁ Κάμιλλος καὶ πυθόμενος τὸ μετὰ τῶν χιλιάρχων στράτευμα πολιορκούμενον ὑπὸ τῶν Λατίνων καὶ τῶν Οὐολούσκων, ἠναγκάσθη καὶ τοὺς οὐκ ἐν ὥρᾳ τῶν πολιτῶν, ἀλλ’ ἤδη παρηβηκότας καθοπλίσαι. περιελθὼν δὲ μακρὰν περίοδον περὶ τὸ Μάρκιον ὄρος καὶ λαθὼν τοὺς πολεμίους ἵδρυσε τὴν στρατιὰν κατόπιν αὐτῶν, καὶ πυρὰ πολλὰ καύσας διεσήμηνε τὴν ἑαυτοῦ παρουσίαν. οἱ μὲν οὖν πολιορκούμενοι θαρρήσαντες ἐπιέναι διενοοῦντο καὶ μάχην συνάπτειν· οἱ δὲ Λατῖνοι καὶ Οὐολοῦσκοι συστείλαντες εἴσω τοῦ χάρακος ἑαυτούς ἀπεσταύρουν ξύλοις πολλοῖς καὶ διεφράγνυντο πανταχόθεν τὸ στρατόπεδον, ἀμφίβολοι γεγονότες ὑπὸ τῶν πολεμίων καὶ περιμένειν ἐγνωκότες ἑτέραν οἴκοθεν δύναμιν, ἅμα δὲ καὶ Τυρρηνῶν προσδεχόμενοι βοήθειαν. τοῦτο δ’ αἰσθόμενος ὁ Κάμιλλος καὶ δεδοικὼς παθεῖν ὅπερ ἐποίησεν αὐτὸς τοὺς πολεμίους κυκλωσάμενος ἔσπευδε προλαβεῖν τὸν καιρόν. ὄντος δὲ τοῦ περιφράγματος ξυλίνου καὶ πνεύματος μεγάλου κατιόντος ἀπὸ τῶν ὀρῶν ἅμα φάει, πυροβόλα παρασκευασάμενος καὶ περὶ τὸν ὄρθρον ἐξαγαγὼν τὴν δύναμιν τοὺς μὲν ἄλλους ἐκέλευσε χρῆσθαι βέλεσι καὶ κραυγῇ καθ’ ἕτερον μέρος, αὐτὸς δὲ τοὺς τὸ πῦρ ἀφήσειν μέλλοντας ἔχων ὅθεν εἰώθει μάλιστα προσπίπτειν ὁ ἄνεμος τῷ χάρακι τῶν πολεμίων ἀνέμενε τὴν ὥραν. ἐπεὶ δὲ συνεστώσης τῆς μάχης ὅ τε ἥλιος ἀνῄει καὶ τὸ πνεῦμα λαμπρὸν ἐξέπιπτε, σημήνας ἐπιδρομὴν κατέσπειρε τοῦ χάρακος ἄφθονα τῶν πυροβόλων. ταχὺ δὲ τῆς φλογὸς ἐν ὕλῃ πυκνῇ καὶ σταυρώμασι ξυλίνοις ἀνατραφείσης καὶ κύκλῳ περινεμομένης, οὐδὲν ἄκος οὐδὲ σβεστήριον ἔχοντες οἱ Λατῖνοι παρεσκευασμένον, ὡς πλῆρες ἦν ἤδη τὸ στρατόπεδον πυρός, ἐπ’ ὀλίγον συστελλόμενοι τόπον ἐξέπιπτον ὑπ’ ἀνάγκης πρὸς ὡπλισμένους καὶ παρατεταγμένους πρὸ τοῦ χάρακος τοὺς πολεμίους, καὶ τούτων μὲν ὀλίγοι διέφυγον, τοὺς δὲ καταλειφθέντας ἐν τῷ στρατοπέδῳ πάντας διέφθειρε τὸ πῦρ, μέχρι οὗ κατασβέσαντες οἱ Ῥωμαῖοι τὰ χρήματα διήρπασαν.", "st": "Cam. 34.1"}, {"sp": "N", "t": "γεγονότων δὲ τούτων ἀπολιπὼν ἐπὶ τὸν στρατοπέδου τὸν υἱὸν Λεύκιον φύλακα τῶν ἡλωκότων ἀνθρώπων καὶ χρημάτων αὐτός εἰς τὴν τῶν πολεμίων ἐνέβαλε. καὶ τὴν Αἰκανῶν πόλιν ἐξελὼν καὶ προσαγαγόμενος τοὺς Οὐολούσκους εὐθὺς ἦγε τὴν στρατιὰν πρὸς τὸ Σούτριον, οὔπω τὰ συμβεβηκότα τοῖς Σούτριον πεπυσμένος, ἀλλ’ ὡς ἔτι κινδυνεύουσι καὶ πολιορκουμένοις ὑπὸ τῶν Τυρρηνῶν βοηθῆσαι σπεύδων. οἱ δ’ ἔτυχον ἤδη τὴν μὲν πόλιν τοῖς πολεμίοις παραδεδωκότες, αὐτοὶ δὲ πάντων ἐνδεεῖς ἐν ἱματίοις μόνον ἀφειμένοι· καὶ καθ’ ὁδὸν ὄντι τῷ Καμίλλῳ μετὰ παίδων καὶ γυναικῶν ἀπήντων ὀδυρόμενοι τὰς ἑαυτῶν τύχας. ὁ δὲ Κάμιλλος αὐτός τε πρὸς τὴν ὄψιν ἐπικλασθεὶς καὶ τοὺς Ῥωμαίους ὁρῶν ἐμφυομένων αὐτοῖς τῶν Σουτρίνων δακρύοντας καὶ δυσανασχετοῦντας ἐπὶ τοῖς γεγενημένοις, ἔγνω μὴ ποιεῖσθαι τῆς τιμωρίας ἀναβολήν, ἀλλ’ εὐθὺς ἄγειν ἐπὶ τὸ Σούτριον ἐκείνης τῆς ἡμέρας, λογιζόμενος ἀνθρώπους εὐδαίμονα καὶ πλουσίαν πόλιν ἄρτι κατειληφότας καὶ μηδένα τῶν πολεμίων ὑπολελοιπότας ἐν αὐτῇ μηδὲ προσδεχομένους ἔξωθεν, ἐκλελυμένους παντάπασι καὶ ἀφυλάκτους εὑρήσειν ὀρθῶς λογισάμενος, οὐ γὰρ μόνον τὴν χώραν ἔλαθε διελθών, ἀλλὰ καὶ πρὸς ταῖς πύλαις γενόμενος καὶ τὰ τείχη καταλαβών· ἐφύλαττε γὰρ οὐδείς, ἀλλ’ ἐν οἴνῳ καὶ συνουσίαις ἦσαν ἐσκεδασμένοι κατὰ τὰς οἰκίας. ἐπεὶ δὲ ᾔσθοντο τοὺς πολεμίους κρατοῦντας ἤδη, οὕτω διέκειντο μοχθηρῶς ὑπὸ πλησμονῆς καὶ μέθης, ὡς μηδὲ πρὸς φυγὴν ὁρμῆσαι πολλούς, ἀλλ’ ἐν ταῖς οἰκίαις αἴσχιστα πάντων ὑπομένοντας ἀποθνῄσκειν ἢ παραδιδόναι σφᾶς αὐτοὺς τοῖς πολεμίοις. τὴν μὲν οὖν Σουτρίνων πόλιν ἡμέρᾳ μιᾷ δὶς ἀλοῦσαν οὕτω συνέβη καὶ τοὺς ἔχοντας ἀποβαλεῖν, καὶ τοὺς ἀφῃρημένους ἀπολαβεῖν διὰ Κάμιλλον,", "st": "Cam. 35.1"}, {"sp": "N", "t": "ὁ δ’ ἀπὸ τούτων θρίαμβος αὐτῷ χάριν οὐκ ἐλάττονα καὶ κόσμον ἤνεγκε τῶν πρώτων δυεῖν. καὶ γὰρ τοὺς πάνυ βασκαίνοντας τῶν πολιτῶν καὶ πάντα βουλομένους εὐτυχίᾳ τινὶ μᾶλλον ἢ δι’ ἀρετὴν κατωρθῶσθαι, τότ’ ἠνάγκαζον αἱ πράξεις τῇ δεινότητι καὶ τῷ δραστηρίῳ τοῦ ἀνδρὸς ἀποδιδόναι τὴν δόξαν. ἦν δὲ τῶν διαμαχομένων αὐτῷ καὶ προσφθονούντων ἐπιφανέστατος Μᾶρκος Μάλλιος, ὁ πρῶτος ὠσάμενος τοὺς Κελτούς ἀπὸ τῆς ἄκρας ὅτε τῷ Καπιτωλίῳ νυκτὸς ἐπέθεντο καὶ διὰ τοῦτο Καπιτωλῖνος ἐπικληθείς. οὗτος γὰρ ἀξιῶν πρῶτος εἶναι τῶν πολιτῶν καὶ μὴ δυνάμενος τὸν Κάμιλλον ἀπὸ τοῦ βελτίστου τρόπου τῇ δόξῃ παρελθεῖν, ὑπόθεσιν τυραννίδος ἐποιήσατο κοινὴν καὶ συνήθη, δημαγωγῶν τοὺς πολλούς, μάλιστα δὲ τῶν ὀφειλόντων χρέα τοῖς μὲν ἀμύνων καὶ συνδικῶν ἐπὶ τοὺς δανειστάς, τοὺς δ’ ἀφαιρούμενος βίᾳ καὶ κωλύων ἄγεσθαι πρὸς τὸν νόμον, ὥστε πολλοὺς τῶν ἀπόρων ταχὺ περὶ αὐτὸν γενέσθαι καὶ πολὺν φόβον παρασχεῖν τοῖς βελτίστοις τῶν πολιτῶν θρασυνομένους καὶ ταράττοντας τὴν ἀγοράν. ἐπεὶ δὲ κατασταθεὶς ἐπὶ ταῦτα δικτάτωρ Κούιντος Καπιτωλῖνος εἰς τὴν εἱρκτὴν ἐνέβαλε τὸν Μάλλιον, ὁ δὲ δῆμος γενομένου τούτου μετέβαλε τὴν ἐσθῆτα, πρᾶγμα γινόμενον ἐπὶ συμφοραῖς μεγάλαις καὶ δημοσίαις, δείσασα τὸν θόρυβον ἡ σύγκλητος ἐκέλευσεν ἀφεθῆναι τὸν Μάλλιον. ὁ δ’ οὐδὲν ἦν ἀφεθεὶς ἀμείνων, ἀλλὰ σοβαρώτερον ἐδημαγώγει καὶ διεστασίαζε τὴν πόλιν. αἱροῦνται δὴ πάλιν χιλίαρχον τὸν Κάμιλλον.", "st": "Cam. 36.1"}, {"sp": "N", "t": "εἰσαγομένων δὲ τῶν κατὰ τοῦ Μαλλίου δικῶν μεγάλα τοὺς κατηγόρους ἔβλαπτεν ἡ ὄψις. ὁ γὰρ τόπος, ἐφ’ οὗ βεβηκὼς ὁ Μάλλιος ἐνυκτομάχησε πρὸς τοὺς Κελτούς, ὑπερεφαίνετο τῆς ἀγορᾶς ἀπὸ τοῦ Καπιτωλίου καὶ παρεῖχεν οἶκτον τοῖς ὁρῶσιν· αὐτός τε τὰς χεῖρας ὀρέγων ἐκεῖσε καὶ δακρύων ὑπεμίμνῃσκε τῶν ἀγώνων, ὥστε τοὺς κρίνοντας ἀπορεῖν καὶ πολλάκις ἀναβάλλεσθαι τὴν δίκην, μήτ’ ἀφεῖναι βουλομένους ἐπὶ τεκμηρίοις φανεροῖς τὸ ἀδίκημα μήτε χρήσασθαι τῷ νόμῳ δυναμένους ἐν ὀφθαλμοῖς τῆς πράξεως οὔσης διὰ τὸν τόπον. ὃ δὴ συμφρονήσας ὁ Κάμιλλος μετήγαγεν ἔξω πύλης τὸ δικαστήριον εἰς τὸ Πετηλῖνον ἄλσος· ὅθεν οὐκ ὄντος τοῦ Καπιτωλίου καταφανοῦς ὅ τε διώκων ἐχρήσατο τῇ κατηγορίᾳ καὶ τοῖς κρίνουσι παρεχώρησεν ἡ μνήμη τῶν γεγονότων ἀξίαν ἀναλαβεῖν ὀργὴν ἐπὶ τοῖς παροῦσιν ἀδικήμασιν. ὁ μὲν οὖν Μάλλιος ἁλοὺς εἰς τὸ Καπιτώλιον ἀπήχθη, καὶ κατὰ τῆς πέτρας ὠσθεὶς τὸν αὐτὸν τόπον ἔσχε καὶ τῶν εὐτυχεστάτων ἔργων καὶ τῶν μεγίστων ἀτυχημάτων μνημεῖον. οἱ δὲ Ῥωμαῖοι τὴν οἰκίαν αὐτοῦ κατασκάψαντες ἱερὸν ἱδρύσαντο θεᾶς, ἣν Μονῆταν καλοῦσι, καὶ τὸ λοιπὸν ἐψηφίσαντο μηδένα τῶν πατρικίων ἐπὶ τῆς ἄκρας κατοικεῖν.", "st": "Cam. 36.5"}, {"sp": "N", "t": "ὁ δὲ Κάμιλλος ἐπὶ χιλιαρχίαν ἕκτην καλούμενος παρῃτεῖτο, γεγονὼς μὲν ἡλικίας ἤδη πρόσω καί πού τινα καί φθόνον δεδιὼς καί νέμεσιν ἐπὶ δόξῃ τοσαύτῃ καί κατορθώμασιν· ἡ δὲ φανερωτάτη τῶν αἰτιῶν ἦν ἀρρωστία σώματος· ἐτύγχανε γὰρ νοσῶν περὶ τὰς ἡμέρας ἐκείνας. οὐ μὴν παρῆκεν αὐτῷ τὴν ἀρχὴν ὁ δῆμος, ἀλλὰ βοῶν μήτε ἱππεύοντος αὐτοῦ μήτε ὁπλομαχοῦντος ἐν τοῖς ἀγῶσι δεῖσθαι, βουλευομένου δὲ μόνον καί προστάττοντος, ἠνάγκασεν ὑποστῆναι τὴν στρατηγίαν καί μεθ’ ἑνὸς τῶν συναρχόντων Λευκίου Φουρίου τὸν στρατὸν ἄγειν εὐθὺς ἐπὶ τοὺς πολεμίους. οὗτοι δ’ ἦσαν Πραινεστῖνοι καί Οὐολοῦσκοι μετὰ πολλῆς δυνάμεως τὴν συμμαχίδα τῶν Ῥωμαίων πορθοῦντες. ἐξελθὼν δὲ καί παραστρατοπεδεύσας τοῖς πολεμίοις αὐτὸς μὲν ἠξίου τρίβειν τὸν πόλεμον χρόνῳ, κἂν εἰ μάχης δεήσειε ῥώσας τὸ σῶμα διαγωνίσασθαι, Λευκίου δὲ τοῦ συνάρχοντος ἐπιθυμίᾳ δόξης φερομένου πρὸς τὸν κίνδυνον ἀκατασχέτως καί συνεξορμῶντος ἅμα ταξιάρχους καί λοχαγούς, φοβηθεὶς μὴ φθόνῳ δή τινι δοκῇ κατόρθωμα καί φιλοτιμίαν ἀφαιρεῖσθαι νέων ἀνδρῶν συνεχώρησεν ἄκων ἐκείνῳ παρατάξαι τὴν δύναμιν, αὐτὸς δὲ διὰ τὴν ἀσθένειαν ὑπελείφθη μετ’ ὀλίγων ἐν τῷ στρατοπέδῳ. τοῦ δὲ Λευκίου προπετῶς χρησαμένου τῇ μάχῃ καί σφαλέντος, αἰσθόμενος τὴν τροπὴν τῶν Ῥωμαίων οὐ κατέσχεν αὑτόν, ἀλλ’ ἀναθορὼν ἐκ τῆς στιβάδος ἀπήντα μετὰ τῶν ὀπαδῶν ἐπὶ τὰς πύλας τοῦ χάρακος, διὰ τῶν φευγόντων ὠθούμενος εἰς τοὺς διώκοντας, ὥστε τοὺς μὲν εὐθὺς ἀναστρέφειν καί συνακολουθεῖν, τοὺς δὲ προσφερομένους ἔξωθεν ἵστασθαι πρὸ αὐτοῦ καὶ συνασπίζειν, παρεγγυῶντας ἀλλήλοις μὴ ἀπολείπεσθαι τοῦ στρατηγοῦ. τότε μὲν οὖν οὕτως ἀπετράποντο τῆς διώξεως οἱ πολέμιοι· τῇ δ’ ὑστεραίᾳ προαγαγὼν τὴν δύναμιν ὁ Κάμιλλος καί συνάψας μάχην αὐτούς τε νικᾷ κατὰ κράτος καὶ τὸν χάρακα λαμβάνει συνεισπεσὼν τοῖς φεύγουσι καί διαφθείρας τοὺς πλείστους, ἐκ δὲ τούτου πυθόμενος πόλιν Σατρίαν ὑπὸ Τυρρηνῶν ἑαλωκέναι καί τοὺς οἰκήτορας ἀπεσφάχθαι Ῥωμαίους ἅπαντας ὄντας, τὴν μὲν πολλὴν καί βαρεῖαν τῆς δυνάμεως εἰς Ῥώμην ἀπέστειλεν, αὐτὸς δὲ τοὺς ἀκμάζοντας μάλιστα καί προθυμοτάτους ἀναλαβών ἐπέβαλε τοῖς τὴν πόλιν ἔχουσι Τυρρηνοῖς καί κρατήσας τοὺς μὲν ἐξήλασεν αὐτῶν, τοὺς δὲ ἀπέκτεινεν.", "st": "Cam. 37.1"}, {"sp": "N", "t": "ἐπανελθὼν δὲ μετὰ πολλῶν λαφύρων εἰς Ῥώμην ἐπέδειξε φρονιμωτάτους ἁπάντων τοὺς μὴ φοβηθέντας ἀσθένειαν καὶ γῆρας ἡγεμόνος ἐμπειρίαν καὶ τόλμαν ἔχοντος, ἀλλ’ ἑλομένους ἐκεῖνον ἄκοντα καὶ νοσοῦντα μᾶλλον ἢ τῶν ἐν ἡλικίᾳ τοὺς δεομένους καὶ σπουδάζοντας ἄρχειν. διὸ καὶ Τουσκλανῶν ἀφεστάναι λεγομένων ἐκέλευον ἐξιέναι τὸν Κάμιλλον ἐπ’ αὐτούς ἕνα τῶν πέντε συστρατήγων προσελόμενον. ὁ δέ, καίπερ ἁπάντων βουλομένων καὶ δεομένων, ἐάσας τοὺς ἄλλους, προσείλετο Λεύκιον Φούριον οὐδενὸς ἂν προσδοκήσαντος· ἐκεῖνος γὰρ ἦν ὁ παρὰ γνώμην τοῦ Καμίλλου διαγωνίσασθαι προθυμηθεὶς ἔναγχος καὶ δυστυχήσας περὶ τὴν μάχην ἀλλὰ βουλόμενος, ὡς ἔοικεν, ἀποκρύψαι τὴν συμφορὰν καὶ τὴν αἰσχύνην ἀπαλλάξαι τοῦ ἀνδρός ἀντὶ πάντων τοῦτον προῆγεν. οἱ δὲ Τουσκλανοὶ τὴν ἁμαρτίαν ἐπανορθούμενοι πανούργως, ἤδη βαδίζοντος ἐπ’ αὐτούς τοῦ Καμίλλου τὸ μὲν πεδίον ἀνθρώπων ὡς ἐν εἰρήνῃ γεωργούντων καὶ νεμόντων ἐνέπλησαν, τὰς δὲ πύλας εἶχον ἀνεῳγμένας καὶ τοὺς παῖδας ἐν τοῖς διδασκαλείοις μανθάνοντας, τοῦ δὲ δήμου τὸ μὲν βάναυσον ἐπὶ τῶν ἐργαστηρίων ἑωρᾶτο περὶ τάς τέχνας, τὸ δ’ ἀστεῖον ἐπὶ τῆς ἀγορᾶς ἐν ἱματίοις οἱ δ’ ἄρχοντες περιῄεσαν σπουδῇ καταλύσεις τοῖς Ῥωμαίοις ἐπαγγέλλοντες, ὡς οὐδὲν κακὸν προσδοκῶντες οὐδὲ συνειδότες. τούτων δὲ πραττομένων ἀπιστεῖν μὲν οὐκ ἐπῄει τῷ Καμίλλῳ τὴν προδοσίαν, οἰκτείρας δὲ τὴν ἐπὶ τῇ προδοσίᾳ μετάνοιαν αὐτῶν ἐκέλευσε πρὸς τὴν σύγκλητον ἐλθόντας παραιτεῖσθαι τὴν ὀργήν καὶ παραιτουμένοις συνέπραξεν αὐτὸς ἀφεθῆναί τε τὴν πόλιν αἰτίας ἁπάσης καὶ μεταλαβεῖν ἰσοπολιτείας, αὗται μὲν οὖν ἐγένοντο τῆς ἕκτης χιλιαρχίας ἐπιφανέσταται πράξεις.", "st": "Cam. 38.1"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Λικιννίου Στόλωνος ἐν τῇ πόλει τὴν μεγάλην στάσιν ἐγείροντος, ἣν ὁ δῆμος ἐστασίαζε πρὸς τὴν σύγκλητον βιαζόμενος δυεῖν ὑπάτων καθισταμένων τὸν ἕτερον πάντως ἐκ δημοτῶν εἶναι καὶ μὴ συναμφοτέρους πατρικίους, δήμαρχοι μὲν ᾑρέθησαν, τὰς δ’ ὑπατικὰς ἀρχαιρεσίας ἐπιτελεσθῆναι διεκώλυσαν οἱ πολλοί. καὶ τῶν πραγμάτων δι’ ἀναρχίας φερομένων ἐς μείζονας ταραχάς ἀποδείκνυται δικτάτωρ ὁ Κάμιλλος ὑπὸ τῆς βουλῆς ἄκοντι τῷ δήμῳ τὸ τέταρτον, οὐδ’ αὐτὸς ὢν πρόθυμος οὐδὲ βουλόμενος ἐναντιοῦσθαι πρὸς ἀνθρώπους παρρησίαν ἔχοντας ἀπὸ πολλῶν καὶ μεγάλων ἀγώνων πρὸς αὐτόν, ὡς πλείονα μετ’ αὐτῶν διαπεπραγμένος ἐν στρατηγίαις ἢ μετὰ τῶν πατρικίων ἐν πολιτείαις, καὶ νῦν διὰ φθόνον ἐκείνων ᾑρημένος ὑπ’ αὐτῶν, ὅπως ἢ καταλύσειε τὸν δῆμον ἰσχύσας ἢ καταλυθείη μὴ κρατήσας. οὐ μὴν ἀλλὰ πειρώμενος ἀμύνειν τοῖς παροῦσι, τὴν ἡμέραν γνοὺς, ἐν ᾗ νομοθετεῖν οἱ δήμαρχοι διενοοῦντο, προέγραψε στρατιᾶς κατάλογον καὶ μετεκάλει τὸν δῆμον ἐκ τῆς ἀγορᾶς εἰς τὸ πεδίον μεγάλας ζημίας ἀπειλῶν κατὰ τοῦ μὴ ὑπακούσαντος. τῶν δὲ δημάρχων ἐκεῖθεν αὖ πάλιν ἀντανισταμένων ταῖς ἀπειλαῖς καὶ διομνυμένων πέντε μυριάσιν ἀργυρίου ζημιώσειν, εἰ μὴ παύσαιτο τοῦ δήμου τὸν νόμον ἀφαιρούμενοις καὶ τὴν ψῆφον, εἴτε δείσας φυγὴν ἑτέραν καὶ καταδίκην, ὡς ἀνδρὶ πρεσβύτῃ καὶ κατειργασμένῳ μεγάλα μὴ πρέπουσαν, εἴτε τοῦ δήμου τὴν βίαν ἄμαχον οὖσαν καὶ δυσνίκητον ὑπερβαλέσθαι μὴ δυνάμενος μηδὲ βουλόμενος, τότε μὲν ὑπεχώρησεν οἴκαδε· ταῖς δ’ ἑξῆς ἡμέραις σκηψάμενος ἀρρωστεῖν ἐξωμόσατο τὴν ἀρχήν.", "st": "Cam. 39.1"}, {"sp": "N", "t": "ἡ δὲ σύγκλητος ἕτερον δικτάτορα κατέστησε· κἀκεῖνος ἀποδείξας ἵππαρχον αὐτὸν τὸν ἡγεμόνα τῆς στάσεως Στόλωνα παρῆκεν ἐπικυρῶσαι τὸν νόμον τὸν μάλιστα λυποῦντα τοὺς πατρικίους, ἐκέλευσε δ’ οὗτος μηδένα πλέθρων πεντακοσίων πλείονα χώραν κεκτῆσθαι. τότε μὲν οὖν λαμπρὸς ὁ Στόλων ἐγεγόνει τῇ ψήφῳ κρατήσας· ὀλίγῳ δ’ ὕστερον αὐτὸς ἑάλω κεκτημένος ὅσην ἔχειν ἐκώλυεν ἑτέρους, καὶ κατὰ τὸν αὑτοῦ νόμον δίκην ἔδωκεν.", "st": "Cam. 39.5"}, {"sp": "N", "t": "ὑπολειπομένης δὲ τῆς περὶ τῶν ὑπατικῶν ἀρχαιρεσιῶν φιλονεικίας, ὃ δὴ χαλεπώτατον τῆς στάσεως ἦν καὶ πρῶτον ἦρξε καὶ πλεῖστα πράγματα τῇ βουλῇ παρέσχε διαφερομένῃ πρὸς τὸν δῆμον, ἀγγελίαι προσέπεσον σαφεῖς, Κελτοὺς αὖθις ἀπὸ τῆς Ἀδριατικῆς ἄραντας θαλάσσης μυριάσι πολλαῖς ἐπὶ τὴν Ῥώμην ἐλαύνειν. ἅμα δὲ τῷ λόγῳ καὶ τὰ ἔργα τοῦ πολέμου παρῆν πορθουμένης τῆς χώρας καὶ τῶν ἀνθρώπων, ὅσοις μὴ ῥᾴδιον ἦν εἰς τὴν Ῥώμην καταφυγεῖν, ἀνὰ τὰ ὄρη σκεδαννυμένων. οὗτος ὁ φόβος κατέπαυσε τὴν στάσιν, καὶ συνελθόντες εἰς ταὐτὸ τοῖς πολλοῖς οἱ κράτιστοι καὶ τῇ βουλῇ τὸ δημοτικὸν εἵλοντο πάντες ἐκ μιᾶς γνώμης δικτάτορα τὸ πέμπτον Κάμιλλον. ὁ δ’ ἦν μὲν σφόδρα γέρων καὶ μικρὸν ἀπέλειπεν ὀγδοήκοντα ἔτη γεγονέναι συνορῶν δὲ τὴν ἀνάγκην καὶ τὸν κίνδυνον, οὔτε ὑποτίμησιν εἰπών, ὡς πρότερον, οὔτε προφάσει χρησάμενος, ἀλλ’ αὐτόθεν ὑποστὰς τὴν στρατηγίαν κατέλεγε τοὺς μαχησομένους.", "st": "Cam. 40.1"}, {"sp": "N", "t": "εἰδὼς δὲ τῆς τῶν βαρβάρων ἀλκῆς τὴν βιαιοτάτην ἐν ταῖς μαχαίραις οὖσαν, ἃς βαρβαρικῶς καὶ σὺν οὐδεμιᾷ τέχνῃ καταφέροντες ὤμους μάλιστα καὶ κεφαλὰς διέκοπτον, ἐχαλκεύσατο μὲν κράνη τοῖς πλείστοις ὁλοσίδηρα καὶ λεῖα ταῖς περιφερείαις, ὡς ἀπολισθαίνειν ἢ κατάγνυσθαι τὰς μαχαίρας, τοῖς δὲ θυρεοῖς κύκλῳ περιήρμοσε λεπίδα χαλκῆν, τοῦ ξύλου καθ’ αὑτὸ τὰς πληγὰς μὴ στέγοντος· αὐτοὺς δὲ τοὺς στρατιώτας ἐδίδαξε τοῖς ὑσσοῖς μακροῖς διὰ χειρὸς χρῆσθαι καὶ τοῖς ξίφεσι τῶν πολεμίων ὑποβάλλοντας ἐκδέχεσθαι τὰς καταφοράς.", "st": "Cam. 40.4"}, {"sp": "N", "t": "ἐπεὶ δὲ πλησίον ἦσαν οἱ Κελτοί, περὶ τὸν Ἀνίωνα ποταμὸν στρατόπεδον βαρὺ καὶ μεστὸν ἀφθόνου λείας ἔχοντες, ἐξαγαγὼν τὴν δύναμιν ἵδρυσε κατὰ νάπης μαλακῆς καὶ συγκλίσεις πολλὰς ἐχούσης, ὥστε τὸ μὲν πλεῖστον ἀποκρύπτεσθαι, τὸ δ’ ὁρώμενον δοκεῖν ὑπὸ δέους εἰς χωρία προσάντη κατειλεῖσθαι. ταύτην δὲ τὴν δόξαν αὐτῶν ὁ Κάμιλλος αὔξειν βουλόμενος οὐ προσήμυνε τῶν ὑπὸ πόδας πορθουμένων, ἀλλὰ τὸν χάρακα φραξάμενος ἠρέμει, μέχρι οὗ τοὺς μὲν ἐν προνομαῖς ἐσκεδασμένους κατεῖδε, τοὺς δ’ ἐν τῷ στρατοπέδῳ πᾶσαν ὥραν ἐμπιπλαμένους ἀφειδῶς καὶ μεθύοντας. τότε δὲ νυκτὸς ἔτι τοὺς ψιλοὺς προεκπέμψας ἐμποδὼν εἶναι τοῖς βαρβάροις εἰς τάξιν καθισταμένοις καὶ διαταράττειν εὐθὺς ἐπεξιόντας, κατεβίβαζεν ὄρθρου τοὺς ὁπλίτας καὶ παρέταττεν ἐν τοῖς ἐπιπέδοις, πολλοὺς καὶ προθύμους, οὐχ ὥσπερ οἱ βάρβαροι προσεδόκων, ὀλίγους καὶ ἀτόλμους φανέντας. πρῶτον μὲν οὖν τοῦτο τῶν Κελτῶν ἀνέτρεψε τὰ φρονήματα παρ’ ἀξίαν ἐπιχειρεῖσθαι δοκούντων. ἔπειτα προσπίπτοντες οἱ ψιλοὶ καὶ πρὶν ἢ τὸν συνήθη λαβεῖν κόσμον καὶ διακριθῆναι κατὰ λόχους κινοῦντες αὐτοὺς καὶ βιαζόμενοι πρὸς τὸ συντυχὸν ἀτάκτους ἠνάγκασαν μάχεσθαι. τέλος δὲ τοῦ Καμίλλου τοὺς ὁπλίτας ἐπάγοντος, οἱ μὲν ἀνατεινάμενοι τὰς μαχαίρας συνδραμεῖν ἔσπευδον, οἱ δὲ τοῖς ὑσσοῖς ἀπαντῶντες καὶ τὰ σεσιδηρωμένα μέρη ταῖς πληγαῖς ὑποφέροντες ἀνέστρεφον τὸν ἐκείνων σίδηρον μαλακὸν ὄντα καὶ λεπτῶς ἐληλαμένον, ὥστε κάμπτεσθαι ταχὺ καὶ διπλοῦσθαι τὰς μαχαίρας, τοὺς δὲ θυρεοὺς συμπεπάρθαι καὶ βαρύνεσθαι τῶν ὑσσῶν ἐφελκομένων. διὸ καὶ μεθιστάμενοι τῶν ἰδίων ὅπλων ἐπειρῶντο τοῖς ἐκείνων συστρέφεσθαι καὶ τοὺς ὑσσοὺς παραφέρειν ἐπιλαμβανόμενοι ταῖς χερσίν. οἱ δὲ Ῥωμαῖοι γυμνουμένους ὁρῶντες ἤδη τοῖς ξίφεσιν ἐχρῶντο, καὶ φόνος μὲν ἦν πολὺς τῶν προτάκτων, φυγὴ δὲ τῶν ἄλλων πανταχόσε τοῦ πεδίου, τοὺς γὰρ λόφους καὶ τὰ ὑψηλὰ προκατειλήφει Κάμιλλος, τὸ δὲ στρατόπεδον διὰ τὸ θαρσεῖν ἄφρακτον ἔχοντες ᾔδεσαν οὐ χαλεπῶς ἁλωσόμενον.", "st": "Cam. 41.1"}, {"sp": "N", "t": "ταύτην τὴν μάχην ἔτεσιν ὕστερον τρισκαίδεκα γενέσθαι λέγουσι τῆς Ῥώμης ἁλώσεως, καὶ βέβαιον ἐξ αὐτῆς φρόνημα κατὰ τῶν Κελτῶν ἐγγενέσθαι Ῥωμαίοις σφόδρα δεδοικόσι τοὺς βαρβάρους, ὡς τὸ πρῶτον διὰ νόσους καὶ τύχας παραλόγους, οὐ κατὰ κράτος, ὑπ’ αὐτῶν νενικημένους, οὕτω δ’ οὖν ὁ φόβος ἦν ἰσχυρός, ὥστε θέσθαι νόμον ἀφεῖσθαι τοὺς ἱερεῖς στρατείας χωρὶς ἂν μὴ Γαλατικὸς ᾖ πόλεμος.", "st": "Cam. 41.6"}, {"sp": "N", "t": "τῶν μὲν οὖν στρατιωτικῶν ἀγώνων οὗτος ἠγωνίσθη τῷ Καμίλλῳ τελευταῖος, τὴν γὰρ Οὐελιτρανῶν πόλιν εἷλεν ἐν παρέργῳ ταύτης τῆς στρατείας ἀμαχεὶ προσχωρήσασαν αὐτῷ. τῶν δὲ πολιτικῶν ὁ μέγιστος ὑπελείπετο καὶ χαλεπώτερος πρὸς τὸν δῆμον ἰσχυρὸν ἐπανήκοντα τῇ νίκῃ καὶ βιαζόμενον ἐκ δημοτῶν ὕπατον ἀποδεῖξαι παρὰ τὸν καθεστῶτα νόμον, ἀντιταττομένης τῆς βουλῆς καὶ τὸν Κάμιλλον οὐκ ἐώσης ἀποθέσθαι τὴν ἀρχήν, ὡς μετ’ ἰσχυρᾶς καὶ μεγάλης ἐξουσίας τῆς ἐκείνου μαχησομένων ἂν βέλτιον ὑπὲρ τῆς ἀριστοκρατίας. ἐπεὶ δὲ προκαθημένου τοῦ Καμίλλου καὶ χρηματίζοντος ἐπὶ τῆς ἀγορᾶς ὑπηρέτης πεμφθεὶς παρὰ τῶν δημάρχων ἐκέλευσεν ἀκολουθεῖν καὶ τὴν χεῖρα τῷ σώματι προσῆγεν ὡς ἀπάξων, κραυγὴ δὲ καὶ θόρυβος, οἷος οὔπω, κατέσχε τὴν ἀγοράν, τῶν μὲν περὶ τὸν Κάμιλλον ὠθούντων ἀπὸ τοῦ βήματος τὸν δημόσιον, τῶν δὲ πολλῶν κάτωθεν ἕλκειν ἐπικελευομένων, ἀπορούμενος τοῖς παροῦσι τὴν μὲν ἀρχὴν οὐ προήκατο, τοὺς δὲ βουλευτὰς ἀναλαβὼν ἐβάδιζεν ἐπὶ τὴν σύγκλητον. καὶ πρὶν εἰσελθεῖν μεταστραφεὶς εἰς τὸ Καπιτώλιον εὔξατο τοῖς θεοῖς κατευθῦναι τὰ παρόντα πρὸς τὸ κάλλιστον τέλος, ὑποσχόμενος ναὸν Ὁμονοίας ἱδρύσασθαι τῆς ταραχῆς καταστάσης.", "st": "Cam. 42.1"}, {"sp": "N", "t": "μεγάλου δ’ ἀγῶνος ἐν τῇ συγκλήτῳ γενομένου πρὸς τὰς ἐναντίας γνώμας, ὅμως ἐνίκησεν ἡ μαλακωτέρα καὶ ὑπείκουσα τῷ δήμῳ καὶ διδοῦσα τῶν ὑπάτων τὸν ἕτερον ἀπὸ τοῦ πλήθους ἀρχαιρεσιάσαι. ταῦτα δ’ ὡς τῇ βουλῇ δοκοῦντα τοῦ δικτάτορος ἀνειπόντος ἐν τῷ δήμῳ, παραχρῆμα μὲν, οἷον εἰκὸς, ἡδόμενοι τῇ βουλῇ διηλλάττοντο καὶ τὸν Κάμιλλον οἴκαδε κρότῳ καὶ βοῇ προέπεμπον. τῇ δ’ ὑστεραίᾳ συνελθόντες ἐψηφίσαντο τῆς μὲν Ὁμονοίας ἱερόν, ὥσπερ εὔξατο Κάμιλλος, εἰς τὴν ἀγορὰν καὶ τὴν ἐκκλησίαν ἄποπτον ἐπὶ τοῖς γεγενημένοις ἱδρύσασθαι, ταῖς δὲ καλουμέναις Λατίναις μίαν ἡμέραν προσθέντας ἑορτάζειν τέτταρας, παραυτίκα δὲ θύειν καὶ στεφανηφορεῖν Ῥωμαίους ἅπαντας. τῶν δ’ ἀρχαιρεσίων βραβευθέντων ὑπὸ Καμίλλου κατεστάθησαν ὕπατοι Μᾶρκος μὲν Αἰμίλιος ἐκ πατρικίων, Λεύκιος δὲ Σέξτιος ἐκ δημοτῶν πρῶτος, καὶ τοῦτο πέρας αἱ Καμίλλου πράξεις ἔσχον.", "st": "Cam. 42.4"}, {"sp": "N", "t": "ἐν δὲ τῷ κατόπιν ἐνιαυτῷ λοιμώδης νόσος ἐμπεσοῦσα τῇ Ῥώμῃ τὸν μὲν ἄλλον ὄχλον οὐ περιληπτὸν ἀριθμῷ διέφθειρε, τῶν δ’ ἀρχόντων τοὺς πλείστους. ἐτελεύτησε δὲ καὶ Κάμιλλος, ἡλικίας μὲν οὕνεκα καὶ βίου τελειότητος, ὡς εἴ τις ἄλλος ἀνθρώπων ὡραῖος, ἀνιάσας δὲ Ῥωμαίους ὡς οὐδὲ σύμπαντες οἱ τῇ νόσῳ κατ’ ἐκεῖνον τὸν χρόνον ἀποθανόντες.", "st": "Cam. 43.1"}, {"sp": "HDR", "t": "Περικλῆς"}, {"sp": "N", "t": "ξένους τινὰς ἐν Ῥώμῃ πλουσίους κυνῶν τέκνα καὶ πιθήκων ἐν τοῖς κόλποις περιφέροντας καὶ ἀγαπῶντας ἰδὼν ὁ Καῖσαρ, ὡς ἔοικεν, ἠρώτησεν εἰ παιδία παρ’ αὐτοῖς οὐ τίκτουσιν αἱ γυναῖκες, ἡγεμονικῶς σφόδρα νουθετήσας τοὺς τὸ φύσει φιλητικὸν ἐν ἡμῖν καὶ φιλόστοργον εἰς θηρία καταναλίσκοντας ἀνθρώποις ὀφειλόμενον. ἆρ’ οὖν, ἐπεὶ φιλομαθές τι κέκτηται καὶ φιλοθέαμον ἡμῶν ἡ ψυχὴ φύσει, λόγον ἔχει ψέγειν τοὺς καταχρωμένους τούτῳ πρὸς τὰ μηδεμιᾶς ἄξια σπουδῆς ἀκούσματα καὶ θεάματα, τῶν δὲ καλῶν καὶ ὠφελίμων παραμελοῦντας; τῇ μὲν γὰρ αἰσθήσει κατὰ πάθος τῆς πληγῆς ἀντιλαμβανομένῃ τῶν προστυγχανόντων ἴσως ἀνάγκη πᾶν τὸ φαινόμενον, ἄν τε χρήσιμον ἄν τ’ ἄχρηστον ᾖ, θεωρεῖν, τῷ νῷ δ’ ἕκαστος εἰ βούλοιτο χρῆσθαι, καὶ τρέπειν ἑαυτὸν ἀεὶ καὶ μεταβάλλειν ῥᾷστα πρὸς τὸ δοκοῦν πέφυκεν, ὥστε χρὴ διώκειν τὸ βέλτιστον, ἵνα μὴ θεωρῇ μόνον, ἀλλὰ καὶ τρέφηται τῷ θεωρεῖν. ὡς γὰρ ὀφθαλμῷ χρόα πρόσφορος ἧς τὸ ἀνθηρὸν ἅμα καὶ τερπνὸν ἀναζωπυρεῖ καὶ τρέφει τὴν ὄψιν, οὕτω τὴν διάνοιαν ἐπάγειν δεῖ θεάμασιν ἃ τῷ χαίρειν πρὸς τὸ οἰκεῖον αὐτὴν ἀγαθὸν ἐκκαλεῖ.", "st": "Per. 1.1"}, {"sp": "N", "t": "ταῦτα δὲ ἔστιν ἐν τοῖς ἀπ’ ἀρετῆς ἔργοις, ἃ καὶ ζῆλόν τινα καὶ προθυμίαν ἀγωγὸν εἰς μίμησιν ἐμποιεῖ τοῖς ἱστορήσασιν· ἐπεὶ τῶν γ’ ἄλλων οὐκ εὐθὺς ἀκολουθεῖ τῷ θαυμάσαι τὸ πραχθὲν ὁρμὴ πρὸς τὸ πρᾶξαι· πολλάκις δὲ καὶ τοὐναντίον χαίροντες τῷ ἔργῳ τοῦ δημιουργοῦ καταφρονοῦμεν, ὡς ἐπὶ τῶν μύρων καὶ τῶν ἁλουργῶν τούτοις μὲν ἡδόμεθα, τοὺς δὲ βαφεῖς καὶ μυρεψοὺς ἀνελευθέρους ἡγούμεθα καὶ βαναύσους. διὸ καλῶς μὲν Ἀντισθένης ἀκούσας ὅτι σπουδαῖός ἐστιν αὐλητὴς Ἰσμηνίας, ἀλλ’ ἄνθρωπος, ἔφη, μοχθηρός· οὐ γὰρ ἂν οὕτω σπουδαῖος ἦν αὐλητής· ὁ δὲ Φίλιππος πρὸς τὸν υἱὸν ἐπιτερπῶς ἔν τινι πότῳ ψήλαντα καὶ τεχνικῶς εἶπεν· οὐκ αἰσχύνῃ καλῶς οὕτω ψάλλων; ἀρκεῖ γάρ, ἂν βασιλεὺς ἀκροᾶσθαι ψαλλόντων σχολάζῃ, καὶ πολὺ νέμει ταῖς Μούσαις ἑτέρων ἀγωνιζομένων τὰ τοιαῦτα θεατὴς γιγνόμενος.", "st": "Per. 1.4"}, {"sp": "N", "t": "ἡ δ’ αὐτουργία τῶν ταπεινῶν τῆς εἰς τὰ καλὰ ῥᾳθυμίας μάρτυρα τὸν ἐν τοῖς ἀχρήστοις πόνον παρέχεται καθ’ αὑτῆς· καὶ οὐδεὶς εὐφυὴς νέος ἢ τὸν ἐν Πίσῃ θεασάμενος Δία γενέσθαι Φειδίας ἐπεθύμησεν ἢ τὴν Ἥραν τὴν ἐν Ἄργει Πολύκλειτος, οὐδ’ Ἀνακρέων ἢ Φιλητᾶς ἢ Ἀρχίλοχος ἡσθεὶς αὐτῶν τοῖς ποιήμασιν. οὐ γὰρ ἀναγκαῖον, εἰ τέρπει τὸ ἔργον ὡς χάριεν, ἄξιον σπουδῆς εἶναι τὸν εἰργασμένον. ὅθεν οὐδ’ ὠφελεῖ τὰ τοιαῦτα τοὺς θεωμένους, πρὸς ἃ μιμητικὸς οὐ γίνεται ζῆλος οὐδὲ ἀνάδοσις κινοῦσα προθυμίαν καὶ ὁρμὴν ἐπὶ τὴν ἐξομοίωσιν. ἀλλ’ ἥ γε ἀρετὴ ταῖς πράξεσιν εὐθὺς οὕτω διατίθησιν ὥστε ἅμα θαυμάζεσθαι τὰ ἔργα καὶ ζηλοῦσθαι τοὺς εἰργασμένους. τῶν μὲν γὰρ ἐκ τῆς τύχης ἀγαθῶν τὰς κτήσεις καὶ ἀπολαύσεις, τῶν δ’ ἀπ’ ἀρετῆς τὰς πράξεις ἀγαπῶμεν, καὶ τὰ μὲν ἡμῖν παρ’ ἑτέρων, τὰ δὲ μᾶλλον ἑτέροις παρ’ ἡμῶν ὑπάρχειν βουλόμεθα. τὸ γὰρ καλὸν ἐφ’ αὑτὸ πρακτικῶς κινεῖ καὶ πρακτικὴν εὐθὺς ὁρμὴν ἐντίθησιν, ἠθοποιοῦν οὐ τῇ μιμήσει τὸν θεατήν, ἀλλὰ τῇ ἱστορίᾳ τοῦ ἔργου τὴν προαίρεσιν παρεχόμενον.", "st": "Per. 2.1"}, {"sp": "N", "t": "ἔδοξεν οὖν καὶ ἡμῖν ἐνδιατρῖψαι τῇ περὶ τοὺς βίους ἀναγραφῇ, καὶ τοῦτο τὸ βιβλίον δέκατον συντετάχαμεν τὸν Ποερικλέους βίον καὶ τὸν Φαβίου Μαξίμου τοῦ διαπολεμήσαντος πρὸς Ἀννίβαν περιέχον, ἀνδρῶν κατά τε τὰς ἄλλας ἀρετὰς ὁμοίων, μάλιστα δὲ πρᾳότητα καὶ δικαιοσύνην, καὶ τῷ δύνασθαι φέρειν δήμων καὶ συναρχόντων ἀγνωμοσύνας ὠφελιμωτάτων ταῖς πατρίσι γενομένων. εἰ δ’ ὀρθῶς στοχαζόμεθα τοῦ δέοντος, ἔξεστι κρίνειν ἐκ τῶν γραφομένων.", "st": "Per. 2.4"}, {"sp": "N", "t": "Περικλῆς γὰρ ἦν τῶν μὲν φυλῶν Ἀκαμαντίδης, τῶν δὲ δήμων Χολαργεύς, οἴκου δὲ καὶ γένους τοῦ πρώτου κατ’ ἀμφοτέρους. Ξάνθιππος γὰρ ὁ νικήσας ἐν Μυκάλῃ τοὺς βασιλέως στρατηγοὺς ἔγημεν Ἀγαρίστην Κλεισθένους ἔγγονον, ὃς ἐξήλασε Πεισιστρατίδας καὶ κατέλυσε τὴν τυραννίδα γενναίως καὶ νόμους ἔθετο καὶ πολιτείαν ἄριστα κεκραμένην πρὸς ὁμόνοιαν καὶ σωτηρίαν κατέστησεν. αὕτη κατὰ τοὺς ὕπνους ἔδοξε τεκεῖν λέοντα, καὶ μεθ’ ἡμέρας ὀλίγας ἔτεκε Περικλέα, τὰ μὲν ἄλλα τὴν ἰδέαν τοῦ σώματος ἄμεμπτον, προμήκη δὲ τῇ κεφαλῇ καὶ ἀσύμμετρον. ὅθεν αἱ μὲν εἰκόνες αὐτοῦ σχεδὸν ἅπασαι κράνεσι περιέχονται, μὴ βουλομένων, ὡς ἔοικε, τῶν τεχνιτῶν ἐξονειδίζειν. οἱ δ’ Ἀττικοὶ ποιηταὶ σχινοκέφαλον αὐτὸν ἐκάλουν· τὴν γὰρ σκίλλαν ἔστιν ὅτε καὶ σχῖνον ὀνομάζουσι. τῶν δὲ κωμικῶν ὁ μὲν Κρατῖνος ἐν Χείρωσι· στάσις δὲ (φησὶ) καὶ πρεσβυγενὴς Κρόνος ἀλλήλοισι μιγέντε μέγιστον τίκτετον τύραννον, ὃν δὴ κεφαληγερέταν θεοὶ καλέουσι· καὶ πάλιν ἐν Νεμέσει· μόλ’, ὦ Ζεῦ ξένιε καὶ καραιέ. Τηλεκλείδης δὲ ποτὲ μὲν ὑπὸ τῶν πραγμάτων ἠπορημένον καθῆσθαί φησιν αὐτὸν ἐν τῇ πόλει καρηβαροῦντα, ποτὲ δὲ μόνον ἐκ κεφαλῆς ἑνδεκακλίνου θόρυβον πολὺν ἐξανατέλλειν· ὁ δ’ Εὔπολις ἐν τοῖς Δήμοις πυνθανόμενος περὶ ἑκάστου τῶν ἀναβεβηκότων ἐξ ᾅδου δημαγωγῶν, ὡς ὁ Περικλῆς ὠνομάσθη τελευταῖος·", "st": "Per. 3.1"}, {"sp": "N", "t": "ὅ τι περ κεφάλαιον τῶν κάτωθεν ἤγαγες.", "st": "Per. 3.1b"}, {"sp": "N", "t": "διδάσκαλον δ’ αὐτοῦ τῶν μουσικῶν οἱ πλεῖστοι Δάμωνα γενέσθαι λέγουσιν, οὗ φασι δεῖν τοὔνομα βραχύνοντας τὴν προτέραν συλλαβὴν ἐκφέρειν· Ἀριστοτέλης δὲ παρὰ Πυθοκλείδῃ μουσικὴν διαπονηθῆναι τὸν ἄνδρα φησίν. ὁ δὲ Δάμων ἔοικεν ἄκρος ὢν σοφιστὴς καταδύεσθαι μὲν εἰς τὸ τῆς μουσικῆς ὄνομα πρὸς τοὺς πολλοὺς ἐπικρυπτόμενος τὴν δεινότητα, τῷ δὲ Περικλεῖ συνῆν καθάπερ ἀθλητῇ τῶν πολιτικῶν ἀλείπτης καὶ διδάσκαλος. οὐ μὴν ἔλαθεν ὁ Δάμων τῇ λύρα παρακαλύμματι χρώμενος, ἀλλ’ ὡς μεγαλοπράγμων καὶ φιλοτύραννος ἐξωστρακίσθη καὶ παρέσχε τοῖς κωμικοῖς διατριβήν. ὁ γοῦν Πλάτων καὶ πυνθανόμενον αὐτοῦ τινα πεποίηκεν οὕτω·", "st": "Per. 4.1"}, {"sp": "N", "t": "πρῶτον μὲν οὖν μοι λέξον, ἀντιβολῶ· σὺ γὰρ,<br>ὥς φασιν, ὁ Χείρων ἐξέθρεψας Περικλέα.", "st": "Per. 4.1b"}, {"sp": "N", "t": "διήκουσε δὲ Περικλῆς καὶ Ζήνωνος τοῦ Ἐλεάτου πραγματευομένου περὶ φύσιν, ὡς Παρμενίδης, ἐλεγκτικὴν δέ τινα καὶ δι’ ἀντιλογίας κατακλείουσαν εἰς ἀπορίαν ἐξασκήσαντος ἕξιν, ὥσπερ καὶ Τίμων ὁ Φλιάσιος εἴρηκε διὰ τούτων·", "st": "Per. 4.3"}, {"sp": "N", "t": "ἀμφοτερογλώσσου τε μέγα σθένος οὐκ ἀλαπαδνὸν<br>Ζήνωνος, πάντων ἐπιλήπτορος.", "st": "Per. 4.3b"}, {"sp": "N", "t": "ὁ δὲ πλεῖστα Περικλεῖ συγγενόμενος καὶ μάλιστα περιθεὶς ὄγκον αὐτῷ καὶ φρόνημα δημαγωγίας ἐμβριθέστερον, ὅλως τε μετεωρίσας καὶ συνεξάρας τὸ ἀξίωμα τοῦ ἤθους, Ἀναξαγόρας ἦν ὁ Κλαζομένιος, ὃν οἱ τότ’ ἄνθρωποι Νοῦν προσηγόρευον, εἴτε τὴν σύνεσιν αὐτοῦ μεγάλην εἰς φυσιολογίαν καὶ περιττὴν διαφανεῖσαν θαυμάσαντες, εἴθ’ ὅτι τοῖς ὅλοις πρῶτος οὐ τύχην οὐδ’ ἀνάγκην διακοσμήσεως ἀρχήν, ἀλλὰ νοῦν ἐπέστησε καθαρὸν καὶ ἄκρατον ἐν μεμιγμένοις πᾶσι τοῖς ἄλλοις, ἀποκρίνοντα τὰς ὁμοιομερείας.", "st": "Per. 4.4"}, {"sp": "N", "t": "τοῦτον ὑπερφυῶς τὸν ἄνδρα θαυμάσας ὁ Περικλῆς καὶ τῆς λεγομένης μετεωρολογίας καὶ μεταρσιολεσχίας ὑποπιμπλάμενος, οὐ μόνον, ὡς ἔοικε, τὸ φρόνημα σοβαρὸν καὶ τὸν λόγον ὑψηλὸν εἶχε καὶ καθαρὸν ὀχλικῆς καὶ πανούργου βωμολοχίας, ἀλλὰ καὶ προσώπου σύστασις ἄθρυπτος εἰς γέλωτα καὶ πρᾳότης πορείας καὶ καταστολὴ περιβολῆς πρὸς οὐδὲν ἐκταραττομένη πάθος ἐν τῷ λέγειν καὶ πλάσμα φωνῆς ἀθόρυβον, καὶ ὅσα τοιαῦτα πάντας θαυμαστῶς ἐξέπληττε. λοιδορούμενος γοῦν ποτε καὶ κακῶς ἀκούων ὑπό τινος τῶν βδελυρῶν καὶ ἀκολάστων ὅλην ἡμέραν ὑπέμεινε σιωπῇ κατ’ ἀγοράν, ἅμα τι τῶν ἐπειγόντων καταπραττόμενος· ἑσπέρας δ’ ἀπῄει κοσμίως οἴκαδε παρακολουθοῦντος τοῦ ἀνθρώπου καὶ πάσῃ χρωμένου βλασφημίᾳ πρὸς αὐτόν. ὡς δ’ ἔμελλεν εἰσιέναι σκότους ὄντος ἤδη, προσέταξέ τινι τῶν οἰκετῶν φῶς λαβόντι παραπέμψαι καὶ καταστῆσαι πρὸς τὴν οἰκίαν τὸν ἄνθρωπον.", "st": "Per. 5.1"}, {"sp": "N", "t": "ὁ δὲ ποιητὴς Ἴων μοθωνικήν φησι τὴν ὁμιλίαν καὶ ὑπότυφον εἶναι τοῦ Περικλέους, καὶ ταῖς μεγαλαυχίαις αὐτοῦ πολλὴν ὑπεροψίαν ἀναμεμῖχθαι καὶ περιφρόνησιν τῶν ἄλλων· ἐπαινεῖ δὲ τὸ Κίμωνος ἐμμελὲς καὶ ὑγρὸν καὶ μεμουσωμένον ἐν ταῖς περιφοραῖς. ἀλλ’ Ἴωνα μέν, ὥσπερ τραγικὴν διδασκαλίαν, ἀξιοῦντα τὴν ἀρετὴν ἔχειν τι πάντως καὶ σατυρικὸν μέρος ἐῶμεν· τοὺς δὲ τοῦ Περικλέους τὴν σεμνότητα δοξοκοπίαν τε καὶ τῦφον ἀποκαλοῦντας ὁ Ζήνων παρεκάλει καὶ αὐτούς τι τοιοῦτο δοξοκοπεῖν, ὡς τῆς προσποιήσεως αὐτῆς τῶν καλῶν ὑποποιούσης τινὰ λεληθότως ζῆλον καὶ συνήθειαν.", "st": "Per. 5.4"}, {"sp": "N", "t": "οὐ μόνον δὲ ταῦτα τῆς Ἀναξαγόρου συνουσίας ἀπέλαυσε Περικλῆς, ἀλλὰ καὶ δεισιδαιμονίας δοκεῖ γενέσθαι καθυπέρτερος, ὅσην τὸ πρὸς τὰ μετέωρα θάμβος ἐνεργάζεται τοῖς αὐτῶν τε τούτων τὰς αἰτίας ἀγνοοῦσι καὶ περὶ τὰ θεῖα δαιμονῶσι καὶ ταραττομένοις δι’ ἀπειρίαν αὐτῶν, ἣν ὁ φυσικὸς λόγος ἀπαλλάττων ἀντὶ τῆς φοβερᾶς καὶ φλεγμαινούσης δεισιδαιμονίας τὴν ἀσφαλῆ μετ’ ἐλπίδων ἀγαθῶν εὐσέβειαν ἐργάζεται.", "st": "Per. 6.1"}, {"sp": "N", "t": "λέγεται δέ ποτε κριοῦ μονόκερω κεφαλὴν ἐξ ἀγροῦ τῷ Περικλεῖ κομισθῆναι, καὶ Λάμπωνα μὲν τὸν μάντιν, ὡς εἶδε τὸ κέρας ἰσχυρὸν καὶ στερεὸν ἐκ μέσου τοῦ μετώπου πεφυκός, εἰπεῖν ὅτι δυεῖν οὐσῶν ἐν τῇ πόλει δυναστειῶν, τῆς Θουκυδίδου καὶ Περικλέους, εἰς ἕνα περιστήσεται τὸ κράτος παρ’ ᾧ γένοιτο τὸ σημεῖον· τὸν δ’ Ἀναξαγόραν τοῦ κρανίου διακοπέντος ἐπιδεῖξαι τὸν ἐγκέφαλον οὐ πεπληρωκότα τὴν βάσιν, ἀλλ’ ὀξὺν ὥσπερ ὠὸν ἐκ τοῦ παντὸς ἀγγείου συνωλισθηκότα κατὰ τὸν τόπον ἐκεῖνον ὅθεν ἡ ῥίζα τοῦ κέρατος εἶχε τὴν ἀρχήν. καὶ τότε μὲν θαυμασθῆναι τὸν Ἀναξαγόραν ὑπὸ τῶν παρόντων, ὀλίγῳ δ’ ὕστερον τὸν Λάμπωνα, τοῦ μὲν Θουκυδίδου καταλυθέντος, τῶν δὲ τοῦ δήμου πραγμάτων ὁμαλῶς ἁπάντων ὑπὸ τῷ Περικλεῖ γενομένων.", "st": "Per. 6.2"}, {"sp": "N", "t": "ἐκώλυε δ’ οὐδέν, οἶμαι, καὶ τὸν φυσικὸν ἐπιτυγχάνειν καὶ τὸν μάντιν, τοῦ μὲν τὴν αἰτίαν, τοῦ δὲ τὸ τέλος καλῶς ἐκλαμβάνοντος· ὑπέκειτο γὰρ τῷ μέν, ἐκ τίνων γέγονε καὶ πῶς πέφυκε, θεωρῆσαι, τῷ δέ, πρὸς τί γέγονε καὶ τί σημαίνει, προειπεῖν. οἱ δὲ τῆς αἰτίας τὴν εὕρεσιν ἀναίρεσιν εἶναι λέγοντες τοῦ σημείου οὐκ ἐπινοοῦσιν ἅμα τοῖς θείοις καὶ τὰ τεχνητὰ τῶν συμβόλων ἀθετοῦντες, ψόφους τε δίσκων καὶ φῶτα πυρσῶν καὶ γνωμόνων ἀποσκιασμούς· ὧν ἕκαστον αἰτίᾳ τινὶ καὶ κατασκευῇ σημεῖον εἶναί τινος πεποίηται. ταῦτα μὲν οὖν ἴσως ἑτέρας ἐστὶ πραγματείας.", "st": "Per. 6.4"}, {"sp": "N", "t": "ὁ δὲ Περικλῆς νέος μὲν ὢν σφόδρα τὸν δῆμον εὐλαβεῖτο. καὶ γὰρ ἐδόκει Πεισιστράτῳ τῷ τυράννῳ τὸ εἶδος ἐμφερὴς εἶναι, τήν τε φωνὴν ἡδεῖαν οὖσαν αὐτοῦ καὶ τὴν γλῶτταν εὔτροχον ἐν τῷ διαλέγεσθαι καὶ ταχεῖαν οἱ σφόδρα γέροντες ἐξεπλήττοντο πρὸς τὴν ὁμοιότητα. πλούτου δὲ καὶ γένους προσόντος αὐτῷ λαμπροῦ καὶ φίλων οἳ πλεῖστον ἠδύναντο, φοβούμενος ἐξοστρακισθῆναι, τῶν μὲν πολιτικῶν οὐδὲν ἔπραττεν, ἐν δὲ ταῖς στρατείαις ἀνὴρ ἀγαθὸς ἦν καὶ φιλοκίνδυνος. ἐπεὶ δ’ Ἀριστείδης μὲν ἀποτεθνήκει καὶ Θεμιστοκλῆς ἐξεπεπτώκει, Κίμωνα δ’ αἱ στρατεῖαι τὰ πολλὰ τῆς Ἑλλάδος ἔξω κατεῖχον, οὕτω δὴ φέρων ὁ Περικλῆς τῷ δήμῳ προσένειμεν ἑαυτόν, ἀντὶ τῶν πλουσίων καὶ ὀλίγων τὰ τῶν πολλῶν καὶ πενήτων ἑλόμενος παρὰ τὴν αὑτοῦ φύσιν ἥκιστα δημοτικὴν οὖσαν. ἀλλ’, ὡς ἔοικε, δεδιὼς μὲν ὑποψίᾳ περιπεσεῖν τυραννίδος, ὁρῶν δ’ ἀριστοκρατικὸν τὸν Κίμωνα καὶ διαφερόντως ὑπὸ τῶν καλῶν κἀγαθῶν ἀνδρῶν ἀγαπώμενον, ὑπῆλθε τοὺς πολλούς, ἀσφάλειαν μὲν ἑαυτῷ, δύναμιν δὲ κατ’ ἐκείνου παρασκευαζόμενος.", "st": "Per. 7.1"}, {"sp": "N", "t": "εὐθὺς δὲ καὶ τοῖς περὶ τὴν δίαιταν ἑτέραν τάξιν ἐπέθηκεν. ὁδόν τε γὰρ ἐν ἄστει μίαν ἑωρᾶτο τὴν ἐπ’ ἀγορὰν καὶ τὸ βουλευτήριον πορευόμενος, κλήσεις τε δείπνων καὶ τὴν τοιαύτην ἅπασαν φιλοφροσύνην καὶ συνήθειαν ἐξέλιπεν, ὡς ἐν οἷς ἐπολιτεύσατο χρόνοις μακροῖς γενομένοις πρὸς μηδένα τῶν φίλων ἐπὶ δεῖπνον ἐλθεῖν, πλὴν Εὐρυπτολέμου τοῦ ἀνεψιοῦ γαμοῦντος ἄχρι τῶν σπονδῶν παραγενόμενος εὐθὺς ἐξανέστη. δειναὶ γὰρ αἱ φιλοφροσύναι παντὸς ὄγκου περιγενέσθαι, καὶ δυσφύλακτον ἐν συνηθείᾳ τὸ πρὸς δόξαν σεμνόν ἐστι· τῆς ἀληθινῆς δ’ ἀρετῆς κάλλιστα φαίνεται τὰ μάλιστα φαινόμενα, καὶ τῶν ἀγαθῶν ἀνδρῶν οὐδὲν οὕτω θαυμάσιον τοῖς ἐκτὸς ὡς ὁ καθ’ ἡμέραν βίος τοῖς συνοῦσιν.", "st": "Per. 7.4"}, {"sp": "N", "t": "ὁ δὲ καὶ τῷ δήμῳ τὸ συνεχὲς φεύγων καὶ τὸν κόρον οἷον ἐκ διαλειμμάτων ἐπλησίαζεν, οὐκ ἐπὶ παντὶ πράγματι λέγων, οὐδ’ ἀεὶ παριὼν εἰς τὸ πλῆθος, ἀλλ’ ἑαυτὸν ὥσπερ τὴν Σαλαμινίαν τριήρη, φησὶ Κριτόλαος, πρὸς τὰς μεγάλας χρείας ἐπιδιδούς, τἆλλα δὲ φίλους καὶ ῥήτορας ἑτέρους καθιεὶς ἔπραττεν. ὧν ἕνα φασὶ γενέσθαι τὸν Ἐφιάλτην, ὃς κατέλυσε τὸ κράτος τῆς ἐξ Ἀρείου πάγου βουλῆς, πολλήν, κατὰ τὸν Πλάτωνα, καὶ ἄκρατον τοῖς πολίταις ἐλευθερίαν οἰνοχοῶν, ὑφ’ ἧς, ὥσπερ ἵππον, ἐξυβρίσαντα τὸν δῆμον οἱ κωμῳδοποιοὶ λέγουσι πειθαρχεῖν οὐκέτι τολμᾶν, ἀλλὰ δάκνειν τὴν Εὔβοιαν καὶ ταῖς νήσοις ἐπιπηδᾶν.", "st": "Per. 7.6"}, {"sp": "N", "t": "τῇ μέντοι περὶ τὸν βίον κατασκευῇ καὶ τῷ μεγέθει τοῦ φρονήματος ἁρμόζοντα λόγον, ὥσπερ ὄργανον, ἐξαρτυόμενος παρενέτεινε πολλαχοῦ τὸν Ἀναξαγόραν, οἷον βαφὴν τῇ ῥητορικῇ τὴν φυσιολογίαν ὑποχεόμενος. τὸ γὰρ ὑψηλόνουν τοῦτο καὶ πάντη τελεσιουργόν, ὡς ὁ θεῖος Πλάτων φησί, πρὸς τῷ εὐφυὴς εἶναι κτησάμενος ἐκ φυσιολογίας, καὶ τὸ πρόσφορον ἑλκύσας ἐπὶ τὴν τῶν λόγων τέχνην, πολὺ πάντων διήνεγκε. διὸ καὶ τὴν ἐπίκλησιν αὐτῷ γενέσθαι λέγουσι· καίτοι τινὲς ἀπὸ τῶν οἷς ἐκόσμησε τὴν πόλιν, οἱ δ’ ἀπὸ τῆς ἐν τῇ πολιτείᾳ καὶ ταῖς στρατηγίαις δυνάμεως Ὀλύμπιον αὐτὸν οἴονται προσαγορευθῆναι· καὶ συνδραμεῖν οὐδὲν ἀπέοικεν ἀπὸ πολλῶν προσόντων τῷ ἀνδρὶ τὴν δόξαν. αἱ μέντοι κωμῳδίαι τῶν τότε διδασκάλων σπουδῇ τε πολλὰς καὶ μετὰ γέλωτος ἀφεικότων φωνὰς εἰς αὐτόν, ἐπὶ τῷ λόγῳ μάλιστα τὴν προσωνυμίαν γενέσθαι δηλοῦσι, βροντᾶν μὲν αὐτὸν καὶ ἀστράπτειν, ὅτε δημηγοροίη, δεινὸν δὲ κεραυνὸν ἐν γλώσσῃ φέρειν λεγόντων.", "st": "Per. 8.1"}, {"sp": "N", "t": "διαμνημονεύεται δέ τις καὶ Θουκυδίδου τοῦ Μελησίου λόγος εἰς τὴν δεινότητα τοῦ Περικλέους μετὰ παιδιᾶς εἰρημένος. ἦν μὲν γὰρ ὁ Θουκυδίδης τῶν καλῶν καὶ ἀγαθῶν ἀνδρῶν, καὶ πλεῖστον ἀντεπολιτεύσατο τῷ Περικλεῖ χρόνον· Ἀρχιδάμου δὲ τοῦ Λακεδαιμονίων βασιλέως πυνθανομένου πότερον αὐτὸς ἢ Περικλῆς παλαίει βέλτιον, ὅταν, εἶπεν, ἐγὼ καταβάλω παλαίων, ἐκεῖνος ἀντιλέγων ὡς οὐ πέπτωκε, νικᾷ καὶ μεταπείθει τοὺς ὁρῶντας.", "st": "Per. 8.4"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ αὐτὸς ὁ Περικλῆς περὶ τὸν λόγον εὐλαβὴς ἦν, ὥστ’ ἀεὶ πρὸς τὸ βῆμα βαδίζων εὔχετο τοῖς θεοῖς μηδὲ ῥῆμα μηδὲν ἐκπεσεῖν ἄκοντος αὐτοῦ πρὸς τὴν προκειμένην χρείαν ἀνάρμοστον. ἔγγραφον μὲν οὖν οὐδὲν ἀπολέλοιπε πλὴν τῶν ψηφισμάτων· ἀπομνημονεύεται δ’ ὀλίγα παντάπασιν· οἷον τὸ τὴν Αἴγιναν ὡς λήμην τοῦ Πειραιῶς ἀφελεῖν κελεῦσαι, καὶ τὸ τὸν πόλεμον ἤδη φάναι καθορᾶν ἀπὸ Πελοποννήσου προσφερόμενον. καί ποτε τοῦ Σοφοκλέους, ὅτε συστρατηγῶν ἐξέπλευσε μετ’ αὐτοῦ, παῖδα καλὸν ἐπαινέσαντος, οὐ μόνον, ἔφη, τὰς χεῖρας, ὦ Σοφόκλεις, δεῖ καθαρὰς ἔχειν τὸν στρατηγόν, ἀλλὰ καὶ τὰς ὄψεις. ὁ δὲ Στησίμβροτός φησιν ὅτι τοὺς ἐν Σάμῳ τεθνηκότας ἐγκωμιάζων ἐπὶ τοῦ βήματος ἀθανάτους ἔλεγε γεγονέναι καθάπερ τοὺς θεούς· οὐ γὰρ ἐκείνους αὐτοὺς ὁρῶμεν, ἀλλὰ ταῖς τιμαῖς ἃς ἔχουσι, καὶ τοῖς ἀγαθοῖς ἃ παρέχουσιν, ἀθανάτους εἶναι τεκμαιρόμεθα· ταῦτ’ οὖν ὑπάρχειν καὶ τοῖς ὑπὲρ τῆς πατρίδος ἀποθανοῦσιν.", "st": "Per. 8.5"}, {"sp": "N", "t": "ἐπεὶ δὲ Θουκυδίδης μὲν ἀριστοκρατικήν τινα τὴν τοῦ Περικλέους ὑπογράφει πολιτείαν, λόγῳ μὲν οὖσαν δημοκρατίαν, ἔργῳ δ’ ὑπὸ τοῦ πρώτου ἀνδρὸς ἀρχήν, ἄλλοι δὲ πολλοὶ πρῶτον ὑπ’ ἐκείνου φασὶ τὸν δῆμον ἐπὶ κληρουχίας καὶ θεωρικὰ καὶ μισθῶν διανομὰς προαχθῆναι, κακῶς ἐθισθέντα καὶ γενόμενον πολυτελῆ καὶ ἀκόλαστον ὑπὸ τῶν τότε πολιτευμάτων ἀντὶ σώφρονος καὶ αὐτουργοῦ, θεωρείσθω διὰ τῶν πραγμάτων αὐτῶν ἡ αἰτία τῆς μεταβολῆς.", "st": "Per. 9.1"}, {"sp": "N", "t": "ἐν ἀρχῇ μὲν γάρ, ὥσπερ εἴρηται, πρὸς τὴν Κίμωνος δόξαν ἀντιταττόμενος ὑπεποιεῖτο τὸν δῆμον· ἐλαττούμενος δὲ πλούτῳ καὶ χρήμασιν, ἀφ’ ὧν ἐκεῖνος ἀνελάμβανε τοὺς πένητας, δεῖπνόν τε καθ’ ἡμέραν τῷ δεομένῳ παρέχων Ἀθηναίων, καὶ τοὺς πρεσβυτέρους ἀμφιεννύων, τῶν τε χωρίων τοὺς φραγμοὺς ἀφαιρῶν ὅπως ὀπωρίζωσιν οἱ βουλόμενοι, τούτοις ὁ Περικλῆς καταδημαγωγούμενος τρέπεται πρὸς τὴν τῶν δημοσίων διανομήν, συμβουλεύσαντος αὐτῷ Δαμωνίδου τοῦ Ὄαθεν, ὡς Ἀριστοτέλης ἱστόρηκε. καὶ ταχὺ θεωρικοῖς καὶ δικαστικοῖς λήμμασιν ἄλλαις τε μισθοφοραῖς καὶ χορηγίαις συνδεκάσας τὸ πλῆθος, ἐχρῆτο κατὰ τῆς ἐξ Ἀρείου πάγου βουλῆς, ἧς αὐτὸς οὐ μετεῖχε διὰ τὸ μήτ’ ἄρχων μήτε θεσμοθέτης μήτε βασιλεὺς μήτε πολέμαρχος λαχεῖν. αὗται γὰρ αἱ ἀρχαὶ κληρωταί τε ἦσαν ἐκ παλαιοῦ, καὶ δι’ αὐτῶν οἱ δοκιμασθέντες ἀνέβαινον εἰς Ἄρειον πάγον. διὸ καὶ μᾶλλον ἰσχύσας ὁ Περικλῆς ἐν τῷ δήμῳ κατεστασίασε τὴν βουλήν, ὥστε τὴν μὲν ἀφαιρεθῆναι τὰς πλείστας κρίσεις δι’ Ἐφιάλτου, Κίμωνα δ’ ὡς φιλολάκωνα καὶ μισόδημον ἐξοστρακισθῆναι, πλούτῳ μὲν καὶ γένει μηδενὸς ἀπολειπόμενον, νίκας δὲ καλλίστας νενικηκότα τοὺς βαρβάρους καὶ χρημάτων πολλῶν καὶ λαφύρων ἐμπεπληκότα τὴν πόλιν, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται. τοσοῦτον ἦν τὸ κράτος ἐν τῷ δήμῳ τοῦ Περικλέους.", "st": "Per. 9.2"}, {"sp": "N", "t": "ὁ μὲν οὖν ἐξοστρακισμὸς ὡρισμένην εἶχε νόμῳ δεκαετίαν τοῖς φεύγουσιν· ἐν δὲ τῷ διὰ μέσου Λακεδαιμονίων στρατῷ μεγάλῳ ἐμβαλόντων εἰς τὴν Ταναγρικὴν καὶ τῶν Ἀθηναίων εὐθὺς ὁρμησάντων ἐπ’ αὐτούς, ὁ μὲν Κίμων ἐλθὼν ἐκ τῆς φυγῆς ἔθετο μετὰ τῶν φυλετῶν εἰς λόχον τὰ ὅπλα καὶ δι’ ἔργων ἀπολύεσθαι τὸν Λακωνισμὸν ἐβούλετο, συγκινδυνεύσας τοῖς πολίταις, οἱ δὲ φίλοι τοῦ Περικλέους συστάντες ἀπήλασαν αὐτὸν ὡς φυγάδα. διὸ καὶ δοκεῖ Περικλῆς ἐρρωμενέστατα τὴν μάχην ἐκείνην ἀγωνίσασθαι καὶ γενέσθαι πάντων ἐπιφανέστατος ἀφειδήσας τοῦ σώματος. ἔπεσον δὲ καὶ τοῦ Κίμωνος οἱ φίλοι πάντες ὁμαλῶς, οὓς Περικλῆς συνεπῃτιᾶτο τοῦ Λακωνισμοῦ· καὶ μετάνοια δεινὴ τοὺς Ἀθηναίους καὶ πόθος ἔσχε τοῦ Κίμωνος, ἡττημένους μὲν ἐπὶ τῶν ὅρων τῆς Ἀττικῆς, προσδοκῶντας δὲ βαρὺν εἰς ἔτους ὥραν πόλεμον. αἰσθόμενος οὖν ὁ Περικλῆς οὐκ ὤκνησε χαρίσασθαι τοῖς πολλοῖς, ἀλλὰ τὸ ψήφισμα γράψας αὐτὸς ἐκάλει τὸν ἄνδρα, κἀκεῖνος κατελθὼν εἰρήνην ἐποίησε ταῖς πόλεσιν. οἰκείως γὰρ εἶχον οἱ Λακεδαιμόνιοι πρὸς αὐτὸν ὥσπερ ἀπήχθοντο τῷ Περικλεῖ καὶ τοῖς ἄλλοις δημαγωγοῖς.", "st": "Per. 10.1"}, {"sp": "N", "t": "ἔνιοι δέ φασιν οὐ πρότερον γραφῆναι τῷ Κίμωνι τὴν κάθοδον ὑπὸ τοῦ Περικλέους ἢ συνθήκας αὐτοῖς ἀπορρήτους γενέσθαι δι’ Ἐλπινίκης, τῆς Κίμωνος ἀδελφῆς, ὥστε Κίμωνα μὲν ἐκπλεῦσαι λαβόντα ναῦς διακοσίας καὶ τῶν ἔξω στρατηγεῖν, καταστρεφόμενον τὴν βασιλέως χώραν, Περικλεῖ δὲ τὴν ἐν ἄστει δύναμιν ὑπάρχειν. ἐδόκει δὲ καὶ πρότερον ἡ Ἐλπινίκη τῷ Κίμωνι τὸν Περικλέα πρᾳότερον παρασχεῖν, ὅτε τὴν θανατικὴν δίκην ἔφευγεν. ἦν μὲν γὰρ εἷς τῶν κατηγόρων ὁ Περικλῆς ὑπὸ τοῦ δήμου προβεβλημένος, ἐλθούσης δὲ πρὸς αὐτὸν τῆς Ἐλπινίκης καὶ δεομένης μειδιάσας εἶπεν· ὦ Ἐλπινίκη, γραῦς εἶ, γραῦς εἶ, ὡς πράγματα τηλικαῦτα πράσσειν. οὐ μὴν ἀλλὰ καὶ πρὸς τὸν λόγον ἅπαξ ἀνέστη, τὴν προβολὴν ἀφοσιούμενος, καὶ τῶν κατηγόρων ἐλάχιστα τὸν Κίμωνα λυπήσας ἀπεχώρησε.", "st": "Per. 10.4"}, {"sp": "N", "t": "πῶς ἂν οὖν τις Ἰδομενεῖ πιστεύσειε κατηγοροῦντι τοῦ Περικλέους ὡς τὸν δημαγωγὸν Ἐφιάλτην φίλον γενόμενον καὶ κοινωνὸν ὄντα τῆς ἐν τῇ πολιτείᾳ προαιρέσεως δολοφονήσαντος διὰ ζηλοτυπίαν καὶ φθόνον τῆς δόξης; ταῦτα γὰρ οὐκ οἶδ’ ὅθεν συναγαγὼν ὥσπερ χολὴν τἀνδρὶ προσβέβληκε, πάντῃ μὲν ἴσως οὐκ ἀνεπιλήπτῳ, φρόνημα δ’ εὐγενὲς ἔχοντι καὶ ψυχὴν φιλότιμον, οἷς οὐδὲν ἐμφύεται πάθος ὠμὸν οὕτω καὶ θηριῶδες. Ἐφιάλτην μὲν οὖν φοβερὸν ὄντα τοῖς ὀλιγαρχικοῖς καὶ περὶ τὰς εὐθύνας καὶ διώξεις τῶν τὸν δῆμον ἀδικούντων ἀπαραίτητον ἐπιβουλεύσαντες οἱ ἐχθροὶ δι’ Ἀριστοδίκου τοῦ Ταναγρικοῦ κρυφαίως ἀνεῖλον, ὡς Ἀριστοτέλης εἴρηκεν. ἐτελεύτησε δὲ Κίμων ἐν Κύπρῳ στρατηγῶν.", "st": "Per. 10.6"}, {"sp": "N", "t": "οἱ δ’ ἀριστοκρατικοὶ μέγιστον μὲν ἤδη τὸν Περικλέα καὶ πρόσθεν ὁρῶντες γεγονότα τῶν πολιτῶν, βουλόμενοι δ’ ὅμως εἶναι τινα τὸν πρὸς αὐτὸν ἀντιτασσόμενον ἐν τῇ πόλει καὶ τὴν δύναμιν ἀμβλύνοντα, ὥστε μὴ κομιδῇ μοναρχίαν εἶναι, Θουκυδίδην τὸν Ἀλωπεκῆθεν, ἄνδρα σώφρονα καὶ κηδεστὴν Κίμωνος, ἀντέστησαν ἐναντιωσόμενον, ὃς ἧττον μὲν ὢν πολεμικὸς τοῦ Κίμωνος, ἀγοραῖος δὲ καὶ πολιτικὸς μᾶλλον, οἰκουρῶν ἐν ἄστει καὶ περὶ τὸ βῆμα τῷ Περικλεῖ συμπλεκόμενος, ταχὺ τὴν πολιτείαν εἰς ἀντίπαλον κατέστησεν.", "st": "Per. 11.1"}, {"sp": "N", "t": "οὐ γὰρ εἴασε τοὺς καλοὺς κἀγαθοὺς καλουμένους ἄνδρας ἐνδιεσπάρθαι καὶ συμμεμῖχθαι πρὸς τὸν δῆμον, ὡς πρότερον, ὑπὸ πλήθους ἠμαυρωμένους τὸ ἀξίωμα, χωρὶς δὲ διακρίνας καὶ συναγαγὼν εἰς ταὐτὸ τὴν πάντων δύναμιν ἐμβριθῆ γενομένην ὥσπερ ἐπὶ ζυγοῦ ῥοπὴν ἐποίησεν. ἦν μὲν γὰρ ἐξ ἀρχῆς διπλόη τις ὕπουλος, ὥσπερ ἐν σιδήρῳ, διαφορὰν ὑποσημαίνουσα δημοτικῆς καὶ ἀριστοκρατικῆς προαιρέσεως, ἡ δ’ ἐκείνων ἅμιλλα καὶ φιλοτιμία τῶν ἀνδρῶν βαθυτάτην τομὴν τεμοῦσα τῆς πόλεως τὸ μὲν δῆμον, τὸ δ’ ὀλίγους ἐποίησε καλεῖσθαι. διὸ καὶ τότε μάλιστα τῷ δήμῳ τὰς ἡνίας ἀνεὶς ὁ Περικλῆς ἐπολιτεύετο πρὸς χάριν, ἀεὶ μέν τινα θέαν πανηγυρικὴν ἢ ἑστίασιν ἢ πομπὴν εἶναι μηχανώμενος ἐν ἄστει καὶ διαπαιδαγωγῶν οὐκ ἀμούσοις ἡδοναῖς τὴν πόλιν, ἑξήκοντα δὲ τριήρεις καθ’ ἕκαστον ἐνιαυτὸν ἐκπέμπων, ἐν αἷς πολλοὶ τῶν πολιτῶν ἔπλεον ὀκτὼ μῆνας ἔμμισθοι, μελετῶντες ἅμα καὶ μανθάνοντες τὴν ναυτικὴν ἐμπειρίαν. πρὸς δὲ τούτοις χιλίους μὲν ἔστειλεν εἰς Χερρόνησον κληρούχους, εἰς δὲ Νάξον πεντακοσίους, εἰς δὲ Ἄνδρον τοὺς ἡμίσεις τούτων, εἰς δὲ Θρᾴκην χιλίους Βισάλταις συνοικήσοντας, ἄλλους δ’ εἰς Ἰταλίαν οἰκιζομένης Συβάρεως, ἣν Θουρίους προσηγόρευσαν. καὶ ταῦτ’ ἔπραττεν ἀποκουφίζων μὲν ἀργοῦ καὶ διὰ σχολὴν πολυπράγμονος ὄχλου τὴν πόλιν, ἐπανορθούμενος δὲ τὰς ἀπορίας τοῦ δήμου, φόβον δὲ καὶ φρουρὰν τοῦ μὴ νεωτερίζειν τι παρακατοικίζων τοῖς συμμάχοις.", "st": "Per. 11.3"}, {"sp": "N", "t": "ὃ δὲ πλείστην μὲν ἡδονὴν ταῖς Ἀθήναις καὶ κόσμον ἤνεγκε, μεγίστην δὲ τοῖς ἄλλοις ἔκπληξιν ἀνθρώποις, μόνον δὲ τῇ Ἑλλάδι μαρτυρεῖ μὴ ψεύδεσθαι τὴν λεγομένην δύναμιν αὐτῆς ἐκείνην καὶ τὸν παλαιὸν ὄλβον, ἡ τῶν ἀναθημάτων κατασκευή, τοῦτο μάλιστα τῶν πολιτευμάτων τοῦ Περικλέους ἐβάσκαινον οἱ ἐχθροὶ καὶ διέβαλλον ἐν ταῖς ἐκκλησίαις, βοῶντες ὡς ὁ μὲν δῆμος ἀδοξεῖ καὶ κακῶς ἀκούει τὰ κοινὰ τῶν Ἑλλήνων χρήματα πρὸς αὑτὸν ἐκ Δήλου μεταγαγών, ἣ δ’ ἔνεστιν αὐτῷ πρὸς τοὺς ἐγκαλοῦντας εὐπρεπεστάτη τῶν προφάσεων, δείσαντα τοὺς βαρβάρους ἐκεῖθεν ἀνελέσθαι καὶ φυλάττειν ἐν ὀχυρῷ τὰ κοινά, ταύτην ἀνῄρηκε Περικλῆς· καὶ δοκεῖ δεινὴν ὕβριν ἡ Ἑλλὰς ὑβρίζεσθαι καὶ τυραννεῖσθαι περιφανῶς, ὁρῶσα τοῖς εἰσφερομένοις ὑπ’ αὐτῆς ἀναγκαίως πρὸς τὸν πόλεμον ἡμᾶς τὴν πόλιν καταχρυσοῦντας καὶ καλλωπίζοντας ὥσπερ ἀλαζόνα γυναῖκα, περιαπτομένην λίθους πολυτελεῖς καὶ ἀγάλματα καὶ ναοὺς χιλιοταλάντους.", "st": "Per. 12.1"}, {"sp": "N", "t": "ἐδίδασκεν οὖν ὁ Περικλῆς τὸν δῆμον ὅτι χρημάτων μὲν οὐκ ὀφείλουσι τοῖς συμμάχοις λόγον προπολεμοῦντες αὐτῶν καὶ τοὺς βαρβάρους ἀνείργοντες, οὐχ ἵππον, οὐ ναῦν, οὐχ ὁπλίτην, ἀλλὰ χρήματα μόνον τελούντων, ἃ τῶν διδόντων οὐκ ἔστιν, ἀλλὰ τῶν λαμβανόντων, ἂν παρέχωσιν ἀνθ’ οὗ λαμβάνουσι· δεῖ δὲ τῆς πόλεως κατεσκευασμένης ἱκανῶς τοῖς ἀναγκαίοις πρὸς τὸν πόλεμον, εἰς ταῦτα τὴν εὐπορίαν τρέπειν αὐτῆς ἀφ’ ὧν δόξα μὲν γενομένων ἀΐδιος, εὐπορία δὲ γινομένων ἑτοίμη παρέσται, παντοδαπῆς ἐργασίας φανείσης καὶ ποικίλων χρειῶν, αἳ πᾶσαν μὲν τέχνην ἐγείρουσαι, πᾶσαν δὲ χεῖρα κινοῦσαι, σχεδὸν ὅλην ποιοῦσιν ἔμμισθον τὴν πόλιν, ἐξ αὑτῆς ἅμα κοσμουμένην καὶ τρεφομένην.", "st": "Per. 12.3"}, {"sp": "N", "t": "τοῖς μὲν γὰρ ἡλικίαν ἔχουσι καὶ ῥώμην αἱ στρατεῖαι τὰς ἀπὸ τῶν κοινῶν εὐπορίας παρεῖχον, τὸν δ’ ἀσύντακτον καὶ βάναυσον ὄχλον οὔτ’ ἄμοιρον εἶναι λημμάτων βουλόμενος οὔτε λαμβάνειν ἀργὸν καὶ σχολάζοντα, μεγάλας κατασκευασμάτων ἐπιβολὰς καὶ πολυτέχνους ὑποθέσεις ἔργων διατριβὴν ἐχόντων ἐνέβαλε φέρων εἰς τὸν δῆμον, ἵνα μηδὲν ἧττον τῶν πλεόντων καὶ φρουρούντων καὶ στρατευομένων τὸ οἰκουροῦν ἔχῃ πρόφασιν ἀπὸ τῶν δημοσίων ὠφελεῖσθαι καὶ μεταλαμβάνειν. ὅπου γὰρ ὕλη μὲν ἦν λίθος, χαλκός, ἐλέφας, χρυσός, ἔβενος, κυπάρισσος, αἱ δὲ ταύτην ἐκπονοῦσαι καὶ κατεργαζόμεναι τέχναι, τέκτονες, πλάσται, χαλκοτύποι, λιθουργοί, βαφεῖς, χρυσοῦ μαλακτῆρες καὶ ἐλέφαντος, ζωγράφοι, ποικιλταί, τορευταί, πομποὶ δὲ τούτων καὶ κομιστῆρες, ἔμποροι καὶ ναῦται καὶ κυβερνῆται κατὰ θάλατταν, οἱ δὲ κατὰ γῆν ἁμαξοπηγοὶ καὶ ζευγοτρόφοι καὶ ἡνίοχοι καὶ καλωστρόφοι καὶ λινουργοὶ καὶ σκυτοτόμοι καὶ ὁδοποιοὶ καὶ μεταλλεῖς, ἑκάστη δὲ τέχνη, καθάπερ στρατηγὸς ἴδιον στράτευμα, τὸν θητικὸν ὄχλον καὶ ἰδιώτην συντεταγμένον εἶχεν, ὄργανον καὶ σῶμα τῆς ὑπηρεσίας γινόμενον, εἰς πᾶσαν, ὡς ἔπος εἰπεῖν, ἡλικίαν καὶ φύσιν αἱ χρεῖαι διένεμον καὶ διέσπειρον τὴν εὐπορίαν.", "st": "Per. 12.5"}, {"sp": "N", "t": "ἀναβαινόντων δὲ τῶν ἔργων ὑπερηφάνων μὲν μεγέθει, μορφῇ δ’ ἀμιμήτων καὶ χάριτι, τῶν δημιουργῶν ἁμιλλωμένων ὑπερβάλλεσθαι τὴν δημιουργίαν τῇ καλλιτεχνίᾳ, μάλιστα θαυμάσιον ἦν τὸ τάχος. ὧν γὰρ ἕκαστον ᾤοντο πολλαῖς διαδοχαῖς καὶ ἡλικίαις μόλις ἐπὶ τέλος ἀφίξεσθαι, ταῦτα πάντα μιᾶς ἀκμῇ πολιτείας ἐλάμβανε τὴν συντέλειαν. καίτοι ποτέ φασιν Ἀγαθάρχου τοῦ ζωγράφου μέγα φρονοῦντος ἐπὶ τῷ ταχὺ καὶ ῥᾳδίως τὰ ζῷα ποιεῖν ἀκούσαντα τὸν Ζεῦξιν εἰπεῖν· ἐγὼ δ’ ἐν πολλῷ χρόνῳ. ἡ γὰρ ἐν τῷ ποιεῖν εὐχέρεια καὶ ταχύτης οὐκ ἐντίθησι βάρος ἔργῳ μόνιμον οὐδὲ κάλλους ἀκρίβειαν· ὁ δ’ εἰς τὴν γένεσιν τῷ πόνῳ προδανεισθεὶς χρόνος ἐν τῇ σωτηρίᾳ τοῦ γενομένου τὴν ἰσχὺν ἀποδίδωσιν. ὅθεν καὶ μᾶλλον θαυμάζεται τὰ Περικλέους ἔργα πρὸς πολὺν χρόνον ἐν ὀλίγῳ γενόμενα. κάλλει μὲν γὰρ ἕκαστον εὐθὺς ἦν τότε ἀρχαῖον, ἀκμῇ δὲ μέχρι νῦν πρόσφατόν ἐστι καὶ νεουργόν· οὕτως ἐπανθεῖ καινότης ἀεί τις ἄθικτον ὑπὸ τοῦ χρόνου διατηροῦσα τὴν ὄψιν, ὥσπερ ἀειθαλὲς πνεῦμα καὶ ψυχὴν ἀγήρω καταμεμιγμένην τῶν ἔργων ἐχόντων.", "st": "Per. 13.1"}, {"sp": "N", "t": "πάντα δὲ διεῖπε καὶ πάντων ἐπίσκοπος ἦν αὐτῷ Φειδίας, καίτοι μεγάλους ἀρχιτέκτονας ἐχόντων καὶ τεχνίτας τῶν ἔργων. τὸν μὲν γὰρ ἑκατόμπεδον Παρθενῶνα Καλλικράτης εἰργάζετο καὶ Ἰκτῖνος, τὸ δ’ ἐν Ἐλευσῖνι τελεστήριον ἤρξατο μὲν Κόροιβος οἰκοδομεῖν, καὶ τοὺς ἐπ’ ἐδάφους κίονας ἔθηκεν οὗτος καὶ τοῖς ἐπιστυλίοις ἐπέζευξεν· ἀποθανόντος δὲ τούτου Μεταγένης ὁ Ξυπέτιος τὸ διάζωμα καὶ τοὺς ἄνω κίονας ἐπέστησε· τὸ δ’ ὀπαῖον ἐπὶ τοῦ ἀνακτόρου Ξενοκλῆς ὁ Χολαργεὺς ἐκορύφωσε· τὸ δὲ μακρὸν τεῖχος, περὶ οὗ Σωκράτης ἀκοῦσαί φησιν αὐτὸς εἰσηγουμένου γνώμην Περικλέους, ἠργολάβησε Καλλικράτης. κωμῳδεῖ δὲ τὸ ἔργον Κρατῖνος ὡς βραδέως περαινόμενον·", "st": "Per. 13.4"}, {"sp": "N", "t": "πάλαι γὰρ αὐτό, φησί,<br>λόγοισι προάγει Περικλέης, ἔργοισι δ’ οὐδὲ κινεῖ.", "st": "Per. 13.4b"}, {"sp": "N", "t": "τὸ δ’ Ὠιδεῖον, τῇ μὲν ἐντὸς διαθέσει πολύεδρον καὶ πολύστυλον, τῇ δ’ ἐρέψει περικλινὲς καὶ κάταντες ἐκ μιᾶς κορυφῆς πεποιημένον, εἰκόνα λέγουσι γενέσθαι καὶ μίμημα τῆς βασιλέως σκηνῆς, ἐπιστατοῦντος καὶ τούτῳ Περικλέους. διὸ καὶ πάλιν Κρατῖνος ἐν Θρᾴτταις παίζει πρὸς αὐτόν·", "st": "Per. 13.6"}, {"sp": "N", "t": "ὁ σχινοκέφαλος Ζεὺς ὅδε<br>προσέρχεται τᾠδεῖον ἐπὶ τοῦ κρανίου<br>ἔχων, ἐπειδὴ τοὔστρακον παροίχεται.", "st": "Per. 13.6b"}, {"sp": "N", "t": "φιλοτιμούμενος δ’ ὁ Περικλῆς τότε πρῶτον ἐψηφίσατο μουσικῆς ἀγῶνα τοῖς Παναθηναίοις ἄγεσθαι, καὶ διέταξεν αὐτὸς ἀθλοθέτης αἱρεθεὶς καθότι χρὴ τοὺς ἀγωνιζομένους αὐλεῖν ἢ ᾄδειν ἢ κιθαρίζειν. ἐθεῶντο δὲ καὶ τότε καὶ τὸν ἄλλον χρόνον ἐν Ὠιδείῳ τοὺς μουσικοὺς ἀγῶνας.", "st": "Per. 13.6c"}, {"sp": "N", "t": "τὰ δὲ Προπύλαια τῆς ἀκροπόλεως ἐξειργάσθη μὲν ἐν πενταετίᾳ Μνησικλέους ἀρχιτεκτονοῦντος· τύχη δὲ θαυμαστὴ συμβᾶσα περὶ τὴν οἰκοδομίαν ἐμήνυσε τὴν θεὸν οὐκ ἀποστατοῦσαν, ἀλλὰ συνεφαπτομένην τοῦ ἔργου καὶ συνεπιτελοῦσαν. ὁ γὰρ ἐνεργότατος καὶ προθυμότατος τῶν τεχνιτῶν ἀποσφαλεὶς ἐξ ὕψους ἔπεσε καὶ διέκειτο μοχθηρῶς, ὑπὸ τῶν ἰατρῶν ἀπεγνωσμένος. ἀθυμοῦντος δὲ τοῦ Περικλέους ἡ θεὸς ὄναρ φανεῖσα συνέταξε θεραπείαν, ᾗ χρώμενος ὁ Περικλῆς ταχὺ καὶ ῥᾳδίως ἰάσατο τὸν ἄνθρωπον. ἐπὶ τούτῳ δὲ καὶ τὸ χαλκοῦν ἄγαλμα τῆς Ὑγιείας Ἀθηνᾶς ἀνέστησεν ἐν ἀκροπόλει παρὰ τὸν βωμὸν ὃς καὶ πρότερον ἦν, ὡς λέγουσιν.", "st": "Per. 13.7"}, {"sp": "N", "t": "ὁ δὲ Φειδίας εἰργάζετο μὲν τῆς θεοῦ τὸ χρυσοῦν ἕδος, καὶ τούτου δημιουργὸς ἐν τῇ στήλῃ ἀναγέγραπται, πάντα δ’ ἦν σχεδὸν ἐπ’ αὐτῷ, καὶ πᾶσιν, ὡς εἰρήκαμεν, ἐπεστάτει τοῖς τεχνίταις διὰ φιλίαν Περικλέους. καὶ τοῦτο τῷ μὲν φθόνον, τῷ δὲ βλασφημίαν ἤνεγκεν, ὡς ἐλευθέρας τῷ Περικλεῖ γυναῖκας εἰς τὰ ἔργα φοιτώσας ὑποδεχομένου τοῦ Φειδίου. δεξάμενοι δὲ τὸν λόγον οἱ κωμικοὶ πολλὴν ἀσέλγειαν αὐτοῦ κατεσκέδασαν, εἴς τε τὴν Μενίππου γυναῖκα διαβάλλοντες, ἀνδρὸς φίλου καὶ ὑποστρατηγοῦντος, εἴς τε τὰς Πυριλάμπους ὀρνιθοτροφίας, ὃς ἑταῖρος ὢν Περικλέους αἰτίαν εἶχε ταῶνας ὑφιέναι ταῖς γυναιξὶν αἷς ὁ Περικλῆς ἐπλησίαζε.", "st": "Per. 13.9"}, {"sp": "N", "t": "καὶ τί ἄν τις ἀνθρώπους σατυρικοὺς τοῖς βίοις καὶ τὰς κατὰ τῶν κρειττόνων βλασφημίας ὥσπερ δαίμονι κακῷ τῷ φθόνῳ τῶν πολλῶν ἀποθύοντας ἑκάστοτε θαυμάσειεν, ὅπου καὶ Στησίμβροτος ὁ Θάσιος δεινὸν ἀσέβημα καὶ μυθῶδες ἐξενεγκεῖν ἐτόλμησεν εἰς τὴν γυναῖκα τοῦ υἱοῦ κατὰ τοῦ Περικλέους; οὕτως ἔοικε πάντη χαλεπὸν εἶναι καὶ δυσθήρατον ἱστορίᾳ τἀληθές, ὅταν οἱ μὲν ὕστερον γεγονότες τὸν χρόνον ἔχωσιν ἐπιπροσθοῦντα τῇ γνώσει τῶν πραγμάτων, ἡ δὲ τῶν πράξεων καὶ τῶν βίων ἡλικιῶτις ἱστορία τὰ μὲν φθόνοις καὶ δυσμενείαις, τὰ δὲ χαριζομένη καὶ κολακεύουσα λυμαίνηται καὶ διαστρέφῃ τὴν ἀλήθειαν.", "st": "Per. 13.11"}, {"sp": "N", "t": "τῶν δὲ περὶ τὸν Θουκυδίδην ῥητόρων καταβοώντων τοῦ Περικλέους ὡς σπαθῶντος τὰ χρήματα καὶ τὰς προσόδους ἀπολλύντος, ἠρώτησεν ἐν ἐκκλησίᾳ τὸν δῆμον εἰ πολλὰ δοκεῖ δεδαπανῆσθαι· φησάντων δὲ πάμπολλα· μὴ τοίνυν, εἶπεν, ὑμῖν, ἀλλ’ ἐμοὶ δεδαπανήσθω, καὶ τῶν ἀναθημάτων ἰδίαν ἐμαυτοῦ ποιήσομαι τὴν ἐπιγραφήν. εἰπόντος οὖν ταῦτα τοῦ Περικλέους, εἴτε τὴν μεγαλοφροσύνην αὐτοῦ θαυμάσαντες εἴτε πρὸς τὴν δόξαν ἀντιφιλοτιμούμενοι τῶν ἔργων, ἀνέκραγον κελεύοντες ἐκ τῶν δημοσίων ἀναλίσκειν καὶ χορηγεῖν μηδενὸς φειδόμενον. τέλος δὲ πρὸς τὸν Θουκυδίδην εἰς ἀγῶνα περὶ τοῦ ὀστράκου καταστὰς καὶ διακινδυνεύσας ἐκεῖνον μὲν ἐξέβαλε, κατέλυσε δὲ τὴν ἀντιτεταγμένην ἑταιρείαν.", "st": "Per. 14.1"}, {"sp": "N", "t": "ὡς οὖν παντάπασι λυθείσης τῆς διαφορᾶς καὶ τῆς πόλεως οἷον ὁμαλῆς καὶ μιᾶς γενομένης κομιδῇ, περιήνεγκεν εἰς ἑαυτὸν τὰς Ἀθήνας καὶ τὰ τῶν Ἀθηναίων ἐξηρτημένα πράγματα, φόρους καὶ στρατεύματα καὶ τριήρεις καὶ νήσους καὶ θάλασσαν, καὶ πολλὴν μὲν δι’ Ἑλλήνων, πολλὴν δὲ καὶ διὰ βαρβάρων ἥκουσαν ἰσχύν, καὶ ἡγεμονίαν ὑπηκόοις ἔθνεσι καὶ φιλίαις βασιλέων καὶ συμμαχίαις πεφραγμένην δυναστῶν, οὐκέθ’ ὁ αὐτὸς ἦν οὐδ’ ὁμοίως χειροήθης τῷ δήμῳ καὶ ῥᾴδιος ὑπείκειν καὶ συνενδιδόναι ταῖς ἐπιθυμίαις ὥσπερ πνοαῖς τῶν πολλῶν, ἀλλ’ ἐκ τῆς ἀνειμένης ἐκείνης καὶ ὑποθρυπτομένης ἔνια δημαγωγίας, ὥσπερ ἀνθηρᾶς καὶ μαλακῆς ἁρμονίας, ἀριστοκρατικὴν καὶ βασιλικὴν ἐντεινάμενος πολιτείαν, καὶ χρώμενος αὐτῇ πρὸς τὸ βέλτιστον ὀρθῇ καὶ ἀνεγκλίτῳ, τὰ μὲν πολλὰ βουλόμενον ἦγε πείθων καὶ διδάσκων τὸν δῆμον, ἦν δ’ ὅτε καὶ μάλα δυσχεραίνοντα κατατείνων καὶ προσβιβάζων ἐχειροῦτο τῷ συμφέροντι, μιμούμενος ἀτεχνῶς ἰατρὸν ποικίλῳ νοσήματι καὶ μακρῷ κατὰ καιρὸν μὲν ἡδονὰς ἀβλαβεῖς, κατὰ καιρὸν δὲ δηγμοὺς καὶ φάρμακα προσφέροντα σωτήρια. παντοδαπῶν γάρ, ὡς εἰκός, παθῶν ἐν ὄχλῳ τοσαύτην τὸ μέγεθος ἀρχὴν ἔχοντι φυομένων, μόνος ἐμμελῶς ἕκαστα διαχειρίσασθαι πεφυκώς, μάλιστα δ’ ἐλπίσι καὶ φόβοις ὥσπερ οἴαξι προσστέλλων τὸ θρασυνόμενον αὐτῶν καὶ τὸ δύσθυμον ἀνιεὶς καὶ παραμυθούμενος, ἔδειξε τὴν ῥητορικὴν κατὰ Πλάτωνα ψυχαγωγίαν οὖσαν καὶ μέγιστον ἔργον αὐτῆς τὴν περὶ τὰ ἤθη καὶ πάθη μέθοδον, ὥσπερ τινὰς τόνους καὶ φθόγγους ψυχῆς μάλ’ ἐμμελοῦς ἁφῆς καὶ κρούσεως δεομένους. αἰτία δ’ οὐχ ἡ τοῦ λόγου ψιλῶς δύναμις, ἀλλ’, ὡς Θουκυδίδης φησίν, ἡ περὶ τὸν βίον δόξα καὶ πίστις τοῦ ἀνδρός, ἀδωροτάτου περιφανῶς γενομένου καὶ χρημάτων κρείττονος· ὃς καὶ τὴν πόλιν ἐκ μεγάλης μεγίστην καὶ πλουσιωτάτην ποιήσας, καὶ γενόμενος δυνάμει πολλῶν βασιλέων καὶ τυράννων ὑπέρτερος, ὧν ἔνιοι καὶ ἐπίτροπον τοῖς υἱέσι διέθεντο ἐκεῖνον, μιᾷ δραχμῇ μείζονα τὴν οὐσίαν οὐκ ἐποίησεν ἧς ὁ πατὴρ αὐτῷ κατέλιπε.", "st": "Per. 15.1"}, {"sp": "N", "t": "καίτοι τὴν δύναμιν αὐτοῦ σαφῶς μὲν ὁ Θουκυδίδης διηγεῖται, κακοήθως δὲ παρεμφαίνουσιν οἱ κωμικοί, Πεισιστρατίδας μὲν νέους τοὺς περὶ αὐτὸν ἑταίρους καλοῦντες, αὐτὸν δ’ ἀπομόσαι μὴ τυραννήσειν κελεύοντες, ὡς ἀσυμμέτρου πρὸς δημοκρατίαν καὶ βαρυτέρας περὶ αὐτὸν οὔσης ὑπεροχῆς· ὁ δὲ Τηλεκλείδης παραδεδωκέναι φησὶν αὐτῷ τοὺς Ἀθηναίους", "st": "Per. 16.1"}, {"sp": "N", "t": "πόλεών τε φόρους αὐτάς τε πόλεις, τὰς μὲν δεῖν, τὰς δ’ ἀναλύειν,", "st": "Per. 16.1b"}, {"sp": "N", "t": "λάϊνα τείχη, τὰ μὲν οἰκοδομεῖν, τὰ δ’ ἔπειτα πάλιν καταβάλλειν,", "st": "Per. 16.1c"}, {"sp": "N", "t": "σπονδάς, δύναμιν, κράτος, εἰρήνην, πλοῦτόν τ’ εὐδαιμονίαν τε.", "st": "Per. 16.1d"}, {"sp": "N", "t": "καὶ ταῦτα καιρὸς οὐκ ἦν οὐδ’ ἀκμὴ καὶ χάρις ἀνθούσης ἐφ’ ὥρᾳ πολιτείας, ἀλλὰ τεσσαράκοντα μὲν ἔτη πρωτεύων ἐν Ἐφιάλταις καὶ Λεωκράταις καὶ Μυρωνίδαις καὶ Κίμωσι καὶ Τολμίδαις καὶ Θουκυδίδαις, μετὰ δὲ τὴν Θουκυδίδου κατάλυσιν καὶ τὸν ὀστρακισμὸν οὐκ ἐλάττω τῶν πεντεκαίδεκα ἐτῶν διηνεκῆ καὶ μίαν οὖσαν ἐν ταῖς ἐνιαυσίοις στρατηγίαις ἀρχὴν καὶ δυναστείαν κτησάμενος, ἐφύλαξεν ἑαυτὸν ἀνάλωτον ὑπὸ χρημάτων, καίπερ οὐ παντάπασιν ἀργῶς ἔχων πρὸς χρηματισμόν, ἀλλὰ τὸν πατρῷον καὶ δίκαιον πλοῦτον, ὡς μήτ’ ἀμελούμενος ἐκφύγοι μήτε πολλὰ πράγματα καὶ διατριβὰς ἀσχολουμένῳ παρέχοι, συνέταξεν εἰς οἰκονομίαν ἣν ᾤετο ῥᾴστην καὶ ἀκριβεστάτην εἶναι. τοὺς γὰρ ἐπετείους καρποὺς ἅπαντας ἀθρόους ἐπίπρασκεν, εἶτα τῶν ἀναγκαίων ἕκαστον ἐξ ἀγορᾶς ὠνούμενος διῴκει τὸν βίον καὶ τὰ περὶ τὴν δίαιταν. ὅθεν οὐχ ἡδὺς ἦν ἐνηλίκοις παισὶν οὐδὲ γυναιξὶ δαψιλὴς χορηγός, ἀλλ’ ἐμέμφοντο τὴν ἐφήμερον ταύτην καὶ συνηγμένην εἰς τὸ ἀκριβέστατον δαπάνην, οὐδενός, οἷον ἐν οἰκίᾳ μεγάλῃ καὶ πράγμασιν ἀφθόνοις, περιρρέοντος, ἀλλὰ παντὸς μὲν ἀναλώματος, παντὸς δὲ λήμματος δι’ ἀριθμοῦ καὶ μέτρου βαδίζοντος. ὁ δὲ πᾶσαν αὐτοῦ τὴν τοιαύτην συνέχων ἀκρίβειαν εἷς ἦν οἰκέτης, Εὐάγγελος, ὡς ἕτερος οὐδεὶς εὖ πεφυκὼς ἢ κατεσκευασμένος ὑπὸ τοῦ Περικλέους πρὸς οἰκονομίαν.", "st": "Per. 16.3"}, {"sp": "N", "t": "ἀπᾴδοντα μὲν οὖν ταῦτα τῆς Ἀναξαγόρου σοφίας, εἴγε καὶ τὴν οἰκίαν ἐκεῖνος ἐξέλιπε καὶ τὴν χώραν ἀφῆκεν ἀργὴν καὶ μηλόβοτον ὑπ’ ἐνθουσιασμοῦ καὶ μεγαλοφροσύνης, οὐ ταὐτὸν δ’ ἐστίν, οἶμαι, θεωρητικοῦ φιλοσόφου καὶ πολιτικοῦ βίος, ἀλλ’ ὁ μὲν ἀνόργανον καὶ ἀπροσδεῆ τῆς ἐκτὸς ὕλης ἐπὶ τοῖς καλοῖς κινεῖ τὴν διάνοιαν, τῷ δ’ εἰς ἀνθρωπείας χρείας ἀναμιγνύντι τὴν ἀρετὴν ἔστιν οὗ γένοιτ’ ἂν οὐ τῶν ἀναγκαίων μόνον, ἀλλὰ καὶ τῶν καλῶν ὁ πλοῦτος, ὥσπερ ἦν καὶ Περικλεῖ βοηθοῦντι πολλοῖς τῶν πενήτων. καὶ μέντοι γε τὸν Ἀναξαγόραν αὐτὸν λέγουσιν ἀσχολουμένου Περικλέους ἀμελούμενον κεῖσθαι συγκεκαλυμμένον ἤδη γηραιὸν ἀποκαρτεροῦντα· προσπεσόντος δὲ τῷ Περικλεῖ τοῦ πράγματος ἐκπλαγέντα θεῖν εὐθὺς ἐπὶ τὸν ἄνδρα καὶ δεῖσθαι πᾶσαν δέησιν, ὀλοφυρόμενον οὐκ ἐκεῖνον, ἀλλ’ ἑαυτόν, εἰ τοιοῦτον ἀπολεῖ τῆς πολιτείας σύμβουλον. ἐκκαλυψάμενον οὖν τὸν Ἀναξαγόραν εἰπεῖν πρὸς αὐτόν· ὦ Περίκλεις, καὶ οἱ τοῦ λύχνου χρείαν ἔχοντες ἔλαιον ἐπιχέουσιν.", "st": "Per. 16.6"}, {"sp": "N", "t": "ἀρχομένων δὲ Λακεδαιμονίων ἄχθεσθαι τῇ αὐξήσει τῶν Ἀθηναίων, ἐπαίρων ὁ Περικλῆς τὸν δῆμον ἔτι μᾶλλον μέγα φρονεῖν καὶ μεγάλων αὑτὸν ἀξιοῦν πραγμάτων, γράφει ψήφισμα, πάντας Ἕλληνας τοὺς ὁπήποτε κατοικοῦντας Εὐρώπης ἢ τῆς Ἀσίας παρακαλεῖν, καὶ μικρὰν πόλιν καὶ μεγάλην, εἰς σύλλογον πέμπειν Ἀθήναζε τοὺς βουλευσομένους περὶ τῶν Ἑλληνικῶν ἱερῶν, ἃ κατέπρησαν οἱ βάρβαροι, καὶ τῶν θυσιῶν ἃς ὀφείλουσιν ὑπὲρ τῆς Ἑλλάδος εὐξάμενοι τοῖς θεοῖς ὅτε πρὸς τοὺς βαρβάρους ἐμάχοντο, καὶ τῆς θαλάττης, ὅπως πλέωσι πάντες ἀδεῶς καὶ τὴν εἰρήνην ἄγωσιν. ἐπὶ ταῦτα δ’ ἄνδρες εἴκοσι τῶν ὑπὲρ πεντήκοντα ἔτη γεγονότων ἐπέμφθησαν, ὧν πέντε μὲν Ἴωνας καὶ Δωριεὶς τοὺς ἐν Ἀσίᾳ καὶ νησιώτας ἄχρι Λέσβου καὶ Ῥόδου παρεκάλουν, πέντε δὲ τοὺς ἐν Ἑλλησπόντῳ καὶ Θρᾴκῃ μέχρι Βυζαντίου τόπους ἐπῄεσαν, καὶ πέντε ἐπὶ τούτοις εἰς Βοιωτίαν καὶ Φωκίδα καὶ Πελοπόννησον, ἐκ δὲ ταύτης διὰ Λοκρῶν ἐπὶ τὴν πρόσοικον ἤπειρον ἕως Ἀκαρνανίας καὶ Ἀμβρακίας ἀπεστάλησαν· οἱ δὲ λοιποὶ δι’ Εὐβοίας ἐπ’ Οἰταίους καὶ τὸν Μαλιέα κόλπον καὶ Φθιώτας Ἀχαιοὺς καὶ Θεσσαλοὺς ἐπορεύοντο, συμπείθοντες ἰέναι καὶ μετέχειν τῶν βουλευμάτων ἐπ’ εἰρήνῃ καὶ κοινοπραγίᾳ τῆς Ἑλλάδος. ἐπράχθη δὲ οὐδέν, οὐδὲ συνῆλθον αἱ πόλεις, Λακεδαιμονίων ὑπεναντιωθέντων, ὡς λέγεται, καὶ τὸ πρῶτον ἐν Πελοποννήσῳ τῆς πείρας ἐλεγχθείσης. τοῦτο μὲν οὖν παρεθέμην ἐνδεικνύμενος αὐτοῦ τὸ φρόνημα καὶ τὴν μεγαλοφροσύνην.", "st": "Per. 17.1"}, {"sp": "N", "t": "ἐν δὲ ταῖς στρατηγίαις εὐδοκίμει μάλιστα διὰ τὴν ἀσφάλειαν, οὔτε μάχης ἐχούσης πολλὴν ἀδηλότητα καὶ κίνδυνον ἑκουσίως ἁπτόμενος, οὔτε τοὺς ἐκ τοῦ παραβάλλεσθαι χρησαμένους τύχῃ λαμπρᾷ καὶ θαυμασθέντας ὡς μεγάλους ζηλῶν καὶ μιμούμενος στρατηγούς, ἀεί τε λέγων πρὸς τοὺς πολίτας ὡς ὅσον ἐπ’ αὐτῷ μενοῦσιν ἀθάνατοι πάντα τὸν χρόνον.", "st": "Per. 18.1"}, {"sp": "N", "t": "ὁρῶν δὲ Τολμίδην τὸν Τολμαίου διὰ τὰς πρότερον εὐτυχίας καὶ διὰ τὸ τιμᾶσθαι διαφερόντως ἐκ τῶν πολεμικῶν σὺν οὐδενὶ καιρῷ παρασκευαζόμενον εἰς Βοιωτίαν ἐμβαλεῖν, καὶ πεπεικότα τῶν ἐν ἡλικίᾳ τοὺς ἀρίστους καὶ φιλοτιμοτάτους ἐθελοντὶ στρατεύεσθαι, χιλίους γενομένους ἄνευ τῆς ἄλλης δυνάμεως, κατέχειν ἐπειρᾶτο καὶ παρακαλεῖν ἐν τῷ δήμῳ, τὸ μνημονευόμενον εἰπών, ὡς εἰ μὴ πείθοιτο Περικλεῖ, τόν γε σοφώτατον οὐχ ἁμαρτήσεται σύμβουλον ἀναμείνας χρόνον. τότε μὲν οὖν μετρίως εὐδοκίμησε τοῦτ’ εἰπών· ὀλίγαις δ’ ὕστερον ἡμέραις, ὡς ἀνηγγέλθη τεθνεὼς μὲν αὐτὸς Τολμίδης περὶ Κορώνειαν ἡττηθεὶς μάχῃ, τεθνεῶτες δὲ πολλοὶ κἀγαθοὶ τῶν πολιτῶν, μεγάλην τοῦτο τῷ Περικλεῖ μετ’ εὐνοίας δόξαν ἤνεγκεν, ὡς ἀνδρὶ φρονίμῳ καὶ φιλοπολίτῃ.", "st": "Per. 18.2"}, {"sp": "N", "t": "τῶν δὲ στρατηγιῶν ἠγαπήθη μὲν ἡ περὶ Χερρόνησον αὐτοῦ μάλιστα, σωτήριος γενομένη τοῖς αὐτόθι κατοικοῦσι τῶν Ἑλλήνων· οὐ γὰρ μόνον ἐποίκους Ἀθηναίων χιλίους κομίσας ἔρρωσεν εὐανδρίᾳ τὰς πόλεις, ἀλλὰ καὶ τὸν αὐχένα διαζώσας ἐρύμασι καὶ προβλήμασιν ἐκ θαλάττης εἰς θάλατταν ἀπετείχισε τὰς καταδρομὰς τῶν Θρᾳκῶν περικεχυμένων τῇ Χερρονήσῳ, καὶ πόλεμον ἐνδελεχῆ καὶ βαρὺν ἐξέκλεισεν, ᾧ συνείχετο πάντα τὸν χρόνον ἡ χώρα βαρβαρικαῖς ἀναμεμιγμένη γειτνιάσεσι καὶ γέμουσα λῃστηρίων ὁμόρων καὶ συνοίκων· ἐθαυμάσθη δὲ καὶ διεβοήθη πρὸς τοὺς ἐκτὸς ἀνθρώπους περιπλεύσας Πελοπόννησον, ἐκ Πηγῶν τῆς Μεγαρικῆς ἀναχθεὶς ἑκατὸν τριήρεσιν. οὐ γὰρ μόνον ἐπόρθησε τῆς παραλίας πολλήν, ὡς Τολμίδης πρότερον, ἀλλὰ καὶ πόρρω θαλάττης προελθὼν τοῖς ἀπὸ τῶν νεῶν ὁπλίταις τοὺς μὲν ἄλλους εἰς τὰ τείχη συνέστειλε δείσαντας αὐτοῦ τὴν ἔφοδον, ἐν δὲ Νεμέᾳ Σικυωνίους ὑποστάντας καὶ συνάψαντας μάχην κατὰ κράτος τρεψάμενος ἔστησε τρόπαιον. ἐκ δ’ Ἀχαΐας φίλης οὔσης στρατιώτας ἀναλαβὼν εἰς τὰς τριήρεις ἐπὶ τὴν ἀντιπέρας ἤπειρον ἐκομίσθη τῷ στόλῳ, καὶ παραπλεύσας τὸν Ἀχελῷον Ἀκαρνανίαν κατέδραμε, καὶ κατέκλεισεν Οἰνιάδας εἰς τὸ τεῖχος, καὶ τεμὼν τὴν γῆν καὶ κακώσας ἀπῆρεν ἐπ’ οἴκου, φοβερὸς μὲν φανεὶς τοῖς πολεμίοις, ἀσφαλὴς δὲ καὶ δραστήριος τοῖς πολίταις. οὐδὲν γὰρ οὐδ’ ἀπὸ τύχης πρόσκρουσμα συνέβη περὶ τοὺς στρατευομένους.", "st": "Per. 19.1"}, {"sp": "N", "t": "εἰς δὲ τὸν Πόντον εἰσπλεύσας στόλῳ μεγάλῳ καὶ κεκοσμημένῳ λαμπρῶς ταῖς μὲν Ἑλληνίσι πόλεσιν ὧν ἐδέοντο διεπράξατο καὶ προσηνέχθη φιλανθρώπως, τοῖς δὲ περιοικοῦσι βαρβάροις ἔθνεσι καὶ βασιλεῦσιν αὐτῶν καὶ δυνάσταις ἐπεδείξατο μὲν τῆς δυνάμεως τὸ μέγεθος καὶ τὴν ἄδειαν καὶ τὸ θάρσος ᾗ βούλοιντο πλεόντων καὶ πᾶσαν ὑφ’ αὑτοῖς πεποιημένων τὴν θάλασσαν, Σινωπεῦσι δὲ τρισκαίδεκα ναῦς ἀπέλιπε μετὰ Λαμάχου καὶ στρατιώτας ἐπὶ Τιμησίεων τύραννον. ἐκπεσόντος δὲ τούτου καὶ τῶν ἑταίρων ἐψηφίσατο πλεῖν εἰς Σινώπην Ἀθηναίων ἐθελοντὰς ἑξακοσίους καὶ συγκατοικεῖν Σινωπεῦσι, νειμαμένους οἰκίας καὶ χώραν ἣν πρότερον οἱ τύραννοι κατεῖχον.", "st": "Per. 20.1"}, {"sp": "N", "t": "τἆλλα δ’ οὐ συνεχώρει ταῖς ὁρμαῖς τῶν πολιτῶν, οὐδὲ συνεξέπιπτεν ὑπὸ ῥώμης καὶ τύχης τοσαύτης ἐπαιρομένων Αἰγύπτου τε πάλιν ἀντιλαμβάνεσθαι καὶ κινεῖν τῆς βασιλέως ἀρχῆς τὰ πρὸς θαλάσσῃ. πολλοὺς δὲ καὶ Σικελίας ὁ δύσερως ἐκεῖνος ἤδη καὶ δύσποτμος ἔρως εἶχεν, ὃν ὕστερον ἐξέκαυσαν οἱ περὶ τὸν Ἀλκιβιάδην ῥήτορες. ἦν δὲ καὶ Τυρρηνία καὶ Καρχηδὼν ἐνίοις ὄνειρος οὐκ ἀπ’ ἐλπίδος διὰ τὸ μέγεθος τῆς ὑποκειμένης ἡγεμονίας καὶ τὴν εὔροιαν τῶν πραγμάτων.", "st": "Per. 20.3"}, {"sp": "N", "t": "ἀλλ’ ὁ Περικλῆς κατεῖχε τὴν ἐκδρομὴν ταύτην καὶ περιέκοπτε τὴν πολυπραγμοσύνην, καὶ τὰ πλεῖστα τῆς δυνάμεως ἔτρεπεν εἰς φυλακὴν καὶ βεβαιότητα τῶν ὑπαρχόντων, μέγα ἔργον ἡγούμενος ἀνείργειν Λακεδαιμονίους καὶ ὅλως ὑπεναντιούμενος ἐκείνοις, ὡς ἄλλοις τε πολλοῖς ἔδειξε καὶ μάλιστα τοῖς περὶ τὸν ἱερὸν πραχθεῖσι πόλεμον. ἐπεὶ γὰρ οἱ Λακεδαιμόνιοι στρατεύσαντες εἰς Δελφοὺς Φωκέων ἐχόντων τὸ ἱερὸν Δελφοῖς ἀπέδωκαν, εὐθὺς ἐκείνων ἀπαλλαγέντων ὁ Περικλῆς ἐπιστρατεύσας πάλιν εἰσήγαγε τοὺς Φωκέας. καὶ τῶν Λακεδαιμονίων ἣν ἔδωκαν αὐτοῖς Δελφοὶ προμαντείαν εἰς τὸ μέτωπον ἐγκολαψάντων τοῦ χαλκοῦ λύκου, λαβὼν καὶ αὐτὸς προμαντείαν τοῖς Ἀθηναίοις εἰς τὸν αὐτὸν λύκον κατὰ τὴν δεξιὰν πλευρὰν ἐνεχάραξεν.", "st": "Per. 21.1"}, {"sp": "N", "t": "ὅτι δ’ ὀρθῶς ἐν τῇ Ἑλλάδι τὴν δύναμιν τῶν Ἀθηναίων συνεῖχεν, ἐμαρτύρησεν αὐτῷ τὰ γενόμενα. πρῶτον μὲν γὰρ Εὐβοεῖς ἀπέστησαν, ἐφ’ οὓς διέβη μετὰ δυνάμεως. εἶτ’ εὐθὺς ἀπηγγέλλοντο Μεγαρεῖς ἐκπεπολεμωμένοι καὶ στρατιὰ πολεμίων ἐπὶ τοῖς ὅροις τῆς Ἀττικῆς οὖσα, Πλειστώνακτος ἡγουμένου, βασιλέως Λακεδαιμονίων. πάλιν οὖν ὁ Περικλῆς κατὰ τάχος ἐκ τῆς Εὐβοίας ἀνεκομίζετο πρὸς τὸν ἐν τῇ Ἀττικῇ πόλεμον· καὶ συνάψαι μὲν εἰς χεῖρας οὐκ ἐθάρσησε πολλοῖς καὶ ἀγαθοῖς ὁπλίταις προκαλουμένοις, ὁρῶν δὲ τὸν Πλειστώνακτα νέον ὄντα κομιδῇ, χρώμενον δὲ μάλιστα Κλεανδρίδῃ τῶν συμβούλων, ὃν οἱ ἔφοροι φύλακα καὶ πάρεδρον αὐτῷ διὰ τὴν ἡλικίαν συνέπεμψαν, ἐπειρᾶτο τούτου κρύφα· καὶ ταχὺ διαφθείρας χρήμασιν αὐτὸν ἔπεισεν ἐκ τῆς Ἀττικῆς ἀπαγαγεῖν τοὺς Πελοποννησίους.", "st": "Per. 22.1"}, {"sp": "N", "t": "ὡς δ’ ἀπεχώρησεν ἡ στρατιὰ καὶ διελύθη κατὰ πόλεις, βαρέως φέροντες οἱ Λακεδαιμόνιοι τὸν μὲν βασιλέα χρήμασιν ἐζημίωσαν, ὧν τὸ πλῆθος οὐκ ἔχων ἐκτῖσαι μετέστησεν ἑαυτὸν ἐκ Λακεδαίμονος, τοῦ δὲ Κλεανδρίδου φεύγοντος θάνατον κατέγνωσαν. οὗτος δ’ ἦν πατὴρ Γυλίππου τοῦ περὶ Σικελίαν Ἀθηναίους καταπολεμήσαντος. ἔοικε δ’ ὥσπερ συγγενικὸν αὐτῷ προστρίψασθαι νόσημα τὴν φιλαργυρίαν ἡ φύσις, ὑφ’ ἧς καὶ αὐτὸς αἰσχρῶς ἐπὶ καλοῖς ἔργοις ἁλοὺς ἐξέπεσε τῆς Σπάρτης. ταῦτα μὲν οὖν ἐν τοῖς περὶ Λυσάνδρου δεδηλώκαμεν.", "st": "Per. 22.3"}, {"sp": "N", "t": "τοῦ δὲ Περικλέους ἐν τῷ τῆς στρατηγίας ἀπολογισμῷ δέκα ταλάντων ἀνάλωμα γράψαντος ἀνηλωμένων εἰς τὸ δέον, ὁ δῆμος ἀπεδέξατο μὴ πολυπραγμονήσας μηδ’ ἐλέγξας τὸ ἀπόρρητον. ἔνιοι δ’ ἱστορήκασιν, ὧν ἐστι καὶ Θεόφραστος ὁ φιλόσοφος, ὅτι καθ’ ἕκαστον ἐνιαυτὸν εἰς τὴν Σπάρτην ἐφοίτα δέκα τάλαντα παρὰ τοῦ Περικλέους, οἷς τοὺς ἐν τέλει πάντας θεραπεύων παρῃτεῖτο τὸν πόλεμον, οὐ τὴν εἰρήνην ὠνούμενος, ἀλλὰ τὸν χρόνον, ἐν ᾧ παρασκευασάμενος καθ’ ἡσυχίαν ἔμελλε πολεμήσειν βέλτιον. αὖθις οὖν ἐπὶ τοὺς ἀφεστῶτας τραπόμενος καὶ διαβὰς εἰς Εὔβοιαν πεντήκοντα ναυσὶ καὶ πεντακισχιλίοις ὁπλίταις κατεστρέψατο τὰς πόλεις. καὶ Χαλκιδέων μὲν τοὺς ἱπποβότας λεγομένους πλούτῳ καὶ δόξῃ διαφέροντας ἐξέβαλεν, Ἑστιεῖς δὲ πάντας ἀναστήσας ἐκ τῆς χώρας Ἀθηναίους κατῴκισε, μόνοις τούτοις ἀπαραιτήτως χρησάμενος ὅτι ναῦν Ἀττικὴν αἰχμάλωτον λαβόντες ἀπέκτειναν τοὺς ἄνδρας.", "st": "Per. 23.1"}, {"sp": "N", "t": "ἐκ τούτου γενομένων σπονδῶν Ἀθηναίοις καὶ Λακεδαιμονίοις εἰς ἔτη τριάκοντα ψηφίζεται τὸν εἰς Σάμον πλοῦν, αἰτίαν ποιησάμενος κατ’ αὐτῶν ὅτι τὸν πρὸς Μιλησίους κελευόμενοι διαλύσασθαι πόλεμον οὐχ ὑπήκουον.", "st": "Per. 24.1"}, {"sp": "N", "t": "ἐπεὶ δ’ Ἀσπασία χαριζόμενος δοκεῖ πρᾶξαι τὰ πρὸς Σαμίους, ἐνταῦθα ἂν εἴη καιρὸς διαπορῆσαι μάλιστα περὶ τῆς ἀνθρώπου, τίνα τέχνην ἢ δύναμιν τοσαύτην ἔχουσα τῶν τε πολιτικῶν τοὺς πρωτεύοντας ἐχειρώσατο καὶ τοῖς φιλοσόφοις οὐ φαῦλον οὐδ’ ὀλίγον ὑπὲρ αὑτῆς παρέσχε λόγον. ὅτι μὲν γὰρ ἦν Μιλησία γένος, Ἀξιόχου θυγάτηρ, ὁμολογεῖται· φασὶ δ’ αὐτὴν Θαργηλίαν τινὰ τῶν παλαιῶν Ἰάδων ζηλώσασαν ἐπιθέσθαι τοῖς δυνατωτάτοις ἀνδράσι. καὶ γὰρ ἡ Θαργηλία τό τ’ εἶδος εὐπρεπὴς γενομένη καὶ χάριν ἔχουσα μετὰ δεινότητος πλείστοις μὲν Ἑλλήνων συνῴκησεν ἀνδράσι, πάντας δὲ προσεποίησε βασιλεῖ τοὺς πλησιάσαντας αὐτῇ, καὶ ταῖς πόλεσι μηδισμοῦ δι’ ἐκείνων ὑπέσπειρεν ἀρχὰς δυνατωτάτων ὄντων καὶ μεγίστων. τὴν δ’ Ἀσπασίαν οἱ μὲν ὡς σοφήν τινα καὶ πολιτικὴν ὑπὸ τοῦ Περικλέους σπουδασθῆναι λέγουσι· καὶ γὰρ Σωκράτης ἔστιν ὅτε μετὰ τῶν γνωρίμων ἐφοίτα, καὶ τὰς γυναῖκας ἀκροασομένας οἱ συνήθεις ἦγον ὡς αὐτήν, καίπερ οὐ κοσμίου προεστῶσαν ἐργασίας οὐδὲ σεμνῆς, ἀλλὰ παιδίσκας ἑταιρούσας τρέφουσαν· Αἰσχίνης δέ φησι καὶ Λυσικλέα τὸν προβατοκάπηλον ἐξ ἀγεννοῦς καὶ ταπεινοῦ τὴν φύσιν Ἀθηναίων γενέσθαι πρῶτον, Ἀσπασίᾳ συνόντα μετὰ τὴν Περικλέους τελευτήν. ἐν δὲ τῷ Μενεξένῳ τῷ Πλάτωνος, εἰ καὶ μετὰ παιδιᾶς τὰ πρῶτα γέγραπται, τοσοῦτόν γ’ ἱστορίας ἔνεστιν, ὅτι δόξαν εἶχε τὸ γύναιον ἐπὶ ῥητορικῇ πολλοῖς Ἀθηναίων ὁμιλεῖν. φαίνεται μέντοι μᾶλλον ἐρωτική τις ἡ τοῦ Περικλέους ἀγάπησις γενομένη πρὸς Ἀσπασίαν. ἦν μὲν γὰρ αὐτῷ γυνὴ προσήκουσα μὲν κατὰ γένος, συνῳκηκυῖα δ’ Ἱππονίκῳ πρότερον, ἐξ οὗ Καλλίαν ἔτεκε τὸν πλούσιον· ἔτεκε δὲ καὶ παρὰ τῷ Περικλεῖ Ξάνθιππον καὶ Πάραλον. εἶτα τῆς συμβιώσεως οὐκ οὔσης αὐτοῖς ἀρεστῆς, ἐκείνην μὲν ἑτέρῳ Βουλομένην συνεξέδωκεν, αὐτὸς δὲ τὴν Ἀσπασίαν λαβὼν ἔστερξε διαφερόντως. καὶ γὰρ ἐξιών, ὥς φασι, καὶ εἰσιὼν ἀπ’ ἀγορᾶς ἠσπάζετο καθ’ ἡμέραν αὐτὴν μετὰ τοῦ καταφιλεῖν.", "st": "Per. 24.2"}, {"sp": "N", "t": "ἐν δὲ ταῖς κωμῳδίαις Ὀμφάλη τε νέα καὶ Δηϊάνειρα καὶ πάλιν Ἥρα προσαγορεύεται. Κρατῖνος δ’ ἄντικρυς παλλακὴν αὐτὴν εἴρηκεν ἐν τούτοις·", "st": "Per. 24.2b"}, {"sp": "N", "t": "Ἥραν τέ οἱ Ἀσπασίαν τίκτει Καταπυγοσύνη παλλακὴν κυνώπιδα.", "st": "Per. 24.2c"}, {"sp": "N", "t": "δοκεῖ δὲ καὶ τὸν νόθον ἐκ ταύτης τεκνῶσαι, περὶ οὗ πεποίηκεν Εὔπολις ἐν Δήμοις αὐτὸν μὲν οὕτως ἐρωτῶντα·", "st": "Per. 24.2d"}, {"sp": "N", "t": "ὁ νόθος δέ μοι ζῇ;", "st": "Per. 24.2e"}, {"sp": "N", "t": "τὸν δὲ Μυρωνίδην ἀποκρινόμενον·<br>καὶ πάλαι γ’ ἂν ἦν ἀνήρ,<br>εἰ μὴ τὸ τῆς πόρνης ὑπωρρώδει κακόν.", "st": "Per. 24.2f"}, {"sp": "N", "t": "οὕτω δὲ τὴν Ἀσπασίαν ὀνομαστὴν καὶ κλεινὴν γενέσθαι λέγουσιν ὥστε καὶ Κῦρον τὸν πολεμήσαντα βασιλεῖ περὶ τῆς τῶν Περσῶν ἡγεμονίας τὴν ἀγαπωμένην ὑπ’ αὐτοῦ μάλιστα τῶν παλλακίδων Ἀσπασίαν ὀνομάσαι, καλουμένην Μιλτὼ πρότερον. ἦν δὲ Φωκαῒ τὸ γένος, Ἑρμοτίμου θυγάτηρ· ἐν δὲ τῇ μάχῃ Κύρυ πεσόντος ἀπαχθεῖσα πρὸς βασιλέα πλεῖστον ἴσχυσε. ταῦτα μὲν ἐπελθόντα τῇ μνήμῃ κατὰ τὴν γραφὴν ἀπώσασθαι καὶ παρελθεῖν ἴσως ἀπάνθρωπον ἦν.", "st": "Per. 24.7"}, {"sp": "N", "t": "τὸν δὲ πρὸς Σαμίους πόλεμον αἰτιῶνται μάλιστα τὸν Περικλέα ψηφίσασθαι διὰ Μιλησίους Ἀσπασίας δεηθείσης. αἱ γὰρ πόλεις ἐπολέμουν τὸν περὶ Πριήνης πόλεμον, καὶ κρατοῦντες οἱ Σάμιοι, παύσασθαι τῶν Ἀθηναίων κελευόντων καὶ δίκας λαβεῖν καὶ δοῦναι παρ’ αὐτοῖς, οὐκ ἐπείθοντο. πλεύσας οὖν ὁ Περικλῆς τὴν μὲν οὖσαν ὀλιγαρχίαν ἐν Σάμῳ κατέλυσεν, τῶν δὲ πρώτων λαβὼν ὁμήρους πεντήκοντα καὶ παῖδας ἴσους εἰς Λῆμνον ἀπέστειλε. καίτοι φασὶν ἕκαστον μὲν αὐτῷ τῶν ὁμήρων διδόναι τάλαντον ὑπὲρ ἑαυτοῦ, πολλὰ δ’ ἄλλα τοὺς μὴ θέλοντας ἐν τῇ πόλει γενέσθαι δημοκρατίαν. ἔτι δὲ Πισσούθνης ὁ Πέρσης ἔχων τινὰ πρὸς Σαμίους εὔνοιαν ἀπέστειλεν αὐτῷ μυρίους χρυσοῦς, παραιτούμενος τὴν πόλιν. οὐ μὴν ἔλαβε τούτων οὐδὲν ὁ Περικλῆς, ἀλλὰ χρησάμενος ὥσπερ ἐγνώκει τοῖς Σαμίοις καὶ καταστήσας δημοκρατίαν ἀπέπλευσεν εἰς τὰς Ἀθήνας. οἱ δ’ εὐθὺς ἀπέστησαν, ἐκκλέψαντος αὐτοῖς τοὺς ὁμήρους Πισσούθνου καὶ τἆλλα παρασκευάσαντος πρὸς τὸν πόλεμον. αὖθις οὖν ὁ Περικλῆς ἐξέπλευσεν ἐπ’ αὐτοὺς οὐχ ἡσυχάζοντας οὐδὲ κατεπτηχότας, ἀλλὰ καὶ πάνυ προθύμως ἐγνωκότας ἀντιλαμβάνεσθαι τῆς θαλάττης. γενομένης δὲ καρτερᾶς ναυμαχίας περὶ νῆσον ἣν Τραγίας καλοῦσι, λαμπρῶς ὁ Περικλῆς ἐνίκα, τέσσαρσι καὶ τεσσαράκοντα ναυσὶν ἑβδομήκοντα καταναυμαχήσας, ὧν εἴκοσι στρατιώτιδες ἦσαν.", "st": "Per. 25.1"}, {"sp": "N", "t": "ἅμα δὲ τῇ νίκῃ καὶ τῇ διώξει τοῦ λιμένος κρατήσας ἐπολιόρκει τοὺς Σαμίους, ἁμῶς γέ πως ἔτι τολμῶντας ἐπεξιέναι καὶ διαμάχεσθαι πρὸ τοῦ τείχους. ἐπεὶ δὲ μείζων ἕτερος στόλος ἦλθεν ἐκ τῶν Ἀθηνῶν καὶ παντελῶς κατεκλείσθησαν οἱ Σάμιοι, λαβὼν ὁ Περικλῆς ἑξήκοντα τριήρεις ἔπλευσεν εἰς τὸν ἔξω πόντον, ὡς μὲν οἱ πλεῖστοι λέγουσι, Φοινισσῶν νεῶν ἐπικούρων τοῖς Σαμίοις προσφερομένων ἀπαντῆσαι καὶ διαγωνίσασθαι πορρωτάτω βουλόμενος, ὡς δὲ Στησίμβροτος, ἐπὶ Κύπρον στελλόμενος· ὅπερ οὐ δοκεῖ πιθανὸν εἶναι. ὁποτέρῳ δ’ οὖν ἐχρήσατο τῶν λογισμῶν, ἁμαρτεῖν ἔδοξε. πλεύσαντος γὰρ αὐτοῦ Μέλισσος ὁ Ἰθαγένους, ἀνὴρ φιλόσοφος στρατηγῶν τότε τῆς Σάμου, καταφρονήσας τῆς ὀλιγότητος τῶν νεῶν ἢ τῆς ἀπειρίας τῶν στρατηγῶν, ἔπεισε τοὺς πολίτας ἐπιθέσθαι τοῖς Ἀθηναίοις. καὶ γενομένης μάχης νικήσαντες οἱ Σάμιοι, καὶ πολλοὺς μὲν αὐτῶν ἄνδρας ἑλόντες, πολλὰς δὲ ναῦς διαφθείραντες, ἐχρῶντο τῇ θαλάσσῃ καὶ παρετίθεντο τῶν ἀναγκαίων πρὸς τὸν πόλεμον ὅσα μὴ πρότερον εἶχον. ὑπὸ δὲ τοῦ Μελίσσου καὶ Περικλέα φησὶν αὐτὸν Ἀριστοτέλης ἡττηθῆναι ναυμαχοῦντα πρότερον.", "st": "Per. 26.1"}, {"sp": "N", "t": "οἱ δὲ Σάμιοι τοὺς αἰχμαλώτους τῶν Ἀθηναίων ἀνθυβρίζοντες ἔστιζον εἰς τὸ μέτωπον γλαῦκας· καὶ γὰρ ἐκείνους οἱ Ἀθηναῖοι σάμαιναν. ἡ δὲ σάμαινα ναῦς ἐστιν ὑόπρωρος μὲν τὸ σίμωμα, κοιλοτέρα δὲ καὶ γαστροειδής, ὥστε καὶ ποντοπορεῖν καὶ ταχυναυτεῖν. οὕτω δ’ ὠνομάσθη διὰ τὸ πρῶτον ἐν Σάμῳ φανῆναι, Πολυκράτους τυράννου κατασκευάσαντος. πρὸς ταῦτα τὰ στίγματα λέγουσι καὶ τὸ Ἀριστοφάνειον ᾐνίχθαι·", "st": "Per. 26.4"}, {"sp": "N", "t": "Σαμίων ὁ δῆμός ἐστιν ὡς πολυγράμματος.", "st": "Per. 26.4b"}, {"sp": "N", "t": "πυθόμενος δ’ οὖν ὁ Περικλῆς τὴν ἐπὶ στρατοπέδου συμφορὰν ἐβοήθει κατὰ τάχος καὶ τοῦ Μελίσσου πρὸς αὐτὸν ἀντιταξαμένου κρατήσας καὶ τρεψάμενος τοὺς πολεμίους εὐθὺς περιετείχιζε, δαπάνῃ καὶ χρόνῳ μᾶλλον ἢ τραύμασι καὶ κινδύνοις τῶν πολιτῶν περιγενέσθαι καὶ συνελεῖν τὴν πόλιν βουλόμενος. ἐπεὶ δὲ δυσχεραίνοντας τῇ τριβῇ τοὺς Ἀθηναίους καὶ μάχεσθαι προθυμουμένους ἔργον ἦν κατασχεῖν, ὀκτὼ μέρη διελὼν τὸ πᾶν πλῆθος ἀπεκλήρου, καὶ τῷ λαβόντι τὸν λευκὸν κύαμον εὐωχεῖσθαι καὶ σχολάζειν παρεῖχε τῶν ἄλλων μαχομένων. διὸ καί φασι τοὺς ἐν εὐπαθείαις τισὶ γενομένους λευκὴν ἡμέραν ἐκείνην ἀπὸ τοῦ λευκοῦ κυάμου προσαγορεύειν.", "st": "Per. 27.1"}, {"sp": "N", "t": "Ἔφορος δὲ καὶ μηχαναῖς χρήσασθαι τὸν Περικλέα, τὴν καινότητα θαυμάσαντα, Ἀρτέμωνος τοῦ μηχανικοῦ παρόντος, ὃν χωλὸν ὄντα καὶ φορείῳ πρὸς τὰ κατεπείγοντα τῶν ἔργων προσκομιζόμενον ὀνομασθῆναι περιφόρητον. τοῦτο μὲν οὖν Ἡρακλείδης ὁ Ποντικὸς ἐλέγχει τοῖς Ἀνακρέοντος ποιήμασιν, ἐν οἷς ὁ περιφόρητος Ἀρτέμων ὀνομάζεται πολλαῖς ἔμπροσθεν ἡλικίαις τοῦ περὶ Σάμον πολέμου καὶ τῶν πραγμάτων ἐκείνων· τὸν δ’ Ἀρτέμωνά φησι τρυφερόν τινα τῷ βίῳ καὶ πρὸς τοὺς φόβους μαλακὸν ὄντα καὶ καταπλῆγα τὰ πολλὰ μὲν οἴκοι καθέζεσθαι, χαλκῆν ἀσπίδα τῆς κεφαλῆς αὐτοῦ δυεῖν οἰκετῶν ὑπερεχόντων, ὥστε μηδὲν ἐμπεσεῖν τῶν ἄνωθεν, εἰ δὲ βιασθείη προελθεῖν, ἐν κλινιδίῳ κρεμαστῷ παρὰ τὴν γῆν αὐτὴν περιφερόμενον κομίζεσθαι, καὶ διὰ τοῦτο κληθῆναι περιφόρητον.", "st": "Per. 27.3"}, {"sp": "N", "t": "ἐνάτῳ δὲ μηνὶ τῶν Σαμίων παραστάντων ὁ Περικλῆς τὰ τείχη καθεῖλε καὶ τὰς ναῦς παρέλαβε καὶ χρήμασι πολλοῖς ἐζημίωσεν, ὧν τὰ μὲν εὐθὺς εἰσήνεγκαν οἱ Σάμιοι, τὰ δ’ ἐν χρόνῳ ῥητῷ ταξάμενοι κατοίσειν ὁμήρους ἔδωκαν. Δοῦρις δ’ ὁ Σάμιος τούτοις ἐπιτραγῳδεῖ πολλὴν ὠμότητα τῶν Ἀθηναίων καὶ τοῦ Περικλέους κατηγορῶν, ἣν οὔτε Θουκυδίδης ἱστόρηκεν οὔτ’ Ἔφορος οὔτ’ Ἀριστοτέλης· ἀλλ’ οὐδ’ ἀληθεύειν ἔοικεν, ὡς ἄρα τοὺς τριηράρχους καὶ τοὺς ἐπιβάτας τῶν Σαμίων εἰς τὴν Μιλησίων ἀγορὰν καταγαγὼν καὶ σανίσι προσδήσας ἐφ’ ἡμέρας δέκα κακῶς ἤδη διακειμένους προσέταξεν ἀνελεῖν, ξύλοις τὰς κεφαλὰς συγκόψαντας, εἶτα προβαλεῖν ἀκήδευτα τὰ σώματα. Δοῦρις μὲν οὖν οὐδ’ ὅπου μηδὲν αὐτῷ πρόσεστιν ἴδιον πάθος εἰωθὼς κρατεῖν τὴν διήγησιν ἐπὶ τῆς ἀληθείας, μᾶλλον ἔοικεν ἐνταῦθα δεινῶσαι τὰς τῆς πατρίδος συμφορὰς ἐπὶ διαβολῇ τῶν Ἀθηναίων.", "st": "Per. 28.1"}, {"sp": "N", "t": "ὁ δὲ Περικλῆς καταστρεψάμενος τὴν Σάμον ὡς ἐπανῆλθεν εἰς τὰς Ἀθήνας, ταφάς τε τῶν ἀποθανόντων κατὰ τὸν πόλεμον ἐνδόξους ἐποίησε καὶ τὸν λόγον εἰπών, ὥσπερ ἔθος ἐστίν, ἐπὶ τῶν σημάτων ἐθαυμαστώθη. καταβαίνοντα δ’ αὐτὸν ἀπὸ τοῦ βήματος αἱ μὲν ἄλλαι γυναῖκες ἐδεξιοῦντο καὶ στεφάνοις ἀνέδουν καὶ ταινίαις ὥσπερ ἀθλητὴν νικηφόρον, ἡ δ’ Ἐλπινίκη προσελθοῦσα πλησίον· ταῦτ’, ἔφη, θαυμαστά, Περίκλεις, καὶ ἄξια στεφάνων, ὃς ἡμῖν πολλοὺς καὶ ἀγαθοὺς ἀπώλεσας πολίτας οὐ Φοίνιξι πολεμῶν οὐδὲ Μήδοις, ὥσπερ οὑμὸς ἀδελφὸς Κίμων, ἀλλὰ σύμμαχον καὶ συγγενῆ πόλιν καταστρεφόμενος. ταῦτα τῆς Ἐλπινίκης λεγούσης ὁ Περικλῆς μειδιάσας ἀτρέμα λέγεται τὸ τοῦ Ἀρχιλόχου πρὸς αὐτὴν εἰπεῖν·", "st": "Per. 28.4"}, {"sp": "N", "t": "οὐκ ἂν μύροισι γραῦς ἐοῦσ’ ἠλείφεο.", "st": "Per. 28.4b"}, {"sp": "N", "t": "θαυμαστὸν δέ τι καὶ μέγα φρονῆσαι καταπολεμήσαντα τοὺς Σαμίους φησὶν αὐτὸν ὁ Ἴων, ὡς τοῦ μὲν Ἀγαμέμνονος ἔτεσι δέκα βάρβαρον πόλιν, αὐτοῦ δὲ μησὶν ἐννέα τοὺς πρώτους καὶ δυνατωτάτους Ἰώνων ἑλόντος. καὶ οὐκ ἦν ἄδικος ἡ ἀξίωσις, ἀλλ’ ὄντως πολλὴν ἀδηλότητα καὶ μέγαν ἔσχε κίνδυνον ὁ πόλεμος, εἴπερ, ὡς Θουκυδίδης φησί, παρ’ ἐλάχιστον ἦλθε Σαμίων ἡ πόλις ἀφελέσθαι τῆς θαλάττης τὸ κράτος Ἀθηναίους.", "st": "Per. 28.6"}, {"sp": "N", "t": "μετὰ ταῦτα κυμαίνοντος ἤδη τοῦ Πελοποννησιακοῦ πολέμου, Κερκυραίοις πολεμουμένοις ὑπὸ Κορινθίων ἔπεισε τὸν δῆμον ἀποστεῖλαι βοήθειαν καὶ προσλαβεῖν ἐρρωμένην ναυτικῇ δυνάμει νῆσον, ὡς ὅσον οὐδέπω Πελοποννησίων ἐκπεπολεμωμένων πρὸς αὐτούς. ψηφισαμένου δὲ τοῦ δήμου τὴν βοήθειαν ἀπέστειλε δέκα ναῦς μόνας ἔχοντα Λακεδαιμόνιον, τὸν Κίμωνος υἱόν, οἷον ἐφυβρίζων· πολλὴ γὰρ ἦν εὔνοια καὶ φιλία τῷ Κίμωνος οἴκῳ πρὸς Λακεδαιμονίους. ὡς ἂν οὖν, εἰ μηδὲν ἔργον μέγα μηδ’ ἐκπρεπὲς ἐν τῇ στρατηγίᾳ τοῦ Λακεδαιμονίου γένοιτο, προσδιαβληθείη μᾶλλον εἰς τὸν λακωνισμόν, ὀλίγας αὐτῷ ναῦς ἔδωκε καὶ μὴ βουλόμενον ἐξέπεμψε. καὶ ὅλως διετέλει κολούων ὡς μηδὲ τοῖς ὀνόμασι γνησίους, ἀλλ’ ὀθνείους καὶ ξένους, ὅτι τῶν Κίμωνος υἱῶν τῷ μὲν ἦν Λακεδαιμόνιος ὄνομα, τῷ δὲ Θεσσαλός, τῷ δὲ Ἠλεῖος. ἐδόκουν δὲ πάντες ἐκ γυναικὸς Ἀρκαδικῆς γεγονέναι.", "st": "Per. 29.1"}, {"sp": "N", "t": "κακῶς οὖν ὁ Περικλῆς ἀκούων διὰ τὰς δέκα ταύτας τριήρεις, ὡς μικρὰν μὲν βοήθειαν τοῖς δεηθεῖσι, μεγάλην δὲ πρόφασιν τοῖς ἐγκαλοῦσι παρεσχηκώς, ἑτέρας αὖθις ἔστειλε πλείονας εἰς τὴν Κέρκυραν, αἳ μετὰ τὴν μάχην ἀφίκοντο.", "st": "Per. 29.1b"}, {"sp": "N", "t": "χαλεπαίνουσι δὲ τοῖς Κορινθίοις καὶ κατηγοροῦσι τῶν Ἀθηναίων ἐν Λακεδαίμονι προσεγένοντο Μεγαρεῖς, αἰτιώμενοι πάσης μὲν ἀγορᾶς, πάντων δὲ λιμένων, ὧν Ἀθηναῖοι κρατοῦσιν, εἴργεσθαι καὶ ἀπελαύνεσθαι παρὰ τὰ κοινὰ δίκαια καὶ τοὺς γεγενημένους ὅρκους τοῖς Ἕλλησιν· Αἰγινῆται δὲ κακοῦσθαι δοκοῦντες καὶ βίαια πάσχειν ἐποτνιῶντο κρύφα πρὸς τοὺς Λακεδαιμονίους, φανερῶς ἐγκαλεῖν τοῖς Ἀθηναίοις οὐ θαρροῦντες. ἐν δὲ τούτῳ καὶ Ποτίδαια, πόλις ὑπήκοος Ἀθηναίων, ἄποικος δὲ Κορινθίων, ἀποστᾶσα καὶ πολιορκουμένη μᾶλλον ἐπετάχυνε τὸν πόλεμον.", "st": "Per. 29.4"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ πρεσβειῶν τε πεμπομένων Ἀθήναζε, καὶ τοῦ βασιλέως τῶν Λακεδαιμονίων Ἀρχιδάμου τὰ πολλὰ τῶν ἐγκλημάτων εἰς διαλύσεις ἄγοντος καὶ τοὺς συμμάχους πραΰνοντος, οὐκ ἂν δοκεῖ συμπεσεῖν ὑπό γε τῶν ἄλλων αἰτιῶν ὁ πόλεμος τοῖς Ἀθηναίοις, εἰ τὸ ψήφισμα καθελεῖν τὸ Μεγαρικὸν ἐπείσθησαν καὶ διαλλαγῆναι πρὸς αὐτούς. διὸ καὶ μάλιστα πρὸς τοῦτο Περικλῆς ἐναντιωθείς, καὶ παροξύνας τὸν δῆμον ἐμμεῖναι τῇ πρὸς τοὺς Μεγαρεῖς φιλονεικία, μόνος ἔσχε τοῦ πολέμου τὴν αἰτίαν.", "st": "Per. 29.5"}, {"sp": "N", "t": "λέγουσι δὲ πρεσβείας Ἀθήναζε περὶ τούτων ἐκ Λακεδαίμονος ἀφιγμένης, καὶ τοῦ Περικλέους νόμον τινὰ προβαλλομένου κωλύοντα καθελεῖν τὸ πινάκιον ἐν ᾧ τὸ ψήφισμα γεγραμμένον ἐτύγχανεν, εἰπεῖν Πολυάλκη τῶν πρέσβεων τινά· σὺ δὲ μὴ καθέλῃς, ἀλλὰ στρέψον εἴσω τὸ πινάκιον· οὐ γὰρ ἔστι νόμος ὁ τοῦτο κωλύων. κομψοῦ δὲ τοῦ λόγου φανέντος οὐδέν τι μᾶλλον ὁ Περικλῆς ἐνέδωκεν. ὑπῆν μὲν οὖν τις, ὡς ἔοικεν, αὐτῷ καὶ ἰδία πρὸς τοὺς Μεγαρεῖς ἀπέχθεια· κοινὴν δὲ καὶ φανερὰν ποιησάμενος αἰτίαν κατ’ αὐτῶν ἀποτέμνεσθαι τὴν ἱερὰν ὀργάδα, γράφει ψήφισμα κήρυκα πεμφθῆναι πρὸς αὐτοὺς καὶ πρὸς Λακεδαιμονίους τὸν αὐτὸν κατηγοροῦντα τῶν Μεγαρέων. τοῦτο μὲν οὖν τὸ ψήφισμα Περικλέους ἐστὶν εὐγνώμονος καὶ φιλανθρώπου δικαιολογίας ἐχόμενον· ἐπεὶ δ’ ὁ πεμφθεὶς κῆρυξ Ἀνθεμόκριτος αἰτίᾳ τῶν Μεγαρέων ἀποθανεῖν ἔδοξε, γράφει ψήφισμα κατ’ αὐτῶν Χαρῖνος, ἄσπονδον μὲν εἶναι καὶ ἀκήρυκτον ἔχθραν, ὃς δ’ ἂν ἐπιβῇ τῆς Ἀττικῆς Μεγαρέων θανάτῳ ζημιοῦσθαι, τοὺς δὲ στρατηγούς, ὅταν ὀμνύωσι τὸν πάτριον ὅρκον, ἐπομνύειν ὅτι καὶ δὶς ἀνὰ πᾶν ἔτος εἰς τὴν Μεγαρικὴν ἐμβαλοῦσι· ταφῆναι δ’ Ἀνθεμόκριτον παρὰ τὰς Θριασίας πύλας, αἳ νῦν Δίπυλον ὀνομάζονται.", "st": "Per. 30.1"}, {"sp": "N", "t": "Μεγαρεῖς δὲ τὸν Ἀνθεμοκρίτου φόνον ἀπαρνούμενοι τὰς αἰτίας εἰς Ἀσπασίαν καὶ Περικλέα τρέπουσι, χρώμενοι τοῖς περιβοήτοις καὶ δημώδεσι τούτοις ἐκ τῶν Ἀχαρνέων στιχιδίοις·", "st": "Per. 30.4"}, {"sp": "N", "t": "πόρνην δὲ Σιμαίθαν ἰόντες Μεγάραδε<br>νεανίαι κλέπτουσι μεθυσοκότταβοι·<br>κἆθ’ οἱ Μεγαρεῖς ὀδύναις πεφυσιγγωμένοι<br>ἀντεξέκλεψαν Ἀσπασίας πόρνας δύο.", "st": "Per. 30.4b"}, {"sp": "N", "t": "τὴν μὲν οὖν ἀρχὴν ὅπως ἔσχεν οὐ ῥᾴδιον γνῶναι, τοῦ δὲ μὴ λυθῆναι τὸ ψήφισμα πάντες ὡσαύτως τὴν αἰτίαν ἐπιφέρουσι τῷ Περικλεῖ. πλὴν οἱ μὲν ἐκ φρονήματος μεγάλου μετὰ γνώμης κατὰ τὸ βέλτιστον ἀπισχυρίσασθαί φασιν αὐτόν, πεῖραν ἐνδόσεως τὸ πρόσταγμα καὶ τὴν συγχώρησιν ἐξομολόγησιν ἀσθενείας ἡγούμενον· οἱ δὲ μᾶλλον αὐθαδείᾳ τινὶ καὶ φιλονεικίᾳ πρὸς ἔνδειξιν ἰσχύος περιφρονῆσαι Λακεδαιμονίων.", "st": "Per. 31.1"}, {"sp": "N", "t": "ἡ δὲ χειρίστη μὲν αἰτία πασῶν, ἔχουσα δὲ πλείστους μάρτυρας, οὕτω πως λέγεται. Φειδίας ὁ πλάστης ἐργολάβος μὲν ἦν τοῦ ἀγάλματος, ὥσπερ εἴρηται, φίλος δὲ τῷ Περικλεῖ γενόμενος καὶ μέγιστον παρ’ αὐτῷ δυνηθεὶς τοὺς μὲν δι’ αὑτὸν ἔσχεν ἐχθροὺς φθονούμενος, οἱ δὲ τοῦ δήμου ποιούμενοι πεῖραν ἐν ἐκείνῳ, ποῖός τις ἔσοιτο τῷ Περικλεῖ κριτής, Μένωνά τινα τῶν Φειδίου συνεργῶν πείσαντες ἱκέτην ἐν ἀγορᾷ καθίζουσιν, αἰτούμενον ἄδειαν ἐπὶ μηνύσει καὶ κατηγορίᾳ τοῦ Φειδίου. προσδεξαμένου δὲ τοῦ δήμου τὸν ἄνθρωπον καὶ γενομένης ἐν ἐκκλησίᾳ διώξεως, κλοπαὶ μὲν οὐκ ἠλέγχοντο· τὸ γὰρ χρυσίον οὕτως εὐθὺς ἐξ ἀρχῆς τῷ ἀγάλματι προσειργάσατο καὶ περιέθηκεν ὁ Φειδίας γνώμῃ τοῦ Περικλέους ὥστε πᾶν δυνατὸν εἶναι περιελοῦσιν ἀποδεῖξαι τὸν σταθμόν, ὃ καὶ τότε τοὺς κατηγόρους ἐκέλευσε ποιεῖν ὁ Περικλῆς.", "st": "Per. 31.2"}, {"sp": "N", "t": "ἡ δὲ δόξα τῶν ἔργων ἐπίεζε φθόνῳ τὸν Φειδίαν, καὶ μάλισθ’ ὅτι τὴν πρὸς Ἀμαζόνας μάχην ἐν τῇ ἀσπίδι ποιῶν αὑτοῦ τινα μορφὴν ἐνετύπωσε πρεσβύτου φαλακροῦ πέτρον ἐπῃρμένου δι’ ἀμφοτέρων τῶν χειρῶν, καὶ τοῦ Περικλέους εἰκόνα παγκάλην ἐνέθηκε μαχομένου πρὸς Ἀμαζόνα. τὸ δὲ σχῆμα τῆς χειρός, ἀνατεινούσης δόρυ πρὸ τῆς ὄψεως τοῦ Περικλέους, πεποιημένον εὐμηχάνως οἷον ἐπικρύπτειν βούλεται τὴν ὁμοιότητα παραφαινομένην ἑκατέρωθεν.", "st": "Per. 31.4"}, {"sp": "N", "t": "ὁ μὲν οὖν Φειδίας εἰς τὸ δεσμωτήριον ἀπαχθεὶς ἐτελεύτησε νοσήσας, ὡς δέ φασιν ἔνιοι, φαρμάκοις, ἐπὶ διαβολῇ τοῦ Περικλέους τῶν ἐχθρῶν παρασκευασάντων. τῷ δὲ μηνυτῇ Μένωνι γράψαντος Γλύκωνος ἀτέλειαν ὁ δῆμος ἔδωκε, καὶ προσέταξε τοῖς στρατηγοῖς ἐπιμελεῖσθαι τῆς ἀσφαλείας τοῦ ἀνθρώπου.", "st": "Per. 31.5"}, {"sp": "N", "t": "περὶ δὲ τοῦτον τὸν χρόνον Ἀσπασία δίκην ἔφευγεν ἀσεβείας, Ἑρμίππου τοῦ κωμῳδοποιοῦ διώκοντος καὶ προσκατηγοροῦντος ὡς Περικλεῖ γυναῖκας ἐλευθέρας εἰς τὸ αὐτὸ φοιτώσας ὑποδέχοιτο. καὶ ψήφισμα Διοπείθης ἔγραψεν εἰσαγγέλλεσθαι τοὺς τὰ θεῖα μὴ νομίζοντας ἢ λόγους περὶ τῶν μεταρσίων διδάσκοντας, ἀπερειδόμενος εἰς Περικλέα δι’ Ἀναξαγόρου τὴν ὑπόνοιαν. δεχομένου δὲ τοῦ δήμου καὶ προσιεμένου τὰς διαβολάς, οὕτως ἤδη ψήφισμα κυροῦται, Δρακοντίδου γράψαντος, ὅπως οἱ λόγοι τῶν χρημάτων ὑπὸ Περικλέους εἰς τοὺς Πρυτάνεις ἀποτεθεῖεν, οἱ δὲ δικασταὶ τὴν ψῆφον ἀπὸ τοῦ βωμοῦ φέροντες ἐν τῇ πόλει κρίνοιεν. Ἅγνων δὲ· τοῦτο μὲν ἀφεῖλε τοῦ ψηφίσματος, κρίνεσθαι δὲ τὴν δίκην ἔγραψεν ἐν δικασταῖς χιλίοις καὶ πεντακοσίοις, εἴτε κλοπῆς καὶ δώρων εἴτ’ ἀδικίου βούλοιτό τις ὀνομάζειν τὴν δίωξιν.", "st": "Per. 32.1"}, {"sp": "N", "t": "ἀσπασίαν μὲν οὖν ἐξῃτήσατο, πολλὰ πάνυ παρὰ τὴν δίκην, ὡς Αἰσχίνης φησίν, ἀφεὶς ὑπὲρ αὐτῆς δάκρυα καὶ δεηθεὶς τῶν δικαστῶν· Ἀναξαγόραν δὲ φοβηθεὶς ἐξέπεμψεν ἐκ τῆς πόλεως. ὡς δὲ διὰ Φειδίου προσέπταισε τῷ δήμῳ, φοβηθεὶς τὸ δικαστήριον μέλλοντα τὸν πόλεμον καὶ ὑποτυφόμενον ἐξέκαυσεν, ἐλπίζων διασκεδάσειν τὰ ἐγκλήματα καὶ ταπεινώσειν τὸν φθόνον ἐν πράγμασι μεγάλοις καὶ κινδύνοις τῆς πόλεως ἐκείνῳ μόνῳ διὰ τὸ ἀξίωμα καὶ τὴν δύναμιν ἀναθείσης ἑαυτήν. αἱ μὲν οὖν αἰτίαι δι’ ἃς οὐκ εἴασεν ἐνδοῦναι Λακεδαιμονίοις τὸν δῆμον, αὗται λέγονται, τὸ δ’ ἀληθὲς ἄδηλον.", "st": "Per. 32.3"}, {"sp": "N", "t": "οἱ δὲ Λακεδαιμόνιοι γινώσκοντες ὡς ἐκείνου καταλυθέντος εἰς πάντα μαλακωτέροις χρήσονται τοῖς Ἀθηναίοις, ἐκέλευον αὐτοὺς τὸ ἄγος ἐλαύνειν τὸ Κυλώνειον, ᾧ τὸ μητρόθεν γένος τοῦ Περικλέους ἔνοχον ἦν, ὡς Θουκυδίδης ἱστόρηκεν. ἡ δὲ πεῖρα περιέστη τοῖς πέμψασιν εἰς τοὐναντίον· ἀντὶ γὰρ ὑποψίας καὶ διαβολῆς ὁ Περικλῆς ἔτι μείζονα πίστιν ἔσχε καὶ τιμὴν παρὰ τοῖς πολίταις, ὡς μάλιστα μισούντων καὶ φοβουμένων ἐκεῖνον τῶν πολεμίων. διὸ καὶ πρὶν ἐμβαλεῖν εἰς τὴν Ἀττικὴν τὸν Ἀρχίδαμον ἔχοντα τοὺς Πελοποννησίους προεῖπε τοῖς Ἀθηναίοις, ἂν ἄρα τἆλλα δῃῶν ὁ Ἀρχίδαμος ἀπέχηται τῶν ἐκείνου διὰ τὴν ξενίαν τὴν οὖσαν αὐτοῖς, ἢ διαβολῆς τοῖς ἐχθροῖς ἐνδιδοὺς ἀφορμάς, ὅτι τῇ πόλει καὶ τὴν χώραν καὶ τὰς ἐπαύλεις ἐπιδίδωσιν.", "st": "Per. 33.1"}, {"sp": "N", "t": "ἐμβάλλουσιν οὖν εἰς τὴν Ἀττικὴν στρατῷ μεγάλῳ Λακεδαιμόνιοι μετὰ τῶν συμμάχων, Ἀρχιδάμου τοῦ βασιλέως ἡγουμένου. καὶ δῃοῦντες τὴν χώραν προῆλθον εἰς Ἀχαρνὰς καὶ κατεστρατοπέδευσαν, ὡς τῶν Ἀθηναίων οὐκ ἀνεξομένων, ἀλλ’ ὑπ’ ὀργῆς καὶ φρονήματος διαμαχουμένων πρὸς αὐτούς. τῷ δὲ Περικλεῖ δεινὸν ἐφαίνετο πρὸς τοὺς ἑξακισμυρίους Πελοποννησίων καὶ Βοιωτῶν ὁπλίτας (τοσοῦτοι γὰρ ἦσαν οἱ τὸ πρῶτον ἐμβαλόντες) ὑπὲρ αὐτῆς τῆς πόλεως μάχην συνάψαι· τοὺς δὲ βουλομένους μάχεσθαι καὶ δυσπαθοῦντας πρὸς τὰ γινόμενα κατεπράϋνε, λέγων ὡς δένδρα μὲν τμηθέντα καὶ κοπέντα φύεται ταχέως, ἀνδρῶν δὲ διαφθαρέντων αὖθις τυχεῖν οὐ ῥᾴδιόν ἐστι. τὸν δὲ δῆμον εἰς ἐκκλησίαν οὐ συνῆγε δεδιὼς βιασθῆναι παρὰ γνώμην, ἀλλ’ ὥσπερ νεὼς κυβερνήτης ἀνέμου κατιόντος ἐν πελάγει θέμενος εὖ πάντα καὶ κατατείνας τὰ ὅπλα χρῆται τῇ τέχνῃ, δάκρυα καὶ δεήσεις ἐπιβατῶν ναυτιώντων καὶ φοβουμένων ἐάσας, οὕτως ἐκεῖνος, τό τε ἄστυ συγκλείσας καὶ καταλαβὼν πάντα φυλακαῖς πρὸς ἀσφάλειαν, ἐχρῆτο τοῖς αὑτοῦ λογισμοῖς, βραχέα φροντίζων τῶν καταβοώντων καὶ δυσχεραινόντων. καίτοι πολλοὶ μὲν αὐτοῦ τῶν φίλων δεόμενοι προσέκειντο, πολλοὶ δὲ τῶν ἐχθρῶν ἀπειλοῦντες καὶ κατηγοροῦντες, χοροὶ δ’ ᾖδον ᾄσματα καὶ σκώμματα πρὸς αἰσχύνην, ἐφυβρίζοντες αὐτοῦ τὴν στρατηγίαν ὡς ἄνανδρον καὶ προϊεμένην τὰ πράγματα τοῖς πολεμίοις. ἐπεφύετο δὲ καὶ Κλέων ἤδη, διὰ τῆς πρὸς ἐκεῖνον ὀργῇς τῶν πολιτῶν πορευόμενος ἐπὶ τὴν δημαγωγίαν, ὡς τἀνάπαιστα ταῦτα δηλοῖ ποιήσαντος Ἑρμίππου·", "st": "Per. 33.3"}, {"sp": "N", "t": "βασιλεῦ σατύρων, τί ποτ’ οὐκ ἐθέλεις<br>δόρυ βαστάζειν, ἀλλὰ λόγους μὲν<br>περὶ τοῦ πολέμου δεινοὺς παρέχεις, ψυχὴ δὲ Τέλητος ὕπεστιν;", "st": "Per. 33.3b"}, {"sp": "N", "t": "κἀγχειριδίου δ’ ἀκόνῃ σκληρᾷ<br>παραθηγομένης βρύχεις κοπίδος, δηχθεὶς αἴθωνι Κλέωνι.", "st": "Per. 33.3c"}, {"sp": "N", "t": "πλὴν ὑπ’ οὐδενὸς ἐκινήθη τῶν τοιούτων ὁ Περικλῆς, ἀλλὰ πρᾴως καὶ σιωπῇ τὴν ἀδοξίαν καὶ τὴν ἀπέχθειαν ὑφιστάμενος, καὶ νεῶν ἑκατὸν ἐπὶ τὴν Πελοπόννησον στόλον ἐκπέμπων αὐτὸς οὐ συνεξέπλευσεν, ἀλλ’ ἔμεινεν οἰκουρῶν καὶ διὰ χειρὸς ἔχων τὴν πόλιν, ἕως ἀπηλλάγησαν οἱ Πελοποννήσιοι. θεραπεύων δὲ τοὺς πολλοὺς ὅμως ἀσχάλλοντας ἐπὶ τῷ πολέμῳ, διανομαῖς τε χρημάτων ἀνελάμβανε καὶ κληρουχίας ἔγραφεν· Αἰγινήτας γὰρ ἐξελάσας ἅπαντας διένειμε τὴν νῆσον Ἀθηναίων τοῖς λαχοῦσιν. ἦν δέ τις παρηγορία καὶ ἀφ’ ὧν ἔπασχον οἱ πολέμιοι. καὶ γὰρ οἱ περιπλέοντες τὴν Πελοπόννησον χώραν τε πολλὴν κώμας τε καὶ πόλεις μικρὰς διεπόρθησαν, καὶ κατὰ γῆν αὐτὸς ἐμβαλὼν εἰς τὴν Μεγαρικὴν ἔφθειρε πᾶσαν. ᾗ καὶ δῆλον ἦν ὅτι πολλὰ μὲν δρῶντες κατὰ γῆν κακὰ τοὺς Ἀθηναίους, πολλὰ δὲ πάσχοντες ὑπ’ ἐκείνων ἐκ θαλάττης, οὐκ ἂν εἰς μῆκος πολέμου τοσοῦτον προὔβησαν, ἀλλὰ ταχέως ἀπεῖπον, ὥσπερ ἐξ ἀρχῆς ὁ Περικλῆς προηγόρευσεν, εἰ μή τι δαιμόνιον ὑπηναντιώθη τοῖς ἀνθρωπίνοις λογισμοῖς.", "st": "Per. 34.1"}, {"sp": "N", "t": "νῦν δὲ πρῶτον μὲν ἡ λοιμώδης ἐνέπεσε φθορὰ καὶ κατενεμήθη τὴν ἀκμάζουσαν ἡλικίαν καὶ δύναμιν· ὑφ’ ἧς καὶ τὰ σώματα κακούμενοι καὶ τὰς ψυχὰς παντάπασιν ἠγριώθησαν πρὸς τὸν Περικλέα, καὶ καθάπερ ἰατρὸν ἢ πατέρα τῇ νόσῳ παραφρονήσαντες ἀδικεῖν ἐπεχείρησαν, ἀναπεισθέντες ὑπὸ τῶν ἐχθρῶν ὡς τὴν μὲν νόσον ἡ τοῦ χωριτικοῦ πλήθους εἰς τὸ ἄστυ συμφόρησις ἀπεργάζεται, θέρους ὥρᾳ πολλῶν ὁμοῦ χύδην ἐν οἰκήμασι μικροῖς καὶ σκηνώμασι πνιγηροῖς ἠναγκασμένων διαιτᾶσθαι δίαιταν οἰκουρὸν καὶ ἀργὴν ἀντὶ καθαρᾶς καὶ ἀναπεπταμένης τῆς πρότερον, τούτου δ’ αἴτιος ὁ τῷ πολέμῳ τὸν ἀπὸ τῆς χώρας ὄχλον εἰς τὰ τείχη καταχεάμενος καὶ πρὸς οὐδὲν ἀνθρώποις τοσούτοις χρώμενος, ἀλλ’ ἐῶν ὥσπερ βοσκήματα καθειργμένους ἀναπίμπλασθαι φθορᾶς ἀπ’ ἀλλήλων, καὶ μηδεμίαν μεταβολὴν μηδ’ ἀναψυχὴν ἐκπορίζων.", "st": "Per. 34.3"}, {"sp": "N", "t": "ταῦτα βουλόμενος ἰᾶσθαι καί τι παραλυπεῖν τοὺς πολεμίους, ἑκατὸν καὶ πεντήκοντα ναῦς ἐπλήρου, καὶ πολλοὺς καὶ ἀγαθοὺς ὁπλίτας καὶ ἱππέας ἀναβιβασάμενος ἔμελλεν ἀνάγεσθαι, μεγάλην ἐλπίδα τοῖς πολίταις καὶ φόβον οὐκ ἐλάττω τοῖς πολεμίοις ἀπὸ τοσαύτης ἰσχύος παρασχών. ἤδη δὲ πεπληρωμένων τῶν νεῶν καὶ τοῦ Περικλέους ἀναβεβηκότος ἐπὶ τὴν ἑαυτοῦ τριήρη τὸν μὲν ἥλιον ἐκλιπεῖν συνέβη καὶ γενέσθαι σκότος, ἐκπλαγῆναι δὲ πάντας ὡς πρὸς μέγα σημεῖον. ὁρῶν οὖν ὁ Περικλῆς περίφοβον τὸν κυβερνήτην καὶ διηπορημένον, ἀνέσχε τὴν χλαμύδα πρὸ τῶν ὄψεων αὐτοῦ, καὶ παρακαλύψας ἠρώτησε μή τι δεινὸν ἢ δεινοῦ τινος οἴεται σημεῖον· ὡς δ’ οὐκ ἔφη, τί οὖν, εἶπεν, ἐκεῖνο τούτου διαφέρει, πλὴν ὅτι μεῖζόν τι τῆς χλαμύδος ἐστὶ τὸ πεποιηκὸς τὴν ἐπισκότησιν; ταῦτα μὲν οὖν ἐν ταῖς σχολαῖς λέγεται τῶν φιλοσόφων.", "st": "Per. 35.1"}, {"sp": "N", "t": "ἐκπλεύσας δ’ οὖν ὁ Περικλῆς οὔτ’ ἄλλο τι δοκεῖ τῆς παρασκευῆς ἄξιον δρᾶσαι, πολιορκήσας τε τὴν ἱερὰν Ἐπίδαυρον ἐλπίδα παρασχοῦσαν ὡς ἁλωσομένην ἀπέτυχε διὰ τὴν νόσον. ἐπιγενομένη γὰρ οὐκ αὐτοὺς μόνον, ἀλλὰ καὶ τοὺς ὁπωσοῦν τῇ στρατιᾷ συμμίξαντας προσδιέφθειρεν. ἐκ τούτου χαλεπῶς διακειμένους τοὺς Ἀθηναίους πρὸς αὐτὸν ἐπειρᾶτο παρηγορεῖν καὶ ἀναθαρρύνειν. οὐ μὴν παρέλυσε τὴν ὀργὴν οὐδὲ μετέπεισε πρότερον ἢ τὰς ψήφους λαβόντας ἐπ’ αὐτὸν εἰς τὰς χεῖρας καὶ γενομένους κυρίους ἀφελέσθαι τὴν στρατηγίαν καὶ ζημιῶσαι χρήμασιν, ὧν ἀριθμὸν οἱ τὸν ἐλάχιστον πεντεκαίδεκα τάλαντα, πεντήκοντα δ’ οἱ τὸν πλεῖστον γράφουσιν. ἐπεγράφη δὲ τῇ δίκῃ κατήγορος, ὡς μὲν Ἰδομενεὺς λέγει, Κλέων, ὡς δὲ Θεόφραστος, Σιμμίας· ὁ δὲ Ποντικὸς Ἡρακλείδης Λακρατίδαν εἴρηκε.", "st": "Per. 35.3"}, {"sp": "N", "t": "τὰ μὲν οὖν δημόσια ταχέως ἔμελλε παύσεσθαι, καθάπερ κέντρον εἰς τοῦτον ἅμα πληγῇ τὸν θυμὸν ἀφεικότων τῶν πολλῶν· τὰ δ’ οἰκεῖα μοχθηρῶς εἶχεν αὐτῷ κατά τε τὸν λοιμὸν οὐκ ὀλίγους ἀποβαλόντι τῶν ἐπιτηδείων καὶ στάσει διατεταραγμένα πόρρωθεν. ὁ γὰρ πρεσβύτατος αὐτοῦ τῶν γνησίων υἱῶν Ξάνθιππος φύσει τε δαπανηρὸς ὢν καὶ γυναικὶ νέᾳ καὶ πολυτελεῖ συνοικῶν, Τισάνδρου θυγατρὶ τοῦ Ἐπιλύκου, χαλεπῶς ἔφερε τὴν τοῦ πατρὸς ἀκρίβειαν γλίσχρα καὶ κατὰ μικρὸν αὐτῷ χορηγοῦντος. πέμψας οὖν πρός τινα τῶν φίλων ἔλαβεν ἀργύριον ὡς τοῦ Περικλέους κελεύσαντος. ἐκείνου δ’ ὕστερον ἀπαιτοῦντος, ὁ μὲν Περικλῆς καὶ δίκην αὐτῷ προσέλαχε, τὸ δὲ μειράκιον ὁ Ξάνθιππος ἐπὶ τούτῳ χαλεπῶς διατεθεὶς ἐλοιδόρει τὸν πατέρα, πρῶτον μὲν ἐκφέρων ἐπὶ γέλωτι τὰς οἴκοι διατριβὰς αὐτοῦ καὶ τοὺς λόγους οὓς ἐποιεῖτο μετὰ τῶν σοφιστῶν. πεντάθλου γάρ τινος ἀκοντίῳ πατάξαντος Ἐπίτιμον τὸν Φαρσάλιον ἀκουσίως καὶ κατακτείναντος, ἡμέραν ὅλην ἀναλῶσαι μετὰ Πρωταγόρου διαποροῦντα πότερον τὸ ἀκόντιον ἢ τὸν βαλόντα μᾶλλον ἢ τοὺς ἀγωνοθέτας κατὰ τὸν ὀρθότατον λόγον αἰτίους χρὴ τοῦ πάθους ἡγεῖσθαι. πρὸς δὲ τούτοις καὶ τὴν περὶ τῆς γυναικὸς διαβολὴν ὑπὸ τοῦ Ξανθίππου φησὶν ὁ Στησίμβροτος εἰς τοὺς πολλοὺς διασπαρῆναι, καὶ ὅλως ἀνήκεστον ἄχρι τῆς τελευτῆς τῷ νεανίσκῳ πρὸς τὸν πατέρα παραμεῖναι τὴν διαφοράν· ἀπέθανε γὰρ ὁ Ξάνθιππος ἐν τῷ λοιμῷ νοσήσας.", "st": "Per. 36.1"}, {"sp": "N", "t": "ἀπέβαλε δὲ καὶ τὴν ἀδελφὴν ὁ Περικλῆς τότε καὶ τῶν κηδεστῶν καὶ φίλων τοὺς πλείστους καὶ χρησιμωτάτους πρὸς τὴν πολιτείαν. οὐ μὴν ἀπεῖπεν οὐδὲ προὔδωκε τὸ φρόνημα καὶ τὸ μέγεθος τῆς ψυχῆς ὑπὸ τῶν συμφορῶν, ἀλλ’ οὐδὲ κλαίων οὐδὲ κηδεύων οὐδὲ πρὸς τάφῳ τινὸς ὤφθη τῶν ἀναγκαίων, πρίν γε δὴ καὶ τὸν περίλοιπον αὑτοῦ τῶν γνησίων υἱῶν ἀποβαλεῖν Πάραλον. ἐπὶ τούτῳ δὲ καμφθεὶς ἐπειρᾶτο μὲν ἐγκαρτερεῖν τῷ ἤθει καὶ διαφυλάττειν τὸ μεγαλόψυχον, ἐπιφέρων δὲ τῷ νεκρῷ στέφανον ἡττήθη τοῦ πάθους πρὸς τὴν ὄψιν, ὥστε κλαυθμόν τε ῥῆξαι καὶ πλῆθος ἐκχέαι δακρύων, οὐδέποτε τοιοῦτον οὐδὲν ἐν τῷ λοιπῷ βίῳ πεποιηκώς.", "st": "Per. 36.4"}, {"sp": "N", "t": "τῆς δὲ πόλεως πειρωμένης τῶν ἄλλων στρατηγῶν εἰς τὸν πόλεμον καὶ ῥητόρων, ὡς δ’ οὐδεὶς βάρος ἔχων ἰσόρροπον οὐδ’ ἀξίωμα πρὸς τοσαύτην ἐχέγγυον ἡγεμονίαν ἐφαίνετο, ποθούσης ἐκεῖνον καὶ καλούσης ἐπὶ τὸ βῆμα καὶ τὸ στρατήγιον, ἀθυμῶν καὶ κείμενος οἴκοι διὰ τὸ πένθος ὑπ’ Ἀλκιβιάδου καὶ τῶν ἄλλων ἐπείσθη φίλων προελθεῖν. ἀπολογησαμένου δὲ τοῦ δήμου τὴν ἀγνωμοσύνην πρὸς αὐτόν, ὑποδεξάμενος αὖθις τὰ πράγματα καὶ στρατηγὸς αἱρεθεὶς ᾐτήσατο λυθῆναι τὸν περὶ τῶν νόθων νόμον, ὃν αὐτὸς εἰσενηνόχει πρότερον, ὡς μὴ παντάπασιν ἐρημίᾳ διαδοχῆς τὸν οἶκον ἐκλίποι τοὔνομα καὶ τὸ γένος.", "st": "Per. 37.1"}, {"sp": "N", "t": "εἶχε δ’ οὕτω τὰ περὶ τὸν νόμον. ἀκμάζων ὁ Περικλῆς ἐν τῇ πολιτείᾳ πρὸ πάνυ πολλῶν χρόνων, καὶ παῖδας ἔχων, ὥσπερ εἴρηται, γνησίους, νόμον ἔγραψε μόνους Ἀθηναίους εἶναι τοὺς ἐκ δυεῖν Ἀθηναίων γεγονότας. ἐπεὶ δὲ τοῦ βασιλέως τῶν Αἰγυπτίων δωρεὰν τῷ δήμῳ πέμψαντος τετρακισμυρίους πυρῶν μεδίμνους ἔδει διανέμεσθαι τοὺς πολίτας, πολλαὶ μὲν ἀνεφύοντο δίκαι τοῖς νόθοις ἐκ τοῦ γράμματος ἐκείνου τέως διαλανθάνουσι καὶ παρορωμένοις, πολλοὶ δὲ καὶ συκοφαντήμασι περιέπιπτον. ἐπράθησαν δ’ οὖν ἁλόντες ὀλίγῳ πεντακισχιλίων ἐλάττους, οἱ δὲ μείναντες ἐν τῇ πολιτείᾳ καὶ κριθέντες Ἀθηναῖοι μύριοι καὶ τετρακισχίλιοι καὶ τεσσαράκοντα τὸ πλῆθος ἐξητάσθησαν. ὄντος οὖν δεινοῦ τὸν κατὰ τοσούτων ἰσχύσαντα νόμον ὑπ’ αὐτοῦ πάλιν λυθῆναι τοῦ γράψαντος, ἡ παροῦσα δυστυχία τῷ Περικλεῖ περὶ τὸν οἶκον, ὡς δίκην τινὰ δεδωκότι τῆς ὑπεροψίας καὶ τῆς μεγαλαυχίας ἐκείνης, ἐπέκλασε τοὺς Ἀθηναίους, καὶ δόξαντες αὐτὸν νεμεσητά τε παθεῖν ἀνθρωπίνων τε δεῖσθαι συνεχώρησαν ἀπογράψασθαι τὸν νόθον εἰς τοὺς φράτορας, ὄνομα θέμενον τὸ αὑτοῦ. καὶ τοῦτον μὲν ὕστερον ἐν Ἀργινούσαις καταναυμαχήσαντα Πελοποννησίους ἀπέκτεινεν ὁ δῆμος μετὰ τῶν συστρατήγων.", "st": "Per. 37.3"}, {"sp": "N", "t": "τότε δὲ τοῦ Περικλέους ἔοικεν ὁ λοιμὸς λαβέσθαι λαβὴν οὐκ ὀξεῖαν, ὥσπερ ἄλλων, οὐδὲ σύντονον, ἀλλὰ βληχρᾷ τινι νόσῳ καὶ μῆκος ἐν ποικίλαις ἐχούσῃ μεταβολαῖς διαχρωμένην τὸ σῶμα σχολαίως καὶ ὑπερείπουσαν τὸ φρόνημα τῆς ψυχῆς. ὁ γοῦν Θεόφραστος ἐν τοῖς Ἠθικοῖς διαπορήσας εἰ πρὸς τὰς τύχας τρέπεται τὰ ἤθη καὶ κινούμενα τοῖς τῶν σωμάτων πάθεσιν ἐξίσταται τῆς ἀρετῆς, ἱστόρηκεν ὅτι νοσῶν ὁ Περικλῆς ἐπισκοπουμένῳ τινὶ τῶν φίλων δείξειε περίαπτον ὑπὸ τῶν γυναικῶν τῷ τραχήλῳ περιηρτημένον, ὡς σφόδρα κακῶς ἔχων ὁπότε καὶ ταύτην ὑπομένοι τὴν ἀβελτερίαν.", "st": "Per. 38.1"}, {"sp": "N", "t": "ἤδη δὲ πρὸς τῷ τελευτᾶν ὄντος αὐτοῦ, περικαθήμενοι τῶν πολιτῶν οἱ βέλτιστοι καὶ τῶν φίλων οἱ περιόντες λόγον ἐποιοῦντο τῆς ἀρετῆς καὶ τῆς δυνάμεως, ὅση γένοιτο, καὶ τὰς πράξεις ἀνεμετροῦντο καὶ τῶν τροπαίων τὸ πλῆθος· ἐννέα γὰρ ἦν ἃ στρατηγῶν καὶ νικῶν ἔστησεν ὑπὲρ τῆς πόλεως. ταῦτα, ὡς οὐκέτι συνιέντος, ἀλλὰ καθῃρημένου τὴν αἴσθησιν αὐτοῦ, διελέγοντο πρὸς ἀλλήλους· ὁ δὲ πᾶσιν ἐτύγχανε τὸν νοῦν προσεσχηκώς, καὶ φθεγξάμενος εἰς μέσον ἔφη θαυμάζειν ὅτι ταῦτα μὲν ἐπαινοῦσιν αὐτοῦ καὶ μνημονεύουσιν, ἃ καὶ πρὸς τύχην ἐστὶ κοινὰ καὶ γέγονεν ἤδη πολλοῖς στρατηγοῖς, τὸ δὲ κάλλιστον καὶ μέγιστον οὐ λέγουσιν. οὐδεὶς γάρ, ἔφη, δι’ ἐμὲ τῶν ὄντων Ἀθηναίων μέλαν ἱμάτιον περιεβάλετο.", "st": "Per. 38.3"}, {"sp": "N", "t": "θαυμαστὸς οὖν ὁ ἀνὴρ οὐ μόνον τῆς ἐπιεικείας καὶ πρᾳότητος, ἣν ἐν πράγμασι πολλοῖς καὶ μεγάλαις ἀπεχθείαις διετήρησεν, ἀλλὰ καὶ τοῦ φρονήματος, εἰ τῶν αὑτοῦ καλῶν ἡγεῖτο βέλτιστον εἶναι τὸ μήτε φθόνῳ μήτε θυμῷ χαρίσασθαι μηδὲν ἀπὸ τηλικαύτης δυνάμεως, μηδὲ χρήσασθαί τινι τῶν ἐχθρῶν ὡς ἀνηκέστῳ. καί μοι δοκεῖ τὴν μειρακιώδη καὶ σοβαρὰν ἐκείνην προσωνυμίαν ἓν τοῦτο ποιεῖν ἀνεπίφθονον καὶ πρέπουσαν, οὕτως εὐμενὲς ἦθος καὶ βίον ἐν ἐξουσίᾳ καθαρὸν καὶ ἀμίαντον Ὀλύμπιον προσαγορεύεσθαι, καθάπερ τὸ τῶν θεῶν γένος ἀξιοῦμεν αἴτιον μὲν ἀγαθῶν, ἀναίτιον δὲ κακῶν πεφυκὸς ἄρχειν καὶ βασιλεύειν τῶν ὄντων, οὐχ ὥσπερ οἱ ποιηταὶ συνταράττοντες ἡμᾶς ἀμαθεστάταις δόξαις ἁλίσκονται τοῖς αὑτῶν μυθεύμασι, τὸν μὲν τόπον, ἐν ᾧ τοὺς θεοὺς κατοικεῖν λέγουσιν, ἀσφαλὲς ἕδος καὶ ἀσάλευτον καλοῦντες, οὐ πνεύμασιν, οὐ νέφεσι χρώμενον, ἀλλ’ αἴθρᾳ μαλακῇ καὶ φωτὶ καθαρωτάτῳ τὸν ἅπαντα χρόνον ὁμαλῶς περιλαμπόμενον, ὡς τοιαύτης τινὸς τῷ μακαρίῳ καὶ ἀθανάτῳ διαγωγῆς μάλιστα πρεπούσης, αὐτοὺς δὲ τοὺς θεοὺς ταραχῆς καὶ δυσμενείας καὶ ὀργῆς ἄλλων τε μεστοὺς παθῶν ἀποφαίνοντες οὐδ’ ἀνθρώποις νοῦν ἔχουσι προσηκόντων. ἀλλὰ ταῦτα μὲν ἴσως ἑτέρας δόξει πραγματείας εἶναι.", "st": "Per. 39.1"}, {"sp": "N", "t": "τοῦ δὲ Περικλέους ταχεῖαν αἴσθησιν καὶ σαφῆ πόθον Ἀθηναίοις ἐνειργάζετο τὰ πράγματα. καὶ γὰρ οἱ ζῶντος βαρυνόμενοι τὴν δύναμιν ὡς ἀμαυροῦσαν αὐτούς, εὐθὺς ἐκ ποδῶν γενομένου πειρώμενοι ῥητόρων καὶ δημαγωγῶν ἑτέρων ἀνωμολογοῦντο μετριώτερον ἐν ὄγκῳ καὶ σεμνότερον ἐν πρᾳότητι μὴ φῦναι τρόπον· ἡ δ’ ἐπίφθονος ἰσχὺς ἐκείνη, μοναρχία λεγομένη καὶ τυραννὶς πρότερον, ἐφάνη τότε σωτήριον ἔρυμα τῆς πολιτείας γενομένη· τοσαύτη φθορὰ καὶ πλῆθος ἐπέκειτο κακίας τοῖς πράγμασιν, ἣν ἐκεῖνος ἀσθενῆ καὶ ταπεινὴν ποιῶν ἀπέκρυπτε καὶ κατεκώλυεν ἀνήκεστον ἐν ἐξουσίᾳ γενέσθαι.", "st": "Per. 39.4"}, {"sp": "HDR", "t": "Φάβιος Μάξιμος"}, {"sp": "N", "t": "τοιούτου δὲ τοῦ Περικλέους ἐν τοῖς ἀξίοις μνήμης γεγονότος, ὡς παρειλήφαμεν, ἐπὶ τὸν Φάβιον τὴν ἱστορίαν μεταγάγωμεν. νυμφῶν μιᾶς λέγουσιν, οἱ δὲ γυναικὸς ἐπιχωρίας, Ἡρακλεῖ μιγείσης περὶ τὸν Θύμβριν ποταμὸν γενέσθαι Φάβιον, ἄνδρα πολὺ καὶ δόκιμον ἐν Ῥώμῃ τὸ Φαβίων γένος ἀφ’ αὐτοῦ παρασχόντα, τινὲς δὲ τοὺς ἀπὸ τοῦ γένους τούτου πρώτους τῇ δι’ ὀρυγμάτων χρησαμένους ἄγρᾳ Φοδίους ἱστοροῦσιν ὀνομάζεσθαι τὸ παλαιόν οὕτω γὰρ ἄχρι νῦν αἱ διώρυχες φόσσαι καὶ φόδερε τὸ σκάψαι καλεῖται· χρόνῳ δὲ τῶν δυεῖν φθόγγων μεταπεσόντων Φάβιοι προσηγορεύθησαν. πολλοὺς δὲ καὶ μεγάλους τῆς οἰκίας ἐξενεγκαμένης ἄνδρας, ἀπὸ Ῥούλλου τοῦ μεγίστου καὶ διὰ τοῦτο Μαξίμου παρὰ Ῥωμαίοις ἐπονομασθέντος τέταρτος ἦν Φάβιος Μάξιμος, περὶ οὗ τάδε γράφομεν.", "st": "Fab. 1.1"}, {"sp": "N", "t": "ἦν δ’ αὐτῷ σωματικὸν μὲν παρωνύμιον ὁ Βερρούκωσος· εἶχε γὰρ ἀκροχορδόνα μικρὰν ἐπάνω τοῦ χείλους ἐπιπεφυκυῖαν ὁ δὲ Ὀουικούλας σημαίνει μὲν τὸ προβάτων, ἐτέθη δὲ πρὸς τὴν πρᾳότητα καὶ βαρύτητα τοῦ ἤθους ἔτι παιδὸς ὄντος. τὸ γὰρ ἡσύχιον αὐτοῦ καὶ σιωπηλὸν καὶ μετὰ πολλῆς εὐλαβείας τῶν παιδικῶν ἁπτόμενον ἡδονῶν, βραδέως δὲ καὶ διαπόνως δεχόμενον τὰς μαθήσεις, εὔκολον δὲ πρὸς τοὺς συνήθεις καὶ κατήκοον ἀβελτερίας τινὸς καὶ νωθρότητος ὑπόνοιαν εἶχε παρὰ τοῖς ἐκτός· ὀλίγοι δ’ ἦσαν οἱ τὸ δυσκίνητον ὑπὸ βάθους καὶ τὸ μεγαλόψυχον καὶ λεοντῶδες ἐν τῇ φύσει καθορῶντες αὐτοῦ. ταχὺ δὲ τοῦ χρόνου προϊόντος ὑπὸ τῶν πραγμάτων ἐγειρόμενος διεσήμαινε καὶ τοῖς πολλοῖς ἀπάθειαν μὲν οὖσαν τὴν δοκοῦσαν ἀπραγίαν, εὐβουλίαν δὲ τὴν εὐλάβειαν, τὸ δὲ πρὸς μηδὲν ὀξὺ μηδ’ εὐκίνητον ἐν πᾶσι μόνιμον καὶ βέβαιον, ὁρῶν δὲ καὶ τῆς πολιτείας τὸ μέγεθος καὶ τῶν πολέμων τὸ πλῆθος, ἤσκει τὸ μὲν σῶμα πρὸς τοὺς πολέμους, ὥσπερ ὅπλον σύμφυτον, τὸν δὲ λόγον ὄργανον πειθοῦς πρὸς τὸν δῆμον, εὖ μάλα πρεπόντως τῷ βίῳ κατακεκοσμημένον. οὐ γὰρ ἐπῆν ὡραϊσμὸς οὐδὲ κενὴ καὶ ἀγοραῖος χάρις, ἀλλὰ νοῦς ἴδιον καὶ περιττὸν ἐν γνωμολογίαις σχῆμα καὶ βάθος ἔχων, ἃς μάλιστα ταῖς Θουκυδίδου προσεοικέναι λέγουσι. διασῴζεται γὰρ αὐτοῦ λόγος, ὃν εἶπεν ἐν τῷ δήμῳ, τοῦ παιδὸς αὐτοῦ μεθ’ ὑπατείαν ἀποθανόντος ἐγκώμιον.", "st": "Fab. 1.3"}, {"sp": "N", "t": "πέντε δ’ ὑπατειῶν ἃς ὑπάτευσεν, ἡ πρώτη τὸν ἀπὸ Λιγύων θρίαμβον ἔσχεν, ἡττηθέντες γὰρ ὑπ’ αὐτοῦ μάχῃ καὶ πολλοὺς ἀποβαλόντες εἰς τὰς Ἄλπεις ἀνεστάλησαν, καὶ τὴν πρόσοικον ἐπαύσαντο τῆς Ἰταλίας ληϊζόμενοι καὶ κακῶς ποιοῦντες. ἐπεὶ δ’ Ἀννίβας ἐμβαλὼν εἰς Ἰταλίαν καὶ μάχῃ πρῶτον περὶ τὸν Τρεβίαν ποταμὸν ἐπικρατήσας αὐτὸς μὲν ἤλαυνε διὰ Τυρρηνίας πορθῶν τὴν χώραν, ἔκπληξιν δὲ δεινὴν καὶ φόβον εἰς τὴν Ῥώμην ἐνέβαλλε, σημεῖα δὲ τὰ μὲν συνήθη Ῥωμαίοις ἀπὸ κεραυνῶν, τὰ δ’ ὅλως ἐξηλλαγμένα καὶ πολλὴν ἀτοπίαν ἔχοντα προσέπιπτε (θυρεούς τε γὰρ ἀφ’ αὑτῶν αἵματι γενέσθαι διαβρόχους ἐλέχθη, καὶ θέρη σταχύων περὶ Ἄντιον ἔναιμα κείρεσθαι, καὶ λίθους μὲν ἐκ τοῦ ἀέρος διαπύρους καὶ φλεγομένους φέρεσθαι, τοῦ δ’ ὑπὲρ Φαλερίους οὐρανοῦ ῥαγῆναι δόξαντος ἐκπίπτειν καὶ διασπείρεσθαι πολλὰ γραμματεῖα, καὶ τούτων ἐν ἑνὶ γεγραμμένον φανῆναι κατὰ λέξιν Ἄρης τὰ ἑαυτοῦ ὅπλα σαλεύει), τὸν μὲν ὕπατον Γάιον Φλαμίνιον οὐδὲν ἤμβλυνε τούτων, ἄνδρα πρὸς τῷ φύσει θυμοειδεῖ καὶ φιλοτίμῳ μεγάλαις ἐπαιρόμενον εὐτυχίαις, ἃς πρόσθεν εὐτύχησε παραλόγως, τῆς τε βουλῆς ἀπᾳδούσης καὶ τοῦ συνάρχοντος ἐνισταμένου βίᾳ συμβαλὼν τοῖς Γαλάταις καὶ κρατήσας, Φάβιον δὲ τὰ μὲν σημεῖα, καίπερ ἁπτόμενα πολλῶν, ἧττον ὑπέθραττε διὰ τὴν ἀλογίαν· τὴν δ’ ὀλιγότητα τῶν πολεμίων καὶ τὴν ἀχρηματίαν πυνθανόμενος καρτερεῖν παρεκάλει τοὺς Ῥωμαίους καὶ μὴ μάχεσθαι πρὸς ἄνθρωπον ἐπ’ αὐτῷ τούτῳ διὰ πολλῶν ἀγώνων ἠσκημένῃ στρατιᾷ χρώμενον, ἀλλὰ τοῖς συμμάχοις ἐπιπέμποντας βοηθείας καὶ τὰς πόλεις διὰ χειρὸς ἔχοντας αὐτὴν ἐᾶν περὶ αὑτῇ μαραίνεσθαι τὴν ἀκμὴν τοῦ Ἀννίβου, καθάπερ φλόγα λάμψασαν ἀπὸ μικρᾶς καὶ κούφης δυνάμεως.", "st": "Fab. 2.1"}, {"sp": "N", "t": "οὐ μὴν ἔπεισε τὸν Φλαμίνιον, ἀλλὰ φήσας οὐκ ἀνέξεσθαι προσιόντα τῇ Ῥώμῃ τὸν πόλεμον οὐδ’, ὥσπερ ὁ παλαιὸς Κάμιλλος, ἐν τῇ πόλει διαμαχεῖσθαι περὶ αὐτῆς, τὸν μὲν στρατὸν ἐξάγειν ἐκέλευσε τοὺς χιλιάρχους, αὐτὸς ἐπὶ τὸν ἵππον ἀλλόμενος ἐξ οὐδενὸς αἰτίου προδήλου παραλόγως ἐντρόμου τοῦ ἵππου γενομένου καὶ πτυρέντος ἐξέπεσε καὶ κατενεχθεὶς ἐπὶ κεφαλὴν ὅμως οὐδὲν ἔτρεψε τῆς γνώμης, ἀλλ’ ὡς ὥρμησεν ἐξ ἀρχῆς ἀπαντῆσαι τῷ Ἀννίβᾳ, περὶ τὴν καλουμένην Θρασυμένην λίμνην τῆς Τυρρηνίας παρετάξατο.", "st": "Fab. 3.1"}, {"sp": "N", "t": "τῶν δὲ στρατιωτῶν συμβαλόντων εἰς χεῖρας ἅμα τῷ καιρῷ τῆς μάχης συνέπεσε σεισμός, ὑφ’ οὗ καὶ πόλεις ἀνετράπησαν καὶ ῥεύματα ποταμῶν ἐξ ἕδρας μετέστη καὶ κρημνῶν ὑπώρειαι περιρράγησαν. ἀλλὰ, καίπερ οὕτω γενομένου βιαίου τοῦ πάθους οὐδεὶς τὸ παράπαν ᾔσθετο τῶν μαχομένων, αὐτὸς μὲν οὖν ὁ Φλαμίνιος πολλὰ καὶ τόλμης ἔργα καὶ ῥώμης ἐπιδεικνύμενος ἔπεσε, καὶ περὶ αὐτὸν οἱ κράτιστοι· τῶν δ’ ἄλλων τραπέντων πολὺς ἦν φόνος, καὶ πεντακισχίλιοι πρὸς μυρίοις κατεκόπησαν, καὶ ἑάλωσαν ἕτεροι τοσοῦτοι, τὸ δὲ Φλαμινίου σῶμα φιλοτιμούμενος θάψαι καὶ κοσμῆσαι δι’ ἀρετὴν ὁ Ἀννίβας οὐχ εὗρεν ἐν τοῖς νεκροῖς, ἀλλ’ ἠγνοεῖτο τὸ παράπαν ὅπως ἠφανίσθη.", "st": "Fab. 3.2"}, {"sp": "N", "t": "τὴν μὲν οὖν ἐπὶ τοῦ Τρεβίου γενομένην ἧτταν οὔθ’ ὁ γράψας στρατηγὸς οὔθ’ ὁ πεμφθεὶς ἄγγελος ἀπ’ εὐθείας ἔφρασεν, ἀλλ’ ἐψεύσατο τὴν νίκην ἐπίδικον αὐτοῖς καὶ ἀμφίδοξον γενέσθαι· περὶ δὲ ταύτης ὡς πρῶτον ἤκουσεν ὁ στρατηγὸς Πομπώνιος, συναγαγὼν εἰς ἐκκλησίαν τὸν δῆμον οὐ περιπλοκὰς οὐδὲ παραγωγὰς ἀλλ’ ἄντικρυς ἔφη προσελθών Νενικήμεθα, ὦ ἄνδρες Ῥωμαῖοι, μεγάλῃ μάχῃ, καὶ διέφθαρται τὸ στρατόπεδον, καὶ Φλαμίνιος ὕπατος ἀπόλωλεν. ἀλλὰ βουλεύεσθε περὶ σωτηρίας αὑτῶν καὶ ἀσφαλείας. οὗτος μὲν οὖν ὥσπερ πνεῦμα τὸν λόγον ἐμβαλὼν εἰς πέλαγος τοσούτου δῆμου συνετάραξε τὴν πόλιν, οὐδ’ ἑστάναι πρὸς τοσαύτην ἔκπληξιν οἱ λογισμοὶ καὶ διαμένειν ἐδύναντο. πάντες δ’ εἰς μίαν γνώμην συνήχθησαν ἀνυπευθύνου δεῖσθαι τὰ πράγματα μοναρχίας, ἣν δικτατορίαν καλοῦσι, καὶ τοῦ μεταχειριουμένου ταύτην ἀθρύπτως καὶ ἀδεῶς ἀνδρός· εἶναι δὲ τοῦτον ἕνα Φάβιον Μάξιμον, ἰσόρροπον ἔχοντα, τῷ μεγέθει τῆς ἀρχῆς τὸ φρόνημα καὶ τὸ ἀξίωμα τοῦ ἤθους, ἡλικίας τε κατὰ τοῦτο γεγενημένον ἐν ᾧ συνέστηκεν ἔτι πρὸς τὰ τῆς ψυχῆς βουλεύματα τὸ σῶμα τῇ ῥώμῃ καὶ συγκέκραται τῷ φρονίμῳ τὸ θαρραλέον.", "st": "Fab. 3.4"}, {"sp": "N", "t": "ὡς οὖν ταῦτ’ ἔδοξεν, ἀποδειχθεὶς δικτάτωρ Φάβιος, καὶ ἀποδείξας αὐτὸς ἵππαρχον Μᾶρκον Μινούκιον, πρῶτον μὲν ᾐτήσατο τὴν σύγκλητον ἵππῳ χρῆσθαι παρὰ τάς στρατείας. οὐ γὰρ ἐξῆν, ἀλλ’ ἀπηγόρευτο κατὰ δή τινα νόμον παλαιόν, εἴτε τῆς ἀλκῆς τὸ πλεῖστον ἐν τῷ πεζῷ τιθεμένων καὶ διὰ τοῦτο τὸν στρατηγὸν οἰομένων δεῖν παραμένειν τῇ φάλαγγι καὶ μὴ προλείπειν, εἴθ’, ὅτι τυραννικὸν εἰς ἅπαντα τἆλλα καὶ μέγα τὸ τῆς ἀρχῆς κράτος ἐστίν, ἔν γε τούτῳ βουλομένων τὸν δικτάτορα τοῦ δήμου φαίνεσθαι δεόμενον. οὐ μὴν ἀλλὰ καὶ αὐτὸς ὁ Φάβιος εὐθὺς ἐνδείξασθαι θέλων τῆς ἀρχῆς τὸ μέγεθος καὶ τὸν ὄγκον, ὡς μᾶλλον ὑπηκόοις χρῷτο καὶ πειθηνίοις τοῖς πολίταις, προῆλθε συνενεγκάμενος εἰς ταὐτὸ ῥαβδουχίας εἰκοσιτέσσαρας· καὶ τοῦ ἑτέρου τῶν ὑπάτων ἀπαντῶντος αὐτῷ τὸν ὑπηρέτην πέμψας ἐκέλευσε τοὺς ῥαβδούχους ἀπαλλάξαι καὶ τὰ παράσημα τῆς ἀρχῆς ἀποθέμενον ἰδιώτην ἀπαντᾶν.", "st": "Fab. 4.1"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα καλλίστην ἀρχόμενος ἐκ θεῶν ἀρχήν, καὶ διδάσκων τὸν δῆμον ὡς ὀλιγωρίᾳ καὶ περιφρονήσει τοῦ στρατηγοῦ πρὸς τὸ δαιμόνιον, οὐ μοχθηρίᾳ τῶν ἀγωνισαμένων σφαλέντα, προὔτρεπε μὴ δεδιέναι τοὺς ἐχθρούς, ἀλλὰ τοὺς θεοὺς ἐξευμενίζεσθαι καὶ τιμᾶν, οὐ δεισιδαιμονίαν ἐνεργαζόμενος, ἀλλὰ θαρρύνων εὐσεβείᾳ τὴν ἀρετὴν καὶ ταῖς παρὰ τῶν θεῶν ἐλπίσι τὸν ἀπὸ τῶν πολεμίων φόβον ἀφαιρῶν καὶ παραμυθούμενος. ἐκινήθησαν δὲ τότε πολλαὶ καὶ τῶν ἀπορρήτων καὶ χρησίμων αὐτοῖς βίβλων, ἃς Σιβυλλείους καλοῦσι· καὶ λέγεται συνδραμεῖν ἔνια τῶν ἀποκειμένων ἐν αὐταῖς λογίων πρὸς τάς τύχας καὶ τάς πράξεις ἐκείνας. καὶ τὸ μὲν γνωσθὲν οὐκ ἦν ἑτέρῳ πυθέσθαι· προελθὼν δὲ ὁ δικτάτωρ εἰς τὸν ὄχλον εὔξατο τοῖς θεοῖς ἐνιαυτοῦ μὲν αἰγῶν καὶ σνῶν καὶ προβάτων καὶ βοῶν ἐπιγονήν, ὅσην Ἰταλίας ὄρη καὶ πεδία καὶ ποταμοὶ καὶ λειμῶνες εἰς ὥραν ἐσομένην θρέψουσι, καταθύσειν ἅπαντα, θέας δὲ μουσικὰς καὶ θυμελικὰς ἄξειν ἀπὸ σηστερτίων τριακοσίων τριάκοντα τριῶν καὶ δηναρίων τριακοσίων τριάκοντα τριῶν ἔτι τριτημορίου προσόντος. τοῦτο τὸ κεφάλαιόν ἐστιν ὀκτὼ μυριάδες δραχμῶν καὶ δραχμαὶ τρισχίλιαι πεντακόσιαι ὀγδοήκοντα τρεῖς καὶ δύο ὀβολοί. λόγον δὲ τῆς εἰς τοῦτο τοῦ πλήθους ἀκριβείας καὶ διανομῆς χαλεπόν ἐστιν εἰπεῖν, εἰ μή τις ἄρα βούλοιτο τῆς τριάδος ὑμνεῖν τὴν δύναμιν, ὅτι καὶ φύσει τέλειος καὶ πρῶτος τῶν περιττῶν ἀρχή τε πλήθους ἐν αὑτῷ τάς τε πρώτας διαφορὰς καὶ τὰ παντὸς ἀριθμοῦ στοιχεῖα μίξας καὶ συναρμόσας εἰς ταὐτὸν ἀνείληφεν.", "st": "Fab. 4.3"}, {"sp": "N", "t": "τῶν μέν οὖν πολλῶν ὁ Φάβιος τὴν γνώμην ἀπαρτήσας εἰς τὸ θεῖον ἡδίω πρὸς τὸ μέλλον ἐποίησεν αὐτὸς δὲ πάσας θέμενος ἐν αὑτῷ τὰς τῆς νίκης ἐλπίδας, ὡς καὶ τοῦ θεοῦ τὰς εὐπραξίας δι’ ἀρετῆς καὶ φρονήσεως παραδιδόντος, τρέπεται πρὸς Ἀννίβαν, οὐχ ὡς διαμαχούμενος, ἀλλὰ χρόνῳ τὴν ἀκμὴν αὐτοῦ καὶ χρήμασι τὴν ἀπορίαν καὶ πολυανθρωπίᾳ τὴν ὀλιγότητα τρίβειν καὶ ὑπαναλίσκειν βεβουλευμένος. ὅθεν ἀεὶ μετέωρος ἀπὸ τῆς ἵππου τῶν πολεμίων ἐν τόποις ὀρεινοῖς στρατοπεδεύων ἐπῃωρεῖτο, καθημένου μέν ἡσυχάζων, κινουμένου δὲ κατὰ τῶν ἄκρων κύκλῳ περιιὼν καὶ περιφαινόμενος ἐκ διαστήματος ὅσον ἀκοντὶ μὴ βιασθῆναι μάχεσθαι καὶ φόβον ὡς μαχησόμενος τοῖς πολεμίοις ἀπὸ τῆς μελλήσεως αὐτῆς παρέχειν. οὕτω δὲ παράγων τὸν χρόνον ὑπὸ πάντων κατεφρονεῖτο, καὶ κακῶς μέν ἤκουεν ἐν τῷ στρατοπέδῳ, κομιδῇ δὲ τοῖς πολεμίοις ἄτολμος ἐδόκει καὶ τὸ μηδὲν εἶναι πλὴν ἑνὸς ἀνδρὸς Ἀννίβου. μόνος δ’ ἐκεῖνος αὐτοῦ τὴν δεινότητα, καὶ τὸν τρόπον ᾧ πολεμεῖν ἐγνώκει, συνιδών, καὶ διανοηθεὶς ὡς πάσῃ τέχνῃ καὶ βίᾳ κινητέος ἐστὶν εἰς μάχην ὁ ἀνὴρ ἢ διαπέπρακται τὰ Καρχηδονίων, οἷς μέν εἰσι κρείττους ὅπλοις χρήσασθαι μὴ δυναμένων, οἷς δὲ λείπονται σώμασι καὶ χρήμασιν ἐλαττουμένων καὶ δαπανωμένων εἰς τὸ μηδέν, ἐπὶ πᾶσαν ἰδέαν στρατηγικῶν σοφισμάτων καὶ παλαισμάτων τρεπόμενος, καὶ πειρώμενος ὥσπερ δεινὸς ἀθλητὴς λαβὴν ζητῶν, προσέβαλλε καὶ διετάραττε καὶ μετῆγε πολλαχόσε τὸν Φάβιον, ἐκστῆσαι τῶν ὑπὲρ τῆς ἀσφαλείας λογισμῶν βουλόμενος.", "st": "Fab. 5.1"}, {"sp": "N", "t": "τῷ δ’ ἡ μέν γνώμη πίστιν ἔχουσα τοῦ συμφέροντος ἐν ἑαυτῇ βέβαιος εἱστήκει καὶ ἀμετάπτωτος· ἠνώχλει δ’ αὐτὸν ὁ ἵππαρχος Μινούκιος φιλομαχῶν ἀκαίρως καὶ θρασυνόμενος καὶ δημαγωγῶν τὸ στράτευμα μανικῆς φορᾶς καὶ κενῶν ἐλπίδων ὑπ’ αὐτοῦ πεπληρωμένον οἳ τὸν μέν Φάβιον σκώπτοντες καὶ καταφρονοῦντες Ἀννίβου παιδαγωγὸν ἀπεκάλουν, τὸν δὲ Μινούκιον μέγαν ἄνδρα καὶ τῆς Ῥώμης ἄξιον ἡγοῦντο στρατηγόν· ὁ δὲ μᾶλλον εἰς φρόνημα καὶ θράσος ἀνειμένος ἐχλεύαζε μὲν τὰς ἐπὶ τῶν ἄκρων στρατοπεδείας, ὡς καλὰ θέατρα τοῦ δικτάτορος ἀεὶ παρασκευαζομένου θεωρήσουσι πορθουμένην καὶ φλεγομένην τὴν Ἰταλίαν, ἠρώτα δὲ τοὺς φίλους τοῦ Φαβίου πότερον εἰς τὸν οὐρανὸν ἄρας ἀναφέρει τὸν στρατὸν ὡς τῆς γῆς ἀπεγνωκώς, ἢ νέφη καὶ ὁμίχλας προβαλλόμενος ἀποδιδράσκει τοὺς πολεμίους. ταῦτα τῶν φίλων πρὸς τὸν Φάβιον ἀπαγγελλόντων καὶ τὴν ἀδοξίαν τῷ κινδύνῳ λῦσαι παραινούντων, οὕτω μέντἄν, ἔφη, δειλότερος ἢ νῦν εἶναι δοκῶ γενοίμην, εἰ σκώμματα καὶ λοιδορίας φοβηθεὶς ἐκπέσοιμι τῶν ἐμαυτοῦ λογισμῶν, καίτοι τὸ μέν ὑπὲρ πατρίδος οὐκ αἰσχρὸν δέος, ἡ δὲ πρὸς δόξαν ἀνθρώπων καὶ διαβολὰς καὶ ψόγους ἔκπληξις οὐκ ἀξίου τηλικαύτης ἀρχῆς ἀνδρός, ἀλλὰ δουλεύοντος ὧν κρατεῖν αὐτὸν καὶ δεσπόζειν κακῶς φρονούντων προσήκει.", "st": "Fab. 5.4"}, {"sp": "N", "t": "μετὰ ταῦτα γίνεται διαμαρτία τὸν Ἀννίβου. βουλόμενος γὰρ ἀποσπάσαι τὸν Φαβίου πορρωτέρω τὸ στράτευμα καὶ πεδίων ἐπιλαβέσθαι προνομὰς ἐχόντων, ἐκέλευσε τοὺς ὁδηγοὺς μετὰ δεῖπνον εὐθὺς ἡγεῖσθαι πρὸς τὸ Κασινάτον. οἱ δὲ τῆς φωνῆς διὰ βαρβαρισμὸν οὐκ ἐξακούσαντες ἀκριβῶς, ἐμβάλλουσιν αὐτοῦ τὴν δύναμιν φέροντες εἰς τὰ καταλήγοντα τῆς Καμπανίας εἰς πόλιν Κασιλῖνον, ἣν τέμνει ῥέων διὰ μέσης ποταμὸς, ὃν Οὐουλτοῦρνον οἱ Ῥωμαῖοι καλοῦσιν. ἔστι δ’ ἡ χώρα τὰ μὲν ἄλλα περιστεφὴς ὄρεσιν αὐλὼν δ’ ἀναπέπταται πρὸς τὴν θάλατταν, ἔνθα τὰ ἕλη καταδίδωσι τοῦ ποταμοῦ περιχεομένου, καὶ θῖνας ἄμμου βαθείας ἔχει, καὶ τελευτᾷ πρὸς αἰγιαλὸν κυματώδη καὶ δύσορμον. ἐνταῦθα καταβαίνοντος τοῦ Ἀννίβου περιελθὼν ἐμπειρίᾳ τῶν ὁδῶν ὁ Φάβιος τὴν μὲν διέξοδον ὁπλίτας τετρακισχιλίους ἐπιστήσας ἐνέφραξε, τὸν δ’ ἄλλον στρατὸν ὑπὲρ τῶν ἄλλων ἄκρων ἐν καλῷ καθίσας διὰ τῶν ἐλαφροτάτων καὶ προχειροτάτων ἐνέβαλε τοῖς ἐσχάτοις τῶν πολεμίων, καὶ συνετάραξεν ἅπαν τὸ στράτευμα, διέφθειρε δὲ περὶ ὀκτακοσίους. ἐκ τούτου βουλόμενος Ἀννίβας ἀπαγαγεῖν τὸ στράτευμα, καὶ τὴν διαμαρτίαν τοῦ τόπου νοήσας καὶ τὸν κίνδυνον, ἀνεσταύρωσε μὲν τοὺς ὁδηγούς, ἐκβιάζεσθαι δὲ τοὺς πολεμίους καὶ προσμάχεσθαι τῶν ὑπερβολῶν ἐγκρατεῖς ὄντας ἀπεγίνωσκε. δυσθύμως δὲ καὶ περιφόβως διακειμένων ἁπάντων, καὶ περιεστάναι σφᾶς πανταχόθεν ἀφύκτους ἡγουμένων ἀπορίας, ἔγνω δολοῦν ἀπάτῃ τοὺς πολεμίους, ἦν δὲ τοιόνδε.", "st": "Fab. 6.1"}, {"sp": "N", "t": "βοῦς ὅσον δισχιλίας ἐκ τῶν αἰχμαλώτων ἐκέλευσε συλλαβόντας ἀναδῆσαι δᾷδα πρὸς ἕκαστον κέρας ἢ λύγων ἢ φρυγάνων αὔων φάκελον· εἶτα νυκτὸς, ὅταν ἀρθῇ σημεῖον, ἀνάψαντας ἐλαύνειν ἐπὶ τὰς ὑπερβολὰς παρὰ τὰ στενὰ καὶ τὰς φυλακὰς τῶν πολεμίων, ἅμα δὲ ταῦτα παρεσκεύαζον οἷς προσετέτακτο, καὶ τὸν ἄλλον αὐτὸς ἀναστήσας στρατὸν ἤδη σκότους ὄντος ἦγε σχολαίως. αἱ δὲ βόες, ἄχρι μὲν τὸ πῦρ ὀλίγον ἦν καὶ περιέκαιε τὴν ὕλην, ἀτρέμα προσεχώρουν ἐλαυνόμεναι πρὸς τὴν ὑπώρειαν, καὶ θαῦμα τοῖς καθορῶσι νομεῦσιν ἀπὸ τῶν ἄκρων καὶ βουκόλοις ἦσαν αἱ φλόγες ἄκροις ἐπιλάμπουσαι τοῖς κέρασιν, ὡς στρατοπέδου καθ’ ἕνα κόσμον ὑπὸ λαμπάδων πολλῶν βαδίζοντος. ἐπεὶ δὲ πυρούμενον τὸ κέρας ἄχρι ῥίζης διέδωκε τῇ σαρκὶ τὴν αἴσθησιν, καὶ πρὸς τὸν πόνον διαφέρουσαι καὶ τινάσσουσαι τὰς κεφαλὰς ἀνεπίμπλαντο πολλῆς ἀπ’ ἀλλήλων φλογός, οὐκ ἐνέμειναν τῇ τάξει τῆς πορείας, ἀλλ’ ἔκφοβοι καὶ περιαλγεῖς οὖσαι δρόμῳ κατὰ τῶν ὀρῶν ἐφέροντο, λαμπόμεναι μὲν οὐρὰς ἄκρας καὶ μέτωπα, πολλὴν δὲ τῆς ὕλης, δι’ ἧς ἔφευγον, ἀνάπτουσαι. δεινὸν οὖν ἧς θέαμα τοῖς παραφυλάττουσι τὰς ὑπερβολὰς Ῥωμαίοις· καὶ γὰρ αἱ φλόγες ἐῴκεσαν ὑπ’ ἀνθρώπων θεόντων διαφερομέναις λαμπάσι, καὶ θόρυβος ἧς ἐν αὐτοῖς πολὺς καὶ φόβος, ἀλλαχόθεν ἄλλους ἐπιφέρεσθαι τῶν πολεμίων σφίσι καὶ κυκλοῦσθαι πανταχόθεν ἡγουμένων, διὸ μένειν οὐκ ἐτόλμων, ἀλλὰ πρὸς τὸ μεῖζον ἀνεχώρουν στρατόπεδον προέμενοι τὰ στενά. καὶ κατὰ τοῦτο δὲ καιροῦ προσμίξαντες οἱ ψιλοὶ τοῦ Ἀννίβου τὰς ὑπερβολὰς κατέσχον, ἡ δ’ ἄλλη δύναμις ἤδη προσέβαινεν ἀδεῶς πολλὴν καὶ βαρεῖαν ἐφελκομένη λείαν.", "st": "Fab. 6.4"}, {"sp": "N", "t": "τῷ δὲ Φαβίῳ συνέβη μὲν ἔτι νυκτὸς αἰσθέσθαι τὸν δόλον φεύγουσαι γὰρ ἔνιαι τῶν βοῶν σποράδες ἧκον αὐτῶν εἰς χεῖρας, ἐνέδρας δὲ δεδιὼς σκοταίους ἀτρέμα τὴν δύναμιν ἐν τοῖς ὅπλοις εἶχεν. ὡς δ’ ἦν ἡμέρα, διώκων ἐξήπτετο τῶν ἐσχάτων, καὶ συμπλοκαὶ περὶ τὰς δυσχωρίας ἐγίνοντο καὶ θόρυβος ἦν πολύς, ἕως παρ’ Ἀννίβου τῶν ὀρειβατεῖν δεινῶν Ἰβήρων ἄνδρες ἐλαφροὶ καὶ ποδώκεις πεμφθέντες ἀπὸ τοῦ στόματος εἰς βαρεῖς ὁπλίτας τοὺς Ῥωμαίους ἐνέβαλον, καὶ διαφθείραντες οὐκ ὀλίγους ἀπέστρεψαν τὸν Φάβιον. τότε δὴ μάλιστα κακῶς ἀκοῦσαι καὶ καταφρονηθῆναι συνέβη τὸν Φάβιον. τῆς γὰρ ἐν τοῖς ὅπλοις τόλμης ὑφιέμενος, ὡς γνώμῃ καὶ προνοίᾳ καταπολεμήσων τὸν Ἀννίβαν, αὐτὸς ἡττημένος τούτοις καὶ κατεστρατηγημένος ἐφαίνετο.", "st": "Fab. 7.1"}, {"sp": "N", "t": "βουλόμενος δὲ μᾶλλον ἐκκαῦσαι τὴν πρὸς αὐτὸν ὀργὴν τῶν Ῥωμαίων ὁ Ἀννίβας, ὡς ἦλθεν ἐπὶ τοὺς ἀγροὺς αὐτοῦ, τὰ μὲν ἄλλα πάντα καίειν καὶ διαφθείρειν ἐκέλευσεν, ἐκείνων δ’ ἀπεῖπεν ἅπτεσθαι μόνων, καὶ παρακατέστησε φυλακὴν οὐδὲν ἐῶσαν ἀδικεῖν οὐδὲ λαμβάνειν ἐκεῖθεν. ταῦτα προσδιέβαλε τὸν Φάβιον εἰς Ῥώμην ἀγγελθέντα· καὶ πολλὰ μὲν αὐτοῦ πρὸς τὸν ὄχλον οἱ δήμαρχοι κατεβόων, ἐπάγοντος μάλιστα Μετιλίου καὶ παροξύνοντος, οὐ κατὰ τὴν πρὸς Φάβιον ἔχθραν, ἀλλ’ οἰκεῖος ὢν Μινουκίου τοῦ ἱππάρχου τιμὴν ᾤετο καὶ δόξαν ἐκείνῳ φέρειν τὰς τούτου διαβολάς· ἐγεγόνει δὲ καὶ τῇ βουλῇ δι’ ὀργῆς οὐχ ἥκιστα μεμφομένῃ τὰς περὶ τῶν αἰχμαλώτων πρὸς Ἀννίβαν ὁμολογίας. ὡμολογήκεισαν γὰρ αὑτοῖς ἄνδρα μὲν ἀνδρὶ λύεσθαι τῶν ἁλισκομένων, εἰ δὲ πλείους οἱ ἕτεροι γένοιντο, διδόναι δραχμὰς ὑπὲρ ἑκάστου τὸν κομιζόμενον πεντήκοντα καὶ διακοσίας. ὡς οὖν γενομένης τῆς κατ’ ἄνδρα διαμείψεως εὑρέθησαν ὑπόλοιποι Ῥωμαίων παρ’ Ἀννίβᾳ τεσσαράκοντα καὶ διακόσιοι, τούτων ἡ σύγκλητος ἔγνω τὰ λύτρα μὴ πέμπειν, καὶ προσῃτιᾶτο τὸν Φάβιον ὡς οὐ πρεπόντως οὐδὲ λυσιτελῶς ἄνδρας ὑπὸ δειλίας πολεμίων ἄγραν γενομένους ἀνακομιζόμενον. ταῦτ’ ἀκούσας ὁ Φάβιος τὴν μὲν ὀργὴν ἔφερε πρᾴως τῶν πολιτῶν, χρήματα δ’ οὐκ ἔχων, διαψεύσασθαι δὲ τὸν Ἀννίβαν καὶ προέσθαι τοὺς πολίτας οὐχ ὑπομένων, ἔπεμψε τὸν υἱὸν εἰς Ῥώμην κελεύσας ἀποδόσθαι τοὺς ἀγροὺς καὶ τὸ ἀργύριον εὐθὺς ὡς αὐτὸν ἐπὶ τὸ στρατόπεδον κομίζειν. ἀποδομένου δὲ τοῦ νεανίσκου τὰ χωρία καὶ ταχέως ἐπανελθόντος ἀπέπεμψε τὰ λύτρα τῷ Ἀννίβᾳ καὶ τοὺς αἰχμαλώτους ἀπέλαβε· καὶ πολλῶν ἀποδιδόντων ὕστερον παρ’ οὐδενὸς ἔλαβεν, ἀλλ’ ἀφῆκε πᾶσι.", "st": "Fab. 7.3"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα τῶν ἱερέων καλούντων αὑτόν εἰς Ῥώμην ἐπί τινας θυσίας παρέδωκε τῷ Μινουκίῳ τὴν δύναμιν, ὑπὲρ τοῦ μὴ μάχεσθαι μηδὲ συμπλέκεσθαι τοῖς πολεμίοις οὐ μόνον ὡς αὐτοκράτωρ διαγορεύσας, ἀλλὰ καί παραινέσεις καὶ δεήσεις πολλὰς αὐτοῦ ποιησάμενος· ὧν ἐκεῖνος ἐλάχιστα φροντίσας εὐθὺς ἐνέκειτο τοῖς πολεμίοις. καί ποτε παραφυλάξας τὸν Ἀννίβαν τὸ πολὺ τῆς στρατιᾶς ἐπί σιτολογίαν ἀφεικότα, καί προσβαλὼν τῷ ὑπολειπομένῳ, κατήραξεν εἰς τὸν χάρακα καί διέφθειρεν οὐκ ὀλίγους καί φόβον περιέστησε πᾶσιν ὡς πολιορκησομένοις ὑπ’ αὐτοῦ. καί συλλεγομένης αὖθις εἰς τὸ στρατόπεδον τῷ Ἀννίβᾳ, τῆς δυνάμεως ἀσφαλῶς ἀνεχώρησεν, αὑτόν τε μεγαλαυχίας ἀμέτρου καί θράσους τὸ στρατιωτικὸν ἐμπεπληκώς. ταχὺ δὲ τοῦ ἔργου λόγος μείζων διεφοίτησεν εἰς Ῥώμην. καί Φάβιος μὲν ἀκούσας ἔφη μᾶλλον τοῦ Μινουκίου φοβεῖσθαι τήν εὐτυχίαν ἢ τήν ἀτυχίαν, ὁ δὲ δῆμος ἦρτο καί μετὰ χαρᾶς εἰς ἀγορὰν συνέτρεχε, καί Μετίλιος ὁ δήμαρχος ἐπί τοῦ βήματος καταστὰς ἐδημηγόρει μεγαλύνων τὸν Μινούκιον, τοῦ δὲ Φαβίου κατηγορῶν οὐ μαλακίαν οὐδ’ ἀνανδρίαν, ἀλλ’ ἤδη προδοσίαν, συναιτιώμενος ἅμα καί τῶν ἄλλων ἀνδρῶν τοὺς δυνατωτάτους καί πρώτους ἐπαγαγέσθαι τὸν πόλεμον ἐξ ἀρχῆς ἐπί καταλύσει τοῦ δήμου, τήν τε πόλιν ἐμβαλεῖν εὐθὺς εἰς μοναρχίαν ἀνυπεύθυνον, ἣ διατρίβουσα τὰς πράξεις ἵδρυσιν Ἀννίβᾳ, παρέξει καί χρόνον αὖθις ἐκ Λιβύης ἑτέραν δύναμιν προσγενέσθαι ὡς κρατοῦντι τῆς Ἰταλίας.", "st": "Fab. 8.1"}, {"sp": "N", "t": "ἐπεὶ δ’ ὁ Φάβιος προσελθὼν ἀπολογεῖσθαι μὲν οὐδ’ ἐμέλλησε πρὸς τὸν δήμαρχον, ἔφη δὲ τάχιστα τὰς θυσίας καὶ τὰς ἱερουργίας γενέσθαι, ὥστ’ ἐπὶ τὸ στράτευμα βαδιεῖσθαι τῷ Μινουκίῳ δίκην ἐπιθήσων, ὅτι κωλύσαντος αὐτοῦ τοῖς πολεμίοις συνέβαλε, θόρυβος διῇξε τοῦ δήμου πολὺς, ὡς κινδυνεύσοντος τοῦ Μινουκίου. καὶ γὰρ εἷρξαι τῷ δικτάτορι καὶ θανατῶσαι πρὸ δίκης ἔξεστι καὶ τοῦ Φαβίου τὸν θυμὸν ἐκ πολλῆς πρᾳότητος κεκινημένον ᾤοντο βαρὺν εἶναι καὶ δυσπαραίτητον. ὅθεν οἱ μὲν ἄλλοι καταδείσαντες ἡσυχίαν ἦγον· ὁ δὲ Μετίλιος ἔχων τὴν ἀπὸ τῆς δημαρχίας ἄδειαν μόνη γὰρ αὕτη δικτάτορος αἱρεθέντος ἡ ἀρχὴ τὸ κράτος οὐκ ἀπόλλυσιν, ἀλλὰ μένει τῶν ἄλλων καταλυθεισῶν, ἐνέκειτο τῷ δήμῳ πολύς, μὴ προέσθαι δεόμενος τὸν Μινούκιον μηδ’ ἐᾶσαι παθεῖν ἃ Μάλλιος Τουρκουᾶτος ἔδρασε τὸν υἱόν, ἀριστεύσαντος καὶ στεφανωθέντος ἀποκόψας πελέκει τὸν τράχηλον, ἀφελέσθαι δὲ τοῦ Φαβίου τὴν τυραννίδα καὶ τῷ δυναμένῳ καὶ βουλομένῳ σῴζειν ἐπιτρέψαι τὰ πράγματα.", "st": "Fab. 9.1"}, {"sp": "N", "t": "τοιούτοις λόγοις κινηθέντες οἱ ἄνθρωποι τὸν μὲν Φάβιον οὐκ ἐτόλμησαν ἀναγκάσαι καταθέσθαι τὴν μοναρχίαν, καίπερ ἀδοξοῦντα, τὸν δὲ Μινούκιον ἐψηφίσαντο τῆς στρατηγίας ὁμότιμον ὄντα διέπειν τὸν πόλεμον ἀπὸ τῆς αὐτῆς ἐξουσίας τῷ δικτάτορι, πρᾶγμα μὴ πρότερον ἐν Ῥώμῃ γεγονός, ὀλίγῳ δ’ ὕστερον αὖθις γενόμενον μετὰ τὴν ἐν Κάνναις ἀτυχίαν. καὶ γὰρ τότ’ ἐπὶ τῶν στρατοπέδων Μᾶρκος ἦν Ἰούνιος δικτάτωρ, καὶ κατὰ πόλιν τὸ βουλευτικὸν ἀναπληρῶσαι δεῆσαν, ἅτε δὴ πολλῶν ἐν τῇ μάχῃ συγκλητικῶν ἀπολωλότων, ἕτερον εἵλοντο δικτάτορα Φάβιον Βουτεῶνα. πλὴν οὗτος μὲν, ἐπεὶ προῆλθε καὶ κατέλεξε τοὺς ἄνδρας καὶ συνεπλήρωσε τὴν βουλήν, αὐθημερὸν ἀφεὶς τοὺς ῥαβδούχους καὶ διαφυγὼν τοὺς προάγοντας, εἰς τὸν ὄχλον ἐμβαλὼν καὶ καταμίξας ἑαυτὸν ἤδη τι τῶν ἑαυτοῦ διοικῶν καὶ πραγματευόμενος ὥσπερ ἰδιώτης ἐπὶ τῆς ἀγορᾶς ἀνεστρέφετο.", "st": "Fab. 9.3"}, {"sp": "N", "t": "τὸν δὲ Μινούκιον ἐπὶ τὰς αὐτὰς τῷ δικτάτορι πράξεις ἀποδείξαντες ᾤοντο κεκολοῦσθαι καὶ γεγονέναι ταπεινὸν παντάπασιν ἐκεῖνον, οὐκ ὀρθῶς στοχαζόμενοι τοῦ ἀνδρός. οὐ γὰρ αὑτοῦ συμφορὰν ἡγεῖτο τὴν ἐκείνων ἄγνοιαν, ἀλλ’ ὥσπερ Διογένης ὁ σοφός, εἰπόντος τινὸς πρὸς αὐτόν· οὗτοι σοῦ καταγελῶσιν, ἀλλ’ ἐγώ εἶπεν, οὐ καταγελῶμαι, μόνους ἡγούμενος καταγελᾶσθαι τοὺς ἐνδιδόντας καὶ πρὸς τὰ τοιαῦτα διαταραττομένους. οὕτω Φάβιος ἔφερεν ἀπαθῶς καὶ ῥᾳδίως ὅσον ἐπ’ αὐτῷ τὰ γινόμενα, συμβαλλόμενος ἀπόδειξιν τῶν φιλοσόφων τοῖς ἀξιοῦσι μήτε ὑβρίζεσθαι μήτε ἀτιμοῦσθαι τὸν ἀγαθὸν ἄνδρα καὶ σπουδαῖον. ἠνία δ’ αὐτὸν ἡ τῶν πολλῶν ἀβουλία διὰ τὰ κοινά, δεδωκότων ἀφορμὰς ἀνδρὸς οὐχ ὑγιαινούσῃ φιλοτιμίᾳ πρὸς τὸν πόλεμον. καὶ δεδοικὼς μὴ παντάπασιν ἐκμανεὶς ὑπὸ κενῆς δόξης καὶ ὄγκου φθάσῃ τι κακὸν ἀπεργασάμενος, λαθὼν ἅπαντας ἐξῆλθε καὶ παραγενόμενος εἰς τὸ στρατόπεδον καὶ καταλαβὼν τὸν Μινούκιον οὐκέτι καθεκτόν, ἀλλὰ βαρὺν καὶ τετυφωμένον καὶ παρὰ μέρος ἄρχειν ἀξιοῦντα, τοῦτο μὲν οὐ συνεχώρησε, τὴν δὲ δύναμιν διενείματο πρὸς αὐτόν, ὡς μέρους μόνος ἄρξων βέλτιον ἢ πάντων παρὰ μέρος. καὶ τὸ μὲν πρῶτον τῶν ταγμάτων καὶ τέταρτον αὐτὸς ἔλαβε, τὸ δὲ δεύτερον καὶ τρίτον ἐκείνῳ παρέδωκεν, ἐπίσης καὶ τῶν συμμαχικῶν διανεμηθέντων. σεμνυνομένου δὲ τοῦ Μινουκίου καὶ χαίροντος ἐπὶ τῷ τὸ πρόσχημα τῆς ἀκροτάτης καὶ μεγίστης ἀρχῆς ὑφεῖσθαι καὶ προπεπηλακίσθαι δι’ αὐτόν, ὑπεμίμνῃσκεν ὁ Φάβιος ὡς οὐκ ὄντος μὲν αὐτῷ πρὸς Φάβιον, ἀλλ’, εἰ σωφρονεῖ, πρὸς Ἀννίβαν τοῦ ἀγῶνος· εἰ δὲ καὶ πρὸς τὸν συνάρχοντα φιλονεικεῖ, σκοπεῖν ὅπως τοῦ νενικημένου καὶ καθυβρισμένου παρὰ τοῖς πολίταις ὁ τετιμημένος καὶ νενικηκὼς οὐ φανεῖται μᾶλλον ὀλιγωρῶν τῆς σωτηρίας αὐτῶν καὶ ἀσφαλείας.", "st": "Fab. 10.1"}, {"sp": "N", "t": "ὁ δὲ ταῦτα μὲν εἰρωνείαν ἡγεῖτο γεροντικήν· παραλαβὼν δὲ τὴν ἀποκληρωθεῖσαν δύναμιν ἰδίᾳ καὶ χωρὶς ἐστρατοπέδευσεν, οὐδὲν ἀγνοοῦντος τοῦ Ἀννίβου τῶν γινομένων, ἀλλὰ πᾶσιν ἐφεδρεύοντος. ἦν δὲ λόφος κατὰ μέσον καταληφθῆναι μὲν οὐ χαλεπός, ὀχυρὸς δὲ καταληφθεὶς στρατοπέδῳ καὶ διαρκὴς εἰς ἅπαντα, τὸ δὲ πέριξ πεδίον ὀφθῆναι μὲν ἄπωθεν ὁμαλὸν διὰ ψιλότητα καὶ λεῖον, ἔχον δέ τινας οὐ μεγάλας τάφρους ἐν αὑτῷ καὶ κοιλότητας ἄλλας. διὸ καὶ τὸν λόφον ἐκ τοῦ ῥᾴστου κρύφα κατασχεῖν παρόν οὐκ ἠθέλησεν ὁ Ἀννίβας, ἀλλ’ ἀπέλιπε μάχης ἐν μέσῳ πρόφασιν. ὡς δ’ εἶδε κεχωρισμένον τοῦ Φαβίου τὸν Μινούκιον, νυκτὸς μὲν εἰς τὰς τάφρους καὶ τὰς κοιλότητας κατέσπειρε τῶν στρατιωτῶν τινας, ἅμα δὲ τῇ ἡμέρᾳ φανερῶς ἔπεμψεν οὐ πολλοὺς καταληψομένους τὸν λόφον, ὡς ἐπαγάγοιτο συμπεσεῖν περὶ τοῦ τόπου τὸν Μινούκιον.", "st": "Fab. 11.1"}, {"sp": "N", "t": "ὃ δὴ καὶ συνέβη, πρῶτον μὲν γὰρ ἀπέστειλε τὴν κούφην στρατιάν, ἔπειτα τοὺς ἱππεῖς, τέλος δ’ ὁρῶν τὸν Ἀννίβαν παραβοηθοῦντα τοῖς ἐπὶ τοῦ λόφου πάσῃ κατέβαινε τῇ δυνάμει συντεταγμένος, καὶ μάχην καρτερὰν θέμενος ἠμύνετο τοὺς ἀπὸ τοῦ λόφου βάλλοντας, συμπλεκόμενος καὶ ἴσα φερόμενος, ἄχρι οὗ καλῶς ἠπατημένον ὁρῶν ὁ Ἀννίβας καὶ γυμνὰ παρέχοντα τοῖς ἐνεδρεύουσι τὰ νῶτα τὸ σημεῖον αἴρει. πρὸς δὲ τοῦτο πολλαχόθεν ἐξανισταμένων ἅμα καὶ μετὰ κραυγῆς προσφερομένων καὶ τοὺς ἐσχάτους ἀποκτιννύντων ἀδιήγητος κατεῖχε ταραχὴ καὶ πτοία τοὺς Ῥωμαίους, αὐτοῦ τε τοῦ Μινουκίου τὸ θράσος κατακέκλαστο, καὶ πρὸς ἄλλον ἄλλοτε τῶν ἡγεμόνων διεπάπταινεν, οὐδενὸς ἐν χώρᾳ μένειν τολμῶντος, ἀλλὰ πρὸς φυγὴν ὠθουμένων οὐ σωτήριον. οἱ γὰρ Νομάδες ἤδη κρατοῦντες κύκλῳ περιήλαυνον τὸ πεδίον καὶ τοὺς ἀποσκιδναμένους ἔκτεινον.", "st": "Fab. 11.3"}, {"sp": "N", "t": "ἐν τοσούτῳ δὲ κακῷ τῶν Ῥωμαίων ὄντων οὐκ ἔλαθεν ὁ κίνδυνος τὸν Φάβιον, ἀλλὰ καὶ τὸ μέλλον, ὡς ἔοικεν, ἤδη προειληφώς τήν τε δύναμιν συντεταγμένην εἶχεν ἐπὶ τῶν ὅπλων καὶ τὰ πραττόμενα γινώσκειν ἐφρόντιζεν οὐ δι’ ἀγγέλων, ἀλλ’ αὐτὸς ἔχων κατασκοπὴν πρὸ τοῦ χάρακος. ὡς οὖν κατεῖδε κυκλούμενον καὶ ταραττόμενον τὸ στράτευμα, καὶ κραυγὴ προσέπιπτεν οὐ μενόντων, ἀλλ’ ἤδη πεφοβημένων καὶ τρεπομένων, μηρόν τε πληξάμενος καὶ στενάξας μέγα πρὸς μὲν τοὺς παρόντας εἶπεν Ὦ Ἡράκλεις, ὡς τάχιον μὲν ἢ ἐγὼ προσεδόκων, βράδιον δ’ ἢ αὐτὸς ἔσπευδε Μινούκιος ἑαυτὸν ἀπολώλεκε, τὰς δὲ σημαίας ἐκφέρειν κατὰ τάχος καὶ τὸν στρατὸν ἕπεσθαι κελεύσας ἀνεβόησε· νῦν τις, ὦ στρατιῶται, Μάρκου Μινουκίου μεμνημένος ἐπειγέσθω· λαμπρὸς γὰρ ἁνὴρ καὶ φιλόπατρις, εἰ δέ τι σπεύδων ἐξελάσαι τοὺς πολεμίους ἥμαρτεν, αὖθις αἰτιασόμεθα.", "st": "Fab. 12.1"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἐπιφανεὶς τρέπεται καὶ διασκίδνησι τοὺς ἐν τῷ πεδίῳ περιελαύνοντας Νομάδας· εἶτα πρὸς τοὺς μαχομένους καὶ κατὰ νώτου τῶν Ῥωμαίων ὄντας ἐχώρει καὶ τοὺς ἐμποδὼν ἔκτεινεν, οἱ δὲ λοιποί, πρὶν ἀποληφθῆναι καὶ γενέσθαι περιπετεῖς οἷς αὐτοὶ τοὺς Ῥωμαίους ἐποίησαν, ἐγκλίναντες ἔφυγον. ὁρῶν δ’ ὁ Ἀννίβας τήν μεταβολὴν καὶ τὸν Φάβιον εὐρώστως παρ’ ἡλικίαν διὰ τῶν μαχομένων ὠθούμενον ἄνω πρὸς τὸν Μινούκιον εἰς τὸν όφον, ἐπέσχε τήν μάχην, καὶ τῇ σάλπιγγι σημήνας ἀνάκλησιν ἀπῆγεν εἰς τὸν χάρακα τοὺς Καρχηδονίους, ἀσμένως καὶ τῶν Ῥωμαίων ἀποτρεπομένων, λέγεται δ’ αὐτὸν ἀπιόντα περὶ τοῦ Φαβίου πρὸς τοὺς φίλους εἰπεῖν τι τοιοῦτον μετὰ παιδιᾶς· οὐκ ἐγὼ μέντοι προὔλεγον ὑμῖν πολλάκις τήν ἐπὶ τῶν ἄκρων ταύτην καθημένην νεφέλην, ὅτι μετὰ ζάλης ποτὲ καὶ καταιγίδων ὄμβρον ἐκρήξει;", "st": "Fab. 12.3"}, {"sp": "N", "t": "μετὰ δὲ τὴν μάχην Φάβιος μὲν ὅσους ἔκτεινε τῶν πολεμίων σκυλεύσας ἀνεχώρησεν, οὐδὲν ὑπερήφανον οὐδ’ ἐπαχθὲς εἰπὼν περὶ τοῦ συνάρχοντος· Μινούκιος δὲ τὴν αὑτοῦ στρατιὰν ἀθροίσας, ἄνδρες, ἔφη, συστρατιῶται, τὸ μὲν ἁμαρτεῖν μηδὲν ἐν πράγμασι μεγάλοις μεῖζον ἢ κατ’ ἄνθρωπόν ἐστι, τὸ δ’ ἁμαρτόντα χρήσασθαι τοῖς πταίσμασι διδάγμασι πρὸς τὸ λοιπὸν ἀνδρὸς ἀγαθοῦ καὶ νοῦν ἔχοντος. ἐγὼ μὲν οὖν ὁμολογῶ μικρὰ μεμφόμενος τὴν τύχην περὶ μειζόνων ἐπαινεῖν. ἃ γὰρ οὐκ ᾐσθόμην χρόνον τοσοῦτον, ἡμέρας μέρει μικρῷ πεπαίδευμαι, γνοὺς ἐμαυτὸν οὐκ ἄρχειν ἑτέρων δυνάμενον, ἀλλ’ ἄρχοντος ἑτέρου δεόμενον καὶ φιλοτιμούμενον νικᾶν ὑφ’ ὧν ἡττᾶσθαι κάλλιον. ὑμῖν δὲ τῶν μὲν ἄλλων ἐστὶν ἄρχων ὁ δικτάτωρ, τῆς δὲ πρὸς ἐκεῖνον εὐχαριστίας αὐτὸς ἡγεμὼν ἔσομαι, πρῶτον ἐμαυτὸν εὐπειθῆ καὶ ποιοῦντα τὸ κελευόμενον ὑπ’ ἐκείνου παρεχόμενος.", "st": "Fab. 13.1"}, {"sp": "N", "t": "ταῦτ’ εἰπὼν καὶ τοὺς ἀετοὺς ἄρασθαι κελεύσας καὶ πάντας ἀκολουθεῖν, ἦγε πρὸς τὸν χάρακα τοῦ Φαβίου. καὶ παρελθὼν ἐντὸς ἐβάδιζεν ἐπὶ τὴν στρατηγικὴν σκηνήν, ὥστε θαυμάζειν καὶ διαπορεῖν πάντας. προελθόντος δὲ τοῦ Φαβίου θέμενος ἔμπροσθεν τὰς σημαίας αὐτὸς μὲν ἐκεῖνον πατέρα μεγάλῃ φωνῇ, οἱ δὲ στρατιῶται τοὺς στρατιώτας πάτρωνας ἠσπάζοντο. τοῦτο δ’ ἔστι τοῖς ἀπελευθέροις προσφώνημα πρὸς τοὺς ἀπελευθερώσαντας. ἡσυχίας δὲ γενομένης ὁ Μινούκιος εἶπε· δύο νίκας, ὦ δίκτατορ, τῇ σήμερον ἡμέρᾳ νενίκηκας, ἀνδρείᾳ μὲν Ἀννίβαν, εὐβουλίᾳ δὲ καὶ χρηστότητι τὸν συνάρχοντα· καὶ δι’ ἧς μὲν σέσωκας ἡμᾶς, δι’ ἧς δὲ πεπαίδευκας, ἡττωμένους αἰσχρὰν μὲν ἧτταν ὑπ’ ἐκείνου, καλὴν δὲ καὶ σωτήριον ὑπὸ σοῦ. πατέρα δή σε χρηστὸν προσαγορεύω, τιμιωτέραν οὐκ ἔχων προσηγορίαν, ἐπεὶ τῆς γε τοῦ τεκόντος χάριτος μείζων ἡ παρὰ σοῦ χάρις αὕτη. ἐγεννήθην μὲν γὰρ ὑπ’ ἐκείνου μόνος, σῴζομαι δὲ ὑπὸ σοῦ μετὰ τοσούτων ταῦτ’ εἰπὼν καὶ περιβαλὼν τὸν Φάβιον ἠσπάζετο. τὸ δ’ αὐτὸ καὶ τοὺς στρατιώτας ἦν ὁρᾶν πράττοντας· ἐνεφύοντο γὰρ ἀλλήλοις καὶ κατεφίλουν, ὥστε μεστὸν εἶναι χαρᾶς καὶ δακρύων ἡδίστων τὸ στρατόπεδον.", "st": "Fab. 13.3"}, {"sp": "N", "t": "ἐκ τούτου Φάβιος μὲν ἀπέθετο τὴν ἀρχήν, ὕπατοι δ’ αὖθις ἀπεδείκνυντο. καὶ τούτων οἱ μὲν πρῶτοι διεφύλαξαν ἣν ἐκεῖνος ἰδέαν τοῦ πολέμου κατέστησε, μάχεσθαι μὲν ἐκ παρατάξεως φεύγοντες πρὸς Ἀννίβαν, τοῖς δὲ συμμάχοις ἐπιβοηθοῦντες καὶ τὰς ἀποστάσεις κωλύοντες· Τερέντιος δὲ Βάρρων εἰς τὴν ὑπατείαν προαχθεὶς ἀπὸ γένους ἀσήμου, βίου δὲ διὰ δημοκοπίαν καὶ προπέτειαν ἐπισήμου, δῆλος ἦν εὐθὺς ἀπειρίᾳ καὶ θρασύτητι τὸν περὶ τῶν ὅλων ἀναρρίψων κύβον. ἐβόα γὰρ ἐν ταῖς ἐκκλησίαις μενεῖν τὸν πόλεμον ἄχρι οὗ Φαβίοις χρῆται στρατηγοῖς ἡ πόλις, αὐτὸς δὲ τῆς αὐτῆς ἡμέρας ὄψεσθαί τε καὶ νικήσειν τοὺς πολεμίους, ἅμα δὲ τούτοις τοῖς λόγοις συνῆγε καὶ κατέγραφε δύναμιν τηλικαύτην, ἡλίκῃ πρὸς οὐδένα πώποτε τῶν πολεμίων ἐχρήσαντο Ῥωμαῖοι. μυριάδες γὰρ ἐννέα δισχιλίων ἀνδρῶν δέουσαι συνετάχθησαν εἰς τὴν μάχην, μέγα δέος Φαβίῳ καὶ τοῖς νοῦν ἔχουσι Ῥωμαίων οὐ γὰρ ἤλπιζον ἕξειν ἀναφορὰν τὴν πόλιν ἐν τοσαύτῃ σφαλεῖσαν ἡλικίᾳ.", "st": "Fab. 14.1"}, {"sp": "N", "t": "διὸ καὶ τὸν συνάρχοντα τοῦ Τερεντίου Παῦλον Αἰμίλιον, ἄνδρα πολλῶν πολέμων ἔμπειρον, οὐκ ἀρεστὸν δὲ τῷ δήμῳ καὶ καταπλῆγα ἔκ τινος καταδίκης πρὸς τὸ δημόσιον αὐτῷ γεγενημένης, ἀνίστη καὶ παρεθάρρυνεν ἐπιλαμβάνεσθαι τῆς ἐκείνου μανίας, διδάσκων ὡς οὐ πρὸς Ἀννίβαν αὐτῷ μᾶλλον ἢ πρὸς Τερέντιον ὑπὲρ τῆς πατρίδος ὁ ἀγὼν ἔσοιτο σπεύδειν γὰρ μάχην γενέσθαι τὸν μὲν οὐκ αἰσθανόμενον τῆς δυνάμεως, τὸν δ’ αἰσθανόμενον τῆς περὶ αὑτὸν ἀσθενείας. ἐγὼ δ’, εἶπεν, ὦ Παῦλε, Τερεντίου πιστεύεσθαι δικαιότερός εἰμι περὶ τῶν Ἀννίβου πραγμάτων διαβεβαιούμενος ὡς, εἰ μηδεὶς αὐτῷ μαχεῖται τοῦτον τὸν ἐνιαυτόν, ἀπολεῖται μένων ὁ ἀνὴρ ἢ φεύγων ἄπεισιν, ᾧ γε καὶ νῦν νικᾶν καὶ κρατεῖν δοκοῦντι τῶν μὲν πολεμίων οὐδεὶς προσκεχώρηκε, τῆς δ’ οἴκοθεν δυνάμεως οὐδ’ ἡ τρίτη μοῖρα πάνυ περίεστι. πρὸς ταῦτα λέγεται τὸν Παῦλον εἰπεῖν ἐμοὶ μὲν, ὦ Φάβιε, τὰ ἐμαυτοῦ σκοποῦντι κρεῖττόν ἐστι τοῖς τῶν πολεμίων ὑποπεσεῖν δόρασιν ἢ πάλιν ταῖς ψήφοις τῶν πολιτῶν εἰ δ’ οὕτως ἔχει τὰ δημόσια πράγματα, πειράσομαι μᾶλλον σοὶ δοκεῖν ἀγαθὸς εἶναι στρατηγὸς ἢ πᾶσι τοῖς ἄλλοις ἐπὶ τἀναντία βιαζομένοις. ταύτην ἔχων τὴν προαίρεσιν ὁ Παῦλος ἐξῆλθεν ἐπὶ τὸν πόλεμον.", "st": "Fab. 14.3"}, {"sp": "N", "t": "ἀλλ’ ὁ Τερέντιος ἐμβαλὼν αὑτὸν εἰς τὸ παρ’ ἡμέραν ἄρχειν, καὶ τῷ Ἀννίβᾳ, παραστρατοπεδεύσας περὶ τὸν Αὐφίδιον ποταμὸν καὶ τὰς λεγομένας Κάννας, ἅμ’ ἡμέρᾳ τὸ τῆς μάχης σημεῖον ἐξέθηκεν ἔστι δὲ χιτὼν κόκκινος ὑπὲρ τῆς στρατηγικῆς σκηνῆς διατεινόμενος, ὥστε καὶ τοὺς Καρχηδονίους ἐξ ἀρχῆς διαταραχθῆναι, τήν τε τόλμαν τοῦ στρατηγοῦ καὶ τὸ τοῦ στρατοπέδου πλῆθος ὁρῶντας, αὐτοὺς οὐδ’ ἥμισυ μέρος ὄντας. Ἀννίβας δὲ τήν δύναμιν ἐξοπλίζεσθαι κελεύσας, αὐτὸς ἱππότης μετ’ ὀλίγων ὑπὲρ λόφου τινὸς μαλακοῦ κατεσκόπει τοὺς πολεμίους ἤδη καθισταμένους εἰς τάξιν. εἰπόντος δέ τινος τῶν περὶ αὐτὸν ἀνδρὸς ἰσοτίμου, τοὔνομα Γίσκωνος, ὡς θαυμαστὸν αὐτῷ φαίνεται τὸ πλῆθος τῶν πολεμίων, συναγαγὼν τὸ πρόσωπον ὁ Ἀννίβας, ἕτερον, εἶπεν, ὦ Γίσκων, λέληθέ σε τούτου θαυμασιώτερον. ἐρομένου δὲ τοῦ Γίσκωνος, τὸ ποῖον; ὅτι, ἔφη, τούτων ὄντων τοσούτων οὐδεὶς ἐν αὐτοῖς Γίσκων καλεῖται. γενομένου δὲ παρὰ δόξαν αὐτοῖς τοῦ σκώμματος ἐμπίπτει γέλως πᾶσι, καὶ κατέβαινον ἀπὸ τοῦ λόφου τοῖς ἀπαντῶσιν ἀεὶ τὸ πεπαιγμένον ἀπαγγέλλοντες, ὥστε διὰ πολλῶν πολὺν εἶναι τὸν γέλωτα καὶ μηδ’ ἀναλαβεῖν ἑαυτοὺς δύνασθαι τοὺς περὶ τὸν Ἀννίβαν. τοῦτο τοῖς Καρχηδονίοις ἰδοῦσι θάρσος παρίστη, λογιζομένοις ἀπὸ πολλοῦ καὶ ἰσχυροῦ τοῦ καταφρονοῦντος ἐπιέναι γελᾶν οὕτως καὶ παίζειν τῷ στρατηγῷ παρὰ τὸν κίνδυνον.", "st": "Fab. 15.1"}, {"sp": "N", "t": "ἐν δὲ τῇ μάχῃ στρατηγήμασιν ἐχρήσατο, πρώτῳ μὲν τῷ ἀπὸ τοῦ τόπου, ποιησάμενος κατὰ νώτου τὸν ἄνεμον πρηστῆρι γὰρ ἐοικὼς φλέγοντι κατερρήγνυτο, καὶ τραχὺν ἐκ πεδίων ὑφάμμων καὶ ἀναπεπταμένων αἴρων κονιορτὸν ὑπὲρ τὴν φάλαγγα τῶν Καρχηδονίων ἐπὶ τοὺς Ῥωμαίους ἐώθει, καὶ προσέβαλλε τοῖς προσώποις ἀποστρεφομένοις καὶ συνταραττομένοις. δευτέρῳ δὲ τῷ περὶ τὴν τάξιν ὃ γὰρ ἦν ἰσχυρότατον αὐτῷ καὶ μαχιμώτατον τῆς δυνάμεως ἑκατέρωσε τοῦ μέσου τάξας, τὸ μέσον αὐτὸ συνεπλήρωσεν ἐκ τῶν ἀχρειοτάτων, ἐμβόλῳ τούτῳ προέχοντι πολὺ τῆς ἄλλης φάλαγγος χρησόμενος· εἴρητο δὲ τοῖς κρατίστοις, ὅταν τούτους διακόψαντες οἱ Ῥωμαῖοι καὶ φερόμενοι πρός τὸ εἶκον ἐκφερομένου τοῦ μέσου καὶ κόλπον λαμβάνοντος ἐντὸς γένωνται τῆς φάλαγγος, ὀξέως ἑκατέρωθεν ἐπιστρέψαντας ἐμβαλεῖν τε πλαγίοις καὶ περιπτύσσειν ὄπισθεν συγκλείοντας. ὃ δὴ καὶ δοκεῖ τὸν πλεῖστον ἀπεργάσασθαι φόνον. ὡς γὰρ ἐνέδωκε τὸ μέσον καὶ τοὺς Ῥωμαίους ἐδέξαντο διώκοντας, ἡ δὲ φάλαγξ τοῦ Ἀννίβου μεταβαλοῦσα τὸ σχῆμα μηνοειδὴς ἐγεγόνει καὶ τῶν ἐπιλέκτων οἱ ταξίαρχοι ταχὺ τοὺς μὲν ἐπ’ ἀσπίδα, τοὺς δ’ ἐπὶ δόρυ κλίναντες προσέπεσον κατὰ τὰ γυμνά, πάντας, ὅσοι μὴ τὴν κύκλωσιν ὑπεκκλίναντες ἔφθασαν, ἐν μέσῳ κατειργάσαντο καὶ διέφθειραν.", "st": "Fab. 16.1"}, {"sp": "N", "t": "λέγεται δὲ καὶ τοῖς ἱππεῦσι τῶν Ῥωμαίων σύμπτωμα παράλογον γενέσθαι, τὸν γὰρ Παῦλον, ὡς ἔοικε, τρωθεὶς ὁ ἵππος ἀπεσείσατο, καὶ τῶν περὶ αὐτὸν ἄλλος καὶ ἄλλος ἀπολιπὼν τὸν ἵππον πεζὸς τῷ ὑπάτῳ προσήμυνε. τοῦτο δ’ οἱ ἱππεῖς ἰδόντες, ὡς παραγγέλματος κοινοῦ δεδομένου, πάντες ἀποπηδήσαντες πεζοὶ συνεπλέκοντο τοῖς πολεμίοις. ἰδὼν δ’ ὁ Ἀννίβας, τοῦτ, ἔφη, μᾶλλον ἠβουλόμην ἢ εἰ δεδεμένους παρέλαβον. ἀλλὰ ταῦτα μὲν οἱ τὰς διεξοδικὰς γράψαντες ἱστορίας ἀπηγγέλκασι.", "st": "Fab. 16.4"}, {"sp": "N", "t": "τῶν δ’ ὑπάτων ὁ μὲν Βάρρων ὀλιγοστὸς ἀφίππευσεν εἰς Οὐενουσίαν πόλιν, ὁ δὲ Παῦλος ἐν τῷ βυθῷ καὶ κλύδωνι τῆς φυγῆς ἐκείνης βελῶν τε πολλῶν ἐπὶ τοῖς τραύμασιν ἐγκειμένων ἀνάπλεως, τὸ σῶμα καὶ τὴν ψυχὴν πένθει τοσούτῳ βαρυνόμενος, πρός τινι λίθῳ καθῆστο, τὸν ἐπισφάξοντα τῶν πολεμίων ἀναμένων. ἦν δὲ δι’ αἵματος πλῆθος, ᾧ συνεπέφυρτο τὴν κεφαλὴν καὶ τὸ πρόσωπον, οὐ πολλοῖς διάδηλος, ἀλλὰ καὶ φίλοι καὶ θεράποντες αὑτὸν ὑπ’ ἀγνοίας παρῆλθον. μόνος δὲ Κορνήλιος Λέντλος, εὐπατρίδης νέος, ἰδὼν καὶ προνοήσας ἀπεπήδησε τοῦ ἵππου, καὶ προσαγαγὼν παρεκάλει χρῆσθαι καὶ σῴζειν αὑτὸν τοῖς πολίταις ἄρχοντος ἀγαθοῦ τότε μάλιστα χρῄζουσιν. ὁ δὲ ταύτην μὲν ἀπετρίψατο τὴν δέησιν, καὶ τὸ μειράκιον αὖθις ἠνάγκασεν ἐπὶ τὸν ἵππον ἀναβῆναι δακρῦον, εἶτα δὲ τὴν δεξιὰν ἐμβαλὼν καὶ συνεξαναστάς, ἀπάγγελλε, εἶπεν, ὦ Λέντλε, Φαβίῳ Μαξίμῳ καὶ γενοῦ μάρτυς αὐτός, ὅτι Παῦλος Αἰμίλιος ἐνέμεινεν αὐτοῦ τοῖς λογισμοῖς ἄχρι τέλους καὶ τῶν ὁμολογηθέντων πρός ἐκεῖνον οὐδὲν ἔλυσεν, ἀλλ’ ἐνικήθη πρότερον ὑπὸ Βάρρωνος, εἶθ’ ὑπὸ Ἀννίβου. τοσαῦτ’ ἐπιστείλας τὸν μὲν Λέντλον ἀπέπεμψεν, αὐτὸς δὲ ῥίψας ἑαυτὸν εἰς τοὺς φονευομένους ἀπέθανε, λέγονται δὲ πεσεῖν μὲν ἐν τῇ μάχῃ Ῥωμαίων πεντακισμύριοι, ζῶντες δ’ ἁλῶναι τετρακισχίλιοι, καὶ μετὰ τὴν μάχην οἱ ληφθέντες ἐπ’ ἀμφοτέροις τοῖς στρατοπέδοις μυρίων οὐκ ἐλάττους.", "st": "Fab. 16.6"}, {"sp": "N", "t": "τὸν δ’ Ἀννίβαν ἐπὶ τηλικούτῳ κατορθώματι τῶν φίλων παρορμώντων ἅμ’ ἕπεσθαι τῇ τύχῃ καὶ συνεπεισπεσεῖν ἅμα τῇ φυγῇ τῶν πολεμίων εἰς τὴν πόλιν, πεμπταῖον γὰρ ἀπὸ τῆς νίκης ἐν Καπιτωλίῳ δειπνήσειν, οὐ ῥᾴδιον εἰπεῖν, ὅστις ἀπέτρεψε λογισμός, ἀλλὰ μᾶλλον δαίμονος ἢ θεοῦ τινος ἐμποδὼν στάντος ἔοικεν ἔργον ἡ πρὸς τοῦτο μέλλησις αὐτοῦ καὶ δειλίασις γενέσθαι. διὸ καὶ Βάρκαν τὸν Καρχηδόνιον εἰπεῖν μετ’ ὀργῆς πρὸς αὐτὸν λέγουσι· σὺ νικᾶν οἶδας, νίκῃ δὲ χρῆσθαι οὐκ οἶδας. καίτοι τοσαύτην μεταβολὴν ἡ νίκη περὶ αὐτὸν ἐποίησεν, ὡς πρὸ τῆς μάχης οὐ πόλιν, οὐκ ἐμπόριον, οὐ λιμένα τῆς Ἰταλίας ἔχοντα, χαλεπῶς δὲ καὶ μόλις τὰ ἐπιτήδεια τῇ στρατιᾷ δι’ ἁρπαγῆς κομιζόμενον, ὁρμώμενον ἀπ’ οὐδενὸς βεβαίου πρὸς τὸν πόλεμον, ἀλλ’ ὥσπερ λῃστηρίῳ μεγάλῳ τῷ στρατοπέδῳ πλανώμενον καὶ περιφερόμενον, τότε πᾶσαν ὀλίγου δεῖν ὑφ’ αὑτῷ ποιήσασθαι τὴν Ἰταλίαν. τὰ γὰρ πλεῖστα καὶ μέγιστα τῶν ἐθνῶν αὐτῷ προσεχώρησεν ἑκούσια, καὶ Καπύην, ἣ μέγιστον ἔχει μετὰ Ῥώμην ἀξίωμα τῶν πόλεων, προσθεμένην κατέσχεν.", "st": "Fab. 17.1"}, {"sp": "N", "t": "οὐ μόνον δ’ ἦν ἄρα τὸ φίλων πεῖραν λαβεῖν, ὡς Εὐριπίδης φησίν, οὐ σμικρὸν κακόν, ἀλλὰ καὶ τὸ φρονίμων στρατηγῶν, ἡ γὰρ πρὸ τῆς μάχης Φαβίου δειλία καὶ ψυχρότης λεγομένη μετὰ τὴν μάχην εὐθὺς οὐδ’ ἀνθρώπινος ἐδόκει λογισμός, ἀλλὰ θεῖόν τι χρῆμα διανοίας καὶ δαιμόνιον ἐκ τοσούτου τὰ μέλλοντα προορωμένης, ἃ μόλις ἦν πιστὰ πάσχουσιν. ὅθεν εὐθὺς εἰς ἐκεῖνον ἡ Ῥώμη συνενεγκοῦσα τὰς λοιπὰς ἐλπίδας, καὶ προσφυγοῦσα τῇ γνώμῃ τοῦ ἀνδρὸς ὥσπερ ἱερῷ καὶ βωμῷ, πρώτην καὶ μεγίστην αἰτίαν ἔσχε τοῦ μεῖναι καὶ μὴ διαλυθῆναι τὴν ἐκεῖνον φρόνησιν, καθάπερ ἐν τοῖς Κελτικοῖς πάθεσιν. ὁ γὰρ ἐν οἷς οὐδὲν ἐδόκει δεινὸν εἶναι καιροῖς εὐλαβὴς φαινόμενος καὶ δυσέλπιστος τότε πάντων καταβεβληκότων ἑαυτοὺς εἰς ἀπέραντα πένθη καὶ ταραχὰς ἀπράκτους, μόνος ἐφοίτα διὰ τῆς πόλεως πρᾴῳ βαδίσματι καὶ προσώπῳ καθεστῶτι καὶ φιλανθρώπῳ προσαγορεύσει, κοπετούς τε γυναικείους ἀφαιρῶν καὶ συστάσεις εἴργων τῶν εἰς τὸ δημόσιον ἐπὶ κοινοῖς ὀδυρμοῖς ἐκφερομένων, βουλήν τε συνελθεῖν ἔπεισε καὶ παρεθάρσυνε τὰς ἀρχάς, αὐτὸς ὢν καὶ ῥώμη καὶ δύναμις ἀρχῆς ἁπάσης πρὸς ἐκεῖνον ἀποβλεπούσης.", "st": "Fab. 17.4"}, {"sp": "N", "t": "ταῖς μὲν οὖν πύλαις ἐπέστησε τοὺς τὸν ἐκπίπτοντα καὶ προλείποντα τὴν πόλιν ὄχλον ἀπείρξοντας, πένθους δὲ καὶ τόπον καὶ χρόνον ὥρισε, κατ’ οἰκίαν ἀποθρηνεῖν κελεύσας ἐφ’ ἡμέρας τριάκοντα τὸν βουλόμενον· μετὰ δὲ ταύτας ἔδει πᾶν πένθος λύεσθαι καὶ καθαρεύειν τῶν τοιούτων τὴν πόλιν. ἑορτῆς τε Δήμητρος εἰς τάς ἡμέρας ἐκείνας καθηκούσης βέλτιον ἐφάνη παραλιπεῖν ὅλως τάς τε θυσίας καὶ τὴν πομπήν ἢ τὸ μέγεθος τῆς συμφορᾶς ὀλιγότητι καὶ κατηφείᾳ τῶν συνερχομένων ἐλέγχεσθαι· καὶ γὰρ τὸ θεῖον ἥδεσθαι τιμώμενον ὑπὸ τῶν εὐτυχούντων. ὅσα μέντοι πρὸς ἱλασμοὺς θεῶν ἢ τεράτων ἀποτροπὰς συνηγόρευον οἱ μάντεις ἐπράττετο. καὶ γὰρ εἰς Δελφοὺς ἐπέμφθη θεοπρόπος Πίκτωρ, συγγενὴς Φαβίου, καὶ τῶν Ἑστιάδων παρθένων δύο διεφθαρμένας εὑρόντες, τὴν μὲν, ὥσπερ ἐστὶν ἔθος, ζῶσαν κατώρυξαν, ἡ δ’ ὑφ’ ἑαυτῆς ἀπέθανε.", "st": "Fab. 18.1"}, {"sp": "N", "t": "μάλιστα δ’ ἄν τις ἀγάσαιτο τὸ φρόνημα καὶ τὴν πρᾳότητα τῆς πόλεως, ὅτε τοῦ ὑπάτου Βάρρωνος ἀπὸ τῆς φυγῆς ἐπανιόντος, ὡς ἄν τις αἴσχιστα καὶ δυσποτμότατα πεπραχὼς ἐπανίοι, ταπεινοῦ καὶ κατηφοῦς, ἀπήντησεν αὐτῷ περὶ τάς πύλας ἥ τε βουλὴ καὶ τὸ πλῆθος ἅπαν ἀσπαζόμενοι. οἱ δ’ ἐν τέλει καὶ πρῶτοι τῆς γερουσίας, ὧν καὶ Φάβιος ἦν, ἡσυχίας γενομένης ἐπῄνεσαν, ὅτι τὴν πόλιν οὐκ ἀπέγνω μετὰ δυστυχίαν τηλικαύτην, ἀλλὰ πάρεστιν ἄρξων ἐπὶ τὰ πράγματα καὶ χρησόμενος τοῖς νόμοις καὶ τοῖς πολίταις ὡς σῴζεσθαι δυναμένοις.", "st": "Fab. 18.4"}, {"sp": "N", "t": "ἐπεὶ δ’ Ἀννίβαν ἐπύθοντο μετὰ τὴν μάχην ἀποτετράφθαι πρὸς τὴν ἄλλην Ἰταλίαν, ἀναθαρρήσαντες ἐξέπεμπον ἡγεμόνας καὶ στρατεύματα, τούτων δ’ ἐπιφανέστατοι Φάβιός τε Μάξιμος καὶ Κλαύδιος Μάρκελλος ἦσαν, ἀπὸ τῆς ἐναντίας σχεδὸν προαιρέσεως θαυμαζόμενοι παραπλησίως. ὁ μὲν γὰρ, ὥσπερ ἐν τοῖς περὶ αὐτοῦ γεγραμμένοις εἴρηται, περιλαμπὲς τὸ δραστήριον ἔχων καὶ γαῦρον, ἅτε δὴ καὶ κατὰ χεῖρα πλήκτης ἀνὴρ καὶ φύσει τοιοῦτος ὢν οἵους Ὅμηρος μάλιστα καλεῖ φιλοπτολέμους καὶ ἀγερώχους ἐν τῷ παραβόλῳ καὶ ἰταμῷ καὶ πρὸς ἄνδρα τολμηρὸν τὸν Ἀννίβαν ἀντιτολμῶντι τρόπῳ πολέμου συνίστατο τοὺς πρώτους ἀγῶνας· Φάβιος δὲ τῶν πρώτων ἐχόμενος λογισμῶν ἐκείνων ἤλπιζε μηδενὸς μαχομένου μηδ’ ἐρεθίζοντος τὸν Ἀννίβαν αὐτὸν ἐπηρεάσειν ἑαυτῷ καὶ κατατριβήσεσθαι περὶ τὸν πόλεμον, ὥσπερ ἀθλητικοῦ σώματος τῆς δυνάμεως ὑπερτόνου γενομένης καὶ καταπόνου, ταχύτατα τὴν ἀκμὴν ἀποβαλόντα. διὸ τοῦτον μὲν ὁ Ποσειδώνιός φησι θυρεόν, τὸν δὲ Μάρκελλον ξίφος ὑπὸ τῶν Ῥωμαίων καλεῖσθαι, κιρναμένην δὲ τὴν Φαβίου βεβαιότητα καὶ ἀσφάλειαν τῇ Μαρκέλλου συνηθείᾳ γενέσθαι τοῖς Ῥωμαίοις. ὁ δ’ Ἀννίβας τῷ μὲν ὡς ῥέοντι σφόδρα ποταμῷ πολλάκις ἀπαντῶν ἐσείετο καὶ παρερρήγνυτο τὴν δύναμιν, ὑφ’ οὗ δὲ καὶ κατὰ μικρὸν ὑπορρέοντος ἀψοφητὶ καὶ παρεμπίπτοντος ἐνδελεχῶς ὑπερειπόμενος καὶ δαπανώμενος ἐλάνθανε· καὶ τελευτῶν εἰς ἀπορίαν κατέστη τοσαύτην ὥστε Μαρκέλλῳ μὲν ἀποκαμεῖν μαχόμενον, Φάβιον δὲ φοβεῖσθαι μὴ μαχόμενον.", "st": "Fab. 19.1"}, {"sp": "N", "t": "τὸ γὰρ πλεῖστον, ὡς εἰπεῖν, τοῦ χρόνου τούτοις διεπολέμησεν ἢ στρατηγοῖς ἢ ἀνθυπάτοις ἢ ὑπάτοις ἀποδεδειγμένοις· ἑκάτερος γὰρ αὐτῶν πεντάκις ὑπάτευσεν. ἀλλὰ Μάρκελλον μὲν ὑπατεύοντα τὸ πέμπτον ἐνέδρᾳ περιβαλὼν ἔκτεινε, Φαβίῳ δὲ πᾶσαν ἀπάτην καὶ διάπειραν ἐπάγων πολλάκις οὐδὲν ἐπέραινε, πλὴν ἅπαξ ὀλίγου παρακρουσάμενος ἔσφηλε τὸν ἄνδρα. συνθεὶς γὰρ ἐπιστολὰς παρὰ τῶν ἐν Μεταποντίῳ δυνατῶν καὶ πρώτων ἔπεμψε πρὸς τὸν Φάβιον, ὡς τῆς πόλεως ἐνδοθησομένης εἰ παραγένοιτο, καὶ τῶν τοῦτο πραττόντων ἐκεῖνον ἐλθεῖν καὶ φανῆναι πλησίον ἀναμενόντων. ταῦτ’ ἐκίνησε τὸν Φάβιον τὰ γράμματα, καὶ λαβὼν μέρος τι τῆς στρατιᾶς ἔμελλεν ὁρμήσειν διὰ νυκτός· εἶτα χρησάμενος ὄρνισιν οὐκ αἰσίοις ἀπετράπη, καὶ μετὰ μικρὸν ἐπεγνώσθη τὰ γράμματα πρὸς αὐτὸν ὑπ’ Ἀννίβου δόλῳ συντεθέντα κἀκεῖνος ἐνεδρεύων αὐτὸν ὑπὸ τὴν πόλιν. ἀλλὰ ταῦτα μὲν ἄν τις εὐνοίᾳ θεῶν ἀναθείη.", "st": "Fab. 19.5"}, {"sp": "N", "t": "τὰς δ’ ἀποστάσεις τῶν πόλεων καὶ τὰ κινήματα τῶν συμμάχων ὁ Φάβιος μᾶλλον ᾤετο δεῖν ἠπίως ὁμιλοῦντα καὶ πρᾴως ἀνείργειν καὶ δυσωπεῖν, μὴ πᾶσαν ὑπόνοιαν ἐλέγχοντα καὶ χαλεπὸν ὄντα παντάπασι τοῖς ὑπόπτοις. λέγεται γὰρ ὅτι στρατιώτην ἄνδρα Μάρσον, ἀνδρείᾳ καὶ γένει τῶν συμμάχων πρῶτον, αἰσθόμενος διειλεγμένον τισὶ τῶν ἐν τῷ στρατοπέδῳ περὶ ἀποστάσεως οὐ διηρέθισεν, ἀλλ’ ὁμολογήσας ἠμελῆσθαι παρ’ ἀξίαν αὐτόν, νῦν μὲν ἔφη τοὺς ἡγεμόνας αἰτιᾶσθαι πρὸς χάριν μᾶλλον ἢ πρὸς ἀρετὴν τὰς τιμὰς νέμοντας, ὕστερον δ’ ἐκεῖνον αἰτιάσεσθαι μὴ φράζοντα μηδ’ ἐντυγχάνοντα πρὸς αὑτόν, εἴ του δέοιτο. καὶ ταῦτ’ εἰπὼν ἵππον τε πολεμιστὴν ἐδωρήσατο καὶ τοῖς ἄλλοις ἀριστείοις ἐκόσμησεν, ὥστε πιστότατον ἐξ ἐκείνου καὶ προθυμότατον εἶναι τὸν ἄνδρα, δεινὸν γὰρ ἡγεῖτο τοὺς μὲν ἱππικοὺς καὶ κυνηγετικοὺς ἐπιμελείᾳ καὶ συνηθείᾳ καὶ τροφῇ μᾶλλον ἢ μάστιξι καὶ κλοιοῖς τὴν χαλεπότητα τῶν ζῴων καὶ τὸ θυμούμενον καὶ τὸ δυσκολαῖνον ἐξαιρεῖν, τὸν δ’ ἀνθρώπων ἄρχοντα μὴ τὸ πλεῖστον ἐν χάριτι καὶ πρᾳότητι τῆς ἐπανορθώσεως τίθεσθαι, σκληρότερον δὲ προσφέρεσθαι καὶ βιαιότερον ἤπερ οἱ γεωργοῦντες ἐρινεοῖς καὶ ἀχράσι καὶ κοτίνοις προσφέρονται, τὰ μὲν εἰς ἐλαίας, τὰ δ’ εἰς ἀπίους, τὰ δ’ εἰς συκᾶς ἐξημεροῦντες καὶ τιθασεύοντες.", "st": "Fab. 20.1"}, {"sp": "N", "t": "ἕτερον τοίνυν τῷ γένει Λευκανὸν ἄνδρα προσήγγειλαν οἱ λοχαγοὶ ῥεμβόμενον ἀπὸ τοῦ στρατοπέδου καὶ τὴν τάξιν ἐκλείποντα πολλάκις, ὁ δ’ ἠρώτησε, τἆλλα ποῖόν τινα τὸν ἄνθρωπον εἰδεῖεν ὄντα. μαρτυρούντων δὲ πάντων ὅτι ῥᾳδίως ἕτερος οὐκ εἴη στρατιώτης τοιοῦτος, ἅμα τ’ αὐτοῦ τινας ἀνδραγαθίας ἐπιφανεῖς καὶ πράξεις λεγόντων, αἰτίαν τῆς ἀταξίας ζητῶν εὗρεν ἔρωτι παιδίσκης κατεχόμενον τὸν ἄνδρα καὶ κινδυνεύοντα μακρὰς ὁδοὺς ἑκάστοτε φοιτῶντα πρὸς ἐκείνην ἀπὸ τοῦ στρατοπέδου. πέμψας οὖν τινας ἀγνοοῦντος αὐτοῦ καὶ συλλαβὼν τὸ γύναιον ἔκρυψεν ἐν τῇ σκηνῇ, καὶ καλέσας τὸν Λευκανὸν ἰδίᾳ πρὸς αὑτόν, οὐ λέληθας, ἔφη, παρὰ τὰ Ῥωμαίων πάτρια καὶ τοὺς νόμους ἀπονυκτερεύων τοῦ στρατοπέδου πολλάκις· ἀλλ’ οὐδὲ χρηστὸς ὢν πρότερον ἐλελήθεις. τὰ μὲν οὖν ἡμαρτημένα σοι λελύσθω τοῖς ἠνδραγαθημένοις, τὸ δὲ λοιπὸν ἐφ’ ἑτέρῳ ποιήσομαι τὴν φρουράν. θαυμάζοντος δὲ τοῦ στρατιώτου προαγαγὼν τὴν ἄνθρωπον ἐνεχείρισεν αὐτῷ καὶ εἶπεν αὕτη μὲν ἐγγυᾶταί σε μενεῖν ἐν τῷ στρατοπέδῳ μεθ’ ἡμῶν σὺ δ’ ἔργῳ δείξεις, εἰ μὴ δι’ ἄλλην τινὰ μοχθηρίαν ἀπέλειπες, ὁ δ’ ἔρως καὶ αὕτη πρόφασις ἦν λεγομένη ταῦτα μὲν περὶ τούτων ἱστοροῦσι.", "st": "Fab. 20.4"}, {"sp": "N", "t": "τὴν δὲ Ταραντίνων πόλιν ἔσχεν ἑαλωκυῖαν ἐκ προδοσίας τὸν τρόπον τοῦτον, ἐστρατεύετο παρ’ αὐτῷ νεανίας Ταραντῖνος ἔχων ἀδελφήν πιστῶς πάνυ καὶ φιλοστόργως διακειμένην πρὸς αὐτόν, ἤρα δὲ ταύτης ἀνὴρ Βρέττιος τῶν τεταγμένων ὑπ’ Ἀννίβου τὴν πόλιν φρουρεῖν ἐφ’ ἡγεμονίας, τοῦτο πράξεως ἐλπίδα τῷ Ταραντίνῳ παρέσχε, καὶ τοῦ Φαβίου συνειδότος εἰς τὴν πόλιν ἀφείθη, λόγῳ δ’ ἀποδεδράκει πρὸς τὴν ἀδελφήν εἰς Τάραντα. αἱ μὲν οὖν πρῶται τῶν ἡμερῶν ἦσαν, καὶ καθ’ ἑαυτὸν ὁ Βρέττιος ἀνεπαύετο, λανθάνειν τὸν ἀδελφὸν οἰομένης ἐκείνης, ἔπειτα λέγει πρὸς αὐτὴν ὁ νεανίας καὶ μὴν ἐκεῖ λόγος ἐφοίτα πολὺς ἀνδρί σε τῶν δυνατῶν καὶ μεγάλων συνεῖναι. τίς οὗτός ἐστιν; εἰ γὰρ εὐδόκιμός τίς, ὥς φασιν, ἀρετῇ καὶ λαμπρός, ἐλάχιστα φροντίζει γένους ὁ πάντα συμμιγνὺς πόλεμος· αἰσχρὸν δὲ μετ’ ἀνάγκης οὐδέν, ἀλλ’ εὐτυχία τίς ἐν καιρῷ τὸ δίκαιον ἀσθενὲς ἔχοντι πρᾳοτάτῳ χρήσασθαι τῷ βιαζομένῳ. ἐκ τούτου μεταπέμπεται μὲν ἡ γυνὴ τὸν Βρέττιον καὶ γνωρίζει τὸν ἀδελφὸν αὐτῷ ταχὺ δὲ συμπράττων τὴν ἐπιθυμίαν ἐκεῖνος καὶ μᾶλλον ἢ πρότερον εὔνουν καὶ χειροήθη τῷ βαρβάρῳ παρέχειν δοκῶν τὴν ἀδελφήν, ἔσχε πιστῶς, ὥστε μὴ χαλεπῶς ἐρῶντος ἀνθρώπου μισθοφόρου μεταστῆσαι διάνοιαν ἐπ’ ἐλπίσι δωρεῶν μεγάλων, ἃς ἐπηγγέλλετο παρέξειν αὐτῷ τὸν Φάβιον.", "st": "Fab. 21.1"}, {"sp": "N", "t": "ταῦτα μὲν οὖν οἱ πλεῖστοι γράφουσι περὶ τούτων· ἔνιοι δὲ τὴν ἄνθρωπον ὑφ’ ἧς ὁ Βρέττιος μετήχθη, φασὶν οὐ Ταραντίνην, ἀλλὰ Βρεττίαν τὸ γένος οὖσαν, τῷ δὲ Φαβίῳ παλλακευομένην, ὡς ᾔσθετο πολίτην καὶ γνώριμον ὄντα τὸν τῶν Βρεττίων ἄρχοντα, τῷ τε Φαβίῳ φράσαι καὶ συνελθοῦσαν εἰς λόγους ὑπὸ τὸ τεῖχος ἐκπεῖσαι καὶ κατεργάσασθαι τὸν ἄνθρωπον.", "st": "Fab. 21.4"}, {"sp": "N", "t": "πραττομένων δὲ τούτων, ὁ Φάβιος περισπάσαι τὸν Ἀννίβαν τεχνάζων ἐπέστειλε τοῖς ἐν Ῥηγίῳ στρατιώταις τὴν Βρεττίαν καταδραμεῖν καὶ Καυλωνίαν ἐξελεῖν κατὰ κράτος στρατοπεδεύσαντας, ὀκτακισχιλίους ὄντας, αὐτομόλους δὲ τοὺς πολλοὺς καὶ τῶν ἐκ Σικελίας ὑπὸ Μαρκέλλου κεκομισμένων ἀτίμων τοὺς ἀχρηστοτάτους καὶ μετ’ ἐλαχίστης τῇ πόλει λύπης καὶ βλάβης ἀπολουμένους. ἤλπιζε γὰρ τούτους προέμενος τῷ Ἀννίβᾳ καὶ δελεάσας ἀπάξειν αὐτὸν ἀπὸ τοῦ Τάραντος· ὃ καὶ συνέβαινεν. εὐθὺς γὰρ ἐκεῖ διώκων ὁ Ἀννίβας ἐρρύη μετὰ τῆς δυνάμεως, ἡμέρᾳ δ’ ἕκτῃ τοὺς Ταραντίνους τοῦ Φαβίου περιστρατοπεδεύσαντος, ὁ προδιειλεγμένος τῷ Βρεττίῳ μετὰ τῆς ἀδελφῆς νεανίσκος ἧκε νύκτωρ πρὸς αὐτόν, εἰδὼς ἀκριβῶς καὶ καθεωρακὼς τὸν τόπον ἐφ’ οὗ παραφυλάττων ὁ Βρέττιος ἔμελλεν ἐνδώσειν καὶ παρήσειν τοῖς προσβάλλουσιν. οὐ μὴν ἁπλῶς γε τῆς προδοσίας ἐξήρτησεν ὁ Φάβιος τὴν πρᾶξιν, ἀλλ’ αὐτὸς μὲν ἐκεῖσε παρελθὼν ἡσυχίαν ἦγεν, ἡ δ’ ἄλλη στρατιὰ προσέβαλλε τοῖς τείχεσιν ἔκ τε γῆς καὶ θαλάττης ἅμα, ποιοῦσα πολλὴν κραυγὴν καὶ θόρυβον, ἄχρι οὗ τῶν πλείστων Ταραντίνων ἐκεῖ βοηθούντων καὶ συμφερομένων τοῖς τειχομαχοῦσιν ἐσήμηνε τῷ Φαβίῳ τὸν καιρὸν ὁ Βρέττιος, καὶ διὰ κλιμάκων ἀναβὰς ἐκράτησε τῆς πόλεως.", "st": "Fab. 22.1"}, {"sp": "N", "t": "ἐνταῦθα μέντοι δοκεῖ φιλοτιμίας ἥττων γενέσθαι· τοὺς γὰρ Βρεττίους πρώτους ἀποσφάττειν ἐκέλευσεν, ὡς μὴ προδοσίᾳ τὴν πόλιν ἔχων φανερὸς γένοιτο, καὶ ταύτης τε διήμαρτε τῆς δόξης καὶ διαβολὴν ἀπιστίας προσέλαβε καὶ ὠμότητος. ἀπέθανον δὲ πολλοὶ καὶ τῶν Ταραντίνων· οἱ δὲ πραθέντες ἐγένοντο τρισμύριοι, καὶ τὴν πόλιν ἡ στρατιὰ διήρπασεν ἀνηνέχθη δ’ εἰς τὸ δημόσιον τρισχίλια τάλαντα. πάντων δὲ τῶν ἄλλων ἀγομένων καὶ φερομένων λέγεται τὸν γραμματέα πυθέσθαι τοῦ Φαβίου περὶ τῶν θεῶν τί κελεύει, τὰς γραφὰς οὕτω προσαγορεύσαντα καὶ τοὺς ἀνδριάντας· τὸν οὖν Φάβιον εἰπεῖν ἀπολείπωμεν τοὺς θεοὺς Ταραντίνοις κεχολωμένους. οὐ μὴν ἀλλὰ τὸν κολοσσὸν τοῦ Ἡρακλέους μετακομίσας ἐκ Τάραντος ἔστησεν ἐν Καπιτωλίῳ, καὶ πλησίον ἔφιππον εἰκόνα χαλκῆν ἑαυτοῦ, πολὺ Μαρκέλλου φανεὶς ἀτοπώτερος περὶ ταῦτα, μᾶλλον δ’ ὅλως ἐκεῖνον ἄνδρα πρᾳότητι καὶ φιλανθρωπίᾳ θαυμαστὸν ἀποδείξας, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται.", "st": "Fab. 22.4"}, {"sp": "N", "t": "Ἀννίβαν δὲ λέγεται διώκοντα τεσσαράκοντα μόνοις ἀπολειφθῆναι σταδίοις, καί φανερῶς μὲν εἰπεῖν ἦν ἄρα καί Ῥωμαίοις Ἀννίβας τις ἕτερος· ἀπεβάλομεν γὰρ τὴν Ταραντίνων πόλιν ὥσπερ ἐλάβομεν, ἰδίᾳ δὲ τότε πρῶτον αὐτῷ παραστῆναι πρὸς τοὺς φίλους εἰπεῖν, ὡς πάλαι μὲν ἑώρα χαλεπὸν αὐτοῖς, νῦν δ’ ἀδύνατον κρατεῖν ἀπὸ τῶν ὑπαρχόντων Ἰταλίας. τοῦτον δεύτερον θρίαμβον ἐθριάμβευσε λαμπρότερον τοῦ προτέρου Φάβιος, ὥσπερ ἀθλητὴς ἀγαθὸς ἐπαγωνιζόμενος τῷ Ἀννίβᾳ καί ῥᾳδίως ἀπολυόμενος αὐτοῦ τὰς πράξεις, ὥσπερ ἅμματα καί λαβὰς οὐκέτι τὸν αὐτὸν ἐχούσας τόνον. ἡ μὲν γὰρ ἀνεῖτο τῆς δυνάμεως αὐτῷ διὰ τρυφὴν καί πλοῦτον, ἡ δ’ ὥσπερ ἐξήμβλυντο καί κατατέτριπτο τοῖς ἀλωφήτοις ἀγῶσιν.", "st": "Fab. 23.1"}, {"sp": "N", "t": "ἦν δὲ Μᾶρκος Λίβιος, οὗ τὸν Τάραντα φρουροῦντος ὁ Ἀννίβας ἀπέστησεν ὅμως δὲ τὴν ἄκραν κατέχων οὐκ ἐξεκρούσθη, καί διεφύλαξεν ἄχρι τοῦ πάλιν ὑπὸ Ῥωμαίοις γενέσθαι τοὺς Ταραντίνους. τοῦτον ἠνία Φάβιος τιμώμενος, καί ποτε πρὸς τὴν σύγκλητον ὑπὸ φθόνου καί φιλοτιμίας ἐξενεχθεὶς εἶπεν ὡς οὐ Φάβιος, ἀλλ’ αὐτὸς αἴτιος γένοιτο τοῦ τὴν Ταραντίνων ἁλῶναι. γελάσας οὖν ὁ Φάβιος, ἀληθῆ λέγεις, εἶπεν, εἰ μὴ γὰρ σὺ τὴν πόλιν ἀπέβαλες, οὐκ ἂν ἐγὼ παρέλαβον.", "st": "Fab. 23.3"}, {"sp": "N", "t": "οἱ δὲ Ῥωμαῖοι τά τ’ ἄλλα τῷ Φαβίῳ προσεφέροντο λαμπρῶς, καὶ τὸν υἱὸν αὐτοῦ Φάβιον ἀνέδειξαν ὕπατον. παραλαβόντος δὲ τὴν ἀρχὴν αὐτοῦ καὶ διοικοῦντός τι τῶν πρὸς τὸν πόλεμον ὁ πατὴρ, εἴτε διὰ γῆρας καὶ ἀσθένειαν εἴτε διαπειρώμενος τοῦ παιδός, ἀναβὰς ἐφ’ ἵππον προσῄει διὰ τῶν ἐντυγχανόντων καὶ περιεστώτων. ὁ δὲ νεανίας κατιδὼν πόρρωθεν οὐκ ἠνέσχετο, πέμψας δ’ ὑπηρέτην ἐκέλευσε καταβῆναι τὸν πατέρα καὶ δι’ αὑτοῦ προσελθεῖν, εἰ δή τι τυγχάνει τῆς ἀρχῆς δεόμενος. καὶ τοὺς μὲν ἄλλους ἠνίασε τὸ ἐπίταγμα, καὶ σιωπῇ πρὸς τὸν Φάβιον ὡς ἀνάξια πάσχοντα τῆς δόξης ἀπέβλεψαν αὐτὸς δ’ ἐκεῖνος ἀποπηδήσας κατὰ τάχος, θᾶττον ἢ βάδην πρὸς τὸν υἱὸν ἐπειχθεὶς, καὶ περιβαλὼν καὶ ἀσπασάμενος, εὖ γε, εἶπεν, ὦ παῖ, φρονεῖς καὶ πράττεις, αἰσθόμενος τίνων ἄρχεις καὶ πηλίκης μέγεθος ἀνείληφας ἀρχῆς, οὕτω καὶ ἡμεῖς καὶ οἱ πρόγονοι τὴν Ῥώμην ηὐξήσαμεν, ἐν δευτέρῳ καὶ γονεῖς καὶ παῖδας ἀεὶ τῶν τῆς πατρίδος καλῶν τιθέμενοι.", "st": "Fab. 24.1"}, {"sp": "N", "t": "λέγεται δ’ ὡς ἀληθῶς τοῦ Φαβίου τὸν πρόπαππον ἐν δόξῃ καὶ δυνάμει μεγίστῃ Ῥωμαίων γενόμενον πεντάκις μὲν αὑτὸν ὑπατεῦσαι καὶ θριάμβους ἐκ πολέμων μεγίστων ἐπιφανεστάτους καταγαγεῖν, ὑπατεύοντι δ’ υἱῷ πρεσβευτὴν συνεξελθεῖν ἐπὶ τὸν πόλεμον, ἐν δὲ τῷ θριάμβῳ τὸν μὲν εἰσελαύνειν ἐπὶ τεθρίππῳ, τὸν δ’ ἵππον ἔχοντα μετὰ τῶν ἄλλων ἐπακολουθεῖν, ἀγαλλόμενον ὅτι τοῦ μὲν υἱοῦ κύριος, τῶν δὲ πολιτῶν μέγιστος καὶ ὢν καὶ προσαγορευόμενος, ὕστερον αὑτὸν τοῦ νόμου καὶ τοῦ ἄρχοντος τίθησιν. ἀλλὰ γὰρ ἐκεῖνος οὐκ ἀπὸ τούτων μόνον θαυμαστὸς ἦν.", "st": "Fab. 24.3"}, {"sp": "N", "t": "τοῦ δὲ Φαβίου τὸν υ ἱὸν ἀποθανεῖν συνέβη· καὶ τὴν μὲν συμφορὰν ὡς ἀνήρ τε φρόνιμος καὶ πατὴρ χρηστὸς ἤνεγκε μετριώτατα, τὸ δ’ ἐγκώμιον, ὃ ταῖς ἐκκομιδαῖς τῶν ἐπιφανῶν οἱ προσήκοντες ἐπιτελοῦσιν, αὐτὸς εἶπε καταστὰς ἐν ἀγορᾷ, καὶ γράψας τὸν λόγον ἐξέδωκεν.", "st": "Fab. 24.4"}, {"sp": "N", "t": "ἐπεὶ δὲ Σκηπίων Κορνήλιος εἰς Ἰβηρίαν πεμφθεὶς Καρχηδονίους μὲν ἐξήλασε μάχαις πολλαῖς κρατήσας, ἔθνη δὲ πάμπολλα καὶ πόλεις μεγάλας καὶ πράγματα λαμπρὰ Ῥωμαίοις κτησάμενος εὔνοιαν εἶχε καὶ δόξαν ἐπανελθὼν ὅσην ἄλλος οὐδείς, ὕπατος δὲ κατασταθεὶς καὶ τὸν δῆμον αἰσθόμενος μεγάλην ἀπαιτοῦντα καὶ προσδεχόμενον πρᾶξιν αὐτοῦ, τὸ μὲν αὐτόθι συμπλέκεσθαι πρὸς Ἀννίβαν ἀρχαῖον ἡγεῖτο λίαν καὶ πρεσβυτικόν, αὐτὴν δὲ Καρχηδόνα καὶ Λιβύην εὐθὺς ἐμπλήσας ὅπλων καὶ στρατευμάτων διενοεῖτο πορθεῖν καὶ τὸν πόλεμον ἐκ τῆς Ἰταλίας ἐκεῖ μεθιστάναι, καὶ πρὸς τοῦτο παντὶ τῷ θυμῷ συνεξώρμα τὸν δῆμον, ἐνταῦθα δὴ Φάβιος ἐπὶ πᾶν δέους ἄγων τὴν πόλιν, ὡς ὑπ’ ἀνδρὸς ἀνοήτου καὶ νέου φερομένην εἰς τὸν ἔσχατον καὶ μέγιστον κίνδυνον, οὔτε λόγου φειδόμενος οὔτ’ ἔργου δοκοῦντος ἀποτρέψειν τοὺς πολίτας τὴν μὲν βουλὴν ἔπεισε, τῷ δὲ δήμῳ διὰ φθόνον ἐδόκει τοῦ Σκηπίωνος εὐημεροῦντος ἐπιλαμβάνεσθαι καὶ δεδιέναι, μή τι μέγα καὶ λαμπρὸν ἐξεργασαμένου καὶ τὸν πόλεμον ἢ παντάπασιν ἀνελόντος ἢ τῆς Ἰταλίας ἐκβαλόντος αὐτὸς ἀργὸς φανῇ καὶ μαλακός ἐν τοσούτῳ χρόνῳ μὴ διαπεπολεμηκώς.", "st": "Fab. 25.1"}, {"sp": "N", "t": "ἔοικε δ’ ὁρμῆσαι μὲν ἐξ ἀρχῆς ὁ Φάβιος πρὸς τὸ ἀντιλέγειν ὑπὸ πολλῆς ἀσφαλείας καὶ προνοίας, μέγαν ὄντα δεδιὼς τὸν κίνδυνον, ἐντεῖναι δέ πως μᾶλλον ἑαυτὸν καὶ πορρωτέρω προαχθῆναι φιλοτιμίᾳ τινὶ καὶ φιλονεικίᾳ, κωλύων τοῦ Σκηπίωνος τὴν αὔξησιν, ὅς γε καὶ Κράσσον ἔπειθε, τὸν συνυπατεύοντα τῷ Σκηπίωνι, μὴ παρεῖναι τὴν στρατηγίαν μηδ’ ὑπείκειν, ἀλλ’ αὐτὸν, εἰ δόξειεν, ἐπὶ Καρχηδονίους περαιοῦσθαι, καὶ χρήματα δοθῆναι πρὸς τὸν πόλεμον οὐκ εἴασε. χρήματα μὲν οὖν Σκηπίων ἑαυτῷ πορίζειν ἀναγκαζόμενος ἤγειρε παρὰ τῶν ἐν Τυρρηνίᾳ πόλεων ἰδίᾳ πρὸς αὐτὸν οἰκείως διακειμένων καὶ χαριζομένων Κράσσον δὲ τὰ μὲν ἡ φύσις οὐκ ὄντα φιλόνεικον, ἀλλὰ πρᾷον, οἴκοι κατεῖχε, τὰ δὲ καὶ νόμος θεῖος ἱερωσύνην ἔχοντα τὴν μεγίστην.", "st": "Fab. 25.4"}, {"sp": "N", "t": "αὖθις οὖν καθ’ ἑτέραν ὁδὸν ἀπαντῶν ὁ Φάβιος τῷ Σκηπίωνι κατεκώλυε τοὺς ὁρμωμένους αὐτῷ συστρατεύεσθαι τῶν νέων καὶ κατεῖχεν, ἔν τε ταῖς βουλαῖς καὶ ταῖς ἐκκλησίαις βοῶν ὡς οὐκ αὐτὸς Ἀννίβαν ἀποδιδράσκοι μόνος ὁ Σκηπίων, ἀλλὰ καὶ τὴν ὑπόλοιπον ἐκπλέοι λαβὼν δύναμιν ἐκ τῆς Ἰταλίας, δημαγωγῶν ἐλπίσι τοὺς νέους καὶ ἀναπείθων ἀπολιπεῖν γονέας καὶ γυναῖκας καὶ πόλιν, ἧς ἐν θύραις ἐπικρατῶν καὶ ἀήττητος ὁ πολέμιος κάθηται. καὶ μέντοι ταῦτα λέγων ἐφόβησε τοὺς Ῥωμαίους, καὶ μόνοις αὐτὸν ἐψηφίσαντο χρῆσθαι τοῖς ἐν Σικελίᾳ, στρατεύμασι καὶ τῶν ἐν Ἰβηρίᾳ γεγονότων μετ’ αὐτοῦ τριακοσίους ἄγειν, οἷς ἐχρῆτο πιστοῖς. ταῦτα μὲν οὖν ἐδόκει πολιτεύεσθαι πρὸς τὴν ἑαυτοῦ φύσιν ὁ Φάβιος.", "st": "Fab. 26.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Σκηπίωνος εἰς Λιβύην διαβάντος εὐθὺς ἔργα θαυμαστὰ καὶ πράξεις ὑπερήφανοι τὸ μέγεθος καὶ τὸ κάλλος εἰς Ῥώμην ἀπηγγέλλοντο, καὶ μαρτυροῦντα ταῖς φήμαις εἵπετο λάφυρα πολλὰ, καὶ βασιλεὺς ὁ Νομάδων αἰχμάλωτος, καὶ δύο στρατοπέδων ὑφ’ ἕνα καιρὸν ἐμπρήσεις καὶ φθορά πολλῶν μὲν ἀνθρώπων, πολλῶν δ’ ὅπλων καὶ ἵππων ἐν αὐτοῖς συγκατακεκαυμένων, καὶ πρεσβεῖαι πρὸς Ἀννίβαν ἐπέμποντο παρὰ Καρχηδονίων καλούντων καὶ δεομένων ἐάσαντα τὰς ἀτελεῖς ἐκείνας ἐλπίδας οἴκαδε βοηθεῖν, ἐν δὲ Ῥώμῃ πάντων ἐχόντων τὸν Σκηπίωνα διὰ στόματος ἐπὶ τοῖς κατορθώμασι, Φάβιος ἠξίου πέμπεσθαι Σκηπίωνι διάδοχον, ἄλλην μὲν οὐκ ἔχων πρόφασιν, εἰπὼν δὲ τὸ μνημονευόμενον, ὡς ἐπισφαλές ἐστι πιστεύειν ἀνδρὸς ἑνὸς τύχῃ τηλικαῦτα πράγματα, χαλεπὸν γὰρ ἀεὶ εὐτυχεῖν τὸν αὐτόν, οὕτω προσέκρουσεν ἤδη πολλοῖς, ὡς δύσκολος ἀνὴρ καὶ βάσκανος ἢ πάμπαν ὑπὸ γήρως ἄτολμος γεγονὼς καὶ δύσελπις, περαιτέρω τε τοῦ μετρίου κατατεθαμβημένος τὸν Ἀννίβαν. οὐδὲ γὰρ ἐκπλεύσαντος αὐτοῦ μετὰ τῶν δυνάμεων ἐξ Ἰταλίας εἴασε τὸ χαῖρον καὶ τεθαρρηκὸς τῶν πολιτῶν ἀθόρυβον καὶ βέβαιον, ἀλλὰ τότε δὴ μάλιστα τὰ πράγματα τῇ πόλει θεούσῃ παρὰ τὸν ἔσχατον κίνδυνον ἐπισφαλῶς ἔχειν ἔλεγε βαρύτερον γὰρ ἐν Λιβύῃ πρὸ Καρχηδόνος αὐτοῖς Ἀννίβαν ἐμπεσεῖσθαι, καὶ στρατὸν ἀπαντήσειν Σκηπίωνι πολλῶν ἔτι θερμὸν αὐτοκρατόρων αἵματι καὶ δικτατόρων καὶ ὑπάτων· ὥστε τὴν πόλιν αὖθις ὑπὸ τῶν λόγων τούτων ἀναταράττεσθαι, καὶ τοῦ πολέμου μεθεστῶτος εἰς Λιβύην ἐγγυτέρω τῆς Ῥώμης οἴεσθαι γεγονέναι τὸν φόβον.", "st": "Fab. 26.3"}, {"sp": "N", "t": "ἀλλὰ Σκηπίων μὲν οὐ μετὰ πολὺν χρόνον αὐτόν τε νικήσας μάχῃ κατὰ κράτος Ἀννίβαν καὶ καταβαλὼν τὸ φρόνημα καὶ καταπατήσας τῆς Καρχηδόνος ὑποπεσούσης, ἀπέδωκε μείζονα χαρὰν ἁπάσης ἐλπίδος τοῖς πολίταις, καὶ τὴν ἡγεμονίαν ὡς ἀληθῶς πολλῷ σάλῳ σεισθεῖσαν ὤρθωσε πάλιν· Φάβιος δὲ Μάξιμος οὐ διήρκεσε τῷ βίῳ πρὸς τὸ τοῦ πολέμου τέλος, οὐδ’ ἤκουσεν Ἀννίβαν ἡττημένον, οὐδὲ τὴν μεγάλην καὶ βέβαιον εὐτυχίαν τῆς πατρίδος ἐπεῖδεν, ἀλλὰ περὶ ὃν χρόνον Ἀννίβας ἀπῆρεν ἐξ Ἰταλίας νόσῳ καμὼν ἐτελεύτησεν. Ἐπαμεινώνδαν μὲν οὖν Θηβαῖοι δημοσίᾳ διὰ πενίαν, ἣν ἀπέλιπεν ὁ ἀνὴρ, ἔθαψαν οὐδὲν γὰρ οἴκοι τελευτήσαντος εὑρεθῆναι πλὴν ὀβελίσκον σιδηροῦν λέγουσι· Φάβιον δὲ Ῥωμαῖοι δημοσίᾳ μὲν οὐκ ἐκήδευσαν, ἰδίᾳ ὁ ἑκάστου τὸ σμικρότατον αὐτῷ τῶν νομισμάτων ἐπενεγκόντος, οὐχ ὡς δι’ ἔνδειαν προσαρκούντων, ἀλλ’ ὡς πατέρα τοῦ δήμου θάπτοντος, ἔσχε τιμὴν καὶ δόξαν ὁ θάνατος αὐτοῦ τῷ βίῳ πρέπουσαν.", "st": "Fab. 27.1"}, {"sp": "HDR", "t": "Περικλέους καὶ Φαβίου σύγκρισις."}, {"sp": "N", "t": "οἱ μὲν οὖν βίοι τῶν ἀνδρῶν τοιαύτην ἔχουσιν ἱστορίαν. ἐπεὶ δὲ καὶ πολιτικῆς καὶ πολεμικῆς ἀρετῆς πολλὰ καὶ καλὰ παραδείγματα καταλελοίπασιν ἀμφότεροι, φέρε τῶν πολεμικῶν ἐκεῖνο πρῶτον λάβωμεν, ὅτι Περικλῆς μὲν ἄριστα πράττοντι τῷ δήμῳ καὶ μεγίστῳ καθ’ αὑτὸν ὄντι καὶ μάλιστα πρὸς δύναμιν ἀκμάζοντι χρώμενος ὑπὸ κοινῆς ἂν δόξειεν εὐτυχίας καὶ ῥώμης πραγμάτων ἀσφαλὴς διαγενέσθαι καὶ ἄπταιστος, αἱ δὲ Φαβίου πράξεις ἐν αἰσχίστοις καὶ δυσποτμοτάτοις καιροῖς ἀναδεξαμένου τὴν πόλιν, οὐκ ἐπ’ ἀγαθοῖς ἀσφαλῆ διετήρησαν, ἀλλ’ ἐκ κακῶν εἰς βελτίω μετέστησαν. καὶ Περικλεῖ μὲν αἱ Κίμωνος εὐπραξίαι καὶ τὰ Μυρωνίδου καὶ τὰ Λεωκράτους τρόπαια καὶ πολλὰ καὶ μεγάλα Τολμίδης κατορθῶν ἐνεορτάσαι μᾶλλον καὶ ἐμπανηγυρίσαι στρατηγοῦντι τὴν πόλιν ἢ κτήσασθαι πολέμῳ καὶ φυλάξαι παρέδωκαν· Φάβιος δ’ ὁρῶν πολλὰς μὲν φυγὰς καὶ ἥττας, πολλοὺς δὲ θανάτους καὶ σφαγὰς αὐτοκρατόρων καὶ στρατηγῶν, λίμνας δὲ καὶ πεδία καὶ δρυμοὺς νεκρῶν στρατοπέδων πλήθοντας, αἵματι δὲ καὶ φόνῳ ποταμοὺς ἄχρι θαλάττης ῥέοντας, ἐν τῷ καθ’ ἑαυτὸν ὁρμωμένῳ καὶ βεβηκότι τὴν πόλιν ἀντιλαμβανόμενος καὶ ὑπερείδων, οὐκ εἴασε τοῖς ἐκείνων ὑποφερομένην πταίσμασι τελέως ἐκχυθῆναι. καίτοι δόξειεν ἂν οὐχ οὕτω χαλεπὸν εἶναι πόλιν ἐν συμφοραῖς μεταχειρίσασθαι ταπεινὴν καὶ τοῦ φρονοῦντος ὑπ’ ἀνάγκης κατήκοον γενομένην, ὡς δι’ εὐτυχίαν ἐπηρμένῳ καὶ σπαργῶντι τῷ δήμῳ χαλινὸν ἐμβαλεῖν ὕβρεως καὶ θρασύτητος· ᾧ δὴ μάλιστα φαίνεται τρόπῳ Περικλῆς Ἀθηναίων περιγενόμενος. ἀλλὰ τῶν Ῥωμαίοις συμπεσόντων τότε κακῶν τὸ μέγεθος καὶ τὸ πλῆθος ἰσχυρόν τινα τὴν γνώμην καὶ μέγαν ἔδειξεν ἄνδρα τὸν μὴ συγχυθέντα μηδὲ προέμενον τοὺς αὑτοῦ λογισμούς.", "st": "Comp. Per.–Fab. 1.1"}, {"sp": "N", "t": "καὶ Σάμῳ μὲν ὑπὸ Περικλέους ἁλούσῃ τὴν Τάραντος ἔστι κατάληψιν ἀντιθεῖναι, καὶ νὴ Δί’ Εὐβοίᾳ τὰς περὶ Καμπανίαν πόλεις· ἐπεὶ αὐτήν γε Καπύην οἱ περὶ Φούλβιον καὶ Ἄππιον ὕπατοι κατέσχον. ἐκ δὲ παρατάξεως Φάβιος οὐ φαίνεται μάχῃ νενικηκώς πλὴν ἀφ’ ἧς τὸν πρότερον εἰσήλασε θρίαμβον, Περικλῆς δ’ ἐννέα τρόπαια κατὰ γῆν καὶ κατὰ θάλατταν ἔστησεν ἀπὸ τῶν πολεμίων. οὐ μὴν λέγεται τοιαύτη πρᾶξις Περικλέους, οἵαν ἔπραξε Φάβιος Μινούκιον ἐξαρπάσας Ἀννίβου καὶ διασώσας ἐντελὲς στρατόπεδον Ῥωμαίων· καλὸν γὰρ τὸ ἔργον καὶ κοινὸν ἀνδρείας ὁμοῦ καὶ φρονήσεως καὶ χρηστότητος· ὥσπερ αὖ πάλιν οὐδὲ σφάλμα λέγεται Περικλέους οἷον ἐσφάλη Φάβιος διὰ τῶν βοῶν καταστρατηγηθεὶς ὑπ’ Ἀννίβου, λαβὼν μὲν αὐτομάτως καὶ κατὰ τύχην ὑπελθόντα τοῖς στενοῖς τὸν πολέμιον, προέμενος δὲ νυκτὸς λαθόντα καὶ μεθ’ ἡμέραν βιασάμενον καὶ φθάσαντα μέλλοντος καὶ κρατήσαντα συλλαβόντος. εἰ δὲ δεῖ μὴ μόνον χρῆσθαι τοῖς παροῦσιν, ἀλλὰ καὶ τεκμαίρεσθαι περὶ τοῦ μέλλοντος ὀρθῶς τὸν ἀγαθὸν στρατηγόν, Ἀθηναίοις μὲν ὡς Περικλῆς προέγνω καὶ προεῖπεν ἐτελεύτησεν ὁ πόλεμος· πολυπραγμονοῦντες γὰρ ἀπώλεσαν τὴν δύναμιν Ῥωμαῖοι δὲ παρὰ τοὺς Φαβίου λογισμοὺς ἐκπέμψαντες ἐπὶ Καρχηδονίους Σκηπίωνα πάντων ἐκράτησαν, οὐ τύχῃ, σοφίᾳ δὲ τοῦ στρατηγοῦ καὶ ἀνδρείᾳ κατὰ κράτος νικήσαντος τοὺς πολεμίους. ὥστε τῷ μὲν τὰ πταίσματα τῆς πατρίδος μαρτυρεῖν ὅτι καλῶς ἔγνω, τὸν δὲ ὑπὸ τῶν κατορθωμάτων ἐλέγχεσθαι τοῦ παντὸς ἐσφαλμένον. ἴση δ’ ἁμαρτία στρατηγοῦ κακῷ περιπεσεῖν μὴ προσδοκήσαντα καὶ κατορθώματος καιρὸν ἀπιστίᾳ προέσθαι. μία γὰρ, ὡς ἔοικεν, ἀπειρία καὶ θράσος γεννᾷ καὶ θάρσος ἀφαιρεῖται, ταῦτα περὶ τῶν πολεμικῶν.", "st": "Comp. Per.–Fab. 2.1"}, {"sp": "N", "t": "τῆς δὲ πολιτείας μέγα μὲν ἔγκλημα τοῦ Περικλέους ὁ πόλεμος, λέγεται γὰρ ἐπακτὸς ὑπ’ ἐκείνου γενέσθαι Λακεδαιμονίοις ἐρίσαντος μὴ ἐνδοῦναι. δοκῶ δὲ μηδ’ ἂν Φάβιον Μάξιμον ἐνδοῦναί τι Καρχηδονίοις, ἀλλ’ εὐγενῶς ὑποστῆναι τὸν ὑπὲρ τῆς ἡγεμονίας κίνδυνον. ἡ μέντοι πρὸς Μινούκιον ἐπιείκεια τοῦ Φαβίου καὶ πρᾳότης ἐλέγχει τὸν πρὸς Κίμωνα καὶ Θουκυδίδην στασιασμόν, ἄνδρας ἀγαθοὺς καὶ ἀριστοκρατικοὺς εἰς φυγὴν ὑπ’ αὐτοῦ καὶ τοὔστρακον ἐκπεσόντας. ἀλλ’ ἥ γε δύναμις μείζων ἡ τοῦ Περικλέους καὶ τὸ κράτος, ὅθεν οὐδ’ ἄλλον εἴασεν ἐνδυστυχῆσαι τῇ πόλει κακῶς βουλευσάμενον στρατηγόν, ἀλλ’ ἢ μόνος αὐτὸν ἐκφυγὼν Τολμίδης καὶ διωσάμενος βίᾳ προσέπταισε Βοιωτοῖς οἱ δ’ ἄλλοι προσετίθεντο καὶ κατεκοσμοῦντο πάντες εἰς τήν ἐκείνου γνώμην ὑπὸ μεγέθους αὐτοῦ τῆς δυνάμεως. Φάβιος δὲ τὸ καθ’ αὐτὸν ἀσφαλὴς ὢν καὶ ἀναμάρτητος τῷ πρὸς τὸ κωλύειν ἑτέρους ἀδυνάτῳ φαίνεται λειπόμενος. οὐ γὰρ ἂν τοσαύταις συμφοραῖς ἐχρήσαντο Ῥωμαῖοι Φαβίου παρ’ αὐτοῖς ὅσον Ἀθήνησι Περικλέους δυνηθέντος.", "st": "Comp. Per.–Fab. 3.1"}, {"sp": "N", "t": "καὶ μὴν τήν γε πρὸς χρήματα μεγαλοφροσύνην ὁ μὲν τῷ μηδὲν λαβεῖν παρὰ τῶν διδόντων, ὁ δὲ τῷ προέσθαι πολλὰ τοῖς δεομένοις ἐπεδείξατο, λυσάμενος τοῖς ἰδίοις χρήμασι τοὺς αἰχμαλώτους. πλὴν τούτων μὲν οὐ πολὺς ἦν ἀριθμός, ἀλλ’ ὅσον ἓξ τάλαντα· Περικλῆς δ’ οὐκ ἂν ἴσως εἴποι τις ὅσα καὶ παρὰ συμμάχων καὶ βασιλέων ὠφελεῖσθαι καὶ θεραπεύεσθαι παρόν, τῆς δυνάμεως διδούσης, ἀδωρότατον ἑαυτὸν καὶ καθαρώτατον ἐφύλαξεν.", "st": "Comp. Per.–Fab. 3.4"}, {"sp": "N", "t": "ἔργων γε μὴν μεγέθεσι καὶ ναῶν καὶ κατασκευαῖς οἰκοδομημάτων, ἐξ ὧν ἐκόσμησεν ὁ Περικλῆς τὰς Ἀθήνας, οὐκ ἄξιον ὁμοῦ πάντα τὰ πρὸ τῶν Καισάρων φιλοτιμήματα τῆς Ῥώμης παραβαλεῖν, ἀλλ’ ἔξοχόν τι πρὸς ἐκεῖνα καὶ ἀσύγκριτον ἡ τούτων ἔσχε μεγαλουργία καὶ μεγαλοπρέπεια τὸ πρωτεῖον.", "st": "Comp. Per.–Fab. 3.5"}], []);})();
